local PS = game:GetService("Players")
local RS = game:GetService("RunService")
local HS = game:GetService("HttpService")
local DB = game:GetService("Debris")
-- V4.3.531 hotfix #3: hoisted from RoClothes() L7585-7588 to file scope. These are
-- pure service refs with no per-execute state; closures inside RoClothes capture
-- them as upvalues from file scope identically to before. Reclaims 4 permanent
-- RoClothes-scope register slots at peak - addresses the 200-cap pressure that
-- was busting iterator/transient allocations at L27707 (`td`), L28303 (`tabBtn`),
-- L30045 (`s`).
local UIS = game:GetService("UserInputService")
local TS = game:GetService("TweenService")
local MPS = game:GetService("MarketplaceService")
-- V4.3.375: MaterialService is blocked on some executors; pcall-guard so script
-- load doesn't abort. Downstream readers must nil-check MS before use.
local MS = nil
pcall(function() MS = game:GetService("MaterialService") end)

-- VERSION - single source of truth. Copy to a new versioned .lua file, then bump
-- these two locals in the copy. Preserve prior releases unchanged.
-- (Header comment at L5 must also be updated manually - Lua can't compute comments.)
local _RC_VER      = "V4.5.31.1008"  -- form: V<major>.<minor>.<patch>.<MMDD>
local _RC_VER_DATE = "2026-10-08"     -- ISO date YYYY-MM-DD

-- ── V4.3.506: Telemetry Phase 1 (local ring buffer + diag helper) ────────────
-- Default-OFF anywhere it touches the network - Phase 1 is local-only, writes
-- to RClothesLerp/diagnostics.log every 60s. Phase 3 (V4.3.507+) will add the
-- opt-in network uploader. See docs/telemetry-implementation-prompt.md.
--
-- The ring buffer holds 256 events (oldest evicted). `Function.diag(ev, p)`
-- and `Function.diagOnce(api)` are the only entry points. Both are no-throw:
-- malformed payloads silently drop, missing executor APIs degrade gracefully.
--
-- File-scope on purpose: the ~30 wire sites (§5 of the brief) live deep inside
-- the giant RoClothes() function which is at the 200-local-register ceiling.
-- Helpers here cost zero outer-scope registers in RoClothes.
local _DIAG_RING = {}
local _DIAG_RING_CAP = 256
local _DIAG_RING_HEAD = 1
local _DIAG_RING_COUNT = 0
local _DIAG_LAST_FLUSH = 0
local _DIAG_FLUSH_INTERVAL = 60            -- seconds
local _DIAG_FILE = "RClothesLerp/diagnostics.log"
local _DIAG_FILE_OLD = "RClothesLerp/diagnostics.log.old"
local _DIAG_FILE_ROTATE_BYTES = 1024 * 1024  -- 1 MB
local _DIAG_INSTALL_ID = nil               -- populated by Phase 3
-- V4.3.513 Fix 10: heal-once flag for the lazy-getter fast-paths. Pre-fix every
-- uploader cycle (~5 min) re-spawned a persist task even though the disk was
-- already correct, racking up redundant atomic-write attempts forever. Set true
-- after a successful _atomicWriteJSON; cleared on opt-out so re-opt-in re-heals.
local _DIAG_INSTALL_ID_DISK_VERIFIED = false
local _DIAG_FIRED_ONCE = {}                -- exec.missing_api de-dup table
local _DIAG_EXE = nil                      -- lazy-cached identifyexecutor() result
local _DIAG_PLAT = nil                     -- lazy-cached platform

local function _diagResolveExe()
	if _DIAG_EXE ~= nil then return _DIAG_EXE end
	local ok, name = pcall(function() return identifyexecutor and identifyexecutor() end)
	if ok and type(name) == "string" and #name > 0 and #name < 64 then
		_DIAG_EXE = name
	else
		_DIAG_EXE = "unknown"
	end
	return _DIAG_EXE
end
local function _diagResolvePlat()
	if _DIAG_PLAT ~= nil then return _DIAG_PLAT end
	local ok, plat = pcall(function()
		local UIS = game:GetService("UserInputService")
		if UIS.TouchEnabled and not UIS.KeyboardEnabled then return "Mobile" end
		if UIS.GamepadEnabled and not UIS.KeyboardEnabled then return "Console" end
		return "Desktop"
	end)
	_DIAG_PLAT = (ok and type(plat) == "string") and plat or "unknown"
	return _DIAG_PLAT
end

local function _diagFileWrite(path, data, append)
	if type(data) ~= "string" or #data == 0 then return false end
	if append and type(appendfile) == "function" then
		local ok = pcall(appendfile, path, data)
		if ok then return true end
	end
	if type(writefile) ~= "function" then return false end
	if append and type(readfile) == "function" and type(isfile) == "function" then
		local exists = false; pcall(function() exists = isfile(path) end)
		if exists then
			local okR, prior = pcall(readfile, path)
			if okR and type(prior) == "string" then
				return select(1, pcall(writefile, path, prior .. data))
			end
		end
	end
	return select(1, pcall(writefile, path, data))
end

local function _diagFileSize(path)
	if type(getfilesize) == "function" then
		local ok, sz = pcall(getfilesize, path)
		if ok and type(sz) == "number" then return sz end
	end
	if type(readfile) == "function" and type(isfile) == "function" then
		local ok, exists = pcall(isfile, path); if not (ok and exists) then return 0 end
		local okR, body = pcall(readfile, path)
		if okR and type(body) == "string" then return #body end
	end
	return 0
end

local function _diagEnsureDir()
	if type(isfolder) == "function" and type(makefolder) == "function" then
		local ok, exists = pcall(isfolder, "RClothesLerp")
		if ok and not exists then pcall(makefolder, "RClothesLerp") end
	end
end

-- Serialize ring as line-delimited JSON (one entry per line). Wrapper fields
-- are repeated per line so a crash mid-flush still leaves a parseable tail.
-- Forward declaration: diagnostics recording above the uploader block must bind
-- the session getter, never a same-named global.
local _DIAG_UP_ENABLED_GETTER

local function _diagSerializeRing()
	if _DIAG_RING_COUNT == 0 then return "" end
	local HSr = game:GetService("HttpService")
	local lines = {}
	-- V4.3.509 Fix 3: only stamp install ID when user is opted in. Pre-fix, the
	-- iid was written to disk regardless of opt-out, breaking the "anonymous logs only"
	-- promise shown on the HUD when telemetry is disabled.
	local iid = ""
	if _DIAG_UP_ENABLED_GETTER and _DIAG_UP_ENABLED_GETTER() then
		iid = _DIAG_INSTALL_ID or ""
	end
	local exe = _diagResolveExe()
	local plat = _diagResolvePlat()
	local total = _DIAG_RING_COUNT
	for i = 1, total do
		local idx
		if _DIAG_RING_COUNT < _DIAG_RING_CAP then
			idx = i
		else
			idx = ((_DIAG_RING_HEAD + i - 2) % _DIAG_RING_CAP) + 1
		end
		local entry = _DIAG_RING[idx]
		if type(entry) == "table" then
			local wrapped = { v = entry.v or _RC_VER, iid = iid, exe = exe, plat = plat, ts = entry.ts, ev = entry.ev, p = entry.p or {} }
			local okEnc, encoded = pcall(function() return HSr:JSONEncode(wrapped) end)
			if okEnc and type(encoded) == "string" then
				lines[#lines + 1] = encoded
			end
		end
	end
	if #lines == 0 then return "" end
	return table.concat(lines, "\n") .. "\n"
end

-- V4.3.515 Fix 1 (CRITICAL): forward-declare _diagUpPush. Prior versions declared
-- it as `local function _diagUpPush(entry)` at L406, AFTER the L272/L303 callsites
-- inside _diagFlush + _diagRecord. Lua locals are lexically scoped from declaration
-- onward, so the earlier references resolved to GLOBAL _diagUpPush (nil), and
-- pcall(nil, ...) silently returned false. Net effect: the wrap-drop event survival
-- mechanism (V4.3.511 Fix 1) and the Phase 1→Phase 3 mirror in _diagRecord were
-- both no-ops since they shipped - zero telemetry made it into the upload ring
-- from these paths. Forward-declare here; convert the L406 site to assignment.
local _diagUpPush

local function _diagFlush()
	if _DIAG_RING_COUNT == 0 then return end
	_diagEnsureDir()
	-- V4.3.509 Fix 4: snapshot count BEFORE the file-I/O yields. Any _diagRecord
	-- invoked during the yield (UI signal, async pcall) appends to the tail;
	-- on success we must clear only the snapshot prefix, not new entries.
	local snapCount = _DIAG_RING_COUNT
	-- V4.3.511 Fix 2: also snapshot HEAD - HEAD only advances on full-ring
	-- eviction, so any HEAD delta after yield = eviction occurred.
	local snapHead  = _DIAG_RING_HEAD
	local payload = _diagSerializeRing()
	if #payload == 0 then return end
	-- V4.3.509 Fix 9: rotate so backup write success gates canonical delete.
	-- Pre-fix order (delfile _OLD → writefile _OLD → delfile canonical) lost
	-- ALL history if the backup write failed.
	local sz = _diagFileSize(_DIAG_FILE)
	if sz >= _DIAG_FILE_ROTATE_BYTES then
		if type(readfile) == "function" and type(writefile) == "function" then
			local okR, body = pcall(readfile, _DIAG_FILE)
			if okR and type(body) == "string" then
				if type(delfile) == "function" then pcall(delfile, _DIAG_FILE_OLD) end  -- clear prior backup slot
				local okW = pcall(writefile, _DIAG_FILE_OLD, body)
				if okW and type(delfile) == "function" then
					pcall(delfile, _DIAG_FILE)  -- only delete canonical AFTER backup succeeded
				end
				-- If backup failed, leave canonical alone (it'll overshoot the rotate
				-- threshold a bit, but history is preserved).
			end
		end
	end
	local ok = _diagFileWrite(_DIAG_FILE, payload, true)
	if ok then
		-- Capture entries added during the I/O yield (at positions snapCount+1..currentCount
		-- when ring hasn't wrapped). On wrap during yield, just drop them - rare and we'd
		-- need full ring rotation to preserve correctly.
		local newEntries
		local addedDuringYield = _DIAG_RING_COUNT - snapCount
		-- V4.3.511 Fix 2: HEAD-delta is the precise eviction signal. Pre-fix
		-- HEAD==1 check dropped entries when HEAD started >1 and never advanced,
		-- and missed single-slot eviction when HEAD wrapped exactly back to 1.
		local evictedDuringYield = (snapHead ~= _DIAG_RING_HEAD)
		if addedDuringYield > 0 and not evictedDuringYield then
			-- No eviction → new entries sit contiguously at snapCount+1..currentCount
			newEntries = {}
			for i = 1, addedDuringYield do
				newEntries[i] = _DIAG_RING[snapCount + i]
			end
		elseif addedDuringYield > 0 or evictedDuringYield then
			-- Wrap during yield: entries scattered across the ring; preserving them
			-- correctly would need full rotation. Drop with observability - push
			-- directly to the upload ring so the event survives the disk-side
			-- clear below (V4.3.511 Fix 1: prior _diagRecord call landed in
			-- _DIAG_RING then got nilled 2 lines later).
			local lostCount = math.max(addedDuringYield, 0)
			if evictedDuringYield then
				local headAdvance = (_DIAG_RING_HEAD - snapHead) % _DIAG_RING_CAP
				-- V4.3.512 Fix 9: full-cycle wrap edge. If HEAD wrapped exactly CAP times
				-- (or any multiple) and landed back on snapHead, the modulo returns 0 even
				-- though a full CAP of evictions occurred. evictedDuringYield was true
				-- (snapHead~=_DIAG_RING_HEAD captures intermediate state via the
				-- AllConnect-PreSimulation/Heartbeat snapshot? No - it compares current
				-- to snap; equal here means wrap landed back). When we got here under
				-- evictedDuringYield AND headAdvance is 0, the only consistent explanation
				-- is a full-cycle wrap: report CAP.
				if headAdvance == 0 then headAdvance = _DIAG_RING_CAP end
				lostCount = math.max(lostCount, headAdvance)
			end
			pcall(_diagUpPush, { v = _RC_VER, ts = os.time(), ev = "diag_ring.wrap_drop", p = { dropped = lostCount } })
		end
		for i = 1, _DIAG_RING_COUNT do _DIAG_RING[i] = nil end
		_DIAG_RING_COUNT = 0
		_DIAG_RING_HEAD = 1
		if newEntries then
			for _, e in ipairs(newEntries) do
				_DIAG_RING_COUNT = _DIAG_RING_COUNT + 1
				_DIAG_RING[_DIAG_RING_COUNT] = e
			end
		end
		_DIAG_LAST_FLUSH = os.clock()
	end
end

local function _diagRecord(ev, p)
	if type(ev) ~= "string" or #ev == 0 or #ev > 64 then return end
	p = (type(p) == "table") and p or {}
	local entry = { v = _RC_VER, ts = os.time(), ev = ev, p = p }
	if _DIAG_RING_COUNT < _DIAG_RING_CAP then
		_DIAG_RING_COUNT = _DIAG_RING_COUNT + 1
		_DIAG_RING[_DIAG_RING_COUNT] = entry
	else
		_DIAG_RING[_DIAG_RING_HEAD] = entry
		_DIAG_RING_HEAD = (_DIAG_RING_HEAD % _DIAG_RING_CAP) + 1
	end
	-- V4.3.507: mirror to the upload ring (Phase 3). Separate buffer because the
	-- disk-flush above clears the local ring on each 60s rotation, but uploads
	-- run every 5min - without a second ring the uploader would always be empty.
	-- Only push when telemetry is enabled - saves memory for users staying opt-out.
	if _DIAG_UP_ENABLED_GETTER and _DIAG_UP_ENABLED_GETTER() then
		pcall(_diagUpPush, entry)
	end
end
local function _diagRecordOnce(api)
	if type(api) ~= "string" then return end
	if _DIAG_FIRED_ONCE[api] then return end
	_DIAG_FIRED_ONCE[api] = true
	_diagRecord("exec.missing_api", { api = api })
end

-- Public wire-site entry points. pcall-wrapped at every call so malformed
-- payloads or transient JSON-encode failures cannot crash the hot path.
local function _diagPublicCall(ev, p) pcall(_diagRecord, ev, p) end
local function _diagPublicCallOnce(api) pcall(_diagRecordOnce, api) end

-- V4.3.530: LogService.MessageOut capture. Subscribes to Roblox's developer
-- console signal and extracts structured events from `[RoClothes] ...` warns
-- the script already emits at known failure points. Turns every existing
-- `warn("[RoClothes] X failed")` into telemetry without retrofitting
-- `_diagPublicCall` at each site.
--
-- Design choices for privacy + cost:
--   1. Allow-list by prefix `[RoClothes]`. Lines without that prefix are
--      ignored - no engine logs, no third-party script logs, no game chat.
--   2. NEVER upload the raw log line. Only pattern matches that explicitly
--      whitelist fields get emitted as structured events. If a pattern
--      pulls a Roblox username (e.g., `Weld '%s' on character '%s' failed`),
--      that pattern is excluded - the structured event omits PII fields.
--   3. Per-event-type rate cap: each extracted event type can fire at most
--      8 times in a 60s window per session. Prevents a stuck loop from
--      flooding the upload pipeline.
--   4. No-pattern lines drop silently. The point is structured diagnostics,
--      not log forwarding.
do
	local _ok_LS, _LS = pcall(function() return game:GetService("LogService") end)
	if _ok_LS and _LS and _LS.MessageOut then
		-- V4.3.531 Fix 4: prior-session cleanup. V4.3.530 shipped this subscriber without
		-- storing the RBXScriptConnection or publishing it on getgenv() for re-execute
		-- cleanup. Every re-execute added another live handler running the same pattern
		-- table against every console line; after N re-executes, N copies of the handler
		-- fired per log line, each emitting duplicate telemetry events. Matches the
		-- V4.3.514 pattern used for `_RC_diag_flush_task` at L449-461.
		do
			local _ok_g, _g = pcall(function() return (getgenv and getgenv()) or nil end)
			local _prior = _ok_g and _g and _g._RC_logsvc_msg_conn or nil
			if _prior then pcall(function() _prior:Disconnect() end) end
		end
		-- Per-event-type rate gate. _rate[evName] = {windowStart, count}.
		local _rate = {}
		local function _rateOk(evName)
			local now = os.clock()
			local r = _rate[evName]
			if not r or (now - r[1]) > 60 then
				_rate[evName] = { now, 1 }
				return true
			end
			if r[2] >= 8 then return false end
			r[2] = r[2] + 1
			return true
		end

		-- Pattern table. Each entry: { pattern, eventName, fieldNames }.
		-- Pattern is Lua-pattern (not regex). Captures map 1:1 to fieldNames.
		-- Anything captured that isn't in fieldNames is dropped. Patterns
		-- with PII captures (Roblox usernames) are NOT included here.
		local _patterns = {
			-- VNS / SmartBone rbxm loading (the main 2026-05-30 / 2026-06-02 community-report surface)
			{ "RigVnsModel: failed to load (.+)",                                 "log.vns_load_failed",         { "path" } },
			{ "RigVnsModel: (.+) loaded but contains no MeshParts",               "log.vns_no_meshparts",        { "path" } },
			{ "RigVnsModel: subModelName \"([^\"]+)\" not found in ([^ ]+)",      "log.vns_submodel_missing",    { "submodel", "path" } },
			-- V4.3.535 Opt-5: dropped the overly-broad `Type 6:` pattern that previously
			-- shadowed both `BreastsType 6:` (L394, below) and `ButtType 6:` (L400) via
			-- first-wins semantics. Real warns at L16253 (ButtType) + L16368 (BreastsType)
			-- both have specific prefixes; the broad pattern mis-categorized BreastsType
			-- emits as `log.vns_rigvns_no_parts_butt` AND prevented the specific patterns
			-- from ever firing. Removing the broad pattern restores correct classification.
			{ "BreastsType 6: RigVnsModel returned no parts",                     "log.vns_rigvns_no_parts_breast",{} },
			-- V4.3.531 Fix 5: `.` matches one byte, em-dash is 3 bytes in UTF-8 - replaced with `.-` (lazy any) so the pattern actually fires.
			{ "BreastsType 6: RigVnsModel threw .- (.+)",                         "log.vns_rigvns_threw_breast", { "err" } },
			{ "ArmType 5: RigVnsModel returned no parts",                         "log.vns_rigvns_no_parts_arm", {} },
			{ "LegsType 8: RigVnsModel returned no parts",                        "log.vns_rigvns_no_parts_leg", {} },
			{ "TorsoType 9: RigVnsModel returned no parts",                       "log.vns_rigvns_no_parts_torso",{} },
			{ "ButtType 6: RigVnsModel returned no parts",                        "log.vns_rigvns_no_parts_butt2",{} },
			{ "LoadSmartBoneApi failed:",                                         "log.vns_sb_api_load_failed",  {} },
			-- Install / manifest
			{ "Content auto%-installer disabled",                                 "log.install_disabled",        {} },
			-- V4.3.531 Fix 5: `[^-]+` is a negated byte class but em-dash is 3 bytes - collapsed to `(.-)` lazy.
			{ "Content manifest (.-) .- proceeding without auto%-install",        "log.install_manifest_skip",   { "reason" } },
			{ "Content manifest malformed",                                       "log.install_manifest_malformed",{} },
			{ "Rejecting suspicious manifest path: (.+)",                         "log.install_path_traversal",  { "path" } },
			{ "install worker crashed: (.+)",                                     "log.install_worker_crash",    { "err" } },
			{ "InstallContentAssets failed: (.+)",                                "log.install_failed",          { "err" } },
			{ "fetchAndSaveChunks: 30s deadline hit with (%d+) chunk",            "log.manifest_deadline",       { "pending" } },
			-- Atomic write (already has structured siblings; capture covers misses)
			{ "atomic write: encode failed for (.+)",                             "log.atomic_encode_fail",      { "path" } },
			{ "atomic write: tmp write failed for (.+)",                          "log.atomic_tmp_fail",         { "path" } },
			{ "atomic write: readback failed for (.+)",                           "log.atomic_readback_fail",    { "path" } },
			-- Character / accessory pipeline
			-- V4.3.531 Fix 5: em-dash byte fix.
			{ "ApplyDescription threw .- likely content%-deleted accessory in bundle: (.+)", "log.hd_apply_threw", { "err" } },
			{ "HumanoidDescriptionLoader timed out",                              "log.hd_timeout",              {} },
			{ "HumanoidDescriptionLoader: bundle has content%-deleted accessory IDs", "log.hd_content_deleted",  {} },
			{ "HumanoidDescriptionLoader: no accessories landed",                 "log.hd_no_accessories",       {} },
			-- Capture / anti-spoof
			{ "Capture%-detection host destroyed (%d+)",                          "log.capture_host_destroyed",  { "count" } },
			{ "CaptureEnded fired with no matching recent CaptureBegan",          "log.capture_spoof_no_begin",  {} },
			{ "CaptureService unavailable",                                       "log.capture_unavailable",     {} },
			-- Generic CharacterExecute / KrulHosted error catchall
			{ "CharacterExecute error: (.+)",                                     "log.char_execute_err",        { "err" } },
			{ "KrulHosted apply error: (.+)",                                     "log.krul_apply_err",          { "err" } },
		}

		-- Truncate captured fields to bound payload size (defense against an
		-- error message that contains an entire stack trace etc.).
		local function _trunc(s)
			if type(s) ~= "string" then return s end
			if #s > 200 then return s:sub(1, 200) .. "...[trunc]" end
			return s
		end

		-- V4.3.531 hotfix #5 + V4.3.533 HIGH Fix 3: orphan self-disconnect with LAZY
		-- session-id capture. V4.3.531 hotfix #5 captured `_mySession` at file scope
		-- BEFORE `RoClothes()` runs and sets `_rcSessionId` at L4541. Result: on first
		-- execute `_mySession = nil` and the orphan self-disconnect guard was a permanent
		-- no-op; on re-execute `_mySession` captured the PRIOR session's id (shifted-by-one)
		-- so the handler would self-disconnect on the NEXT session's first log line.
		-- Confirmed by 3-agent audit + workflow verification 2026-06-03.
		-- V4.3.533 fix: capture `_mySession` LAZILY inside the MessageOut callback on first
		-- fire. By then `RoClothes()` has finished init and minted `_rcSessionId` (the very
		-- first `[RoClothes]` log line is emitted at L4512 inside RoClothes), so the latched
		-- value is this handler's OWN session id. Subsequent fires compare against the live
		-- `_g._rcSessionId` - if it changed, we belong to a previous execute and disconnect.
		local _gh_ref
		pcall(function() _gh_ref = (getgenv and getgenv()) or nil end)
		pcall(function()
			local _conn
			local _mySession  -- latched on first MessageOut fire (lazy)
			_conn = _LS.MessageOut:Connect(function(message, msgType)
				-- V4.3.533 HIGH Fix 3: lazy latch of this session's id on first fire.
				if not _mySession and _gh_ref then
					_mySession = _gh_ref._rcSessionId
				end
				-- V4.3.531 hotfix #5: orphan self-disconnect. If the live session id no
				-- longer matches the one we latched on first fire, this handler belongs
				-- to a previous execute that wasn't cleaned up - disconnect now.
				if _mySession and _gh_ref and _gh_ref._rcSessionId ~= _mySession then
					pcall(function() if _conn then _conn:Disconnect() end end)
					return
				end
				if type(message) ~= "string" then return end
				-- Allow-list by prefix. Anything not prefixed is ignored.
				-- V4.3.531 hotfix #5: use PLAIN substring search (4th arg `true`) instead
				-- of pattern matching. LogService.MessageOut fires on every console line in
				-- the process - including chatty engine warnings unrelated to RoClothes. Plain
				-- substring search is significantly faster than the pattern engine for the
				-- early-out path. User reported "physics SUPER wonky" in V4.3.531 - physics
				-- code is byte-identical to V4.3.525, so the only plausible per-frame overhead
				-- source is this handler firing pattern-matches on every engine log line.
				if not message:find("[RoClothes]", 1, true) then return end
				-- Strip the prefix segment for cleaner pattern matching.
				local body = message:match("%[RoClothes%]%s*(.+)") or message
				for _, def in ipairs(_patterns) do
					local pat, evName, fields = def[1], def[2], def[3]
					local captures = { string.match(body, pat) }
					if #captures > 0 or string.find(body, pat) then
						if not _rateOk(evName) then return end
						local payload = {}
						for i, fn in ipairs(fields) do
							payload[fn] = _trunc(captures[i])
						end
						if msgType then
							-- 0=Output, 1=Info, 2=Warning, 3=Error per Enum.MessageType
							local _ok_mt, _mtVal = pcall(function() return msgType.Value end)
							if _ok_mt then payload._mt = _mtVal end
						end
						_diagPublicCall(evName, payload)
						return  -- one match per line; first wins
					end
				end
			end)
			-- V4.3.531 Fix 4: publish on getgenv so the next session's prior-cleanup block
			-- at the top of this `do ... end` can Disconnect this connection on re-execute.
			pcall(function()
				local _ok_g2, _g2 = pcall(function() return (getgenv and getgenv()) or nil end)
				if _ok_g2 and _g2 then _g2._RC_logsvc_msg_conn = _conn end
			end)
		end)
	end
end

-- Periodic flush coroutine - file-scope so it survives even if RoClothes()
-- short-circuits during init. Initial 5s wait so script-start events flush
-- together in the first batch.
-- V4.3.514: stash task handle on getgenv() and cancel prior session's coroutine
-- on re-execute. Without this, every re-execute leaked a flush coroutine forever.
do
	local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
	local _prior = _ok_genv and _genv and _genv._RC_diag_flush_task or nil
	if _prior then pcall(task.cancel, _prior) end
	local _h = task.spawn(function()
		task.wait(5)
		while true do
			pcall(_diagFlush)
			task.wait(_DIAG_FLUSH_INTERVAL)
		end
	end)
	if _ok_genv and _genv then _genv._RC_diag_flush_task = _h end
end

-- ============================================================================
-- V4.3.507: Phase 3 - opt-in network uploader.
--
-- Phase 1's _DIAG_RING is cleared on every 60s disk-flush, so the uploader
-- needs its own queue. _DIAG_UP_RING is a separate ring buffer that mirrors
-- _DIAG_RING on each event but is drained ONLY by successful uploads. Cap
-- and eviction semantics match Phase 1's (256 entries, FIFO eviction).
--
-- Privacy commitments enforced in this layer:
--   - Default OFF (PlayerDataDefault._telemEnabled = false).
--   - Install ID generated lazily, never tied to UserId.
--   - No upload attempt at all when _telemEnabled is false.
--   - 3 retries on 5xx / network failure, then silent stop for the session.
--   - 4xx responses DROP the batch (server validation rejected - don't retry).
--   - Hard caps: 50 events per batch, 64 KB serialized - server WAF caps at
--     50 events and 100 KB body, so leaving 36 KB headroom is intentional.
-- ============================================================================
local _DIAG_UP_RING = {}
local _DIAG_UP_RING_CAP = 256
local _DIAG_UP_RING_HEAD = 1
local _DIAG_UP_RING_COUNT = 0
local _DIAG_UP_ENDPOINT = "https://krulhub.dev/telemetry/ingest"
local _DIAG_UP_INTERVAL = 300          -- 5 minutes between batches
local _DIAG_UP_MAX_EVENTS = 50
local _DIAG_UP_MAX_BYTES = 64 * 1024
local _DIAG_UP_RETRY_DELAYS = {5, 15, 60}  -- exponential backoff seconds
local _DIAG_UP_NETWORK_DEAD = false    -- set true after retries exhausted; reset on success
local _DIAG_UP_RETRY_COUNT = 0
_DIAG_UP_ENABLED_GETTER = nil          -- set by RoClothes init to a getter for PlayerData[lP.Name]._telemEnabled
local _DIAG_UP_INSTALLID_GETTER = nil  -- set by RoClothes init to a getter that lazy-generates+persists the install ID
-- V4.3.518 Fix 1: monotonic push sequence to make peek+yield+consume race-safe.
-- During HTTP POST yield the ring can wrap-evict the peeked entries; consume
-- by-count would drop unrelated live entries from the new head. Consume by
-- seq lets evicted entries become silent no-ops (next head has a higher seq).
local _DIAG_UP_SEQ = 0

-- V4.3.511 Fix 8: Settings.json write lock. Four callers can race on this file:
-- saveButton, _persistTelemKeys, the lazy install-ID spawn, and the AutoExecute
-- persist. Each does read-decode-merge-write; even with _atomicWriteJSON they
-- can interleave at the read step and lose each other's mutations on the
-- subsequent write. The boolean lock serializes the whole read-merge-write
-- transaction (not just the write).
local _SETTINGS_WRITE_LOCK = false
-- V4.3.521 Fix 1: per-acquire lock generation. V4.3.520 Fix 1's watchdog had no
-- identity - holder A's 30s watchdog could force-release holder B's lock if B
-- happened to be holding it at the +30s mark. 3rd attempt: file-scope _lockGen
-- bumps on every acquire; watchdog only fires if both _SETTINGS_WRITE_LOCK is
-- still set AND _lockGen still matches the acquire's captured gen.
local _SETTINGS_LOCK_GEN = 0
local function _acquireSettingsLock(timeoutSec)
	timeoutSec = timeoutSec or 5
	local t0 = os.clock()
	while _SETTINGS_WRITE_LOCK do
		if os.clock() - t0 > timeoutSec then return false end
		task.wait(0.05)
	end
	_SETTINGS_WRITE_LOCK = true
	_SETTINGS_LOCK_GEN = _SETTINGS_LOCK_GEN + 1
	return _SETTINGS_LOCK_GEN
end
-- V4.5.24 Fix: gen-aware release. Only the holder that STILL owns the lock (gen match) may clear it.
-- If a watchdog already force-released or a successor holds the lock, this is a no-op - closes the
-- late-normal-path release of a stale holder freeing a NEW holder's lock mid-transaction.
local function _releaseSettingsLock(gen)
	if gen == nil or _SETTINGS_LOCK_GEN == gen then
		_SETTINGS_WRITE_LOCK = false
	end
end
-- V4.3.520 Fix 1: REPLACE V4.3.519 Fix 5's task.defer release - defer fires on
-- next scheduler tick which lands DURING fn's first yield, releasing the lock
-- mid-transaction and defeating the mutex. Use a 30s watchdog instead: normal
-- path releases via the deferred-cleanup local; cancellation safety comes from
-- the watchdog clearing a stuck lock if the holder coroutine died mid-yield.
local function _withSettingsLock(fn)
	local _myGen = _acquireSettingsLock(5)
	if not _myGen then
		_diagPublicCall("settings.write_lock_timeout", {})
		return false, "lock_timeout"
	end
	-- Watchdog: 30s after acquire, if lock is STILL held by the same logical
	-- acquire (no other caller intervened), force-release. Catches the cancel-
	-- mid-yield case without releasing during normal yields.
	-- V4.3.531 Fix 6: prior code left the task.delay handle unreachable and never
	-- cancelled it on the normal release path. Every settings save left a 30s
	-- timer alive in the scheduler - gen-match guard prevented incorrect releases
	-- but the timers still accumulated across save-heavy sessions (bundle import,
	-- slider drags, AutoExecute toggles). Now stored + cancelled on normal exit.
	local _acquiredAt = os.clock()
	local _watchdog = task.delay(30, function()
		if _SETTINGS_WRITE_LOCK and _SETTINGS_LOCK_GEN == _myGen and (os.clock() - _acquiredAt) >= 30 then
			_releaseSettingsLock(_myGen)
			_diagPublicCall("settings.write_lock_watchdog", {})
		end
	end)
	local ok, err = pcall(fn)
	_releaseSettingsLock(_myGen)
	if _watchdog then pcall(task.cancel, _watchdog) end
	if not ok then
		_diagPublicCall("settings.write_error", { err = tostring(err) })
		return false, tostring(err)
	end
	return true, nil
end

-- V4.3.508: canonical head+count layout. Push writes at tail = (head-1+count) mod CAP + 1;
-- consume/evict advances head. Single layout eliminates the dense-vs-wrapped branch that
-- caused partial-drain corruption (V4.3.507 audit Fix 1 - consume left wrapped state, next
-- push's dense branch then overwrote live entries at COUNT+1).
-- V4.3.515 Fix 1 (CRITICAL): converted from `local function` to assignment of the
-- forward-declared symbol above. See comment block before _diagFlush.
_diagUpPush = function(entry)
	if type(entry) ~= "table" then return end
	_DIAG_UP_SEQ = _DIAG_UP_SEQ + 1
	entry._seq = _DIAG_UP_SEQ
	if _DIAG_UP_RING_COUNT < _DIAG_UP_RING_CAP then
		local writeIdx = ((_DIAG_UP_RING_HEAD - 1 + _DIAG_UP_RING_COUNT) % _DIAG_UP_RING_CAP) + 1
		_DIAG_UP_RING[writeIdx] = entry
		_DIAG_UP_RING_COUNT = _DIAG_UP_RING_COUNT + 1
	else
		_DIAG_UP_RING[_DIAG_UP_RING_HEAD] = entry
		_DIAG_UP_RING_HEAD = (_DIAG_UP_RING_HEAD % _DIAG_UP_RING_CAP) + 1
	end
end

-- Return up to `n` oldest events without consuming them. Used by the uploader
-- to build a batch + by the "View Pending" UI to show what would be sent.
local function _diagUpPeek(n)
	if _DIAG_UP_RING_COUNT == 0 then return {} end
	local out = {}
	local take = math.min(n or _DIAG_UP_RING_CAP, _DIAG_UP_RING_COUNT)
	for i = 1, take do
		local idx = ((_DIAG_UP_RING_HEAD - 1 + i - 1) % _DIAG_UP_RING_CAP) + 1
		out[#out + 1] = _DIAG_UP_RING[idx]
	end
	return out
end

-- V4.3.518 Fix 1: consume up to a captured peek-seq. Evicted entries (seq
-- already higher than maxSeq) trigger an early stop; new entries pushed
-- during the upload yield are untouched.
local function _diagUpConsumeUpTo(maxSeq)
	if type(maxSeq) ~= "number" then return end
	while _DIAG_UP_RING_COUNT > 0 do
		local head = _DIAG_UP_RING[_DIAG_UP_RING_HEAD]
		if not head or type(head._seq) ~= "number" or head._seq > maxSeq then break end
		_DIAG_UP_RING[_DIAG_UP_RING_HEAD] = nil
		_DIAG_UP_RING_HEAD = (_DIAG_UP_RING_HEAD % _DIAG_UP_RING_CAP) + 1
		_DIAG_UP_RING_COUNT = _DIAG_UP_RING_COUNT - 1
	end
	if _DIAG_UP_RING_COUNT == 0 then _DIAG_UP_RING_HEAD = 1 end
end

-- Drop the oldest `n` events (called after successful upload OR after 4xx drop).
local function _diagUpConsume(n)
	if n <= 0 or _DIAG_UP_RING_COUNT == 0 then return end
	n = math.min(n, _DIAG_UP_RING_COUNT)
	for k = 1, n do
		_DIAG_UP_RING[_DIAG_UP_RING_HEAD] = nil
		_DIAG_UP_RING_HEAD = (_DIAG_UP_RING_HEAD % _DIAG_UP_RING_CAP) + 1
	end
	_DIAG_UP_RING_COUNT = _DIAG_UP_RING_COUNT - n
	if _DIAG_UP_RING_COUNT == 0 then _DIAG_UP_RING_HEAD = 1 end
end

-- V4.3.518 Fix 5: stable Random instance for install-ID generation. Pre-fix
-- math-based seeding lost precision in double-float lower bits; two opt-ins
-- in the same tick window could collide. Engine-seeded Random.new() (no-arg)
-- uses cryptographic entropy at construction.
local _DIAG_INSTALLID_RNG = Random.new()
-- UUIDv4 generator. Local Random instance - V4.3.478 lesson: never touch
-- process-wide math.randomseed (mutates other scripts' RNG state).
local function _diagGenUUIDv4()
	local _rng = _DIAG_INSTALLID_RNG
	local function _hex(n)
		local s = ""
		for i = 1, n do
			s = s .. string.format("%x", _rng:NextInteger(0, 15))
		end
		return s
	end
	local yChars = {"8", "9", "a", "b"}
	local y = yChars[_rng:NextInteger(1, 4)]
	return _hex(8) .. "-" .. _hex(4) .. "-4" .. _hex(3) .. "-" .. y .. _hex(3) .. "-" .. _hex(12)
end

-- Build a batch wrapper for upload. Caps at MAX_EVENTS and MAX_BYTES; if a
-- single event exceeds MAX_BYTES (impossible in practice - each event's `p`
-- is already capped 4 KB server-side and ~1 KB in practice), drop it.
local function _diagBuildBatch()
	if not _DIAG_UP_INSTALLID_GETTER then return nil, 0 end
	local iid = _DIAG_UP_INSTALLID_GETTER()
	if type(iid) ~= "string" or #iid == 0 then return nil, 0 end
	local exe = _diagResolveExe()
	local plat = _diagResolvePlat()
	local HSr = game:GetService("HttpService")
	local candidates = _diagUpPeek(_DIAG_UP_MAX_EVENTS)
	if #candidates == 0 then return nil, 0 end
	-- Build, serialize, and shrink-to-fit by halving until <=MAX_BYTES.
	local take = #candidates
	local payload, encoded
	-- V4.3.518 Fix 1: also track the max _seq in the included slice so the
	-- caller can consume-by-seq after the HTTP yield (avoids dropping live
	-- entries pushed during the yield if the ring wrap-evicts).
	local maxSeq = nil
	while take > 0 do
		local evs = {}
		local sliceMax = nil
		for i = 1, take do
			local e = candidates[i]
			evs[i] = { ts = e.ts, ev = e.ev, p = e.p or {} }
			if type(e._seq) == "number" and (not sliceMax or e._seq > sliceMax) then sliceMax = e._seq end
		end
		payload = { v = _RC_VER, iid = iid, exe = exe, plat = plat, events = evs }
		local okEnc, enc = pcall(function() return HSr:JSONEncode(payload) end)
		if not okEnc then return nil, 0 end
		encoded = enc
		maxSeq = sliceMax
		if #encoded <= _DIAG_UP_MAX_BYTES then break end
		take = math.floor(take / 2)
	end
	if not encoded or take == 0 then
		-- Single event too large - drop the oldest to unblock the queue.
		-- V4.3.509 Fix 8: surface the drop so we notice if a payload generator
		-- starts emitting oversized `p` tables in the wild.
		pcall(_diagRecord, "upload.event_oversize", { hint = "single event > _DIAG_UP_MAX_BYTES, dropping" })
		_diagUpConsume(1)
		return nil, 0
	end
	return encoded, take, maxSeq
end

-- Resolve the HTTP request function from the script's existing fallback chain.
local function _diagResolveHttpReq()
	-- Match the V4.3.505 _httpReq chain at L15533+ (System.Env populated by RoClothes init).
	local env = (getgenv and getgenv()) or _G
	return env.http_request
		or env.request
		or (env.syn and env.syn.request)
		or (env.http and env.http.request)
end

-- POST a batch. Returns (statusCode, ok). statusCode is 0 on transport-level failure.
local function _diagUpPost(encoded)
	local reqFn = _diagResolveHttpReq()
	if type(reqFn) ~= "function" then
		_diagPublicCallOnce("upload_request_fn")
		return 0, false
	end
	-- V4.3.526 Fix 14: 60s HTTP timeout via deadline race. Pre-fix a stalled POST
	-- held the uploader coroutine indefinitely; ring kept wrap-evicting; only
	-- returned 5xx triggered backoff, not hung sockets.
	local _done = false
	local _ok, _res = false, nil
	local _httpCo = coroutine.running()
	-- V4.3.531 Fix 7a: guard against being called outside a task.spawn context. On the
	-- main thread `coroutine.running()` returns nil in Lua 5.1-style Luau and
	-- `coroutine.yield()` below would error. Bail with a transport-failure tuple
	-- rather than crash the upload pipeline.
	if not _httpCo then return 0, false end
	-- V4.3.531 Fix 7b: store the timeout handle so the success path can cancel it.
	-- Pre-fix every upload left a 60s timer in the scheduler regardless of outcome;
	-- the timer's `if not _done` guard prevented double-resume but the handle stayed
	-- live (memory + scheduler eval cost) until expiry.
	local _timeoutH = task.delay(60, function()
		if not _done then
			_done = true
			_ok = false
			_res = { StatusCode = 0, Body = "[client timeout 60s]" }
			pcall(task.spawn, _httpCo)
		end
	end)
	task.spawn(function()
		local _pok, _pres = pcall(reqFn, {
			Url = _DIAG_UP_ENDPOINT,
			Method = "POST",
			Headers = { ["Content-Type"] = "application/json" },
			Body = encoded,
		})
		if not _done then
			_done = true
			_ok = _pok
			_res = _pres
			if _timeoutH then pcall(task.cancel, _timeoutH) end
			pcall(task.spawn, _httpCo)
		end
	end)
	coroutine.yield()
	local ok, res = _ok, _res
	if not ok then return 0, false end
	if type(res) ~= "table" then return 0, false end
	local code = tonumber(res.StatusCode) or tonumber(res.Status) or 0
	return code, (code >= 200 and code < 300)
end

-- Single upload attempt. Returns:
--   "ok"      → batch sent, consumed N events from the ring
--   "drop"    → 4xx rejection, batch consumed (server rejected - don't retry)
--   "retry"   → 5xx or transport failure, batch stays in ring
--   "skip"    → nothing to send / not enabled / network already dead
local function _diagUpAttempt()
	-- V4.3.508: check enabled BEFORE NETWORK_DEAD so opt-out → opt-in flow clears the dead-path
	-- (diagUploadClear now resets NETWORK_DEAD on toggle).
	if not _DIAG_UP_ENABLED_GETTER then return "skip" end
	local enabled = _DIAG_UP_ENABLED_GETTER()
	if not enabled then return "skip" end
	if _DIAG_UP_NETWORK_DEAD then return "skip" end
	if _DIAG_UP_RING_COUNT == 0 then return "skip" end
	local encoded, take, maxSeq = _diagBuildBatch()
	if not encoded or take == 0 then return "skip" end
	local code, isOk = _diagUpPost(encoded)
	if isOk then
		-- V4.3.518 Fix 1: consume by captured seq (race-safe across HTTP yield).
		if type(maxSeq) == "number" then
			_diagUpConsumeUpTo(maxSeq)
		else
			_diagUpConsume(take)
		end
		_DIAG_UP_RETRY_COUNT = 0
		return "ok"
	end
	if code >= 400 and code < 500 then
		-- Validation failure server-side: drop and move on.
		-- V4.3.518 Fix 1: also race-safe consume on 4xx (same post-yield window).
		if type(maxSeq) == "number" then
			_diagUpConsumeUpTo(maxSeq)
		else
			_diagUpConsume(take)
		end
		_DIAG_UP_RETRY_COUNT = 0
		return "drop"
	end
	return "retry"
end

-- Periodic uploader coroutine. Wakes every UP_INTERVAL seconds, runs one
-- attempt, handles retry backoff. Bails silently if _telemEnabled is false.
-- V4.3.514: stash + cancel prior session's coroutine on re-execute (same pattern as _diagFlush above).
do
	local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
	local _prior = _ok_genv and _genv and _genv._RC_diag_up_task or nil
	if _prior then pcall(task.cancel, _prior) end
	local _h = task.spawn(function()
	-- Initial delay so we don't fire before RoClothes init populates the getters.
	task.wait(30)
	while true do
		-- V4.3.508: wrap iteration body so a single throw (e.g. JSON encode of an
		-- exotic event field) doesn't kill telemetry for the session.
		local _ok, _waitFor = pcall(function()
			local res = _diagUpAttempt()
			if res == "retry" then
				-- Bounded backoff: retry up to 3 times before giving up for the session.
				_DIAG_UP_RETRY_COUNT = _DIAG_UP_RETRY_COUNT + 1
				local delay = _DIAG_UP_RETRY_DELAYS[_DIAG_UP_RETRY_COUNT] or 60
				-- V4.3.509 Fix 7: off-by-one. Comment says "up to 3 retries" but `>` allowed
				-- a 4th attempt before NETWORK_DEAD. Use `>=` so retry count matches doc.
				if _DIAG_UP_RETRY_COUNT >= #_DIAG_UP_RETRY_DELAYS then
					_DIAG_UP_NETWORK_DEAD = true
					_DIAG_UP_RETRY_COUNT = 0
					return _DIAG_UP_INTERVAL
				else
					return delay
				end
			else
				return _DIAG_UP_INTERVAL
			end
		end)
		if _ok and type(_waitFor) == "number" then
			task.wait(_waitFor)
		else
			task.wait(_DIAG_UP_INTERVAL)
		end
	end
	end)
	if _ok_genv and _genv then _genv._RC_diag_up_task = _h end
end

-- Manual flush - called by "Send Now" button. Runs one attempt synchronously
-- (no retry backoff - user expects immediate feedback). Returns the result
-- string and the count of events sent if "ok".
local function _diagUpFlushNow()
	if _DIAG_UP_NETWORK_DEAD then _DIAG_UP_NETWORK_DEAD = false end  -- give it another shot
	_DIAG_UP_RETRY_COUNT = 0  -- so background loop doesn't immediately re-kill after this attempt
	local before = _DIAG_UP_RING_COUNT
	local res = _diagUpAttempt()
	local sent = (res == "ok") and (before - _DIAG_UP_RING_COUNT) or 0
	return res, sent
end

-- V4.3.302: file-scope allowlist for Preset keys writable from foreign-bundle data.
-- Used by ApplyBundleToPeerData, _overlayTweaks, and checkBundle to gate writes to
-- PlayerData fields. Pre-fix V4.3.296 only enforced this in _overlayTweaks; the other
-- two paths used a narrow blacklist that left LastRequestID, Cooldown, AutoExecute,
-- DelayTime, ExecutionMaid, Connections, CurrentBundle, etc. writable from peer/import
-- bundles - bundle-corruption-as-DoS / cross-player-state-poison vectors.
local _PEER_ALLOWED_PRESET_KEYS = {
	BreastsType=true, TorsoType=true, ArmType=true, LegsType=true, ButtType=true,
	BreastsScale=true, ButtsScale=true, LegsScale=true, TorsoScale=true, LeftArmScale=true, RightArmScale=true, CockScale=true,
	BodyPartPhysics=true, Tone=true, RealtimeBodyTransparency=true,
	Face=true, AccessorySizeLock=true, PhysicsObeyGravity=true,
	TopHP=true, BottomHP=true, HardcoreHP=true, NippleColor=true,
	NippleColorFromBundle=true, SmartBoneEnabled=true,
	TearParticles=true, HealParticles=true, MeshSizeLock=true,
	MeshBasePartInvisible=true, BreathingEnabled=true, OvertoneEnabled=true,
	BreathingAmplitude=true, OvertoneAmplitude=true, BundleBodyColor=true,
	BreastsStiffness=true, BreastsDamping=true, ButtsStiffness=true, ButtsDamping=true,
	CockStiffness=true, CockDamping=true,
	-- Local-bundle-applicable keys (additions for checkBundle parity):
	BodyTransparency=true, FPerson=true, DamageSFX=true, Volume=true,
	-- V4.3.354: keys captured by Save Outfit's _buildOutfitPreset. Local re-apply
	-- via checkBundle reads these from v.Preset; without the allowlist entry the
	-- generic write at L18635 silently drops them, so re-equipping a saved outfit
	-- would lose its catalog clothing IDs / outfit id / strip filter / skin tone.
	-- All of these are simple values (string / sub-table / Color3) - no live
	-- references to internal connection / cooldown machinery.
	CatalogClothes=true, CatalogOutfitId=true, StripCategories=true, SkinTone=true,
	-- V4.3.370: auto-strip-on-rip preferences. Both are simple values
	-- (boolean / map<string,string>). The map values are constrained to
	-- "None"/"Top"/"Bottom"/"Both" - runtime ignores unknown values.
	AutoStripOnRip=true, StripOnRipMap=true,
	-- V4.3.403: per-cloth HP cycle + recolor + accessory HP + gizmo offsets/presets. (see Changelog for full rationale)
	-- V4.3.382 added these to Save Outfit's _buildOutfitPreset capture, but they
	ClothesHP=true, ClothesRecolor=true, AccessoryHP=true,
	-- V4.3.517 Fix 6: include singular GizmoOffset alongside plural GizmoOffsets.
	-- Peer broadcasts and _buildOutfitPreset capture both; plural was allowlisted but
	-- singular was dropped at the gate, silently losing per-target offset on round-trip.
	GizmoOffsets=true, GizmoOffset=true, GizmoPresets=true,
	-- V4.3.446: catalog round-trip parity. CatalogUsername mirrors CatalogOutfitId
	-- (already allowed). CatalogRemove is per-bundle accessory exclusion list.
	-- CatalogHistory is the recently-equipped ring buffer (cap 20). MeshEdit
	-- preserves user's per-part Size/CFrame/TextureId overrides across save/load.
	CatalogUsername=true, CatalogRemove=true, CatalogHistory=true, MeshEdit=true,
	-- V4.3.504: LocalTransparency per-part bool map. Toggle handlers at L22779-22781 mutate
	-- this on user clicks; without preset capture + allowlist entry, saved outfits lost
	-- the user's per-part visibility state on reload.
	LocalTransparency=true,
	-- V4.3.534 F10/F11/F12: previously-missing allowlist entries surfaced by feature-
	-- completeness audit. Without these, captures in _buildOutfitPreset (HPClothesTemplates,
	-- FPsnap, HeadTracking, PositionPhysicsMultiply, RotationPhysicsMultiply) would be
	-- rejected at every load gate (_validatePresetValue / ApplyBundleToPeerData) and the
	-- save would round-trip as a no-op. F12 entries are accepted by checkBundle's special-
	-- case branch (L24675-L24678) but adding them here keeps the allowlist comprehensive.
	HPClothesTemplates=true, FPsnap=true, HeadTracking=true,
	PositionPhysicsMultiply=true, RotationPhysicsMultiply=true,
}

-- Tail animation constants (outside RoClothes to save local registers)
local timeStep = 1 / 60
local inverseTimeStep = 1 / timeStep
local wagAnimationDropAmplitude = 0.2
local wagAnimationSwayAmplitude = 0.4
local wagAnimationRollAmplitude = 0.5
local wagAnimationBlendInAlpha = 0.008
local wagAnimationBlendOutAlpha = 0.02

-- V4.3.374: file-scope fade-tween cache + helper, hoisted from inside (see Changelog for full rationale)
local _RC_TS = game:GetService("TweenService")
local _RC_FADE_INFO_HIDE = TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local _RC_FADE_INFO_SHOW = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local _RC_pendingFadeTweens = setmetatable({}, {__mode = "k"})
-- V4.3.424: was `_prev:Cancel()` only - the cancelled Tween's Instance property still
-- strongly references its target (the handle MeshPart), which keeps the supposedly-weak
-- key alive through the Tween value. Classic weak-table-with-strong-value-ref footgun:
-- the table grows monotonically across bundle swaps even though it's marked `__mode="k"`.
-- Each bundle swap leaks ~12 cancelled Tween objects keyed by detached MeshParts. Fix:
-- `:Destroy()` the previous tween after `:Cancel()`, and clear the entry on Completed
-- so non-cancelled tweens also drop. Caught by bug-hunter audit 2026-05-14 (HIGH/HIGH).
local function _RC_fadeHandle(handle, targetTransparency)
	if not handle then return end
	-- Persist HP ownership separately from body tracking; healing restores the
	-- handle's authored alpha rather than forcing every accessory to opaque.
	local _baseAlpha = handle:GetAttribute("_RC_HPBaseTransparency")
	if _baseAlpha == nil then
		_baseAlpha = handle.Transparency
		handle:SetAttribute("_RC_HPBaseTransparency", _baseAlpha)
	end
	handle:SetAttribute("_RC_HPHidden", targetTransparency >= 0.5)
	if targetTransparency < 0.5 then targetTransparency = _baseAlpha end
	local _prev = _RC_pendingFadeTweens[handle]
	if _prev then pcall(function() _prev:Cancel(); _prev:Destroy() end) end
	local _info = (targetTransparency >= 0.5) and _RC_FADE_INFO_HIDE or _RC_FADE_INFO_SHOW
	local _t = _RC_TS:Create(handle, _info, {Transparency = targetTransparency})
	_RC_pendingFadeTweens[handle] = _t
	pcall(function() _t:Play() end)
	-- Clear our entry once the tween completes naturally so the handle GC-eligibility
	-- isn't blocked by our value-side strong ref. Guard against late-replacement: only
	-- nil the slot if it still points at THIS tween.
	pcall(function()
		_t.Completed:Once(function()
			if _RC_pendingFadeTweens[handle] == _t then
				_RC_pendingFadeTweens[handle] = nil
			end
			pcall(function() _t:Destroy() end)
		end)
	end)
end

-- V4.3.265: hoisted constants - keeps them out of the RoClothes function-scope
-- 200-local register budget. Same names so callsites unchanged.
local MaxBreastsType = 6   -- V4.3.414: dropped from 7 → 6. Phys UV V2 (Type 7) removed - mesh authoring constraints made SB physics impossible (only Bone has skin weights, Bone.001 dead; V4.3.409 oscillation test proved it). The Type 7 dispatch block remains but now falls through to SB1 weld (the dispatch is unreachable since cycle UI caps at 6, but the safe-fallback is kept in case of saved bundles with BreastsType=7).
local MaxTorsoType   = 9   -- 9 = VNS mesh type
local MaxArmType     = 5   -- 5 = VNS mesh type
local MaxLegsType    = 8   -- 8 = VNS mesh type
local MaxButtType    = 6   -- 6 = VNS mesh type
local DarkerColorPercentage  = 17.75
local Darker2ColorPercentage = 32.75
local Circle = 2 * math.pi

-- V4.3.50 hotfix: moved out of RoClothes to avoid LuaU 200-local register cap per function.
-- Modules A (physics warn throttle) + C (weld re-clone budget) pushed RoClothes over the limit,
-- triggering "Out of local registers" at UIDragDetector allocation. Keeping these file-scope
-- means TryRecloneWeld and the physics pcall handler capture them as upvalues instead of locals.
local physicsWarnState = {}  -- [errKey] = lastWarnClock
local PHYSICS_WARN_COOLDOWN = 5
local reCloneBudget = setmetatable({}, {__mode = "k"})
local RECLONE_WINDOW_SECONDS = 1
local RECLONE_MAX_PER_WINDOW = 8


-- GUI BUILDER MODULE (V4.3.113) - declarative UI construction
-- Placed at file scope so Theme/UI are upvalues inside RoClothes(),
-- consuming only 2 locals from the RoClothes() register pool.


-- ===================================================================
-- V4.3.492: Global persistent brand overlay. Bouncing "RoClothes:Krul"
-- letters that live from script entry through end of intro, replacing
-- the V4.3.307 _RoClothesBootSplash pill AND the V4.3.189 _sharedLoadui
-- fullscreen "loading" splash. User report 2026-05-19 (V4.3.491):
-- "can you improve the download phase to include the brand?" + "the
-- 'loading' text still pops up". This module owns the loading UI for
-- the entire boot pipeline: install → preload → playback transition.
-- ===================================================================
local _RC_Brand = {}
do
	local cg          = game:GetService("CoreGui")
	local _RS_brand   = game:GetService("RunService")
	local TextService = game:GetService("TextService")

	local BRAND_STR     = "RoClothes:Krul"
	local BRAND_FONT    = Enum.Font.GothamBold
	local BRAND_CYCLE   = 1.4    -- bounce cycle seconds (matches playground)
	local BRAND_STAGGER = 0.07   -- per-letter Mexican-wave stagger (matches playground)

	local _gui, _dim, _holder, _wrappers, _letters, _pctReadout
	local _letterTweens  -- legacy sentinel - V4.3.501 retired per-letter tweens but the
	                     -- name is checked by older audit guards; kept as a live-flag table
	local _bounceConn    -- V4.3.501: single Heartbeat that drives all letters from elapsed time
	local _letterWidths = {}
	local _totalBigW    = 0
	local _bigSize      = 36
	local _LETTER_MIN_FRAC = 0.22

	local _installBounce  -- V4.3.502: forward-declared so _build() can call it; defined below

	local function _build()
		-- Wipe any prior brand from a re-execute mid-boot.
		for _, c in ipairs(cg:GetChildren()) do
			if c.Name == "_RoClothesBrand" then pcall(function() c:Destroy() end) end
		end

		local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720)
		_bigSize = math.clamp(math.floor(vp.Y * 0.05), 36, 96)
		local holderH = math.floor(_bigSize * 1.8)

		_letterWidths = {}
		_totalBigW = 0
		for i = 1, #BRAND_STR do
			local ch = BRAND_STR:sub(i, i)
			local _ok, b = pcall(function()
				return TextService:GetTextSize(ch, _bigSize, BRAND_FONT, Vector2.new(2000, 2000))
			end)
			local nat = (_ok and b and b.X) or (_bigSize * 0.55)
			_letterWidths[i] = math.max(nat + 1, math.floor(_bigSize * _LETTER_MIN_FRAC))
			_totalBigW = _totalBigW + _letterWidths[i]
		end

		_gui = Instance.new("ScreenGui")
		_gui.Name = "_RoClothesBrand"
		_gui.IgnoreGuiInset = true
		_gui.ResetOnSpawn = false
		_gui.DisplayOrder = 1000002       -- ABOVE install overlay (999999), intro (999998), install popup (1000000)
		_gui.Parent = cg

		_dim = Instance.new("Frame", _gui)
		_dim.Size = UDim2.fromScale(1, 1)
		_dim.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
		_dim.BackgroundTransparency = 1   -- transparent during install (no dim until intro card materializes)
		_dim.BorderSizePixel = 0
		_dim.Active = false               -- input falls through to install / game

		_holder = Instance.new("Frame", _dim)
		_holder.BackgroundTransparency = 1
		_holder.BorderSizePixel = 0
		_holder.AnchorPoint = Vector2.new(0.5, 0.5)
		_holder.Position = UDim2.fromScale(0.5, 0.5)
		_holder.Size = UDim2.fromOffset(_totalBigW, holderH)
		-- V4.3.495: ZIndex bumped 20 → 500 so the brand renders above EVERYTHING
		-- in the intro's gui (ring labels' active slot is ZIndex=100, skip
		-- button is ZIndex=200). Under Global ZIndexBehavior - which some
		-- executors default to even though Roblox Studio defaults to Sibling -
		-- the previous ZIndex=20 was BELOW the active ring label and the brand
		-- was hidden behind the video. ZIndex=500 wins under both Sibling and
		-- Global behavior. User report: "scan the full source code, find out
		-- why and fix it".
		_holder.ZIndex = 500

		_wrappers = {}
		_letters  = {}
		local cumX = 0
		for i = 1, #BRAND_STR do
			local ch = BRAND_STR:sub(i, i)
			local w  = _letterWidths[i]
			local wrap = Instance.new("Frame", _holder)
			wrap.BackgroundTransparency = 1
			wrap.BorderSizePixel = 0
			wrap.AnchorPoint = Vector2.new(0, 0.5)
			wrap.Position = UDim2.new(0, cumX, 0.5, 0)
			wrap.Size = UDim2.fromOffset(w, math.floor(_bigSize * 1.2))
			wrap.ZIndex = 501  -- V4.3.495: above labels[1]=100 + skip=200 under Global ZIndexBehavior
			_wrappers[i] = wrap

			local lb = Instance.new("TextLabel", wrap)
			lb.AnchorPoint = Vector2.new(0.5, 0.5)
			lb.Position = UDim2.fromScale(0.5, 0.5)
			lb.Size = UDim2.fromScale(1, 1)
			lb.BackgroundTransparency = 1
			lb.BorderSizePixel = 0
			lb.Font = BRAND_FONT
			lb.TextSize = _bigSize
			lb.Text = ch
			lb.ZIndex = 502  -- V4.3.495: above wrapper + everything else under Global
			lb.TextXAlignment = Enum.TextXAlignment.Center
			lb.TextYAlignment = Enum.TextYAlignment.Center
			lb.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
			lb.TextStrokeTransparency = 0.2
			if i >= 11 then  -- "K","r","u","l" (positions 11-14)
				lb.TextColor3 = Color3.fromRGB(255, 110, 180)  -- pink
			elseif ch == ":" then
				lb.TextColor3 = Color3.fromRGB(200, 200, 215)
			else
				lb.TextColor3 = Color3.fromRGB(245, 247, 255)
			end
			_letters[i] = lb
			cumX = cumX + w
		end

		-- Small % readout pill below the brand.
		_pctReadout = Instance.new("TextLabel", _holder)
		_pctReadout.AnchorPoint = Vector2.new(0.5, 0)
		_pctReadout.Position = UDim2.new(0.5, 0, 1, 8)
		_pctReadout.Size = UDim2.fromOffset(72, 22)
		_pctReadout.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
		_pctReadout.BackgroundTransparency = 0.45
		_pctReadout.BorderSizePixel = 0
		_pctReadout.Font = Enum.Font.RobotoMono
		_pctReadout.TextSize = 12
		_pctReadout.TextColor3 = Color3.fromRGB(200, 205, 220)
		_pctReadout.Text = "0%"
		_pctReadout.ZIndex = 503  -- V4.3.495: above brand letters
		Instance.new("UICorner", _pctReadout).CornerRadius = UDim.new(0, 6)

		-- V4.3.501: single deterministic Heartbeat replaces 14 per-letter
		-- coroutines. The V4.3.495 task.spawn-per-letter approach used
		-- `tween.Completed:Wait()` to gate each phase, but Wait() doesn't
		-- resume exactly at tween end - it queues on the next Heartbeat,
		-- adding ~1/60s of unique jitter per coroutine per cycle. Per-letter
		-- jitter accumulates INDEPENDENTLY, so within ~30-60 cycles the
		-- letters drift completely out of phase. User report with screenshot
		-- after V4.3.499/500: "the bouncing effect gets out of sync, and its
		-- not bouncing letter by letter, making it look weird" - pink 'Krul'
		-- letters at peak while 'RoClothes:' was sitting at baseline.
		--
		-- Single-Heartbeat design: ONE connection drives ALL letters. Each
		-- letter's Y position is a pure function of `(os.clock() - start)`
		-- and its index `i`. No per-letter state, no Wait jitter, no possible
		-- phase drift. This matches CSS `animation-delay` semantics from
		-- intro_loader_playground.html: every letter's phase is derived from
		-- one shared wall clock + a constant per-letter offset.
		--
		-- Bounce curve (matches playground CSS keyframes):
		--   0% .. 30% : ease-in-out, baseline (0) → peak (_peakPx)
		--   30% .. 60%: ease-in-out, peak → baseline
		--   60% .. 100%: rest at baseline
		-- Smoothstep `t*t*(3-2t)` is the standard cubic that approximates CSS
		-- `ease-in-out` (the actual CSS curve is cubic-bezier(.42,0,.58,1)
		-- which is visually indistinguishable from smoothstep for a 0.42s arc).
		_installBounce()
	end

	-- V4.3.502: bounce install extracted so rebuildBounce() can re-arm the
	-- Heartbeat after the boot scrub kills it without rebuilding the GUI.
	_installBounce = function()
		local _bounceStart = os.clock()
		local _CYCLE       = BRAND_CYCLE
		local _STAG        = BRAND_STAGGER
		_letterTweens = {}  -- live-flag (truthy) so legacy audit guards still pass
		if _bounceConn then pcall(function() _bounceConn:Disconnect() end); _bounceConn = nil end
		_bounceConn = RS.Heartbeat:Connect(function()
			if not (_letters and _letterTweens) then return end
			local t = os.clock() - _bounceStart
			for i, lb in ipairs(_letters) do
				if lb and lb.Parent then
					-- V4.3.502: derive peak per-letter from CURRENT TextSize so the
					-- amplitude scales with Phase-2 migration (letters shrink to the
					-- small corner brand; bounce must shrink with them).
					local letterPeakPx = -math.floor((lb.TextSize or _bigSize) * 0.4)
					local phase = ((t - (i - 1) * _STAG) % _CYCLE) / _CYCLE
					local y
					if phase < 0.30 then
						local u = phase / 0.30
						y = u * u * (3 - 2 * u) * letterPeakPx
					elseif phase < 0.60 then
						local u = (phase - 0.30) / 0.30
						y = (1 - u * u * (3 - 2 * u)) * letterPeakPx
					else
						y = 0
					end
					lb.Position = UDim2.new(0.5, 0, 0.5, math.floor(y))
				end
			end
		end)
	end

	function _RC_Brand.build()
		if _gui and _gui.Parent then return end  -- idempotent
		_build()
	end

	-- V4.3.502: re-arm the Heartbeat after the boot scrub at ~L4325 disconnects
	-- it (the scrub identifies "script-owned" Heartbeat connections by
	-- getfenv(_fn).script == script and disconnects them; the brand bounce
	-- satisfies that check and gets killed on re-execute). Called from the
	-- post-scrub region in boot.
	function _RC_Brand.rebuildBounce()
		if _gui and _gui.Parent and _letters then
			_installBounce()
		end
	end

	-- V4.3.527 Fix 1: progress readout starting at 50% on warm sessions.
	-- Install (cold) drives 0..50%, preload drives 50..100%. On warm sessions install bails early without
	-- calling setProgress at all, so the FIRST call comes from preload at ~50% - the visible readout jumps
	-- 0% → 50% instantly. Detection: if the first call this session is ≥ 50%, install was skipped → rescale
	-- subsequent calls from [50,100] → [0,100] so the readout fills smoothly from 0% during preload only.
	local _firstProgressCallSeen = false
	local _rescaleFromHalf = false
	function _RC_Brand.setProgress(pct)
		if not _firstProgressCallSeen then
			_firstProgressCallSeen = true
			if pct >= 50 then _rescaleFromHalf = true end
		end
		if _rescaleFromHalf then pct = (pct - 50) * 2 end
		if _pctReadout and _pctReadout.Parent then
			_pctReadout.Text = math.floor(math.clamp(pct, 0, 100)) .. "%"
		end
	end

	function _RC_Brand.exists()
		return _gui ~= nil and _gui.Parent ~= nil
	end

	-- Snapshot of layout primitives - intro consumes these to drive the
	-- corner migration tween.
	function _RC_Brand.snapshot()
		return {
			gui          = _gui,
			dim          = _dim,
			holder       = _holder,
			wrappers     = _wrappers,
			letters      = _letters,
			pctReadout   = _pctReadout,
			letterWidths = _letterWidths,
			totalBigW    = _totalBigW,
			bigSize      = _bigSize,
			letterMinFrac = _LETTER_MIN_FRAC,
		}
	end

	function _RC_Brand.destroy()
		-- V4.3.501: disconnect the single Heartbeat that drives all letters.
		if _bounceConn then pcall(function() _bounceConn:Disconnect() end); _bounceConn = nil end
		_letterTweens = nil  -- clears the live-flag so any in-flight callback bails
		-- V4.3.497: destroy brand instances directly. V4.3.494 reparented _holder
		-- into intro.dim, so destroying only _gui (now empty ScreenGui) leaks the
		-- letter labels if the intro destroy short-circuits.
		if _holder then pcall(function() _holder:Destroy() end) end
		if _gui then pcall(function() _gui:Destroy() end); _gui = nil end
		_dim, _holder, _wrappers, _letters, _pctReadout = nil, nil, nil, nil, nil
	end
end
-- V4.3.496: only build the brand if the executor has the APIs the intro needs.
-- Audit Pass D #6: pre-fix `_RC_Brand.build()` ran unconditionally at script
-- entry, allocating ScreenGui + 14 wrappers + 14 TextLabels + spinning 14
-- task.spawn coroutines forever - even on minimal executors where the intro
-- can never play (no getcustomasset, no isfile). Now gate on the same caps
-- [V3 MERGE] old brand/video loader RETIRED - V3's Vampiric Aurora title is the intro now.
-- (build disabled; _RC_Brand.exists() stays false, so all `if _RC_Brand.exists()` guards skip cleanly.)

-- V4.3.556: install-complete marker portability. The marker was the DOTFILE
-- `RClothesContent/.manifest_version`. Volt (and likely other executors)
-- silently fail writefile/isfile on leading-dot filenames - verified on disk
-- 2026-06-08: Volt workspace had 1212 files and ZERO dotfiles, while Xeno had
-- the `.manifest_version` dotfile present. On Volt the marker never persisted,
-- which broke the intro through THREE paths: (1) _playIntroVideo's marker gate
-- bailed every launch; (2) _firstRunInstall stayed true forever → slow sync
-- install every launch; (3) the post-install intro replay was gated on the
-- marker landing, which it never did. Fix: the primary marker is now the
-- NON-dotfile `RClothesContent/manifest_version` (underscore/plain names write
-- fine on Volt - proven by _vns_uniq/_vns_dump dirs existing there). The legacy
-- dotfile is still READ as a fallback so dot-capable executors with an existing
-- `.manifest_version` don't trigger a needless re-verify on the first upgrade
-- launch. All marker existence checks route through _rcMarkerExists; writes use
-- MARKER_PATH (= primary); deletes remove both names.
local _RC_MARKER_PRIMARY = "RClothesContent/manifest_version"
local _RC_MARKER_LEGACY  = "RClothesContent/.manifest_version"
local function _rcMarkerExists(_isf)
	if type(_isf) ~= "function" then return false end
	local a = false; pcall(function() a = _isf(_RC_MARKER_PRIMARY) and true or false end)
	if a then return true end
	local b = false; pcall(function() b = _isf(_RC_MARKER_LEGACY) and true or false end)
	return b
end


--
-- V4.3.300: per-frame physics tick body extracted to a file-scope (see Changelog for full rationale)
local _physicsTickCtx = {}
local function _doPhysicsTickPart(ctx, Part, Property)
	if not Part or not Part.Parent or not Property.Base or not Property.Base.Parent or not Property.Weld or not Property.Weld.Parent then
		return
	end

	if ctx.Function.FallenPartCheck(Part) then
		ctx.DataList.CurrentPartList.BodyPartPhysics[Part] = nil
		return
	end

	local Character = ctx.DataList.Character
	local Human = Character and Character:FindFirstChildOfClass("Humanoid")
	if not Character or not Human then return end

	local Base = Property.Base
	local CurrentCFrame = Base.CFrame

	local OriginCFrame = Property.OriginCFrame
	local OriginPosition = OriginCFrame.Position
	local CurrentPosition = CurrentCFrame.Position
	local PositionDistance = (OriginPosition - CurrentPosition)

	-- Proximity LOD + teleport sanity check (matches reference)
	if (ctx._camPos - Base.Position).Magnitude < 300
		and (PositionDistance.Magnitude < math.max(Human.WalkSpeed/8,1) or PositionDistance.Magnitude <= Base.AssemblyLinearVelocity.Magnitude) then
		local Weld = Property.Weld
		local CF = Property.CF
		local CF1 = Property.CF1
		local Spring = Property.Spring
		local Position = Property.Position
		local Rotation = Property.Rotation

		local OriginLookVector = OriginCFrame.LookVector
		local CurrentLookVector = CurrentCFrame.LookVector
		-- V4.3.168.8: `OriginLookVector - CurrentLookVector` already returns a
		-- Vector3; the old code wrapped it in Vector3.new(...XYZ...) which was
		-- a pure no-op copy allocating 1 Vector3 per part per frame for no reason.
		local LookVectorAxis = (OriginLookVector - CurrentLookVector)
		-- V4.5.0: clamp a single-frame facing SNAP. When you go idle->walk, the Humanoid AutoRotates to
		-- face the movement direction in ONE frame; respawns/teleports do the same. That spikes
		-- LookVectorAxis (|OriginLook - CurrentLook| is up to 2 for a 180deg flip, ~1.41 for 90deg) and
		-- whips the breast/butt springs SIDEWAYS on the first step of an otherwise straight walk (the
		-- reported bug; reproduced: a 90deg snap gave a +0.79 lateral spring-velocity spike that then
		-- oscillated side-to-side). A REAL turn is gradual - even a fast ~516deg/s spin is only ~0.15/frame
		-- - so cap the magnitude at 0.15: snaps read as a gentle turn, every normal turn is untouched. The
		-- POSITION term already rejects teleports at L2123 (`PositionDistance.Magnitude < WalkSpeed/8`);
		-- rotation had no equivalent guard, which is why straight-line walks still whipped on step one.
		local _lvaSq = LookVectorAxis:Dot(LookVectorAxis)
		if _lvaSq > 0.0225 then LookVectorAxis = LookVectorAxis * (0.15 / math.sqrt(_lvaSq)) end  -- 0.15^2 = 0.0225

		Spring:TimeSkip(ctx.d)
		-- V4.5.1 (side-to-side walk swing, TRUE root cause): the impulse terms above are all WORLD-space, but
		-- the spring velocity is consumed as WELD-LOCAL rotation. Because the breast weld's authored basis maps
		-- the horizontal spring channels to VISUALLY LATERAL motions (roll+yaw) and only the vertical channel to
		-- the front-back nod, any forward/back walk acceleration could ONLY roll the breast sideways (jump=vertical
		-- looked correct; walk start/stop swung sideways). Fix: (1) rotate the impulse into the Base (Torso) frame
		-- so "forward" is always the local Z channel regardless of world facing (no-op at the canonical -Z facing,
		-- so butts/rod tuning is unchanged); (2) for breasts, FOLD the body-forward component into the nod channel
		-- and zero it out of the roll channel, so forward accel nods front-back exactly like a jump does.
		local _imp = CurrentCFrame:VectorToObjectSpace(PositionDistance + LookVectorAxis
			+ ctx._inertiaImpulse
			+ Vector3.new(0, ctx._landImpulse, 0))
		if Part.Name == "Left Breast" or Part.Name == "Right Breast" then
			_imp = Vector3.new(_imp.X, _imp.Y - _imp.Z, 0)  -- -Z fold: nods DOWN on forward movement (sign verified on-device)
		end
		Spring:Impulse(_imp)

		-- V4.3.460: direct offset dispatch via precomputed Property._poX_to / _poY_to /
		-- _poZ_to (and rotation equivalents). Pre-fix this ran two `pairs` loops + 6
		-- string compares per part per frame. Now: 3 hash lookups + 3 multiplies.
		local _poX, _poY, _poZ = Property._poX_to, Property._poY_to, Property._poZ_to
		local _PPM = ctx.PositionPhysicsMultiply
		local _sv = Spring.Velocity
		local posX = _poX and (Position[_poX] * _sv[_poX]) * _PPM or 0
		local posY = _poY and (Position[_poY] * _sv[_poY]) * _PPM or 0
		local posZ = _poZ and (Position[_poZ] * _sv[_poZ]) * _PPM or 0
		local _roX, _roY, _roZ = Property._roX_to, Property._roY_to, Property._roZ_to
		local _rmul = ctx._radMul
		local rotX = _roX and Rotation[_roX] * _sv[_roX] * _rmul or 0
		local rotY = _roY and Rotation[_roY] * _sv[_roY] * _rmul or 0
		local rotZ = _roZ and Rotation[_roZ] * _sv[_roZ] * _rmul or 0

		Weld.C0 = CF * (
			CFrame.new(posX, posY, posZ) *
			CFrame.Angles(rotX, rotY, rotZ)
		)


		-- Overtone spring: high-freq tremor fed from same raw inputs as primary spring
		if Property.Spring2 then
			Property.Spring2:TimeSkip(ctx.d)
			Property.Spring2:Impulse(
				(PositionDistance + LookVectorAxis + ctx._inertiaImpulse) * ctx._overtoneAmp)
			local ov = Property.Spring2.Velocity
			if ov:Dot(ov) > 400 then Property.Spring2.Velocity = ov.Unit * 20 end  -- 20^2=400
			-- V4.5.0 (side-to-side walk bug): the overtone applies a DIRECT world-axis rotation (ov.Z->roll,
			-- ov.Y->yaw) with no body-frame remap, so it leaks the walk's forward/vertical motion into the
			-- breast's SIDE-TO-SIDE axes. For breasts, add only the forward overtone as PITCH (front-back);
			-- other parts keep the full 3-axis tremor.
			if Part.Name == "Left Breast" or Part.Name == "Right Breast" then
				Weld.C0 = Weld.C0 * CFrame.Angles(ov.Z * ctx._radMulOvt, 0, 0)
			else
				Weld.C0 = Weld.C0 * CFrame.Angles(
					ov.X * ctx._radMulOvt,
					ov.Y * ctx._radMulOvt,
					ov.Z * ctx._radMulOvt)
			end
		end

		-- Breathing idle: smooth direct Y offset on Weld.C0 (no spring interference)
		if ctx._breathEnabled and ctx._horizSpeed < 2.0 then
			local _bPhase = (Part.Name == "Left Breast" or Part.Name == "Left Butt") and 0 or 0.3
			Weld.C0 = Weld.C0 * CFrame.new(0, math.sin(ctx._breathAccum * ctx._halfPi + _bPhase) * ctx._breathAmplitude, 0)
		end

		if ctx._physGravity then
			if Part.Name == "Left Breast" then
				Part:AddTag("AppliedPhysics")
				local frame = Base.CFrame

				if Property.BreastsType == 2 or Property.BreastsType == 6 then
					Weld.C1 = CF1 * CFrame.Angles(math.abs(OriginLookVector.Y)*-math.clamp(frame.LookVector.Y,-math.huge,.35) + frame.LookVector.Y*.15, 0, -frame.RightVector.Y)
				elseif Property.BreastsType == 3 then
					Weld.C1 = CF1 * CFrame.Angles((-frame.LookVector.Y*.2)-frame.RightVector.Y, 0, math.abs(OriginLookVector.Y)*math.clamp(frame.LookVector.Y,-math.huge,.35))
				elseif Property.BreastsType == 5 then
					Weld.C1 = CF1 * CFrame.Angles(math.abs(OriginLookVector.Y)*math.clamp(frame.LookVector.Y,-math.huge,.35), 0, frame.RightVector.Y)
				else
					Weld.C1 = CF1 * CFrame.Angles((frame.LookVector.Y*.2)+frame.RightVector.Y, 0, math.abs(OriginLookVector.Y)*-math.clamp(frame.LookVector.Y,-math.huge,.35))
				end

			elseif Part.Name == "Right Breast" then
				Part:AddTag("AppliedPhysics")
				local frame = Base.CFrame

				if Property.BreastsType == 2 or Property.BreastsType == 6 then
					Weld.C1 = CF1 * CFrame.Angles(math.abs(OriginLookVector.Y)*-math.clamp(frame.LookVector.Y,-math.huge,.35) - frame.LookVector.Y*.15, 0, -frame.RightVector.Y)
				elseif Property.BreastsType == 3 then
					Weld.C1 = CF1 * CFrame.Angles((frame.LookVector.Y*.2)-frame.RightVector.Y, 0, math.abs(OriginLookVector.Y)*math.clamp(frame.LookVector.Y,-math.huge,.35))
				elseif Property.BreastsType == 5 then
					Weld.C1 = CF1 * CFrame.Angles(math.abs(OriginLookVector.Y)*math.clamp(frame.LookVector.Y,-math.huge,.35), 0, frame.RightVector.Y)
				else
					Weld.C1 = CF1 * CFrame.Angles((-frame.LookVector.Y*.2)+frame.RightVector.Y, 0, math.abs(OriginLookVector.Y)*-math.clamp(frame.LookVector.Y,-math.huge,.35))
				end

			elseif Part.Name == "Breasts Shirt" or Part.Name == "Breasts Pants" then
				local frame = Base.CFrame
				Weld.C1 = CF1 * CFrame.Angles(frame.RightVector.Y, 0, math.abs(OriginLookVector.Y)*-math.clamp(frame.LookVector.Y,-math.huge,.42))
			end

		elseif Part:HasTag("AppliedPhysics") then
			if Part.Name == "Left Breast" or Part.Name == "Right Breast" or Part.Name == "Breasts Shirt" or Part.Name == "Breasts Pants" then
				Weld.C1 = CF1
				Part:RemoveTag("AppliedPhysics")
			end
		end
	end
	Property.OriginCFrame = CurrentCFrame
end

