local function _svAt(px) _pS = math.clamp((px.X - _sv.AbsolutePosition.X) / math.max(1, _sv.AbsoluteSize.X), 0, 1); _pV = 1 - math.clamp((px.Y - _sv.AbsolutePosition.Y) / math.max(1, _sv.AbsoluteSize.Y), 0, 1); _pRefresh() end
