-- Close ONLY on a click genuinely OUTSIDE the card. This does NOT rely on Active sinking (which keeps leaking on
-- this executor): even if a click on the card reaches the dim, the bounds check keeps the picker open. io.Position
-- and AbsolutePosition are both raw (IgnoreGuiInset) screen coords, so they line up.
_pDim.InputBegan:Connect(function(io)
	if io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch then
		local p, cp, cs = io.Position, _pCard.AbsolutePosition, _pCard.AbsoluteSize
		if p.X < cp.X or p.X > cp.X + cs.X or p.Y < cp.Y or p.Y > cp.Y + cs.Y then pickerScreen.Enabled = false end
	end
end)
end  -- close the picker do-block

-- ===== generic confirm/prompt modal (reused). buttons = { {text=, kind="primary"?, onClick=} , ... }; opt. text field. =====
-- Wrapped in `do…end`: the _m* element locals are used ONLY by showModal + the InputBegan closure, so scoping them
-- makes them upvalues (freed from the main chunk) - reclaims registers for multi-panel (Luau 200-local cap). BUT
-- `modalScreen` IS referenced OUTSIDE (openHome's ownGui set + the DESTROY teardown), so it must be forward-declared,
-- not scoped into the block - otherwise it reads nil outside and `{ [modalScreen]=true }` throws "table index is nil".
local showModal, modalScreen  -- forward: showModal (dialogs/Bundles), modalScreen (openHome ownGui + DESTROY)
do
modalScreen = new("ScreenGui", { Name = "RoClothesModal", ResetOnSpawn = false, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, IgnoreGuiInset = true, DisplayOrder = 1003, Enabled = false, Parent = PlayerGui })
GUIObject.ModalScreen = modalScreen  -- V4.5.17: creation-site stash so BREAKER.Destroying can destroy it by reference (see L~1918)
local _mDim = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Parent = modalScreen })
local _mCard = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(300, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = T.bg, BorderSizePixel = 0, Active = true, Parent = modalScreen }); corner(_mCard, 14); stroke(_mCard, T.line, 1); pad(_mCard, 16, 16, 16, 16); vlist(_mCard, 12)
local _mTitle = lbl({ Size = UDim2.new(1, 0, 0, 20), Text = "", Font = FONTB, TextSize = 16, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 1, Parent = _mCard })
local _mMsg = lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = "", TextColor3 = T.txt2, TextSize = 12.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 2, Parent = _mCard })
local _mField = new("TextBox", { Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = T.bg2, BorderSizePixel = 0, Text = "", PlaceholderColor3 = T.txt3, Font = FONT, TextColor3 = T.txt, TextSize = 13, ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left, Visible = false, LayoutOrder = 3, Parent = _mCard }); corner(_mField, 8); stroke(_mField, T.line, 1); pad(_mField, 10, 10, 0, 0)
local _mBtns = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 32), LayoutOrder = 4, Parent = _mCard })
new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Right, Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = _mBtns })
function showModal(title, message, buttons, withField, fieldDefault)
	_mTitle.Text = title or ""
	_mMsg.Text = message or ""; _mMsg.Visible = (message ~= nil and message ~= "")
	_mField.Visible = withField or false; if withField then _mField.Text = fieldDefault or "" end
	for _, c in ipairs(_mBtns:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
	for i, b in ipairs(buttons or {}) do
		local prim = b.kind == "primary"
		local btn = new("TextButton", { AutoButtonColor = false, Text = b.text or "OK", Font = FONTB, TextColor3 = prim and T.txt or T.txt2, TextSize = 13, BackgroundColor3 = prim and T.accentD or T.card, BorderSizePixel = 0, AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 1, 0), LayoutOrder = i, Parent = _mBtns }); corner(btn, 8); pad(btn, 14, 14, 0, 0); UI.hoverFill(btn, prim and T.accentD or T.card, prim and T.accent or T.cardHi)
		if not prim then stroke(btn, T.line, 1) end  -- prim = flat accent fill; a gradient on this text button would tint its own TEXT (the reddish-caption bug)
		btn.MouseButton1Click:Connect(function() modalScreen.Enabled = false; if b.onClick then b.onClick(_mField.Text) end end)
	end
	modalScreen.Enabled = true
end
_mDim.InputBegan:Connect(function(io)  -- close only on a click OUTSIDE the card (bounds-checked, doesn't rely on Active sinking)
	if io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch then
		local p, cp, cs = io.Position, _mCard.AbsolutePosition, _mCard.AbsoluteSize
		if p.X < cp.X or p.X > cp.X + cs.X or p.Y < cp.Y or p.Y > cp.Y + cs.Y then modalScreen.Enabled = false end
	end
end)
end  -- close the modal do-block
-- NOTE (merge): the Clothes grid rebuild is stashed on UI._renderClothesGrid (assigned by PAGES.clothes) so
-- krulTypeDialog - defined below, before PAGES - can re-render the grid after a Shirt/Pants pick. Using the
-- existing UI upvalue table (not a fresh main-chunk local) keeps _buildV3GUI under Luau's 200-local cap.
local function saveOutfitDialog()
	-- WIRED (merge): mirrors V2 Modals.saveOutfit - the modal field is the name source (showModal passes _mField.Text
	-- into each button's onClick); empty -> "Outfit_HHMM_mmdd" default (V2 L5134-5144). Save Private -> saveOutfit(name,false);
	-- Publish -> saveOutfit(name,true). V3's generic modal closes on click, so progress/result is surfaced via a toast.
	local function _save(public, name)
		name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
		if name == "" then name = "Outfit_" .. os.date("%H%M_%m%d") end
		if not (System and System.saveOutfit) then toast("Save Outfit", "Save unavailable on this executor.", "warn"); return end
		toast("Save Outfit", public and "Saving + publishing…" or "Saving…")
		task.spawn(function()
			local finalName, msg = System.saveOutfit(name, public)
			toast("Save Outfit", tostring(msg or (finalName and ("Saved '" .. finalName .. "'")) or "failed"), "ok")
		end)
	end
	showModal("Save Outfit", "Capture your whole look - clothes, physics, size and adjustments.", { { text = "Save Private", onClick = function(name) _save(false, name) end }, { text = "Publish", kind = "primary", onClick = function(name) _save(true, name) end }, { text = "Cancel" } }, true, "Outfit_" .. os.date("%H%M_%m%d"))
end
local function exportBundleDialog()
	-- WIRED (merge): mirrors V2 Modals.bundleExport (L5202) - exports the currently APPLIED bundle. Copy ->
	-- System.exportBundle(nil,"clipboard") (one step); Submit -> System.exportBundle(nil,"community") behind a 2-step
	-- confirm (V3's generic modal closes on click, so the confirm is a nested modal rather than V2's in-modal re-arm).
	-- Results surface via toast (the generic modal has no status line). exportBundle(name,mode): nil name => active bundle.
	local function _copy()
		local msg = (System and System.exportBundle and System.exportBundle(nil, "clipboard")) or "Copied."
		toast("Export Bundle", tostring(msg), "ok")
	end
	local function _submit()
		toast("Export Bundle", "Submitting…")
		task.spawn(function()
			local msg = (System and System.exportBundle and System.exportBundle(nil, "community")) or "Submitted."
			toast("Export Bundle", tostring(msg), "ok")
		end)
	end
	showModal("Export Bundle", "Exports the bundle you currently have applied. Copy a shareable snippet, or submit it to the community review queue.", {
		{ text = "Copy", onClick = _copy },
		{ text = "Submit", kind = "primary", onClick = function()
			showModal("Submit to Community?", "This posts your applied bundle to the community review queue.", {
				{ text = "Confirm Submit", kind = "primary", onClick = _submit },
				{ text = "Cancel" },
			})
		end },
		{ text = "Close" },
	})
end
-- stashed on the UI table (not a main-chunk local) to stay under Luau's 200-local cap in _buildV3GUI.
UI._saveBundleDialog = function()
	-- WIRED (merge): mirrors V2 Modals.saveBundle (L5168) - the destination modal for freshly imported bundles
	-- (System._pendingImports). Save Private -> System.finalizeImportPrivate() (writes to disk); Community ->
	-- System.finalizeImportCommunity() (writes + POSTs for review); Cancel -> System.cancelImport() (discards).
	-- Results surface via toast + a Bundles re-render (UI._renderBundles).
	local pending = (System and System._pendingImports) or {}
	local n = #pending
	local subtitle = (n == 1 and ('Imported "' .. tostring(pending[1] and pending[1].name) .. '" - where to save?'))
		or (n > 1 and ('Imported ' .. n .. ' bundles - where to save?'))
		or "Imported bundle - where do you want to save it?"
	showModal("Imported bundle", subtitle, {
		{ text = "Save Private", kind = "primary", onClick = function()
			local msg = (System and System.finalizeImportPrivate and System.finalizeImportPrivate()) or "Saved."
			toast("Import", tostring(msg), "ok")
			if UI._renderBundles then UI._renderBundles() end
		end },
		{ text = "Community", onClick = function()
			toast("Import", "Submitting…")
			task.spawn(function()
				local msg = (System and System.finalizeImportCommunity and System.finalizeImportCommunity()) or "Submitted."
				toast("Import", tostring(msg), "ok")
				if UI._renderBundles then UI._renderBundles() end
			end)
		end },
		{ text = "Cancel", onClick = function()
			if System and System.cancelImport then System.cancelImport() end
		end },
	})
end
-- stashed on the UI table (not a main-chunk local) to stay under Luau's 200-local cap in _buildV3GUI.
UI._manageDeletedDialog = function()
	-- WIRED (merge): mirrors V2 Modals.manageDeleted (L5264) - the real DeletedBundles list. Built as its own modal
	-- ScreenGui (V3's generic showModal can't host a dynamic per-row list). List from System.getDeletedBundles(); each
	-- row Restore -> System.restoreBundle(name); Refresh -> System.redownloadBundles(); Clear All (2-step) ->
	-- System.clearDeletedBundles(). Every action re-reads the list + re-renders the Bundles grid (UI._renderBundles).
	local scr = new("ScreenGui", { Name = "RoClothesManageDeleted", ResetOnSpawn = false, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, IgnoreGuiInset = true, DisplayOrder = 1004, Parent = PlayerGui })
	local function closeMd() scr:Destroy() end
	local dim = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Parent = scr })
	local card = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(360, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = T.bg, BorderSizePixel = 0, Active = true, Parent = scr }); corner(card, 14); stroke(card, T.line, 1); pad(card, 16, 16, 16, 16); vlist(card, 12)
	lbl({ Size = UDim2.new(1, 0, 0, 20), Text = "Hidden / Deleted Bundles", Font = FONTB, TextSize = 16, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 1, Parent = card })
	lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = "Deleted bundles are blocklisted. Restore brings one back; Clear All wipes the whole blocklist.", TextColor3 = T.txt2, TextSize = 12.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 2, Parent = card })
	local listWrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3, Parent = card }); vlist(listWrap, 6)
	local function _syncBundles() if UI._renderBundles then UI._renderBundles() end end
	local rebuild
	rebuild = function()
		for _, c in ipairs(listWrap:GetChildren()) do if c:IsA("GuiObject") then c:Destroy() end end
		local names = (System and System.getDeletedBundles and System.getDeletedBundles()) or {}
		if #names == 0 then
			lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = "No hidden bundles. Delete a bundle to see it here.", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = listWrap })
			return
		end
		for i, nn in ipairs(names) do
			local nm = nn
			local row = new("Frame", { BackgroundColor3 = T.card, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 34), LayoutOrder = i, Parent = listWrap }); corner(row, 8); stroke(row, T.lineSoft, 1); pad(row, 10, 10, 0, 0)
			lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(1, -84, 1, 0), Text = nm, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = row })
			local rb = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(72, 24), BackgroundColor3 = T.accentD, BorderSizePixel = 0, AutoButtonColor = false, Font = FONTB, Text = "Restore", TextColor3 = T.txt, TextSize = 12, Parent = row }); corner(rb, 7)
			rb.MouseButton1Click:Connect(function()
				if System and System.restoreBundle then System.restoreBundle(nm) end
				_syncBundles(); rebuild()
			end)
		end
	end
	rebuild()
	local foot = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 32), LayoutOrder = 4, Parent = card })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Right, Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = foot })
	local function mkBtn(text, order, primary)
		local b = new("TextButton", { AutoButtonColor = false, Text = text, Font = FONTB, TextColor3 = primary and T.txt or T.txt2, TextSize = 13, BackgroundColor3 = primary and T.accentD or T.card, BorderSizePixel = 0, AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 1, 0), LayoutOrder = order, Parent = foot }); corner(b, 8); pad(b, 14, 14, 0, 0)
		if not primary then stroke(b, T.line, 1) end
		return b
	end
	local refreshBtn = mkBtn("Refresh", 1, false)
	refreshBtn.MouseButton1Click:Connect(function()
		if System and System.redownloadBundles then System.redownloadBundles() end
		_syncBundles(); rebuild()
	end)
	local clearArmed = false
	local clearBtn = mkBtn("Clear All", 2, false)
	clearBtn.MouseButton1Click:Connect(function()
		if not clearArmed then clearArmed = true; clearBtn.Text = "Click again"; task.delay(3, function() if clearArmed and clearBtn and clearBtn.Parent then clearArmed = false; clearBtn.Text = "Clear All" end end); return end
		clearArmed = false; clearBtn.Text = "Clear All"
		if System and System.clearDeletedBundles then System.clearDeletedBundles() end
		_syncBundles(); rebuild()
	end)
	local closeBtn = mkBtn("Close", 3, true)
	closeBtn.MouseButton1Click:Connect(closeMd)
	dim.InputBegan:Connect(function(io)
		if io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch then
			local p, cp, cs = io.Position, card.AbsolutePosition, card.AbsoluteSize
			if p.X < cp.X or p.X > cp.X + cs.X or p.Y < cp.Y or p.Y > cp.Y + cs.Y then closeMd() end
		end
	end)
end
UI._executorGuide = function()
	-- Executor compatibility guide. Verdicts from WEAO sUNC data (2026-07) cross-checked with RoClothes testing.
	-- Recommended = full support; Partial = works with the noted caveat; Not verified = no sUNC data on file.
	local REC = { "Volt", "Wave", "Seliware", "Potassium", "MacSploit", "Cosmic", "Real", "Madium", "Opiumware", "Synapse Z", "Velocity", "SirHurt", "Volcano" }
	local PARTIAL = {
		{ "Delta", "Mesh bodies render only partially" },
		{ "Codex", "No image loading - clothing textures and news images won't show" },
		{ "Solara", "Basics only (external, ~47% sUNC) - advanced physics may not work" },
		{ "Xeno", "Basics only (~41% sUNC) - advanced features limited" },
	}
	local function verdictOf(nm)
		local low = tostring(nm or ""):lower()
		if low == "" or low == "unknown" then return nil end
		for _, r in ipairs(REC) do if low:find(r:lower(), 1, true) then return "full", r end end
		for _, p in ipairs(PARTIAL) do if low:find(p[1]:lower(), 1, true) then return "partial", p[1], p[2] end end
		return "other"
	end
	local scr = new("ScreenGui", { Name = "RoClothesExecGuide", ResetOnSpawn = false, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, IgnoreGuiInset = true, DisplayOrder = 1005, Parent = PlayerGui })
	local _egVpConn
	local function disconnectEGViewport()
		if _egVpConn then pcall(function() _egVpConn:Disconnect() end); _egVpConn = nil end
	end
	local function closeEG() disconnectEGViewport(); scr:Destroy() end
	scr.Destroying:Connect(disconnectEGViewport)
	local dim = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Parent = scr })
	local card = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(400, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = T.bg, BorderSizePixel = 0, Active = true, Parent = scr }); corner(card, 14); stroke(card, T.line, 1); pad(card, 16, 16, 16, 16); vlist(card, 10)
	new("UISizeConstraint", { MaxSize = Vector2.new(400, 560), Parent = card })
	-- auto-fit: scale the fixed 400-wide card to the viewport so it never overflows on mobile / small windows (every UI resizes to screen)
	local egScale = new("UIScale", { Scale = 1, Parent = card })
	local function fitEG()
		local cam = workspace.CurrentCamera; local vw = (cam and cam.ViewportSize.X) or 800; local vh = (cam and cam.ViewportSize.Y) or 600
		local ch = card.AbsoluteSize.Y / math.max(egScale.Scale, 0.05); if ch < 120 then ch = 560 end  -- recover the LOGICAL height (AbsoluteSize is post-UIScale)
		egScale.Scale = math.max(0.4, math.min((vw - 28) / 400, (vh - 28) / ch, 1))
	end
	task.defer(fitEG); task.delay(0.12, fitEG)  -- refit once AutomaticSize.Y settles
	-- V4.5.24 Fix: self-disconnecting ViewportSize listener (was leaking a permanent connection
	-- every time the executor guide opened).
	-- V4.5.24 (r2) Fix: restore the pcall wrapper the other 4 viewport sites kept - a nil
	-- CurrentCamera frame here would throw and abort the whole executor-guide builder.
	pcall(function()
		_egVpConn = workspace.CurrentCamera and workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
			if not scr.Parent then disconnectEGViewport(); return end
			fitEG()
		end)
	end)
	lbl({ Size = UDim2.new(1, 0, 0, 22), Text = "Executor Compatibility", Font = FONTB, TextSize = 17, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 1, Parent = card })
	lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = "Which executors run RoClothes:Krul well. Pick a Recommended one for the smoothest experience.", TextColor3 = T.txt2, TextSize = 12.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 2, Parent = card })
	do
		local v, matched, reason = verdictOf(_execName)
		local col = (v == "full" and Color3.fromRGB(40, 140, 80)) or (v == "partial" and Color3.fromRGB(170, 130, 35)) or Color3.fromRGB(70, 72, 92)
		local msg
		if v == "full" then msg = "You're on " .. matched .. " - fully supported."
		elseif v == "partial" then msg = "You're on " .. matched .. " - partial: " .. reason .. "."
		elseif v == "other" then msg = "You're on " .. tostring(_execName) .. " - not in our verified list yet."
		else msg = "Executor not detected." end
		local yb = new("Frame", { BackgroundColor3 = col, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3, Parent = card }); corner(yb, 9); pad(yb, 12, 12, 9, 9)
		lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = msg, Font = FONTB, TextColor3 = Color3.fromRGB(255, 255, 255), TextSize = 12.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = yb })
	end
	local sf = new("ScrollingFrame", { BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 300), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 4, ScrollBarImageColor3 = T.line, LayoutOrder = 4, Parent = card }); vlist(sf, 8)
	local function sectionHeader(txt, col, order)
		local hh = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 20), LayoutOrder = order, Parent = sf })
		local dot = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(10, 10), BackgroundColor3 = col, BorderSizePixel = 0, Parent = hh }); corner(dot, 5)
		lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 18, 0.5, 0), Size = UDim2.new(1, -18, 1, 0), Text = txt, Font = FONTB, TextSize = 14, TextColor3 = col, TextXAlignment = Enum.TextXAlignment.Left, Parent = hh })
	end
	sectionHeader("Recommended - full support", Color3.fromRGB(80, 200, 120), 1)
	do
		local wrap = new("Frame", { BackgroundColor3 = T.card, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = sf }); corner(wrap, 9); stroke(wrap, T.lineSoft, 1); pad(wrap, 12, 12, 10, 10)
		lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = table.concat(REC, "   -   "), TextColor3 = T.txt, TextSize = 13, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = wrap })
	end
	sectionHeader("Partial - works with limits", Color3.fromRGB(230, 190, 70), 3)
	for i, p in ipairs(PARTIAL) do
		local row = new("Frame", { BackgroundColor3 = T.card, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3 + i, Parent = sf }); corner(row, 9); stroke(row, T.lineSoft, 1); pad(row, 12, 12, 8, 8); vlist(row, 2)
		lbl({ Size = UDim2.new(1, 0, 0, 16), Text = p[1], Font = FONTB, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, Parent = row })
		lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = p[2], TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = row })
	end
	lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = "Source: weao.xyz sUNC results + RoClothes testing.", TextColor3 = T.txt3, TextSize = 10.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 5, Parent = card })
	local closeBtn = new("TextButton", { AutoButtonColor = false, Text = "Close", Font = FONTB, TextColor3 = T.txt, TextSize = 13, BackgroundColor3 = T.accentD, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 34), LayoutOrder = 6, Parent = card }); corner(closeBtn, 9)
	closeBtn.MouseButton1Click:Connect(closeEG)
	dim.InputBegan:Connect(function(io)
		if io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch then
			local pp, cp, cs = io.Position, card.AbsolutePosition, card.AbsoluteSize
			if pp.X < cp.X or pp.X > cp.X + cs.X or pp.Y < cp.Y or pp.Y > cp.Y + cs.Y then closeEG() end
		end
	end)
end
local function krulTypeDialog(clothName)
	-- WIRED (merge): mirrors V2 Modals.krulType - Shirt/Pants -> System.setClothType(clothName,kind); Cancel ->
	-- System.clearClothPending(). Each choice then rebuilds the Clothes grid via the forward-declared renderer.
	showModal('Is "' .. clothName .. '" a shirt or pants?', nil, {
		{ text = "Shirt", kind = "primary", onClick = function() if System and System.setClothType then System.setClothType(clothName, "Shirt") end; if UI._renderClothesGrid then UI._renderClothesGrid() end end },
		{ text = "Pants", kind = "primary", onClick = function() if System and System.setClothType then System.setClothType(clothName, "Pants") end; if UI._renderClothesGrid then UI._renderClothesGrid() end end },
		{ text = "Cancel", onClick = function() if System and System.clearClothPending then System.clearClothPending() end; if UI._renderClothesGrid then UI._renderClothesGrid() end end },
	})
end

-- ===== extra primitives used by the 1-to-1 pages (cycler / colour swatch / text field / keybind) =====
function UI.cyc(parent, label, values, order, onChange, initVal)
	local key = _curPage .. "\1c:" .. (label or "")
	local r = rowShell(parent, 40, order)
	lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(1, -114, 1, 0), Text = label or "", TextXAlignment = Enum.TextXAlignment.Left, Parent = r })
	local i = 1
	local seed = initVal; if seed == nil then seed = S[key] end  -- explicit initial value wins, else the persisted one
	if seed ~= nil then for idx, val in ipairs(values) do if val == seed then i = idx; break end end end
	local cur = lbl({ AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -16, 0.5, 0), Size = UDim2.new(0, 104, 1, 0), Text = tostring(values[i]), Font = FONTB, TextColor3 = T.accent, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Right, TextTruncate = Enum.TextTruncate.AtEnd, Parent = r }); UI.breathe(cur, { TextColor3 = T.accent:Lerp(Color3.fromRGB(255, 255, 255), 0.25) }, 2.6)  -- ambient value glow
	-- hit area confined to the value (right), not the whole row
	local hit = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0, 124, 1, 0), BackgroundTransparency = 1, AutoButtonColor = false, Text = "", Parent = r })
	hit.MouseButton1Click:Connect(function() i = i % #values + 1; cur.Text = tostring(values[i]); UI.pop(cur); S[key] = values[i]; if onChange then onChange(values[i], i) end end)
	return r
end
function UI.swatch(parent, name, color, order, onPick)
	local r = rowShell(parent, 42, order)
	local chip = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(26, 26), BackgroundColor3 = color or T.accent, BorderSizePixel = 0, Parent = r }); corner(chip, 7); stroke(chip, T.line, 1)
	lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 36, 0.5, 0), Size = UDim2.new(1, -140, 1, 0), Text = name or "", TextXAlignment = Enum.TextXAlignment.Left, Parent = r })
	local hexL = lbl({ AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.new(0, 92, 1, 0), Text = "", Font = FONTB, TextColor3 = T.txt2, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Right, Parent = r })
	local function setHex(c) hexL.Text = string.format("#%02X%02X%02X", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)) end
	setHex(color or T.accent)
	-- tapping the chip (left) opens the HSV picker; on apply it recolours the chip + hex and fires onPick.
	-- hit area confined to the colour chip, not the whole row
	local hit = new("TextButton", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(0, 40, 1, 0), BackgroundTransparency = 1, AutoButtonColor = false, Text = "", Parent = r })
	hit.MouseButton1Click:Connect(function() openColorPicker(chip.BackgroundColor3, function(c) chip.BackgroundColor3 = c; setHex(c); if onPick then onPick(c) end end) end)
	return r, chip
end
function UI.field(parent, label, value, order, editable, onCommit, placeholder, persistDraft)
	-- `placeholder` (optional): a HINT that shows only when the box is empty; distinct from `value` (the
	-- box's actual seeded text). When omitted, `value` doubles as the placeholder (legacy behaviour). Pass
	-- an explicit placeholder + value="" for a search box so the hint never becomes real, selectable text.
	local r = rowShell(parent, 40, order)
	lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(0.46, -6, 1, 0), Text = label or "", TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = r })
	if editable then
		local key = _curPage .. "\1f:" .. (label or "")
		local draft = persistDraft and S[key]
		local box = new("TextBox", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -10, 0.5, 0), Size = UDim2.new(0.54, -6, 0, 26), BackgroundColor3 = T.bg, BorderSizePixel = 0, Text = draft or value or "", PlaceholderText = placeholder or value or "", PlaceholderColor3 = T.txt3, Font = FONT, TextColor3 = T.txt, TextSize = 12, ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left, Parent = r }); corner(box, 7); local bs = stroke(box, T.line, 1); pad(box, 8, 8, 0, 0)
		box.Focused:Connect(function() tween(bs, 0.2, { Color = T.accent }) end)
		box.FocusLost:Connect(function() tween(bs, 0.2, { Color = T.line }); if persistDraft then S[key] = box.Text end; if onCommit then onCommit(box.Text) end end)
		return r, box
	end
	lbl({ AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.new(0.54, -6, 1, 0), Text = tostring(value or ""), Font = FONTB, TextColor3 = T.accent, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Right, TextTruncate = Enum.TextTruncate.AtEnd, Parent = r })
	return r
end
function UI.hint(parent, text, order)
	local f = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order or 1, Parent = parent })
	lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = text or "", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = f })
	return f
end
function UI.seg(parent, opts, order, onSwitch, initIdx, ht, counts, label)  -- counts (optional): a parallel array of numbers -> a small count badge on each segment (Bundles). label (optional): a caption ABOVE the bar so a bare segmented control says what it controls (settings) - matches the labelled toggle/cyc rows; omitted = full-width unlabelled bar (panel tabs).
	local n, G = #opts, 3
	local barH = ht or 32
	-- optional label ABOVE the bar (designparser consistency/clarity: every OTHER control row is labelled; a bare seg wasn't)
	local host, yOff = parent, 0
	if label and label ~= "" then
		local wrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, barH + 18), LayoutOrder = order or 1, Parent = parent })
		lbl({ Position = UDim2.new(0, 1, 0, 0), Size = UDim2.new(1, -1, 0, 14), Text = label, Font = FONTB, TextColor3 = T.txt2, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, Parent = wrap })
		host, yOff = wrap, 18
	end
	local r = new("Frame", { BackgroundColor3 = T.card, BorderSizePixel = 0, Position = UDim2.new(0, 0, 0, yOff), Size = UDim2.new(1, 0, 0, barH), LayoutOrder = order or 1, Parent = host }); corner(r, 8); pad(r, 3, 3, 3, 3)
	-- n equal segments placed by scale + a gap-offset (scale-safe under the panel UIScale; no UIListLayout needed), so a
	-- single accent indicator can SLIDE between them instead of each pill fading in place.
	local function segPos(i) return UDim2.new((i - 1) / n, (i - 1) * G / n, 0, 0) end
	local segSize = UDim2.new(1 / n, -G * (n - 1) / n, 1, 0)
	local ind = new("Frame", { BackgroundColor3 = T.accentD, BorderSizePixel = 0, Position = segPos(initIdx or 1), Size = segSize, Parent = r }); corner(ind, 6); new("UIGradient", { Rotation = 25, Color = ColorSequence.new(T.accent, T.accentD), Parent = ind })
	local pills = {}
	local function hl(idx, animate)
		if animate then tween(ind, 0.28, { Position = segPos(idx) }, QUINT) else ind.Position = segPos(idx) end
		for i, p in ipairs(pills) do tween(p, 0.2, { TextColor3 = i == idx and T.txt or T.txt2 }) end
	end
	for i, o in ipairs(opts) do
		local btn = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundTransparency = 1, Position = segPos(i), Size = segSize, Parent = r })  -- transparent; the sliding indicator marks the active one
		local pl = lbl({ Size = UDim2.fromScale(1, 1), Text = tostring(o), TextColor3 = T.txt2, Font = FONTB, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.AtEnd, Parent = btn })
		pills[i] = pl
		if counts and counts[i] then  -- count badge in the segment's own top-right (doesn't shift the centred label; the 3px gap keeps it off the neighbour)
			local bd = new("Frame", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -2, 0, 2), Size = UDim2.fromOffset(16, 13), BackgroundColor3 = T.bg, BackgroundTransparency = 0.1, BorderSizePixel = 0, ZIndex = 3, Parent = btn }); corner(bd, 6)
			lbl({ Size = UDim2.fromScale(1, 1), Text = tostring(counts[i]), Font = FONTB, TextColor3 = T.txt, TextSize = 9, TextXAlignment = Enum.TextXAlignment.Center, Parent = bd })
		end
		btn.MouseButton1Click:Connect(function() hl(i, true); if onSwitch then onSwitch(o, i) end end)
	end
	hl(initIdx or 1, false)
	return yOff > 0 and host or r  -- labelled: return the wrapper (label + bar) so P()'s hover-preview covers both
end
function UI.keybind(parent, label, current, order, onSet)  -- a row that captures the NEXT key press to rebind (Escape cancels). Stores the KeyCode NAME (string).
	local r = rowShell(parent, 40, order)
	lbl({ Size = UDim2.new(1, -108, 1, 0), Text = label, Font = FONTB, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, Parent = r })
	local key = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.5, 0), Size = UDim2.fromOffset(92, 26), BackgroundColor3 = T.bg, AutoButtonColor = false, Text = current or "None", Font = FONTB, TextColor3 = T.accent, TextSize = 12, TextTruncate = Enum.TextTruncate.AtEnd, Parent = r }); corner(key, 7); stroke(key, T.line, 1)
	local conn  -- the live capture connection; dropped on rebind-done, on re-click, AND on row teardown (fillSettings rebuilds these rows live, e.g. if you click another setting mid-capture)
	local function stopCapture() if conn then conn:Disconnect(); conn = nil end end
	r.Destroying:Connect(stopCapture)   -- row destroyed mid-capture -> drop the dangling InputBegan conn (fillSettings rebuilds these rows live)
	key.MouseButton1Click:Connect(function()
		if conn then return end   -- already capturing (double-click) -> ignore, don't stack a 2nd connection
		key.Text = "Press a key…"
		conn = UserInputService.InputBegan:Connect(function(io, gpe)
			if gpe or io.UserInputType ~= Enum.UserInputType.Keyboard then return end   -- ignore typing in a field (gpe) + non-keys, so WASD / search text can't hijack the bind
			local name = io.KeyCode.Name
			stopCapture()
			if name == "Escape" then name = current or "None" end   -- Escape cancels, keep the old bind
			key.Text = name; if onSet then onSet(name) end
		end)
	end)
	return r
end
function UI.tiles(parent, items, order, cellH)
	local grid = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order or 1, Parent = parent })
	new("UIGridLayout", { CellSize = UDim2.new(1 / 3, -6, 0, cellH or 50), CellPadding = UDim2.fromOffset(8, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = grid })  -- 3-up (was 2-up) so more assets per row; height 50 (was 64) trims the dead space
	local cells = {}
	for i, it in ipairs(items) do
		local c = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = T.card, BorderSizePixel = 0, LayoutOrder = i, Parent = grid }); corner(c, 9); local s = stroke(c, T.lineSoft, 1); local csc = new("UIScale", { Parent = c }); pad(c, 11, 11, 8, 8)
		lbl({ Size = UDim2.new(1, 0, 0, 18), Text = it.name or "", Font = FONTB, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = c })
		if it.sub then lbl({ Position = UDim2.new(0, 0, 0, 20), Size = UDim2.new(1, 0, 0, 14), Text = it.sub, TextColor3 = T.txt3, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = c }) end
		if it.badge then
			local b = new("Frame", { AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -8, 1, -8), AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 16), BackgroundColor3 = it.badgeColor or T.good, BorderSizePixel = 0, Parent = c }); corner(b, 5); pad(b, 6, 6, 0, 0)
			lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 1, 0), Text = it.badge, Font = FONTB, TextColor3 = T.bg, TextSize = 9.5, Parent = b })
		end
		c.MouseEnter:Connect(function() tween(s, 0.2, { Color = T.line }); tween(csc, 0.18, { Scale = 1.035 }, QUINT) end)  -- hover-lift
		c.MouseLeave:Connect(function() tween(s, 0.2, { Color = T.lineSoft }); tween(csc, 0.18, { Scale = 1 }, QUINT) end)
		if it.onClick then c.MouseButton1Click:Connect(function() csc.Scale = 0.96; tween(csc, 0.35, { Scale = 1.035 }, BACK); it.onClick() end) end  -- tap-pop
		cells[i] = { btn = c, cat = it.cat }
	end
	-- setFilter(want): show only tiles whose .cat == want (nil want = show all). UIGridLayout skips hidden cells.
	local function setFilter(want) for _, e in ipairs(cells) do e.btn.Visible = (want == nil or e.cat == want) end end
	return grid, setFilter
end
-- tappable body-map figure (Body tab): toggle each part's first-person visibility.
local function bodyMap(parent, order, onTail)
	-- The "purple box": tap a body part to hide it in first-person. The FIGURE sits on the LEFT; the caller drops
	-- first-person controls into the returned right-hand host. Returns (card, rightHost).
	local card = new("Frame", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 178), LayoutOrder = order, Parent = parent }); corner(card, 12); stroke(card, T.lineSoft, 1)
	new("UIGradient", { Rotation = 55, Color = ColorSequence.new(Color3.fromRGB(46, 35, 62), Color3.fromRGB(23, 21, 29)), Parent = card })
	-- left figure zone (fixed width so the right host gets the rest of the box)
	local figZone = new("Frame", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 6, 0.5, 0), Size = UDim2.fromOffset(124, 178), Parent = card })
	local fig = new("Frame", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.fromOffset(92, 150), Parent = figZone })
	new("Frame", { BackgroundColor3 = Color3.fromRGB(0, 0, 0), BackgroundTransparency = 0.74, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 1, -3), Size = UDim2.fromOffset(74, 10), Parent = fig }); -- soft ground shadow under the feet (drawn first, behind the parts)
	-- [V3 MERGE FIX] figure faces the viewer, so figure-LEFT = character RIGHT (mirror). Each region taps the real
	-- LocalTransparency[part] (LOCAL-only per-part FP hide): pink(shown)=SHOWN in first person (render loop disables
	-- the FP distance-fade), dim=hidden. Seeded from real PD via getLocalTransparency. Mirrors V2 L3644-3666.
	local _bmPDKey = { Hat = "Hat", Head = "Head", Torso = "Torso", ["Arm L"] = "Right Arm", ["Arm R"] = "Left Arm", ["Leg L"] = "Right Leg", ["Leg R"] = "Left Leg" }
	local function region(name, x, y, w, hh, rad)
		local _pdKey = _bmPDKey[name]
		local shown = true
		if _pdKey then
			local _lt = System and System.getLocalTransparency and System.getLocalTransparency()
			shown = (type(_lt) == "table" and _lt[_pdKey] == true)
		end
		local p = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = T.accent, BackgroundTransparency = shown and 0.26 or 0.86, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, x, 0.5, y), Size = UDim2.fromOffset(w, hh), Parent = fig }); corner(p, rad or 5)
		local s = stroke(p, Color3.fromRGB(255, 255, 255), 1); s.Transparency = shown and 0.8 or 0.94  -- crisp light edge so the parts read as distinct
		p.MouseEnter:Connect(function() if shown then tween(p, 0.15, { BackgroundTransparency = 0.1 }) end end)
		p.MouseLeave:Connect(function() tween(p, 0.15, { BackgroundTransparency = shown and 0.26 or 0.86 }) end)
		p.MouseButton1Click:Connect(function()
			shown = not shown; tween(p, 0.2, { BackgroundTransparency = shown and 0.26 or 0.86 }); tween(s, 0.2, { Transparency = shown and 0.8 or 0.94 })
			if _pdKey and System and System.setLocalTransparency then System.setLocalTransparency(_pdKey, shown) end  -- pink(shown)=SHOW in FP; dim=hide. LOCAL-only.
		end)
	end
	region("Hat", 0, -63, 26, 11, 4); region("Head", 0, -49, 24, 24, 12); region("Torso", 0, -15, 36, 44, 9)
	region("Arm L", -28, -12, 12, 40, 6); region("Arm R", 28, -12, 12, 40, 6)
	region("Leg L", -10, 44, 15, 46, 6); region("Leg R", 10, 44, 15, 46, 6)
	-- Tail: a reveal, not an FP toggle - tapping shows/hides the Tail card. Distinct purple tint + tilt.
	if onTail then
		local shown = false
		local tail = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = T.accent2, BackgroundTransparency = 0.35, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 23, 0.5, 40), Size = UDim2.fromOffset(10, 36), Rotation = 26, Parent = fig }); corner(tail, 5)
		tail.MouseButton1Click:Connect(function() shown = not shown; tween(tail, 0.2, { BackgroundTransparency = shown and 0.08 or 0.35 }); onTail(shown); toast("Tail", shown and "Tail options shown" or "Tail options hidden") end)
	end
	-- right host: first-person controls (the POV toggle) sit here, vertically centred, filling the space beside the figure
	local right = new("Frame", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.5, 0), Size = UDim2.new(1, -146, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = card }); vlist(right, 8)
	return card, right
end

--=================================================================================
-- PAGES  (mock - full 1-to-1 population comes next)
--=================================================================================
local PAGES = {}
-- [V3 MERGE] the demo-data table (was: fabricated clothes/catalog/equipped/bundle/keybind lists) is fully REMOVED.
-- Every tab now reads LIVE engine state: getClothesList / getRecolorRows / getStripRows / getHPRows /
-- catalogLoadPage / getCatalogEquipped / getBundleList / getKeybindName. No fabricated data remains.
-- one Home 2-column row -> (row, leftColumn, rightColumn). The canvas scales to fit, so it's always 2 columns.
local function twoCol(parent, order, count)
	count = count or 2
	local row = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order, Parent = parent })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 12), SortOrder = Enum.SortOrder.LayoutOrder, VerticalAlignment = Enum.VerticalAlignment.Top, Parent = row })
	local off = -12 * (count - 1) / count  -- share the inter-column gaps so N columns fill the row exactly (count=2 -> -6, matching the old layout)
	local c = {}
	for i = 1, count do c[i] = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1 / count, off, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = i, Parent = row }); vlist(c[i], 12) end
	return row, c[1], c[2], c[3]
end
-- ── Tab-page REDESIGN primitives ─────────────────────────────────────────────────────────────────────────
-- Layout tools (like flex cells), NOT a fixed template - each tab arranges them bespoke to pack short controls
-- side-by-side instead of one-per-row, and to break the monotonous stack of identical full-width bars.
local function cols(parent, order, n, gap)  -- a horizontal row of n equal cells; drop ONE control into each cell
	n = n or 2; gap = gap or 8
	local row = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order or 1, Parent = parent })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, gap), VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder, Parent = row })
	local cells = {}
	for i = 1, n do cells[i] = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1 / n, -gap * (n - 1) / n, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = i, Parent = row }) end
	return cells
end
local function secHead(parent, title, order)  -- slim uppercase-accent section label with a hairline underline
	local f = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 24), LayoutOrder = order or 1, Parent = parent })
	lbl({ Position = UDim2.new(0, 2, 0, 1), Size = UDim2.new(1, -2, 0, 14), Text = string.upper(title or ""), Font = FONTB, TextColor3 = T.accent, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, Parent = f })
	new("Frame", { Name = "Hairline", AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, 0), Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = T.line, BackgroundTransparency = 0.5, BorderSizePixel = 0, Parent = f })
	return f
end
-- a BENTO section group: TRANSPARENT (no grey card box) - a WHITE section title + a hairline (distinct grid) + controls.
local function tile(parent, title, order)
	local c = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order or 1, Parent = parent }); vlist(c, 7)
	if title and title ~= "" then
		local hd = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 21), LayoutOrder = 0, Parent = c })
		lbl({ Position = UDim2.new(0, 1, 0, 0), Size = UDim2.new(1, -1, 0, 15), Text = string.upper(title), Font = FONTB, TextColor3 = T.txt, TextSize = 12.5, TextXAlignment = Enum.TextXAlignment.Left, Parent = hd })
		new("Frame", { Name = "Hairline", AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, 0), Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = T.line, BackgroundTransparency = 0.4, BorderSizePixel = 0, Parent = hd })  -- hairline under the title (named so the entrance draws it in L->R)
	end
	return c
end
-- two side-by-side bento columns split (leftFrac) with a VERTICAL hairline between them (distinct grid). Drop tiles in each.
local function bentoCols(parent, order, leftFrac, gap)
	leftFrac = leftFrac or 0.5; gap = gap or 9
	local wrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order or 1, Parent = parent })
	local row = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = wrap })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, gap), VerticalAlignment = Enum.VerticalAlignment.Top, SortOrder = Enum.SortOrder.LayoutOrder, Parent = row })
	local a = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(leftFrac, -gap / 2, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = row }); vlist(a, gap)
	local b = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1 - leftFrac, -gap / 2, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = row }); vlist(b, gap)
	-- vertical grid divider at the split. Kept OUT of the horizontal layout (own frame in `wrap`) with its height SYNCED to
	-- the row - a scale-height divider INSIDE the layout made the auto-sized row balloon to full height (that empty gap).
	local div = new("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(leftFrac, 0, 0, 0), Size = UDim2.new(0, 1, 0, 0), BackgroundColor3 = T.line, BackgroundTransparency = 0.25, BorderSizePixel = 0, ZIndex = 2, Parent = wrap })
	local function syncDiv() div.Size = UDim2.new(0, 1, 0, row.AbsoluteSize.Y) end
	row:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncDiv); syncDiv()
	return a, b
end
-- brief accent flash on a value label (used when a live stat changes).
local function flashLabel(lb) local orig = lb.TextColor3; lb.TextColor3 = T.accent; tween(lb, 0.55, { TextColor3 = orig }, QUINT) end
-- count a value label from its current number to `target`, formatted each step (fmt handles commas); optional accent flash.
local function animateNumber(label, target, fmt, flash)
	fmt = fmt or tostring
	local cur = tonumber((label.Text:gsub("[^%d]", ""))) or 0
	if flash then flashLabel(label) end
	local steps, dur = 18, 0.6
	task.spawn(function()
		for s = 1, steps do
			if not label.Parent then return end
			label.Text = fmt(math.floor(cur + (target - cur) * (s / steps) + 0.5))
			task.wait(dur / steps)
		end
		if label.Parent then label.Text = fmt(target) end
	end)
end
-- Home cards deal-in, SPLIT into prep (hide, before the header letters fly in) + reveal (scale-pop + cascade +
-- count-up, once the letters have landed). The header itself is handled separately (per-letter wave + fly).
local _homeBaseY = 18  -- resting Y (offset in the header frame) of each letter; the wave oscillates around it.
-- _KR._homeLetters: the current header letters, kept so a live UI-settings change can restart the wave (on _KR to save a Luau register)
local function homePrep(cards)
	local prep = {}
	for _, card in ipairs(cards or {}) do
		if card and card.Parent then
			local sc = card:FindFirstChildOfClass("UIScale") or new("UIScale", { Parent = card })
			sc.Scale = 0.97
			local targets, nums = {}, {}
			_KR.scanFade(card, targets, nums, nil)  -- capture+hide every transparency; count-up integer labels collected into nums
			prep[#prep + 1] = { sc = sc, targets = targets, nums = nums }
		end
	end
	return prep
end
local function homeRevealCards(prep)
	for i, p in ipairs(prep or {}) do
		task.delay((0.05 + i * 0.06) * SPEED, function()
			tween(p.sc, 0.55, { Scale = 1 }, BACK)  -- the pop
			for j, t in ipairs(p.targets) do  -- contents cascade outer->inner (capped stagger so big cards don't drag)
				task.delay(math.min(j, 14) * 0.018 * SPEED, function() tween(t[1], 0.4, { [t[2]] = t[3] }, QUINT) end)
			end
			task.delay(0.12 * SPEED, function() for _, nl in ipairs(p.nums) do if nl[1].Parent then countUp(nl[1], nl[2]) end end end)
		end)
	end
end
-- Continuous "Mexican wave" on the header letters - matches the intro loader EXACTLY: one shared os.clock drives
-- ALL letters (no per-letter state = no drift), CYCLE 1.4s, STAGGER 0.07s, peak = 40% of size, smoothstep up/down/rest.
-- _KR._waveConn: wave loop connection (on _KR to save a Luau register)
local function stopWave()
	if _KR._waveConn then pcall(function() _KR._waveConn:Disconnect() end); _KR._waveConn = nil end
	if _KR._homeLetters then for _, e in ipairs(_KR._homeLetters) do if e.lbl and e.lbl.Parent then e.lbl.Position = UDim2.new(0, e.x, 0, _homeBaseY) end end end  -- settle letters back to rest, else disabling the wave freezes them mid-bounce (garbled header)
end
local function startWave(letters)
	stopWave()
	if not letters or #letters == 0 then return end
	local CYCLE, STAG, startT = 1.4, 0.07, os.clock()
	local peak = -math.floor(((letters[1] and letters[1].lbl and letters[1].lbl.TextSize) or 24) * 0.4)  -- invariant across the brand letters (all share one TextSize) -> compute ONCE, not per-letter every frame
	_KR._waveConn = RunService.Heartbeat:Connect(function()
		local t = os.clock() - startT
		for i, e in ipairs(letters) do
			local ll = e.lbl
			if ll and ll.Parent then
				local phase = ((t - (i - 1) * STAG) % CYCLE) / CYCLE
				local y = 0
				if phase < 0.30 then local u = phase / 0.30; y = u * u * (3 - 2 * u) * peak
				elseif phase < 0.60 then local u = (phase - 0.30) / 0.30; y = (1 - u * u * (3 - 2 * u)) * peak end
				ll.Position = UDim2.new(0, e.x, 0, _homeBaseY + math.floor(y))
			end
		end
	end)
end
local function buildHome(h)
	local name = (LocalPlayer.DisplayName ~= "" and LocalPlayer.DisplayName) or LocalPlayer.Name
	if SET.hideName then name = "Hidden" end  -- privacy: mask the display name everywhere it appears
	local uname = SET.hideName and "@hidden" or ("@" .. LocalPlayer.Name)
	local GAP = 12  -- base card gap; Compact density is now applied globally via vlist/DGAP (don't double-dial here)
	-- Home is a horizontal split: the dashboard (main, left) + a tall narrow info rail (right) holding Warning +
	-- Credits. Both live inside the fit-to-screen canvas, so it scales as ONE unit on every device (desktop AND
	-- mobile); moving Warning/Credits off the bottom row also shortens the canvas so the dashboard fits bigger.
	local RAIL_W = 340
	-- header spans the full canvas top (LayoutOrder 1, above the split) so the dashboard cards AND the info
	-- rail both begin below it - the Warning/Credits align with the Server/Friends row, not the header text.
	local w = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 58), LayoutOrder = 1, Parent = h })
	local split = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = h })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, GAP + 4), VerticalAlignment = Enum.VerticalAlignment.Top, SortOrder = Enum.SortOrder.LayoutOrder, Parent = split })
	local main = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, -(RAIL_W + 16), 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = split }); vlist(main, GAP)
	local rail = new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromOffset(RAIL_W, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = split }); vlist(rail, GAP)
	-- "RoClothes:Krul" as INDIVIDUAL letters so each can wave (Heartbeat) + fly from/into the favicon.
	-- Colours match the intro loader: "RoClothes" near-white, ":" grey, "Krul" pink; soft black stroke.
	local BRAND, HSIZE = "RoClothes:Krul", 24
	local letters, cumX = {}, 0
	_KR.glyphW = _KR.glyphW or {}  -- per-glyph width memo: the brand is a fixed string at fixed HSIZE/FONTB, so a settings-driven Home rebuild reuses measurements instead of re-running GetTextSize every time
	for i = 1, #BRAND do
		local ch = BRAND:sub(i, i)
		local col = (i >= 11) and Color3.fromRGB(255, 110, 180) or (ch == ":" and Color3.fromRGB(200, 200, 215) or Color3.fromRGB(245, 247, 255))
		local wpx = _KR.glyphW[ch]; if not wpx then wpx = 12; pcall(function() wpx = math.ceil(TextService:GetTextSize(ch, HSIZE, FONTB, Vector2.new(1e4, 1e4)).X) + 1 end); _KR.glyphW[ch] = wpx end  -- memoized per glyph
		local ll = lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, cumX, 0, _homeBaseY), Size = UDim2.fromOffset(wpx, HSIZE + 6), Text = ch, Font = FONTB, TextColor3 = col, TextSize = HSIZE, TextXAlignment = Enum.TextXAlignment.Center, Parent = w })
		ll.TextStrokeColor3 = Color3.fromRGB(0, 0, 0); ll.TextStrokeTransparency = 0.45
		letters[i] = { lbl = ll, x = cumX }
		cumX = cumX + wpx
	end
	lbl({ Position = UDim2.new(0, 0, 0, 40), Size = UDim2.new(1, 0, 0, 15), Text = "Welcome home, " .. name, TextColor3 = T.txt3, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, Parent = w })
	-- V4.4.x: executor-capability warning beside the logo (red) - appears only if the boot probe found a gap.
	local capsHomeWarn = lbl({ AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 2), Size = UDim2.fromOffset(340, 54), Text = "", Font = FONT, TextSize = 12.5, TextColor3 = Color3.fromRGB(255, 110, 120), TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Right, TextYAlignment = Enum.TextYAlignment.Top, Visible = false, ZIndex = 5, Parent = w })
	System._onCapsGap(function(txt) if capsHomeWarn and capsHomeWarn.Parent then capsHomeWarn.Text = txt; capsHomeWarn.Visible = true end end)
	local _, leftCol, rightCol = twoCol(main, 1)
	local function fmtT(u) return string.format("%02d:%02d:%02d", math.floor(u / 3600), math.floor(u / 60) % 60, u % 60) end
	-- Server card (green) -> left column
	local plrs = game:GetService("Players")
	local ping = "-"
	pcall(function() ping = math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()) .. " ms" end)
	local up = 0; pcall(function() up = math.floor(time()) end)
	local sCard, sbody = UI.card(leftCol, "Server", "Information on the session you're in.", 1, Color3.fromRGB(34, 92, 74))
	local _, svals = UI.stats(sbody, {
		{ #plrs:GetPlayers() .. " playing", "Players" },
		{ plrs.MaxPlayers .. " can join", "Maximum players" },
		{ ping, "Latency" },
		{ fmtT(up), "In server for" },
		(SET.hideLocation and { "Hidden", "Location", "full" } or { _serverRegion, "Location", "full" }),  -- V4.5.24 Fix: dropped the `true` (tap-to-reveal mask) from the real-region branch - it masked the region when privacy was OFF and showed a plain "Hidden" when ON (inverted). No mask needed on either branch: "Hidden" is already privacy-safe.
		{ "Tap to copy", "Join script", "full", copy = function()
			local pid, jid = 0, ""; pcall(function() pid, jid = game.PlaceId, game.JobId end)
			return ('game:GetService("TeleportService"):TeleportToPlaceInstance(%d, "%s", game:GetService("Players").LocalPlayer)'):format(pid, jid)
		end },
	}, nil, Color3.fromRGB(34, 92, 74))
	-- live counter: "In server for" ticks every second while the card exists (HH:MM:SS).
	local upL = svals["In server for"]
	if upL then task.spawn(function()
		while upL.Parent do local u = 0; pcall(function() u = math.floor(time()) end); upL.Text = fmtT(u); task.wait(1) end
	end) end
	-- Latency ticks live every ~2s so it always shows the LATEST ping (not the one-shot value from build time).
	local pingL = svals["Latency"]
	if pingL then task.spawn(function()
		while pingL.Parent do local ms; pcall(function() ms = math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()) end); if ms then pingL.Text = ms .. " ms" end; task.wait(2) end
	end) end
	-- Friends card (blue) -> right column, top. Counts fetched async, count up when they land.
	local fCard, fbody = UI.card(rightCol, "Friends", "See which of your friends are around.", 1, Color3.fromRGB(52, 62, 128))
	local _, fvals = UI.stats(fbody, { { "0", "In server" }, { "-", "Offline" }, { "0", "Online" }, { "-", "All" } }, nil, Color3.fromRGB(52, 62, 128))
	-- all four are filled by the async fetch below; mark them so the entrance count-up leaves them alone (else it can overwrite the fetched value back to 0).
	for _, k in ipairs({ "In server", "Online", "Offline", "All" }) do if fvals[k] then fvals[k]:SetAttribute("live", true) end end
	task.spawn(function()
		local inServer, online, total = 0, 0, nil
		pcall(function()
			local o = LocalPlayer:GetFriendsOnline(200)
			if type(o) == "table" then online = #o; for _, f in ipairs(o) do if f.PlaceId == game.PlaceId then inServer += 1 end end end
		end)
		pcall(function()  -- total friends INCL. offline - GetFriendsAsync is paginated, so walk every page
			local fp = game:GetService("Players"):GetFriendsAsync(LocalPlayer.UserId); local n = 0
			while true do for _ in ipairs(fp:GetCurrentPage()) do n += 1 end; if fp.IsFinished then break end; fp:AdvanceToNextPageAsync() end
			total = n
		end)
		if fvals["In server"] and fvals["In server"].Parent then countUp(fvals["In server"], tostring(inServer)) end
		if fvals["Online"] and fvals["Online"].Parent then countUp(fvals["Online"], tostring(online)) end
		if total and fvals["All"] and fvals["All"].Parent then countUp(fvals["All"], tostring(total)) end                              -- real total (was a "-" placeholder)
		if total and fvals["Offline"] and fvals["Offline"].Parent then countUp(fvals["Offline"], tostring(math.max(0, total - online))) end  -- offline = total minus online (was a "-" placeholder)
	end)
	-- Profile card (cyan) -> left column, below Server (above the full-width Executor card).
	local pCard, pbody = UI.card(leftCol, "Profile", nil, 2, Color3.fromRGB(34, 90, 110))
	local prow = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 48), Parent = pbody })
	local av = new("ImageLabel", { Size = UDim2.fromOffset(48, 48), BackgroundColor3 = T.bg2, BorderSizePixel = 0, Image = "", Parent = prow }); corner(av, 11)
	-- Show the Krul brand icon FIRST so the slot is NEVER a blank box, then upgrade to the LIVE Roblox headshot
	-- only once PreloadAsync confirms it actually resolved. Some executors sandbox the rbxthumb content protocol
	-- (same class as the rbxassetid runtime block) and render a blank square - icon-first guarantees a visible
	-- avatar there, while executors that DO support rbxthumb still get the live headshot. (blurAvatar = privacy:
	-- stay on the brand icon, never upgrade.) thumb/ok live inside the task closure → no _buildV3GUI register cost.
	useKrulIcon(av)
	if not SET.blurAvatar then
		task.spawn(function()
			local thumb = "rbxthumb://type=AvatarHeadShot&id=" .. LocalPlayer.UserId .. "&w=150&h=150"
			local ok = false
			pcall(function() game:GetService("ContentProvider"):PreloadAsync({ thumb }, function(_, st) ok = ok or (st == Enum.AssetFetchStatus.Success) end) end)
			if ok and av.Parent then av.Image = thumb end
		end)
	end
	lbl({ Position = UDim2.new(0, 60, 0, 6), Size = UDim2.new(1, -60, 0, 20), Text = name, Font = FONTB, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Left, Parent = prow })
	lbl({ Position = UDim2.new(0, 60, 0, 27), Size = UDim2.new(1, -60, 0, 15), Text = uname, TextColor3 = T.txt3, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, Parent = prow })
	-- RoClothes card (violet) -> right column, below Friends.
	local rCard, rbody = UI.card(rightCol, "RoClothes:Krul", "Your session at a glance.", 2, Color3.fromRGB(92, 46, 104))
	-- [V3 MERGE FIX] REAL session values (was fabricated "V4.4.3"/"Online"/"3 outfits Saved by you"):
	UI.stats(rbody, {
		{ _RC_VER, "Script version" },  -- real version constant (L84), not a hardcoded string
		{ (System and System._contentInstalled) and "Ready" or "Syncing", "CDN content" },  -- real install state
		{ tostring((System and System.getBundleList and #(System.getBundleList("mine", "") or {})) or 0) .. " saved", "Your bundles" },  -- real saved-bundle count
		{ _execName, "Executor" },
	}, 1, Color3.fromRGB(92, 46, 104))
	local sysL = lbl({ Size = UDim2.new(1, 0, 0, 14), Text = "FPS --  ·  Phys --  ·  Mem --", Font = FONT, TextColor3 = T.txt3, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 2, Parent = rbody })  -- live status readout (the real script's status footer: FPS / physics FPS / memory)
	task.spawn(function()
		local Stats = game:GetService("Stats"); local frames = 0
		local conn = RunService.RenderStepped:Connect(function() frames = frames + 1 end)  -- count frames per window for a stable FPS
		while sysL.Parent do
			local t0 = os.clock(); task.wait(0.5); local el = math.max(0.001, os.clock() - t0)
			local fps = math.floor(frames / el + 0.5); frames = 0
			local phys, mem = 0, 0
			-- "Phys" = the engine's LIVE body-part-physics count (System.getPhysCount, L10760) - the original
			-- script's footer metric. (Was workspace:GetRealPhysicsFPS(), which is pinned at ~60 and reads as a
			-- meaningless constant; getPhysCount reflects the actual active-physics parts - 0 when none, correct.)
			pcall(function() if System and System.getPhysCount then phys = System.getPhysCount() end end)
