	-- The 2 / 19444 are only a fallback shown until the fetch lands (or if HTTP is blocked / the endpoint is down).
	local liveOnline, liveRuns = 2, 19444
	-- height 80 so the card bottom sits LEVEL with the Credits card in the rail (measured: same bottom edge).
	local banner = new("Frame", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 80), LayoutOrder = 2, Parent = main }); corner(banner, 12); stroke(banner, T.lineSoft, 1)
	local bgrad = new("UIGradient", { Rotation = 20, Color = ColorSequence.new(Color3.fromRGB(48, 30, 46), Color3.fromRGB(26, 22, 30)), Parent = banner })  -- subtle vampiric tint (not grey)
	task.spawn(function() while bgrad.Parent do tween(bgrad, 4, { Rotation = 36 }); task.wait(4.1); tween(bgrad, 4, { Rotation = 20 }); task.wait(4.1) end end)  -- slow living sheen drift
	-- stats LEFT (vertically centered), guide button pinned to the RIGHT border - both on the same centre line.
	local bInner = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 22, 0.5, 0), AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 46), BackgroundTransparency = 1, Parent = banner })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 26), SortOrder = Enum.SortOrder.LayoutOrder, Parent = bInner })
	local onlineLbl = miniStat(bInner, "0", "ONLINE NOW", 1, true, 24)
	new("Frame", { Size = UDim2.fromOffset(1, 34), BackgroundColor3 = T.line, BorderSizePixel = 0, LayoutOrder = 2, Parent = bInner })
	local runsLbl = miniStat(bInner, "0", "TOTAL RUNS", 3, false, 24)
	local guideBtn = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -18, 0.5, 0), AutoButtonColor = false, Text = "", BackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, Size = UDim2.fromOffset(158, 40), Parent = banner }); corner(guideBtn, 10)
	new("UIGradient", { Rotation = 25, Color = ColorSequence.new(Color3.fromRGB(132, 84, 196), Color3.fromRGB(92, 56, 150)), Parent = guideBtn })  -- vampiric violet
	lbl({ Size = UDim2.fromScale(1, 1), Text = "Executor Guide", Font = FONTB, TextColor3 = T.txt, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Center, Parent = guideBtn })
	guideBtn.MouseButton1Click:Connect(function() if UI._executorGuide then UI._executorGuide() end end)
	onlineLbl:SetAttribute("live", true); runsLbl:SetAttribute("live", true)  -- entrance leaves these to the live loop below (which counts them up itself)
	-- poll krulhub.dev/stats while Home is open; COUNT the numbers up (from 0 first time, old->new after) instead of snapping; fall back to the placeholder if HTTP is blocked. Loop ends when the banner is rebuilt.
	local firstStat = true
	task.spawn(function()
		task.wait(0.9)  -- let the entrance reveal the banner first, so the count-up from 0 is actually seen (not run behind the fade)
		while onlineLbl.Parent do
			local res, d
			local req = request or http_request or (syn and syn.request) or (http and http.request)
			if req then local ok, out = pcall(req, { Url = "https://krulhub.dev/stats", Method = "GET" }); if ok and type(out) == "table" then res = out.Body end end
			if not res then pcall(function() res = game:HttpGet("https://krulhub.dev/stats") end) end
			if res then pcall(function() local j = game:GetService("HttpService"):JSONDecode(res); if type(j) == "table" then d = j end end) end
			local on = (d and type(d.online) == "number") and d.online or (firstStat and liveOnline or nil)
			local rn = (d and type(d.totalRuns) == "number") and d.totalRuns or (firstStat and liveRuns or nil)
			if on ~= nil and onlineLbl.Parent then animateNumber(onlineLbl, on, tostring, not firstStat) end
			if rn ~= nil and runsLbl.Parent then animateNumber(runsLbl, rn, fmtNum, not firstStat) end
			firstStat = false
			task.wait(30)
		end
	end)
	-- Info rail (right): the COMPLETE warning + the FULL credits list, designed as proper cards. Executor is
	-- already a stat on the RoClothes card, so the standalone executor/discord cards are gone.
	local warn = new("Frame", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = rail }); corner(warn, 12); local ws = stroke(warn, Color3.fromRGB(170, 44, 54), 2); pad(warn, 16, 16, 15, 15); vlist(warn, 12)
	new("UIGradient", { Rotation = 90, Color = ColorSequence.new(Color3.fromRGB(31, 12, 16), Color3.fromRGB(20, 10, 13)), Parent = warn })  -- white base shows the real dark-red card colour
	-- big "!" sign + large WARNING header (matches the real Credits warning banner), both pulse.
	local wbanner = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 58), LayoutOrder = 1, Parent = warn })  -- NOT `banner` - that name is the stats banner above; shadowing it dropped the stats banner out of the entrance list.
	local sign = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(56, 56), BackgroundColor3 = Color3.fromRGB(150, 30, 42), BorderSizePixel = 0, Parent = wbanner }); corner(sign, 14); local signStroke = stroke(sign, Color3.fromRGB(232, 74, 84), 2)
	lbl({ Size = UDim2.fromScale(1, 1), Text = "!", Font = FONTB, TextSize = 42, TextColor3 = Color3.fromRGB(255, 255, 255), TextXAlignment = Enum.TextXAlignment.Center, Parent = sign })
	lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 70, 0.5, 0), Size = UDim2.new(1, -70, 1, 0), Text = "WARNING", Font = FONTB, TextSize = 30, TextColor3 = Color3.fromRGB(255, 120, 138), TextXAlignment = Enum.TextXAlignment.Left, Parent = wbanner })
	lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = "Unauthorized sharing of screenshot or record of RoClothes:Krul content on social media is strictly prohibited. This script embeds a unique, invisible synthetic ID on your screen. If any leaked content is traced back to your account, you will be permanently blacklisted. Do not share record or screenshot on social media without Krul's explicit consent.", TextColor3 = Color3.fromRGB(255, 190, 190), TextSize = 13.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 2, Parent = warn })
	task.spawn(function()  -- pulse the sign + border deep<->bright red (spec's "pulsing red"); stops on rebuild.
		while ws.Parent do
			tween(ws, 1.1, { Color = Color3.fromRGB(232, 60, 78) }); tween(signStroke, 1.1, { Color = Color3.fromRGB(255, 128, 138) }); tween(sign, 1.1, { BackgroundColor3 = Color3.fromRGB(198, 44, 60) }); task.wait(1.15)
			tween(ws, 1.1, { Color = Color3.fromRGB(120, 32, 42) }); tween(signStroke, 1.1, { Color = Color3.fromRGB(200, 60, 70) }); tween(sign, 1.1, { BackgroundColor3 = Color3.fromRGB(140, 28, 40) }); task.wait(1.15)
		end
	end)
	local cred = new("Frame", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = rail }); corner(cred, 12); stroke(cred, T.lineSoft, 1); pad(cred, 15, 15, 13, 13); vlist(cred, 8)
	new("UIGradient", { Rotation = 90, Color = ColorSequence.new(Color3.fromRGB(48, 36, 72), Color3.fromRGB(28, 22, 38)), Parent = cred })
	lbl({ Size = UDim2.new(1, 0, 0, 20), Text = "Credits", Font = FONTB, TextSize = 16, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 0, Parent = cred })
	local people = { { "Krul", "RoClothes:Krul Dev" }, { "LERP", "RoClothes:Lerp Dev" }, { "Unknowing", "Original RoClothes" }, { "Wynn", "Assistant developer" }, { "EC", "Website developer" }, { "die2n1ght", "Clothing artist" }, { "Quitamase", "Video animation" } }
	for i, p in ipairs(people) do
		local pr = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 17), LayoutOrder = i, Parent = cred })
		lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(0.42, 0, 1, 0), Text = p[1], Font = FONTB, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = pr })
		lbl({ AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0.58, -6, 1, 0), Text = p[2], TextColor3 = T.txt3, TextSize = 11.5, TextXAlignment = Enum.TextXAlignment.Right, TextTruncate = Enum.TextTruncate.AtEnd, Parent = pr })
	end
	-- gradient on a TextButton tints its TEXT too (that reddish caption) - so the button carries only the
	-- gradient (white base = it shows its true pink, not a muddy dark multiply) and the caption is a CHILD label.
	local CHAT_URL = "https://krulhub.dev/s/krul-chat"  -- the real script's chat endpoint (fetch + loadstring + run KrulGlobalChat)
	local chatBtn = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 32), LayoutOrder = 98, Parent = cred }); corner(chatBtn, 8)
	new("UIGradient", { Rotation = 25, Color = ColorSequence.new(Color3.fromRGB(124, 92, 214), Color3.fromRGB(78, 58, 150)), Parent = chatBtn })  -- violet, matching the real script's Chat button
	local chatLbl = lbl({ Size = UDim2.fromScale(1, 1), Text = "Open Chat", Font = FONTB, TextColor3 = T.txt, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Center, Parent = chatBtn })  -- child label so the gradient doesn't tint it; captured for load-state feedback
	local _gcBusy = false
	local function launchChat()  -- mirrors the real script: fetch + loadstring + run, guarded, with label feedback
		if _gcBusy then return end; _gcBusy = true; chatLbl.Text = "Loading…"
		task.spawn(function()
			local ok = pcall(function() local src = game:HttpGet(CHAT_URL); local fn = loadstring(src); if type(fn) == "function" then fn() end end)
			chatLbl.Text = ok and "Open Chat" or "Failed - retry"
			task.wait(1); _gcBusy = false
		end)
	end
	chatBtn.MouseButton1Click:Connect(launchChat); chatBtn.Activated:Connect(launchChat)  -- both, like the real script (the busy guard makes the double-fire a no-op)
	local disc = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 32), LayoutOrder = 99, Parent = cred }); corner(disc, 8)
	new("UIGradient", { Rotation = 25, Color = ColorSequence.new(T.accent, T.accentD), Parent = disc })
	lbl({ Size = UDim2.fromScale(1, 1), Text = "Join Discord", Font = FONTB, TextColor3 = T.txt, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Center, Parent = disc })
	disc.MouseButton1Click:Connect(function() local ok = setclipboard and pcall(setclipboard, "https://discord.gg/SBUuYsnShf"); toast("Discord", ok and "discord.gg/SBUuYsnShf copied." or "No clipboard on this executor.", ok and "ok" or "warn") end)
	-- entrance targets, in deal-in order (Server, Friends, Profile, RoClothes, banner, Warning, Credits).
	return { header = w, letters = letters, host = split, cards = { sCard, fCard, pCard, rCard, banner, warn, cred } }
end
function PAGES.body(h)
	-- BENTO: a flow of section tiles; within each, controls pair 2-up (dropdowns, stiffness/damping sliders, swatches,
	-- toggles). The body-map stays full-width. Still scrolls (huge tab) but roughly half the height it was.
	-- Phase 2 wiring helpers: V3's sliders show INTEGERS in a display range [dmin,dmax]; the engine
	-- fields live in a real range [lo,hi]. _sd seeds the display value from engine state; _wr returns
	-- an onChange that maps the display integer back to the engine value (mirrors V2 _wireSlider).
	local function _gp(f) return System and System.getPD and System.getPD(f) end
	local function _sd(field, lo, hi, dmin, dmax, ddefault)
		local cur = _gp(field)
		if type(cur) ~= "number" then return ddefault end
		local span = (hi - lo); if span == 0 then span = 1 end
		return math.clamp(math.floor(dmin + (cur - lo) / span * (dmax - dmin) + 0.5), dmin, dmax)
	end
	local function _wr(field, lo, hi, dmin, dmax, phys)
		return function(v)
			local span = (dmax - dmin); if span == 0 then span = 1 end
			local eng = lo + (v - dmin) / span * (hi - lo)
			if phys then if System and System.setPhysicsField then System.setPhysicsField(field, eng) end
			elseif System and System.setPD then System.setPD(field, eng) end
		end
	end
	-- WIRED (merge): body-type dropdowns are engine-driven. Options come from System.getBodyTypeLabels()
	-- (indexed by the PD field key) capped at System.getBodyTypeMax(); disabled types (label == false, e.g.
	-- ButtType 4/5 = no mesh) are skipped. Picking maps the option label back to its real type NUMBER and
	-- writes System.setPD(field, n) -- the SAME engine path V2's _bodyTypeDrawerRow used (V2 L3387). The
	-- current PD value seeds the shown selection. Returns the current numeric type (Breasts uses it for the Bra row).
	local _BTL = (System and System.getBodyTypeLabels and System.getBodyTypeLabels()) or {}
	local _BTM = (System and System.getBodyTypeMax and System.getBodyTypeMax()) or {}
	local function _bodyDrop(parent, text, field, order, onPickType)
		local labels = _BTL[field] or {}
		local maxT = _BTM[field] or 1
		local function nameFor(v) local l = labels[v]; if l == nil or l == false then return "Type " .. tostring(v) end; return l end
		local opts, toType = {}, {}
		for t = 1, maxT do
			if labels[t] ~= false then local nm = nameFor(t); opts[#opts + 1] = nm; toType[nm] = t end
		end
		local cur = (System and System.getPD and System.getPD(field)); if type(cur) ~= "number" then cur = 1 end
		S[_curPage .. "\1d:" .. text] = nameFor(cur)  -- seed the shown value from live PD (engine is ground truth)
		UI.dropdown(parent, text, opts, order, function(o)
			local n = toType[o]
			if n and System and System.setPD then System.setPD(field, n) end
			if onPickType then onPickType(n) end
		end)
		return cur
	end
	-- BODY TYPES
	local bt = tile(h, "Body Types", 1)
	-- Breasts + its Type-6 Bra sub-cycle live together (full-width); the Bra cycler only shows when Type 6 is picked.
	local braWrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = bt }); vlist(braWrap, 7)
	local braRow  -- forward; the Breasts onPick closure captures it.
	local _curBreasts = _bodyDrop(braWrap, "Breasts", "BreastsType", 1, function(n) if braRow then UI.reveal(braRow, n == 6, true) end end)
	-- Bra sub-cycle (BreastsType == 6): None -> Bra 1 -> Bra 2, engine-driven via getBraState/cycleBra (mirrors V2 L3427).
	do
		local _bs = (System and System.getBraState and System.getBraState()) or "none"
		local _braInit = (_bs == "bra1" and "Bra 1") or (_bs == "bra2" and "Bra 2") or "None"
		braRow = UI.cyc(braWrap, "Bra", { "None", "Bra 1", "Bra 2" }, 2, function() if System and System.cycleBra then System.cycleBra() end end, _braInit)
	end
	braRow.Visible = (_curBreasts == 6)  -- re-sync to live BreastsType after a rebuild.
	local bt1 = cols(bt, 2, 2); _bodyDrop(bt1[1], "Torso", "TorsoType", 1); _bodyDrop(bt1[2], "Arm", "ArmType", 1)
	local bt2 = cols(bt, 3, 2); _bodyDrop(bt2[1], "Legs", "LegsType", 1); _bodyDrop(bt2[2], "Butt", "ButtType", 1)
	-- SCALE
	local sc = tile(h, "Scale", 4)
	local sc1 = cols(sc, 1, 2); UI.slider(sc1[1], "Breasts Scale", _sd("BreastsScale", 0.5, 2.5, 50, 250, 100), 50, 250, 1, _wr("BreastsScale", 0.5, 2.5, 50, 250)); UI.slider(sc1[2], "Butts Scale", _sd("ButtsScale", 0.5, 2.5, 50, 250, 100), 50, 250, 1, _wr("ButtsScale", 0.5, 2.5, 50, 250))
	UI.slider(sc, "Legs Scale", _sd("LegsScale", 0.5, 2.5, 50, 250, 100), 50, 250, 2, _wr("LegsScale", 0.5, 2.5, 50, 250))
	local sc3 = cols(sc, 3, 2); UI.slider(sc3[1], "Torso Scale", _sd("TorsoScale", 0.5, 2.5, 50, 250, 100), 50, 250, 3, _wr("TorsoScale", 0.5, 2.5, 50, 250)); UI.slider(sc3[2], "Left Arm Scale", _sd("LeftArmScale", 0.5, 2.5, 50, 250, 100), 50, 250, 3, _wr("LeftArmScale", 0.5, 2.5, 50, 250))
	local sc4 = cols(sc, 4, 2); UI.slider(sc4[1], "Right Arm Scale", _sd("RightArmScale", 0.5, 2.5, 50, 250, 100), 50, 250, 4, _wr("RightArmScale", 0.5, 2.5, 50, 250))
	-- PHYSICS - stiffness/damping paired per body part
	local ph = tile(h, "Physics - Stiffness & Damping", 3)
	local ph1 = cols(ph, 1, 2); UI.slider(ph1[1], "Breasts Stiffness", _sd("BreastsStiffness", 0.5, 30, 1, 30, 12), 1, 30, 1, _wr("BreastsStiffness", 0.5, 30, 1, 30, true)); UI.slider(ph1[2], "Breasts Damping", _sd("BreastsDamping", 0.01, 1.5, 1, 150, 40), 1, 150, 1, _wr("BreastsDamping", 0.01, 1.5, 1, 150, true))
	local ph2 = cols(ph, 2, 2); UI.slider(ph2[1], "Butts Stiffness", _sd("ButtsStiffness", 0.5, 30, 1, 30, 12), 1, 30, 1, _wr("ButtsStiffness", 0.5, 30, 1, 30, true)); UI.slider(ph2[2], "Butts Damping", _sd("ButtsDamping", 0.01, 1.5, 1, 150, 40), 1, 150, 1, _wr("ButtsDamping", 0.01, 1.5, 1, 150, true))
	local ph3 = cols(ph, 3, 2); UI.slider(ph3[1], "Cock Stiffness", _sd("CockStiffness", 0.5, 30, 1, 30, 12), 1, 30, 1, _wr("CockStiffness", 0.5, 30, 1, 30, true)); UI.slider(ph3[2], "Cock Damping", _sd("CockDamping", 0.01, 1.5, 1, 150, 40), 1, 150, 1, _wr("CockDamping", 0.01, 1.5, 1, 150, true))
	-- PHYSICS MULTIPLIERS
	local pm = tile(h, "Physics Multipliers", 4)
	local pm1 = cols(pm, 1, 2)
	do
		local _pp = (System and System.getPositionPhysicsMultiply and System.getPositionPhysicsMultiply()) or 1
		local _rp = (System and System.getRotationPhysicsMultiply and System.getRotationPhysicsMultiply()) or 4
		UI.slider(pm1[1], "Position Physics Multiply", math.clamp(math.floor((tonumber(_pp) or 1) + 0.5), 0, 20), 0, 20, 1, function(v) if System and System.setPositionPhysicsMultiply then System.setPositionPhysicsMultiply(v) end end)
		UI.slider(pm1[2], "Rotation Physics Multiply", math.clamp(math.floor((tonumber(_rp) or 4) + 0.5), 0, 20), 0, 20, 1, function(v) if System and System.setRotationPhysicsMultiply then System.setRotationPhysicsMultiply(v) end end)
	end
	local pm2 = cols(pm, 2, 2); UI.toggle(pm2[1], "Body Part Physics", (_gp("BodyPartPhysics") and true) or false, 1, function(st) if System and System.setPD then System.setPD("BodyPartPhysics", st) end end); UI.toggle(pm2[2], "Physics Obey Gravity", (_gp("PhysicsObeyGravity") and true) or false, 1, function(st) if System and System.setPD then System.setPD("PhysicsObeyGravity", st) end end)
	-- FIRST-PERSON & BODY-MAP
	local fp = tile(h, "First-Person & Body-Map", 5)
	UI.hint(fp, "Tap a part to hide it in first person; tap the tail for tail options.", 1)
	local tailRow  -- forward; the tail region reveals it.
	local _, mapRight = bodyMap(fp, 2, function(shown) if tailRow then UI.reveal(tailRow, shown, true) end end)
	UI.toggle(mapRight, "First Person POV", (_gp("FPerson") and true) or false, 1, function(st) if System and System.setPD then System.setPD("FPerson", st) end end)  -- inside the purple box, on the right
	do local _ts = _gp("tailSettings"); tailRow = UI.toggle(mapRight, "Tail Physics", (type(_ts) == "table" and _ts.tailPhysicsEnabled and true) or false, 2, function(st) if System and System.setPDNested then System.setPDNested("tailSettings", "tailPhysicsEnabled", st) end end) end; tailRow.Visible = false  -- inside the box too, under POV; revealed when the tail is tapped
	-- APPEARANCE
	local ap = tile(h, "Appearance", 6)
	local ap1 = cols(ap, 1, 2); do local _tv = { "Base", "Dark", "Use NippleColor" }; local _tc = _gp("Tone"); UI.cyc(ap1[1], "Skin", { "Tone: Base", "Tone: Dark", "Tone: Use NippleColor" }, 1, function(o, i) if System and System.setPD then System.setPD("Tone", _tv[i]) end end, (_tc and ("Tone: " .. tostring(_tc))) or nil) end; UI.field(ap1[2], "Local Transparency", "per-part (body-map)", 1, false)  -- [V3 MERGE FIX] display-only; the body-map figure IS the real control (mirrors V2 L3631)
	-- WIRED (merge): Skin/Nipple swatches. UI.swatch opens the shared HSV picker (openColorPicker) seeded from the
	-- chip's current colour; on Apply it fires onPick(c) -> System.setPD("SkinTone"/"NippleColor", c) (the NON-cloth__slot
	-- branch of V2 Modals.cp -> setPD(target)). The chip seeds from the live PD colour so re-opening shows it.
	local ap2 = cols(ap, 2, 2)
	do
		local _sk = (System and System.getPD and System.getPD("SkinTone"))
		UI.swatch(ap2[1], "Skin Tone", (typeof(_sk) == "Color3" and _sk) or Color3.fromRGB(248, 215, 195), 1, function(c) if System and System.setPD then System.setPD("SkinTone", c) end end)
		local _np = (System and System.getPD and System.getPD("NippleColor"))
		UI.swatch(ap2[2], "Nipple Color", (typeof(_np) == "Color3" and _np) or Color3.fromRGB(255, 167, 169), 1, function(c) if System and System.setPD then System.setPD("NippleColor", c) end end)
	end
	-- IDLE MOTION
	local im = tile(h, "Idle Motion", 7)
	local im1 = cols(im, 1, 2); UI.toggle(im1[1], "Breathing Idle", (_gp("BreathingEnabled") and true) or false, 1, function(st) if System and System.setPD then System.setPD("BreathingEnabled", st) end end); UI.toggle(im1[2], "Overtone Spring", (_gp("OvertoneEnabled") and true) or false, 1, function(st) if System and System.setPD then System.setPD("OvertoneEnabled", st) end end)
	UI.toggle(im, "SmartBone Physics", (_gp("SmartBoneEnabled") and true) or false, 2, function(st) if System and System.setPD then System.setPD("SmartBoneEnabled", st) end end)
	local im2 = cols(im, 3, 2); UI.slider(im2[1], "Breathing Amplitude", _sd("BreathingAmplitude", 0, 0.05, 0, 100, 25), 0, 100, 1, _wr("BreathingAmplitude", 0, 0.05, 0, 100)); UI.slider(im2[2], "Overtone Amplitude", _sd("OvertoneAmplitude", 0, 1, 0, 100, 50), 0, 100, 1, _wr("OvertoneAmplitude", 0, 1, 0, 100))
end
function PAGES.clothes(h, sticky)
	-- WIRED (merge): real engine-driven dynamic grid. Mirrors V2 Pages._renderClothes - pulls the cloth registry from
	-- System.getClothesList() ({name,hidden,krulHosted,equipped}), applies the All/2D (KrulHosted) segment + search text
	-- as LOCAL filters, skips Hidden entries, builds a tile per cloth with an EQUIPPED badge. A click either toggles a
	-- normal cloth (System.toggleCloth) or, for a KrulHosted cloth NOT yet equipped, opens the KrulType modal first
	-- (System.clothNeedsType && !System.isClothEquipped). The grid re-renders on seg switch, search commit, and after equip.
	local render  -- forward; the seg/search closures capture it.
	local _tab, _search = nil, ""  -- _tab: nil = All, "2d" = KrulHosted only
	-- STICKY: the filter seg + search pin above the scrolling grid (they stay put while you scroll the clothes)
	local sw = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = sticky }); pad(sw, 14, 10, 4, 8)
	local top = cols(sw, 1, 2)
	UI.seg(top[1], { "All", "2D" }, 1, function(o, i) _tab = (i == 2) and "2d" or nil; if render then render() end end)
	UI.field(top[2], "Search clothes", "", 1, true, function(t) _search = t or ""; if render then render() end end, nil, true)
	-- empty-state label + the grid host live in the scrolling body; render clears+rebuilds only the grid host.
	local emptyLbl = lbl({ Name = "Empty", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Text = "", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Visible = false, Parent = h })
	local gridWrap = new("Frame", { Name = "ClothesGridWrap", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = h })
	render = function()
		if not (gridWrap and gridWrap.Parent) then return end
		for _, c in ipairs(gridWrap:GetChildren()) do c:Destroy() end
		local list = (System and System.getClothesList and System.getClothesList()) or {}
		local needle = string.lower(_search or "")
		local items, shown = {}, 0
		for _, e in ipairs(list) do
			if not e.hidden then
				-- tab filter: All => everything; 2d => KrulHosted only. search: plain case-insensitive substring (no Lua patterns).
				local tabMatch = (_tab == nil) or (_tab == "2d" and e.krulHosted)
				local searchMatch = (needle == "") or (string.find(string.lower(e.name), needle, 1, true) ~= nil)
				if tabMatch and searchMatch then
					shown = shown + 1
					local nm = e.name
					items[#items + 1] = {
						name = nm,
						sub = e.krulHosted and "KrulHosted" or nil,
						badge = e.equipped and "EQUIPPED" or (e.krulHosted and "2D") or nil,
						badgeColor = e.equipped and T.good or T.accent,
						onClick = function()
							-- KrulHosted + not-yet-equipped -> ask Shirt/Pants first; else toggle + re-render.
							if System and System.clothNeedsType and System.clothNeedsType(nm)
								and not (System.isClothEquipped and System.isClothEquipped(nm)) then
								krulTypeDialog(nm)
							elseif System and System.toggleCloth then
								System.toggleCloth(nm); if render then render() end
							end
						end,
					}
				end
			end
		end
		UI.tiles(gridWrap, items, 1, 64)
		if shown == 0 then
			emptyLbl.Text = (needle ~= "" and ('No clothes match "' .. _search .. '".'))
				or (_tab == "2d" and "No 2D (KrulHosted) clothes installed yet.")
				or "No clothes available."
			emptyLbl.Visible = true
		else
			emptyLbl.Visible = false
		end
	end
	UI._renderClothesGrid = render  -- expose to krulTypeDialog via the UI upvalue (re-render after a Shirt/Pants pick)
	if System then System.renderClothesList = render end  -- V1 parity: let the hotSwap tail refresh EQUIPPED badges when a background path (peer/bundle/reset) mutates CurrentClothes. Self-guards on a stale grid (L3791).
	render()
end
function PAGES.catalog(h, sticky)
	-- two views toggled by the seg; declared BEFORE the seg so its closure can capture them.
