	local browser = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Visible = false, Parent = h }); vlist(browser, 8)
	-- STICKY: the By ID / Browser view toggle pins above the scroll so you can switch views from anywhere
