	local _catCatRow = _catCats[1]
	local _catSearch = ""
	local _catFilters = { freeOnly = false, creator = "" }
	local _catCursor, _catPageIndex, _catCursorStack, _catNextCursor = "", 1, {}, nil
	local _catFetching, _catHadFull, _catLimit = false, false, 30
	local _catFillToken, _equippedFillToken  -- newest per-item detail-fill job wins; older serialized fills self-cancel
	local topr = cols(browser, 1, 2)
