	local catWrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3, Parent = browser })
	new("UIGridLayout", { CellSize = UDim2.new(0.2, -5, 0, 28), CellPadding = UDim2.fromOffset(6, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = catWrap })  -- 5-up
	local catChips = {}
	local function paintCats() for row, e in pairs(catChips) do local on = (row == _catCatRow); tween(e.b, 0.2, { BackgroundColor3 = on and T.accentD or T.card, TextColor3 = on and Color3.new(1, 1, 1) or T.txt2 }); tween(e.s, 0.2, { Color = on and T.accent or T.lineSoft }) end end
	for i, cdef in ipairs(_catCats) do
		local _cd = cdef
		local b = new("TextButton", { AutoButtonColor = false, Text = cdef.label or "?", BackgroundColor3 = T.card, BorderSizePixel = 0, Font = FONTB, TextColor3 = T.txt2, TextSize = 11, LayoutOrder = i, Parent = catWrap }); corner(b, 7); local s = stroke(b, T.lineSoft, 1)
		catChips[_cd] = { b = b, s = s }
