		b.MouseEnter:Connect(function() if _cd ~= _catCatRow and SET.hoverFx and not SET.reduceMotion then tween(b, 0.15, { BackgroundColor3 = T.cardHi }) end end)  -- hover brighten, non-active chips only
		b.MouseLeave:Connect(function() if _cd ~= _catCatRow then tween(b, 0.15, { BackgroundColor3 = T.card }) end end)
	end
	-- Strip default avatar: 8 boolean category toggles WIRED to System.catalogStripToggle; active state from
	-- System.getCatalogStrip() (mirrors V2 _paintStrip L4046-4055). Accent fill = active.
	secHead(browser, "Strip default avatar", 6)  -- sits just above Equipped (below the browse grid + pagination)
	local strip = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 7, Parent = browser })
	new("UIGridLayout", { CellSize = UDim2.new(0.25, -6, 0, 30), CellPadding = UDim2.fromOffset(8, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = strip })
	local _stripBtns = {}
