	end
	for i, nm in ipairs({ "Hat", "Hair", "Face", "Neck", "Shoulder", "Front", "Back", "Waist" }) do
		local _cat = nm
		local b = new("TextButton", { AutoButtonColor = false, Text = nm, BackgroundColor3 = T.card, BorderSizePixel = 0, Font = FONTB, TextColor3 = T.txt2, TextSize = 11, LayoutOrder = i, Parent = strip }); corner(b, 7); stroke(b, T.lineSoft, 1)
		_stripBtns[nm] = b
		b.MouseButton1Click:Connect(function() if System and System.catalogStripToggle then System.catalogStripToggle(_cat) end; paintStrip() end)
	end
	paintStrip()
	local grid = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 4, Parent = browser })
	new("UIGridLayout", { CellSize = UDim2.new(1 / 3, -6, 0, 114), CellPadding = UDim2.fromOffset(8, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = grid })  -- 3-up
	-- status / empty-state label under the grid (also surfaces fetch failures, mirrors V2 statusLbl L4080)
	local statusLbl = lbl({ Name = "CatStatus", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 4, Text = "", TextColor3 = T.txt3, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, TextWrapped = true, Visible = false, Parent = browser })
	-- pager: Prev | Page N | Next (cursor-stack pagination, mirrors V2 L4082-4100). Created before renderGrid so the
	-- renderer's closure captures prev/pgLbl/nxt; the click handlers reference the forward-declared renderGrid.
	local pg = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 34), LayoutOrder = 5, Parent = browser })
	local prev = new("TextButton", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(72, 28), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "Prev", Font = FONTB, TextColor3 = T.txt2, TextSize = 12, Visible = false, Parent = pg }); corner(prev, 7); stroke(prev, T.lineSoft, 1); UI.hoverFill(prev, T.card, T.cardHi)
	local pgLbl = lbl({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(90, 20), Text = "Page 1", Font = FONTB, TextColor3 = T.txt2, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Center, Parent = pg })
	local nxt = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(72, 28), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "Next", Font = FONTB, TextColor3 = T.txt2, TextSize = 12, Visible = false, Parent = pg }); corner(nxt, 7); stroke(nxt, T.lineSoft, 1); UI.hoverFill(nxt, T.card, T.cardHi)
