		elseif dir == "prev" then if #_catCursorStack > 0 then _rbPopped = table.remove(_catCursorStack); _catCursor = _rbPopped or _catCursor end; _catPageIndex = _catPageIndex - 1 end  -- V4.5.24 Fix: guard the empty stack (table.remove({}) throws) + no bogus "" cursor; the failure rollback re-pushes only real strings
		_catFetching = true
		for _, ch in ipairs(grid:GetChildren()) do if not ch:IsA("UIGridLayout") then ch:Destroy() end end
