				local _thumbUri = (it.id and ("rbxthumb://type=" .. _thumbKind .. "&id=" .. tostring(it.id) .. "&w=150&h=150")) or ""
				local c = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = T.card, BorderSizePixel = 0, LayoutOrder = order, Parent = grid }); corner(c, 9); local cst = stroke(c, eq and T.accent or T.lineSoft, eq and 1.5 or 1); local csc = new("UIScale", { Parent = c }); pad(c, 8, 8, 8, 6)
				local img = new("ImageLabel", { BackgroundColor3 = T.bg, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 72), Image = _thumbUri, ScaleType = Enum.ScaleType.Fit, Parent = c }); corner(img, 6)
				local nameLbl = lbl({ Position = UDim2.new(0, 0, 0, 76), Size = UDim2.new(1, 0, 0, 15), Text = tostring(it.name or ("ID " .. tostring(it.id))), Font = FONTB, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = c })
				local priceLbl = lbl({ Position = UDim2.new(0, 0, 0, 92), Size = UDim2.new(1, 0, 0, 13), Text = pxText, TextColor3 = T.warn, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, Parent = c })
				local _eq = eq
				if _eq then local bd = new("Frame", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -5, 0, 5), Size = UDim2.fromOffset(52, 15), BackgroundColor3 = T.accentD, BorderSizePixel = 0, ZIndex = 3, Parent = c }); corner(bd, 5); lbl({ Size = UDim2.fromScale(1, 1), Text = "EQUIPPED", Font = FONTB, TextColor3 = Color3.new(1, 1, 1), TextSize = 8, ZIndex = 3, Parent = bd }); UI.breathe(new("UIScale", { Parent = bd }), { Scale = 1.07 }, 1.5) end
				c.MouseEnter:Connect(function() tween(csc, 0.18, { Scale = 1.04 }, QUINT); tween(cst, 0.18, { Color = _eq and T.accent or T.line }) end)  -- hover-lift
				c.MouseLeave:Connect(function() tween(csc, 0.18, { Scale = 1 }, QUINT); tween(cst, 0.18, { Color = _eq and T.accent or T.lineSoft }) end)
				c.MouseButton1Click:Connect(function()
					if System and System.catalogApplyItem then
						System.catalogApplyItem(item)
						renderGrid(false, nil, true); renderEquipped()  -- re-render the page (badges) + the equipped sidebar; keepScroll so equip doesn't yank you to the top
					end
				end)
				-- queue an async detail fill when name/price/type are missing (mirrors V2 L4146-4150)
				if (not it.name) or it.name == ("ID " .. tostring(it.id)) or it.priceInRobux == nil or (not it.assetType) then
					needs[#needs + 1] = { item = it, nameLbl = nameLbl, priceLbl = priceLbl, cell = c }
				end
			end
			pgLbl.Text = "Page " .. tostring(_catPageIndex)
			prev.Visible = (_catPageIndex > 1)
			nxt.Visible = (_catNextCursor ~= nil and _catNextCursor ~= "")  -- [V3 MERGE FIX] was: or _catHadFull -> Next showed with no cursor while the handler bailed (visible-but-inert)
			statusLbl.Visible = (order == 0)
			if order == 0 then statusLbl.Text = "No results." end
			-- async per-item detail fill (mirrors V2 L4160-4195): SERIALIZED + throttled - executor HTTP blocks the main
			-- thread on many mobile executors, so fetch one at a time with a task.wait() between each. A per-render token
			-- cancels an in-flight fill the moment the grid is re-rendered (new search / page / category).
			local _fillTok = {}; _catFillToken = _fillTok
