				for _, nd in ipairs(needs) do
					if _catFillToken ~= _fillTok then return end
					if not grid or not grid.Parent then return end
					local _it = nd.item
					if nd.cell and nd.cell.Parent then
						local d = System and System.catalogItemDetails and System.catalogItemDetails(_it.id)
						if _catFillToken ~= _fillTok then return end
						if d and nd.cell and nd.cell.Parent then
							if d.name and nd.nameLbl then nd.nameLbl.Text = d.name end
							if d.price ~= nil and nd.priceLbl then nd.priceLbl.Text = (d.price > 0) and ("R$ " .. tostring(d.price)) or "Free" end
						end
						if d then  -- patch the item table so the click handler applies with the resolved assetType
							if d.name then _it.name = d.name end
							if d.price then _it.priceInRobux = d.price end
							if d.assetType then _it.assetType = d.assetType end
						end
					end
					task.wait()  -- yield a frame so the engine breathes between blocking HTTP calls
				end
			end)
			_catFetching = false
			-- V4.5.17: restore the scroll position now the cells are rebuilt (equip/unequip keepScroll). A frame lets
			-- AutomaticCanvasSize recompute so the position isn't re-clamped to the top; set twice for the mobile case.
			-- REG-FIX: gate on this render's fill token (_fillTok) so a NEW search/page nav that started during the yield
			-- isn't yanked to this render's stale offset - if _catFillToken changed, a newer render owns the scroll now.
			if _scrollFrame and _scrollPos then
				task.wait()
				if _catFillToken == _fillTok then pcall(function() _scrollFrame.CanvasPosition = _scrollPos end) end
				task.wait()
				if _catFillToken == _fillTok then pcall(function() _scrollFrame.CanvasPosition = _scrollPos end) end
			end
		end)
	end
	-- register so the engine hotSwap tail (peer/bundle/reset) re-paints the visible grid (mirrors V2 L4201).
	UI._renderCatalog = renderGrid; if System then System.renderCatalog = renderGrid end
	secHead(browser, "Equipped", 8)
	local eqBox = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 9, Parent = browser }); vlist(eqBox, 8)
	-- THE EQUIPPED RENDERER (mirrors V2 Pages._renderEquipped L4210): rebuild rows from getCatalogEquipped; each row =
	-- name + Remove -> catalogRemoveEquipped(id, slot). Names resolve async via catalogItemDetails (serialized, cancel-token).
	renderEquipped = function()
		if not eqBox or not eqBox.Parent then return end
		for _, ch in ipairs(eqBox:GetChildren()) do if not ch:IsA("UIListLayout") then ch:Destroy() end end
		local list = (System and System.getCatalogEquipped and System.getCatalogEquipped()) or {}
		local _needs = {}
		local i = 0
		for _, e in ipairs(list) do
			local _e = e
			i += 1
			local nm0 = "ID " .. tostring(e.id)
			local row = new("Frame", { BackgroundColor3 = T.card, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 34), LayoutOrder = i, Parent = eqBox }); corner(row, 8); stroke(row, T.lineSoft, 1); pad(row, 10, 10, 0, 0)
			local nameLbl = lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(1, -84, 1, 0), Text = nm0 .. "  (" .. tostring(e.kind) .. ")", TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = row })
			local rm = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(72, 24), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "Remove", Font = FONTB, TextColor3 = T.bad, TextSize = 12, Parent = row }); corner(rm, 6); stroke(rm, T.lineSoft, 1); UI.hoverFill(rm, T.card, T.cardHi)
			rm.MouseButton1Click:Connect(function()
				if System and System.catalogRemoveEquipped then System.catalogRemoveEquipped(_e.id, _e.slot) end
				renderEquipped(); renderGrid(false)
			end)
			_needs[#_needs + 1] = { e = _e, nameLbl = nameLbl }
		end
		if i == 0 then UI.hint(eqBox, "Nothing equipped.", 1) end
		-- SERIALIZED name fills (cache-first inside the bridge); a per-render token cancels a stale fill (V2 L4236-4249).
		local _tok = {}; _equippedFillToken = _tok
		task.spawn(function()
			for _, nd in ipairs(_needs) do
				if _equippedFillToken ~= _tok then return end
				if nd.nameLbl and nd.nameLbl.Parent then
					local d = System and System.catalogItemDetails and System.catalogItemDetails(nd.e.id)
					if _equippedFillToken ~= _tok then return end
					if d and d.name and nd.nameLbl and nd.nameLbl.Parent then nd.nameLbl.Text = d.name .. "  (" .. tostring(nd.e.kind) .. ")" end
				end
				task.wait()
			end
		end)
	end
	-- register the equipped sidebar so the engine hotSwap tail re-paints it after a peer/bundle/reset (mirrors V2 L4253).
	UI._renderEquipped = renderEquipped; if System then System.renderEquipped = renderEquipped end
	paintCats()  -- highlight the active category chip
	-- initial paint: load the first page + the equipped sidebar when the Browser view FIRST opens (mirror V2 L4257-4264,
	-- which defers the network fetch until Browser is shown rather than firing it on build under the By-ID default view).
	local _catFirstOpen = false
	browser:GetPropertyChangedSignal("Visible"):Connect(function()
		if browser.Visible and not _catFirstOpen then
			_catFirstOpen = true
			renderGrid(true); renderEquipped()
		end
	end)
end
function PAGES.bundles(h, sticky)
	-- WIRED (merge): real engine-driven bundles grid + the cross-tab detecting-bundle flow. Mirrors V2 Pages.bundles /
	-- Pages._renderBundles (L4278-4408): the seg drives System.setBundleTab + re-render; tiles come from
	-- System.getBundleList(tab,search) ({name,tab,active}); a normal click applies (System.applyBundle) and - when an
	-- Options action is armed on UI._detectingBundle - the click instead COPIES (exportBundle name,"clipboard") or
	-- DELETES (deleteBundle + clearBundle if it was the active one) that bundle, then disarms. The renderer is registered
	-- onto System.renderBundles (hotSwap re-paint) and stashed on UI._renderBundles. Engine tab ids: community/mine/clothing/preset.
	local TAB_IDS = { "community", "mine", "clothing", "preset" }
	local TAB_LABELS = { community = "Community", mine = "Mine", clothing = "Clothing", preset = "Presets" }
	local render  -- forward; the seg/search closures capture it
	local _tabIdx = 1
	do  -- seed the active tab from the engine (mirrors V2 L4293-4296)
		local at = System and System.getActiveBundleTab and System.getActiveBundleTab()
		if at then for i, id in ipairs(TAB_IDS) do if id == at then _tabIdx = i; break end end end
	end
	local _tab = TAB_IDS[_tabIdx]
	local _search = ""
	if System and System.setBundleTab then System.setBundleTab(_tab) end
	-- per-segment count badges (read once from the engine, like the old mock's bcounts; counts are total-per-tab)
	local _counts = (System and System.getBundleCounts and System.getBundleCounts()) or {}
	local bcounts = { _counts.community or 0, _counts.mine or 0, _counts.clothing or 0, _counts.preset or 0 }
	-- STICKY: a detect-hint banner (shown only when an Options action is armed) + the 4-way seg + search pin above the grid
	local sw = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = sticky }); pad(sw, 14, 10, 4, 8); vlist(sw, 8)
	local hint = new("Frame", { BackgroundColor3 = Color3.fromRGB(40, 30, 18), BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Visible = false, Parent = sw }); corner(hint, 8); stroke(hint, T.warn, 1); pad(hint, 10, 10, 7, 7)
	local hintLbl = lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = "", TextColor3 = T.warn, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = hint })
	UI.seg(sw, { "Community", "Mine", "Clothing", "Presets" }, 2, function(o, i) _tab = TAB_IDS[i] or "community"; if System and System.setBundleTab then System.setBundleTab(_tab) end; if render then render() end end, _tabIdx, nil, bcounts)
	UI.field(sw, "Search bundles", "", 3, true, function(t) _search = t or ""; if render then render() end end, nil, true)
	-- actions (scroll): Save Outfit (accent primary) | Export Bundle | Manage Deleted
	local ab = cols(h, 1, 3)
	UI.button(ab[1], "Save Outfit", "primary", 1, saveOutfitDialog)
	UI.button(ab[2], "Export Bundle", nil, 1, exportBundleDialog)
	UI.button(ab[3], "Manage Deleted", nil, 1, function() if UI._manageDeletedDialog then UI._manageDeletedDialog() end end)
	-- empty-state label + grid host live in the scrolling body; render clears+rebuilds only the grid host
	local emptyLbl = lbl({ Name = "Empty", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3, Text = "", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Visible = false, Parent = h })
	local gridWrap = new("Frame", { Name = "BundlesGridWrap", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = h })
	render = function()
		if not (gridWrap and gridWrap.Parent) then return end
		for _, c in ipairs(gridWrap:GetChildren()) do c:Destroy() end
		-- reflect any armed Options bundle action in the hint banner (mirrors V2 L4350-4361)
		local armed = UI._detectingBundle
		if armed == "delete" then hintLbl.Text = "Click a bundle below to DELETE it."; hint.Visible = true
		elseif armed == "export_copy" then hintLbl.Text = "Click a bundle below to COPY its template to the clipboard."; hint.Visible = true
		else hint.Visible = false end
		local list = (System and System.getBundleList and System.getBundleList(_tab, _search)) or {}
		local items = {}
		for _, e in ipairs(list) do
			local nm = e.name
			items[#items + 1] = {
				name = nm,
				sub = TAB_LABELS[e.tab] or e.tab,
				badge = e.active and "ACTIVE" or nil,
				badgeColor = T.accent,
				-- tile click: consume an armed Options action (copy/delete THIS bundle, then disarm) else apply it (V2 L4370-4395)
				onClick = function()
					local mode = UI._detectingBundle
					if mode == "export_copy" then
						UI._detectingBundle = nil
						if System and System.exportBundle then
							task.spawn(function()
								local msg = System.exportBundle(nm, "clipboard")
								toast("Copy Template", tostring(msg or "Copied."), "ok")
							end)
						end
						if render then render() end
					elseif mode == "delete" then
						UI._detectingBundle = nil
						if System and System.deleteBundle then
							System.deleteBundle(nm)
							-- if the deleted bundle was the active one, clear live state + hotSwap (V2 L4384-4388)
							if System.getPD and System.clearBundle and (System.getPD("CurrentBundle") == nm or System.getPD("CurrentPreset") == nm) then
								System.clearBundle()
							end
							toast("Delete Bundle", 'Deleted "' .. nm .. '".', "warn")
						end
						if render then render() end
					elseif System and System.applyBundle then
						System.applyBundle(nm)
						if render then render() end
					end
				end,
			}
		end
		UI.tiles(gridWrap, items, 1, 64)
		if #list == 0 then
			emptyLbl.Text = (_search ~= "" and ('No bundles match "' .. _search .. '".')) or ("No " .. (TAB_LABELS[_tab] or _tab) .. " bundles yet.")
			emptyLbl.Visible = true
		else
			emptyLbl.Visible = false
		end
	end
	UI._renderBundles = render
	if System then System.renderBundles = render end  -- mirror V2 L4406 (hotSwap re-fires this)
	render()
end
function PAGES.edit(h)
	-- GIZMO / 3D-transform tab, WIRED to the real engine bridge (mirrors V2 Pages.edit L4420-4716).
	-- Reuse-not-rebuild: _reseedAll pushes the LIVE offset back into the EXISTING sliders + Properties in
	-- place; it is registered via System.gizmoRegisterRefresher so the engine's own reset/mutation paths
	-- (System.doReset iterating GizmoSliderRefreshers) re-sync this page too. NEVER rebuild the sliders.
	local Sy = System
	-- CLONE MANAGER (V4.5.x): spawn/select/remove frozen 1:1 copies; selecting one retargets the whole hub.
	do
		local ct = tile(h, "Clones", 0)
		UI.hint(ct, "Spawn a frozen 1:1 copy of your current look; tap one to edit it (the whole hub retargets to it). Your own avatar is never touched.", 1)
		local cbtns = cols(ct, 2, 2)
		local _renderClones
		UI.button(cbtns[1], "Spawn Clone", "primary", 1, function()
			local key = Sy and Sy.spawnClone and Sy.spawnClone()
			toast("Clones", key and ("Spawned " .. key .. ".") or "Couldn't spawn (no character?).", key and "ok" or "warn")
			if _renderClones then _renderClones() end
		end)
		UI.button(cbtns[2], "Clear All", nil, 1, function()
			if Sy and Sy.clearClones then Sy.clearClones() end
			if _renderClones then _renderClones() end
			toast("Clones", "Cleared all clones.", "info")
		end)
		local clist = new("Frame", { Name = "CloneList", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3, Parent = ct }); vlist(clist, 6)
		local _selCtl = new("Frame", { Name = "CloneSelCtl", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 4, Parent = ct }); vlist(_selCtl, 6)
		_renderClones = function()
			if not (clist and clist.Parent) then return end
			for _, c in ipairs(clist:GetChildren()) do if c:IsA("Frame") or c:IsA("TextButton") then c:Destroy() end end
			for _, c in ipairs(_selCtl:GetChildren()) do if not c:IsA("UIListLayout") then c:Destroy() end end
			local rows = (Sy and Sy.getCloneList and Sy.getCloneList()) or {}
			for i, e in ipairs(rows) do
				local r = rowShell(clist, 32, i)
				local isClone = (e.label ~= "Self")
				local hit = new("TextButton", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(1, isClone and -34 or -4, 1, 0), BackgroundColor3 = e.selected and T.cardHi or T.card, AutoButtonColor = false, Text = "", Parent = r }); corner(hit, 7); stroke(hit, e.selected and T.accent or T.line, e.selected and 1.5 or 1)
				lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 10, 0.5, 0), Size = UDim2.new(1, -14, 1, 0), Text = e.label .. (e.selected and "  (editing)" or ""), TextXAlignment = Enum.TextXAlignment.Left, TextColor3 = e.selected and T.txt or T.txt2, Parent = hit })
				hit.MouseButton1Click:Connect(function()
					if Sy and Sy.setSelect then Sy.setSelect(e.key) end
					if _renderClones then _renderClones() end
				end)
				if isClone then
					local xb = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -2, 0.5, 0), Size = UDim2.fromOffset(28, 28), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "x", Font = FONTB, TextColor3 = T.txt2, TextSize = 13, Parent = r }); corner(xb, 7); stroke(xb, T.line, 1)
					xb.MouseButton1Click:Connect(function()
						if Sy and Sy.removeClone then Sy.removeClone(e.key) end
						if _renderClones then _renderClones() end
					end)
				end
			end
			-- selected-clone controls: rename + hide-name + rotate (drag repositions; these turn/label it)
			local selKey, selHidden, selName
			for _, e in ipairs(rows) do if e.selected and e.label ~= "Self" then selKey, selHidden, selName = e.key, e.nameHidden, e.label end end
			if selKey then
				local rr = rowShell(_selCtl, 34, 1)
				local tb = new("TextBox", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(1, -4, 1, 0), BackgroundColor3 = T.card, Text = selName or "", PlaceholderText = "Rename this clone...", ClearTextOnFocus = false, Font = FONTB, TextSize = 13, TextColor3 = T.txt, TextXAlignment = Enum.TextXAlignment.Left, Parent = rr }); corner(tb, 7); stroke(tb, T.line, 1)
				local _pad = Instance.new("UIPadding"); _pad.PaddingLeft = UDim.new(0, 10); _pad.Parent = tb
				tb.FocusLost:Connect(function()
					if Sy and Sy.renameClone then Sy.renameClone(selKey, tb.Text) end
					if _renderClones then _renderClones() end
				end)
				local possessing = Sy and Sy.isPossessing and Sy.isPossessing(selKey)
				local br = cols(_selCtl, 2, 2)
				local nb = new("TextButton", { Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = selHidden and T.card or T.cardHi, AutoButtonColor = false, Text = selHidden and "Name: hidden" or "Name: shown", Font = FONTB, TextSize = 12, TextColor3 = T.txt2, Parent = br[1] }); corner(nb, 7); stroke(nb, selHidden and T.line or T.accent, 1)
				nb.MouseButton1Click:Connect(function()
					if Sy and Sy.setCloneNameHidden then Sy.setCloneNameHidden(selKey, not selHidden) end
					if _renderClones then _renderClones() end
				end)
				-- Possess: directly walk/turn the clone (WASD + mouse), then release to re-freeze it here.
				local pb = new("TextButton", { Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = possessing and T.cardHi or T.card, AutoButtonColor = false, Text = possessing and "Release control" or "Possess (WASD)", Font = FONTB, TextSize = 12, TextColor3 = possessing and T.txt or T.txt2, Parent = br[2] }); corner(pb, 7); stroke(pb, possessing and T.accent or T.line, possessing and 1.5 or 1)
				pb.MouseButton1Click:Connect(function()
					if not Sy then return end
					if possessing then if Sy.releaseClone then Sy.releaseClone() end
					else if Sy.possessClone then Sy.possessClone(selKey) end end
					if _renderClones then _renderClones() end
				end)
				-- Copy my look: re-sync a stale clone to whatever YOU are currently wearing (one tap).
				local cr = rowShell(_selCtl, 32, 3)
				local cb = new("TextButton", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = T.cardHi, AutoButtonColor = false, Text = "Copy my look onto this clone", Font = FONTB, TextSize = 12, TextColor3 = T.txt, Parent = cr }); corner(cb, 7); stroke(cb, T.accent, 1)
				cb.MouseButton1Click:Connect(function()
					local ok = Sy and Sy.syncCloneFromSelf and Sy.syncCloneFromSelf(selKey)
					toast("Edit", ok and "Clone updated to your current look." or "Couldn't copy look.", ok and "ok" or "warn")
					if _renderClones then _renderClones() end
				end)
			end
		end
		if Sy then Sy.renderCloneList = _renderClones end
		_renderClones()
	end
	local _paintTargetBtn, _reseedAll  -- forwards (assigned below; used by click closures at runtime)
	local L, R = bentoCols(h, 1, 0.5)
	-- LEFT: Target
	local tg = tile(L, "Target", 1)
	UI.hint(tg, "Tap a body part below. Torso = whole body; an arm/leg/head moves only itself.", 1)
	-- BODY MAP selector (like the game's JointSelector). A front-facing humanoid of tappable parts.
	-- Mirrored (front view) so the on-screen side matches the avatar you see: the viewer-LEFT column
	-- is the character's RIGHT limb. Each tap targets that part's rig joint + spawns the 3D handles.
	local _bmAccent = T.accent or Color3.fromRGB(80, 120, 220)
	local bmBtns, bmResolved = {}, {}  -- bmResolved: canonical slot -> the actual rig part it mapped to (R15), for the highlight
	local bmap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 178), LayoutOrder = 2, Parent = tg })
	local bmIn = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.new(0, 148, 0, 168), BackgroundTransparency = 1, Parent = bmap })
	for _, pinfo in ipairs({
		{ "Head", 0.50, 0.12, 0.30, 0.17 }, { "Torso", 0.50, 0.42, 0.36, 0.36 },
		{ "Right Arm", 0.18, 0.42, 0.16, 0.36 }, { "Left Arm", 0.82, 0.42, 0.16, 0.36 },
		{ "Right Leg", 0.39, 0.81, 0.17, 0.30 }, { "Left Leg", 0.61, 0.81, 0.17, 0.30 },
	}) do
		local key = pinfo[1]
		local b = new("TextButton", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(pinfo[2], 0, pinfo[3], 0), Size = UDim2.new(pinfo[4], 0, pinfo[5], 0), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "", Parent = bmIn })
		corner(b, 7); stroke(b, T.line, 1)
		bmBtns[key] = b
		b.MouseButton1Click:Connect(function()
			if not (Sy and Sy.setGizmoTarget) then return end
			local targets = (Sy.getGizmoTargets and Sy.getGizmoTargets()) or {}
			-- Resolve the canonical slot to the actual rig part. R6: exact ("Torso"->"Torso"). R15: closest part
			-- (Torso->LowerTorso = whole-body root; Left Arm->LeftUpperArm = shoulder; Left Leg->LeftUpperLeg = hip).
			local resolved
			for _, t in ipairs(targets) do if t.key == key then resolved = t.key; break end end
			if not resolved then
				local kl = key:lower()
				local side = (kl:find("left") and "left") or (kl:find("right") and "right") or nil
				local limb = (kl:find("arm") and "arm") or (kl:find("leg") and "leg") or (kl:find("torso") and "torso") or (kl:find("head") and "head") or nil
				local pref = (limb == "torso") and "lower" or "upper"  -- torso->LowerTorso (root joint); arm/leg->Upper (shoulder/hip)
				local best
				for _, t in ipairs(targets) do
					local tl = t.key:lower()
					if ((not side) or tl:find(side)) and ((not limb) or tl:find(limb)) then
						if tl:find(pref) then best = t.key; break elseif not best then best = t.key end
					end
				end
				resolved = best
			end
			if not resolved then toast("Gizmo", key .. " is not on this rig (no matching part).", "warn"); return end
			bmResolved[key] = resolved
			Sy.setGizmoTarget(resolved)
			if Sy.showGizmo3D then Sy.showGizmo3D() end
			_paintTargetBtn()
		end)
	end
	local sgtCap = lbl({ Size = UDim2.new(1, 0, 0, 18), Text = "Tap a body part", Font = FONTB, TextColor3 = T.txt2, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Center, LayoutOrder = 3, Parent = tg })
	-- (V4.5.x) Preset name / Save-Load-Delete Preset + Clear/Export/Multi removed per owner request
	-- (part of the old gizmo system being reworked). 'Set Gizmo Target' above is kept.
	-- RIGHT: Transform -- RIG POSER controls (gizmo-only; the old X/Y/Z sliders are gone).
	-- Pick a body target on the left, choose Move or Rotate, then DRAG the 3D handles in the
	-- world. Snap step = the game "0.001 studs / degrees" smoothness (0.001 = smooth, higher
	-- = coarser precise steps). Move edits the joint C0 -> the rig hierarchy moves everything.
	local tr = tile(R, "Transform", 1)
	UI.hint(tr, "Pick a body target, choose Move or Rotate, then drag the 3D handles in the world.", 1)
	local _accent = T.accent or Color3.fromRGB(80, 120, 220)
	local mvBtn, rotBtn
	local function _paintMode()
		local m = (Sy and Sy.getGizmoMode3D and Sy.getGizmoMode3D()) or "Pos"
		local function _pb(b, on)
			if not b then return end
			b.BackgroundColor3 = on and _accent or T.card
			local st = b:FindFirstChildOfClass("UIStroke"); if st then st.Color = on and _accent or T.line end
			local l = b:FindFirstChildWhichIsA("TextLabel"); if l then l.TextColor3 = on and Color3.fromRGB(255,255,255) or T.txt2 end
		end
		_pb(mvBtn, m == "Pos"); _pb(rotBtn, m == "Rot")
	end
	local _mrow = cols(tr, 2, 2)
	mvBtn = new("TextButton", { Size = UDim2.new(1, 0, 0, 36), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "Move", Font = FONTB, TextSize = 14, TextColor3 = T.txt2, Parent = _mrow[1] }); corner(mvBtn, 9); stroke(mvBtn, T.line, 1)
	rotBtn = new("TextButton", { Size = UDim2.new(1, 0, 0, 36), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "Rotate", Font = FONTB, TextSize = 14, TextColor3 = T.txt2, Parent = _mrow[2] }); corner(rotBtn, 9); stroke(rotBtn, T.line, 1)
	mvBtn.MouseButton1Click:Connect(function() if Sy and Sy.setGizmoMode3D then Sy.setGizmoMode3D("Pos") end _paintMode() end)
	rotBtn.MouseButton1Click:Connect(function() if Sy and Sy.setGizmoMode3D then Sy.setGizmoMode3D("Rot") end _paintMode() end)
	_paintMode()
	UI.field(tr, "Snap step", tostring((Sy and Sy.getGizmoStep and Sy.getGizmoStep()) or 0.001), 3, true, function(v)
		local n = tonumber((tostring(v or "")):match("[%d%.]+"))
		if n and Sy and Sy.setGizmoStep then Sy.setGizmoStep(n) end
	end)
	-- ACTIONS: Reset Pose | Hide Gizmo -- parented to the RIGHT column (below Transform) so it fills
	-- the empty space under the short Transform tile instead of sitting full-width below both columns.
	local ac = tile(R, "Actions", 2)
	local a1 = cols(ac, 1, 2)
	UI.button(a1[1], "Reset Pose", nil, 1, function()
		if Sy and Sy.resetGizmoPose then Sy.resetGizmoPose() end
		if Sy and Sy.hideGizmo3D then Sy.hideGizmo3D() end
		toast("Edit", "Pose reset + animations restored.", "ok")
	end)
	UI.button(a1[2], "Hide Gizmo", nil, 1, function()
		if Sy and Sy.hideGizmo3D then Sy.hideGizmo3D() end
		toast("Edit", "Gizmo hidden.", "info")
	end)
	-- (rig poser has no per-axis offset readout; these helpers are kept as no-ops for callers)
	_reseedAll = function() _paintTargetBtn() end
	-- ── live captions ─────────────────────────────────────────────────────────────────────────────────
	_paintTargetBtn = function()
		local cur = Sy and Sy.getGizmoTarget and Sy.getGizmoTarget()
		if sgtCap then sgtCap.Text = cur and ("Selected: " .. cur) or "Tap a body part" end
		for key, b in pairs(bmBtns) do
			local on = (cur == key) or (bmResolved[key] == cur and cur ~= nil)  -- R6 exact OR the R15-resolved part
			b.BackgroundColor3 = on and _bmAccent or T.card
			local st = b:FindFirstChildOfClass("UIStroke"); if st then st.Color = on and _bmAccent or T.line; st.Thickness = on and 2 or 1 end
		end
	end
	-- initial paint + seed, then expose render + refresher hooks (mirror V2 L4678 refresher / L4714-4715 renderEdit)
	_paintTargetBtn(); _reseedAll()
	local function _render() _paintTargetBtn(); _reseedAll() end
	UI._renderEdit = _render; UI._reseedGizmo = _reseedAll  -- stashed on UI (no new main-chunk locals)
	if Sy then
		if Sy.gizmoUnregisterRefresher and UI._gizmoRefresher then Sy.gizmoUnregisterRefresher(UI._gizmoRefresher) end  -- drop the prior Edit-page refresher (page is rebuilt every nav visit) so dead closures don't accumulate
		UI._gizmoRefresher = _reseedAll
		if Sy.gizmoRegisterRefresher then Sy.gizmoRegisterRefresher(_reseedAll) end
		Sy.renderEdit = _render
	end
end
function PAGES.settings(h)
	-- BENTO: the six toggles split into two themed columns (long labels need the column width), Diagnostics full-width below.
	local L, R = bentoCols(h, 1, 0.5)
	local function _gp(f) return System and System.getPD and System.getPD(f) end
	local tg = tile(L, "Toggles", 1)
	UI.toggle(tg, "Mesh Size Lock", (_gp("MeshSizeLock") and true) or false, 1, function(st) if System and System.setPD then System.setPD("MeshSizeLock", st) end end)
	UI.toggle(tg, "Accessory Size Lock", (_gp("AccessorySizeLock") and true) or false, 2, function(st) if System and System.setPD then System.setPD("AccessorySizeLock", st) end end)
	UI.toggle(tg, "Mesh Base Part Invisible", (_gp("MeshBasePartInvisible") and true) or false, 3, function(st) if System and System.setPD then System.setPD("MeshBasePartInvisible", st) end end)
	local bh = tile(R, "Behaviour", 1)
	UI.toggle(bh, "Avatar Sync (BETA)", (System and System.getAvatarSync and System.getAvatarSync()) and true or false, 1, function(st) if System and System.setAvatarSync then System.setAvatarSync(st) end end)
	UI.toggle(bh, "Click Execute", (System and System.getClickExecute and System.getClickExecute()) and true or false, 2, function(st) if System and System.setClickExecute then System.setClickExecute(st) end end)
	UI.toggle(bh, "Realtime Body Transparency", (_gp("RealtimeBodyTransparency") and true) or false, 3, function(st) if System and System.setPD then System.setPD("RealtimeBodyTransparency", st) end end)
	local dg = tile(h, "Diagnostics", 2)  -- full-width under the two columns
	UI.hint(dg, "Anonymous telemetry - no account data.", 1)
	UI.toggle(dg, "Anonymous telemetry", (System and System.getTelemEnabled and System.getTelemEnabled()) and true or false, 2, function(st) if System and System.setTelemEnabled then System.setTelemEnabled(st) end end)
	local db = cols(dg, 3, 2)
	UI.button(db[1], "View Pending", nil, 1, function() local n = (System and System.diagPendingCount and System.diagPendingCount()) or 0; toast("Telemetry", n .. " event(s) pending upload.", "info") end)
	UI.button(db[2], "Send Now", nil, 1, function() local n = (System and System.diagPendingCount and System.diagPendingCount()) or 0; if n == 0 then toast("Telemetry", "Nothing to send.", "info") else if System and System.diagSendNow then System.diagSendNow() end; toast("Telemetry", "Sent " .. n .. " event(s).", "ok") end end)
end
function PAGES.player(h)
	-- REDESIGN - BENTO of section TILES, each sized to its content. Small Target + medium Actions stack in a narrow
	-- left column; the content-heavy Loadout is the big wide tile on the right. Sections share the grid; sizes vary.
	local L, R = bentoCols(h, 1, 0.4)
	-- LEFT column: Target (small tile) then Actions (medium tile)
	local tg = tile(L, "Target", 1)
	-- WIRED (Phase 2): real roster snapshot (Self + connected peers). onPick -> System.setSelect + engine PlayerExecute.Text.
	do
		local _plist = { "Self (you)" }
		for _, _p in ipairs(PS:GetPlayers()) do if _p ~= LocalPlayer then table.insert(_plist, _p.Name) end end
		UI.dropdown(tg, "Player", _plist, 1, function(o)
			local nm = (o == "Self (you)") and "Self" or o
			local disp = (System and System.setSelect) and System.setSelect(nm) or nm
			if GUIObject.PlayerExecute then GUIObject.PlayerExecute.Text = (nm == "Self") and "Self" or (disp or nm) end
		end)
	end
	local ac = tile(L, "Actions", 2)
	UI.button(ac, "Execute", "primary", 1, function() if System and System.doExecute then System.doExecute() end end)  -- natural height; the primary accent fill already marks it as the CTA
	UI.button(ac, "Reset", nil, 2, function() if System and System.doReset then System.doReset() end end)
	-- WIRED (Phase 4 DONE): Auto Execute -> System.setAutoExecute (restores V1's Settings.json persist + local-only peer-guard); setPD fallback for safety.
	UI.toggle(ac, "Auto Execute", (System and System.getPD and System.getPD("AutoExecute")) or false, 3, function(st) if System and System.setAutoExecute then System.setAutoExecute(st) elseif System and System.setPD then System.setPD("AutoExecute", st) end end)
	-- RIGHT column: Loadout (the biggest tile - it holds the most)
	local lo = tile(R, "Loadout", 1)
	local ff = cols(lo, 1, 2)  -- Bundle + Delay
	do  -- Bundle field: display-only, seeded from current bundle (set from the Bundles tab)
		local _bcur = System and System.getPD and System.getPD("CurrentBundle")
		UI.field(ff[1], "Bundle", (_bcur and _bcur ~= "nil" and tostring(_bcur)) or "nil", 1, false)
	end
	do  -- Delay field: editable -> System.setDelay (tonumber; skips non-numeric), seeded from pd.DelayTime
		local _dcur = System and System.getPD and System.getPD("DelayTime")
		UI.field(ff[2], "Delay", (_dcur ~= nil and tostring(_dcur)) or "1", 1, true, function(v) if System and System.setDelay then System.setDelay(v) end end)
	end
	local RM = { { "Method 1", "Standard", "Direct swap. Fastest; best for most avatars." }, { "Method 2", "Proxy", "Rig proxy. Best fidelity for layered meshes." }, { "Method 3", "First Person", "First-person view; hides your own head." } }
	local mdesc
	-- WIRED: Render method -> System.setMethod(1..3); seg seeded from System.getMethod()
	local _curMethod = (System and System.getMethod and System.getMethod()) or 1
	if _curMethod < 1 or _curMethod > 3 then _curMethod = 1 end
	UI.seg(lo, { RM[1][1], RM[2][1], RM[3][1] }, 2, function(o, i) if mdesc then mdesc.Text = RM[i][2] .. " - " .. RM[i][3] end; if System and System.setMethod then System.setMethod(i) end end, _curMethod)  -- natural seg height
	mdesc = lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = RM[_curMethod][2] .. " - " .. RM[_curMethod][3], TextColor3 = T.txt3, TextSize = 11, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 3, Parent = lo })
	-- WIRED: Bundle Body Color / Face -> momentary buttons that TOGGLE the boolean PD field (read via getPD, write inverse)
	UI.button(lo, "Bundle Body Color", nil, 4, function() if System and System.setPD then System.setPD("BundleBodyColor", not (System.getPD and System.getPD("BundleBodyColor"))) end end)  -- natural height (stacked; no fill-to-match tuning)
	UI.button(lo, "Face", nil, 5, function() if System and System.setPD then System.setPD("Face", not (System.getPD and System.getPD("Face"))) end end)
end
function PAGES.recolor(h)
	-- WIRED (merge): real engine-driven recolour list. Mirrors V2 Pages._renderRecolor - one row per recolourable slot
	-- of the equipped clothes, from System.getRecolorRows() ({cloth,slot,current,default}). Tapping a swatch opens V3's
	-- HSV picker (openColorPicker) seeded from the current colour; on Apply -> System.setRecolor(cloth,slot,color). The
	-- reset (x) clears the slot -> System.resetRecolor(cloth,slot) + re-render. render is registered onto
	-- System.renderRecolorList (like V2 L2914) so the engine's equip/setType tail re-fires it after a cloth change.
	UI.hint(h, "Auto-fills from equipped clothes; tap a swatch to recolour a part, or x to reset it.", 1)
	local list = new("Frame", { Name = "RecolorList", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = h }); vlist(list, 8)
	local empty = lbl({ Name = "Empty", Visible = false, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 9999, Text = "", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = list })
	local render
	-- one recolour row: colour chip (opens the HSV picker) + "cloth slot" label + reset (x). Built from V3 primitives
	-- (V3's UI has no lrow), targeting System.setRecolor / System.resetRecolor exactly like V2's UI.lrow recolor row.
	local function _row(cloth, slot, curCol, order)
		local r = rowShell(list, 42, order)
		local chip = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(26, 26), BackgroundColor3 = curCol or T.accent, BorderSizePixel = 0, Parent = r }); corner(chip, 7); stroke(chip, T.line, 1)
		lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 36, 0.5, 0), Size = UDim2.new(1, -36 - 34, 1, 0), Text = cloth .. " " .. slot, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = r })
		local xb = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -4, 0.5, 0), Size = UDim2.fromOffset(24, 24), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "x", Font = FONTB, TextColor3 = T.txt2, TextSize = 13, Parent = r }); corner(xb, 7); local xs = stroke(xb, T.line, 1)
		xb.MouseEnter:Connect(function() tween(xb, 0.18, { BackgroundColor3 = T.cardHi }); tween(xs, 0.18, { Color = T.bad }) end)
		xb.MouseLeave:Connect(function() tween(xb, 0.18, { BackgroundColor3 = T.card }); tween(xs, 0.18, { Color = T.line }) end)
		-- chip hit area (left) opens the picker; on Apply -> setRecolor + repaint the chip.
		local hit = new("TextButton", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(40, 42), BackgroundTransparency = 1, AutoButtonColor = false, Text = "", Parent = r })
		hit.MouseButton1Click:Connect(function()
			openColorPicker(chip.BackgroundColor3, function(c)
				chip.BackgroundColor3 = c
				if System and System.setRecolor then System.setRecolor(cloth, slot, c) end
			end)
		end)
		xb.MouseButton1Click:Connect(function()
			if System and System.resetRecolor then System.resetRecolor(cloth, slot) end
			if render then render() end
		end)
	end
	render = function()
		if not (list and list.Parent) then return end  -- stale page guard
		for _, c in ipairs(list:GetChildren()) do
			if c:IsA("Frame") or c:IsA("TextButton") then c:Destroy() end  -- keep layout + Empty (a TextLabel); drop only row shells
		end
		local rows = (System and System.getRecolorRows and System.getRecolorRows()) or {}
		if #rows == 0 then
			empty.Text = "Nothing to recolour. Equip a cloth that has recolourable parts."
			empty.Visible = true
			return
		end
		empty.Visible = false
		for i, row in ipairs(rows) do
			_row(row.cloth, row.slot, row.current or row.default, i)
		end
	end
	if System then System.renderRecolorList = render end  -- register (mirrors V2 L2914) so the engine re-fires on hotSwap/equip
	render()
end
function PAGES.damage(h)
	-- BENTO: Shirt | Pants as symmetric tiles (tear slider + ripped-id field each); then Damage SFX (fields + toggles
	-- paired), Auto-Strip (cycler + Configure reveal with per-cloth strip cyclers 2-up), and Per-cloth HP cyclers 2-up.
	local L, R = bentoCols(h, 1, 0.5)
	-- Phase 2 wiring helpers (Damage): seed fields/toggles/sliders from engine PlayerData.
	local function _gp(f) return System and System.getPD and System.getPD(f) end
	local function _num(f, d) local v = _gp(f); return (type(v) == "number") and v or d end
	local function _seed(f) local v = _gp(f); return (v ~= nil and v ~= "") and tostring(v) or "" end
	local function _hpSeed(k) local hp = _gp("HPClothes"); local v = type(hp) == "table" and hp[k]; return ((type(v) == "string" or type(v) == "number") and v ~= "" and tostring(v)) or "" end  -- BUGFIX: same boolean-false seed as _catCloth ("false" leaked into the field when HPClothes was nil/non-table). Type-check v.
	local sh = tile(L, "Shirt", 1)
	UI.slider(sh, "Shirt tears at % HP", _num("TopHP", 50), 0, 150, 1, function(v) if System and System.setPDNum then System.setPDNum("TopHP", v) end end)  -- V4.5.17: max 100->150 (owner request). NOTE: the 5th arg is max (the `1` is LayoutOrder, not a step). >100 only bites in Hardcore HP (a bigger flat durability pool); normal mode caps at 100% damage so 101-150 never tears there.
	UI.field(sh, "Ripped Shirt Id", _hpSeed("Shirt"), 2, true, function(t) if System and System.setHPClothes then System.setHPClothes("Shirt", t) end end)
	local pt = tile(R, "Pants", 1)
	UI.slider(pt, "Pants tear at % HP", _num("BottomHP", 50), 0, 150, 1, function(v) if System and System.setPDNum then System.setPDNum("BottomHP", v) end end)  -- V4.5.17: max 100->150 (owner request); see the Shirt slider note above re: Hardcore-only meaningfulness.
	UI.field(pt, "Ripped Pants Id", _hpSeed("Pants"), 2, true, function(t) if System and System.setHPClothes then System.setHPClothes("Pants", t) end end)
	local sx = tile(h, "Damage SFX & Particles", 2)
	local sf = cols(sx, 1, 2)
	UI.field(sf[1], "Damage SFX Id", _seed("DamageSFX"), 1, true, function(t) if System and System.setPDNum then System.setPDNum("DamageSFX", t) end end)
	UI.field(sf[2], "Volume", (_seed("Volume") ~= "" and _seed("Volume")) or "1", 1, true, function(t) if tonumber(t) and System and System.setPD then System.setPD("Volume", tonumber(t)) end end)
	local tp = cols(sx, 2, 2)
	UI.toggle(tp[1], "Tear Particles", (_gp("TearParticles") and true) or false, 1, function(st) if System and System.setPD then System.setPD("TearParticles", st) end end)
	UI.toggle(tp[2], "Heal Particles", (_gp("HealParticles") and true) or false, 1, function(st) if System and System.setPD then System.setPD("HealParticles", st) end end)
	UI.toggle(sx, "Clothing Hardcore HP", (_gp("HardcoreHP") and true) or false, 3, function(st) if System and System.setPD then System.setPD("HardcoreHP", st) end end)
	local as = tile(h, "Auto-Strip on Rip", 3)
	local ar = cols(as, 1, 2)
	-- WIRED (merge): Auto-Strip cycler seeded from System.getAutoStripOnRip(); each toggle flips System.toggleAutoStripOnRip()
	-- (OFF/ON stay in step because both advance one boolean, seeded from the same live value). Mirrors V2 L3892.
	do
		local _asOn = (System and System.getAutoStripOnRip and System.getAutoStripOnRip()) or false
		UI.cyc(ar[1], "Auto-Strip", { "OFF", "ON" }, 1, function() if System and System.toggleAutoStripOnRip then System.toggleAutoStripOnRip() end end, _asOn and "ON" or "OFF")
	end
	local cfgG = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Visible = false, LayoutOrder = 2, Parent = as }); vlist(cfgG, 7)
	-- WIRED (merge): per-cloth strip rows rebuilt from System.getStripRows() ({cloth,mode}); each cycler steps the
	-- engine's None->Top->Bottom->Both->None via System.cycleStrip(cloth) (the fixed values list matches that order,
	-- seeded from the live mode). Registered on System.renderStripList so the engine re-fires it after equip changes
	-- (mirrors V2 L3907/L3927). Replaces the old demo strip loop with live getStripRows.
	local _stripEmpty = lbl({ Name = "Empty", Visible = false, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 9999, Text = "", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = cfgG })
	local function _renderStrip()
		if not (cfgG and cfgG.Parent) then return end
		for _, c in ipairs(cfgG:GetChildren()) do if c:IsA("Frame") then c:Destroy() end end  -- keep the vlist + Empty (a TextLabel)
		local rows = (System and System.getStripRows and System.getStripRows()) or {}
		if #rows == 0 then _stripEmpty.Text = "Equip a cloth to configure auto-strip."; _stripEmpty.Visible = true; return end
		_stripEmpty.Visible = false
		for i = 1, #rows, 2 do
			local cc = cols(cfgG, i, 2)
			for k = 0, 1 do
				local row = rows[i + k]
				if row then local _cl = row.cloth; UI.cyc(cc[k + 1], "Strip " .. _cl, { "None", "Top", "Bottom", "Both" }, 1, function() if System and System.cycleStrip then System.cycleStrip(_cl) end end, row.mode) end
			end
		end
	end
	if System then System.renderStripList = _renderStrip end
	UI.button(ar[2], "Configure…", nil, 1, function()  -- toggles the per-cloth strip panel; rebuilds on open (V2 L3903)
		local willShow = not cfgG.Visible
		if willShow then _renderStrip() end
		UI.reveal(cfgG, willShow, true)
	end)
	_renderStrip()
	local hp = tile(h, "Per-cloth HP", 4)
	UI.hint(hp, "Cycle each equipped item (and accessory): None -> TopHP -> BottomHP -> InverseTop -> InverseBottom.", 1)
	local HP_MODES = { "None", "TopHP", "BottomHP", "InverseTop", "InverseBottom" }  -- list index = engine HP state (0..4) + 1
	-- WIRED (merge): per-cloth + per-accessory HP rows rebuilt from System.getHPRows() ({label,state,accessory}); each
	-- cycler steps None->TopHP->BottomHP->InverseTop->InverseBottom via System.cycleClothHP(label, accessory) (values
	-- list matches the engine's 0..4 order, seeded from row.state). Registered on System.renderHPList so the engine
	-- re-fires it after equip changes (mirrors V2 L3939/L3959). Replaces the old demo HP loop with live getHPRows.
	local hpG = new("Frame", { Name = "HPList", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = hp }); vlist(hpG, 7)
	local _hpEmpty = lbl({ Name = "Empty", Visible = false, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 9999, Text = "", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = hpG })
	local function _renderHP()
		if not (hpG and hpG.Parent) then return end
		for _, c in ipairs(hpG:GetChildren()) do if c:IsA("Frame") then c:Destroy() end end  -- keep the vlist + Empty (a TextLabel)
		local rows = (System and System.getHPRows and System.getHPRows()) or {}
		if #rows == 0 then _hpEmpty.Text = "Equip a cloth or wear an accessory to set per-item HP."; _hpEmpty.Visible = true; return end
		_hpEmpty.Visible = false
		for i = 1, #rows, 2 do
			local hc = cols(hpG, i, 2)
			for k = 0, 1 do
				local row = rows[i + k]
				if row then local _lb, _acc = row.label, row.accessory; UI.cyc(hc[k + 1], _lb, HP_MODES, 1, function() if System and System.cycleClothHP then System.cycleClothHP(_lb, _acc) end end, HP_MODES[(row.state or 0) + 1]) end
			end
		end
	end
	if System then System.renderHPList = _renderHP end
	_renderHP()
end
function PAGES.options(h)
	-- BENTO: On Loadup | Keybinds as balanced columns, a full-width Save, then a Bundle & Content tile with the buttons
	-- paired 2-up (long labels shortened so they fit half-width), and Danger on its own. Scrolls (heavy tab) - fine.
	local L, R = bentoCols(h, 1, 0.5)
	local ol = tile(L, "On Loadup", 1)
	UI.toggle(ol, "Close UI on Loadup", (System and System.getLoadup and System.getLoadup("Closed")) and true or false, 1, function(st) if System and System.setLoadupClosed then System.setLoadupClosed(st) end end)
	UI.toggle(ol, "Execute on Loadup", (System and System.getLoadup and System.getLoadup("Execute")) and true or false, 2, function(st) if System and System.setLoadupExecute then System.setLoadupExecute(st) end end)
	do local _fp = (System and System.getLoadupFPerson and System.getLoadupFPerson()) or 0; UI.cyc(ol, "FPerson Loadup", { "false", "true" }, 3, function(o) if System and System.setLoadupFPerson then System.setLoadupFPerson(o == "true" and 1 or 0) end end, (_fp ~= 0) and "true" or "false") end
	do local _lb = System and System.getLoadup and System.getLoadup("Bundle"); UI.field(ol, "Bundle", (_lb and _lb ~= "" and _lb) or "bundle name…", 4, true, function(t) if System and System.setLoadupBundle then System.setLoadupBundle(t) end end) end
	local kb = tile(R, "Keybinds", 1)
	-- UI.keybind's onSet passes a KeyCode NAME (string); the engine keybind upvalue is an Enum.KeyCode -> convert back.
	local function _kbSet(engName) return function(k) if System and System.setKeybind then local kc = Enum.KeyCode[k]; if kc then System.setKeybind(engName, kc) end end end end
	local function _kbCur(engName, fallback) return (System and System.getKeybindName and System.getKeybindName(engName)) or fallback end
	UI.keybind(kb, "GUI", _kbCur("GUI", "Insert"), 1, _kbSet("GUI"))   -- real capture; fallback = engine default keybind
	UI.keybind(kb, "Heal", _kbCur("Heal", "="), 2, _kbSet("Heal"))
	UI.keybind(kb, "Damage", _kbCur("Dmg", "-"), 3, _kbSet("Dmg"))   -- engine keybind name is "Dmg"
	UI.keybind(kb, "Naked", _kbCur("Naked", "N"), 4, _kbSet("Naked"))
	UI.button(h, "Save", "primary", 2, function() local ok = System and System.persistLoadup and System.persistLoadup(); toast(ok and "Saved" or "Save failed", ok and "Loadup settings written." or "Could not write Settings.", ok and "ok" or "warn") end)  -- prominent CTA under the two columns
	local bc = tile(h, "Bundle & Content", 3)
	-- WIRED (merge): Import Bundle field -> System.importBundle(text) (mirrors V2 Pages.options L4856-4867: fetch/JSONDecode
	-- for URLs or sandboxed loadstring for pastes, staging survivors into System._pendingImports). On a non-empty parse it
	-- opens the Save Bundle destination modal; the status string surfaces via toast.
	UI.field(bc, "Import Bundle", "paste table or URL", 1, true, function(t)
		if not (t and t ~= "" and System and System.importBundle) then return end
		local res = System.importBundle(t)
		if res and res.status then toast("Import Bundle", tostring(res.status), (res.ok and "ok") or "warn") end
		if res and res.pending and res.pending > 0 and UI._saveBundleDialog then UI._saveBundleDialog() end
	end, nil, true)
	UI.hint(bc, "Paste a bundle table or a share URL, then Save Import.", 2)
	local b1 = cols(bc, 3, 2)
	UI.button(b1[1], "Export Bundle", nil, 1, exportBundleDialog)
	-- WIRED (merge): Copy Template / Delete Bundle reproduce V2's cross-tab detecting-bundle flow (L4884-4893): arm the flag
	-- on UI._detectingBundle, jump to the Bundles tab (UI._goBundles), and the NEXT bundle tile click acts on THAT bundle.
	UI.button(b1[2], "Copy Template", nil, 1, function()
		UI._detectingBundle = "export_copy"; toast("Copy Template", "Pick a bundle on the Bundles tab to copy its template.", "info")
		if UI._goBundles then UI._goBundles() end
	end)
	local b2 = cols(bc, 4, 2)
	UI.button(b2[1], "Delete Bundle", nil, 1, function()
		UI._detectingBundle = "delete"; toast("Delete Bundle", "Pick a bundle on the Bundles tab to delete it.", "warn")
		if UI._goBundles then UI._goBundles() end
	end)
	-- WIRED (merge): re-open the Save Bundle destination modal for any still-pending imports (V2 L4904-4907)
	UI.button(b2[2], "Save Import…", nil, 1, function()
		if System and System._pendingImports and #System._pendingImports > 0 and UI._saveBundleDialog then UI._saveBundleDialog() else toast("Import", "No imported bundles pending.", "info") end
	end)
	local b3 = cols(bc, 5, 2)
	UI.button(b3[1], "Redownload All", nil, 1, function()
		if not (System and System.doRedownload) then return end
		if Function and Function._redlInProgress then toast("Downloading content", "Already downloading -- please wait.", "warn"); return end
		toast("Downloading content", "Starting download...", "info")
		local lastTotal, lastFailed = 0, 0
		System.doRedownload(function(done, total, failed, file, size, stage)  -- LIVE progress -> updates the toast in place (silent = no x-count spam)
			if type(total) == "number" and total > 0 then lastTotal = total end
			if type(failed) == "number" then lastFailed = failed end
			if stage == "complete" then
				if lastTotal > 0 and lastFailed == 0 then toast("Content ready", string.format("Re-downloaded %d files.", lastTotal), "ok")
				elseif lastTotal > 0 then toast("Redownload finished", string.format("%d of %d files failed - try again.", lastFailed, lastTotal), "warn") end
				-- lastTotal == 0 -> nothing to fetch, or a pre-download failure (the install-error card speaks for itself) - no toast
			elseif stage == "error" then
				toast("Redownload failed", "Couldn't complete the download - check your connection and try again.", "err")
			elseif type(done) == "number" and lastTotal > 0 then
				toast("Downloading content", string.format("%d / %d files  (%d%%)", done, lastTotal, math.floor(done / lastTotal * 100)), "info", true)
			end
		end)
	end)
	UI.toggle(b3[2], "Naked Mode", (System and System.getPD and System.getPD("_nakedMode")) and true or false, 1, function(st) if System and System.setNaked then System.setNaked(st) end end)
	local dz = tile(h, "Danger", 4)
	local dPress, dBtn, dTok = 0, nil, 0   -- DESTROY needs 3 presses so a mis-tap can't wipe the UI; dTok resets the count if they stop
	dBtn = UI.button(dz, "DESTROY", nil, 1, function()
		dPress = dPress + 1; dTok = dTok + 1; local myTok = dTok
		local lb = dBtn:FindFirstChildOfClass("TextLabel")
		if dPress >= 3 then
			local p, s = dBtn.AbsolutePosition, dBtn.AbsoluteSize
			if destroyUI then destroyUI(p.X + s.X / 2, p.Y + s.Y / 2) end   -- pass the button centre → the shockwave bursts from the button
			if System and System.doDestroy then System.doDestroy() end   -- real engine teardown (BREAKER:Destroy) after the shockwave visual
		else
			if lb then lb.Text = "PRESS " .. (3 - dPress) .. " MORE" end
			task.delay(2.5, function() if myTok == dTok and dPress < 3 then dPress = 0; if lb then lb.Text = "DESTROY" end end end)   -- stop pressing → reset
		end
	end)
end

--=================================================================================
-- SMARTBAR + EXPANDING PANEL
--=================================================================================
local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
-- responsive: one device scale for the panel + Home content (bar auto-sizes on its own).
-- capped at 1.0 so it never INFLATES on big screens (that was the "massive cards"); only scales DOWN on small ones.
local UISCALE = math.clamp(math.min(vp.X / 1500, vp.Y / 860), 0.58, 1.0)
-- MOBILE resize: pure-touch devices report a viewport that renders the whole UI (bar + panels + home) noticeably bigger
-- than the game's own touch-DPI UI (user measured ~60% larger vs PC). Shrink it on touch-WITHOUT-keyboard (MouseEnabled
-- is unreliable on phones - see the roblox-ismobile-mouseenabled memory). ONE knob = the 0.66 factor; the 0.5 floor keeps
-- it legible. Everything is UISCALE'd, so the bar AND the docked multi-panels shrink together (de-cramps them too).
pcall(function() if UserInputService.TouchEnabled and UserInputService.AccelerometerEnabled then UISCALE = math.max(0.5, UISCALE * 0.66) end end)  -- gate on the ACCELEROMETER (a hardware sensor PCs lack) + touch: TouchEnabled/KeyboardEnabled MISFIRED on the PC executor and shrank desktop too
local BAR_H, BAR_Y = 56, 10  -- BAR_Y = gap from the screen bottom (lower now, but not hugging the edge)
local PANEL_W = math.floor(math.min(580, vp.X - 32))
local PANEL_H = math.max(120, math.floor(math.min(328, vp.Y - 124)))  -- tall enough a dense bento tab fits WITHOUT scrolling (was 288)
-- All 11 real tabs, each its own bar button (colour-coded by the real group families).
local SECTIONS = {
	{ id = "player", label = "Player", icon = "player", color = Color3.fromRGB(124, 92, 214) },
	{ id = "body", label = "Body", icon = "body", color = Color3.fromRGB(96, 110, 214) },
	{ id = "clothes", label = "Clothes", icon = "clothes", color = Color3.fromRGB(202, 120, 66) },
	{ id = "recolor", label = "Recolor", icon = "recolor", color = Color3.fromRGB(216, 96, 150) },
	{ id = "damage", label = "Damage", icon = "damage", color = Color3.fromRGB(196, 60, 72) },
	{ id = "catalog", label = "Catalog", icon = "catalog", color = Color3.fromRGB(58, 162, 150) },
	{ id = "bundles", label = "Bundles", icon = "bundles", color = Color3.fromRGB(80, 172, 108) },
	{ id = "edit", label = "Edit", icon = "edit", color = Color3.fromRGB(214, 174, 88) },
	{ id = "settings", label = "Settings", icon = "settings", color = Color3.fromRGB(96, 132, 168) },
	{ id = "options", label = "Options", icon = "options", color = Color3.fromRGB(110, 124, 180) },
}
local SECTION_BY_ID = {}; for _, s in ipairs(SECTIONS) do SECTION_BY_ID[s.id] = s end
-- page descriptions shown in the header bar (per sub-tab).
local SECTION_DESC = {
	player = "Target and core actions.", body = "Types, scale, physics, body-map.", clothes = "Equip and search.",
	recolor = "Recolour equipped cloth parts.", damage = "HP, clothing tear and SFX.",
	catalog = "Roblox marketplace.", bundles = "Saved outfits and community.",
	edit = "3D gizmo - position and rotation.", settings = "View, toggles, diagnostics.",
	options = "Loadup, keybinds, bundle.",
}

local panel = new("Frame", { Name = "Panel", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.fromOffset(PANEL_W, PANEL_H), BackgroundColor3 = T.bg, BorderSizePixel = 0, ClipsDescendants = true, Visible = false, Parent = panelScreen })
_KR.panels[panel] = true  -- register the single tab panel for the glassy-panels setting
panel:SetAttribute("PanelRoot", true)  -- so the dropdown-picker can find its panel (single OR multi) by walking ancestors
local panelCorner = corner(panel, 16); local panelStroke = stroke(panel, T.line, 1)  -- no gradient: bg colour morphs from the button colour to the card colour
new("UIScale", { Scale = UISCALE, Parent = panel })  -- responsive: scale the panel to the device
-- the panel grows out of / shrinks into the chevron button: it animates POSITION + SIZE to the
-- chevron's exact footprint, so it visibly collapses INTO the button (not the middle of the screen).
-- panel is CENTRE-anchored, so its open position is the card's centre (above the bar), and the collapsed
-- position is the button's CENTRE -- so it can never land above the button, only ON it.
-- BAR_H * UISCALE, not raw BAR_H: the bar RENDERS scaled, so the gap must use the scaled height (else a big gap on mobile).
local function panelOpenRect(pw, dockOverride)  -- returns (Position, Size) for a single-panel dock (default = current SET._panelDock; dockOverride lets the drag preview query ANY dock's rect). bar/top = the normal panel; left/right = a Multi-Panel-style side column (RESIZED narrow + edge-docked, so it fills the side and never clips). Defined before `bar`/GUI_INSET exist (the drag closure captures it early), so it derives everything from constants + a live inset.
	local dock = dockOverride or SET._panelDock or "bar"  -- DRAG-TO-DOCK: bar (default, near the SmartBar) | top | left | right. No centre dock (must not sit over the avatar). Stored on SET so it persists with the other UI prefs.
	local off = BAR_Y + math.floor(BAR_H * UISCALE * (SET.barSize or 1)) + 6 + math.floor(PANEL_H * UISCALE / 2)  -- x barSize so the panel clears a Small/Large bar (matches A.barPos / fitHome)
	pw = pw or _KR._panelFullW or PANEL_W  -- last full (bar-derived) width from popOpen, NOT the current panel size (which is the slim column when side-docked → dragging back to the bar would otherwise stay narrow)
	if dock == "left" or dock == "right" then
		local vp2 = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
		local margin, gap, minCenter = 12, 10, 140
		local topInset = 0; pcall(function() topInset = game:GetService("GuiService"):GetGuiInset().Y end)  -- clear the Roblox topbar (can't use GUI_INSET here - defined later)
		local topMargin = math.max(margin, topInset + gap)
		local sideW = math.min(math.clamp(math.floor(vp2.X * 0.32), 300, 460), math.floor((vp2.X - 2 * margin - minCenter) / 2)); sideW = math.max(160, sideW)  -- same column width MP uses (no-strip case)
		local barClear = BAR_Y + math.ceil(BAR_H * UISCALE * (SET.barSize or 1)) + gap  -- reserve the SmartBar's own edge
		local cTop, cBot
		if SET.barTop then cTop, cBot = math.max(barClear, topMargin), vp2.Y - margin
		else cTop, cBot = topMargin, vp2.Y - barClear end
		local h = math.max(120, cBot - cTop)  -- clamp: on a tiny viewport barClear+topMargin can exceed vp.Y -> negative height -> a 0-size (invisible) panel
		local cx = (dock == "left") and margin or (vp2.X - margin - sideW)
		return UDim2.fromOffset(math.floor(cx + sideW / 2), math.floor(cTop + h / 2)),  -- anchor (0.5,0.5): centre of the column rect; Position is SCREEN px, Size is LOGICAL (÷UISCALE) since the panel carries a UIScale (matches MP.set)
		       UDim2.fromOffset(math.floor(sideW / UISCALE), math.floor(h / UISCALE))
	end
	local pos = (dock == "top") and UDim2.new(0.5, 0, 0, off) or (SET.barTop and UDim2.new(0.5, 0, 0, off) or UDim2.new(0.5, 0, 1, -off))
	return pos, UDim2.fromOffset(pw, PANEL_H)  -- "bar" default / "top": normal panel size
end
local PANEL_MIN = UDim2.fromOffset(34, 15)
local pHead = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 42), Parent = panel }); pad(pHead, 14, 12, 0, 0)
-- the logo lives on the PANEL (not the header) so it can morph from the button centre to the top-left of the card.
local pIconHost = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(24, 21), Size = UDim2.fromOffset(20, 20), BackgroundTransparency = 1, ZIndex = 4, Parent = panel })
local pTitle = lbl({ AnchorPoint = Vector2.new(0, 0), Position = UDim2.new(0, 30, 0, 5), Size = UDim2.new(1, -70, 0, 18), Text = "Home", Font = FONTB, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Left, Parent = pHead })
-- description sits in the header bar UNDER the title (so pages don't repeat "Clothes / Clothes description").
local pDesc = lbl({ AnchorPoint = Vector2.new(0, 0), Position = UDim2.new(0, 30, 0, 24), Size = UDim2.new(1, -70, 0, 13), Text = "", TextColor3 = T.txt3, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, Parent = pHead })
local pClose = UI.closeBtn(pHead, 26, 8, 0.25)
-- DRAG-TO-DOCK (single panel): a transparent handle over the header (minus the close X) lets you drag the
-- panel around; on release it SNAPS to the nearest dock (near-bar / top / left / right / centre). Panel is anchored (0.5,0.5).
do  -- body lives in a nested fn so its locals sit in their OWN frame, not the main chunk's 200-register budget
	local function _spDrag()
		local pDragHit = new("TextButton", { BackgroundTransparency = 1, AutoButtonColor = false, Text = "", Size = UDim2.new(1, -44, 1, 0), ZIndex = 3, Parent = pHead })
		local dragging, K, lastZone = false, Vector2.new(0, 0), nil  -- K = the ScreenGui's inset offset: Position.Offset = cursor + K puts the panel's anchor under the cursor (screens here IgnoreGuiInset). lastZone tracks the hovered dock so we only re-morph on change.
		local DOCKS = { "bar", "top", "left", "right" }
		local ghosts = {}  -- one translucent outline per dock, showing every place the panel can snap to
		local function ensureGhosts()
			if ghosts.bar then return end
			for _, dk in ipairs(DOCKS) do
				local g = new("Frame", { Name = "DockGhost_" .. dk, AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = T.accent, BackgroundTransparency = 0.9, BorderSizePixel = 0, Visible = false, ZIndex = 2, Parent = panel.Parent })
				new("UIScale", { Scale = UISCALE, Parent = g })  -- match the panel's UIScale so panelOpenRect's LOGICAL Size renders 1:1
				corner(g, 14); local s = stroke(g, T.accent, 2); s.Transparency = 0.4
				ghosts[dk] = g
			end
		end
		local function zoneAt(cx, cy, vp) if cx < vp.X * 0.28 then return "left" elseif cx > vp.X * 0.72 then return "right" elseif cy < vp.Y * 0.28 then return "top" else return "bar" end end
		local function showGhosts(on, active)
			ensureGhosts()
			for _, dk in ipairs(DOCKS) do
				local g = ghosts[dk]
				if on then
					local p, sz = panelOpenRect(nil, dk); g.Position = p; g.Size = sz; g.Visible = true
					local hot = dk == active; g.BackgroundTransparency = hot and 0.72 or 0.92
					local st = g:FindFirstChildOfClass("UIStroke"); if st then st.Transparency = hot and 0 or 0.55 end
				else g.Visible = false end
			end
		end
		local function follow(io)  -- panel is a fixed SHRUNK proxy; just highlight the dock under the cursor + pin the cursor ~18px below the proxy's top edge (on the header)
			local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
			local zone = zoneAt(io.Position.X, io.Position.Y, vp)
			if zone ~= lastZone then lastZone = zone; showGhosts(true, zone) end  -- re-highlight the dock the cursor is over (all 4 outlines stay visible)
			local half = 132 * UISCALE / 2  -- fixed proxy half-height (132 logical)
			panel.Position = UDim2.fromOffset(math.floor(io.Position.X + K.X), math.floor(io.Position.Y + K.Y - 18 + half))
		end
		local startM, moved = nil, false
		pDragHit.InputBegan:Connect(function(io)
			if io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch then
				dragging = true; startM = io.Position; moved = false
				local scr = panel.Parent; local inset = Vector2.new(0, 0); pcall(function() inset = game:GetService("GuiService"):GetGuiInset() end)
				K = (scr and scr.IgnoreGuiInset) and inset or Vector2.new(0, 0)
				lastZone = nil  -- DRAG-SLOP: don't shrink/follow/re-dock until the finger travels (a bare header tap leaves the panel exactly as-is)
			end
		end)
		local _c1 = UserInputService.InputChanged:Connect(function(io)
			if dragging and panel.Parent and (io.UserInputType == Enum.UserInputType.MouseMovement or io.UserInputType == Enum.UserInputType.Touch) then
				if not moved and startM and (io.Position - startM).Magnitude > 8 then moved = true; panel.AnchorPoint = Vector2.new(0.5, 0.5); tween(panel, 0.15, { Size = UDim2.fromOffset(210, 132) }, QUINT) end  -- real drag: centre-anchor + shrink to the proxy
				if moved then follow(io) end
			end
		end)
		local _c2 = UserInputService.InputEnded:Connect(function(io)
			if dragging and (io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch) then
				dragging = false; showGhosts(false)
				if moved then  -- only a real drag re-docks; a tap did nothing (panel untouched, still full-size at its dock)
					local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
					SET._panelDock = zoneAt(io.Position.X, io.Position.Y, vp)
					local dp, ds = panelOpenRect(); tween(panel, 0.35, { Position = dp, Size = ds }, QUINT)  -- glide AND resize to the chosen dock
				end
			end
		end)
		panel.Destroying:Connect(function() pcall(function() _c1:Disconnect() end) pcall(function() _c2:Disconnect() end) end)  -- global UIS conns leak on teardown/re-exec otherwise (pin the whole UI subtree from GC) - mirror the MP/slider cleanup
	end
	_spDrag()
end
new("Frame", { Position = UDim2.new(0, 12, 0, 42), Size = UDim2.new(1, -24, 0, 1), BackgroundColor3 = T.lineSoft, BorderSizePixel = 0, Parent = panel })
local pageHost = new("ScrollingFrame", { BackgroundTransparency = 1, Position = UDim2.new(0, 0, 0, 46), Size = UDim2.new(1, 0, 1, -46), BorderSizePixel = 0, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 3, ScrollBarImageColor3 = T.line, ScrollBarImageTransparency = 0.45, ScrollingDirection = Enum.ScrollingDirection.Y, Parent = panel }); pad(pageHost, 14, 10, 4, 16); vlist(pageHost, 8)
-- STICKY zone: grid tabs pin their filter/search row here (2nd arg to their page fn) so it stays put while the grid
-- scrolls; empty (0 height) on every other tab. pageHost + the top fade get pushed below it by syncSticky().
local stickyBar = new("Frame", { Name = "Sticky", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), Position = UDim2.new(0, 0, 0, 46), AutomaticSize = Enum.AutomaticSize.Y, Parent = panel })
-- scroll edge fades: content dissolves into the panel bg at the top/bottom instead of hard-cutting at the edge.
-- (parented to the panel, not the scroll, so they stay put while content scrolls under them. T.bg = panel's resting bg.)
local function pageEdgeFade(atTop, yTop, h)
	local f = new("Frame", { BackgroundColor3 = T.bg, BorderSizePixel = 0, ZIndex = 6, AnchorPoint = atTop and Vector2.new(0.5, 0) or Vector2.new(0.5, 1), Size = UDim2.new(1, -32, 0, h), Position = atTop and UDim2.new(0.5, 0, 0, yTop) or UDim2.new(0.5, 0, 1, 0), Parent = panel })  -- inset 16px so the fade clears the panel's rounded corners
	local up = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) })
	local dn = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) })
	new("UIGradient", { Rotation = 90, Transparency = atTop and up or dn, Parent = f })
	return f
end
local topFade = pageEdgeFade(true, 46, 16)  -- top (just under the header divider)
local botFade = pageEdgeFade(false, 0, 18)  -- bottom
topFade.Visible = false; botFade.Visible = false  -- hidden during the morph so no black bars flash on open/close
-- push pageHost + the top fade below the sticky zone (its height is 0 when empty, so non-grid tabs are unaffected)
_KR.syncStickyZone = function(hostFrame, stickyFrame, headerH, fadeFrame)  -- keep a scroll host BELOW the sticky zone's live height (shared by the single panel + every Multi-Panel panel). ÷UISCALE: AbsoluteSize is POST-scale (the panel is UISCALE'd) but the host offset is LOGICAL; was overlapping the sticky row on <1.0 (mobile) devices.
	local sh = math.ceil(stickyFrame.AbsoluteSize.Y / UISCALE)
	hostFrame.Position = UDim2.new(0, 0, 0, headerH + sh)
	hostFrame.Size = UDim2.new(1, 0, 1, -(headerH + sh))
	if fadeFrame then fadeFrame.Position = UDim2.new(0.5, 0, 0, headerH + sh) end
end
local function syncSticky() _KR.syncStickyZone(pageHost, stickyBar, 46, topFade) end  -- single panel: 46px header + the top edge-fade
stickyBar:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncSticky); syncSticky()
-- Edge fades FOLLOW the scroll: the top fade only appears once you've scrolled DOWN (so it never dims the first
-- section header at rest - that was the subtle grey tint), the bottom fade only while there's more content below.
-- A tab whose content fits shows neither.
local activeTab, panelOpen, activeBtn, activeColor = nil, false, nil, T.accent  -- [V3 MERGE FIX] declared ABOVE refreshFades (which reads panelOpen); was declared ~65 lines later => panelOpen compiled as a nil GLOBAL => edge-fades were dead on every tab.
local function refreshFades()
	if not panelOpen then topFade.Visible = false; botFade.Visible = false; return end
	local pos = pageHost.CanvasPosition.Y
	local maxScroll = math.max(0, pageHost.AbsoluteCanvasSize.Y - pageHost.AbsoluteWindowSize.Y)
	topFade.Visible = pos > 3
	botFade.Visible = pos < maxScroll - 3
end
pageHost:GetPropertyChangedSignal("CanvasPosition"):Connect(refreshFades)

-- ===== option-picker modal (opened by every UI.dropdown instead of an inline drop). Parented INTO the panel so it
-- ALWAYS fits perfectly inside the tab and resizes with it: the dim fills the panel (scale 1,1), the card insets from
-- its edges (scale width, capped) and caps its list to the panel height. High ZIndex (panelScreen is Sibling) so the
-- whole picker draws above the tab content, which tops out at ~6 (the edge fades). =====
local DZ = 90
local dropLayer = new("Frame", { Name = "DropdownLayer", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Visible = false, ZIndex = DZ, Parent = panel })
local _dDim = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = DZ, Parent = dropLayer }); corner(_dDim, 16)  -- fills the panel + rounds to match its corners
local _dCard = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, -40, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = T.bg, BorderSizePixel = 0, Active = true, ZIndex = DZ + 1, Parent = dropLayer }); corner(_dCard, 13); stroke(_dCard, T.line, 1); pad(_dCard, 14, 14, 14, 14); vlist(_dCard, 10)
new("UISizeConstraint", { MaxSize = Vector2.new(420, 1000000), Parent = _dCard })  -- don't stretch the list across a wide desktop panel
local _dScale = new("UIScale", { Scale = 1, Parent = _dCard })  -- entrance pop (multiplies with the panel's own UIScale)
local _dTitle = lbl({ Size = UDim2.new(1, 0, 0, 20), Text = "", Font = FONTB, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = DZ + 2, LayoutOrder = 1, Parent = _dCard })
-- options in a height-capped scroller so a long list (Breasts has 7) still fits inside the panel; short lists auto-shrink.
local _dScroll = new("ScrollingFrame", { BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y, ScrollBarThickness = 3, ScrollBarImageColor3 = T.line, ZIndex = DZ + 2, LayoutOrder = 2, Parent = _dCard })
new("UIListLayout", { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder, Parent = _dScroll })
local _dCloseCb  -- the opener's onClose (chevron spring-back), fired on pick OR backdrop-tap dismissal
local function hideDropdown() dropLayer.Visible = false; dropLayer.Parent = panel; if _dCloseCb then local cb = _dCloseCb; _dCloseCb = nil; pcall(cb) end end  -- hide + RE-HOME to the single panel; FIRE the opener's close cb (chevron spring-back) so it isn't left stuck rotated
UI.openDropdown = function(title, options, current, onChoose, onClose, root)
	if _dCloseCb then local cb = _dCloseCb; _dCloseCb = nil; pcall(cb) end   -- another panel's dropdown is still open -> spring ITS chevron back before we re-home the shared picker into THIS panel (else it's left stuck rotated)
	_dTitle.Text = tostring(title or "Select")
	for _, c in ipairs(_dScroll:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
	for i, opt in ipairs(options) do
		local sel = (tostring(opt) == tostring(current))  -- the current value gets an accent fill so it's obvious at a glance
		local ob = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = sel and T.accentD or T.card, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 34), ZIndex = DZ + 3, LayoutOrder = i, Parent = _dScroll }); corner(ob, 8); pad(ob, 12, 12, 0, 0)
		local st = (not sel) and stroke(ob, T.lineSoft, 1) or nil
		lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(1, 0, 1, 0), Text = tostring(opt), TextColor3 = sel and T.txt or T.txt2, Font = sel and FONTB or FONT, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = DZ + 4, Parent = ob })
		if not sel then
			ob.MouseEnter:Connect(function() tween(ob, 0.18, { BackgroundColor3 = T.cardHi }); if st then tween(st, 0.18, { Color = T.line }) end end)
			ob.MouseLeave:Connect(function() tween(ob, 0.18, { BackgroundColor3 = T.card }); if st then tween(st, 0.18, { Color = T.lineSoft }) end end)
		end
		ob.MouseButton1Click:Connect(function() _dCloseCb = nil; dropLayer.Visible = false; if onClose then onClose() end; if onChoose then onChoose(opt) end end)
	end
	local rows = #options
	local tgt = root or panel; dropLayer.Parent = tgt  -- panel-aware: the picker opens INSIDE the panel whose dropdown was tapped
	local capH = (tgt == panel) and PANEL_H or (tgt.AbsoluteSize.Y / UISCALE)  -- BOTH the single panel and every MP frame carry a UIScale=UISCALE (see MP.make), so a multi-panel's AbsoluteSize is POST-scale → ÷UISCALE to get the LOGICAL height the _dScroll list Size is set in (else the list is cramped on mobile where UISCALE<1)
	_dScroll.Size = UDim2.new(1, 0, 0, math.min(rows * 34 + math.max(0, rows - 1) * 5, math.max(68, capH - 82)))  -- list height capped to the target panel
