end
_dDim.InputBegan:Connect(function(io)  -- close on a click OUTSIDE the card (bounds-checked; doesn't rely on Active sinking on Volt)
	if io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch then
		local p, cp, cs = io.Position, _dCard.AbsolutePosition, _dCard.AbsoluteSize
		if p.X < cp.X or p.X > cp.X + cs.X or p.Y < cp.Y or p.Y > cp.Y + cs.Y then dropLayer.Visible = false; if _dCloseCb then _dCloseCb() end; _dCloseCb = nil end
