end)
local bar = new("Frame", { Name = "SmartBar", AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -BAR_Y), Size = UDim2.new(0, 0, 0, BAR_H), AutomaticSize = Enum.AutomaticSize.X, BackgroundColor3 = T.bg, BorderSizePixel = 0, ClipsDescendants = true, Parent = screen })
local barCorner = corner(bar, 16); stroke(bar, T.line, 1); pad(bar, 18, 18, 0, 0); new("UIGradient", { Rotation = 90, Color = ColorSequence.new(T.bg2, T.bg), Parent = bar })
_KR.panels[bar] = true  -- register the SmartBar for the glassy-panels setting (SET.glass)
new("UIScale", { Scale = UISCALE, Parent = bar })  -- responsive: scale the bar to the device (compress uses logical sizes below)
new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 14), Parent = bar })
local clock = lbl({ Size = UDim2.new(0, 46, 1, 0), Text = "00:00", Font = FONTB, TextColor3 = T.txt2, TextSize = 15, LayoutOrder = 1, Parent = bar })
local function barDivider(order, name) new("Frame", { Name = name or "Div", Size = UDim2.new(0, 1, 0, 26), BackgroundColor3 = T.line, BorderSizePixel = 0, LayoutOrder = order, Parent = bar }) end
barDivider(2, "ClockDiv")  -- named so the "Show clock" setting can hide it with the clock

local tabs = {}
-- (activeTab/panelOpen/activeBtn/activeColor now declared above refreshFades - see [V3 MERGE FIX])
local homeOpen, openHome, closeHome = false, nil, nil  -- full-screen Home (assigned below the bar build)
_KR._hiddenGuis = {}  -- other ScreenGuis we hid while Home is open, to restore on close (on _KR to save a Luau register)
-- a tab button's on-screen footprint (bottom-centre position + size), so the panel morphs from/into the button ITSELF.
local GUI_INSET = Vector2.new(0, 0); pcall(function() GUI_INSET = game:GetService("GuiService"):GetGuiInset() end)
local function btnFootprint(btn)
	if btn and btn.AbsoluteSize.X > 0 then
		local ap, asz = btn.AbsolutePosition, btn.AbsoluteSize
		-- + GUI_INSET: on an IgnoreGuiInset ScreenGui, AbsolutePosition under-reports by the topbar inset, so the
		-- panel's offset positioning needs the inset added back to actually land ON the button.
		-- size divided by UISCALE because the panel carries a UIScale (avoids double-scaling the collapsed footprint).
		return UDim2.fromOffset(math.floor(ap.X + asz.X / 2 + GUI_INSET.X), math.floor(ap.Y + asz.Y / 2 + GUI_INSET.Y)), UDim2.fromOffset(math.floor(asz.X / UISCALE), math.floor(asz.Y / UISCALE))
	end
	local _p = panelOpenRect(); return _p, PANEL_MIN
end
local function buildPageInto(host, sticky, id)  -- build a tab's content into ANY scroll host + sticky zone (single OR a multi-panel)
	if _curPage == "edit" and id ~= "edit" and System and System.hideGizmo3D then pcall(System.hideGizmo3D) end  -- RIG POSER: drop the 3D handles when leaving the Edit tab
	_curPage = id  -- stateful controls key their persisted value to this tab; captured at build time (builds are synchronous)
	for _, c in ipairs(host:GetChildren()) do if not c:IsA("UIListLayout") and not c:IsA("UIPadding") then c:Destroy() end end
	for _, c in ipairs(sticky:GetChildren()) do c:Destroy() end  -- reset the sticky zone; grid tabs re-fill it via the 2nd arg
	local b = PAGES[id]; if b then b(host, sticky) end
	host.CanvasPosition = Vector2.new(0, 0)
	if _KR.fadeInto then _KR.fadeInto(host.Parent) end  -- if UI-transparency is ON, fade this freshly-built panel to match (BEFORE the cascade, so the cascade reveals to the faded value instead of fighting it)
	if SET.cardAnims and not SET.reduceMotion then cascadeIn(host, 0.16) end  -- "Card animations" gates the page cascade
end
local function buildPage(id)  -- single-panel wrapper: unchanged behaviour (the one panel's pageHost + stickyBar)
	hideDropdown()  -- close any open dropdown-picker when the tab (re)builds
	buildPageInto(pageHost, stickyBar, id)
end
local function setActive(id)
	for tid, t in pairs(tabs) do tween(t.dot, 0.3, { BackgroundTransparency = tid == id and 0 or 1 }); tween(t.iconScale, 0.3, { Scale = tid == id and 1 or 0.9 }, QUINT) end
end
local function setHeadIcon(id)
	pIconHost:ClearAllChildren()
	local s = SECTION_BY_ID[id]
	local ic = mkIcon(s and s.icon or id, 20); ic.Size = UDim2.fromScale(1, 1); ic.Parent = pIconHost
end
-- the panel collapses onto the button, but the button is a top->dark GRADIENT, so a solid accent looks brighter
-- than the button. tabTone darkens the collapse colour to the button's average so they match on close.
local function tabTone(c) return c:Lerp(Color3.fromRGB(0, 0, 0), 0.16) end
local function popOpen(id, label, color, btn)
	-- V4.5.17: RESIZE the panel to the LIVE viewport BEFORE building the page. PANEL_W/H were computed ONCE at load from `vp`; a device rotation (portrait load -> landscape) then left the panel sized for the TALLER screen, so it covered ~56% of a short landscape phone ("single panel blocks the useful part"). Recompute from the CURRENT viewport (matches popOpen's existing live-width `pw` at L~4465 + fitHome's live-vp pattern). The panel RENDERS at *UISCALE, so also cap the rendered height to ~58% of the live height, keeping the avatar visible behind/above the bottom-docked panel.
	do
		local cam = workspace.CurrentCamera; local lv = cam and cam.ViewportSize
		local lvw2, lvh2 = (lv and lv.X) or vp.X, (lv and lv.Y) or vp.Y
		PANEL_W = math.floor(math.min(580, lvw2 - 32))
		PANEL_H = math.max(120, math.floor(math.min(328, lvh2 - 124, lvh2 * 0.58 / (UISCALE > 0 and UISCALE or 1))))
	end
	activeTab = id; activeBtn = btn; activeColor = color or T.accent; setActive(id); pTitle.Text = label or id; pDesc.Text = SECTION_DESC[id] or ""; setHeadIcon(id); buildPage(id)
	local fp, fs = btnFootprint(btn)
	-- the panel opens to the SmartBar's width (never wider than the bar) -- it follows the bar's size.
	local lvw = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X) or vp.X  -- LIVE viewport: the load-time vp goes stale on a desktop window resize, letting the centred panel overflow both edges
	local pw = PANEL_W; if bar.AbsoluteSize.X > 10 then pw = math.clamp(math.floor(bar.AbsoluteSize.X / UISCALE), 300, math.max(300, lvw - 24)) end  -- V4.5.19: math.max floor on the clamp MAX - on a viewport narrower than 324px (tiny window / emulator) lvw-24 < 300, so max < min and math.clamp THREW, crashing every tab-open
	_KR._panelFullW = pw  -- remember the bar-derived full width so a drag back to the bar/top dock restores it (panelOpenRect)
	-- COLLAPSED = the button itself: its footprint, its colour, a centred logo, header hidden.
	panel.Position = fp; panel.Size = fs; panel.BackgroundColor3 = tabTone(activeColor); panel.BackgroundTransparency = _KR.glass  -- glassy-panels: open at the chosen translucency, not forced opaque
	panelCorner.CornerRadius = UDim.new(0, math.floor(11 * _KR.cornerScale + 0.5)); panelStroke.Transparency = 1
	pIconHost.Position = UDim2.fromScale(0.5, 0.5)
	pTitle.TextTransparency = 1; pDesc.TextTransparency = 1; pClose.Visible = false; panel.Visible = true  -- Visible set AFTER the collapse position, so the first frame renders ON the button
	-- MORPH: the button box expands into the card, its colour bleeds to the card colour, the logo slides to the top-left.
	if SET.cardAnims and not SET.reduceMotion then
		local _op, _os = panelOpenRect(pw); tween(panel, 0.6, { Position = _op, Size = _os, BackgroundColor3 = T.bg }, QUINT)
		tween(panelCorner, 0.6, { CornerRadius = UDim.new(0, math.floor(16 * _KR.cornerScale + 0.5)) }, QUINT)
		tween(panelStroke, 0.55, { Transparency = 0 })
		tween(pIconHost, 0.6, { Position = UDim2.fromOffset(24, 21) }, QUINT)
		task.delay(0.32 * SPEED, function() tween(pTitle, 0.4, { TextTransparency = 0 }); tween(pDesc, 0.4, { TextTransparency = 0 }); pClose.Visible = true end)
		task.delay(0.6 * SPEED, function() if panelOpen and activeTab == id then refreshFades() end end)  -- edge fades reflect the scroll (never dim the top header at rest)
	else  -- "Card animations" off → snap straight to the open state (no morph)
		local _sp, _ss = panelOpenRect(pw); panel.Position = _sp; panel.Size = _ss; panel.BackgroundColor3 = T.bg
		panelCorner.CornerRadius = UDim.new(0, math.floor(16 * _KR.cornerScale + 0.5)); panelStroke.Transparency = 0; pIconHost.Position = UDim2.fromOffset(24, 21)
		pTitle.TextTransparency = 0; pDesc.TextTransparency = 0; pClose.Visible = true
		task.delay(0.05, function() if panelOpen and activeTab == id then refreshFades() end end)
	end
end
local function openTab(id, label, color, btn)
	if MP._tabSwitching then return end  -- a switch morph is mid-flight → ignore taps until it settles (else the 2nd tap re-reads the still-stale activeBtn/activeColor and snaps the panel back to a wrong button). On MP table = no new top-level local.
	if panelOpen and activeTab ~= id and SET.cardAnims and not SET.reduceMotion then
		MP._tabSwitching = true
		-- SWITCH: content fades out first, the old card collapses into ITS button, then the new one morphs out.
		local oldFp, oldFs = btnFootprint(activeBtn); local oldCol = activeColor
		pClose.Visible = false; topFade.Visible = false; botFade.Visible = false
		tween(pTitle, 0.14, { TextTransparency = 1 }); tween(pDesc, 0.14, { TextTransparency = 1 }); cascadeOut(pageHost, 0.14)
		task.delay(0.17 * SPEED, function()
			tween(pIconHost, 0.28, { Position = UDim2.fromScale(0.5, 0.5) }, EXPO)
			tween(panel, 0.3, { Position = oldFp, Size = oldFs, BackgroundColor3 = tabTone(oldCol) }, EXPO)
			tween(panelCorner, 0.3, { CornerRadius = UDim.new(0, math.floor(11 * _KR.cornerScale + 0.5)) }, EXPO)
			tween(panelStroke, 0.2, { Transparency = 1 })
			task.delay(0.3 * SPEED, function() popOpen(id, label, color, btn); MP._tabSwitching = false end)  -- chain always runs → flag always clears (no permanent block)
		end)
		return
	end
	panelOpen = true
	popOpen(id, label, color, btn)
end
local function closePanel()
	if not panelOpen then return end
	hideDropdown()  -- dismiss any open dropdown-picker along with the panel
	panelOpen = false; local fp, fs = btnFootprint(activeBtn); local col = activeColor; activeTab = nil; activeBtn = nil; setActive(nil); pClose.Visible = false; topFade.Visible = false; botFade.Visible = false
	if SET.cardAnims and not SET.reduceMotion then
		-- STEP 1: the content + title fade out first, so you never see the cards/lines during the collapse.
		tween(pTitle, 0.16, { TextTransparency = 1 }); tween(pDesc, 0.16, { TextTransparency = 1 }); cascadeOut(pageHost, 0.16)
		-- STEP 2: only THEN does the emptied card morph back into its button (logo to centre, shrink + recolour).
		task.delay(0.22 * SPEED, function()
			if panelOpen then return end
			tween(pIconHost, 0.45, { Position = UDim2.fromScale(0.5, 0.5) }, EXPO)
			tween(panel, 0.45, { Position = fp, Size = fs, BackgroundColor3 = tabTone(col) }, EXPO)
			tween(panelCorner, 0.45, { CornerRadius = UDim.new(0, math.floor(11 * _KR.cornerScale + 0.5)) }, EXPO)
			tween(panelStroke, 0.28, { Transparency = 1 })
			task.delay(0.45 * SPEED + 0.05, function() if not panelOpen then panel.Visible = false end end)
		end)
	else
		panel.Visible = false  -- "Card animations" off → just hide it (no collapse morph)
	end
end
local function onTabClick(id, label, color, btn)
	if homeOpen and closeHome then closeHome() end
	if SET.multiPanel then MP.open(id, label, color, btn)
	elseif activeTab == id and panelOpen then closePanel()
	else openTab(id, label, color, btn) end
end
pClose.MouseButton1Click:Connect(closePanel)
-- WIRED (merge): cross-tab jump used by the Options detecting-bundle flow (Copy Template / Delete Bundle arm UI._detectingBundle
-- then call this to switch to the Bundles tab, where the next tile click consumes the armed action). Stashed on the UI table
-- so PAGES.options (defined earlier) can reach it without a new main-chunk local. Reads tabs/SECTION_BY_ID at call time.
UI._goBundles = function()
	local sec = SECTION_BY_ID and SECTION_BY_ID["bundles"]
	local t = tabs and tabs["bundles"]
	if sec and t and t.btn then onTabClick(sec.id, sec.label, sec.color, t.btn) end
end
-- ===== Multi-Panel Mode core (SET.multiPanel) - up to 5 lightweight docked panels around the perimeter, center clear.
-- Placed here (panel / vp / buildPageInto / mkIcon now exist); overwrites the early MP.open/closeAll stubs. =====
MP.screen = new("ScreenGui", { Name = "RoClothesMulti", ResetOnSpawn = false, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, IgnoreGuiInset = true, DisplayOrder = 1000, Enabled = false, Parent = PlayerGui })
GUIObject.MultiScreen = MP.screen  -- V4.5.17: creation-site stash so BREAKER.Destroying can destroy it by reference (MP is a _buildV3GUI local = invisible to the teardown closure; MP.host is a child of MP.screen so this covers it too)
MP.host = new("Frame", { Name = "MPHost", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Parent = MP.screen })  -- persistent full-screen host: every docked panel parents HERE (not MP.screen directly), so one relayout can tile them all + one descendant walk fades them
function MP.edgeStart(r, vpx)  -- the off-screen start/exit point for a panel at rect r, by which perimeter edge it's docked to (shared by the open entrance AND the Home-takeover slide). vpx optional: pass it in a loop so viewport width isn't re-read per panel.
	vpx = vpx or (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X) or 1280
	local cx = r.x + r.w / 2
	if cx < vpx * 0.34 then return r.x - (r.w + 24), r.y
	elseif cx > vpx * 0.66 then return r.x + (r.w + 24), r.y
	elseif SET.barTop then return r.x, r.y + (r.h + 24) else return r.x, r.y - (r.h + 24) end
end
function MP.setVisible(v)  -- Home takeover: slide the panels OUT to their docked edges (not a sudden disappear), then disable; on return, enable + slide them back IN
	MP._visTok = (MP._visTok or 0) + 1; local tok = MP._visTok  -- cancels an in-flight fade so a fast Home re-toggle can't mis-hide
	if not v then hideDropdown() end   -- close any OPEN docked-panel dropdown before hiding, else it ghosts back over the panels when Home closes (MP.close already does this; setVisible didn't)
	local vpx = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X) or 1280  -- read once, passed into edgeStart so the loops below don't re-read viewport width per panel
	if v then
		MP.screen.Enabled = true
		MP.relayout(false)  -- rects current (the bar edge / viewport may have changed while Home was up); positions set synchronously, overwritten by the edge-start below before the frame renders
		if SET.cardAnims and not SET.reduceMotion then
			for _, id in ipairs(MP.order) do local inst = MP.panels[id]
				if inst and inst.rect then local sx, sy = MP.edgeStart(inst.rect, vpx); inst.frame.Position = UDim2.fromOffset(sx, sy); tween(inst.frame, 0.4, { Position = UDim2.fromOffset(inst.rect.x, inst.rect.y) }, QUINT) end
			end
		end
	elseif SET.cardAnims and not SET.reduceMotion and #MP.order > 0 then
		for _, id in ipairs(MP.order) do local inst = MP.panels[id]
			if inst and inst.rect then local sx, sy = MP.edgeStart(inst.rect, vpx); tween(inst.frame, 0.26, { Position = UDim2.fromOffset(sx, sy) }, QUINT) end
		end
		task.delay(0.3 * SPEED, function() if MP._visTok == tok then MP.screen.Enabled = false end end)  -- disable only AFTER the slide-out; token guards a re-show landing mid-slide
	else
		MP.screen.Enabled = false
	end
end
function MP.syncTabs()  -- multi mode: light up EVERY open panel's bar button (dot + full-size icon), dim the rest. (single mode uses setActive for the ONE active tab.)
	for tid, t in pairs(tabs) do
		local on = MP.panels[tid] ~= nil
		tween(t.dot, 0.3, { BackgroundTransparency = on and 0 or 1 })
		tween(t.iconScale, 0.3, { Scale = on and 1 or 0.9 }, QUINT)
	end
end
function MP.retheme()  -- re-colour open multi-panels live on a theme / accent change (their chrome + content were built with the OLD T palette, so they'd otherwise stay the old colour)
	for _, id in ipairs(MP.order) do
		local inst = MP.panels[id]
		if inst and inst.frame then
			inst.frame.BackgroundColor3 = T.bg
			local s = inst.frame:FindFirstChildOfClass("UIStroke"); if s then s.Color = T.line end
			buildPageInto(inst.host, inst.sticky, id)  -- rebuild the content in the new colours (accent controls, etc.)
		end
	end
end
function MP.make(id, label, color)  -- one docked panel: header (icon+title+X) + scroll host + sticky; content via buildPageInto
	local f = new("Frame", { Name = "MP_" .. id, BackgroundColor3 = T.bg, BorderSizePixel = 0, ClipsDescendants = true, Size = UDim2.fromOffset(280, 300), Parent = MP.host })
	_KR.panels[f] = true; f.BackgroundTransparency = _KR.glass  -- glassy-panels: a docked panel inherits the current translucency
	new("UIScale", { Scale = UISCALE, Parent = f })  -- scale the WHOLE panel like the single panel does (relayout sets a LOGICAL Size, this renders it back to the screen rect) → content density MATCHES the single panel instead of being double-shrunk to UISCALE² and not filling
	f:SetAttribute("PanelRoot", true)
	corner(f, 14); stroke(f, T.line, 1)
	local head = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 40), Parent = f }); pad(head, 12, 10, 0, 0)
	local iconHost = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(20, 20), BackgroundTransparency = 1, Parent = head })
	local sec = SECTION_BY_ID[id]; local ic = mkIcon((sec and sec.icon) or id, 20); ic.Size = UDim2.fromScale(1, 1); ic.Parent = iconHost
	lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 28, 0.5, 0), Size = UDim2.new(1, -64, 1, 0), Text = label or id, Font = FONTB, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, Parent = head })
	local x = UI.closeBtn(head, 24, 7, 0.2)
	new("Frame", { Position = UDim2.new(0, 12, 0, 40), Size = UDim2.new(1, -24, 0, 1), BackgroundColor3 = T.lineSoft, BorderSizePixel = 0, Parent = f })
	local sticky = new("Frame", { Name = "Sticky", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), Position = UDim2.new(0, 0, 0, 44), AutomaticSize = Enum.AutomaticSize.Y, Parent = f })
	local host = new("ScrollingFrame", { BackgroundTransparency = 1, Position = UDim2.new(0, 0, 0, 44), Size = UDim2.new(1, 0, 1, -44), BorderSizePixel = 0, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 3, ScrollBarImageColor3 = T.line, ScrollingDirection = Enum.ScrollingDirection.Y, Parent = f }); pad(host, 12, 8, 4, 14); vlist(host, 8)
	local function syncMPSticky() _KR.syncStickyZone(host, sticky, 44, nil) end  -- Multi-Panel: 44px header, no edge fade (shared _KR.syncStickyZone)
	sticky:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncMPSticky); syncMPSticky()
	x.MouseButton1Click:Connect(function() MP.close(id) end)
	-- DRAG-TO-DOCK: a transparent handle over the header (minus the close X) lets you drag this panel to a
	-- different perimeter zone; on release it SNAPS to the zone under the cursor (Left / Right / centre-Top).
	local dragHit = new("TextButton", { BackgroundTransparency = 1, AutoButtonColor = false, Text = "", Size = UDim2.new(1, -38, 1, 0), Position = UDim2.new(0, 0, 0, 0), ZIndex = 3, Parent = head })
	do
		local dragging, K, lastZone = false, Vector2.new(0, 0), nil
		local function mpZone(cx, cy, vp) return (cy < vp.Y * 0.34 and cx > vp.X * 0.34 and cx < vp.X * 0.66) and "T" or (cx < vp.X * 0.5 and "L" or "R") end
		local function follow(io)  -- RESIZE f to the hovered slot's shape (top-left anchored), and pin the cursor to its header (horizontal centre, ~18px below top)
			local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
			local zone = mpZone(io.Position.X, io.Position.Y, vp)
			if zone ~= lastZone then  -- hovered a different zone → morph f to that slot + re-highlight
				lastZone = zone
				MP.userZone = MP.userZone or {}; MP.userZone[id] = zone
				MP.relayout(true)  -- other panels glide into the (occ+1) split; f's slot is RESERVED (skipped) into MP._dragSlot
				MP.dragGhost(MP._dragSlot)  -- outline the reserved slot (relayout's EXACT rect, so it aligns with where the panel drops)
			end
			f.Position = UDim2.fromOffset(math.floor(io.Position.X + K.X - f.AbsoluteSize.X / 2), math.floor(io.Position.Y + K.Y - 18))
		end
		local startM, moved = nil, false
		dragHit.InputBegan:Connect(function(io)
			if io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch then
				dragging = true; MP._dragging = id; startM = io.Position; moved = false
				local scr = f:FindFirstAncestorWhichIsA("ScreenGui"); local inset = Vector2.new(0, 0); pcall(function() inset = game:GetService("GuiService"):GetGuiInset() end)
				K = (scr and scr.IgnoreGuiInset) and inset or Vector2.new(0, 0)
				lastZone = nil  -- DRAG-SLOP: don't shrink/reflow/re-dock until the finger actually travels (a bare header tap does nothing)
			end
		end)
		local mc, me
		mc = UserInputService.InputChanged:Connect(function(io)
			if dragging and f.Parent and (io.UserInputType == Enum.UserInputType.MouseMovement or io.UserInputType == Enum.UserInputType.Touch) then
				if not moved and startM and (io.Position - startM).Magnitude > 8 then moved = true; tween(f, 0.15, { Size = UDim2.fromOffset(math.floor(210 / UISCALE), math.floor(132 / UISCALE)) }, QUINT) end  -- real drag: shrink to the proxy
				if moved then follow(io) end
			end
		end)
		me = UserInputService.InputEnded:Connect(function(io)
			if dragging and (io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch) then
