			end
		end)
		f.Destroying:Connect(function() pcall(function() mc:Disconnect() end) pcall(function() me:Disconnect() end) if MP.userZone then MP.userZone[id] = nil end if MP._dragging == id then MP._dragging = nil; MP.dragGhost(nil) end end)  -- destroyed mid-drag (InputEnded is disconnected first): clear the stuck drag state + hide the ghost, else MP.set skips this id forever + the outline lingers
	end
	buildPageInto(host, sticky, id)
	MP.panels[id] = { id = id, frame = f, host = host, sticky = sticky }
	return MP.panels[id]
end
function MP.set(id, x, y, w, h, animate)  -- move/resize one panel's frame to a screen-px rect
	local inst = MP.panels[id]; if not inst then return end
	if id == MP._dragging then return end  -- an active drag owns this panel's Position; don't fight it
	inst.rect = { x = x, y = y, w = w, h = h }  -- SCREEN px (MP.open's entrance slides the newcomer in screen px)
	local pos, size = UDim2.fromOffset(x, y), UDim2.fromOffset(math.floor(w / UISCALE), math.floor(h / UISCALE))  -- Position = screen px (not affected by the frame's own UIScale); Size = LOGICAL so the frame's UIScale renders it back to w×h screen
	if animate and SET.cardAnims and not SET.reduceMotion then tween(inst.frame, 0.4, { Position = pos, Size = size }, QUINT)
	else inst.frame.Position = pos; inst.frame.Size = size end
end
function MP.relayout(animate, instantId)  -- adaptive perimeter: place every open panel around the L/R/top edges. instantId SNAPS that one panel (its own entrance animates it in) while the rest glide.
	-- TUNING NOTE (user, 2026-07-07): only the EXTREME centre must stay clear (so the avatar shows). The centre strip is
	-- pinned to the SmartBar's width + centred on it; the side columns run full-height on the edges, just OUTSIDE that strip.
	local n = #MP.order; if n == 0 then return end
	MP._dragSlot = nil  -- during a drag this gets set to the dragged panel's RESERVED slot rect (below) so the drag preview + ghost use relayout's EXACT geometry
	MP.zones = MP.zones or { { "R" }, { "L", "R" }, { "L", "R", "R" }, { "L", "L", "R", "R" }, { "L", "L", "R", "R", "T" } }  -- perimeter layout per open-panel count; built ONCE (was a fresh literal every relayout). Centre strip (T) only at 5.
	local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)  -- LIVE viewport (the load-time upvalue goes stale on window resize) - same pattern as fitHome/fitSettings
	local margin, gap = 12, 10
	-- V4.5.17: MPHost sits in a ScreenGui whose coord space is inset-SHIFTED on mobile (device safe area) -> MPHost.AbsolutePosition.X is negative, so raw-viewport x placements render off the left edge (the left column bled ~47px off-screen; the whole 2x2 grid looked shifted left with dead space on the right). Offset every HORIZONTAL placement by the host's own left inset so the grid centers on the VISIBLE screen. It is 0 on desktop / edge-to-edge (AbsolutePosition.X == 0), so this is a no-op there. (Vertical already self-corrects: topMargin uses GUI_INSET.Y, which equals the host's top inset.)
	local insetX = math.max(0, math.floor(-((MP.host and MP.host.AbsolutePosition.X) or 0) + 0.5))
	local topMargin = math.max(margin, GUI_INSET.Y + gap)  -- start BELOW the Roblox topbar (coreui: menu/chat/etc.); reuse the boot-cached inset instead of a GetGuiInset() service call every resize tick
	local minCenter = 140  -- the EXTREME centre stays clear (avatar shows through) when no centre strip is shown
	local hasTop = n >= 5  -- a centre (top/bottom) strip appears ONLY at 5 panels now (desktop); mobile caps at 4 → L/R columns only, no strip
	if MP.userZone then for _, _id in ipairs(MP.order) do if MP.userZone[_id] == "T" then hasTop = true; break end end end  -- ...OR when a panel was dragged to the centre-top
	local barW = (bar and bar.AbsoluteSize.X > 10) and bar.AbsoluteSize.X or (vp.X * 0.42)
	local center, bHalf = vp.X / 2, barW / 2
	local sideW
	if hasTop then
		sideW = math.floor(center - bHalf - margin - gap)  -- FILL right up to the bar-width centre strip (no awkward empty gap beside it); only the strip-wide centre stays clear for the avatar
	else
		sideW = math.min(math.clamp(math.floor(vp.X * 0.32), 300, 460), math.floor((vp.X - 2 * margin - minCenter) / 2))  -- no strip: moderate columns, keep the extreme centre clear
	end
	sideW = math.max(160, sideW)
	local topH = math.clamp(math.floor(vp.Y * 0.33), 230, 350)   -- top-centre strip height (taller per user 2026-07-11: 0.24/185-270 -> 0.27/205-300 was too subtle -> now 0.33/230-350). Tune this one line.
	local barClear = BAR_Y + math.ceil(BAR_H * UISCALE * (SET.barSize or 1)) + gap  -- x barSize so docked side columns reserve the right room past a Small/Large bar
	local zones = MP.zones[n]  -- centre strip (T) ONLY at 5 panels (desktop); mobile caps at 4 → everything on the L/R sides
	local left, right, top = {}, {}, nil
	for i, id in ipairs(MP.order) do local z = (MP.userZone and MP.userZone[id]) or zones[i] or "R"; if z == "T" then if not top then top = id else right[#right + 1] = id end elseif z == "L" then left[#left + 1] = id else right[#right + 1] = id end end  -- userZone (drag-to-dock) wins over the auto per-count layout
	-- the SmartBar is CENTRE-aligned, so a side column (far L/R edge) only reserves the bar's edge WHERE they overlap in X.
	local leftHit = (margin + sideW) > (center - bHalf)             -- does the left column overlap the centred bar in X?
	local rightHit = (vp.X - margin - sideW) < (center + bHalf)     -- ...the right column?
	local stripY = SET.barTop and (vp.Y - margin - topH) or topMargin
	local function sideRange(hit)  -- vertical [top, bottom] for a side column; TOP always clears the Roblox topbar (topMargin); reserves the bar's own edge only where they overlap in X
		if SET.barTop then return (hit and barClear or topMargin), (vp.Y - margin) else return topMargin, (vp.Y - (hit and barClear or margin)) end
	end
	local function placeCol(ids, cx, hit)
		local c = #ids; if c == 0 then return end
		local cTop, cBot = sideRange(hit); local span = cBot - cTop; local h = math.floor((span - gap * (c - 1)) / c)
		for i, id in ipairs(ids) do
			local y = math.floor(cTop + (i - 1) * (h + gap))
			if id == MP._dragging then MP._dragSlot = { x = math.floor(cx), y = y, w = sideW, h = h }  -- reserve, don't place: the dragged panel follows the cursor
			else MP.set(id, math.floor(cx), y, sideW, h, animate and id ~= instantId) end
		end
	end
	placeCol(left, insetX + margin, leftHit)
	placeCol(right, insetX + vp.X - margin - sideW, rightHit)
	if top then local tw = math.min(barW, vp.X - 2 * margin)
		if top == MP._dragging then MP._dragSlot = { x = math.floor(insetX + center - tw / 2), y = stripY, w = math.floor(tw), h = topH }
		else MP.set(top, math.floor(insetX + center - tw / 2), stripY, math.floor(tw), topH, animate and top ~= instantId) end
	end  -- centre strip = SmartBar width, centred on the bar (aligned with it)
end
function MP.dragGhost(slot)  -- DRAG-TO-DOCK preview: outline the ONE slot the dragged panel will land in (relayout reserves it in MP._dragSlot). The other panels reflow live via relayout, so this slot sits empty + visible and its rect matches relayout EXACTLY.
	if not MP._ghost then
		MP._ghost = new("Frame", { Name = "DragGhost", BackgroundColor3 = T.accent, BackgroundTransparency = 0.82, BorderSizePixel = 0, Visible = false, ZIndex = 0, Parent = MP.host })
		corner(MP._ghost, 14); local s = stroke(MP._ghost, T.accent, 2); s.Transparency = 0
	end
	if not slot then MP._ghost.Visible = false; return end
	MP._ghost.Position = UDim2.fromOffset(slot.x, slot.y); MP._ghost.Size = UDim2.fromOffset(slot.w, slot.h); MP._ghost.Visible = true
end
function MP.open(id, label, color, btn)
	if MP.panels[id] then MP.close(id); return end  -- already open → tapping its bar button CLOSES it (toggle) - consistent with single-panel mode (tap the active tab to close). Docked panels never overlap, so a front-most "focus" was moot.
	-- MOBILE caps at 4 panels, DESKTOP at 5 (the 5th is the centre strip, which only fits a big screen). V4.5.17: the old gate was TouchEnabled+AccelerometerEnabled, but the Studio device emulator (and some phones) report AccelerometerEnabled=FALSE while KeyboardEnabled/MouseEnabled stay TRUE (the PC's persist through emulation) -> a phone wrongly got cap 5. Robust gate: touch AND (accelerometer OR a phone-small viewport, min side <= 550px). A real PC (no touch) always keeps 5; a touch PC keeps 5 unless its window is phone-tiny.
	local cap = 5; pcall(function()
		local vpS = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
		local smallScreen = vpS ~= nil and math.min(vpS.X, vpS.Y) <= 550
		if UserInputService.TouchEnabled and (UserInputService.AccelerometerEnabled or smallScreen) then cap = 4 end
	end)
	if #MP.order >= cap then toast("Multi-Panel", cap .. " panels open - close one first.", "warn"); return end
	MP.order[#MP.order + 1] = id
	local inst = MP.make(id, label, color)
	MP.relayout(true, id)  -- existing panels GLIDE to their new slots; the newcomer SNAPS to its slot (instantId) so the entrance below isn't fought by a relayout tween
	MP.syncTabs()          -- light up this tab's bar button (its panel is now open)
	local r = inst.rect
	if SET.cardAnims and not SET.reduceMotion and r then
		-- entrance: slide IN from the docked edge (directional - matches where it lands) + a soft scale, while the content cascades in
		local sx, sy = MP.edgeStart(r)
		inst.frame.Position = UDim2.fromOffset(sx, sy)
		tween(inst.frame, 0.42, { Position = UDim2.fromOffset(r.x, r.y) }, QUINT)
	end
end
function MP.close(id)
	local inst = MP.panels[id]; if not inst then return end
	if dropLayer.Parent == inst.frame then hideDropdown() end  -- ONLY if the shared picker is homed in THIS panel: re-home it before we destroy the frame. If it belongs to another still-open panel, leave it alone (don't dismiss someone else's dropdown).
	MP.panels[id] = nil
	for i, v in ipairs(MP.order) do if v == id then table.remove(MP.order, i); break end end
	MP.syncTabs()  -- dim this tab's bar button (its panel is gone)
	if SET.cardAnims and not SET.reduceMotion then tween(inst.frame, 0.2, { Size = UDim2.fromOffset(inst.frame.Size.X.Offset, 0) }); task.delay(0.2 * SPEED, function() inst.frame:Destroy() end)  -- keep the LOGICAL width (frame is UIScale'd now), shrink height to 0
	else inst.frame:Destroy() end
	MP.relayout(true)
end
function MP.closeAll() for _, id in ipairs({ table.unpack(MP.order) }) do MP.close(id) end end
if workspace.CurrentCamera then  -- window resize (desktop/windowed) → re-tile the docked panels to the new viewport. Mobile viewports don't resize, so this is a no-op there.
	MP.vpConn = workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function() if MP.screen.Enabled and #MP.order > 0 then MP.relayout(false) end end)  -- captured so destroyUI can disconnect (was stacking on re-run)
end

local function makeTab(sec, order)
	local col = sec.color
	local b = new("TextButton", { Name = "Tab_" .. sec.id, AutoButtonColor = false, Text = "", Size = UDim2.fromOffset(40, 40), BackgroundColor3 = col, BorderSizePixel = 0, LayoutOrder = order, Parent = bar })
	corner(b, 11); new("UIGradient", { Rotation = 90, Color = ColorSequence.new(col, col:Lerp(Color3.new(0, 0, 0), 0.32)), Parent = b })
	local hoverFill = new("Frame", { BackgroundColor3 = IC, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), BorderSizePixel = 0, Parent = b }); corner(hoverFill, 11)
	local sheen = stroke(b, IC, 1, 1)
	local ic = mkIcon(sec.icon or sec.id, 20); ic.AnchorPoint = Vector2.new(0.5, 0.5); ic.Position = UDim2.fromScale(0.5, 0.5); ic.Parent = b
	local iconScale = new("UIScale", { Scale = 0.9, Parent = ic })
	local lb = lbl({ Size = UDim2.fromScale(1, 1), Text = sec.label or sec.id, Font = FONTB, TextColor3 = IC, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Center, Visible = false, Parent = b })  -- "Labels" bar mode shows this INSTEAD of the icon (A.applyBarLabels toggles visibility + re-widths the button)
	local dot = new("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, -7), Size = UDim2.fromOffset(6, 6), BackgroundColor3 = IC, BackgroundTransparency = 1, BorderSizePixel = 0, Parent = b }); corner(dot, 3)
	tabs[sec.id] = { btn = b, dot = dot, iconScale = iconScale, icon = ic, label = lb }
	-- hover: edge sheen + a subtle fill only. No lift, no scale pop - the icon stays put (user asked for no push-up).
	b.MouseEnter:Connect(function()
		tween(sheen, 0.25, { Transparency = 0.25 })
		tween(hoverFill, 0.3, { BackgroundTransparency = 0.82 })
	end)
	b.MouseLeave:Connect(function()
		tween(sheen, 0.25, { Transparency = 1 })
		tween(hoverFill, 0.3, { BackgroundTransparency = 1 })
	end)
	b.MouseButton1Click:Connect(function() tween(iconScale, 0.14, { Scale = 1.25 }); task.wait(0.1); tween(iconScale, 0.5, { Scale = activeTab == sec.id and 0.9 or 1 }, BACK); onTabClick(sec.id, sec.label, col, b) end)
	return b
end
for i, sec in ipairs(SECTIONS) do makeTab(sec, 2 + i) end  -- all 11 tabs, one bar button each

-- profile avatar on the bar ("my picture"), leftmost via LayoutOrder 0
local avatar = new("ImageButton", { Name = "Avatar", Size = UDim2.fromOffset(38, 38), BackgroundColor3 = T.card, BorderSizePixel = 0, AutoButtonColor = false, Image = "rbxthumb://type=AvatarHeadShot&id=" .. LocalPlayer.UserId .. "&w=48&h=48", LayoutOrder = 0, Parent = bar })
corner(avatar, 19); local avs = stroke(avatar, T.line, 1)
if not SET.barAvatar then useKrulIcon(avatar) end  -- Krul favicon is the DEFAULT bar icon; the "Show my avatar" setting keeps the rbxthumb headshot instead
avatar.MouseEnter:Connect(function() tween(avs, 0.25, { Color = T.accent }) end)
avatar.MouseLeave:Connect(function() tween(avs, 0.25, { Color = T.line }) end)
-- FULL-SCREEN HOME (dim + game blur, floating cards on the left). The favicon opens it.
-- base MUST be white: a UIGradient MULTIPLIES the BackgroundColor3, so a dark base multiplies the gradient to
-- black (that was the "stuck on black" bug). White base -> the gradient shows its true vampiric colours.
local homeView = new("Frame", { Name = "HomeView", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false, Parent = homeScreen })
-- Backdrop kept NEUTRAL GREY (the cards carry the colour, not the background).
local homeBg = new("UIGradient", { Rotation = 90, Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromRGB(42, 42, 48)), ColorSequenceKeypoint.new(0.5, Color3.fromRGB(26, 26, 30)), ColorSequenceKeypoint.new(1, Color3.fromRGB(33, 33, 39)) }), Parent = homeView })
-- BACKGROUND AMBIENT (SET.ambient): a gentle sway of the backdrop gradient while Home is on screen. Manual sine (not a
-- tween) so toggling it off snaps back to 90 with no lingering tween to fight; reads SET.ambient live -> the Motion
-- toggle takes effect instantly, no rebuild. reduceMotion also stills it.
task.spawn(function()
	local t0 = os.clock()
	while homeView.Parent do
		if homeView.Visible and SET.ambient and not SET.reduceMotion then
			homeBg.Rotation = 90 + math.sin((os.clock() - t0) * 0.35) * 8
			task.wait()
		else
			if homeBg.Rotation ~= 90 then homeBg.Rotation = 90 end
			task.wait(0.4)
		end
	end
end)
-- Home is designed at a FIXED width (2 columns) and the whole canvas scales to the device via a UIScale,
-- so mobile gets the EXACT same layout as desktop, just smaller. The scroll frame matches the scaled canvas width.
local HOME_W = 960
-- Home does NOT scroll: it FITS the screen. A plain frame holds the fixed-width canvas; fitHome() scales it to fit.
local homeScroll = new("Frame", { BackgroundTransparency = 1, Position = UDim2.fromOffset(30, 44), Size = UDim2.fromOffset(math.floor(HOME_W * UISCALE), 300), BorderSizePixel = 0, ClipsDescendants = false, Parent = homeView })
local homeCanvas = new("Frame", { Name = "Canvas", BackgroundTransparency = 1, Size = UDim2.fromOffset(HOME_W, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = homeScroll }); vlist(homeCanvas, 12)
local homeCanvasScale = new("UIScale", { Scale = UISCALE, Parent = homeCanvas })
-- scale the fixed 900px-wide canvas so its FULL width + height fit the viewport (no scroll, adapts to any screen).
local function fitHome()
	task.wait()  -- let any pending AutomaticSize.Y settle so we read the true content height
	local cur = homeCanvasScale.Scale
	local ch = homeCanvas.AbsoluteSize.Y / (cur > 0 and cur or 1)  -- LOGICAL height (AbsoluteSize is post-scale). Measured at the CURRENT scale, NOT by flashing to scale 1 -- on mobile that flash briefly rendered the full-width (960px) parked dashboard back on-screen behind Settings, because the parked off-screen offset (~viewport width) is LESS than the full canvas width. This was the bar-size "Home layers below Settings" bleed.
	local cam = workspace.CurrentCamera; local vps = cam and cam.ViewportSize  -- read ViewportSize ONCE (a Vector2) instead of marshaling it twice for .X and .Y
	local vw = (vps and vps.X) or vp.X
	local vh = (vps and vps.Y) or vp.Y
	-- V4.5.17: PHONE-ONLY Home enlargement. On a small (phone) viewport, trim the top/side margins + the bar gap so the tall dashboard fills more of the short screen; DESKTOP keeps its original roomier reserves untouched. OVERFLOW-PROOF by construction: topBase == topM and the position floor is <= topM, so when Home fills availH its bottom lands EXACTLY at (vh - barSpace) and can never pass the SmartBar. (The earlier all-screens attempt overflowed because topBase 20 fell BELOW the 36px floor, shoving Home down into the bar.) Gate on viewport size (min side <= 550px), which cleanly excludes desktop (min side ~730+).
	local isPhone = math.min(vw, vh) <= 550
	local barPad, topM, sideM, floorY = 30, 44, 48, 36  -- desktop reserves (identical to the original)
	if isPhone then barPad, topM, sideM, floorY = 20, 14, 22, 10 end  -- phone: tighter margins -> Home renders larger, still clears the bar by barPad(20)px
	local barSpace = BAR_Y + math.floor(BAR_H * UISCALE * (SET.barSize or 1)) + barPad  -- x barSize so Home reserves room below a larger/smaller bar; barPad is ALSO the guaranteed gap above the bar
	local availW, availH = vw - sideM, vh - barSpace - topM
	-- cap 1.3 (not 1.0): let Home ENLARGE to fill a big screen instead of sitting tiny + centered; still scales DOWN to fit small screens.
	local fit = math.min(availW / HOME_W, (ch > 0) and (availH / ch) or 1, 1.3)
	local s = math.max(0.3, fit)  -- pure fit-to-screen (the old "UI scale %" multiplier was replaced by UI transparency)
	homeCanvasScale.Scale = s
	local sw, sh = HOME_W * s, ch * s
	homeScroll.Size = UDim2.fromOffset(math.ceil(sw), math.ceil(sh))
	local topBase = SET.barTop and (barSpace + 8) or topM  -- when the SmartBar is on top, push the dashboard below it; else = the top margin (== topM, so Home's bottom is exactly vh-barSpace and the barPad gap above the bar is guaranteed)
	-- V4.5.17: center on homeView's OWN width, not the raw viewport. On mobile the ScreenGui's coordinate space is inset-widened (device safe-area), so homeView is WIDER than the viewport and shifted left; centering by raw vw then left-biased the dashboard by half the inset (~47px on an S25U). homeView.AbsoluteSize.X == vw on desktop/edge-to-edge, so this is a no-op there.
	homeScroll.Position = UDim2.fromOffset(math.floor((homeView.AbsoluteSize.X - sw) / 2), math.max(floorY, math.floor(topBase + (availH - sh) / 2)))
end
local A = {}  -- UI-settings apply namespace: the many small apply fns live as table fields, which keeps them off Luau's 200-local main-chunk limit
-- ── Home side panels: left = UI Settings, right = News & Announcements (slide in from the edges) ──────────
local resetSides, placeSideButtons, goTo  -- forward
-- a titled sub-card inside a side view (controls / content go straight into it).
-- Shrink a side view (via a UIScale) so its FULL height fits the viewport - the settings content can be tall.
local function fitSide(panel)
	task.spawn(function()
		local sc = panel:FindFirstChildOfClass("UIScale") or new("UIScale", { Parent = panel })
		sc.Scale = 1; task.wait()  -- measure at natural size
		local cam = workspace.CurrentCamera; local vps = cam and cam.ViewportSize  -- read ViewportSize ONCE (a Vector2) instead of marshaling it twice for .X and .Y
		local vw = (vps and vps.X) or vp.X
		local vh = (vps and vps.Y) or vp.Y
		local w, h = panel.AbsoluteSize.X, panel.AbsoluteSize.Y
		sc.Scale = (w > 0 and h > 0) and math.max(0.4, math.min((vw - 40) / w, (vh - 80) / h, 1)) or 1  -- scale-to-fit BOTH axes on the LIVE viewport (was height-only + stale vp, so News stayed too big on mobile)
	end)
end
-- ── UI Settings: floating cards on the LEFT, a live PREVIEW pane on the RIGHT (no big wrapper container) ──────
-- Sized with MARGINS (not full-screen), centred. LEFT = every card in a 2-col grid (all visible, NO scroll);
-- RIGHT = the preview, shown directly (no sandbox box).
-- Settings is a FIXED-size canvas scaled to fit the screen - EXACTLY like Home. The whole UI (cards + preview) shrinks
-- to fit any device: no reflow, no scroll, no fragile content measurement (which is what kept clipping on mobile).
local SET_W, SET_H = 1180, 720
local settingsPanel = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, vp.X + 40, 0.5, 0), Size = UDim2.fromOffset(SET_W, SET_H), BackgroundTransparency = 1, ZIndex = 8, Parent = homeView })
local settingsScale = new("UIScale", { Scale = 1, Parent = settingsPanel })
local function fitSettings()  -- pure viewport math on the FIXED panel size - reliable, no visibility/layout dependency
	local cam = workspace.CurrentCamera; local vps = cam and cam.ViewportSize  -- read ViewportSize ONCE (a Vector2) instead of marshaling it twice for .X and .Y
	local vw = (vps and vps.X) or vp.X
	local vh = (vps and vps.Y) or vp.Y
	local barZone = BAR_Y + math.floor(BAR_H * UISCALE) + 16  -- SmartBar footprint (gap-from-edge + scaled height + clearance). The panel is centred, so reserve it 2x to clear the bar whether docked Bottom OR Top. V4.5.16: tall (now-labelled) settings content was touching the bar.
	settingsScale.Scale = math.max(0.3, math.min((vw - 40) / SET_W, (vh - math.max(96, barZone * 2)) / settingsPanel.Size.Y.Offset, 1))  -- fit the panel's ACTUAL height (fillSettings grows it to the tallest column, floored at SET_H) so tall content never overflows on mobile
end
