	wave = "The 'RoClothes:Krul' header letters run a continuous Mexican wave.",
	glow = "A spinning rainbow ring around the favicon while Home is open.",
	cardAnims = "Cards and panels deal / morph in when they open (vs. appearing instantly).",
	animSpeed = "How fast every animation plays.",
	toastAnims = "Notifications slide + pop in (vs. just appearing).",
	hoverFx = "Rows brighten and round off when the cursor is over them.",
	reduceMotion = "Master switch: turns off every animation at once (waves, glows, card deals, hover) for a still, calm UI.",
	ambient = "A slow, gentle sway of the Home backdrop. Off = a perfectly still background.",
	privacy = "One switch: hides your name, location and avatar at once (for streaming).",
	hideName = "Replaces your display name and @handle with 'Hidden'.",
	hideLocation = "Masks the server region in the Server card.",
	blurAvatar = "Swaps your Roblox headshot for the brand icon.",
	uiTrans = "Makes the UI see-through - panels, icons + outlines fade; text stays solid + readable.",
