	multiPanel = "Keep up to 5 SmartBar panels open at once, docked around the screen edges.",
	barAvatar = "Puts your Roblox headshot on the SmartBar. Off = the Krul brand icon (the default).",
	barSide = "Docks the SmartBar to the left, centre or right of its edge.",
	clockShow = "Shows or hides the little clock at the left end of the SmartBar.",
	clock24 = "Clock format: 24-hour (15:45) or 12-hour (3:45 PM).",
	barLabels = "SmartBar buttons show either the drawn icon (default) or the section name - your pick, never both.",
	barSize = "Scales the whole SmartBar - Small, Default or Large.",
	notify = "Turns the little corner toast notifications on or off.",
