}
local function miniToggle(parent, on, pos)
	local t = new("Frame", { Position = pos, Size = UDim2.fromOffset(42, 22), BackgroundColor3 = on and T.accent or T.bg, BorderSizePixel = 0, ZIndex = 9, Parent = parent }); corner(t, 11); if not on then stroke(t, T.line, 1) end
	local k = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = on and UDim2.new(1, -19, 0.5, 0) or UDim2.new(0, 3, 0.5, 0), Size = UDim2.fromOffset(16, 16), BackgroundColor3 = on and T.txt or T.txt2, BorderSizePixel = 0, ZIndex = 9, Parent = t }); corner(k, 8)
end
local function renderPreviewVisual(key, stage)
	pad(stage, 6, 6, 6, 4)
	-- sub(i,n,label,hot): one framed mini-screen in a row of n, labelled underneath; hot = accent-highlighted (the current choice)
	local function sub(i, n, label, hot)  -- one mini-screen STACKED top-to-bottom (n rows), labelled under each. No card bg; the CURRENT choice is marked by the accent label only.
		local f = new("Frame", { Position = UDim2.new(0, 4, (i - 1) / n, 4), Size = UDim2.new(1, -8, 1 / n, -24), BackgroundTransparency = 1, ZIndex = 9, Parent = stage })
		lbl({ AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, i / n, -3), Size = UDim2.new(1, 0, 0, 15), Text = label, Font = FONTB, TextColor3 = hot and T.accent or T.txt3, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 9, Parent = stage })
		return f
	end
	local function onoff(build) local cur = SET[key]; build(sub(1, 2, "On", cur == true), true); build(sub(2, 2, "Off", cur == false), false) end  -- two side-by-side On / Off examples, current one highlighted
	-- mini REAL-UI components (so previews look 1-to-1, just minified): the SmartBar pill (icon squares) + a real card.
	local function miniBar(parent, w)
		local bar = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(w or 122, 26), BackgroundColor3 = T.bg, BorderSizePixel = 0, ZIndex = 9, Parent = parent }); corner(bar, 13); stroke(bar, T.line, 1)
		local row = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, -12, 0, 16), BackgroundTransparency = 1, ZIndex = 9, Parent = bar }); new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), HorizontalAlignment = Enum.HorizontalAlignment.Center, VerticalAlignment = Enum.VerticalAlignment.Center, Parent = row })
		local cols = { T.accent, Color3.fromRGB(124, 92, 214), Color3.fromRGB(255, 110, 180), Color3.fromRGB(216, 177, 90), Color3.fromRGB(58, 209, 122), T.accent2 }
		for i = 1, 6 do local ic = new("Frame", { Size = UDim2.fromOffset(14, 14), BackgroundColor3 = cols[((i - 1) % #cols) + 1], BorderSizePixel = 0, LayoutOrder = i, ZIndex = 9, Parent = row }); corner(ic, 5) end
		return bar
	end
	local function miniCard(parent, w, hgt)
		local c = new("Frame", { Size = UDim2.fromOffset(w, hgt), BackgroundColor3 = T.card, BorderSizePixel = 0, ZIndex = 9, Parent = parent }); corner(c, 8); stroke(c, T.lineSoft, 1)
		new("UIGradient", { Rotation = 40, Color = ColorSequence.new(Color3.fromRGB(40, 40, 48), Color3.fromRGB(24, 24, 30)), Parent = c })
		return c
	end
	local function realBar(parent, scale)  -- the ACTUAL SmartBar, cloned (real drawn icons) + scaled for the preview - not a wireframe. Static visual.
		local holder = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1, AutomaticSize = Enum.AutomaticSize.XY, ZIndex = 9, Parent = parent })
		new("UIScale", { Scale = scale or 0.42, Parent = holder })
		local c = bar:Clone(); c.Name = "PrevBar"; c.Visible = true; c.Active = false; c.AnchorPoint = Vector2.new(0, 0); c.Position = UDim2.new(0, 0, 0, 0)
		local cs = c:FindFirstChildOfClass("UIScale"); if cs then cs:Destroy() end  -- the clone carries the live bar's own UIScale=UISCALE; drop it so the holder's flat 0.42 is the ONLY scale (nested UIScales multiply → 0.42×UISCALE, tiny on mobile)
		c.Parent = holder
		return holder
	end
	if key == "theme" then  -- a clickable grid of every preset (tap to apply); current highlighted
		local names = { "Vampiric Noir", "Midnight", "Rose Gold", "Ocean", "Sunset", "Emerald", "Mono", "Crimson", "Ice", "Custom" }
		local grid = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 9, Parent = stage })
		new("UIGridLayout", { CellSize = UDim2.new(1 / 3, -8, 0, 58), CellPadding = UDim2.fromOffset(8, 8), HorizontalAlignment = Enum.HorizontalAlignment.Center, VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder, Parent = grid })
		for i, name in ipairs(names) do
			local isC = name == "Custom"; local acc = isC and SET.accent or A.themes[name].accent; local bgc = isC and SET.custom.bg or A.themes[name].bg[2]; local cur = SET.theme == name
			local cell = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = bgc, BorderSizePixel = 0, LayoutOrder = i, ZIndex = 9, Parent = grid }); corner(cell, 9); stroke(cell, cur and T.accent or T.lineSoft, cur and 1.6 or 1)
			local dot = new("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 7), Size = UDim2.fromOffset(22, 22), BackgroundColor3 = acc, BorderSizePixel = 0, ZIndex = 9, Parent = cell }); corner(dot, 11)
			lbl({ AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -4), Size = UDim2.new(1, -6, 0, 14), Text = name, Font = FONTB, TextColor3 = cur and T.accent or T.txt2, TextSize = 9.5, TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 9, Parent = cell })
			cell.MouseButton1Click:Connect(function() SET.theme = name; A.apply("theme") end)
		end
	elseif key == "accent" then  -- the colour applied to a mini-UI (toggle + slider + hex)
		local demo = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, -18, 0, 150), BackgroundColor3 = T.card, BorderSizePixel = 0, ZIndex = 9, Parent = stage }); corner(demo, 12); stroke(demo, T.lineSoft, 1); pad(demo, 16, 16, 14, 14); vlist(demo, 12)
		local r1 = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 24), LayoutOrder = 1, ZIndex = 9, Parent = demo }); lbl({ Size = UDim2.new(1, -50, 1, 0), Text = "Example toggle", Font = FONTB, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 9, Parent = r1 }); miniToggle(r1, true, UDim2.new(1, -46, 0.5, -11))
		local track = new("Frame", { LayoutOrder = 2, Size = UDim2.new(1, 0, 0, 6), BackgroundColor3 = T.bg, BorderSizePixel = 0, ZIndex = 9, Parent = demo }); corner(track, 3); local fillb = new("Frame", { Size = UDim2.new(0.7, 0, 1, 0), BackgroundColor3 = T.accent, BorderSizePixel = 0, ZIndex = 9, Parent = track }); corner(fillb, 3); new("UIGradient", { Color = ColorSequence.new(T.accent2, T.accent), Parent = fillb })
		local hex = new("Frame", { LayoutOrder = 3, Size = UDim2.new(1, 0, 0, 42), BackgroundColor3 = T.accentD, BorderSizePixel = 0, ZIndex = 9, Parent = demo }); corner(hex, 8); new("UIGradient", { Rotation = 25, Color = ColorSequence.new(T.accent, T.accentD), Parent = hex })
		lbl({ Size = UDim2.fromScale(1, 1), Text = string.format("#%02X%02X%02X", math.floor(T.accent.R * 255 + 0.5), math.floor(T.accent.G * 255 + 0.5), math.floor(T.accent.B * 255 + 0.5)), Font = FONTB, TextColor3 = T.txt, TextSize = 15, ZIndex = 9, Parent = hex })
	elseif key == "bg" then  -- the 4 backdrop styles arranged in the 4 CORNERS (2x2); current marked by its accent label
		local g, acc = A.curBg()
		for i, opt in ipairs({ "Blur", "Gradient", "Solid", "Dim only" }) do
			local cx, cy = (i - 1) % 2, math.floor((i - 1) / 2)  -- column / row of the 2x2
			local q = new("Frame", { Position = UDim2.new(cx * 0.5, 5, cy * 0.5, 5), Size = UDim2.new(0.5, -10, 0.5, -10), BackgroundTransparency = 1, ZIndex = 9, Parent = stage })
			local scene = new("Frame", { Size = UDim2.new(1, 0, 1, -16), BackgroundColor3 = (opt == "Blur" and g[1]) or g[2], BorderSizePixel = 0, ClipsDescendants = true, ZIndex = 9, Parent = q }); corner(scene, 10); stroke(scene, SET.bg == opt and T.accent or T.lineSoft, SET.bg == opt and 1.6 or 1)
			if opt == "Gradient" then new("UIGradient", { Rotation = 90, Color = ColorSequence.new(acc:Lerp(Color3.new(0, 0, 0), 0.5), g[3]), Parent = scene }) end
			if opt == "Dim only" then new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.5, BorderSizePixel = 0, ZIndex = 9, Parent = scene }) end
			new("Frame", { Position = UDim2.new(0, 10, 0, 12), Size = UDim2.new(1, -20, 0, 12), BackgroundColor3 = T.card, BorderSizePixel = 0, ZIndex = 9, Parent = scene })
			new("Frame", { Position = UDim2.new(0, 10, 0, 30), Size = UDim2.new(0.6, 0, 0, 9), BackgroundColor3 = T.card, BorderSizePixel = 0, ZIndex = 9, Parent = scene })
			lbl({ AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, 0), Size = UDim2.new(1, 0, 0, 14), Text = opt, Font = FONTB, TextColor3 = SET.bg == opt and T.accent or T.txt3, TextSize = 10.5, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 9, Parent = q })
		end
	elseif key == "bar" then  -- both dock positions, current highlighted - the ACTUAL SmartBar (cloned) docked on a mini dashboard
		for i, opt in ipairs({ "Bottom", "Top" }) do
			local top = (opt == "Top")
			local p = sub(i, 2, opt, top == (SET.barTop and true or false))
			local cd = miniCard(p, 156, 60); cd.AnchorPoint = Vector2.new(0.5, 0.5); cd.Position = UDim2.new(0.5, 0, 0.5, 0)  -- the dashboard the bar docks to
			local holder = realBar(p, 0.42); holder.Position = top and UDim2.new(0.5, 0, 0.5, -30) or UDim2.new(0.5, 0, 0.5, 30)  -- the ACTUAL SmartBar clone, docked at the card's top / bottom edge
		end
	elseif key == "density" then  -- comfy = roomy gaps (fewer rows); compact = tight gaps so MORE rows fit - SAME row height
		for i, opt in ipairs({ "Comfy", "Compact" }) do
			local p = sub(i, 2, opt, SET.density == opt)
			local comfy = (opt == "Comfy"); local rh = 18  -- SAME height both ways (density changes spacing, not row height)
			local col = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.45), Size = UDim2.new(1, -18, 0, 128), BackgroundTransparency = 1, ZIndex = 9, Parent = p }); new("UIListLayout", { Padding = UDim.new(0, comfy and 9 or 3), VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder, Parent = col })
			for j = 1, (comfy and 4 or 6) do  -- tighter gaps let more rows fit the same column
