				local tg = new("Frame", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(18, 9), BackgroundColor3 = T.accent, BorderSizePixel = 0, ZIndex = 9, Parent = r }); corner(tg, 5)  -- mini toggle
			end
		end
	elseif key == "wave" then
		onoff(function(p, on)
			local BR, cx, letters = "RoClothes:Krul", 0, {}
			local host = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(1, 26), BackgroundTransparency = 1, ZIndex = 9, Parent = p })
			for i = 1, #BR do local ch = BR:sub(i, i); local col = (i >= 11) and Color3.fromRGB(255, 110, 180) or (ch == ":" and Color3.fromRGB(200, 200, 215) or Color3.fromRGB(245, 247, 255))
				local w = 9; pcall(function() w = math.ceil(TextService:GetTextSize(ch, 13, FONTB, Vector2.new(1e4, 1e4)).X) + 1 end)
				local ll = lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, cx, 0.5, 0), Size = UDim2.fromOffset(w, 20), Text = ch, Font = FONTB, TextSize = 13, TextColor3 = col, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 9, Parent = host }); ll.TextStrokeTransparency = 0.5
				letters[i] = { lbl = ll, x = cx }; cx = cx + w end
			host.Size = UDim2.fromOffset(cx, 26)
