				for i, e in ipairs(letters) do local ph = ((t - (i - 1) * 0.07) % 1.4) / 1.4; local y = 0
					if ph < 0.3 then local u = ph / 0.3; y = u * u * (3 - 2 * u) * -6 elseif ph < 0.6 then local u = (ph - 0.3) / 0.3; y = (1 - u * u * (3 - 2 * u)) * -6 end
					e.lbl.Position = UDim2.new(0, e.x, 0.5, math.floor(y)) end; task.wait() end end) end
