			if on then local gs = new("UIStroke", { Thickness = 3, Color = Color3.new(1, 1, 1), Parent = fav }); local gg = new("UIGradient", { Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 84, 96)), ColorSequenceKeypoint.new(0.4, Color3.fromRGB(120, 232, 120)), ColorSequenceKeypoint.new(0.7, Color3.fromRGB(70, 200, 255)), ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 84, 96)) }), Parent = gs }); task.spawn(function() while fav.Parent do gg.Rotation = (gg.Rotation + 3) % 360; task.wait() end end)
