					if on then local sc = new("UIScale", { Scale = 0.8, Parent = c }); c.BackgroundTransparency = 1; task.delay(i * 0.12, function() if c.Parent then tween(sc, 0.5, { Scale = 1 }, BACK); tween(c, 0.4, { BackgroundTransparency = 0 }) end end) end
