					if not p.Parent then break end; tween(row, 0.3, { BackgroundColor3 = T.cardHi }); tween(rs, 0.3, { Color = T.line }); tween(rc, 0.3, { CornerRadius = UDim.new(0, 11) }); task.wait(1.1)
					if not p.Parent then break end; tween(row, 0.3, { BackgroundColor3 = T.card }); tween(rs, 0.3, { Color = T.lineSoft }); tween(rc, 0.3, { CornerRadius = UDim.new(0, 9) }); tween(cur, 0.6, { Position = UDim2.new(0.5, 44, 0.5, 36) }, QUINT); task.wait(0.9)
