			local hl = applied and (key == "privacy" or key == "hideLocation")
			local ba = applied and (key == "privacy" or key == "blurAvatar")
			local card = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, -18, 0, 66), BackgroundColor3 = T.card, BorderSizePixel = 0, ZIndex = 9, Parent = p }); corner(card, 9); stroke(card, T.lineSoft, 1); pad(card, 10, 10, 10, 10)
			local av = new("ImageLabel", { Size = UDim2.fromOffset(44, 44), BackgroundColor3 = T.bg2, BorderSizePixel = 0, Image = "rbxthumb://type=AvatarHeadShot&id=" .. LocalPlayer.UserId .. "&w=100&h=100", ZIndex = 9, Parent = card }); corner(av, 9); if ba then useKrulIcon(av) end
			lbl({ Position = UDim2.new(0, 54, 0, 2), Size = UDim2.new(1, -54, 0, 16), Text = hn and "Hidden" or ((LocalPlayer.DisplayName ~= "" and LocalPlayer.DisplayName) or LocalPlayer.Name), Font = FONTB, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 9, Parent = card })
			lbl({ Position = UDim2.new(0, 54, 0, 20), Size = UDim2.new(1, -54, 0, 13), Text = hn and "@hidden" or ("@" .. LocalPlayer.Name), TextColor3 = T.txt3, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 9, Parent = card })
			lbl({ Position = UDim2.new(0, 54, 0, 35), Size = UDim2.new(1, -54, 0, 12), Text = hl and "Location  •••" or "Location  US-East", TextColor3 = T.txt3, TextSize = 10.5, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 9, Parent = card })
		end)
	elseif key == "animSpeed" then  -- a dot sweeping at the chosen speed
		local dur = 0.9 * (100 / math.max(10, SET.animSpeed))
		local track = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.45), Size = UDim2.new(0.82, 0, 0, 40), BackgroundTransparency = 1, ZIndex = 9, Parent = stage })
		local dot = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(34, 34), BackgroundColor3 = T.accent, BorderSizePixel = 0, ZIndex = 9, Parent = track }); corner(dot, 17)
		task.spawn(function() while dot.Parent do tween(dot, dur, { Position = UDim2.new(1, -34, 0.5, 0) }, QUINT); task.wait(dur + 0.15); if dot.Parent then tween(dot, dur, { Position = UDim2.new(0, 0, 0.5, 0) }, QUINT); task.wait(dur + 0.15) end end end)
		lbl({ AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -6), Size = UDim2.new(1, 0, 0, 20), Text = SET.animSpeed .. "% speed", Font = FONTB, TextColor3 = T.accent, TextSize = 15, ZIndex = 9, Parent = stage })
	elseif key == "uiTrans" then  -- a mini of the real UI that fades to the chosen transparency + back, to demo the effect
		local host = new("CanvasGroup", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.42), Size = UDim2.fromOffset(184, 112), BackgroundTransparency = 1, GroupTransparency = 0, ZIndex = 9, Parent = stage })
		miniCard(host, 84, 72).Position = UDim2.fromOffset(0, 0)
		miniCard(host, 84, 72).Position = UDim2.fromOffset(100, 0)
		local b = miniBar(host, 162); b.AnchorPoint = Vector2.new(0.5, 1); b.Position = UDim2.new(0.5, 0, 1, 0)
		local target = math.max(0.18, math.clamp((SET.uiTrans or 0) / 100, 0, 0.92))  -- pulse to at least 0.18 so the effect is visible even at 0%
		lbl({ AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -6), Size = UDim2.new(1, 0, 0, 18), Text = SET.uiTrans .. "% transparent", Font = FONTB, TextColor3 = T.accent, TextSize = 15, ZIndex = 9, Parent = stage })
		task.spawn(function() while host.Parent do tween(host, 0.9, { GroupTransparency = target }, QUINT); task.wait(1.1); if host.Parent then tween(host, 0.9, { GroupTransparency = 0 }, QUINT); task.wait(1.1) end end end)
	elseif key == "multiPanel" then  -- On = panels docked around the perimeter with the centre (avatar) clear; Off = one panel centred over the middle
		onoff(function(p, on)
			local SW, SH = 168, 86
			local scr = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(SW, SH), BackgroundColor3 = T.bg2, BorderSizePixel = 0, ClipsDescendants = true, ZIndex = 9, Parent = p }); corner(scr, 8); stroke(scr, T.lineSoft, 1)
			local function dock(x, y, w, h)  -- one mini docked panel: accent stroke + a little header bar
				local c = new("Frame", { Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h), BackgroundColor3 = T.card, BorderSizePixel = 0, ZIndex = 10, Parent = scr }); corner(c, 4); stroke(c, T.accent, 1)
				new("Frame", { Position = UDim2.fromOffset(4, 4), Size = UDim2.new(1, -8, 0, 3), BackgroundColor3 = T.accent, BorderSizePixel = 0, ZIndex = 10, Parent = c })
			end
			local av = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(18, 18), BackgroundColor3 = T.card, BorderSizePixel = 0, ZIndex = 9, Parent = scr }); corner(av, 9); stroke(av, T.line, 1)  -- the avatar in the centre
			if on then
				dock(5, 5, 40, SH - 10)             -- left column, full height
				dock(SW - 45, 5, 40, SH - 10)       -- right column, full height
				dock(52, 5, SW - 104, 22)           -- top-centre strip (bar-width, centred) - avatar stays visible below it
			else
				dock((SW - 74) / 2, (SH - 54) / 2, 74, 54)  -- single centred panel, sitting OVER the middle
			end
		end)
	elseif key == "barAvatar" then  -- Krul brand icon (default) vs the player's headshot, as circular bar chips; current highlighted
		for i, opt in ipairs({ "Krul icon", "My avatar" }) do
			local isAv, hot = (i == 2), SET.barAvatar == (i == 2)
			local chip = new("ImageLabel", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(48, 48), BackgroundColor3 = T.card, BorderSizePixel = 0, Image = isAv and ("rbxthumb://type=AvatarHeadShot&id=" .. LocalPlayer.UserId .. "&w=100&h=100") or "", ZIndex = 9, Parent = sub(i, 2, opt, hot) }); corner(chip, 24); stroke(chip, hot and T.accent or T.line, hot and 1.6 or 1)
			if not isAv then useKrulIcon(chip) end
		end
	else
		local val = SET[key]
		local txt = (type(val) == "boolean") and (val and "ON" or "OFF") or tostring(val)
		lbl({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, 0, 0, 44), Text = txt, Font = FONTB, TextColor3 = ((type(val) == "boolean") and val) and T.accent or T.txt, TextSize = 34, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 9, Parent = stage })
	end
end
local function renderPreview(key, label)
	if _KR._prevKey == key and _KR._prevLabel == label then return end  -- key alone isn't unique (Accent swatch + Custom-colours row both use "accent") - compare label too, else the heading stays stale
	_KR._prevKey = key; _KR._prevLabel = label
	for _, c in ipairs(previewBody:GetChildren()) do if not c:IsA("UIPadding") then c:Destroy() end end
	lbl({ Size = UDim2.new(1, 0, 0, 24), Text = label or key, Font = FONTB, TextSize = 18, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 8, Parent = previewBody })
	lbl({ Position = UDim2.new(0, 0, 0, 27), Size = UDim2.new(1, 0, 0, 36), Text = PREV_DESC[key] or "", TextColor3 = T.txt3, TextSize = 12.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 8, Parent = previewBody })
	local stage = new("Frame", { AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, 0), Size = UDim2.new(1, 0, 1, -70), BackgroundTransparency = 1, ZIndex = 8, Parent = previewBody })  -- transparent: the demo shows directly, no sandbox box
	pcall(renderPreviewVisual, key, stage)
	if SET.cardAnims and not SET.reduceMotion then local sc = new("UIScale", { Scale = 0.97, Parent = stage }); tween(sc, 0.3, { Scale = 1 }, BACK) end  -- gentle materialise on each preview swap (GC'd with the stage on the next render)
end
local function refreshPreview() if _KR.saveCfg then _KR.saveCfg() end; if _KR._prevKey then local k, l = _KR._prevKey, _KR._prevLabel; _KR._prevKey = nil; renderPreview(k, l) end end  -- auto-save the config (debounced) + re-render the CURRENT preview so its demo reflects a live SET change. refreshPreview is called after EVERY settings change (A.apply ends with it; the preview-only toggles call it directly), so it's the one save chokepoint.
local function clearPreview() for _, c in ipairs(previewBody:GetChildren()) do if not c:IsA("UIPadding") then c:Destroy() end end; _KR._prevKey = nil end  -- tears down the preview so its animation loops stop (called when the menu closes)
-- ── News & Announcements - master-detail (left headline list ↔ right inline reader pane), backend-driven ─────
local newsPanel, renderNews  -- forward: newsPanel drives the carousel, renderNews is called by the live fetch (Phase B)
do
	local PW, PH = 1040, 700  -- FIXED design size (like Settings' SET_W/SET_H); fitSide scales-to-fit both axes, so it shrinks to the device instead of adapting-then-staying-big
	newsPanel = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, vp.X + 40, 0.5, 0), Size = UDim2.fromOffset(PW, PH), BackgroundTransparency = 1, ZIndex = 8, Parent = homeView })
	local hd = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 46), Parent = newsPanel })
	lbl({ Size = UDim2.new(1, 0, 0, 24), Text = "News & Announcements", Font = FONTB, TextSize = 22, TextXAlignment = Enum.TextXAlignment.Left, Parent = hd })
	lbl({ Position = UDim2.new(0, 0, 0, 25), Size = UDim2.new(1, 0, 0, 15), Text = "Latest from KrulHub - pick a story on the left.", TextColor3 = T.txt3, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, Parent = hd })
	-- MASTER-DETAIL layout: left = a compact scrollable headline list, right = the selected story read inline (no full-screen overlay).
	local list = new("ScrollingFrame", { Position = UDim2.fromOffset(0, 58), Size = UDim2.new(0.34, -10, 1, -58), BackgroundTransparency = 1, BorderSizePixel = 0, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 4, ScrollBarImageColor3 = T.line, ScrollBarImageTransparency = 0.5, ScrollingDirection = Enum.ScrollingDirection.Y, ZIndex = 8, Parent = newsPanel }); vlist(list, 7); pad(list, 1, 8, 2, 8)
	new("Frame", { Position = UDim2.new(0.34, 0, 0, 64), Size = UDim2.new(0, 1, 1, -78), BackgroundColor3 = T.line, BackgroundTransparency = 0.5, BorderSizePixel = 0, ZIndex = 8, Parent = newsPanel })  -- divider between list + detail
	local detail = new("ScrollingFrame", { Position = UDim2.new(0.34, 16, 0, 56), Size = UDim2.new(0.66, -16, 1, -56), BackgroundTransparency = 1, BorderSizePixel = 0, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.None, ScrollBarThickness = 5, ScrollBarImageColor3 = T.line, ScrollBarImageTransparency = 0.4, ScrollingDirection = Enum.ScrollingDirection.Y, ZIndex = 8, Parent = newsPanel }); vlist(detail, 11); pad(detail, 2, 12, 2, 14)
	-- CANVAS driven MANUALLY (not AutomaticCanvasSize): with the panel's fitSide UIScale above it, AutomaticCanvasSize left
	-- dead scroll space at the bottom on mobile. AbsoluteContentSize is POST-scale → ÷ the effective ancestor scale, + the
	-- detail's own top/bottom padding (2+14). The do-block scopes both locals so they never touch the 200-local budget.
	do
		local dl = detail:FindFirstChildOfClass("UIListLayout")
		local function syncCanvas()
			local k = 1; local o = detail; while o and o.Parent do local s = o:FindFirstChildOfClass("UIScale"); if s then k = k * s.Scale end; o = o.Parent end
			detail.CanvasSize = UDim2.new(0, 0, 0, math.ceil(dl.AbsoluteContentSize.Y / math.max(k, 0.01)) + 16)
		end
		dl:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(syncCanvas); syncCanvas()
	end
	local NEWS = {
		{ title = "GUI Redesign shipped", date = "Jul 4", cat = "Update", new = true, image = "https://picsum.photos/seed/krulhub/720/320", body = "The new SmartBar home is live: per-tab colour families, a smooth, staggered motion pass, a redesigned Settings panel with live previews, and 10 colour themes plus a full Custom theme. Nearly every control now does something real - tap around every tab and see." },
		{ title = "Catalog browser", date = "Jun 28", cat = "Update", new = false, body = "Browse the Roblox marketplace right inside the hub, strip the default avatar, try items on, and save the fits you like straight into your bundles. By-ID and Browser modes are both supported." },
		{ title = "Outfit contest", date = "Jun 20", cat = "Event", new = false, body = "Post your best RoClothes fit in the Discord - the top three each week get featured in-hub and a role. Judged on creativity and how well it uses the layering system. Ends soon!" },
		{ title = "Discord milestone", date = "Jun 12", cat = "Community", new = false, body = "discord.gg/SBUuYsnShf just hit a new member milestone - thank you all. Previews, betas and update notes always land there first, and support is fastest in the help channels." },
	}
	local NEWS_CAT = { Update = Color3.fromRGB(96, 150, 240), Event = Color3.fromRGB(233, 74, 128), Community = Color3.fromRGB(72, 200, 130), Guide = Color3.fromRGB(214, 174, 88) }
	local function catCol(c) return NEWS_CAT[c] or T.accent end
	local function loadNewsImage(parent, url)  -- proxy the external image via /chat/img, write to disk, getcustomasset, overlay it; animates GIF sprite-sheets. Cached per-URL for the session so re-opening a story is instant (no re-download / re-write), which is what removes the load hitch.
		if type(url) ~= "string" or url == "" then return end
		local function apply(asset, m)  -- overlay the loaded asset + size the slot to its aspect. Shared by the cache-hit path and the fresh download so the layout is identical either way.
			if not parent.Parent then return end
			-- FULL WIDTH, no black bars: size the slot to the image's OWN aspect (full width, height derived) so it fills exactly.
			-- Crop (not Fit) so a missing dimension fills the slot instead of letterboxing to black. The clamp is a wide sanity bound only.
			local il = new("ImageLabel", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Image = asset, ScaleType = Enum.ScaleType.Crop, BorderSizePixel = 0, ZIndex = 8, Parent = parent }); corner(il, 12)
			local deco = parent:FindFirstChild("Deco"); if deco then deco.Visible = false end  -- real image is up: hide the placeholder badges so they can't block it
			local imW, imH = m.imW, m.imH
			if m.gif then  -- the proxy returns a sprite-sheet PNG + metadata; flip-book it (Roblox can't animate a gif)
				imW, imH = m.fw, m.fh
				il.ScaleType = Enum.ScaleType.Stretch; il.ImageRectSize = Vector2.new(m.fw, m.fh)
				task.spawn(function() local f = 0; while il.Parent do f = (f % m.frames) + 1; il.ImageRectOffset = Vector2.new(((f - 1) % m.cols) * m.fw, math.floor((f - 1) / m.cols) * m.fh); task.wait(m.durs[f] or 0.08) end end)
			end
			if imW and imH and imW > 0 and imH > 0 then
				parent.Size = UDim2.new(1, 0, 0, math.floor((0.66 * PW - 30) / math.clamp(imW / imH, 0.2, 6)))  -- slot height = KNOWN logical width / real aspect (deterministic, scale-independent; plain offset keeps AutomaticCanvasSize correct)
			end
		end
		local cache = A._newsImg; if not cache then cache = {}; A._newsImg = cache end  -- session cache: url -> { path, dims, gif metadata }
		local hit = cache[url]
		if hit then  -- already fetched this story this session: reuse the on-disk file, NO network and NO re-write (this is what kills the navigation hitch)
			local exists = false; pcall(function() exists = (isfile and isfile(hit.path)) or false end)
			if exists then local oka, asset = pcall(getcustomasset, hit.path); if oka and type(asset) == "string" then apply(asset, hit); return end end
		end
		task.spawn(function()
			local req = request or http_request or (syn and syn.request) or (http and http.request)
			local wf, gca = writefile, getcustomasset
			if not (req and wf and gca) then return end
			-- V4.5.20 FIX: news images now live on krulhub.dev/news-img (self-hosted, R2). The /chat/img proxy
			-- returns 502 on same-zone URLs (a Cloudflare Worker can't subrequest its own zone), which blanked
			-- EVERY news/announcement image + gif. Fetch krulhub.dev-hosted images DIRECTLY (no proxy needed for
			-- our own CDN); keep the proxy only for EXTERNAL urls (Discord etc., which also need its X-Img-W/H +
			-- gif-sprite metadata). A direct static PNG has no X-Img headers, so it sizes to the default 16:9 slot.
			local fetchUrl
			if url:match("^https?://krulhub%.dev/") then
				fetchUrl = url
			else
				local enc = url; pcall(function() enc = game:GetService("HttpService"):UrlEncode(url) end)
				fetchUrl = "https://krulhub.dev/chat/img?u=" .. enc
			end
			local ok, res = pcall(req, { Url = fetchUrl, Method = "GET" })
			if not ok or type(res) ~= "table" or not res.Body or (tonumber(res.StatusCode) or tonumber(res.Status) or 200) >= 300 then return end  -- V4.5.19: tonumber - a string StatusCode ("200") made "200">=300 THROW here (ordered string-vs-number compare) inside this bare task.spawn, killing every news-image load for the session
			local hdr = res.Headers or res.headers or {}
			local function H(k) return hdr[k] or hdr[string.lower(k)] or hdr[string.upper(k)] end
			local ext = string.find((H("Content-Type") or ""), "jpeg") and ".jpeg" or ".png"  -- getcustomasset validates the extension
			local pathf = "krulnews_" .. tostring(#res.Body) .. "_" .. (url:gsub("%W", ""):sub(-14)) .. ext
			local already = false; pcall(function() already = (isfile and isfile(pathf)) or false end)
			if not already then task.wait(); if not pcall(wf, pathf, res.Body) then return end end  -- yield so the ~1MB synchronous write lands on a fresh frame (not the click's); skip the write entirely if already on disk
			local oka, asset = pcall(gca, pathf)
			if not oka or type(asset) ~= "string" or not parent.Parent then return end
			local m = { path = pathf, imW = tonumber(H("X-Img-W")), imH = tonumber(H("X-Img-H")) }
			if (H("X-Img-Type") or "") == "gif" then
				m.gif = true
				m.frames = tonumber(H("X-Frames")) or 1; m.cols = tonumber(H("X-Cols")) or 1
				m.fw = tonumber(H("X-Frame-W")) or 100; m.fh = tonumber(H("X-Frame-H")) or 100
				m.durs = {}; for d in string.gmatch(tostring(H("X-Durations") or ""), "[^,]+") do m.durs[#m.durs + 1] = (tonumber(d) or 80) / 1000 end
			end
			cache[url] = m  -- remember for instant re-views this session
			apply(asset, m)
		end)
	end
	local function imageBlock(parent, item)  -- category-tinted placeholder; overlays the real image/GIF (loadNewsImage) when item.image is set
		local img = new("Frame", { Size = UDim2.new(1, 0, 0, math.floor((0.66 * PW - 30) * 9 / 16)), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ClipsDescendants = true, ZIndex = 8, Parent = parent }); corner(img, 12)  -- FULL WIDTH; height = the KNOWN logical content width (0.66·PW − insets) ÷ aspect (16:9 placeholder; loadNewsImage sets the real aspect). A PLAIN OFFSET height, NOT a UIAspectRatioConstraint - the constraint + Scale-width combo silently broke the detail ScrollingFrame's AutomaticCanvasSize (image vanished + body clipped on PC). Crop fills it → full width, no bars.
		new("UIGradient", { Rotation = 40, Color = ColorSequence.new(catCol(item.cat):Lerp(Color3.fromRGB(20, 20, 26), 0.12), catCol(item.cat):Lerp(Color3.fromRGB(14, 14, 19), 0.72)), Parent = img })
		-- Placeholder badges live in one group so loadNewsImage can hide them the moment the real image loads - otherwise
		-- they sit ON TOP of the photo and block its content (the reader header below already shows the category + date).
		local deco = new("Frame", { Name = "Deco", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 9, Parent = img })
		lbl({ AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -12, 1, -8), Size = UDim2.new(0, 80, 0, 34), Text = "KRUL", Font = FONTB, TextColor3 = Color3.new(1, 1, 1), TextTransparency = 0.84, TextSize = 24, TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 9, Parent = deco })
		local tag = new("Frame", { Position = UDim2.new(0, 12, 0, 12), Size = UDim2.new(0, 0, 0, 20), AutomaticSize = Enum.AutomaticSize.X, BackgroundColor3 = catCol(item.cat), BorderSizePixel = 0, ZIndex = 9, Parent = deco }); corner(tag, 6); pad(tag, 8, 8, 0, 0)
		lbl({ AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 1, 0), Text = string.upper(item.cat or "News"), Font = FONTB, TextColor3 = Color3.new(1, 1, 1), TextSize = 10.5, ZIndex = 9, Parent = tag })
		if item.new then local nb = new("Frame", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 12), Size = UDim2.fromOffset(40, 20), BackgroundColor3 = T.bad, BorderSizePixel = 0, ZIndex = 9, Parent = deco }); corner(nb, 6); lbl({ Size = UDim2.fromScale(1, 1), Text = "NEW", Font = FONTB, TextColor3 = Color3.new(1, 1, 1), TextSize = 10, ZIndex = 9, Parent = nb }) end
		if item.image then loadNewsImage(img, item.image) end  -- overlay the real image/GIF (stays on the gradient if it can't load)
		return img
	end
	-- News title + body just use Roblox's NATIVE AutomaticSize.Y (see renderDetail): the ACTUAL TextLabel render, exact on
	-- every client. Every GetTextSize variant mismatched the mobile client's text layout (it over-counted lines → the
	-- body-to-button gap that no measuring-math fixed). The manual detail canvas reads AbsoluteContentSize, so it tracks the
	-- AutomaticSize'd heights automatically - same as the image (deterministic offset) at the top: nothing is hand-measured.
	-- DETAIL pane: render the selected story inline (image + title + meta + full body + action button).
	local _shownItem  -- the story currently in the reader; lets a live re-render skip rebuilding an unchanged one
	local function sameNews(a, b) return a and b and a.title == b.title and a.body == b.body and a.image == b.image and a.link == b.link and a.linkLabel == b.linkLabel and a.cat == b.cat and a.date == b.date end
	local function renderDetail(item)
		if item and sameNews(item, _shownItem) then return end  -- SAME story on a 60s-poll re-render → keep the pane (don't reload the image or snap the reader's scroll back to the top)
		_shownItem = item
		for _, ch in ipairs(detail:GetChildren()) do if not (ch:IsA("UIListLayout") or ch:IsA("UIPadding") or ch:IsA("UIScale")) then ch:Destroy() end end
		if not item then
			lbl({ Size = UDim2.new(1, 0, 0, 40), Text = "No news right now.", TextColor3 = T.txt3, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Center, LayoutOrder = 1, Parent = detail })
			return
		end
		imageBlock(detail, item).LayoutOrder = 1  -- loadNewsImage sizes the slot to each image's aspect (full width, no bars)
		local body = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, ZIndex = 8, Parent = detail }); pad(body, 4, 6, 12, 4); vlist(body, 9)
		lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = item.title, Font = FONTB, TextSize = 22, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, TextWrapped = true, LayoutOrder = 1, ZIndex = 8, Parent = body })
		lbl({ Size = UDim2.new(1, 0, 0, 15), Text = string.upper(item.cat or "News") .. "   ·   " .. (item.date or ""), TextColor3 = catCol(item.cat), Font = FONTB, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 2, ZIndex = 8, Parent = body })
		lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = item.body or "", TextColor3 = T.txt2, TextSize = 14, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, LayoutOrder = 3, ZIndex = 8, Parent = body })  -- NATIVE AutomaticSize.Y = the real render height on any client (GetTextSize mismatched the mobile text layout → the gap)
		UI.button(body, item.linkLabel or "Join Discord", "primary", 4, function() local lnk = item.link or "discord.gg/SBUuYsnShf"; local ok = setclipboard and pcall(setclipboard, lnk:find("://") and lnk or ("https://" .. lnk)); toast("Discord", ok and (lnk .. " copied.") or "No clipboard on this executor.", ok and "ok" or "warn") end)
		detail.CanvasPosition = Vector2.new(0, 0)  -- reset scroll to top on each switch (no UIScale on the ScrollingFrame - it breaks AutomaticCanvasSize, which clipped long article bodies)
	end
	-- MASTER list: compact headline rows; the selected row is highlighted (bg + accent bar) and drives the detail pane.
	local _selRow, _selIdx = nil, 1
	local function setRowSel(row, on)
		tween(row, 0.15, { BackgroundTransparency = on and 0 or 1 })
		local sb = row:FindFirstChild("SelBar"); if sb then tween(sb, 0.15, { BackgroundTransparency = on and 0 or 1 }) end
	end
	local function selectRow(row, item, idx)
		if _selRow == row then return end
		if _selRow and _selRow.Parent then setRowSel(_selRow, false) end
		_selRow, _selIdx = row, idx; setRowSel(row, true); renderDetail(item)
	end
	local function headlineRow(item, idx)
		local row = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = T.cardHi, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 56), LayoutOrder = idx, ZIndex = 8, Parent = list }); corner(row, 10)
		local sb = new("Frame", { Name = "SelBar", AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(3, 32), BackgroundColor3 = catCol(item.cat), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 9, Parent = row }); corner(sb, 2)
		local dot = new("Frame", { Position = UDim2.fromOffset(14, 12), Size = UDim2.fromOffset(6, 6), BackgroundColor3 = catCol(item.cat), BorderSizePixel = 0, ZIndex = 9, Parent = row }); corner(dot, 3)
		lbl({ Position = UDim2.new(0, 26, 0, 9), Size = UDim2.new(1, -92, 0, 13), Text = string.upper(item.cat or "News"), Font = FONTB, TextColor3 = catCol(item.cat), TextSize = 10, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 9, Parent = row })
		lbl({ AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 9), Size = UDim2.new(0, 60, 0, 13), Text = item.date or "", TextColor3 = T.txt3, TextSize = 10.5, TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 9, Parent = row })
		lbl({ Position = UDim2.new(0, 14, 0, 26), Size = UDim2.new(1, item.new and -60 or -26, 0, 20), Text = item.title, Font = FONTB, TextColor3 = T.txt, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 9, Parent = row })
		if item.new then local nb = new("Frame", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0, 36), Size = UDim2.fromOffset(34, 15), BackgroundColor3 = T.bad, BorderSizePixel = 0, ZIndex = 9, Parent = row }); corner(nb, 5); lbl({ Size = UDim2.fromScale(1, 1), Text = "NEW", Font = FONTB, TextColor3 = Color3.new(1, 1, 1), TextSize = 8.5, ZIndex = 9, Parent = nb }) end
		return row
	end
	renderNews = function(items)
		items = (items and #items > 0) and items or NEWS
		for _, ch in ipairs(list:GetChildren()) do if not (ch:IsA("UIListLayout") or ch:IsA("UIPadding")) then ch:Destroy() end end
		_selRow = nil
		local keep = math.clamp(_selIdx or 1, 1, #items)  -- keep the reader on the same slot across live re-renders
		local rRef, iRef
		for i, it in ipairs(items) do
			local row = headlineRow(it, i)
			row.MouseButton1Click:Connect(function() selectRow(row, it, i) end)
			row.MouseEnter:Connect(function() if _selRow ~= row then tween(row, 0.12, { BackgroundTransparency = 0.55 }) end end)
			row.MouseLeave:Connect(function() if _selRow ~= row then tween(row, 0.12, { BackgroundTransparency = 1 }) end end)
			if i == keep then rRef, iRef = row, it end
		end
		if rRef then selectRow(rRef, iRef, keep) end
	end
	renderNews()
	-- LIVE: poll krulhub.dev/news so the feed is backend-controlled + updates itself; re-renders ONLY when the
	-- payload changes (so it doesn't interrupt scrolling/reading); falls back to the built-in NEWS if HTTP is blocked.
	task.spawn(function()
		local lastRaw; task.wait(0.6)
		while newsPanel.Parent do
			local res
			local req = request or http_request or (syn and syn.request) or (http and http.request)
			if req then local ok, out = pcall(req, { Url = "https://krulhub.dev/news", Method = "GET" }); if ok and type(out) == "table" then res = out.Body end end
			if not res then pcall(function() res = game:HttpGet("https://krulhub.dev/news") end) end
			if not res and not _KR.dataOfflineAuto then  -- both request() and game:HttpGet failed -> krulhub.dev unreachable. Announce ONCE via a NON-BLOCKING toast; the built-in feed still shows. (A full-screen modal here sank all screen input at boot - a background failure must never grab a blocking popup.)
				_KR.dataOfflineAuto = true; toast("Data servers", "Couldn't reach krulhub.dev - showing the built-in news feed.", "warn")
			end
			if res and res ~= lastRaw then
				lastRaw = res
				local d; pcall(function() d = game:GetService("HttpService"):JSONDecode(res) end)
				if d and type(d.items) == "table" and #d.items > 0 then renderNews(d.items) end
			end
			task.wait(60)
		end
	end)
end
_curPage = "uiset"  -- state-store prefix for the settings controls
-- Built by a FUNCTION (not an inline block) so "Reset to defaults" can rebuild the controls straight from SET -
-- the knobs actually snap back. Clearing the uiset state-store keys at the top guarantees every rebuild seeds
-- from SET (the source of truth), never a stale persisted value.
-- Theme presets. Defined HERE - before fillSettings' boot-time preview seed (renderPreview "theme") reads them -
-- rather than down with the apply fns, else the FIRST UI-Settings open shows a blank theme grid: the seed indexed
-- a nil A.themes and the error was swallowed by the preview pcall. The apply fns further down use this table too.
A.themes = {
	["Vampiric Noir"] = { accent = Color3.fromRGB(233, 74, 128), bg = { Color3.fromRGB(42, 42, 48), Color3.fromRGB(26, 26, 30), Color3.fromRGB(33, 33, 39) } },
	["Midnight"]      = { accent = Color3.fromRGB(96, 150, 240), bg = { Color3.fromRGB(26, 30, 44), Color3.fromRGB(17, 19, 28), Color3.fromRGB(21, 24, 36) } },
	["Rose Gold"]     = { accent = Color3.fromRGB(232, 150, 132), bg = { Color3.fromRGB(46, 38, 40), Color3.fromRGB(30, 25, 27), Color3.fromRGB(38, 30, 32) } },
	["Ocean"]         = { accent = Color3.fromRGB(64, 196, 224), bg = { Color3.fromRGB(28, 40, 52), Color3.fromRGB(18, 26, 34), Color3.fromRGB(22, 32, 42) } },
	["Sunset"]        = { accent = Color3.fromRGB(255, 138, 76), bg = { Color3.fromRGB(48, 34, 34), Color3.fromRGB(30, 22, 24), Color3.fromRGB(40, 28, 28) } },
	["Emerald"]       = { accent = Color3.fromRGB(72, 200, 130), bg = { Color3.fromRGB(28, 42, 36), Color3.fromRGB(18, 28, 24), Color3.fromRGB(22, 34, 28) } },
	["Mono"]          = { accent = Color3.fromRGB(200, 205, 220), bg = { Color3.fromRGB(40, 40, 44), Color3.fromRGB(24, 24, 27), Color3.fromRGB(31, 31, 35) } },
	["Crimson"]       = { accent = Color3.fromRGB(232, 72, 84), bg = { Color3.fromRGB(46, 34, 36), Color3.fromRGB(28, 20, 22), Color3.fromRGB(37, 26, 28) } },
	["Ice"]           = { accent = Color3.fromRGB(150, 200, 255), bg = { Color3.fromRGB(34, 40, 50), Color3.fromRGB(22, 27, 34), Color3.fromRGB(27, 33, 42) } },
}
local function fillSettings()
	_curPage = "uiset"  -- a SmartBar tab open may have moved _curPage; restore it so controls key + the clear-loop below stay consistent
	for k in pairs(S) do if type(k) == "string" and k:sub(1, 6) == "uiset\1" then S[k] = nil end end
	for _, c in ipairs(setLeft:GetChildren()) do if not c:IsA("UIListLayout") then c:Destroy() end end
	local setRow, sL, sM, sR = twoCol(setLeft, 1, 3)  -- THREE columns: shorter columns = a shorter canvas = far less shrink on mobile. setRow (the wrapper) AutomaticSize.Y = the tallest column, measured below to grow the canvas so nothing overflows
	local function P(row, key, label) if row then row.MouseEnter:Connect(function() renderPreview(key, label) end) end; return row end  -- hover a control -> preview it
	-- AUTO-BALANCE: each section drops into whichever column is currently shorter (its control count + 1 for the header),
	-- so the two columns always end near-level no matter how many sections exist - no dead space at the bottom of one
	-- column. Definition order is preserved WITHIN a column. `rows` = the controls the section holds (its height proxy).
	-- pre-assign each section to the shortest of the 3 columns, LARGEST first (largest-first greedy packs far tighter
	-- than build-order, so all three columns end near-level -- no dead space). SECS = each section's control count.
	local SECS = { { "Appearance", SET.theme == "Custom" and 7 or 6 }, { "Motion", 8 }, { "Privacy", 4 }, { "Layout", 3 }, { "SmartBar", 9 }, { "Actions", 2 }, { "Behavior", 3 } }
	table.sort(SECS, function(a, b) return a[2] > b[2] end)
	local colH, colO, assign, cols = { 0, 0, 0 }, { 0, 0, 0 }, {}, { sL, sM, sR }
	for _, s in ipairs(SECS) do local m = 1; if colH[2] < colH[m] then m = 2 end; if colH[3] < colH[m] then m = 3 end; colH[m] = colH[m] + s[2] + 1; assign[s[1]] = m end
	local function sec(name) local m = assign[name] or 1; colO[m] = colO[m] + 1; return tile(cols[m], name, colO[m]) end  -- build order preserved WITHIN each pre-assigned column
	-- Appearance
	local ap = sec("Appearance")
	P(UI.swatch(ap, "Accent colour", SET.accent, 1, function(c) SET.accent = c; A.apply("accent") end), "accent", "Accent colour")
	P(UI.cyc(ap, "Theme", { "Vampiric Noir", "Midnight", "Rose Gold", "Ocean", "Sunset", "Emerald", "Mono", "Crimson", "Ice", "Custom" }, 2, function(o) SET.theme = o; A.apply("theme") end, SET.theme), "theme", "Theme")
	P(UI.cyc(ap, "Background", { "Blur", "Gradient", "Solid", "Dim only" }, 3, function(o) SET.bg = o; A.apply("bg") end, SET.bg), "bg", "Background")
	if SET.theme == "Custom" then  -- a COMPACT single row of the 4 custom-colour swatches (so the card doesn't elongate off-screen)
		local cr = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 54), LayoutOrder = 4, Parent = ap })
		cr.MouseEnter:Connect(function() renderPreview("accent", "Custom colours") end)
		lbl({ Size = UDim2.new(1, 0, 0, 15), Text = "Custom colours", Font = FONTB, TextColor3 = T.txt2, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, Parent = cr })
		local sw = new("Frame", { BackgroundTransparency = 1, Position = UDim2.new(0, 0, 0, 18), Size = UDim2.new(1, 0, 0, 36), Parent = cr }); new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 8), Parent = sw })
		for _, it in ipairs({ { "Accent 2", "accent2" }, { "Card", "card" }, { "Backdrop", "bg" }, { "Text", "text" } }) do
			local ck = it[2]
			local cell = new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromOffset(55, 36), Parent = sw })
			-- The border is a FILLED FRAME behind the chip (not a UIStroke) so it renders reliably no matter what an
			-- entrance/transparency pass does to stroke transparency -- a plain BackgroundTransparency is simpler here.
			local bord = new("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 0), Size = UDim2.fromOffset(38, 26), BackgroundColor3 = Color3.fromRGB(164, 169, 186), BorderSizePixel = 0, Parent = cell }); corner(bord, 7)
			local chip = new("TextButton", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.fromOffset(34, 22), BackgroundColor3 = SET.custom[ck], AutoButtonColor = false, Text = "", BorderSizePixel = 0, Parent = bord }); corner(chip, 6)
			lbl({ AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, 0), Size = UDim2.new(1, 0, 0, 12), Text = it[1], TextColor3 = T.txt3, TextSize = 9.5, TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.AtEnd, Parent = cell })
			chip.MouseButton1Click:Connect(function() openColorPicker(SET.custom[ck], function(c) SET.custom[ck] = c; A.apply("theme") end) end)
		end
	end
	-- Accent presets: quick-pick swatches that set JUST the accent (your theme's backdrop stays). Tap-to-apply, live.
	do
		local pr = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 52), LayoutOrder = 5, Parent = ap })
		pr.MouseEnter:Connect(function() renderPreview("accent", "Accent presets") end)
		lbl({ Size = UDim2.new(1, 0, 0, 15), Text = "Accent presets", Font = FONTB, TextColor3 = T.txt2, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, Parent = pr })
		local chips = new("Frame", { BackgroundTransparency = 1, Position = UDim2.new(0, 0, 0, 19), Size = UDim2.new(1, 0, 0, 32), Parent = pr }); new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), VerticalAlignment = Enum.VerticalAlignment.Center, Parent = chips })  -- gap 4 so 8x24 + 7x4 = 220 fits the ~224px column (was 30px+6gap = 282 -> overflowed the card's right edge)
		for _, col in ipairs({ Color3.fromRGB(233, 74, 128), Color3.fromRGB(232, 72, 84), Color3.fromRGB(255, 138, 76), Color3.fromRGB(216, 177, 90), Color3.fromRGB(72, 200, 130), Color3.fromRGB(64, 196, 224), Color3.fromRGB(96, 150, 240), Color3.fromRGB(168, 120, 240) }) do
			local sel = SET.accent == col
			local chip = new("TextButton", { Size = UDim2.fromOffset(24, 24), BackgroundColor3 = col, AutoButtonColor = false, Text = "", BorderSizePixel = 0, Parent = chips }); corner(chip, 12); stroke(chip, sel and T.txt or T.line, sel and 2 or 1)  -- 24px: 8 swatches must FIT the column (30px overflowed). The whole settings scales uniformly, so logical fit holds on every device.
			chip.MouseButton1Click:Connect(function() SET.accent = col; A.apply("accent") end)
		end
	end
	P(UI.slider(ap, "Corner roundness %", SET.corner, 0, 200, 6, function(v) SET.corner = v; A.apply("corner") end), "corner", "Corner roundness")
	P(UI.slider(ap, "Glassy panels %", SET.glass, 0, 70, 7, function(v) SET.glass = v; A.apply("glass") end), "glass", "Glassy panels")
	-- Motion
	local mo = sec("Motion")
	P(UI.toggle(mo, "Header wave", SET.wave, 1, function(v) SET.wave = v; A.apply("wave") end), "wave", "Header wave")
	P(UI.toggle(mo, "Favicon glow", SET.glow, 2, function(v) SET.glow = v; A.apply("glow") end), "glow", "Favicon glow")
	P(UI.toggle(mo, "Card animations", SET.cardAnims, 3, function(v) SET.cardAnims = v; refreshPreview() end), "cardAnims", "Card animations")
	P(UI.slider(mo, "Animation speed %", SET.animSpeed, 25, 200, 4, function(v) SET.animSpeed = v; A.apply("animSpeed") end), "animSpeed", "Animation speed")
	P(UI.toggle(mo, "Toast pop-in", SET.toastAnims, 5, function(v) SET.toastAnims = v; refreshPreview() end), "toastAnims", "Toast pop-in")
	P(UI.toggle(mo, "Hover effects", SET.hoverFx, 6, function(v) SET.hoverFx = v; refreshPreview() end), "hoverFx", "Hover effects")
	P(UI.toggle(mo, "Ambient backdrop", SET.ambient, 7, function(v) SET.ambient = v; A.apply("ambient") end), "ambient", "Ambient backdrop")
	P(UI.toggle(mo, "Reduce motion", SET.reduceMotion, 8, function(v) SET.reduceMotion = v; A.apply("reduceMotion") end), "reduceMotion", "Reduce motion")
	-- Privacy
	local pv = sec("Privacy")
	P(UI.toggle(pv, "Privacy mode", SET.privacy, 1, function(v) SET.privacy = v; A.apply("privacy") end), "privacy", "Privacy mode")
	P(UI.toggle(pv, "Hide username", SET.hideName, 2, function(v) SET.hideName = v; A.apply("rebuild") end), "hideName", "Hide username")
	P(UI.toggle(pv, "Hide location", SET.hideLocation, 3, function(v) SET.hideLocation = v; A.apply("rebuild") end), "hideLocation", "Hide location")
	P(UI.toggle(pv, "Blur avatar", SET.blurAvatar, 4, function(v) SET.blurAvatar = v; A.apply("rebuild") end), "blurAvatar", "Blur avatar")
	-- Layout
	local ly = sec("Layout")
	P(UI.slider(ly, "UI transparency", SET.uiTrans, 0, 80, 1, function(v) SET.uiTrans = v; A.apply("uiTrans") end), "uiTrans", "UI transparency")  -- cap 80% so the settings (incl. this slider + Reset) stay findable to undo
	P(UI.seg(ly, { "Comfy", "Compact" }, 2, function(o) SET.density = o; A.apply("density") end, (SET.density == "Compact" and 2 or 1), nil, nil, "Density"), "density", "Density")
	P(UI.toggle(ly, "Blur background", SET.blur, 3, function(v) SET.blur = v; A.apply("blur") end), "blur", "Blur background")
	-- SmartBar
	local sb = sec("SmartBar")
	P(UI.seg(sb, { "Bottom", "Top" }, 1, function(o) SET.barTop = (o == "Top"); A.apply("bar") end, (SET.barTop and 2 or 1), nil, nil, "SmartBar position"), "bar", "SmartBar position")
	P(UI.toggle(sb, "Auto-hide bar", SET.autoHide, 2, function(v) SET.autoHide = v; A.apply("autoHide") end), "autoHide", "Auto-hide bar")
	P(UI.toggle(sb, "Multi-Panel Mode", SET.multiPanel, 3, function(v) SET.multiPanel = v; A.apply("multiPanel") end), "multiPanel", "Multi-Panel Mode")
	P(UI.toggle(sb, "Show my avatar", SET.barAvatar, 4, function(v) SET.barAvatar = v; A.apply("barAvatar") end), "barAvatar", "Avatar on bar")
	P(UI.seg(sb, { "Left", "Center", "Right" }, 5, function(o) SET.barSide = o; A.apply("bar") end, (SET.barSide == "Left" and 1 or SET.barSide == "Right" and 3 or 2), nil, nil, "Dock side"), "barSide", "Dock side")
	P(UI.toggle(sb, "Show clock", SET.clockShow, 6, function(v) SET.clockShow = v; A.apply("clock") end), "clockShow", "Clock")
	P(UI.seg(sb, { "24h", "12h" }, 7, function(o) SET.clock24 = (o == "24h"); A.apply("clock") end, (SET.clock24 and 1 or 2), nil, nil, "Clock format"), "clock24", "Clock format")
	P(UI.seg(sb, { "Icons", "Labels" }, 8, function(o) SET.barLabels = (o == "Labels"); A.apply("barLabels") end, (SET.barLabels and 2 or 1), nil, nil, "Bar buttons"), "barLabels", "Bar buttons")
	P(UI.seg(sb, { "Small", "Default", "Large" }, 9, function(o) SET.barSize = ({ Small = 0.85, Default = 1, Large = 1.2 })[o] or 1; A.apply("barSize") end, (SET.barSize < 1 and 1 or SET.barSize > 1 and 3 or 2), nil, nil, "Bar size"), "barSize", "Bar size")
	-- Actions
	local ac = sec("Actions")
	UI.button(ac, "Replay intro", nil, 1, function() A.playIntro() end)
	UI.button(ac, "Reset to defaults", nil, 2, function() A.apply("reset") end)
	-- Behavior
	local bh = sec("Behavior")
	P(UI.toggle(bh, "Notifications", SET.notify, 1, function(v) SET.notify = v; refreshPreview() end), "notify", "Notifications")
	P(UI.cyc(bh, "Toast position", { "Top-right", "Top-left", "Bottom-right", "Bottom-left" }, 2, function(o) SET.toastPos = o; A.apply("toast") end, SET.toastPos), "toastPos", "Toast position")
	UI.button(bh, "Send test notification", nil, 3, function() toast("Test notification", "Hover to pause, click to dismiss. Errors linger longer.", "ok") end)  -- preview the notification style + position without triggering a real action
	if not _KR._prevKey then renderPreview("theme", "Theme") end  -- seed the preview pane on first build
	task.spawn(function()  -- GROW the settings canvas to the tallest column so tall content never spills off-screen on mobile (fixed SET_H was too short once controls were added). ÷scale recovers the LOGICAL height (AbsoluteSize is post-settingsScale).
		task.wait()  -- let the columns' AutomaticSize.Y settle first
		if not setRow.Parent then return end
		local sc = settingsScale.Scale
		local H = (sc > 0) and (setRow.AbsoluteSize.Y / sc) or setRow.AbsoluteSize.Y
		settingsPanel.Size = UDim2.fromOffset(SET_W, math.max(SET_H, math.ceil(H) + 60))  -- 60 = the 48px header + a little breathing room below the last card
		fitSettings()
	end)
end
fillSettings()
-- (the News view is built above by the redesigned renderNews)
-- minimal edge buttons: a big "<" / ">" chevron + a name below, NO box/border.
local function edgeBtn(isL)
	local b = new("TextButton", { AnchorPoint = Vector2.new(isL and 1 or 0, 0.5), Size = UDim2.fromOffset(54, 78), BackgroundTransparency = 1, AutoButtonColor = false, Text = "", ZIndex = 4, Parent = homeView })
	local chev = lbl({ AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 0), Size = UDim2.new(1, 0, 0, 38), Text = isL and "<" or ">", Font = FONTB, TextSize = 30, TextColor3 = T.txt2, TextXAlignment = Enum.TextXAlignment.Center, Parent = b })
	local nm = lbl({ AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, 0), Size = UDim2.new(1, 18, 0, 28), Text = "", Font = FONTB, TextColor3 = T.txt3, TextSize = 9.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Center, TextYAlignment = Enum.TextYAlignment.Top, Parent = b })
	b.MouseEnter:Connect(function() tween(chev, 0.15, { TextColor3 = T.accent }); tween(nm, 0.15, { TextColor3 = T.txt2 }) end)
	b.MouseLeave:Connect(function() tween(chev, 0.15, { TextColor3 = T.txt2 }); tween(nm, 0.15, { TextColor3 = T.txt3 }) end)
	return b, nm
end
local leftBtn, leftNm = edgeBtn(true)
local rightBtn, rightNm = edgeBtn(false)
local _active, _homeX = "home", nil
local ORDER = { settings = 0, home = 1, news = 2 }
local function viewOf(n) return n == "home" and homeScroll or (n == "settings" and settingsPanel or newsPanel) end
local function centerP(n) return n == "home" and (_homeX or homeScroll.Position) or UDim2.new(0.5, 0, 0.5, 0) end
placeSideButtons = function()  -- pin BOTH nav buttons to the HOME view's edges for EVERY view (the Home menu is the source of truth, so the buttons never jump between Home / Settings / News; only visibility + labels change per view - see updateButtons).
	local px = (_homeX or homeScroll.Position).X.Offset  -- captured Home centre, not the live pos (mid-slide it may be off-screen)
	local w = homeScroll.Size.X.Offset
	leftBtn.Position = UDim2.new(0, px - 8, 0.5, 0)       -- Home's LEFT edge  (UI Settings on Home; Home button on News)
	rightBtn.Position = UDim2.new(0, px + w + 8, 0.5, 0)  -- Home's RIGHT edge (News on Home; Home button on Settings)
end
local function updateButtons()
	leftBtn.Visible = _active ~= "settings"; rightBtn.Visible = _active ~= "news"
	leftNm.Text = _active == "home" and "UI Settings" or "Home"
	rightNm.Text = _active == "home" and "News" or "Home"
	placeSideButtons()
end
goTo = function(target)
	if not target or _active == target then return end
	if _active == "settings" and target ~= "settings" then clearPreview() end   -- stop the preview's animation loops when navigating away (goTo doesn't close Home, so closeHome's clearPreview never fires)
	local dir = (ORDER[target] > ORDER[_active]) and 1 or -1  -- +1 = pan toward News (views slide left)
	local VW = ((workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X) or vp.X) + 40  -- LIVE viewport: the load-time vp goes stale (viewport not sized yet at build / window resize), which shrinks the slide + parks side views on-screen (same live-read pattern as fitHome/fitSettings)
	if _active == "home" then _homeX = homeScroll.Position end
	local cur = viewOf(_active)
	tween(cur, 0.44, { Position = centerP(_active) + UDim2.fromOffset(-dir * VW, 0) }, QUINT)  -- current slides away
	local tv = viewOf(target)
	tv.Position = centerP(target) + UDim2.fromOffset(dir * VW, 0)                              -- target starts off-screen
	tween(tv, 0.44, { Position = centerP(target) }, QUINT)                                     -- ...and slides into view
	_active = target
	updateButtons()
	if target == "home" then  -- back on Home: resume the header wave (pointless while Home is slid off-screen behind a side view)
		if homeOpen and SET.wave and not SET.reduceMotion then startWave(_KR._homeLetters) end
	else
		stopWave()  -- leaving Home for Settings/News: stop the per-frame wave on the now-invisible header
	end
	if target == "settings" and not _KR._prevKey then renderPreview("theme", "Theme") end  -- re-seed the preview if a close cleared it
end
resetSides = function()
	_active = "home"; _homeX = nil  -- forget any stale centre so the buttons use the fresh (fitHome) home position
	local far = UDim2.new(0.5, ((workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X) or vp.X) + 40, 0.5, 0)  -- LIVE viewport (see goTo): stale load-time vp parked side panels only ~40px off-centre → overlapped Home in Studio / early-inject / after resize
	settingsPanel.Position = far; newsPanel.Position = far
	updateButtons()
end
leftBtn.MouseButton1Click:Connect(function() goTo(_active == "home" and "settings" or "home") end)
rightBtn.MouseButton1Click:Connect(function() goTo(_active == "home" and "news" or "home") end)
pcall(function() _KR.homeBlur = Instance.new("BlurEffect"); _KR.homeBlur.Size = 0; _KR.homeBlur.Enabled = false; _KR.homeBlur.Parent = game:GetService("Lighting"); GUIObject.HomeBlur = _KR.homeBlur end)  -- stash on GUIObject so the BREAKER teardown can destroy this Lighting BlurEffect too (else a re-execute leaves the whole screen blurred with no UI)
-- ── Theme + backdrop (driven by the UI Settings → Appearance card) ───────────────────────────────────────
-- (A.themes is defined earlier, just above fillSettings, so the boot-time preview seed can read it - see note there)
A.curBg = function()  -- {light, mid, dark} backdrop colours + accent for the current theme (handles Custom)
	if SET.theme == "Custom" then local b = SET.custom.bg; return { b:Lerp(Color3.new(1, 1, 1), 0.1), b, b:Lerp(Color3.new(0, 0, 0), 0.22) }, SET.accent end
	local th = A.themes[SET.theme] or A.themes["Vampiric Noir"]; return th.bg, th.accent
end
-- Backdrop opacity per style. Low = opaque (hides the game behind). "Dim only" stays intentionally see-through;
-- the others are near-opaque so opening Home/News/Settings doesn't leave the game world visible around the panel.
A.bgDim = function() return (SET.bg == "Solid" and 0) or (SET.bg == "Gradient" and 0.06) or (SET.bg == "Dim only" and 0.34) or 0.08 end
-- Repaint the full-screen home backdrop + blur for the current SET.bg + SET.theme (LIVE - no rebuild needed).
A.applyBackdrop = function()
	local g, acc = A.curBg()
	if SET.bg == "Gradient" then
		homeBg.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, acc:Lerp(Color3.new(0, 0, 0), 0.5)), ColorSequenceKeypoint.new(1, g[2]) })
	else
		homeBg.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, g[1]), ColorSequenceKeypoint.new(0.5, g[2]), ColorSequenceKeypoint.new(1, g[3]) })
	end
	if homeOpen then tween(homeView, 0.3, { BackgroundTransparency = A.bgDim() }) end
	if _KR.homeBlur and homeOpen then
		if SET.bg == "Blur" and SET.blur then _KR.homeBlur.Enabled = true; tween(_KR.homeBlur, 0.3, { Size = 28 }) else tween(_KR.homeBlur, 0.3, { Size = 0 }) end
	end
end
-- designparser dark-mode: high-chroma colours "glow" on a near-black bg (Helmholtz-Kohlrausch). Soften the applied
-- accent ~18% toward its luminance-matched grey - reduces chroma while holding hue + luminance (so contrast is kept).
-- SET.accent (the stored pick + the swatches) stays vivid; only the RENDERED T.accent is softened for the dark UI.
A._softenAccent = function(c)  -- on A (not a main-chunk local: the RoClothes chunk is at the 200-register ceiling)
	local l = 0.2126 * c.R + 0.7152 * c.G + 0.0722 * c.B
	return c:Lerp(Color3.new(l, l, l), 0.18)
end
-- Accent/Theme change: re-derive the accent shades in T, repaint the backdrop, rebuild the home so cards re-tint.
A.applyTheme = function(fromPreset)
	if SET.theme == "Custom" then
		local c, cu = A._softenAccent(SET.accent), SET.custom
		-- SYNC: every T.* field set below must ALSO be restored in the else-branch's TDEF line, or it bleeds into the next preset when the user switches back (sibling of the "preset-settable field not reset on switch" landmine).
		T.accent = c; T.accent2 = cu.accent2; T.accentD = c:Lerp(Color3.new(0, 0, 0), 0.34)
		T.card = cu.card; T.cardHi = cu.card:Lerp(Color3.new(1, 1, 1), 0.08)
		T.bg = cu.bg; T.bg2 = cu.bg:Lerp(Color3.new(0, 0, 0), 0.25)
		T.txt = cu.text; T.txt2 = cu.text:Lerp(cu.bg, 0.28); T.txt3 = cu.text:Lerp(cu.bg, 0.52)
	else
		if fromPreset then local th = A.themes[SET.theme]; if th then SET.accent = th.accent end end
		T.card, T.cardHi, T.bg, T.bg2, T.txt, T.txt2, T.txt3 = TDEF.card, TDEF.cardHi, TDEF.bg, TDEF.bg2, TDEF.txt, TDEF.txt2, TDEF.txt3  -- restore defaults when leaving Custom. KEEP IN SYNC with the Custom branch above: every T.* field Custom overrides must be listed here or it bleeds into the next preset (accent/accent2/accentD are re-derived just below, so only the card/bg/txt family needs restoring). TDEF itself is a full pairs(T) snapshot, so it auto-covers new fields - only THIS list is manual.
		local c = A._softenAccent(SET.accent or T.accent)  -- dark-mode chroma-soften (see A._softenAccent)
		T.accent = c; T.accent2 = c:Lerp(Color3.new(1, 1, 1), 0.22); T.accentD = c:Lerp(Color3.new(0, 0, 0), 0.34)
	end
	A.applyBackdrop()
	fillSettings()                                                    -- re-tint the settings controls with the new accent (live)
	if A.rebuildHome then A.rebuildHome() end
	if MP.retheme then MP.retheme() end  -- re-colour any open multi-panels live (their content was built with the old palette)
end
-- ── Favicon rainbow glow + header-letter fly (the Home open/close special treatment) ─────────────────────
_KR._homeGen = 0  -- gen token: cancels a stale open/close if the user re-toggles mid-transition
-- Rainbow glow on the favicon border: a 2nd UIStroke (leaves the hover stroke `avs` untouched) whose gradient spins.
-- WHITE base is essential: a UIGradient MULTIPLIES the stroke Color, and UIStroke's default Color is black, so a
-- black base would multiply the rainbow to black (invisible - that was the "no glow" bug).
-- _KR._glowStroke, _KR._glowGrad, _KR._glowSpin: favicon glow parts (on _KR to save Luau registers)
local function startGlow()
	if not _KR._glowStroke then
		_KR._glowStroke = new("UIStroke", { Thickness = 3, Transparency = 1, Color = Color3.fromRGB(255, 255, 255), Parent = avatar })
		_KR._glowGrad = new("UIGradient", { Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 84, 96)), ColorSequenceKeypoint.new(0.20, Color3.fromRGB(255, 186, 60)),
			ColorSequenceKeypoint.new(0.40, Color3.fromRGB(120, 232, 120)), ColorSequenceKeypoint.new(0.60, Color3.fromRGB(70, 200, 255)),
			ColorSequenceKeypoint.new(0.80, Color3.fromRGB(186, 120, 255)), ColorSequenceKeypoint.new(1.00, Color3.fromRGB(255, 84, 96)),
		}), Parent = _KR._glowStroke })
	end
	tween(_KR._glowStroke, 0.5, { Transparency = 0.05 })
	if _KR._glowSpin then pcall(function() _KR._glowSpin:Disconnect() end) end
	-- spin the rainbow by advancing the gradient Rotation each frame (~110 deg/s). Directly setting the property
	-- via Heartbeat is more reliable than a TweenService tween on UIGradient.Rotation (which wasn't animating).
	_KR._glowSpin = RunService.Heartbeat:Connect(function(dt) if _KR._glowGrad and _KR._glowGrad.Parent then _KR._glowGrad.Rotation = (_KR._glowGrad.Rotation + dt * 110) % 360 end end)
end
local function stopGlow()
	if _KR._glowStroke then tween(_KR._glowStroke, 0.45, { Transparency = 1 }) end
	if _KR._glowSpin then local sp = _KR._glowSpin; _KR._glowSpin = nil; task.delay(0.5, function() pcall(function() sp:Disconnect() end) end) end  -- keep spinning through the fade, then disconnect
end
openHome = function()
	if homeOpen or _destroyed then return end
	homeOpen = true
	_KR._homeGen += 1; local gen = _KR._homeGen
	-- V4.5.17 NON-INTRUSIVE: Home no longer disables the Roblox CoreGui (topbar/menu, Backpack + tool hotkeys, EmotesMenu) or hides the host game's own ScreenGuis. That combo broke the game for users ("the game UI + animations broken and impossible to access the special keys ingame"). Home is already a full-screen DIMMED backdrop, so the game UI simply shows (dimmed) behind it and stays fully usable + escapable. `_hiddenGuis` is kept (empty) so closeHome's restore + the teardown CoreGui-re-enable stay safe no-ops.
	_KR._hiddenGuis = {}
	GUIObject._hiddenGuis = _KR._hiddenGuis
	if panelOpen then closePanel() end
	MP.setVisible(false)  -- suspend the multi-panel workspace under the full-screen Home
	stopWave()
	for _, c in ipairs(homeCanvas:GetChildren()) do if not (c:IsA("UIListLayout") or c:IsA("UIScale")) then c:Destroy() end end
	local anim = buildHome(homeCanvas)
	_KR._homeLetters = anim.letters                                         -- kept so a live UI-settings change can restart the wave
	local motion = not SET.reduceMotion
	local doCards = SET.cardAnims and motion                            -- animate the card deal-in?
	local prep = doCards and homePrep(anim.cards) or nil                -- hide the cards so they don't flash before the reveal
	if doCards then for _, e in ipairs(anim.letters) do e.lbl.TextTransparency = 1 end end  -- hide the letters; they fade in below
	fitHome()                                                           -- yields a frame; scales the canvas
	if not homeOpen or gen ~= _KR._homeGen then return end                  -- a close() landed during the yield
	if resetSides then resetSides() end                                 -- side panels start closed each open
	homeView.Visible = true; homeView.BackgroundTransparency = 1
	fitSide(newsPanel)                                                  -- news is a centred card; the settings view scrolls instead
	A.applyBackdrop()                                                   -- tweens transparency→bgDim + blur, for the current bg/theme
	if SET.glow and motion then startGlow() end                         -- favicon rainbow glow (if enabled)
	if SET.wave and motion then startWave(anim.letters) end             -- header waves from the start (if enabled)
	if doCards then
		for i, e in ipairs(anim.letters) do                             -- letters fade in left-to-right (the wave owns their Position)
			local ll = e.lbl; task.delay(i * 0.02, function() if ll.Parent then tween(ll, 0.4, { TextTransparency = 0 }, QUINT) end end)
		end
		homeRevealCards(prep)                                           -- cards deal in
	end
end
closeHome = function()
	if not homeOpen then return end
	homeOpen = false
	_KR._homeGen += 1; local gen = _KR._homeGen
	-- V4.5.17 NON-INTRUSIVE: closeHome no longer force-enables CoreGui/topbar. openHome disables none, so re-enabling here would only clobber CoreGui the HOST GAME itself disabled (custom-inventory / immersion games). The _hiddenGuis restore below stays (it re-enables only game ScreenGuis WE hid = none now).
	for _, g in ipairs(_KR._hiddenGuis) do pcall(function() g.Enabled = true end) end; _KR._hiddenGuis = {}
	if SET.multiPanel then MP.setVisible(true) end  -- restore + slide the workspace back in when Home closes (setVisible re-tiles for any bar-edge / viewport change, THEN slides the panels in from their edges - so no MP.relayout(false) here, which would snap them and kill the slide-in)
	stopWave(); stopGlow()                             -- wave stops, favicon glow fades out
	cascadeOut(homeCanvas, 0.2)                        -- header + cards fade out together
	clearPreview()                                     -- stop any running settings-preview animation loops
	if _active == "settings" then tween(settingsPanel, 0.4, { Position = UDim2.new(0.5, 0, 1.5, 0) }, QUINT)  -- slide the active side view OUT (it was vanishing instantly with no animation)
	elseif _active == "news" then tween(newsPanel, 0.4, { Position = UDim2.new(0.5, 0, 1.5, 0) }, QUINT) end
	leftBtn.Visible = false; rightBtn.Visible = false  -- hide the nav buttons during the close
	tween(homeView, 0.4, { BackgroundTransparency = 1 })
	if _KR.homeBlur then tween(_KR.homeBlur, 0.4, { Size = 0 }) end
	task.delay(0.42 * SPEED, function()
		if gen ~= _KR._homeGen then return end             -- a reopen landed during the fade - leave its content alone
		homeView.Visible = false; if _KR.homeBlur then _KR.homeBlur.Enabled = false end
		for _, c in ipairs(homeCanvas:GetChildren()) do if not (c:IsA("UIListLayout") or c:IsA("UIScale")) then c:Destroy() end end  -- tear down content so the ambient loops + stats poll stop while hidden
	end)
end
_KR._homeBusy = false  -- V4.5.16: moved off a top-level `local` onto _KR to relieve Luau's 200-live-local ceiling (Volt compiler hit it: "_homeBusy exceeded limit 200")
avatar.MouseButton1Click:Connect(function()
	if _KR._homeBusy then return end  -- debounce: ignore rapid re-clicks during the open/close transition (prevents the visual glitches)
	_KR._homeBusy = true; task.delay(math.max(0.6, 0.9 * SPEED), function() _KR._homeBusy = false end)  -- scales with the animation length (the card reveal is ~1.2s at default speed)
	if homeOpen then closeHome() else openHome() end
end)


-- hide/show: the down-chevron (transparent, no black box) COMPRESSES the whole bar into a favicon circle;
-- its content clips away as it shrinks (bar has ClipsDescendants), and tapping the circle expands it back.
_KR.chev = new("TextButton", { Name = "Chevron", AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -(BAR_Y + math.floor(BAR_H * UISCALE) + 7)), Size = UDim2.fromOffset(32, 16), BackgroundTransparency = 1, AutoButtonColor = false, Text = "", Visible = false, Parent = screen })  -- hidden until reveal() - else it shows over the intro while the bar is parked off-screen
new("UIScale", { Scale = UISCALE, Parent = _KR.chev })  -- scale + sit just above the scaled bar (was floating far away on mobile)
new("Frame", { BackgroundColor3 = T.txt2, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, -3, 0.5, 0), Size = UDim2.fromOffset(9, 2), Rotation = 40, Parent = _KR.chev })
new("Frame", { BackgroundColor3 = T.txt2, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 3, 0.5, 0), Size = UDim2.fromOffset(9, 2), Rotation = -40, Parent = _KR.chev })
-- the favicon circle the bar compresses into (and the tap-target to expand again)
-- the reopen puck lives in the TOP ScreenGui (panelScreen) so its click is never eaten by a higher layer.
_KR.barPuck = new("ImageButton", { Name = "Puck", AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -BAR_Y), Size = UDim2.fromOffset(BAR_H, BAR_H), BackgroundColor3 = T.card, BorderSizePixel = 0, AutoButtonColor = false, ScaleType = Enum.ScaleType.Crop, ImageTransparency = 1, BackgroundTransparency = 1, Visible = false, Image = "rbxthumb://type=AvatarHeadShot&id=" .. LocalPlayer.UserId .. "&w=48&h=48", Parent = panelScreen }); _KR.puckCorner = corner(_KR.barPuck, math.floor(BAR_H / 2)); stroke(_KR.barPuck, T.line, 1); useKrulIcon(_KR.barPuck)
new("UIScale", { Scale = UISCALE, Parent = _KR.barPuck })  -- match the scaled bar
_KR.PILL_W, _KR.PILL_H = 56, 22  -- the small pill the circle settles into (on _KR to save a Luau register)
_KR.barHidden, _KR._barFullW = false, 0  -- on _KR to save Luau registers
_KR.hideBar = function()
	if _KR.barHidden then return end
	_KR.barHidden = true; closePanel(); if homeOpen then closeHome() end
	local _bsc = bar:FindFirstChildOfClass("UIScale"); _KR._barFullW = bar.AbsoluteSize.X / ((_bsc and _bsc.Scale > 0) and _bsc.Scale or UISCALE)  -- logical width via the bar's LIVE UIScale (= UISCALE x barSize), so Small/Large don't overshoot the restore tween
	bar.AutomaticSize = Enum.AutomaticSize.None; bar.Size = UDim2.fromOffset(_KR._barFullW, BAR_H); _KR.chev.Visible = false
	-- the favicon fades in AT circle size DURING the compress, so it never snaps in at the last second.
	_KR.barPuck.Visible = true; _KR.barPuck.Size = UDim2.fromOffset(BAR_H, BAR_H); _KR.puckCorner.CornerRadius = UDim.new(0, math.floor(BAR_H / 2)); _KR.barPuck.ImageTransparency = 1; _KR.barPuck.BackgroundTransparency = 1
	tween(_KR.barPuck, 0.5, { ImageTransparency = 0, BackgroundTransparency = 0 })
	tween(bar, 0.55, { Size = UDim2.fromOffset(BAR_H, BAR_H) })                    -- compress into a circle (moderately slow)
	tween(barCorner, 0.55, { CornerRadius = UDim.new(0, math.floor(BAR_H / 2)) })
	-- once it's a circle, hide the bar and let the circle SETTLE into the small pill (the reopen).
	task.delay(0.55 * SPEED, function()
		if _KR.barHidden then
			bar.Visible = false
			tween(_KR.barPuck, 0.42, { Size = UDim2.fromOffset(_KR.PILL_W, _KR.PILL_H) }, BACK)
			tween(_KR.puckCorner, 0.42, { CornerRadius = UDim.new(0, math.floor(_KR.PILL_H / 2)) })
		end
	end)
end
_KR.showBar = function()
	if not _KR.barHidden then return end
	_KR.barHidden = false
	-- grow the pill back to a circle, then hand off to the bar (seamless: circle -> circle) and expand it out.
	tween(_KR.barPuck, 0.35, { Size = UDim2.fromOffset(BAR_H, BAR_H) }); tween(_KR.puckCorner, 0.35, { CornerRadius = UDim.new(0, math.floor(BAR_H / 2)) })
	task.delay(0.36 * SPEED, function()
		if not _KR.barHidden then
			_KR.barPuck.Visible = false
			bar.Visible = true; bar.Size = UDim2.fromOffset(BAR_H, BAR_H)
			tween(bar, 0.55, { Size = UDim2.fromOffset(_KR._barFullW > 0 and _KR._barFullW or 360, BAR_H) }, BACK)
			tween(barCorner, 0.55, { CornerRadius = UDim.new(0, 16) })
			task.delay(0.4 * SPEED, function() if not _KR.barHidden then bar.AutomaticSize = Enum.AutomaticSize.X; _KR.chev.Visible = true end end)
		end
	end)
end
_KR.chev.MouseButton1Click:Connect(_KR.hideBar)
_KR.barPuck.MouseButton1Click:Connect(function() if bar.Visible then return end; _KR.showBar() end)  -- ignore taps during the hide-compress (bar still Visible): the puck sits above the bar + would fire a tween fighting the live shrink

-- ══ UI Settings apply layer ══════════════════════════════════════════════════════════════════════════════
-- The controls in fillSettings() write SET; THESE functions make SET actually change the running UI.
-- Silent live rebuild of the dashboard: used when a content / privacy / visibility / theme setting changes.
-- The user is always on the settings side-view when they change a setting, so the dashboard is parked off-screen;
-- we rebuild it in place, keep it parked, and refresh _homeX so sliding back reveals the new content, centred.
A.rebuildTok = 0
A.rebuildHome = function()
	if not homeOpen then return end
	A.rebuildTok += 1; local tok = A.rebuildTok
	task.delay(0.04, function()  -- coalesce rapid changes (e.g. Streamer flips 4 flags) into a single rebuild
		if tok ~= A.rebuildTok or not homeOpen then return end
		for _, c in ipairs(homeCanvas:GetChildren()) do if not (c:IsA("UIListLayout") or c:IsA("UIScale")) then c:Destroy() end end
		local anim = buildHome(homeCanvas)
		_KR._homeLetters = anim.letters
		local parked = homeScroll.Position
		fitHome()                                                    -- content size may have changed; re-fit + re-centre
		_homeX = homeScroll.Position                                 -- fresh on-screen centre for the return slide
		if _active ~= "home" then homeScroll.Position = parked end   -- keep it parked while a side view is showing
		if SET.wave and not SET.reduceMotion then startWave(_KR._homeLetters) end  -- new letters -> restart the wave
		if SET.glow and not SET.reduceMotion then startGlow() end             -- re-engage the favicon glow too (Reset sets glow ON but only rebuildHome runs after - startGlow is idempotent, avatar is stable)
	end)
end
-- Move the whole SmartBar (+ puck + chevron) to the top or bottom edge.
A.barPos = function()
	local sh = math.floor(BAR_H * UISCALE * (SET.barSize or 1))
	local ax, pxS, pxO = 0.5, 0.5, 0   -- Dock side (SET.barSide): horizontal anchor + position. Center default; Left/Right hug the edge with a 14px margin.
	if SET.barSide == "Left" then ax, pxS, pxO = 0, 0, 14
	elseif SET.barSide == "Right" then ax, pxS, pxO = 1, 1, -14 end
	if SET.barTop then
		bar.AnchorPoint = Vector2.new(ax, 0); bar.Position = UDim2.new(pxS, pxO, 0, BAR_Y)
		_KR.barPuck.AnchorPoint = Vector2.new(ax, 0); _KR.barPuck.Position = UDim2.new(pxS, pxO, 0, BAR_Y)
		_KR.chev.AnchorPoint = Vector2.new(ax, 0); _KR.chev.Position = UDim2.new(pxS, pxO, 0, BAR_Y + sh + 7)
	else
		bar.AnchorPoint = Vector2.new(ax, 1); bar.Position = UDim2.new(pxS, pxO, 1, -BAR_Y)
		_KR.barPuck.AnchorPoint = Vector2.new(ax, 1); _KR.barPuck.Position = UDim2.new(pxS, pxO, 1, -BAR_Y)
		_KR.chev.AnchorPoint = Vector2.new(ax, 1); _KR.chev.Position = UDim2.new(pxS, pxO, 1, -(BAR_Y + sh + 7))
	end
	if SET.multiPanel then MP.relayout(true) end  -- docked panels re-tile to the bar's NEW edge (relayout reads SET.barTop). Covers both the "bar" toggle and Reset. No-op when no panels are open.
end
-- Auto-hide: while nothing is open and the bar sits idle for 4s, compress it to the puck. Tapping the puck restores it.
A.autoConn = nil; A.lastActive = os.clock()
A.stopAuto = function() if A.autoConn then pcall(function() A.autoConn:Disconnect() end); A.autoConn = nil end end
A.startAuto = function()
	A.lastActive = os.clock()
	if A.autoConn then return end
	A.autoConn = RunService.Heartbeat:Connect(function()
		if not SET.autoHide then return end
		if panelOpen or homeOpen or _KR.barHidden then A.lastActive = os.clock(); return end  -- in use → keep it up
		if os.clock() - A.lastActive > 4 then _KR.hideBar() end                                -- idle → auto-hide
	end)
end
bar.MouseEnter:Connect(function() A.lastActive = os.clock() end)  -- hovering the bar is activity (don't auto-hide out from under the cursor)
-- UI TRANSPARENCY: make the UI SEE-THROUGH by fading each SURFACE (backgrounds / images / outlines / scrollbars) from
-- its crisp base, while TEXT stays fully opaque and gets a dark contrast outline so it reads over the game behind it.
-- History (do not repeat): a CanvasGroup pixelated (low-res offscreen buffer, PC + mobile); fading text made it vanish
-- (GC-compounding) AND fought the hover/entrance/glow text tweens. Surfaces-only + solid outlined text is the method that works.
_KR.fadeProps, _KR.strokeProps = { "BackgroundTransparency", "ImageTransparency", "ScrollBarImageTransparency" }, { "Transparency" }  -- SURFACE props for GuiObjects (bg / image / scrollbar) vs a UIStroke's OWN .Transparency. *** THE BUG (found 0712): GuiObjects must get ONLY the three named props, NEVER a bare "Transparency". Roblox's GuiObject.Transparency is a COMBINED property whose setter ALSO writes TextTransparency + ImageTransparency -- so fading it silently faded the TEXT. That is why "surfaces-only" STILL killed text. UIStroke.Transparency (strokeProps) is a separate, safe thing, applied only to UIStrokes below.
local function _pruneFadeCache()
	local cache = _KR.fadeCache
	if not cache then _KR.fadeIn = nil; return end
	local seen, write = {}, 1
	for read = 1, #cache do
		local e, o = cache[read], cache[read][1]
		if o and o.Parent then cache[write] = e; write += 1; seen[o] = true end
	end
	for i = write, #cache do cache[i] = nil end
	_KR.fadeIn = seen  -- rebuild the set from retained entries so destroyed UI releases both references
end
A.applyTrans = function()  -- UI transparency = see-through SURFACES, solid TEXT. PERF: walk the tree + capture each target's crisp BASE only ONCE per engage, into _KR.fadeCache; every later slider tick just re-sets that cached list. (Before, every drag tick did a full GetDescendants + pcall-read + GetAttribute on the WHOLE UI -> thousands of allocations per tick -> the drag lagged.)
	local t = math.clamp((SET.uiTrans or 0) / 100, 0, 0.92)
	if t <= 0 then
		if _KR.fadeCache then for _, e in ipairs(_KR.fadeCache) do if e[1].Parent then e[1][e[2]] = e[3] end end; _KR.fadeCache, _KR.fadeIn = nil, nil end  -- OFF -> restore every target to its crisp base, drop the cache + seen-set (next engage re-walks from the now-crisp UI, so bases stay correct + new UI is picked up)
		return
	end
	if _KR.fadeCache then _pruneFadeCache() end
	if not _KR.fadeCache then  -- ENGAGE (0 -> >0): ONE walk. cache = { {inst, prop, base, isStroke}, ... }; seen = set of cached instances (so _KR.fadeInto can fold a later-opened panel in without double-capturing what's already here). Surfaces fade from base; every text label gets a dark contrast outline (its FILL is never touched).
		local cache, seen = {}, {}
		for _, sg in ipairs({ screen, homeScreen, panelScreen, MP.screen }) do
			if sg then for _, o in ipairs(sg:GetDescendants()) do
				local props = o:IsA("UIStroke") and _KR.strokeProps or (o:IsA("GuiObject") and _KR.fadeProps)  -- UIStroke -> its own .Transparency; GuiObject -> ONLY bg/image/scrollbar (NEVER the combined .Transparency, which also fades text)
				if props then for _, p in ipairs(props) do
					local ok, cur = pcall(function() return o[p] end)
					if ok and type(cur) == "number" then cache[#cache + 1] = { o, p, cur, false }; seen[o] = true end
				end end
				if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then
					cache[#cache + 1] = { o, "TextStrokeTransparency", o.TextStrokeTransparency, true }; seen[o] = true
					pcall(function() o.TextStrokeColor3 = Color3.new(0, 0, 0) end)   -- dark outline colour, set ONCE here; its strength (transparency) is driven per-tick below
				end
			end end
		end
		_KR.fadeCache, _KR.fadeIn = cache, seen
	end
	for _, e in ipairs(_KR.fadeCache) do  -- HOT PATH (per tick): cheap re-set. Parent-guarded so a since-destroyed element is skipped (no pcall needed).
		local o = e[1]
		if o.Parent then o[e[2]] = e[4] and math.min(e[3], 1 - t) or (e[3] + (1 - e[3]) * t) end  -- isStroke -> stronger outline as t rises; surface -> fade from its base
	end
end
_KR.fadeInto = function(root)  -- fade a freshly-built subtree (e.g. a panel opened AFTER UI-transparency was turned up) to the current level + add it to the cache so it also tracks the slider. Skips anything already cached (via _KR.fadeIn) so a persistent frame isn't double-captured (which would compound). No-op unless transparency is engaged.
	local t = math.clamp((SET.uiTrans or 0) / 100, 0, 0.92)
	if t <= 0 or not _KR.fadeCache then return end
	_pruneFadeCache()
	local list = root:GetDescendants(); list[#list + 1] = root  -- include the panel frame itself
	for _, o in ipairs(list) do
		if not _KR.fadeIn[o] then
			local props = o:IsA("UIStroke") and _KR.strokeProps or (o:IsA("GuiObject") and _KR.fadeProps)
			if props then for _, p in ipairs(props) do
				local ok, cur = pcall(function() return o[p] end)
				if ok and type(cur) == "number" then _KR.fadeCache[#_KR.fadeCache + 1] = { o, p, cur, false }; o[p] = cur + (1 - cur) * t; _KR.fadeIn[o] = true end
			end end
			if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then
				_KR.fadeCache[#_KR.fadeCache + 1] = { o, "TextStrokeTransparency", o.TextStrokeTransparency, true }; _KR.fadeIn[o] = true
				pcall(function() o.TextStrokeColor3 = Color3.new(0, 0, 0); o.TextStrokeTransparency = math.min(o.TextStrokeTransparency, 1 - t) end)
			end
		end
	end
end
A.reset = function()
	SET.wave, SET.glow, SET.cardAnims, SET.animSpeed, SET.toastAnims, SET.hoverFx, SET.reduceMotion, SET.ambient = true, true, true, 100, true, true, false, true
	SET.uiTrans, SET.density, SET.blur, SET.barTop, SET.autoHide, SET.multiPanel, SET.barAvatar = 0, "Comfy", true, false, false, false, false  -- multiPanel/barAvatar were omitted → Reset left it ON
	SET.privacy, SET.hideName, SET.hideLocation, SET.blurAvatar = false, false, false, false
	SET.bg, SET.theme, SET.accent = "Blur", "Vampiric Noir", A.themes["Vampiric Noir"].accent
	SET.corner = 100; A.applyCorner()   -- restore default roundness across every registered corner
	SET.glass = 0; A.applyGlass()        -- restore fully opaque panels
	SET.clockShow, SET.clock24, SET.barSide = true, true, "Center"; A.applyClock()   -- clock shown + 24h; barSide re-applied by the A.barPos() call below
	SET.barLabels = false; A.applyBarLabels()   -- bar buttons back to drawn icons
	SET.barSize = 1; A.applyBarSize()           -- bar back to default size
	SET.notify, SET.toastPos = true, "Top-right"; A.applyToast()   -- behavior back to defaults
	SET.custom = { accent2 = TDEF.accent2, card = TDEF.card, bg = TDEF.bg, text = TDEF.txt }
	SPEED = BASE_SPEED
	A.stopAuto(); if _KR.barHidden then _KR.showBar() end; MP.closeAll()   -- reset turns Multi-Panel off → close any docked panels
	A.barPos()
	useKrulIcon(avatar)   -- reset → Krul brand icon is the default bar favicon again
	densify()             -- density reset to Comfy → restore full gaps (+ rescale what's on screen) BEFORE the rebuild below, else it re-lays at stale Compact spacing
	A.applyTheme(false)   -- restores T.accent + backdrop; it already rebuilds the settings controls (fillSettings) AND re-fits the home at 100%
	A.applyTrans()        -- clear any UI transparency (uiTrans reset to 0)
	toast("UI Settings", "Reset to defaults.", "warn")
end
A.applyCorner = function()  -- live GLOBAL corner roundness: rescale every registered UICorner from its stored base radius
	_KR.cornerScale = (SET.corner or 100) / 100
	for c, base in pairs(_KR.corners) do pcall(function() c.CornerRadius = UDim.new(0, math.floor(base * _KR.cornerScale + 0.5)) end) end
end
A.applyGlass = function()  -- glassy panels: fade the SmartBar + tab/docked panel backdrops AND every cell (rowShell row), all registered in _KR.panels. Text / icons / strokes are children, so they stay crisp; only the FILLS go translucent.
	_KR.glass = (SET.glass or 0) / 100
	for f in pairs(_KR.panels) do if f.Parent then f.BackgroundTransparency = _KR.glass end end  -- Parent guard (not pcall): cheaper now that every cell is registered, and a since-destroyed frame is just skipped
end
A.clockText = function()  -- 24h straight from FormatLocalTime; 12h derived MANUALLY (don't rely on locale AM/PM pattern support, which may be why it "didn't change")
	local ok, s = pcall(function() return DateTime.now():FormatLocalTime("HH:mm", "en-us") end)
	if not ok or type(s) ~= "string" or #s < 5 then return "--:--" end
	if SET.clock24 then return s end
	local hh = tonumber(s:sub(1, 2)) or 0; local mm = s:sub(4, 5)
	local ap = hh >= 12 and "PM" or "AM"; local h12 = hh % 12; if h12 == 0 then h12 = 12 end
	return string.format("%d:%s %s", h12, mm, ap)
end
A.applyClock = function()  -- SmartBar clock: show/hide it + its divider, widen for 12h, and REFRESH the text NOW (don't wait up to 5s for the loop)
	clock.Visible = SET.clockShow
	local d = bar:FindFirstChild("ClockDiv"); if d then d.Visible = SET.clockShow end
	clock.Size = UDim2.new(0, SET.clock24 and 46 or 72, 1, 0)  -- 12h ("12:45 PM") needs more room than 24h ("15:45")
	clock.Text = A.clockText()   -- instant feedback on toggle
end
A.applyBarLabels = function()  -- SmartBar buttons show EITHER the drawn icon OR the section name (never both), so the bar never doubles in size
	for _, t in pairs(tabs) do
		if t.icon then t.icon.Visible = not SET.barLabels end
		if t.label then t.label.Visible = SET.barLabels end
		if t.btn then
			if SET.barLabels then
				local w = 44; pcall(function() w = math.ceil(TextService:GetTextSize(t.label.Text, 13, FONTB, Vector2.new(1e4, 1e4)).X) + 26 end)  -- single-line width (no wrap → cross-platform-safe) + padding
				t.btn.Size = UDim2.fromOffset(w, 40)
			else t.btn.Size = UDim2.fromOffset(40, 40) end
		end
	end
end
A.applyBarSize = function()  -- scale the WHOLE SmartBar cluster (bar + collapse chevron + collapsed puck) TOGETHER so they stay matched; reposition + re-fit Home below it
	local f = UISCALE * (SET.barSize or 1)
	for _, o in ipairs({ bar, _KR.chev, _KR.barPuck }) do local s = o:FindFirstChildOfClass("UIScale"); if s then s.Scale = f end end
	A.barPos()
	if homeOpen then task.spawn(function() local parked = homeScroll.Position; fitHome(); _homeX = homeScroll.Position; if _active ~= "home" then homeScroll.Position = parked end end) end  -- mirror A.apply("bar"): re-fit for the new bar space, but RESTORE Home's parked position so it doesn't visibly jump while you're in Settings (this was the glitch)
end
A.applyToast = function()  -- Toast position (Behavior): move the toast stack to the chosen screen corner
	local p = SET.toastPos or "Top-right"
	local ax = (p == "Top-left" or p == "Bottom-left") and 0 or 1
	local ay = (p == "Bottom-left" or p == "Bottom-right") and 1 or 0
	toastHost.AnchorPoint = Vector2.new(ax, ay)
	toastHost.Position = UDim2.new(ax, ax == 0 and 14 or -14, ay, ay == 0 and 14 or -14)
	local lay = toastHost:FindFirstChildOfClass("UIListLayout")
	if lay then lay.HorizontalAlignment = (ax == 0) and Enum.HorizontalAlignment.Left or Enum.HorizontalAlignment.Right; lay.VerticalAlignment = (ay == 0) and Enum.VerticalAlignment.Top or Enum.VerticalAlignment.Bottom end
end
A.apply = function(k)
	if k == "animSpeed" then SPEED = BASE_SPEED * (100 / math.max(10, SET.animSpeed))
	elseif k == "wave" then if homeOpen and _active == "home" and SET.wave and not SET.reduceMotion then startWave(_KR._homeLetters) else stopWave() end
	elseif k == "glow" then if homeOpen and SET.glow and not SET.reduceMotion then startGlow() else stopGlow() end
	elseif k == "reduceMotion" then  -- master motion switch: stop/restart the live loops now; individual toggles + the reduceMotion checks at every use-site handle the rest
		if homeOpen and _active == "home" and SET.wave and not SET.reduceMotion then startWave(_KR._homeLetters) else stopWave() end
		if homeOpen and SET.glow and not SET.reduceMotion then startGlow() else stopGlow() end
	elseif k == "ambient" then  -- the Home backdrop sway loop reads SET.ambient live; nothing to rebuild
	elseif k == "blur" then if _KR.homeBlur and homeOpen then if SET.bg == "Blur" and SET.blur then _KR.homeBlur.Enabled = true; tween(_KR.homeBlur, 0.3, { Size = 28 }) else tween(_KR.homeBlur, 0.3, { Size = 0 }) end end  -- 28 = the same strength A.applyBackdrop uses (was 18 → toggling the setting weakened the blur)
	elseif k == "uiTrans" then A.applyTrans()  -- fade the whole UI to the chosen transparency (live)
	elseif k == "bg" then A.applyBackdrop()
	elseif k == "corner" then A.applyCorner()
	elseif k == "glass" then A.applyGlass()
	elseif k == "clock" then A.applyClock()
	elseif k == "barLabels" then A.applyBarLabels()
	elseif k == "barSize" then A.applyBarSize()
	elseif k == "toast" then A.applyToast()
	elseif k == "accent" then A.applyTheme(false)
	elseif k == "theme" then A.applyTheme(true)
	elseif k == "bar" then A.barPos(); if homeOpen then task.spawn(function() local parked = homeScroll.Position; fitHome(); _homeX = homeScroll.Position; if _active ~= "home" then homeScroll.Position = parked end end) end  -- re-fit so the dashboard moves below/above with the bar
	elseif k == "autoHide" then if SET.autoHide then A.startAuto() else A.stopAuto() end
	elseif k == "multiPanel" then if SET.multiPanel then if panelOpen then closePanel() end else MP.closeAll() end  -- never leave single + multi both live
	elseif k == "barAvatar" then if SET.barAvatar then avatar.Image = "rbxthumb://type=AvatarHeadShot&id=" .. LocalPlayer.UserId .. "&w=48&h=48" else useKrulIcon(avatar) end  -- swap the bar favicon live: player headshot vs Krul brand icon
	elseif k == "density" then densify(); fillSettings(); A.rebuildHome()  -- densify() LIVE-rescales every list gap (home + settings + all tab pages, incl. their persistent scroll layouts); fillSettings/rebuildHome also re-apply card padding
	elseif k == "privacy" then
		local v = SET.privacy
		SET.hideName, SET.hideLocation, SET.blurAvatar = v, v, v
		fillSettings()   -- reflect the cascade in the Privacy toggles
		A.rebuildHome()
	elseif k == "reset" then A.reset()
	else A.rebuildHome() end  -- "rebuild" + any content / visibility key
	refreshPreview()  -- the changed setting may be the one being previewed -> re-render so its demo reflects the new state
end

--=================================================================================
-- BOOT
--=================================================================================
bar.Position = UDim2.new(0.5, 0, 1, BAR_H + 50)  -- parked off-screen; the intro video's reveal() (below) tweens it in once the video finishes / is skipped
task.spawn(function() while screen.Parent do clock.Text = A.clockText(); task.wait(5) end end)  -- A.clockText formats per SET.clock24 (24h vs manual 12h AM/PM)
-- breathing active-tab indicator: the active tab's dot gently pulses in and out.
task.spawn(function()
	while screen.Parent do
		local t = activeTab and tabs[activeTab]
		if t and t.dot and t.dot.BackgroundTransparency < 0.5 then
			tween(t.dot, 1.0, { Size = UDim2.fromOffset(9, 9) }, QUINT); task.wait(1.0)
			tween(t.dot, 1.0, { Size = UDim2.fromOffset(6, 6) }, QUINT); task.wait(1.0)
		else
			task.wait(0.35)
		end
	end
end)
-- ═══ VAMPIRIC AURORA TITLE / LOADING SCREEN - full-screen, waits for a Skip tap; NO image assets ═══
-- Retired the 591-frame ring-buffer video (the community disliked it). Pure GUI primitives (Frames + UIGradient +
-- text), so none of the video's mobile pain (PreloadAsync hangs, getcustomasset paths). Wrapped in an IIFE (not a
-- do-block): the boot section's register peak is near Luau's 200 limit, and a function frame moves these locals off
-- the main chunk. Built task-by-task per gui_redesign/TITLE_SCREEN_PLAN.md. Task 1 = full-screen shell + working Skip.
A.playIntro = function()  -- the Vampiric Aurora title screen. Runs once at boot (called at the end of this block); UI Settings > Actions > "Replay intro" calls it again.
	-- REPLAY-SAFE: tear down any prior intro overlay + its Camera-bound ViewportSize conn first so a replay starts clean
	-- (the boot run leaves nothing behind; this guards a replay, or a DESTROY that interrupted a play).
	pcall(function() local ex = PlayerGui:FindFirstChild("RoClothesIntro"); if ex then ex:Destroy() end end)
	if MP.introVpConn then pcall(function() MP.introVpConn:Disconnect() end); MP.introVpConn = nil end
	local function reveal()  -- hand off to the SmartBar (the old boot tail): bar rises, Home auto-opens, welcome toast
		if _KR.cfgLoaded and not _KR.cfgApplied then   -- one-shot: re-skin the built UI to the SAVED config just before the bar slides in. Home builds fresh below with the updated palette, so nothing flashes. Everything here reads persistent frames (settingsPanel/setLeft/homeCanvas all exist), so it's safe pre-openHome.
			_KR.cfgApplied = true
			SPEED = BASE_SPEED * (100 / math.max(10, SET.animSpeed))
			local sa = SET.accent
			pcall(A.applyTheme, true); if SET.accent ~= sa then SET.accent = sa; pcall(A.applyTheme, false) end   -- palette + accent; restore a custom accent the preset apply may have reset to its default
			for _, fn in ipairs({ A.applyBarSize, A.applyBarLabels, A.applyClock, A.applyCorner, A.applyGlass, A.applyTrans, A.applyToast }) do pcall(fn) end
			pcall(densify)  -- [V3 MERGE FIX] apply saved density: densify() sets the gap/pad multipliers + LIVE-rescales the built settings panel; Home + tab pages build fresh below with them. Was omitted -> saved "Compact" rendered at Comfy.
			if SET.autoHide then pcall(A.startAuto) end  -- [V3 MERGE FIX] start the idle auto-hide watcher if saved ON (only A.apply("autoHide") started it before -> saved autoHide=true was dead after a re-execute).
		end
		A.barPos()  -- set the bar's anchor + rest position for the LIVE dock (Bottom/Top x Left/Center/Right); was hardcoded bottom-centre, so a Replay-intro after changing the dock dropped the bar in the wrong spot (off-screen on Top)
		local rest = bar.Position
		bar.Position = rest + UDim2.new(0, 0, 0, SET.barTop and -(BAR_H + 50) or (BAR_H + 50))  -- park just off the docked edge...
		tween(bar, 0.7, { Position = rest }, QUINT)                                              -- ...then slide it in
		task.delay(0.5, function() pcall(function() _KR.chev.Visible = true end) end)   -- the collapse chevron was hidden during the intro; reveal it as the bar arrives
		-- V4.5.17 NON-INTRUSIVE: Home no longer auto-opens on boot (it blanked the game + CoreGui the instant you ran the script). The SmartBar slides in; the user opens what they want from it - a tab for a feature, or the avatar for the Home dashboard.
		task.delay(1.1, function() toast("Welcome to RoClothes:Krul", "Your SmartBar is ready - tap a tab to start, or your avatar for Home.", "ok") end)
	end


	-- full-screen overlay: a T.bg backdrop (fills the whole screen) + a 1280×720 design canvas fitted to the viewport.
	-- Aurora / motes (later task) parent onto `dim` so they fill the whole screen; the UI (logo / loader / skip) lives
	-- on the scaled `content` canvas so its layout is consistent on every device.
	local DW, DH = 1280, 720
	local ov = new("ScreenGui", { Name = "RoClothesIntro", IgnoreGuiInset = true, ResetOnSpawn = false, DisplayOrder = 2000, Parent = PlayerGui })
	local dim = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.bg, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1, Parent = ov })  -- FULLY TRANSPARENT container for the aurora/motes (see-through per the user) - never gets a dark fill
	local content = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(DW, DH), BackgroundTransparency = 1, ZIndex = 2, Parent = dim })
	local introScale = new("UIScale", { Scale = 1, Parent = content })
	local function fitIntro()  -- same reliable scale-to-fit math as fitSettings: pure viewport math on the fixed canvas
		local cam = workspace.CurrentCamera
		local vw, vh = (cam and cam.ViewportSize.X) or 1280, (cam and cam.ViewportSize.Y) or 720
		introScale.Scale = math.max(0.3, math.min((vw - 24) / DW, (vh - 24) / DH))  -- FILL the viewport (no 1.0 cap): content scales to the limiting dimension, so mobile + PC see the SAME proportions
	end
	fitIntro(); pcall(function() MP.introVpConn = workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(fitIntro) end)

	-- which run is this? 1st run (no marker) → DOWNLOAD flow; 2nd+ run (marker present) → INSTANT. The demo simulates it
	-- with a getgenv flag (persists across re-executions in a session) + a marker file (persists across sessions).
	-- which run is this? 1st run (marker absent) → DOWNLOAD flow; 2nd+ (marker present) → cached WELCOME-BACK. Marker =
	-- a getgenv flag (persists across re-executions in a session) + a file (persists across sessions).
	local FORCE_FIRST_RUN = false                       -- flip true to always preview the download flow
	-- V4.4.x DEMO LOADER WIRING: key the DOWNLOAD-flow vs WELCOME-BACK decision to the REAL install
	-- state. System._firstRunInstallPending is set true in RoClothes' first-run branch (marker absent)
	-- and false on warm runs, so the download flow shows EXACTLY when there's a real first-run download
	-- to run - and the loader below DRIVES that real download. (Replaces the standalone demo's own
	-- getgenv/marker simulation.) FORCE_FIRST_RUN still forces a preview of the flow.
	local firstRun = FORCE_FIRST_RUN or (System and System._firstRunInstallPending == true) or false

	-- ── AURORA + motes: the ambient background (on `dim`, behind `content`; pure Frames + UIGradient, no image assets) ──
	local done = false                       -- the finish() guard; declared HERE so the ambient loops below capture the same one
	local SINE = Enum.EasingStyle.Sine
	local animate = SET.cardAnims and not SET.reduceMotion
	local function ribbon(hue, rot, yf, phase)  -- a soft drifting colour band (white-fade UIGradient keeps the hue; a coloured gradient would multiply-darken it)
		local rb = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, yf), Size = UDim2.fromScale(1.7, 0.46), Rotation = rot, BackgroundColor3 = hue, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1, Parent = dim })
		new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.12), NumberSequenceKeypoint.new(1, 1) }), Parent = rb })
		tween(rb, 1.3, { BackgroundTransparency = 0.5 })
		if animate then task.spawn(function()
			task.wait(phase)
			while rb.Parent and not done do
				tween(rb, 7, { Rotation = rot + 7, Position = UDim2.fromScale(0.54, yf + 0.03) }, SINE); task.wait(math.max(0.1, 7 * SPEED))
				if not rb.Parent or done then break end
				tween(rb, 7, { Rotation = rot - 7, Position = UDim2.fromScale(0.46, yf - 0.03) }, SINE); task.wait(math.max(0.1, 7 * SPEED))
			end
		end) end
	end
	ribbon(T.accent, -18, 0.30, 0); ribbon(T.accent2, 14, 0.60, 1.2); ribbon(T.accent, 6, 0.86, 2.4)  -- staggered pink / purple / pink

	if animate then for i = 1, 16 do  -- rising, twinkling motes
		local s = math.random(2, 5)
		local m = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(math.random(), math.random()), Size = UDim2.fromOffset(s, s), BackgroundColor3 = (i % 3 == 0) and T.accent2 or (i % 3 == 1) and T.accent or Color3.new(1, 1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1, Parent = dim }); corner(m, 999)
		task.spawn(function()
			while m.Parent and not done do
				local dur = math.random(6, 12)
				m.Position = UDim2.fromScale(math.random(), 1.08)
				tween(m, 0.8, { BackgroundTransparency = math.random(35, 62) / 100 })
				tween(m, dur, { Position = UDim2.fromScale(m.Position.X.Scale + (math.random() - 0.5) * 0.08, -0.08) }, Enum.EasingStyle.Linear)
				task.wait(math.max(0.1, dur * SPEED)); if not m.Parent or done then break end
				tween(m, 0.6, { BackgroundTransparency = 1 }); task.wait(math.max(0.1, 0.6 * SPEED))
			end
		end)
	end end

	-- ── VIGNETTE: gentle edge-darkening for depth + edge contrast; centre stays clear so the see-through is intact ──
	local function vig(rot)  -- a black frame, transparent through the middle, ~20% at the edges (via a UIGradient)
		local v = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1, Parent = dim })
		new("UIGradient", { Rotation = rot, Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.8), NumberSequenceKeypoint.new(0.35, 1), NumberSequenceKeypoint.new(0.65, 1), NumberSequenceKeypoint.new(1, 0.8) }), Parent = v })
		if animate then tween(v, 1.1, { BackgroundTransparency = 0 }) else v.BackgroundTransparency = 0 end
	end
	vig(90); vig(0)  -- darken top+bottom, then left+right → soft corners; created AFTER the aurora/motes so it sits above them (still below content)

	-- the ORIGINAL per-letter "RoClothes:Krul" logo (RoClothes near-white / ":" grey / Krul brand pink 255,110,180),
	-- soft stroke, centred upper-third. Glow + wave + taglines land in a later task; brandLetters drives the wave.
	local brand = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.34, 0), Size = UDim2.fromOffset(1, 46), BackgroundTransparency = 1, ZIndex = 6, Parent = content })
	local brandLetters = {}
	do
		local BR, _bx = "RoClothes:Krul", 0
		for i = 1, #BR do
			local ch = BR:sub(i, i)
			local col = (i >= 11) and Color3.fromRGB(255, 110, 180) or (ch == ":" and Color3.fromRGB(200, 200, 215) or Color3.fromRGB(245, 247, 255))
			local w = 22; pcall(function() w = math.ceil(TextService:GetTextSize(ch, 42, FONTB, Vector2.new(1e4, 1e4)).X) + 2 end)
			local ll = lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, _bx, 0.5, 0), Size = UDim2.fromOffset(w, 46), Text = ch, Font = FONTB, TextSize = 42, TextColor3 = col, TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 1, ZIndex = 6, Parent = brand }); ll.TextStrokeTransparency = 0.5
			brandLetters[i] = { lbl = ll, x = _bx }; _bx = _bx + w
		end
		brand.Size = UDim2.fromOffset(_bx, 46)
	end

	-- glow halo behind the logo (breathes) + the header letter WAVE (brand ZIndex 6 sits above glow ZIndex 5)
	local glow = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.34, 0), Size = UDim2.fromOffset(600, 150), BackgroundColor3 = T.accent, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 5, Parent = content }); corner(glow, 999)
	new("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.5), NumberSequenceKeypoint.new(1, 1) }), Parent = glow })  -- horizontal fade → a soft pink aura, not a hard pill
	if animate then
		glow.BackgroundTransparency = 1; tween(glow, 0.45, { BackgroundTransparency = 0.5 }); task.delay(0.5, function() if not done then tween(glow, 0.6, { BackgroundTransparency = 0.8 }) end end)  -- BLOOM on entrance: flash bright, then settle
		task.spawn(function() task.wait(1.3); while glow.Parent and not done do tween(glow, 1.8, { BackgroundTransparency = 0.9 }); task.wait(math.max(0.1, 1.8 * SPEED)); if not glow.Parent or done then break end; tween(glow, 1.8, { BackgroundTransparency = 0.72 }); task.wait(math.max(0.1, 1.8 * SPEED)) end end)  -- breathe
		task.spawn(function()  -- Mexican wave on the logo letters (same as the Home header), until done
			local t0 = os.clock()
			while not done and brand.Parent do
				local t = os.clock() - t0
				for i, e in ipairs(brandLetters) do
					local ph = ((t - (i - 1) * 0.07) % 1.5) / 1.5; local y = 0
					if ph < 0.3 then local u = ph / 0.3; y = u * u * (3 - 2 * u) * -6 elseif ph < 0.6 then local u = (ph - 0.3) / 0.3; y = (1 - u * u * (3 - 2 * u)) * -6 end
					e.lbl.Position = UDim2.new(0, e.x, 0.5, math.floor(y))
				end
				task.wait()
			end
		end)
	else
		glow.BackgroundTransparency = 0.84  -- reduce-motion: set instant (was tweening - parity with vig()'s else-branch)
	end

	-- rotating taglines: atmospheric flavor lines INTERLEAVED with feature "ad" lines that describe the UI
	-- (fade-swap, longer dwell so the ad copy reads) - shuffled once so the order varies each run.
	local taglines = {
		-- flavor
		"Couture for the cursed…", "Dressing you to kill…", "Threads darker than midnight…", "The night has excellent taste…", "Tailored by moonlight…", "Blood-red never goes out of style…", "Fangs out, fits on…", "Krul insists on elegance…", "Eternal style, no daylight required…", "Draping you in shadow…", "Rendering your finest fits…", "Serving looks after dark…", "Every thread, perfected…", "Your fit, immortalized…", "Where mortals become legends…", "Loading looks that bite…", "Almost runway-ready…", "Patience, darling…",
		-- feature ads (describe the UI)
		"Eleven tabs, one elegant SmartBar.", "Ten themes, or craft your own.", "Multi-Panel Mode: five tools at once.", "Every setting previewed live before you commit.", "Buttery, staggered motion on every tap.", "Recolor, resize, reshape - precision dressing.", "The whole catalog, straight from krulhub.dev.", "Live FPS, physics and memory on your Home.", "Glass panels, custom roundness, your transparency.", "Dock the bar anywhere - icons or labels.", "Krul Global Chat, one tap away.", "Community bundles, curated and ready.", "A settings panel that shows, not tells.", "Tuned for mobile and desktop alike.", "Your avatar, your stats, your night.", "Layer, drape and lock every thread.", "News, drops and betas - first, always.", "Crafted by Krul, obsessed with the details.",
	}
	for i = #taglines, 2, -1 do local j = math.random(i); taglines[i], taglines[j] = taglines[j], taglines[i] end
	local tag = lbl({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.45, 0), Size = UDim2.fromOffset(760, 26), Text = taglines[1], Font = FONT, TextSize = 18, TextColor3 = Color3.fromRGB(232, 230, 242), TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 1, ZIndex = 6, Parent = content })
	if animate then task.spawn(function()
		task.wait(0.9)
		local ti = 1
		while tag.Parent and not done do
			tween(tag, 0.45, { TextTransparency = 0.08 }); task.wait(math.max(0.1, 2.1 * SPEED))
			if not tag.Parent or done then break end
			tween(tag, 0.4, { TextTransparency = 1 }); task.wait(math.max(0.1, 0.4 * SPEED))
			ti = ti % #taglines + 1; tag.Text = taglines[ti]
		end
	end) else tag.TextTransparency = 0.08 end  -- reduce-motion: one static tagline, no fade-cycling (parity with the other ambient loops)

	-- ── DOWNLOAD LOG: streaming filenames above the bar (monospace; newest at the bottom, older lines fading up) ──
	local LOGN = 4
	local LOGPRE = { "", "", "assets/", "tex/", "ui/", "mesh/", "cfg/", "icon/" }
	local LOGEXT = { ".mesh", ".json", ".png", ".ktx2", ".webp", ".ogg", ".lua", ".cfg", ".dat", ".rbxm", ".txt" }
	local LOGCH = "abcdefghijklmnopqrstuvwxyz0123456789"
	local logBox = new("Frame", { AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 0.62, 0), Size = UDim2.fromOffset(560, 76), BackgroundTransparency = 1, ZIndex = 6, Parent = content })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 3), HorizontalAlignment = Enum.HorizontalAlignment.Center, VerticalAlignment = Enum.VerticalAlignment.Bottom, Parent = logBox })
	local logLines = {}
	for i = 1, LOGN do logLines[i] = lbl({ Size = UDim2.fromOffset(560, 15), Text = "", Font = Enum.Font.Code, TextSize = 13, TextColor3 = Color3.fromRGB(150, 152, 170), TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 0.06 + (LOGN - i) * 0.26, LayoutOrder = i, ZIndex = 6, Parent = logBox }) end
	local function fakeName()
		local n = ""; for _ = 1, math.random(6, 9) do local k = math.random(#LOGCH); n = n .. LOGCH:sub(k, k) end
		return LOGPRE[math.random(#LOGPRE)] .. n .. LOGEXT[math.random(#LOGEXT)] .. "  ·  " .. math.random(12, 840) .. " KB"
	end
	local function pushFile(nm)  -- shift the stack up, newest at the bottom; nm = a REAL filename (else a fake one)
		for i = 1, LOGN - 1 do logLines[i].Text = logLines[i + 1].Text end
		logLines[LOGN].Text = nm or fakeName()
	end
	local streaming = false  -- T6 turns this on during the download; the loop pushes files only while it's on
	if animate then task.spawn(function()
		while logBox.Parent and not done do
			if streaming then pushFile() end
			task.wait(math.max(0.06, math.random(10, 22) / 100 * SPEED))
		end
	end) end

	-- ── LOADER: progress bar + % + checklist chips (driven by setProgress; T6 feeds it the download) ──
	-- V4.5.16: the BAR is centred on screen; the % + elapsed trail to its RIGHT as independent overlays. Previously a
	-- centred UIListLayout row of [bar][%][timer] centred the whole GROUP - which pushed the bar left of centre by the
	-- width of the labels, so it read as misaligned under the (genuinely centred) title and stage chips.
	local loaderRow = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.66, 0), Size = UDim2.fromOffset(500, 20), BackgroundTransparency = 1, ZIndex = 6, Parent = content })
	local track = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.fromOffset(500, 8), BackgroundColor3 = T.line, BackgroundTransparency = 0.2, BorderSizePixel = 0, ZIndex = 6, Parent = loaderRow }); corner(track, 4)
	local fill = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(0, 0, 1, 0), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 7, Parent = track }); corner(fill, 4); new("UIGradient", { Color = ColorSequence.new(T.accent, T.accent2), Parent = fill })  -- white base so the pink→purple gradient shows
	-- V4.5.16: % + elapsed centred as a pair directly BELOW the (centred) bar - keeps the whole loader on the centre
	-- axis (the % straddles centre on the left, the elapsed on the right, 12px gap). Was: labels trailed right of the bar.
	local pct = lbl({ AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(0.5, -6, 0.5, 22), Size = UDim2.fromOffset(60, 20), Text = "0%", Font = FONTB, TextSize = 15, TextColor3 = T.txt, TextXAlignment = Enum.TextXAlignment.Right, TextTransparency = 0.1, ZIndex = 6, Parent = loaderRow })  -- +22 → 8px below the bar (proximity: related, within the progress unit)
	-- V4.4.x: elapsed-time counter (mm:ss) beside the % - ticks up while downloading, driven in the firstRun branch.
	local timerLbl = lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0.5, 6, 0.5, 22), Size = UDim2.fromOffset(52, 20), Text = "0:00", Font = FONT, TextSize = 14, TextColor3 = T.txt2, TextXAlignment = Enum.TextXAlignment.Left, TextTransparency = 0.2, ZIndex = 6, Parent = loaderRow })
	-- V4.4.x: a soft light band SWEEPS across the bar every couple seconds so it reads as actively working, not a static bar.
	track.ClipsDescendants = true
	local barSweep = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(-0.25, 0, 0.5, 0), Size = UDim2.new(0.22, 0, 1, 0), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 8, Parent = track })
	new("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.5), NumberSequenceKeypoint.new(1, 1) }), Parent = barSweep })  -- soft edges → a glint, not a hard block
	if animate then task.spawn(function()
		while track.Parent and not done do
			barSweep.Position = UDim2.new(-0.25, 0, 0.5, 0); barSweep.BackgroundTransparency = 0.3
			tween(barSweep, 0.85, { Position = UDim2.new(1.25, 0, 0.5, 0) })
			task.wait(0.85); barSweep.BackgroundTransparency = 1
			task.wait(1.7)   -- pause between sweeps ("once in a while")
		end
		pcall(function() barSweep:Destroy() end)
	end) end

	-- install-stage chips: Connecting / Downloading / Installing / Finalizing - tick off at 25 / 50 / 75 / 100% (Frame dot markers, no glyphs)
	local CHIP, CHIPDONE, chipAt, chips = { "Connecting", "Downloading", "Installing", "Finalizing" }, { "Connected", "Downloaded", "Installed", "Finalized" }, { 0.25, 0.5, 0.75, 1.0 }, {}  -- install stages; each label swaps -ing → -ed when it completes
	-- V4.5.16: chips tied to the BAR's axis (0.66) + a fixed 61px drop = a 16px section gap below the % row (chunking:
	-- the checklist is a SEPARATE chunk from the progress unit, so 2× the 8px within-unit gap). Was 0.72 → 0.2px, touching.
	local chipRow = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.66, 61), Size = UDim2.fromOffset(500, 28), BackgroundTransparency = 1, ZIndex = 6, Parent = content })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 8), HorizontalAlignment = Enum.HorizontalAlignment.Center, VerticalAlignment = Enum.VerticalAlignment.Center, Parent = chipRow })
	for i, name in ipairs(CHIP) do
		local chip = new("Frame", { Size = UDim2.fromOffset(116, 26), BackgroundColor3 = T.card, BackgroundTransparency = 0.3, BorderSizePixel = 0, LayoutOrder = i, ZIndex = 6, Parent = chipRow }); corner(chip, 13); local cs = stroke(chip, T.line, 1); cs.Transparency = 0.35
		-- state-by-SHAPE (designparser red-green-color-blindness: never signal state by colour alone): pending = HOLLOW
		-- ring (transparent fill + grey stroke), active/done = FILLED accent. Progress reads even in greyscale.
		local dot = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 12, 0.5, 0), Size = UDim2.fromOffset(8, 8), BackgroundColor3 = T.accent, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 7, Parent = chip }); corner(dot, 999); local dotRing = stroke(dot, Color3.fromRGB(120, 120, 135), 1.5); dotRing.Transparency = 0.15
		local cl = lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 26, 0.5, 0), Size = UDim2.fromOffset(82, 20), Text = name, Font = FONT, TextSize = 13, TextColor3 = Color3.fromRGB(165, 165, 180), TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 7, Parent = chip })
		chips[i] = { chip = chip, lbl = cl, dot = dot, ring = dotRing, stroke = cs, name = name, doneText = CHIPDONE[i], done = false }
	end
	local function markChipDone(c)
		if c.done then return end
		c.done = true; c._active = nil; c.lbl.Text = c.doneText   -- swap -ing → -ed (e.g. Downloading → Downloaded)
		tween(c.dot, 0.3, { BackgroundColor3 = T.accent, BackgroundTransparency = 0 }); tween(c.ring, 0.3, { Color = T.accent, Transparency = 0.1 }); tween(c.lbl, 0.3, { TextColor3 = T.txt })
		tween(c.stroke, 0.3, { Color = T.accent, Transparency = 0.25 }); tween(c.chip, 0.3, { BackgroundTransparency = 0.15 })
	end
	local function markChipActive(c)  -- the stage happening RIGHT NOW: filled accent dot + a gentle pulse (clear focal point), text stays -ing (not done yet)
		if c.done or c._active then return end
		c._active = true
		tween(c.dot, 0.3, { BackgroundColor3 = T.accent, BackgroundTransparency = 0 }); tween(c.ring, 0.3, { Color = T.accent, Transparency = 0.2 }); tween(c.lbl, 0.3, { TextColor3 = T.txt2 })
		tween(c.stroke, 0.3, { Color = T.accent, Transparency = 0.3 }); tween(c.chip, 0.3, { BackgroundTransparency = 0.2 })
		if animate then task.spawn(function()  -- breathe the active dot so "happening now" is unmistakable; self-stops when the stage completes (c._active cleared by markChipDone)
			while c._active and not done and c.dot.Parent do
				tween(c.dot, 0.6, { BackgroundTransparency = 0.45 }); task.wait(0.6)
				if not (c._active and not done) then break end
				tween(c.dot, 0.6, { BackgroundTransparency = 0 }); task.wait(0.6)
			end
			pcall(function() c.dot.BackgroundTransparency = 0 end)
		end) end
	end
	-- V4.4.x: chips reflect REAL install PHASES (1=Connecting 2=Downloading 3=Installing 4=Finalizing),
	-- not arbitrary % quarters. Earlier phases show DONE, the current phase shows ACTIVE (highlighted).
	local _stageAt = 0
	local function setStage(idx)
		idx = math.clamp(math.floor(idx), 1, #chips)
		if idx < _stageAt then return end   -- monotonic; never regress a phase
		_stageAt = idx
		for i, c in ipairs(chips) do
			if i < idx then markChipDone(c)
			elseif i == idx then markChipActive(c) end
		end
	end
	local function finishChips()  -- install complete → every phase DONE
		for _, c in ipairs(chips) do markChipDone(c) end
	end
	local function setProgress(p)  -- bar + % ONLY; the chips are driven by real phase via setStage()
		p = math.clamp(p, 0, 1)
		fill.Size = UDim2.new(p, 0, 1, 0); pct.Text = math.floor(p * 100 + 0.5) .. "%"
	end
	-- V4.4.x: red "taking a while" warning - hidden; revealed if the download runs past ~30s (see the firstRun branch).
	local slowWarn = lbl({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.785, 0), Size = UDim2.fromOffset(560, 40), Text = "Taking a while - a slow download is usually your executor or network, not the script.", Font = FONT, TextSize = 13, TextColor3 = Color3.fromRGB(255, 120, 130), TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Center, TextYAlignment = Enum.TextYAlignment.Center, TextTransparency = 1, Visible = false, ZIndex = 7, Parent = content })
	local function showSlowWarn()
		if done or slowWarn.Visible then return end
		if not slowWarn.Parent then return end  -- V4.5.24 Fix: DESTROY mid-download destroys the intro without setting `done`; a write to a destroyed instance throws in the scheduler
		slowWarn.Visible = true
		if animate then tween(slowWarn, 0.5, { TextTransparency = 0.05 }) else slowWarn.TextTransparency = 0.05 end
	end
	-- V4.4.x: executor-capability warning at the TOP of the loader (red) - shown if the boot probe found a gap.
	local capsLoaderWarn = lbl({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.11, 0), Size = UDim2.fromOffset(700, 40), Text = "", Font = FONT, TextSize = 13, TextColor3 = Color3.fromRGB(255, 110, 120), TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 1, Visible = false, ZIndex = 8, Parent = content })
	System._onCapsGap(function(txt)
		if not (capsLoaderWarn and capsLoaderWarn.Parent) then return end
		capsLoaderWarn.Text = txt; capsLoaderWarn.Visible = true
		if animate then tween(capsLoaderWarn, 0.5, { TextTransparency = 0.05 }) else capsLoaderWarn.TextTransparency = 0.05 end
	end)

	-- Skip - bottom-right of the canvas, accent-gradient fill (white base so the gradient shows). Locked/unlocked in a
	-- later task; for now always active. The ONLY hand-off - no timers.
	local skip = new("TextButton", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.84, 0), Size = UDim2.fromOffset(168, 40), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, AutoButtonColor = false, Text = "", ZIndex = 8, Parent = content }); corner(skip, 11); new("UIGradient", { Rotation = 25, Color = ColorSequence.new(T.accent, T.accent2), Parent = skip })  -- centred just below the loader (per the user)
	local skipLbl = lbl({ Size = UDim2.fromScale(1, 1), Text = "Enter", Font = FONTB, TextSize = 16, TextColor3 = Color3.new(1, 1, 1), TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 1, ZIndex = 9, Parent = skip })  -- caption in a CHILD label - the button's UIGradient would otherwise recolor its own text invisible (roblox-uigradient-text)
	local skipScale = new("UIScale", { Scale = 1, Parent = skip })  -- ONE UIScale, animated by BOTH the entrance pop and the unlock pulse (two UIScales would conflict)

	local function finish()  -- dramatic exit: accent flash + logo scatter + loader drop, then fade out and hand off (once)
		if done then return end; done = true
		if animate then
			local flash = new("Frame", { Name = "ExitFlash", Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.accent, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 50, Parent = dim })
			tween(flash, 0.16, { BackgroundTransparency = 0.5 }); task.delay(0.2, function() tween(flash, 0.55, { BackgroundTransparency = 1 }) end)
			for i, e in ipairs(brandLetters) do task.delay((i - 1) * 0.02, function() pcall(function() tween(e.lbl, 0.45, { Position = UDim2.new(0, e.x, 0.5, -28) }) end) end) end   -- letters scatter upward
			for _, f in ipairs({ logBox, loaderRow, chipRow }) do pcall(function() tween(f, 0.45, { Position = f.Position + UDim2.fromOffset(0, 34) }) end) end   -- loader drops away
		end
		tween(dim, 0.5, { BackgroundTransparency = 1 })
		for _, d in ipairs(dim:GetDescendants()) do
			if d.Name ~= "ExitFlash" then pcall(function()
				if d:IsA("GuiObject") and d.BackgroundTransparency < 1 then tween(d, 0.45, { BackgroundTransparency = 1 }) end
				if d:IsA("TextLabel") or d:IsA("TextButton") then tween(d, 0.45, { TextTransparency = 1 }) end
				if d:IsA("ImageLabel") then tween(d, 0.45, { ImageTransparency = 1 }) end
			end) end
		end
		task.delay(0.6, function() if MP.introVpConn then pcall(function() MP.introVpConn:Disconnect() end); MP.introVpConn = nil end; pcall(function() ov:Destroy() end); reveal() end)  -- introVpConn lives on the Camera (outside ov) → ov:Destroy() won't stop it; disconnect so fitIntro can't fire on the dead intro
	end
	local skipLocked = false
	local function lockSkip()  -- first run: greyed + "Loading…" until the download hits 100%
		skipLocked = true; skip.Active = false; skipLbl.Text = "Loading…"; skip.BackgroundColor3 = T.line
		for _, g in ipairs(skip:GetChildren()) do if g:IsA("UIGradient") then g.Enabled = false end end
	end
	local function unlockSkip()  -- 100% (or second run): pink + "Enter" + an attention pulse
		skipLocked = false; skip.Active = true; skipLbl.Text = "Enter"; skip.BackgroundColor3 = Color3.new(1, 1, 1)
		for _, g in ipairs(skip:GetChildren()) do if g:IsA("UIGradient") then g.Enabled = true end end
		if animate then tween(skipScale, 0.15, { Scale = 1.12 }); task.delay(0.15 * SPEED, function() tween(skipScale, 0.4, { Scale = 1 }, BACK) end) end
	end
	-- V4.4.x: the DESTROY button's shockwave, on the Enter hand-off. Standalone burst (flare + concentric
	-- shockwaves + spiralling embers + glow) fired from the button centre - NO teardown; finish() still hands off.
	local function enterBurst(bx, by)
		local fx = new("ScreenGui", { Name = "RoClothesEnterFx", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 2002, Parent = PlayerGui })
		local orig = UDim2.fromOffset(bx, by)
		local vw = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X) or 1280
		local function bdot(sz, col, z, par) local d = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = orig, Size = UDim2.fromOffset(sz, sz), BackgroundColor3 = col, BorderSizePixel = 0, ZIndex = z or 12, Parent = par or fx }); corner(d, 999); return d end
		local core = bdot(40, Color3.fromRGB(255, 235, 245), 16); core.BackgroundTransparency = 0   -- flare
		tween(core, 0.12, { Size = UDim2.fromOffset(150, 150) }); task.delay(0.12, function() tween(core, 0.42, { Size = UDim2.fromOffset(300, 300), BackgroundTransparency = 1 }) end)
		for r = 1, 4 do task.delay((r - 1) * 0.07, function() if not fx.Parent then return end   -- concentric shockwaves
			local ring = bdot(24, T.bg, 11); ring.BackgroundTransparency = 1; local rs = stroke(ring, (r % 2 == 0) and T.accent2 or T.accent, 13)
			tween(ring, 0.6, { Size = UDim2.fromOffset(vw * 1.5, vw * 1.5) }, EXPO); tween(rs, 0.6, { Transparency = 1, Thickness = 2 })
		end) end
		local outSp = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = orig, Size = UDim2.fromOffset(0, 0), BackgroundTransparency = 1, ZIndex = 14, Parent = fx }); tween(outSp, 0.9, { Rotation = 150 }, QUINT)   -- pivot → embers SPIRAL out
		local COL = { T.accent, T.accent2, Color3.fromRGB(255, 220, 235) }
		for i = 1, 40 do
			local m = bdot(2 + math.random() * 7, COL[(i % 3) + 1], 14, outSp); m.Position = UDim2.fromOffset(0, 0)
			local ang, dist = math.random() * math.pi * 2, 120 + math.random() * 480
			tween(m, 0.6 + math.random() * 0.4, { Position = UDim2.fromOffset(math.cos(ang) * dist, math.sin(ang) * dist), Size = UDim2.fromOffset(1, 1), BackgroundTransparency = 1 }, QUINT)
		end
		local glow = bdot(90, T.accent, 10); glow.BackgroundTransparency = 0.22; tween(glow, 0.9, { Size = UDim2.fromOffset(420, 420), BackgroundTransparency = 1 })
		task.delay(1.3, function() pcall(function() fx:Destroy() end) end)
	end
	skip.MouseButton1Click:Connect(function()   -- Enter is the ONLY hand-off; no-ops while locked
		if skipLocked then return end
		if animate then local ap, asz = skip.AbsolutePosition, skip.AbsoluteSize; pcall(enterBurst, ap.X + asz.X / 2 + GUI_INSET.X, ap.Y + asz.Y / 2 + GUI_INSET.Y) end   -- shockwave from the button centre (+GUI_INSET: the burst fx is IgnoreGuiInset, so AbsolutePosition under-reports by the topbar inset - same correction as destroyUI/edgeStart)
		finish()
	end)

	-- V4.4.x: loader ERROR state - hide the download UI, show a red message, unlock Enter (into the degraded
	-- UI). Used when HTTP is definitively blocked (no point pretending to download) or the install truly fails.
	local errLbl = lbl({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.64, 0), Size = UDim2.fromOffset(660, 66), Text = "", Font = FONT, TextSize = 15, TextColor3 = Color3.fromRGB(255, 110, 120), TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 1, Visible = false, ZIndex = 8, Parent = content })
	local function loaderError(msg)
		if done then return end
		streaming = false
		pcall(function() loaderRow.Visible = false; chipRow.Visible = false; logBox.Visible = false; slowWarn.Visible = false end)
		errLbl.Text = msg; errLbl.Visible = true
		if animate then tween(errLbl, 0.4, { TextTransparency = 0.03 }) else errLbl.TextTransparency = 0.03 end
		unlockSkip(); skipLbl.Text = "Enter"
	end

	-- ── TWO-RUN FLOW: first run DOWNLOADS (Skip locked until 100%); second run is INSTANT (Skip active). No auto-hand-off. ──
	if firstRun then
		lockSkip(); streaming = animate
		if not animate then logLines[LOGN].Text = "Downloading assets…" end
		task.spawn(function()
			-- V4.4.x DEMO LOADER WIRING: drive this loader with the REAL first-run download instead of a
			-- fake timer. System._runFirstRunInstall (RoClothes' deferred first-run runner) YIELDS until
			-- every file has landed, calling onProgress(done,total,failed) throughout - we map that to the
			-- bar/%/stage-chips. The ambient fake-filename scroller (`streaming`) keeps rolling for flavor.
			-- Fallback: if the runner is absent (a forced preview, or a warm session that still forced this
			-- flow), use the old smooth ease-out sim so the loader never sits frozen.
			if System and System._runFirstRunInstall then
				streaming = false   -- REAL filenames drive the log now; silence the fake-name scroller so they don't interleave
				-- The real pack/file download lands in chunky bursts (a pack = ~11 files at once), so feeding
				-- raw done/total straight to setProgress makes the bar + stage-chips JUMP. Instead the callback
				-- only moves a monotonic TARGET (_realP); a per-frame loop eases the DISPLAYED value (_dispP)
				-- toward it, so the bar fills and the chips (Connecting→Downloading→Installing→Finalizing at
				-- 25/50/75/100%) light in a smooth sequence - the demo's feel, on real data.
				local _realP, _dispP, _lastShown = 0, 0, nil
				local _installDone = false
				setStage(1)  -- Connecting: manifests being fetched, before the first byte
				-- V4.4.x: if HTTP is DEFINITIVELY blocked, there's no point running the download flow - the
				-- "Connecting" stage has honestly covered the probe; now show a network error instead of a bar
				-- that can only sit at 0%. Wait for the probe (≤8s); nil/timeout falls through to try anyway.
				do
					local _ct = os.clock()
					while System._caps.http == nil and not System._capsDone and (os.clock() - _ct) < 8 do task.wait(0.2) end
					if System._caps.http == false then
						loaderError("Your executor can't reach the internet (HTTP is blocked), so RoClothes can't download its content. Most features won't work on this executor.")
						return
					end
				end
				task.spawn(function()  -- V4.4.x: elapsed-time counter, ticks until the loader finishes
					local _t0 = os.clock()
					while not done do
						local el = os.clock() - _t0
						timerLbl.Text = string.format("%d:%02d", math.floor(el / 60), math.floor(el % 60))
						task.wait(0.25)
					end
				end)
				task.delay(30, showSlowWarn)  -- V4.4.x: past ~30s, warn (red) that a slow download is usually the executor/network
				task.delay(90, function() if not done and slowWarn.Parent then slowWarn.Text = "Still downloading… big first-time install on a slow connection. If it seems stuck, try another executor or check your network." end end)  -- V4.5.24 Fix: Parent guard (intro may be destroyed by DESTROY without `done` set)
				task.spawn(function()
					while not done and not _installDone do
						local dt = task.wait()
						_dispP = _dispP + (_realP - _dispP) * math.clamp(dt * 6, 0, 1)  -- exponential ease toward target
						if _dispP > _realP then _dispP = _realP end
						setProgress(_dispP)
					end
				end)
				local _pok, _installOk = pcall(System._runFirstRunInstall, function(dn, tot, fl, file, sz, stage)
					if done then return end
					-- REAL install phase → light the matching chip. Connecting was set active above and
					-- auto-completes once Downloading begins; Installing/Finalizing fire at the real end steps.
					if stage == "downloading" then setStage(2)
					elseif stage == "installing" then setStage(3)
					elseif stage == "finalizing" then setStage(4) end
					local p = (tot and tot > 0) and (dn / tot) or _realP
					if p > _realP then _realP = p end   -- monotonic target; the smoothing loop follows it
					-- push the REAL file just downloaded into the log (basename + KB, matching the fake format)
					if file and file ~= _lastShown then
						_lastShown = file
						local base = tostring(file):match("[^/]+$") or tostring(file)
						local kb = (type(sz) == "number" and sz > 0) and ("  ·  " .. math.max(1, math.floor(sz / 1024)) .. " KB") or ""
						pushFile(base .. kb)
					end
				end)
				-- V4.4.x: the install returned FAILURE (marker never landed) → don't show "All assets ready" on a
				-- broken install. Surface a network/download error + let them Enter into the degraded UI.
				if (not _pok) or (_installOk == false) then
					loaderError("Couldn't download RoClothes content. " .. ((System._caps.http == false) and "Your executor's network/HTTP is blocked." or "The download failed - check your connection, or try another executor."))
					return
				end
				_realP = 1   -- install returned → target 100%; let the smoothing catch up before the hard-set below (no end-snap)
				local _t0 = os.clock()
				while not done and _dispP < 0.999 and (os.clock() - _t0) < 1.5 do task.wait() end
				_installDone = true
			else
				local start, DURATION = os.clock(), 8
				while not done and ov.Parent do   -- .Parent guard so it stops if the overlay is torn down outside the Skip/finish path (e.g. destroyUI)
					local e = math.clamp((os.clock() - start) / DURATION, 0, 1)
					local pp = 1 - (1 - e) * (1 - e)    -- ease-out: quick, then settles near the end (feels like a real download)
					setProgress(pp)
					setStage(pp >= 0.75 and 4 or pp >= 0.5 and 3 or pp >= 0.25 and 2 or 1)  -- preview has no real phases; map bar → chips
					if e >= 1 then break end
					task.wait()
				end
			end
			if not done then
				setProgress(1); streaming = false
				finishChips()   -- every phase DONE (flips the active chip to its -ed state)
				for i = 1, LOGN - 1 do logLines[i].Text = "" end; logLines[LOGN].Text = "All assets ready"
				unlockSkip()
			end
		end)
	else  -- SECOND type: a WELCOME-BACK splash - NO download UI (a cached run shouldn't scream "downloading")
		loaderRow.Visible = false; chipRow.Visible = false; logBox.Visible = false
		local welcome = lbl({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.58, 0), Size = UDim2.fromOffset(420, 26), Text = "Welcome back", Font = FONT, TextSize = 18, TextColor3 = Color3.fromRGB(214, 212, 226), TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 1, ZIndex = 6, Parent = content })
		skip.Position = UDim2.new(0.5, 0, 0.68, 0)          -- Enter sits just under the welcome line (no loader below it)
		unlockSkip(); skipLbl.Text = "Enter"                -- nothing to skip on a cached run - you're entering
		task.delay(0.6, function() if not done then tween(welcome, 0.6, { TextTransparency = 0.05 }) end end)
	end

	-- CONTRAST: the backdrop is see-through, so give every text label a dark stroke → readable over the live game
	for _, d in ipairs(content:GetDescendants()) do
		if d:IsA("TextLabel") then d.TextStrokeColor3 = Color3.fromRGB(10, 10, 14); d.TextStrokeTransparency = 0.3 end
	end

	-- ENTRANCE choreography: the logo assembles letter-by-letter, then the Skip button pops in. (Aurora / glow / loader
	-- reveal themselves; the backdrop stays fully see-through.)
	task.spawn(function()
		if animate then
			for _, e in ipairs(brandLetters) do e.lbl.TextTransparency = 1 end
			for i, e in ipairs(brandLetters) do task.delay((i - 1) * 0.045 * SPEED, function() if not done then tween(e.lbl, 0.45, { TextTransparency = 0 }) end end) end
		else
			for _, e in ipairs(brandLetters) do e.lbl.TextTransparency = 0 end
		end
		task.wait(math.max(0.2, 0.5 * SPEED))
		if done then return end
		if animate then skipScale.Scale = 0.62 end
		tween(skip, 0.5, { BackgroundTransparency = 0.12 }); tween(skipLbl, 0.5, { TextTransparency = 0 })
		if animate then tween(skipScale, 0.55, { Scale = 1 }, BACK) end   -- pop in
	end)
end
A.playIntro()  -- play once at boot (identical timing to the old inline IIFE)

-- TEST teardown so the script can be re-run cleanly without rejoining. TEMPORARY - the shipped DESTROY (more
-- complete) will replace this. Disconnects the global Heartbeats + picker UIS drag conns, un-hides any game GUIs
-- we hid, drops the Lighting blur, and destroys every ScreenGui (which cascades to descendants → ends the ambient
-- `while <inst>.Parent do` loops and fires the sliders' Destroying disconnects).
destroyUI = function(ox, oy)   -- ox,oy = the DESTROY-button-centre (raw AbsolutePosition space); the shockwave bursts from there
	if _destroyed then return end
	_destroyed = true
	stopWave(); stopGlow(); if A.stopAuto then A.stopAuto() end   -- kill ambient loops NOW so nothing re-appears mid-exit
	pcall(function() _pk1:Disconnect() end); pcall(function() _pk2:Disconnect() end)
	pcall(function() MP.vpConn:Disconnect() end); pcall(function() MP.setVpConn:Disconnect() end); pcall(function() MP.introVpConn:Disconnect() end)   -- the 3 previously-uncaptured ViewportSize connections (were stacking on DESTROY + re-run)
	-- The REAL teardown (restore the game's UI + destroy every ScreenGui). Deferred behind the exit animation below.
	local function teardown()
		-- V4.5.17 NON-INTRUSIVE: destroyUI teardown no longer force-enables CoreGui/topbar. openHome disables none, so re-enabling would only clobber CoreGui the host game itself disabled. The _hiddenGuis restore below stays (re-enables only game ScreenGuis WE hid = none now).
		for _, g in ipairs(_KR._hiddenGuis or {}) do pcall(function() g.Enabled = true end) end
		if _KR.homeBlur then pcall(function() _KR.homeBlur:Destroy() end) end
		pcall(function() local i = PlayerGui:FindFirstChild("RoClothesIntro"); if i then i:Destroy() end end)  -- tear down the intro overlay too if DESTROY is hit mid-play
		for _, s in ipairs({ screen, homeScreen, panelScreen, pickerScreen, modalScreen, MP.screen, GUIObject.hardcoreUI }) do pcall(function() s:Destroy() end) end  -- V4.5.24 Fix: hardcoreUI (mobile Heal/Tear buttons + hardcore HP group) was missing -> orphan after DESTROY
	end
	if SET.reduceMotion then teardown(); return end   -- reduced motion → no exit animation, tear down immediately
	-- EXIT ANIMATION - the UI COLLAPSES INTO the DESTROY button first (gliding in, swirling + shrinking to a point) while a
	-- core charges and sparks SPIRAL IN; then it DETONATES: a flare, FIVE thick concentric shockwaves, ~54 embers SPIRALLING
	-- out + debris streaks, and a lingering glow. Then teardown.
	local cam = workspace.CurrentCamera
	local vw, vh = (cam and cam.ViewportSize.X) or 1280, (cam and cam.ViewportSize.Y) or 720
	local tx, ty = ox or (vw / 2), oy or (vh / 2)                                             -- collapse target = the button centre (AbsolutePosition space)
	local cx, cy = (ox and ox + GUI_INSET.X) or (vw / 2), (oy and oy + GUI_INSET.Y) or (vh / 2)   -- fx burst origin (+ inset for the IgnoreGuiInset overlay) = the button's RENDERED centre, so blast + collapse line up
	local fx = new("ScreenGui", { Name = "RoClothesDestroyFx", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 2001, Parent = PlayerGui })
	local orig = UDim2.fromOffset(cx, cy)
	local function dot(sz, col, z, par) local d = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = orig, Size = UDim2.fromOffset(sz, sz), BackgroundColor3 = col, BorderSizePixel = 0, ZIndex = z or 12, Parent = par or fx }); corner(d, 999); return d end
	local function spinner(deg, dur, z) local sp = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = orig, Size = UDim2.fromOffset(0, 0), BackgroundTransparency = 1, Rotation = 0, ZIndex = z or 13, Parent = fx }); tween(sp, dur, { Rotation = deg }, QUINT); return sp end   -- rotating pivot → children moving radially trace a SPIRAL
	-- PHASE 1 - COLLAPSE INTO THE BUTTON (~0.36s): each container glides to the button, swirls + shrinks to nothing; a core
	-- charges up while sparks SPIRAL IN (spinner pivot + a radial-in tween).
	for _, o in ipairs({ bar, homeScroll, panel }) do pcall(function()
		if not (o and o.AbsoluteSize.X > 0) then return end
		local ac = o.AbsolutePosition + o.AbsoluteSize / 2
		tween(o, 0.36, { Position = o.Position + UDim2.fromOffset(tx - ac.X, ty - ac.Y), Rotation = 24 }, QUINT)   -- glide to the button + swirl
		local u = o:FindFirstChildOfClass("UIScale"); if u then tween(u, 0.36, { Scale = 0 }, QUINT) end            -- shrink into the point
	end) end
	local core = dot(6, Color3.fromRGB(255, 235, 245), 16); core.BackgroundTransparency = 0.1; tween(core, 0.36, { Size = UDim2.fromOffset(54, 54) })
	local inSp = spinner(-150, 0.36, 15)
	for i = 1, 18 do
		local ang, dist = (i / 18) * math.pi * 2, 150 + math.random() * 210
		local s = dot(3 + math.random() * 3, (i % 2 == 0) and T.accent or T.accent2, 15, inSp); s.Position = UDim2.fromOffset(math.cos(ang) * dist, math.sin(ang) * dist); s.BackgroundTransparency = 1
		tween(s, 0.16, { BackgroundTransparency = 0.1 }); tween(s, 0.36, { Position = UDim2.fromOffset(0, 0), Size = UDim2.fromOffset(1, 1) }, QUINT)
	end
	for _, sg in ipairs({ screen, homeScreen, panelScreen, MP.screen }) do   -- fade text/images so nothing lingers into the blast (the containers shrink; this catches the rest)
		for _, d in ipairs(sg:GetDescendants()) do pcall(function()
			if (d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox")) and d.TextTransparency < 1 then tween(d, 0.32, { TextTransparency = 1 }) end
			if (d:IsA("ImageLabel") or d:IsA("ImageButton")) and d.ImageTransparency < 1 then tween(d, 0.32, { ImageTransparency = 1 }) end
		end) end
	end
	-- PHASE 2 - DETONATION (~0.36s in): hide the collapsed UI (it's a point now), then flare + FIVE thick shockwaves + a
	-- SPIRAL ember blast + streaks + glow.
	task.delay(0.36, function()
		if not fx.Parent then return end
		pcall(function() for _, sg in ipairs({ screen, homeScreen, panelScreen, MP.screen }) do sg.Enabled = false end end)
		tween(core, 0.12, { Size = UDim2.fromOffset(150, 150), BackgroundTransparency = 0 }); task.delay(0.12, function() tween(core, 0.42, { Size = UDim2.fromOffset(320, 320), BackgroundTransparency = 1 }) end)
		for r = 1, 5 do task.delay((r - 1) * 0.07, function() if not fx.Parent then return end   -- FIVE thick concentric shockwaves
			local ring = dot(24, T.bg, 11); ring.BackgroundTransparency = 1; local rs = stroke(ring, (r % 2 == 0) and T.accent2 or T.accent, 13)
			tween(ring, 0.65, { Size = UDim2.fromOffset(vw * 1.9, vw * 1.9) }, EXPO); tween(rs, 0.65, { Transparency = 1, Thickness = 2 })
		end) end
		local outSp = spinner(155, 0.9, 14)   -- ember blast SPIRALS out (spinner pivot + a radial-out tween)
		local COL = { T.accent, T.accent2, Color3.fromRGB(255, 220, 235) }
		for i = 1, 54 do
			local m = dot(2 + math.random() * 8, COL[(i % 3) + 1], 14, outSp); m.Position = UDim2.fromOffset(0, 0)   -- start at the pivot
			local ang, dist = math.random() * math.pi * 2, 150 + math.random() * 560
			tween(m, 0.6 + math.random() * 0.4, { Position = UDim2.fromOffset(math.cos(ang) * dist, math.sin(ang) * dist), Size = UDim2.fromOffset(1, 1), BackgroundTransparency = 1 }, QUINT)
		end
		for i = 1, 16 do   -- streaks: thin elongated debris shooting straight out along its own angle
			local ang = math.random() * math.pi * 2
			local st = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = orig, Size = UDim2.fromOffset(54, 3), Rotation = math.deg(ang), BackgroundColor3 = (i % 2 == 0) and T.accent or Color3.fromRGB(255, 220, 235), BorderSizePixel = 0, ZIndex = 12, Parent = fx }); corner(st, 2)
			local dist = 240 + math.random() * 360
			tween(st, 0.45, { Position = UDim2.fromOffset(cx + math.cos(ang) * dist, cy + math.sin(ang) * dist), Size = UDim2.fromOffset(7, 1), BackgroundTransparency = 1 }, QUINT)
		end
		local glow = dot(90, T.accent, 10); glow.BackgroundTransparency = 0.22; tween(glow, 0.9, { Size = UDim2.fromOffset(440, 440), BackgroundTransparency = 1 })
	end)
	task.delay(1.4, function() pcall(function() fx:Destroy() end); teardown() end)
end
	-- ---- engine GUIObject contract: hand the engine its real surfaces ----
	GUIObject.Screen = screen                 -- engine Insert-key toggles screen.Enabled
	-- Retain the compatibility Frame contract; V3 owns its window dragging.
	GUIObject.MainFrame = new("Frame", { Name = "_EngineMainFrameStub", BackgroundTransparency = 1, Visible = false, Size = UDim2.fromOffset(1, 1), Parent = screen })

	-- [V3 MERGE FIX] ENGINE OVERLAY BRIDGE. The engine calls System.showOverlay(kind,data) for install progress
	-- (L8133), install-fail (L7746), data-offline (L9998), and the RECORDING anti-spoof banner (L9091), + System.hideOverlay()
	-- (L8264/9026). V2's GUI provided these; V3 was MISSING them -> warm "Redownload All" showed NO progress, and the
	-- recording anti-spoof warning never appeared. Reproduced natively: live progress toast + a persistent recording banner.
	do
		System.showOverlay = function(kind, data)
			data = data or {}
			if kind == "installer" then
				local done, total, failed = tonumber(data.done) or 0, tonumber(data.total) or 0, tonumber(data.failed) or 0
				local pct = (total > 0) and math.floor((done / total) * 100 + 0.5) or 0
				toast("Downloading content", string.format("%d%%   %d / %d files%s", pct, done, total, failed > 0 and ("   (" .. failed .. " failed)") or ""), "info")  -- same title updates in place -> live progress
			elseif kind == "installFail" then
				toast("Content install failed", (data.reason and data.reason ~= "" and tostring(data.reason)) or "Couldn't download content -- try Redownload All, or check your connection.", "err")
			elseif kind == "dataOffline" then
				toast("Data servers unreachable", (data.reason and data.reason ~= "" and tostring(data.reason)) or "Couldn't reach krulhub.dev -- some features may be limited.", "warn")
			elseif kind == "recording" then  -- anti-spoof: prominent, persistent (do NOT auto-dismiss / weaken)
				pcall(function() if _KR._recBanner then _KR._recBanner:Destroy() end end)
				_KR._recBanner = new("ScreenGui", { Name = "RCRecordingWarn", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 99999, Parent = PlayerGui })
				local bn = new("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 10), Size = UDim2.new(0, 440, 0, 46), BackgroundColor3 = Color3.fromRGB(150, 22, 34), BorderSizePixel = 0, Parent = _KR._recBanner }); corner(bn, 10); stroke(bn, Color3.fromRGB(255, 100, 120), 1.5)
				lbl({ Size = UDim2.new(1, -20, 1, 0), Position = UDim2.new(0, 10, 0, 0), Text = (data.text and data.text ~= "" and tostring(data.text)) or "RECORDING DETECTED", TextColor3 = Color3.fromRGB(255, 236, 236), TextSize = 13, Font = FONTB, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Center, Parent = bn })
			end
		end
		System.hideOverlay = function(kind)
			-- The engine calls hideOverlay() no-arg on install-complete (L8293) AND from the recording-stop
			-- path (_dismissVideoOverlay L9055). Key off `kind` so an install finishing WHILE recording can
			-- NEVER tear down the persistent anti-spoof banner (that path passes "recording").
			if kind == "recording" then
				pcall(function() if _KR._recBanner then _KR._recBanner:Destroy(); _KR._recBanner = nil end end)
				return
			end
			pcall(function() local t = _toasts and _toasts["Downloading content"]; if t and t.card and t.card.Parent then toast("Downloading content", "Content ready.", "ok") end end)
		end
	end
	GUIObject.PlayerExecute = new("TextLabel", { Name = "PlayerExecute", BackgroundTransparency = 1, Text = "Self", Parent = screen })
	-- HP-HUD / hidden viewport / mobile-close (engine tween/parent crash-sites) - built with V3's `new`, parented to the stealth container
	GUIObject.hardcoreUI = new("ScreenGui", { Name = "HealthUI", IgnoreGuiInset = true, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Parent = PlayerGui })
	GUIObject.hardcoreGroup = new("CanvasGroup", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.new(0.1, 0, 0.1, 0), GroupTransparency = 1, Visible = false, Parent = GUIObject.hardcoreUI })
	new("UIAspectRatioConstraint", { Parent = GUIObject.hardcoreGroup })
	GUIObject.repairBar = new("ImageLabel", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), BackgroundTransparency = 1, Size = UDim2.new(.5, 0, .5, 0), Image = "rbxassetid://2866648598", ImageTransparency = .2, Visible = false, Parent = GUIObject.hardcoreGroup })
