function RoClothes(Player)
	print("Adults only, Ro-Clothes " .. _RC_VER .. ", Credit to Krul, Wynn, EC, Lerp.")

	-- V4.3.492: SUPPRESSED - `_RoClothesBootSplash` was the V4.3.307 "Ro-Clothes - loading…"
	-- pill at top-center. Replaced by the global `_RC_Brand` bouncing brand overlay defined
	-- at file scope (built at script entry). Kept the wipe of any prior _RoClothesBootSplash
	-- for safe re-execute behavior, but no new splash is created.
	pcall(function()
		local _CG = game:GetService("CoreGui")
		for _, _c in ipairs(_CG:GetChildren()) do
			if _c.Name == "_RoClothesBootSplash" then pcall(function() _c:Destroy() end) end
		end
	end)

	-- V4.3.262+266: rapid-double-click execute → 2 GUIs bug. The prior-breaker kill loop
	-- runs before BREAKER is created, and InstallContentAssets yields on HTTP between
	-- them - if a second execute fires during that yield, it sees no BREAKER, kills
	-- nothing, and both sessions complete setup → 2 GUIs. Singleton flag covers it.
	-- V4.3.266: low-quality executors (Xeno, etc.) lock down `_G` / `getgenv()` such
	-- that any global write errors with "attempt to call a nil value" at script entry.
	-- Wrap the entire singleton machinery in pcall - if globals are restricted, the
	-- singleton silently no-ops and `_isActiveSession` returns true (script always
	-- proceeds, losing only the rapid-double-execute protection on those executors).
	-- Also pcall `tick()` since some executors don't ship it.
	local _isActiveSession = function() return true end
	do
		local okSetup, _genv, _mySession = pcall(function()
			local _g = (getgenv and getgenv()) or _G
			local _t = (tick and tick()) or os.clock()
			local _id = string.format("%d_%.6f", math.random(0, 2^31 - 1), _t)
			_g._rcSessionId = _id  -- may error on restricted env; pcall catches it
			return _g, _id
		end)
		if okSetup and _genv and _mySession then
			_isActiveSession = function() return _genv._rcSessionId == _mySession end
		end
	end

	-- Setup Tables
	local Maid = {}
	local Function = {Spring = {}}
	-- V4.3.506: wire telemetry public entry points onto the Function table so
	-- the ~30 wire sites in §5 can call Function.diag / Function.diagOnce.
	-- The implementations live at file scope (no RoClothes-outer-register cost).
	Function.diag = _diagPublicCall
	Function.diagOnce = _diagPublicCallOnce
	Function.diagFlush = function() pcall(_diagFlush) end
	Function.diagSnapshot = function()
		-- Returns a shallow copy of the ring for Phase 3 "View Pending" UI.
		local out = {}
		for i = 1, _DIAG_RING_COUNT do
			local idx
			if _DIAG_RING_COUNT < _DIAG_RING_CAP then
				idx = i
			else
				idx = ((_DIAG_RING_HEAD + i - 2) % _DIAG_RING_CAP) + 1
			end
			out[#out + 1] = _DIAG_RING[idx]
		end
		return out
	end
	-- V4.3.507: Phase 3 - upload-queue inspectors and force-flush.
	-- Snapshot of the upload queue (what would be sent on next batch).
	-- V4.3.508: cap snapshot at 50 (matches upload batch size). Prevents the
	-- View Pending dialog from returning the full 256-cap ring.
	-- V4.3.518 Fix 1: strip internal _seq tag from public snapshot output.
	Function.diagUploadSnapshot = function()
		local raw = _diagUpPeek(50)
		local out = {}
		for i, e in ipairs(raw) do
			if type(e) == "table" then
				local c = {}
				for k, v in pairs(e) do if k ~= "_seq" then c[k] = v end end
				out[i] = c
			else
				out[i] = e
			end
		end
		return out
	end
	Function.diagUploadCount = function() return _DIAG_UP_RING_COUNT end
	-- Force an upload attempt now (used by "Send Now" button).
	Function.diagUploadNow = function() return _diagUpFlushNow() end
	-- Discard the entire upload queue (used by opt-out - events captured pre-opt-out
	-- should not be ambiently sent after the user changes their mind).
	Function.diagUploadClear = function()
		_DIAG_UP_RING = {}
		_DIAG_UP_RING_COUNT = 0
		_DIAG_UP_RING_HEAD = 1
		_DIAG_UP_RETRY_COUNT = 0
		_DIAG_UP_NETWORK_DEAD = false  -- V4.3.508: opt-out → opt-in should clear dead-path
		-- V4.3.513 Fix 10: clear heal-once flag so a re-opt-in re-verifies disk state.
		-- (User may have deleted Settings.json externally while opted-out; re-opt-in
		-- must heal it, not assume the prior session's disk-verified is still valid.)
		_DIAG_INSTALL_ID_DISK_VERIFIED = false
	end
	-- GUI TEARDOWN: GUIObject is a no-op proxy. The GUI layer was removed but the
	-- engine still reads/writes/method-calls GUIObject.* in ~179 places (HP HUD,
	-- keybinds, mobile buttons, CharacterReset, MeshEditButton, CatalogAccessoryFrameAdd,
	-- CharacterPreview, RunInitialization). The proxy absorbs .X / .X=v / :Method() at any
	-- depth so none of them crash. (A dummy passed INTO a real Roblox API e.g.
	-- TweenService:Create still throws - see the ~10 flagged HP-tween / censor sites.)
	local _RC_GUI_DUMMY = setmetatable({}, {
		__index = function(self) return self end,
		__newindex = function() end,
		__call = function(self) return self end,
	})
	local GUIObject = setmetatable({}, {
		-- MERGE: store real assignments (GUIObject.X = realInstance). Reads return the stored
		-- real instance if present, else the no-op dummy (so engine refs to un-provided members
		-- still absorb harmlessly). Before this, __newindex swallowed every assignment, so the
		-- merged GUI's GUIObject.Screen/MainFrame/hardcoreUI/etc. never took effect.
		__index = function(t, k) local v = rawget(t, k); if v ~= nil then return v else return _RC_GUI_DUMMY end end,
		__newindex = function(t, k, v) rawset(t, k, v) end,
	})
	local PlayerData = {}
	local AllConnect = {}
	local GizmoSliderRefreshers = {}

	-- V4.3.98: gimbal - ANIMATIONS ON/OFF button suppresses passive animations, movement unchanged. (see Changelog for full rationale)
	-- V4.3.168.16: collapsed 11 gimbal_* locals into a single `Gimbal` table. Was
	local Gimbal = {
		selBox       = nil,
		adornPart    = nil,
		handles      = {},   -- tips, dots, AND shafts (all handle Parts)
		handleData   = {},   -- [Part]={...} for tips/dots, {isShaft=true} for shafts
		                      -- ["__mode"]="pos"|"rot", ["__apply"]=fn
		dragging     = false,
		activeHandle = nil,
		dragLastX    = 0,
		dragLastY    = 0,
		mouse        = nil,
		inputConns   = {},   -- Button1Down, Move, InputEnded; disconnected in destroyGimbal
		cachedTarget = nil,  -- cached GizmoTarget name; skip mesh scan when unchanged
	}
	Gimbal.handleData["__mode"] = "pos"  -- persists across target changes
	-- C1 is absorbed into C0 write formula (accessory size loop); no __weld needed
	local function destroyGimbal()
		if Gimbal.selBox then pcall(function() Gimbal.selBox:Destroy() end); Gimbal.selBox = nil end
		for _, hp in ipairs(Gimbal.handles) do pcall(function() hp:Destroy() end) end
		Gimbal.handles    = {}
		local savedMode  = Gimbal.handleData["__mode"] or "pos"
		Gimbal.handleData = {}
		Gimbal.handleData["__mode"] = savedMode  -- keep mode choice across target changes
		Gimbal.adornPart    = nil
		Gimbal.dragging     = false
		Gimbal.activeHandle = nil
		-- Disconnect accumulated mouse/UIS connections from previous target
		for _, c in ipairs(Gimbal.inputConns) do pcall(function() c:Disconnect() end) end
		table.clear(Gimbal.inputConns)
		Gimbal.cachedTarget = nil
		-- V4.3.460: clear V4.3.460-H3 short-circuit cache so Vector3 userdata isn't pinned across teardowns
		Gimbal._lastP = nil
		Gimbal._lastL = nil
	end

	-- C-3 fix: PositionPhysicsMultiply and Method were previously declared here (= 1 each)
	-- and then re-declared later with their real values (Method=2, PositionPhysicsMultiply=1).
	-- The early declarations shadowed nothing meaningful but Method=1 was wrong for any code
	-- that executed between here and the real declaration. Removed; authoritative declarations
	-- remain at their proper location below (lines ~1082 and ~1113).
	-- V4.3.433: RotationPhysicsMultiply hoisted to file scope to free 1 register slot.
	local SelectPlayer = PS.LocalPlayer.Name
	local CharacterPreviewLoading = false
	-- H-4/L-1 fix: declare loadup* as explicit locals so they are upvalues, not implicit globals.
	-- Without local declarations, first write at line ~16731 goes to getgenv() (global environment),
	-- colliding across re-executions and leaking to other scripts via getgenv().
	local loadupBreastsStiffness
	local loadupBreastsDamping
	local loadupButtsStiffness
	local loadupButtsDamping

	Maid.__index = Maid
	function Maid.new() return setmetatable({Tasks = {}}, Maid) end
	function Maid:Give(task)
		local id = HS:GenerateGUID(false)
		self.Tasks[id] = task
		return task, id
	end
	function Maid:Remove(idOrTask)
		-- V4.3.514: pre-extract target before running the task. A task function
		-- that itself calls Maid:Remove for OTHER ids would mutate self.Tasks
		-- mid-iteration of an outer pairs() loop. Find, remove from table, THEN run.
		local target_id, target_task
		for id, task in pairs(self.Tasks) do
			if id == idOrTask or task == idOrTask then
				target_id, target_task = id, task
				break
			end
		end
		if target_id then
			self.Tasks[target_id] = nil
			if typeof(target_task) == "RBXScriptConnection" then
				target_task:Disconnect()
			elseif typeof(target_task) == "Instance" then
				target_task:Destroy()
			elseif typeof(target_task) == "function" then
				target_task()
			elseif typeof(target_task) == "table" and target_task.Destroy then
				target_task:Destroy()
			end
		end
	end
	function Maid:DoCleaning()
		for id, task in pairs(self.Tasks) do
			pcall(function()  -- V4.3.567 H-13: per-task guard; pre-fix one throwing task aborted the whole for-loop, leaving the rest of teardown un-run (ghost GUI / un-reset body)
				if typeof(task) == "RBXScriptConnection" then
					task:Disconnect()
				elseif typeof(task) == "Instance" then
					task:Destroy()
				elseif typeof(task) == "function" then
					task()
				elseif typeof(task) == "table" and task.Destroy then
					task:Destroy()
				elseif typeof(task) == "table" and task.Disconnect then
					task:Disconnect()
				end
			end)
			self.Tasks[id] = nil
		end
	end

	-- V4.3.574 ROOT-CAUSE FIX - settings never persisted on Volt-class executors.
	-- System.Env was getgenv() alone, but on many executors the file/HTTP functions
	-- (readfile/writefile/isfile/makefolder/... + http_request/request) live in the SCRIPT
	-- environment as DIRECT globals and are NOT mirrored into getgenv(), so System.Env.writefile
	-- etc. were nil. _atomicWriteJSON captures env from `local env = System.Env` (~L5470, the
	-- nearest one BEFORE the writer is defined; the curated direct-global env at ~L7721 comes
	-- AFTER it and does not apply), so every canonical Settings.json write was pcall(nil, ...)
	-- -> failed -> swallowed -> nothing ever saved (keybinds, bundles, toggles, telemetry). A
	-- manual writefile test worked because that hits the DIRECT global, which is exactly why
	-- this hid for so long. Fix: prefer the direct script-env global for each known executor
	-- function, with getgenv() as the __index fallback. System.Env is read-only here (no field
	-- is ever assigned), so the metatable wrapper is safe.
	local System
	do
		local _g = (getgenv and getgenv()) or _G or {}
		local _env = setmetatable({}, { __index = _g })
		local function _pref(name, fn) if type(fn) == "function" then _env[name] = fn end end
		_pref("readfile", readfile);             _pref("writefile", writefile)
		_pref("appendfile", appendfile);         _pref("isfile", isfile)
		_pref("isfolder", isfolder);             _pref("makefolder", makefolder)
		_pref("delfile", delfile);               _pref("delfolder", delfolder)
		_pref("listfiles", listfiles);           _pref("loadfile", loadfile)
		_pref("getcustomasset", getcustomasset); _pref("getsynasset", getsynasset)
		_pref("http_request", http_request);     _pref("request", request)
		_pref("getfilesize", getfilesize);       _pref("setclipboard", setclipboard)
		System = {
			Env = _env,
			GlobalMaid = Maid.new()
		}
	end

	do
		-- V4.3.167.6: Per-session randomized identifiers to dodge Anti-Dex / scanner
		-- detection. Replaces previously hardcoded literals "RoClothes" (CollectionService
		-- tag, ScreenGui name), "RoClothesBreaker" (workspace Folder), and
		-- "Method2CharacterFolder" (workspace Folder). Each session generates fresh
		-- 8-hex-char names so static-string scanners can't fingerprint the script.
		do
			local _r = Random.new(os.clock() * 1e6 + (((tick and tick()) or os.clock()) * 1000))  -- V4.3.355: tick() fallback so init doesn't crash on Xeno-class executors
			local function _rand8() return string.format("%08x", _r:NextInteger(0, 0x7FFFFFFF)) end
			System.RCTag       = "rc_"   .. _rand8()  -- CollectionService tag
			System.M2FName     = "__m2f_" .. _rand8()  -- Method2CharacterFolder Name
			System.ScreenName  = "ui_"   .. _rand8()  -- top-level ScreenGui Name
			System.BreakerName = "__rcb_" .. _rand8()  -- BREAKER Folder Name
		end

		-- V4.3.168: Avatar Sync state. Default OFF. See Wiki/tools/avatar_sync_script_plan.md.
		-- Publishes own bundle to krulhub.dev on apply; polls /avatar/server every 5s for
		-- in-server peers and renders their bundles via the existing Method 2 pipeline.
		System.AvatarSync = {
			enabled           = false,
			lastPublishedHash = nil,
			forceClear        = false,       -- sticky explicit reset until the next real local edit
			pollCursor        = nil,
			debounceHandle    = nil,
			pollHandle        = nil,
			heartbeatHandle   = nil,         -- V4.3.168.19: 60s re-publish to keep server TTL alive
			syncedPeers       = {},          -- V4.3.173: [userId] = { dataKey, lastUpdatedMs, bundleData, tweaks, characterAddedConn, applied }
			placeId           = game.PlaceId,
			jobId             = game.JobId,
			-- V4.3.168.5: surface publish/poll failures in the toggle label so users
			-- aren't left wondering why peers don't see them. Set by the publish + poll
			-- helpers; cleared on next successful round-trip.
			lastError         = nil,         -- string | nil (e.g. "publish 429", "no http")
			lastErrorAt       = 0,           -- tick() when lastError was set
			lastSeenCount     = 0,           -- V4.3.168.21: peers reported by last poll response (for "X/Y peers rendered" diagnostic)
			-- V4.3.174: gates publish on a USER-INITIATED change since the most recent toggle-ON. (see Changelog for full rationale)
			userActed         = false,
		}

		System.NPCs = {}
		System.tailVariables = {}
		System.tailVariables.Default = {
			tailScaledAnimationTime = 0,
			tailScaledTime = 0,
			accumulator = 0,
			stiffness = 96,
			damping = 9,
			linearAmplitude = Vector3.new(13, 8, 13),
			angularAmplitude = Vector3.new(0, 25, 0),
			timeScale = 1,
			wagAnimationEnabled = true,
			wagAnimationSpeed = 1
		}
		System.BundleButtons = {}
		System.ClothesButtons = {}
		System.RecolorButtons = {}

		System.RigMap = {
			["Head"] = {"Head"},
			["Torso"] = {"UpperTorso", "LowerTorso"},
			["Right Arm"] = {"RightUpperArm", "RightLowerArm", "RightHand"},
			["Left Arm"] = {"LeftUpperArm", "LeftLowerArm", "LeftHand"},
			["Right Leg"] = {"RightUpperLeg", "RightLowerLeg", "RightFoot"},
			["Left Leg"] = {"LeftUpperLeg", "LeftLowerLeg", "LeftFoot"}
		}
		-- V4.3.460: precomputed inverse map for direct R15-part-name → R6-part-name
		-- lookup. Replaces the per-frame-per-accessory walk at L16574 that iterated
		-- all 6 RigMap entries × table.find per entry. One hash lookup vs 6×N.
		System.R15ToR6Name = {
			Head            = "Head",
			UpperTorso      = "Torso",     LowerTorso     = "Torso",
			RightUpperArm   = "Right Arm", RightLowerArm  = "Right Arm", RightHand = "Right Arm",
			LeftUpperArm    = "Left Arm",  LeftLowerArm   = "Left Arm",  LeftHand  = "Left Arm",
			RightUpperLeg   = "Right Leg", RightLowerLeg  = "Right Leg", RightFoot = "Right Leg",
			LeftUpperLeg    = "Left Leg",  LeftLowerLeg   = "Left Leg",  LeftFoot  = "Left Leg",
		}
		
		System.BodyPartSize = {
			["Head"] = Vector3.new(2, 1, 1),
			["HeadScale"] = Vector3.new(1, 1, 1),
			["HeadMeshFix"] = Vector3.new(1.198, 1.202, 1.198),
			["Torso"] = Vector3.new(2, 2, 1),
			["Left Arm"] = Vector3.new(1, 2, 1),
			["Left Leg"] = Vector3.new(1, 2, 1),
			["Right Arm"] = Vector3.new(1, 2, 1),
			["Right Leg"] = Vector3.new(1, 2, 1),
			["HumanoidRootPart"] = Vector3.new(2, 2, 1),
		}

		System.AttachmentCFrame = {
			["RootAttachment"] = CFrame.new(0,0,0),

			["FaceCenterAttachment"] = CFrame.new(0,0,0),
			["FaceFrontAttachment"] = CFrame.new(0, 0, -0.6),
			["HairAttachment"] = CFrame.new(0,0.6,0),
			["HatAttachment"] = CFrame.new(0,0.6,0),

			["LeftGripAttachment"] = CFrame.new(0, -1, 0),
			["LeftShoulderAttachment"] = CFrame.new(0,1,0),

			["LeftFootAttachment"] = CFrame.new(0, -1, 0),

			["RightGripAttachment"] = CFrame.new(0, -1, 0),
			["RightShoulderAttachment"] = CFrame.new(0,1,0),

			["RightFootAttachment"] = CFrame.new(0, -1, 0),

			["BodyBackAttachment"] = CFrame.new(0, 0, 0.5),
			["BodyFrontAttachment"] = CFrame.new(0, 0, -0.5),
			["LeftCollarAttachment"] = CFrame.new(-1, 1, 0),
