	function Function.GetRigType(Character)
		if Character:FindFirstChild("UpperTorso") then return "R15" end
		return "R6"
	end

	function Function.CharacterIsBuilt(Character)
		if not Character or not Character.Parent then return false end
		local Humanoid = Character:FindFirstChildOfClass("Humanoid")
		local Root = Character:FindFirstChild("HumanoidRootPart")
		if not Humanoid or not Root or not Character:IsDescendantOf(workspace) then
			return false
		end
		-- V4.3.168.10: wait for rig-appropriate body parts before declaring the character (see Changelog for full rationale)
		-- V4.3.168.18: upgraded the check from upper-segments-only to ALL body parts. User
		if not Character:FindFirstChild("Head") then return false end
		if Humanoid.RigType == Enum.HumanoidRigType.R15 then
			if not Character:FindFirstChild("UpperTorso")    then return false end
			if not Character:FindFirstChild("LowerTorso")    then return false end
			if not Character:FindFirstChild("LeftUpperArm")  then return false end
			if not Character:FindFirstChild("LeftLowerArm")  then return false end
			if not Character:FindFirstChild("LeftHand")      then return false end
			if not Character:FindFirstChild("RightUpperArm") then return false end
			if not Character:FindFirstChild("RightLowerArm") then return false end
			if not Character:FindFirstChild("RightHand")     then return false end
			if not Character:FindFirstChild("LeftUpperLeg")  then return false end
			if not Character:FindFirstChild("LeftLowerLeg")  then return false end
			if not Character:FindFirstChild("LeftFoot")      then return false end
			if not Character:FindFirstChild("RightUpperLeg") then return false end
			if not Character:FindFirstChild("RightLowerLeg") then return false end
			if not Character:FindFirstChild("RightFoot")     then return false end
		else  -- R6
			if not Character:FindFirstChild("Torso")     then return false end
			if not Character:FindFirstChild("Left Arm")  then return false end
			if not Character:FindFirstChild("Right Arm") then return false end
			if not Character:FindFirstChild("Left Leg")  then return false end
			if not Character:FindFirstChild("Right Leg") then return false end
		end
		return true
	end

	local env = System.Env

	-- V4.3.504: hoisted from saveButton closure (was L23735 only). Lifting it here
	-- lets the catalog/dead-id/bundle/VNS JSON writers route through the same
	-- write-tmp → readback-verify → write-canonical pipeline so a botched
	-- JSONEncode can't shred a healthy on-disk file.
	-- Fix 5: tmp path is salted (clock + rand) so concurrent writes from
	-- independent callers don't share a tmp slot.
	-- V4.3.533 MED Fix 5 + V4.3.534 F1: replaced global `math.random(1, 1e9)` with an
	-- isolated Random.new() instance + monotonic counter. `math.random` mutates Luau's
	-- shared global PRNG state. _atomicWriteJSON is on the hot path (12 call sites:
	-- Settings save, BundleLoader updates, CatalogAssetTypeCache, KnownDeadIds,
	-- telemetry persist) and was silently advancing the global PRNG between every save.
	-- Downstream math.random consumers (intro frame jitter, sound-id picker, NPC ids)
	-- were becoming deterministic-by-save-pattern. Mirrors V4.3.531 Fix 10.
	--
	-- V4.3.534 F1: V4.3.533 placed `_atomicWriteRng` + `_atomicWriteCounter` at single-
	-- tab indent inside RoClothes() - these became permanent outer-scope register slots,
	-- contributing to the 200-cap pressure that has triggered 7 prior same-version
	-- register-cap hotfixes (V4.3.522/523/523/526/531×3). Wrapped the helper definition
	-- in a `do ... end` block so the RNG + counter are CLOSURE UPVALUES on _atomicWriteJSON
	-- rather than RoClothes-scope locals. Net: 3 outer-scope slots → 1 (just the function
	-- name itself, which is unavoidable since 39 call sites in RoClothes need it).
	local _atomicWriteJSON
	do
		local _atomicWriteRng
		local _atomicWriteCounter = 0
		function _atomicWriteJSON(canonicalPath, tbl)
			_atomicWriteRng = _atomicWriteRng or Random.new()
			_atomicWriteCounter = _atomicWriteCounter + 1
			local tmpPath = canonicalPath .. ".tmp." .. tostring(os.clock()) .. "_"
				.. tostring(_atomicWriteRng:NextInteger(1, 1e9)) .. "_" .. tostring(_atomicWriteCounter)
		local _okEnc, _encoded = pcall(function() return HS:JSONEncode(tbl) end)
		if not _okEnc or type(_encoded) ~= "string" then
			warn("[RoClothes] atomic write: encode failed for " .. canonicalPath)
			Function.diag("atomic_write.fail", { path = tostring(canonicalPath):sub(1, 128), stage = "encode" })
			if env.delfile then
				local _okDel = pcall(env.delfile, tmpPath)
				if not _okDel then Function.diag("atomic_write.tmp_orphan", { path = tostring(tmpPath):sub(1, 128) }) end
			end
			return false
		end
		local _okW = pcall(env.writefile, tmpPath, _encoded)
		if not _okW then
			warn("[RoClothes] atomic write: tmp write failed for " .. canonicalPath)
			Function.diag("atomic_write.fail", { path = tostring(canonicalPath):sub(1, 128), stage = "tmp" })
			if env.delfile then pcall(env.delfile, tmpPath) end
			return false
		end
		local _okR2, _back = pcall(env.readfile, tmpPath)
		if not _okR2 or type(_back) ~= "string" then
			warn("[RoClothes] atomic write: readback failed for " .. canonicalPath .. " - canonical preserved")
			Function.diag("atomic_write.fail", { path = tostring(canonicalPath):sub(1, 128), stage = "readback" })
			if env.delfile then pcall(env.delfile, tmpPath) end
			return false
		end
		local _okD2 = pcall(HS.JSONDecode, HS, _back)
		if not _okD2 then
			warn("[RoClothes] atomic write: readback parse failed for " .. canonicalPath .. " - canonical preserved")
			Function.diag("atomic_write.fail", { path = tostring(canonicalPath):sub(1, 128), stage = "parse" })
			if env.delfile then pcall(env.delfile, tmpPath) end
			return false
		end
		local _okC = pcall(env.writefile, canonicalPath, _encoded)
		if not _okC then
			warn("[Ro-Clothes] _atomicWriteJSON: canonical write failed for " .. tostring(canonicalPath))
			Function.diag("atomic_write.fail", { path = tostring(canonicalPath):sub(1, 128), stage = "canonical" })
		end
		if env.delfile then pcall(env.delfile, tmpPath) end
		return _okC
	end
	end -- V4.3.534 F1: close do-block that scopes _atomicWriteRng + _atomicWriteCounter as closure upvalues

	-- V4.3.521 Fix 9: listfiles path-format compat (Aki's Solara bundle bug).
	-- Some executors return leaf-only names ("MyBundle.json"), others return
	-- "RClothesLerp/Bundles/MyBundle.json", others backslash-separated. Try the path
	-- as-returned first, then with backslash→forward-slash, then prepended with
	-- the folder if it's a bare basename.
	local function _normalizeBundlePath(p)
		if type(p) ~= "string" then return nil end
		if env.isfile and env.isfile(p) then return p end
		local _fwd = p:gsub("\\", "/")
		if _fwd ~= p and env.isfile and env.isfile(_fwd) then return _fwd end
		if not p:find("/") and not p:find("\\") then
			local _prefixed = "RClothesLerp/Bundles/" .. p
			if env.isfile and env.isfile(_prefixed) then return _prefixed end
		end
		return nil
	end

	-- V4.3.278: memoize resolved asset URLs. Pre-fix, GetAsset was called inside (see Changelog for full rationale)
	-- V4.3.300: cap entries at 1000 to prevent unbounded growth across long sessions
	local _gcaMemo = {}
	local _gcaMemoCount = 0
	-- V4.3.433: _GCA_MEMO_MAX hoisted to file scope (above RoClothes) to free 1 register slot.
	function Function.GetAsset(Path)
		-- V4.3.214: nil/empty guard - Path:gsub crashes on nil. Some PartListDefault
		-- entries have no TextureId/MeshId; let the caller pass nil safely.
		-- V4.5.24 Fix: also require a string. A non-string non-nil Path passed the old guard
		-- (`not Path or Path == ""`), then crashed on Path:gsub at the local-path step
		-- below - exactly the class V4.3.552 patched for _safeRewrite without closing here.
		if type(Path) ~= "string" or Path == "" then return Path end
		-- V4.5.6 EXECUTOR-SUPPORT: remote/catalog asset URLs (rbxassetid://, http(s)://, rbxthumb://)
		-- are NEVER local files. Some executors (Solara) THROW ":7818/:7455 BLOCKED file path" from
		-- isfile/getcustomasset when handed such a path - and the isfile probe below was UNGUARDED, so
		-- that throw escaped GetAsset -> ApplyAssets -> HumanoidDescriptionLoader SKIPPED the accessory,
		-- i.e. CATALOG ACCESSORIES NEVER EQUIPPED on those executors (on-device Solara repro 2026-07-18).
		-- These load directly as MeshId/TextureId with no getcustomasset (verified on-device), so return
		-- as-is. (rbxasset:// LOCAL vns paths still fall through - they get stripped to a local path first.)
		if type(Path) == "string" then
			local _pfx = Path:sub(1, 13)
			if _pfx == "rbxassetid://" or Path:sub(1, 7) == "http://" or Path:sub(1, 8) == "https://" or Path:sub(1, 11) == "rbxthumb://" then  -- BUGFIX: "rbxthumb://" is 11 chars, not 10 - sub(1,10) never matched, so rbxthumb thumbnails fell through to the local-file path (:7818 BLOCKED throw on Solara)
				return Path
			end
		end
		local cached = _gcaMemo[Path]
		if cached ~= nil then return cached end
		-- V4.3.300: hard reset on cap to prevent slow leak.
		if _gcaMemoCount >= _GCA_MEMO_MAX then
			_gcaMemo = {}
			_gcaMemoCount = 0
		end
		local RelativePath = (Path:gsub("rbxasset://", ""))
		local gca = getcustomasset or getsynasset
		if System.isfile and gca then
			-- V4.3.555: CapSec executors (Xeno class) have basename-keyed
			-- getcustomasset cache - arm/leg/butt left.mesh/right.mesh all
			-- collide at `rbxasset://{UUID}/left.mesh`. The install pipeline
			-- writes a unique-basename mirror copy to RClothesContent/_vns_uniq/
			-- so we can call getcustomasset on the unique path and get a
			-- collision-free URL. ONLY fires for VNS asset lookups on CapSec
			-- executors - non-CapSec uses the V4.3.218 path-as-is flow below.
			if System._vnsCapsecMeshIdLocked then
				local _vnsRel
				if RelativePath:sub(1, 5) == "_vns/" then
					-- Came in as `rbxasset://_vns/...` → vns-rooted path
					_vnsRel = "RClothesContent/" .. RelativePath
				elseif RelativePath:sub(1, 21) == "RClothesContent/_vns/" then
					-- Came in as `rbxasset://RClothesContent/_vns/...` → already prefixed
					_vnsRel = RelativePath
				end
				if _vnsRel then
					local _flat = _vnsRel:gsub("[/\\]", "_")
					local _uniq = "RClothesContent/_vns_uniq/" .. _flat
					if System.isfile(_uniq) then
						local ok, url = pcall(gca, _uniq)
						if ok and type(url) == "string" and #url > 0 then
							_gcaMemo[Path] = url; _gcaMemoCount = _gcaMemoCount + 1
							return url
						end
					end
				end
			end
			-- 1. Try the path as-is (workspace-rooted: "RClothesContent/...", "_vns/...")
			if System.isfile(RelativePath) then
				local ok, url = pcall(gca, RelativePath)
				if ok and type(url) == "string" and #url > 0 then
					_gcaMemo[Path] = url; _gcaMemoCount = _gcaMemoCount + 1
					return url
				end
			end
			-- 2. V4.3.218: try with "RClothesContent/" prefix. VNS rbxm files reference
			--    `rbxasset://_vns/...` (relative to Roblox content folder root) but we
			--    install them at `<workspace>/RClothesContent/_vns/...` via the
			--    auto-installer. This fallback bridges the two.
			if RelativePath:sub(1, 16) ~= "RClothesContent/" then
				local prefixed = "RClothesContent/" .. RelativePath
				if System.isfile(prefixed) then
					local ok, url = pcall(gca, prefixed)
					if ok and type(url) == "string" and #url > 0 then
						_gcaMemo[Path] = url; _gcaMemoCount = _gcaMemoCount + 1
						return url
					end
				end
			end
		end
		-- Fallback: return the original path (handles rbxassetid:// Roblox assets,
		-- or relies on the active Roblox version's content folder having the file).
		-- V4.3.465: DO NOT CACHE the fallback. Pre-fix this cached the unresolved
		-- URL - if GetAsset was called BEFORE InstallContentAssets completed (very
		-- common: script boot triggers character respawn → RigVnsModel walks the
		-- rbxm → GetAsset fires for each baked-in `rbxasset://_vns/...` URL while
		-- install workers were still mid-fetch → isfile() returned false → fallback
		-- cached), subsequent calls returned the cached unresolved URL even after
		-- the files landed on disk. MeshContentProvider then failed to fetch them.
		-- User-reported "BreastsType 6 breast doesnt load" (2026-05-17, screenshot
		-- 2026-05-18 confirmed V4.3.464 still affected) pointed here once V4.3.464's
		-- hardening warns ruled out the dispatch-side paths. Redownload writes files
		-- but doesn't clear this in-process memo so the user was stuck.
		-- Only cache SUCCESSFUL resolutions; nil-result paths get re-evaluated each call.
		-- Cost: one extra pair of isfile probes per nil-result path per call - negligible
		-- vs the alternative of leaving the user with a broken Type 6 across the session.
		-- For rbxassetid:// Roblox-catalog URLs that legitimately have no local file,
		-- the early `Path == ""` short-circuit + the Roblox engine's own cache absorb
		-- the cost.
		return Path
	end

	-- V4.3.309: MeshPart cache. CreateMeshPartAsync yields each call (~50-200ms on (see Changelog for full rationale)
	local _mpCache       = {}      -- [cacheKey] = parented MeshPart (template)
	local _mpCacheOrder  = {}      -- FIFO: oldest key first
	-- V4.3.433: _MP_CACHE_MAX hoisted to file scope (above RoClothes) to free 1 register slot.
	function Function.CachedCreateMeshPartAsync(meshId, collisionFidelity, renderFidelity)
		collisionFidelity = collisionFidelity or Enum.CollisionFidelity.Box
		renderFidelity    = renderFidelity    or Enum.RenderFidelity.Performance
		if type(meshId) ~= "string" or meshId == "" or System._sessionAlive == false then return nil end
		local key = meshId .. "|" .. tostring(collisionFidelity.Value) .. "|" .. tostring(renderFidelity.Value)
		local cached = _mpCache[key]
		if cached and cached.Parent then
			return cached:Clone()
		end
		-- Some executors hang on local mesh creation. Preserve their SpecialMesh
		-- fallback while allowing built-in and catalog assets to use the engine API.
		local _isRealAsset = (meshId:match("^rbxassetid://") ~= nil) or (meshId:match("^rbxasset://fonts") ~= nil)
		if Function._cmpaBroken and not _isRealAsset then return nil end
		-- One creator owns each cold key. Keep an abandoned request registered until
		-- its native call returns, so retries cannot accumulate hung jobs for that key.
		Function._mpPending = Function._mpPending or {}
		local pending = Function._mpPending[key]
		if not pending and (Function._mpActive or 0) >= 16 then
			-- Bound distinct native creates as well as duplicate keys. Waiting callers
			-- own no pending entry; native slots remain held through late completion.
			local queuedAt = os.clock()
			while (Function._mpActive or 0) >= 16 and not Function._mpPending[key]
				and System._sessionAlive ~= false and os.clock() - queuedAt < 6 do task.wait() end
			if System._sessionAlive == false then return nil end
			pending = Function._mpPending[key]
			cached = _mpCache[key]
			if cached and cached.Parent then return cached:Clone() end
			if not pending and (Function._mpActive or 0) >= 16 then return nil end
		end
		if not pending then
			pending = { started = os.clock(), done = false }
			Function._mpPending[key] = pending
			Function._mpActive = (Function._mpActive or 0) + 1
			task.spawn(function()
				local ok, mp = pcall(function()
					return game:GetService("InsertService"):CreateMeshPartAsync(meshId, collisionFidelity, renderFidelity)
				end)
				Function._mpActive = Function._mpActive - 1
				if ok and mp then
					if pending.abandoned or System._sessionAlive == false then
						pcall(function() mp:Destroy() end)
					else
						local stored = pcall(function()
							local storage = game:GetService("ReplicatedStorage")
							local holder = storage:FindFirstChild("_RCMpCache")
							if not holder then
								holder = Instance.new("Folder"); holder.Name = "_RCMpCache"; holder.Parent = storage
							end
							mp.Name = "tpl_" .. (mp.Name or "MeshPart")
							mp.Parent = holder
							_mpCache[key] = mp
							local staleIndex = table.find(_mpCacheOrder, key)
							if staleIndex then table.remove(_mpCacheOrder, staleIndex) end
							table.insert(_mpCacheOrder, key)
							while #_mpCacheOrder > _MP_CACHE_MAX do
								local oldKey = table.remove(_mpCacheOrder, 1)
								local old = _mpCache[oldKey]
								if old then pcall(function() old:Destroy() end) end
								_mpCache[oldKey] = nil
							end
							pending.template = mp
						end)
						if not stored then pcall(function() mp:Destroy() end) end
					end
				end
				pending.done = true
				if Function._mpPending[key] == pending then Function._mpPending[key] = nil end
			end)
		end
		while not pending.done and not pending.abandoned and System._sessionAlive ~= false
			and os.clock() - pending.started < 6 do task.wait() end
		if not pending.done then
			pending.abandoned = true
			if System._sessionAlive ~= false then
				if not _isRealAsset then Function._cmpaBroken = true end
				if Function.diagOnce then pcall(Function.diagOnce, "cmpa_hang_specialmesh_fallback") end
			end
			return nil
		end
		if pending.template and pending.template.Parent and System._sessionAlive ~= false then
			return pending.template:Clone()
		end
		return nil
	end

	function Function.RequestHeadMeshSize(DataList, meshId)
		local parts = DataList.CurrentPartList
		if not parts or System._sessionAlive == false then return end
		if parts.TrueMeshSize and parts.TrueMeshSize.MeshId == meshId then return end
		if parts.TrueMeshSizePending == meshId then return end
		local failed = parts.TrueMeshSizeFailure
		if failed and failed.MeshId == meshId and failed.Generation == System._meshContentGeneration
			and os.clock() < failed.RetryAt then return end
		local request = {}
		parts.TrueMeshSizeRequest = request
		parts.TrueMeshSizePending = meshId
		task.spawn(function()
			local ok, part = pcall(Function.CachedCreateMeshPartAsync, meshId,
				Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
			if not ok then part = nil end
			if DataList.CurrentPartList ~= parts or parts.TrueMeshSizeRequest ~= request
				or System._sessionAlive == false then
				if part then pcall(function() part:Destroy() end) end
				return
			end
			parts.TrueMeshSizePending = nil
			parts.TrueMeshSizeRequest = nil
			if part then
				local previous = parts.TrueMeshSize
				if previous and previous.Part then pcall(function() previous.Part:Destroy() end) end
				parts.TrueMeshSize = { Part = part, MeshId = meshId }
				parts.TrueMeshSizeFailure = nil
			else
				parts.TrueMeshSizeFailure = { MeshId = meshId, RetryAt = os.clock() + 3,
					Generation = System._meshContentGeneration }
			end
		end)
	end

