			local _msc = Instance.new("UIScale", f)  -- auto-fit for narrow / mobile screens
			local function _fitB() local _cam = workspace.CurrentCamera; local _vw = (_cam and _cam.ViewportSize.X) or 800; _msc.Scale = math.min(1, (_vw - 24) / 560) end
			_fitB(); pcall(function()
