			end)
			local _ic = Instance.new("Frame", f); _ic.Position = UDim2.fromOffset(14, 14); _ic.Size = UDim2.fromOffset(36, 36); _ic.BackgroundColor3 = _WARN; _ic.BackgroundTransparency = 0.14; _ic.BorderSizePixel = 0
			Instance.new("UICorner", _ic).CornerRadius = UDim.new(0, 10)
			local _icx = Instance.new("TextLabel", _ic); _icx.Size = UDim2.fromScale(1, 1); _icx.BackgroundTransparency = 1; _icx.Font = Enum.Font.GothamBold; _icx.Text = "!"; _icx.TextColor3 = Color3.new(1, 1, 1); _icx.TextSize = 22; _icx.TextXAlignment = Enum.TextXAlignment.Center
			local _tl = Instance.new("TextLabel", f); _tl.Position = UDim2.fromOffset(62, 12); _tl.Size = UDim2.new(1, -76, 0, 20); _tl.BackgroundTransparency = 1; _tl.Font = Enum.Font.GothamBold; _tl.TextSize = 14; _tl.TextColor3 = _TXT; _tl.Text = "Mesh loading issue on your executor"; _tl.TextXAlignment = Enum.TextXAlignment.Left
			local lbl = Instance.new("TextLabel", f)
			lbl.Position = UDim2.fromOffset(62, 34); lbl.Size = UDim2.new(1, -76, 0, 46); lbl.BackgroundTransparency = 1; lbl.Font = Enum.Font.Gotham; lbl.TextSize = 12.5; lbl.TextColor3 = _TXT2; lbl.TextXAlignment = Enum.TextXAlignment.Left; lbl.TextYAlignment = Enum.TextYAlignment.Top; lbl.TextWrapped = true
			lbl.Text = "Your executor has a bug that breaks custom mesh loading (CreateMeshPartAsync), so the body may look rough or mis-sized. This is NOT the script - it hits every mesh script on this build. For full quality, use a different executor until it's patched."
			local btn = Instance.new("TextButton", f)
			btn.AnchorPoint = Vector2.new(1, 1); btn.Position = UDim2.new(1, -12, 1, -10); btn.Size = UDim2.fromOffset(96, 28); btn.BackgroundColor3 = Color3.fromRGB(38, 38, 50); btn.AutoButtonColor = false; btn.Text = "Got it"; btn.TextColor3 = _TXT; btn.Font = Enum.Font.GothamBold; btn.TextSize = 13; btn.BorderSizePixel = 0
