	-- V4.3.309: pre-warm common SmartBone body-type meshes at boot. After install (see Changelog for full rationale)
	function Function.PrewarmCommonMeshes()
		local _paths = {
			"RClothesContent/_vns/model/breast/1/leftb.mesh",
			"RClothesContent/_vns/model/breast/1/rightb.mesh",
			"RClothesContent/_vns/model/breast/1/leftn.mesh",
			"RClothesContent/_vns/model/breast/1/rightn.mesh",
			"RClothesContent/_vns/model/butt/1/left.mesh",
			"RClothesContent/_vns/model/butt/1/right.mesh",
			"RClothesContent/_vns/model/arm/1/left.mesh",
			"RClothesContent/_vns/model/arm/1/right.mesh",
			"RClothesContent/_vns/model/leg/1/left.mesh",
			"RClothesContent/_vns/model/leg/1/right.mesh",
			"RClothesContent/_vns/model/torso/1/1.mesh",
		}
		for _, _p in ipairs(_paths) do
			task.spawn(function()
				if System.isfile and not System.isfile(_p) then return end  -- not on disk yet
				local _resolved = Function.GetAsset("rbxasset://" .. _p)
				pcall(Function.CachedCreateMeshPartAsync, _resolved,
					Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
			end)
		end
	end

	-- V4.3.279: foreign-bundle MeshEdit sanity gate. A community-published bundle (see Changelog for full rationale)
	function Function.SanitizeMeshEditValue(propName, propVal)
		if propVal == nil then return nil, false end
		if propName == "Size" then
			if typeof(propVal) ~= "Vector3" then return nil, false end
			local x, y, z = propVal.X, propVal.Y, propVal.Z
			-- NaN check (NaN ~= NaN), Inf check, magnitude cap.
			if x ~= x or y ~= y or z ~= z then return nil, false end
			if math.abs(x) == math.huge or math.abs(y) == math.huge or math.abs(z) == math.huge then return nil, false end
			-- Engine clothing-mesh ceiling: 256 studs per axis is generous; the
			-- engine cap is ~2048 but anything over 256 in clothing is foreign-bundle
			-- griefing. Floor of 0.05 prevents zero-axis mesh-prep crashes on mobile.
			x = math.clamp(x, 0.05, 256)
			y = math.clamp(y, 0.05, 256)
			z = math.clamp(z, 0.05, 256)
			return Vector3.new(x, y, z), true
		elseif propName == "CFrame" or propName == "CFrame1" then
			if typeof(propVal) ~= "CFrame" then return nil, false end
			-- NaN scan over CFrame components - a NaN in any component will refuse
			-- to replicate and may trigger a render-thread assert.
			local _ok, _components = pcall(propVal.GetComponents, propVal)
			if not _ok or not _components then return nil, false end
			for _, c in ipairs({propVal:GetComponents()}) do
				if c ~= c or math.abs(c) == math.huge then return nil, false end
			end
			return propVal, true
		elseif propName == "MeshId" or propName == "TextureId" then
			if type(propVal) ~= "string" then return nil, false end
			-- Allowlist: rbxasset:// (local content, our shipped meshes) or
			-- rbxassetid://NUMBER (Roblox catalog). Reject http://, file://,
			-- empty strings, or paths with ../ traversal.
			if propVal == "" then return nil, false end
			if propVal:match("^rbxasset://[%w_%-/. ]+$") then return propVal, true end
			if propVal:match("^rbxassetid://%d+$") then return propVal, true end
			return nil, false
		elseif propName == "Transparency" or propName == "Reflectance" then
			if type(propVal) ~= "number" then return nil, false end
			if propVal ~= propVal then return nil, false end  -- NaN
			return math.clamp(propVal, 0, 1), true
		end
		-- Unknown prop name - pass through (covers Recolor flags, future fields).
		-- Reject only obviously dangerous types (function/userdata/thread).
		local _t = type(propVal)
		if _t == "function" or _t == "userdata" or _t == "thread" then return nil, false end
		return propVal, true
	end

	function Function.InitializeAssets()
		if env.isfolder and env.makefolder and not env.isfolder("RClothesContent") then
			-- V4.3.515 Fix 7: pcall-wrap to match sibling sites (e.g. L6732, L13782).
			pcall(env.makefolder, "RClothesContent")
			warn("[RoClothes] Created missing RClothesContent folder in workspace.")
		end
		if env.writefile then pcall(env.writefile, "RClothesContent/.nomedia", "") end  -- V4.5.16: Android `.nomedia` hides RoClothes photos from the phone Gallery/Photos; written every boot so EXISTING installs are covered without a redownload
		-- VNS install check removed - the executor-workspace check produced false-positive
		-- warnings when files were correctly placed in the Roblox content folder
		-- (rbxasset:// resolves to AppData/Local/Roblox/Versions/.../content/RClothesContent/).
		-- If a mesh actually fails to load, CreateMeshPartAsync logs the failing path itself.
	end

	function Function.ApplyAssets(Root)
		-- V4.3.306: pcall-wrap every asset-property write. Xeno's executor restricts (see Changelog for full rationale)
		local function _trySet(inst, prop, val)
			pcall(function() inst[prop] = val end)
		end
		-- V4.3.552: defensive guard for non-string asset properties. On modern
		-- Roblox (Content-type migration era), MeshId / TextureID / ColorMap /
		-- Texture may return Content userdata instead of string. Calling
		-- Function.GetAsset on a Content userdata would invoke :gsub on
		-- userdata which THROWS - not caught by _trySet's pcall (which only
		-- guards the assignment, not the argument evaluation). The throw would
		-- abort this entire ApplyAssets call, leaving downstream code in an
		-- inconsistent state. Identified by V4.3.552 broad-scan workflow as a
		-- latent crash that becomes live once V4.3.551 bytes-rebuild starts
		-- producing Content-backed MeshParts. Guard: pcall the read first,
		-- skip rewrite if non-string. For non-string reads the asset was set
		-- via engine API (CreateMeshPartAsync) at construction time and doesn't
		-- need post-load rewriting.
		local function _safeRewrite(inst, prop)
			local _okR, _cur = pcall(function() return inst[prop] end)
			if not _okR or type(_cur) ~= "string" then return end
			local _new = Function.GetAsset(_cur)
			-- V4.4.x EXECUTOR-SUPPORT: only rewrite when GetAsset actually resolved a DIFFERENT
			-- (local getcustomasset) URL - i.e. a custom VNS mesh. For a standard rbxassetid://
			-- accessory GetAsset returns the input UNCHANGED, so this would re-assign MeshId/TextureID
			-- to the same value it already holds. That runtime rbxassetid content-load is exactly what
			-- some executors' anti-rip security hooks BLOCK (":7455/:7405 BLOCKED file path"), and the
			-- accessory was ALREADY loaded correctly by ApplyDescription - so the write is pure no-op on
			-- a normal executor and pure harm on a blocking one. Skipping identity writes is zero-
			-- regression everywhere and lets rbxassetid accessories survive on locked-down executors.
			if _new ~= _cur then
				_trySet(inst, prop, _new)
			end
		end
		for _, v in pairs(Root:GetDescendants() or {}) do
			if v:IsA("MeshPart") then
				_safeRewrite(v, "MeshId")
				_safeRewrite(v, "TextureID")
			elseif v:IsA("SpecialMesh") then
				_safeRewrite(v, "MeshId")
				_safeRewrite(v, "TextureId")
			elseif v:IsA("Decal") or v:IsA("Texture") then
				_safeRewrite(v, "Texture")
			elseif v:IsA("ImageLabel") or v:IsA("ImageButton") then
				_safeRewrite(v, "Image")
			end
		end
		-- Check root itself
		if Root:IsA("MeshPart") then
			_safeRewrite(Root, "MeshId")
			_safeRewrite(Root, "TextureID")
		elseif Root:IsA("SpecialMesh") then
			_safeRewrite(Root, "MeshId")
			_safeRewrite(Root, "TextureId")
		end
	end
	
	Function.InitializeAssets()

