			local _icx = Instance.new("TextLabel", _ic)
			_icx.Size = UDim2.fromScale(1, 1); _icx.BackgroundTransparency = 1; _icx.Font = Enum.Font.GothamBold; _icx.Text = "!"; _icx.TextColor3 = Color3.new(1, 1, 1); _icx.TextSize = 26; _icx.TextXAlignment = Enum.TextXAlignment.Center
			local _title = Instance.new("TextLabel", _card)
			_title.AnchorPoint = Vector2.new(0.5, 0); _title.Position = UDim2.new(0.5, 0, 0, 78); _title.Size = UDim2.new(1, -44, 0, 26); _title.BackgroundTransparency = 1; _title.Font = Enum.Font.GothamBold; _title.TextSize = 19; _title.TextColor3 = _TXT; _title.Text = "Content download failed"; _title.TextXAlignment = Enum.TextXAlignment.Center
			local _body = Instance.new("TextLabel", _card)
			_body.AnchorPoint = Vector2.new(0.5, 0); _body.Position = UDim2.new(0.5, 0, 0, 112); _body.Size = UDim2.new(1, -44, 0, 124); _body.BackgroundTransparency = 1; _body.Font = Enum.Font.Gotham; _body.TextSize = 14; _body.TextColor3 = _TXT2; _body.TextWrapped = true; _body.TextXAlignment = Enum.TextXAlignment.Center; _body.TextYAlignment = Enum.TextYAlignment.Top
			-- V4.5.17: when a log file exists (per-file install failure), tell the user to SEND it to us on Discord
			-- (that file names the exact failures + reasons, so it's exactly what we need to fix per-device issues).
			_body.Text = (message or "Something went wrong while downloading RoClothes assets.")
				.. (logPath and ("\n\nPlease send us this file on our Discord so we can fix it for your device:\n" .. logPath)
					or "\n\nStill stuck? Report it in our Discord:")
			-- click-to-copy Discord link (so the user never has to type it out)
			local _DISCORD = "discord.gg/SBUuYsnShf"
			local _lnk = Instance.new("TextButton", _card)
			_lnk.AnchorPoint = Vector2.new(0.5, 0); _lnk.Position = UDim2.new(0.5, 0, 0, 244); _lnk.Size = UDim2.new(1, -60, 0, 26); _lnk.BackgroundColor3 = Color3.fromRGB(30, 30, 42); _lnk.BackgroundTransparency = 0.3; _lnk.AutoButtonColor = false; _lnk.Font = Enum.Font.GothamBold; _lnk.TextSize = 13; _lnk.TextColor3 = _AC1; _lnk.Text = _DISCORD .. "   (tap to copy)"; _lnk.BorderSizePixel = 0
			local _lc = Instance.new("UICorner", _lnk); _lc.CornerRadius = UDim.new(0, 8)
			local _lst = Instance.new("UIStroke", _lnk); _lst.Color = _LINE; _lst.Thickness = 1; _lst.Transparency = 0.4
			_lnk.MouseButton1Click:Connect(function()
				local _cb = setclipboard or toclipboard or writeclipboard or (System and System.Env and System.Env.setclipboard)
				local _ok = _cb and pcall(_cb, _DISCORD)
				_lnk.Text = _ok and ("Copied!   " .. _DISCORD) or _DISCORD
				_lnk.TextColor3 = _ok and Color3.fromRGB(120, 220, 150) or _AC1
				task.delay(1.6, function() if _lnk.Parent then _lnk.Text = _DISCORD .. "   (tap to copy)"; _lnk.TextColor3 = _AC1 end end)
			end)
			-- Dismiss = the app's primary accent-gradient button (white base so the pink->purple gradient shows)
			local _btn = Instance.new("TextButton", _card)
			_btn.AnchorPoint = Vector2.new(0.5, 1); _btn.Position = UDim2.new(0.5, 0, 1, -20); _btn.Size = UDim2.fromOffset(160, 40); _btn.BackgroundColor3 = Color3.new(1, 1, 1); _btn.AutoButtonColor = false; _btn.Text = ""; _btn.BorderSizePixel = 0
			_uic = Instance.new("UICorner", _btn); _uic.CornerRadius = UDim.new(0, 11)
			local _bgrad = Instance.new("UIGradient", _btn); _bgrad.Rotation = 25; _bgrad.Color = ColorSequence.new(_AC1, _AC2)
			local _blbl = Instance.new("TextLabel", _btn)
			_blbl.Size = UDim2.fromScale(1, 1); _blbl.BackgroundTransparency = 1; _blbl.Font = Enum.Font.GothamBold; _blbl.Text = "Dismiss"; _blbl.TextColor3 = Color3.new(1, 1, 1); _blbl.TextSize = 15; _blbl.TextXAlignment = Enum.TextXAlignment.Center
			_btn.MouseButton1Click:Connect(function() pcall(function() _gui:Destroy() end) end)
			-- PHASE 10 (PART B): also drive the merged GUI's install-fail overlay with the
			-- real failure message. Guarded: System.showOverlay only exists post-GUI-build,
			-- so a FIRST-RUN install failure (engine L~6444, before the GUI) shows only this
			-- engine card; a WARM Redownload failure (after the GUI exists) also surfaces the
			-- themed overlay. SAME real failure drives both.
			if System.showOverlay then pcall(System.showOverlay, "installFail", { reason = tostring(message or "") }) end
		end

		-- Hard-fail-safe: if executor lacks the file APIs, popup the user. The script
		-- still works as long as the user has files in the Roblox content folder
		-- (legacy install path). The CreateMeshPartAsync warns will tell them otherwise.
		if not (env.isfile and env.writefile and env.makefolder and env.isfolder) then
			warn("[RoClothes] Content auto-installer disabled (executor missing file APIs).")
			_showInstallError("Your executor is missing required file APIs (isfile / writefile / makefolder / isfolder).\nThe script may still work if RClothesContent is already installed manually.")
			return
		end

		local CONTENT_MANIFEST_URL = "https://krulhub.dev/roclothes/content-manifest.json"
		local CONTENT_BASE_URL     = "https://krulhub.dev/roclothes/content/"
		-- V4.4.x PACK FAST-PATH: a few large concatenated "pack" blobs + a byte-offset manifest let the
		-- installer satisfy hundreds of files with a handful of GETs instead of one-GET-per-file (the real
		-- first-run bottleneck is per-file HTTP round-trips, not bandwidth). Served under the existing
		-- content route (→ R2 key roclothes-content/_packs/...) so NO Cloudflare worker change is needed.
		-- Manifest: { version, packs:["p0.bin",...], files:[{p=<path>, k=<packIdx 0-based>, o=<offset>, n=<len>},...] }.
		-- Entirely OPTIONAL: if the manifest/pack is missing or any slice fails a size-check, that file
		-- falls straight through to the per-file worker loop below - zero regression vs the old path.
		-- V4.3.556: primary marker is the non-dotfile name (writes on Volt etc.).
		-- _RC_MARKER_LEGACY (the old `.manifest_version` dotfile) is read as a
		-- fallback below so dot-capable executors don't re-verify on upgrade.
		local MARKER_PATH          = _RC_MARKER_PRIMARY
		-- Bound concurrent multi-MB bodies: five workers on touch-only mobile,
		-- eight on desktop. More connections did not improve measured throughput.
		local _isMobile = (UIS and UIS.TouchEnabled and not UIS.KeyboardEnabled) or false
		local MAX_PARALLEL = _isMobile and 5 or 8
		local MANIFEST_TIMEOUT_S   = 30    -- V4.3.303: was 10s - too aggressive on slow connections / cold-cache executors (Xeno report)

		-- HTTP fetch helper. Uses game:HttpGet first, falls back to executor http_request
		-- chain (some executors block game:HttpGet but allow request/http_request/syn.request).
		-- V4.3.303: returns (data, errMsg) - second return surfaces the actual failure
		-- reason so the manifest-fetch path can log it instead of hiding behind "timeout".
		local function _fetch(url)
			System._installFetchState = System._installFetchState or { active = 0 }
			local state = System._installFetchState
			if System._sessionAlive == false then return nil, "session ended" end
			if state.active >= MAX_PARALLEL then return nil, "transport still busy after timeout" end
			local job = { done = false, abandoned = false }
			state.active = state.active + 1
			task.spawn(function()
				local ran, result, err = pcall(function()
					-- Uses game:HttpGet first, falls back to executor http_request chain. (V4.4.x tried native
					-- request()-first to bypass Roblox's HTTP throttle, but on the owner's executor it was no
					-- faster / slightly slower, so reverted to HttpGet-first.)
					local ok, data = pcall(game.HttpGet, game, url)
					if job.abandoned or System._sessionAlive == false then return nil, "request abandoned" end
					if ok and type(data) == "string" and #data > 0 then return data end
					local _hgErr = (not ok) and tostring(data) or ("empty/non-string body: "..tostring(data))
					local reqFn = (System.Env and (System.Env.http_request or System.Env.request))
						or http_request or request or (syn and syn.request)
					if reqFn then
						local rok, res = pcall(reqFn, {Url = url, Method = "GET"})
						if job.abandoned or System._sessionAlive == false then return nil, "request abandoned" end
						if rok and res and res.Body and (tonumber(res.StatusCode) == 200 or res.Success) then  -- V4.5.19: tonumber - string "200" was discarded as a transport failure
							return res.Body
						end
						local _reqErr = (not rok) and tostring(res)
							or string.format("status=%s success=%s bodyLen=%s",
								tostring(res and res.StatusCode), tostring(res and res.Success),
								tostring(res and res.Body and #res.Body))
						-- V4.3.506 telemetry: both HttpGet and request() failed.
						do
							local _host = tostring(url):match("https?://([^/]+)") or "?"
							local _status = (res and tonumber(res.StatusCode)) or 0
							Function.diag("exec.transport_error", { fn = "request", status = _status, url_host = _host:sub(1, 96) })
						end
						return nil, "HttpGet: "..(_hgErr or "?").."  | request(): ".._reqErr
					end
					-- No executor request fn at all - note this as a missing-api capability gate.
					Function.diagOnce("request_fn_chain")
					return nil, "HttpGet: "..(_hgErr or "?").."  | no executor request() fn available"
				end)
				state.active = state.active - 1
				if not job.abandoned then
					if ran then job.data, job.error = result, err
					else job.error = tostring(result) end
				end
				job.done = true
			end)
			-- Native executor transports cannot always be cancelled. Keep their slot
			-- occupied until they settle, but release the installer after its deadline.
			local started = os.clock()
			while not job.done and System._sessionAlive ~= false and os.clock() - started < 30 do task.wait(0.05) end
			if not job.done then
				job.abandoned = true
				return nil, System._sessionAlive == false and "session ended" or "timeout after 30s"
			end
			if System._sessionAlive == false then return nil, "session ended" end
			return job.data, job.error
		end

		-- Step 1: fetch manifest with a wall-clock timeout. We don't have a real
		-- request-cancel API, so we race the fetch against task.delay.
		local manifestRaw, manifestErr
		local fetchDone = false
		task.spawn(function()
			manifestRaw, manifestErr = _fetch(CONTENT_MANIFEST_URL)
			fetchDone = true
		end)
		local _t0 = os.clock()
		while not fetchDone and (os.clock() - _t0) < MANIFEST_TIMEOUT_S do task.wait(0.1) end
		if not manifestRaw then
			-- V4.3.303: surface the actual error + distinguish timeout from fetch-failure.
			local _reason = fetchDone and ("fetch failed: "..tostring(manifestErr or "?"))
				or ("timeout after "..MANIFEST_TIMEOUT_S.."s (fetchDone="..tostring(fetchDone)..")")
			warn("[RoClothes] Content manifest "..(_reason).." - proceeding without auto-install (legacy content folder will be used if present).")
			_showInstallError("Could not reach our asset servers.\n\nReason: "..(_reason).."\n\nIf RClothesContent is already installed locally, the script may still work.")
			return
		end

		-- Step 2: parse manifest.
		local mok, manifest = pcall(function() return HS:JSONDecode(manifestRaw) end)
		if not mok or type(manifest) ~= "table" or type(manifest.files) ~= "table" then
			warn("[RoClothes] Content manifest malformed - skipping auto-install.")
			_showInstallError("The content manifest from our servers is malformed.\nThis usually means the CDN is mid-deploy - try again in a minute.")
			return
		end
		local manifestVersion = tostring(manifest.version or "unknown")
		-- V4.4.x START-LATENCY: on a true first run (content folder absent) EVERYTHING is missing, so the
		-- _vns_uniq repair pass + the per-file isfile/getfilesize verify scan below are pure wasted work that
		-- keeps the loader stuck on "Connecting" before any byte downloads (owner report: "scanning something
		-- for a long time before it starts"). Capture the folder state ONCE here - BEFORE the _vns_uniq pass
		-- creates the folder - and skip both scans when it's a clean first run (just queue every file).
		local _contentFolderMissing = (env.isfolder and not env.isfolder("RClothesContent")) or false
		-- V4.3.312: removed V4.3.311's hardcoded `_knownBroken` allowlist filter for the (see Changelog for full rationale)

		-- V4.3.555: _vns_uniq mirror repair pass. Runs BEFORE the warm-path
		-- early-return so existing installs (V4.3.554 era) get their truncated
		-- mirror files repaired. Background: Xeno's getcustomasset keys URLs
		-- by basename - arm/leg/butt all have left.mesh/right.mesh files →
		-- cross-contamination at the URL cache layer. V4.3.555 fix: write a
		-- unique-basename copy of every VNS mesh to RClothesContent/_vns_uniq/
		-- so getcustomasset gets a unique URL per source file. V4.3.554 tried
		-- to do this via runtime `readfile→writefile` but Xeno's readfile
		-- truncates binary data at the first \\0 byte (filesystem audit 2026-
		-- 06-08 confirmed 11 truncated files in _vns_uniq/ ranging 38-4173 B
		-- vs source sizes 5KB-654KB). The fix is to use HTTP-downloaded bytes
		-- (binary-safe Lua string from HttpGet) instead of readfile. This
		-- repair pass iterates manifest entries for `_vns/.../*.mesh` files,
		-- checks if the unique mirror exists at expected size, and if not,
		-- re-downloads from CDN. Sequential (typically <15 files when needed,
		-- usually 0 after first run). Telemetry: install.uniq_mirror_repaired
		-- on completion with count.
		if (not _contentFolderMissing) and (not forceAll) then   -- V4.4.x: skip the mirror-repair scan on a clean first run / forceAll (nothing exists to repair)
			local _uniqDir = "RClothesContent/_vns_uniq"
			if not env.isfolder(_uniqDir) then pcall(env.makefolder, _uniqDir) end
			local _envGfsM = (getgenv and getgenv()) or _G
			local _gfsM = _envGfsM.getfilesize or getfilesize or (System.Env and System.Env.getfilesize)
			local _uniqTodo = {}
			for _, entry in ipairs(manifest.files) do
				if type(entry) == "table" and type(entry.p) == "string"
				   and entry.p:match("^_vns/.+%.mesh$") and entry.s then
					local _flat = ("RClothesContent/" .. entry.p):gsub("[/\\]", "_")
					local _uniqPath = _uniqDir .. "/" .. _flat
					local _ok = env.isfile(_uniqPath)
					if _ok and _gfsM then
						local _szOk, _sz = pcall(_gfsM, _uniqPath)
						if not _szOk or _sz ~= entry.s then _ok = false end
					end
					if not _ok then
						-- V4.4.2 (round 3): only repair the mirror when the SOURCE _vns file already exists. On a
						-- cold first run the source isn't downloaded yet, so without this EVERY vns mesh got
						-- re-downloaded SEQUENTIALLY here (no setProgress -> stuck at 0%), THEN again by the main
						-- installer (which writes the mirror itself). Mirror repair is only meaningful warm.
						if env.isfile("RClothesContent/" .. entry.p) then
							table.insert(_uniqTodo, {p = entry.p, uniqPath = _uniqPath, s = entry.s})
						end
					end
				end
			end
			if #_uniqTodo > 0 then
				local _uniqDone, _uniqFail = 0, 0
				for _, _t in ipairs(_uniqTodo) do
					if System._sessionAlive == false then return end
					local _encUrl = CONTENT_BASE_URL .. _t.p:gsub(" ", "%%20")
					local _data, _err = _fetch(_encUrl)
					if _data and #_data == _t.s then
						if env.delfile and env.isfile(_t.uniqPath) then
							pcall(env.delfile, _t.uniqPath)
						end
						local _wok = pcall(env.writefile, _t.uniqPath, _data)
						if _wok then
							_uniqDone = _uniqDone + 1
							System._meshContentGeneration = (System._meshContentGeneration or 0) + 1
						else _uniqFail = _uniqFail + 1 end
					else
						_uniqFail = _uniqFail + 1
					end
				end
				print(string.format(
					"[RoClothes][install] _vns_uniq mirror repaired: %d/%d files (failed=%d)",
					_uniqDone, #_uniqTodo, _uniqFail))
				Function.diag("install.uniq_mirror_repaired", {
					todo = #_uniqTodo, done = _uniqDone, failed = _uniqFail,
				})
			end
		end

		-- Step 3: cache short-circuit. If the marker matches AND a sentinel file is
		-- present (guards against partial first-install where we wrote the marker
		-- but the user wiped the workspace folder), bail out fast.
		-- V4.3.556: read primary (non-dotfile) first, then legacy dotfile. The
		-- legacy fallback lets dot-capable executors that installed under the old
		-- marker name short-circuit the warm path instead of doing a full
		-- re-verify on the first launch after upgrading to V4.3.556.
		local cachedVer = nil
		for _, _mp in ipairs({ MARKER_PATH, _RC_MARKER_LEGACY }) do
			if env.isfile(_mp) then
				local rok, rdata = pcall(env.readfile, _mp)
				if rok and type(rdata) == "string" then cachedVer = rdata; break end
			end
		end
		-- V4.3.520 Fix 11: trim whitespace + BOM before compare. Pre-fix, executors
		-- that append \n on writefile would mismatch on read and force a full ~1100-file
		-- reinstall on every warm boot.
		local function _trimMarker(s)
			if type(s) ~= "string" then return "" end
			s = s:gsub("^\239\187\191", "")  -- UTF-8 BOM
			return (s:gsub("^%s+", ""):gsub("%s+$", ""))
		end
		-- V4.3.558: marker writer. ROOT CAUSE of the Volt intro-skip (runtime-
		-- proven by the V4.3.557 probe): Volt's writefile REJECTS filenames ending
		-- in ".tmp" with "invalid argument #1 to 'writefile' (Illegal path)". The
		-- old atomic marker write used `MARKER_PATH .. ".tmp"` (ends in .tmp) → it
		-- failed at step 1 on Volt → the whole atomic block was skipped → the marker
		-- never persisted → the intro's marker gate bailed every launch + the
		-- install re-ran cold every launch. (Every other prior theory - dotfile,
		-- extensionless, newline/BOM - was refuted: the V4.3.557 probe showed
		-- `.manifest_version`, `manifest_version`, and `manifest_version.txt` ALL
		-- write+persist fine on Volt; only the `.tmp`-suffixed temp failed.)
		-- _atomicWriteJSON survived on Volt precisely because its temp ends in a
		-- counter (`....tmp.<clock>_<rng>_<n>`), not in ".tmp".
		-- Fix: use a Volt-safe temp suffix (ends in "_mk", not ".tmp"), verify with
		-- _trimMarker tolerance, and - belt-and-suspenders - fall back to a DIRECT
		-- writefile of the marker if it still isn't on disk afterward (the V4.3.557
		-- probe proved a direct `writefile(MARKER_PATH, ...)` works on Volt). The
		-- marker is ~12 bytes, so a direct write has negligible torn-write risk; a
		-- torn marker only triggers a cheap re-verify next boot (todo empty).
		local function _writeMarker(_mv)
			local _tmp = MARKER_PATH .. ".tmp." .. tostring(os.clock()) .. "_mk"
			local _okW = pcall(env.writefile, _tmp, _mv)
			if _okW and env.isfile and env.isfile(_tmp) then
				local _okR, _back = pcall(env.readfile, _tmp)
				if _okR and type(_back) == "string" and _trimMarker(_back) == _trimMarker(_mv) then
					pcall(env.writefile, MARKER_PATH, _mv)
				end
				if env.delfile then pcall(env.delfile, _tmp) end
			end
			-- Fallback: if the marker still isn't present (temp path blocked on this
			-- executor, or verify failed), write it directly. Proven to work on Volt.
			if not (env.isfile and env.isfile(MARKER_PATH)) then
				pcall(env.writefile, MARKER_PATH, _mv)
			end
		end
		if (not forceAll) and _trimMarker(cachedVer) == _trimMarker(manifestVersion) and #manifest.files > 0 then
			-- Spot-check: first file must exist. If it doesn't, the cache is lying.
			local first = manifest.files[1]
			if first and first.p and env.isfile("RClothesContent/" .. first.p) then
				return  -- warm path, no work needed
			end
		end

		-- V4.3.441: drop the stale marker BEFORE we start overwriting content frames.
		-- This signals downstream consumers (intro preload, getcustomasset callers)
		-- that the on-disk content is mid-update and may be inconsistent. Marker is
		-- re-written at end of successful install; the next session plays intro
		-- normally if install completed.
		System._installInProgress = true
		-- V4.3.556: delete BOTH the primary (non-dotfile) and legacy dotfile
		-- markers so an interrupted install can't leave a stale either-name
		-- marker that the next boot mistakes for a complete install.
		if env.delfile then
			if env.isfile(MARKER_PATH) then pcall(env.delfile, MARKER_PATH) end
			if env.isfile(_RC_MARKER_LEGACY) then pcall(env.delfile, _RC_MARKER_LEGACY) end
		end

		-- Step 4: cold path. Build the work list (missing files OR size mismatch).
		local todo = {}
		for _, entry in ipairs(manifest.files) do
			if type(entry) == "table" and type(entry.p) == "string" then
				-- V4.3.441: reject manifest entries with path-traversal or absolute
				-- prefixes. Manifest is fetched from krulhub.dev over HTTPS so source
				-- is trusted today, but a misconfigured CDN bucket, mistyped path, or
				-- compromised worker can put `../../foo` or `C:\…` into entry.p and
				-- env.writefile happily writes wherever its cwd reaches. Allowlist:
				-- word chars, digits, underscore, dash, dot, forward-slash, space.
				-- Explicit reject for `..` segments (catches `foo/../bar`).
				-- V4.3.502: replace the substring `%.%.` find with a segment-based
				-- check. The substring form rejects legitimate paths like
				-- `foo..bar/baz.png` (no traversal - `..` is just inside a filename),
				-- and conversely a hostile `foo/.../bar` slips past the segment
				-- intent. Iterate `/`-separated segments and reject only when a
				-- segment is exactly `..` or `.`.
				local _badSeg = false
				for seg in entry.p:gmatch("[^/]+") do
					if seg == ".." or seg == "." then _badSeg = true; break end
				end
				if _badSeg or entry.p:sub(1,1) == "/" or entry.p:sub(2,2) == ":"
					or not entry.p:match("^[%w_%-./ ]+$") then
					warn("[RoClothes] Rejecting suspicious manifest path: " .. tostring(entry.p))
					continue
				end
				local localPath = "RClothesContent/" .. entry.p
				local needs = true
				-- V4.4.x: forceAll (Redownload All) skips the "already present + size-matched" short-circuit,
				-- so EVERY file is re-fetched. Gives the user a genuine re-download with live progress instead
				-- of an instant silent no-op when content is already installed (the "Redownload does nothing"
				-- report). Boot/first-run callers pass no arg → normal verify-only behaviour is preserved.
				if (not forceAll) and (not _contentFolderMissing) and env.isfile(localPath) then
					-- Size-mismatch check via getfilesize when available; otherwise trust isfile.
					-- V4.3.504: standard env-resolution (getgenv first). Xeno/Volt expose
					-- getfilesize only via getgenv()/_G, not as a top-level global.
					local _envGfs = (getgenv and getgenv()) or _G
					local _gfs = _envGfs.getfilesize or getfilesize or (System.Env and System.Env.getfilesize)
					if entry.s and type(entry.s) == "number" and _gfs then
						local ok, sz = pcall(_gfs, localPath)
						if ok and sz == entry.s then
							needs = false
						elseif ok and type(sz) == "number" then
							-- V4.3.506 telemetry: file exists but size differs from manifest.
							Function.diag("install.size_mismatch", { path = tostring(entry.p):sub(1, 128), got = sz, expected = entry.s })
						end
					else
						-- No size-check API: trust isfile presence. Updates won't be detected
						-- automatically - manifest version bump is the safety net.
						needs = false
					end
				end
				if needs then table.insert(todo, {p = entry.p, localPath = localPath, s = entry.s}) end
			end
		end

		if #todo == 0 then
			-- All files present and size-matched. Refresh the marker so the next run
			-- hits the warm path. V4.3.558: routed through _writeMarker (Volt-safe
			-- temp + direct-write fallback) - the old `MARKER_PATH..".tmp"` write was
			-- silently rejected by Volt ("Illegal path") so the marker never landed.
			_writeMarker(manifestVersion)
			-- V4.4.x: resolve the merged-GUI toast so a nothing-to-do path never leaves the button's
			-- "Downloading content / Starting download…" toast hanging forever. hideOverlay flips it to
			-- "Content ready." (no-op on first-run boot before the GUI exists). Redownload now passes
			-- forceAll=true so it won't hit this branch, but other callers (warm verify) still resolve.
			if System.hideOverlay then pcall(System.hideOverlay) end
			return
		end

		-- V4.3.257: minimal pill overlay at top-center. Game stays visible/interactable.
		local overlayGui, overlayText, overlayBar
		-- V4.4.x: when onProgress is supplied (the Vampiric Aurora first-run loader driving the REAL
		-- download), that loader owns the on-screen progress UI - skip building the raw engine pill so
		-- the two don't both show. Boot/warm callers pass no onProgress → the raw pill still builds.
		if not onProgress then
			local cg = game:GetService("CoreGui")
			-- V4.5.16: RENEWED to the modern look (was 15,15,20 pill + blue-grey stroke + plain text). Raw Instance.new +
			-- hardcoded modern palette (helpers/T out of scope here) + accent dot + a live pink->purple progress bar + fit.
			overlayGui = Instance.new("ScreenGui")
			overlayGui.Name = "_RoClothesInstaller"; overlayGui.IgnoreGuiInset = true; overlayGui.ResetOnSpawn = false; overlayGui.DisplayOrder = 999999; overlayGui.Parent = cg
			local container = Instance.new("Frame", overlayGui)
			container.AnchorPoint = Vector2.new(0.5, 0); container.Position = UDim2.new(0.5, 0, 0, 14); container.Size = UDim2.fromOffset(360, 46); container.BackgroundColor3 = Color3.fromRGB(20, 20, 28); container.BackgroundTransparency = 0.06; container.BorderSizePixel = 0
			Instance.new("UICorner", container).CornerRadius = UDim.new(0, 14)
			local _stk = Instance.new("UIStroke", container); _stk.Color = Color3.fromRGB(233, 74, 128); _stk.Thickness = 1; _stk.Transparency = 0.4
			local _psc = Instance.new("UIScale", container)  -- auto-fit for narrow / mobile screens
			local function _fitPill() local _cam = workspace.CurrentCamera; local _vw = (_cam and _cam.ViewportSize.X) or 800; _psc.Scale = math.min(1, (_vw - 24) / 360) end
			_fitPill(); pcall(function()
				local _vpP
				_vpP = workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
					if not overlayGui.Parent then pcall(function() _vpP:Disconnect() end) return end  -- V4.5.24 Fix: self-disconnect (was leaking a connection per installer pill)
					_fitPill()
				end)
			end)
			local _dot = Instance.new("Frame", container); _dot.AnchorPoint = Vector2.new(0, 0.5); _dot.Position = UDim2.new(0, 14, 0.5, -3); _dot.Size = UDim2.fromOffset(8, 8); _dot.BackgroundColor3 = Color3.fromRGB(233, 74, 128); _dot.BorderSizePixel = 0
			Instance.new("UICorner", _dot).CornerRadius = UDim.new(1, 0)
			overlayText = Instance.new("TextLabel", container)
			overlayText.AnchorPoint = Vector2.new(0.5, 0); overlayText.Position = UDim2.new(0.5, 0, 0, 9); overlayText.Size = UDim2.new(1, -50, 0, 20); overlayText.BackgroundTransparency = 1; overlayText.Font = Enum.Font.GothamMedium; overlayText.TextSize = 13; overlayText.TextColor3 = Color3.fromRGB(236, 236, 245); overlayText.TextXAlignment = Enum.TextXAlignment.Center; overlayText.TextTruncate = Enum.TextTruncate.AtEnd
			overlayText.Text = "Installing RoClothes assets...  0 / " .. #todo
			local _track = Instance.new("Frame", container); _track.AnchorPoint = Vector2.new(0.5, 1); _track.Position = UDim2.new(0.5, 0, 1, -8); _track.Size = UDim2.new(1, -28, 0, 3); _track.BackgroundColor3 = Color3.fromRGB(48, 48, 60); _track.BorderSizePixel = 0
			Instance.new("UICorner", _track).CornerRadius = UDim.new(1, 0)
			overlayBar = Instance.new("Frame", _track); overlayBar.Size = UDim2.new(0, 0, 1, 0); overlayBar.BackgroundColor3 = Color3.fromRGB(233, 74, 128); overlayBar.BorderSizePixel = 0
			Instance.new("UICorner", overlayBar).CornerRadius = UDim.new(1, 0)
			local _bgr = Instance.new("UIGradient", overlayBar); _bgr.Color = ColorSequence.new(Color3.fromRGB(233, 74, 128), Color3.fromRGB(150, 64, 214))
		end

		-- V4.3.436: pre-compute all parent folders ONCE before spawning workers.
		-- Pre-fix every worker ran a `for seg in item.p:gmatch("[^/]+")` loop with
		-- per-segment `env.isfolder` + `pcall(env.makefolder)` for EVERY file -
		-- ~5-8 file-API calls × ~463 files = ~3000 redundant calls. Folder structure
		-- is deterministic from the manifest, so build the unique-folder set upfront
		-- and create each only once. Eliminates per-worker path-prefix scanning.
		do
			local _folderSet = {}
			for _, item in ipairs(todo) do
				local cur = "RClothesContent"
				for seg in (item.p):gmatch("[^/]+") do
					if seg:match("%.") then break end  -- file leaf, stop
					cur = cur .. "/" .. seg
					_folderSet[cur] = true
				end
			end
			for path in pairs(_folderSet) do
				if not env.isfolder(path) then pcall(env.makefolder, path) end
			end
			-- V4.5.16: drop a `.nomedia` marker in each content folder so Android's media scanner SKIPS them - RoClothes
			-- textures/photos then never pollute the user's phone Gallery/Photos app (community fix; harmless on PC/iOS).
			if env.writefile then
				pcall(env.writefile, "RClothesContent/.nomedia", "")
				for path in pairs(_folderSet) do pcall(env.writefile, path .. "/.nomedia", "") end
			end
		end

		-- Step 6: parallel downloads. Worker coroutines pull from the shared queue.
		local nextIdx = 1
		local doneCount = 0
		local _lastFile, _lastFileSize = nil, nil  -- V4.4.x: most-recent successfully-written file (path + bytes) so onProgress can show REAL filenames in the Aurora loader log
		local failCount = 0
		local failedPaths = {}  -- V4.3.267: capture which paths failed so we can show them in the popup + write to disk for user reports
		local activeWorkers = 0
		-- V4.3.436: overlay text update throttle. Pre-fix the worker rewrote
		-- `overlayText.Text` on every file completion (~463 UI rerenders fighting
		-- the render thread during install). Now throttled to once every 10 files
		-- or 0.25s elapsed since last refresh - whichever fires first. The final
		-- progress is always shown because the wait loop redraws once on exit.
		local _lastOverlayCount = -1
		local _lastOverlayTime  = 0
		local function _maybeUpdateOverlay()
			local now = os.clock()
			if (doneCount - _lastOverlayCount) >= 10 or (now - _lastOverlayTime) >= 0.25 then
				_lastOverlayCount = doneCount
				_lastOverlayTime  = now
				if overlayText then
					overlayText.Text = string.format("Installing RoClothes assets...  %d / %d", doneCount, #todo) .. ((failCount > 0) and ("  (" .. failCount .. " failed)") or "")
				end
				if overlayBar then overlayBar.Size = UDim2.new(math.clamp(doneCount / math.max(#todo, 1), 0, 1), 0, 1, 0) end  -- live progress fill
				-- V4.3.492: also drive the global brand's % readout. Install phase
				-- maps to 0..50% (the first half) so the bar visually progresses
				-- across install + preload. The intro's preload then drives 50..100%.
				if _RC_Brand and _RC_Brand.exists() and #todo > 0 then
					_RC_Brand.setProgress((doneCount / #todo) * 50)
				end
				-- PHASE 10 (PART B): also drive the merged GUI's installer overlay with the live
				-- count. Guarded: System.showOverlay only exists post-GUI-build. On FIRST-RUN
				-- install (engine L~6444, before the GUI is built) this no-ops and the _RC_Brand
				-- bar above owns the progress UX; on a WARM Redownload (Options -> Redownload All
				-- Content, after the GUI exists) this surfaces progress in the themed overlay.
				-- V4.4.x: when a caller passes onProgress (the Aurora first-run loader driving the REAL
				-- download), IT owns the progress UI - feed it live counts and DON'T also fire the themed
				-- toast (which would stack behind the intro). Boot/warm callers keep the toast path.
				if onProgress then
					pcall(onProgress, doneCount, #todo, failCount, _lastFile, _lastFileSize, "downloading")
				elseif System.showOverlay then
					pcall(System.showOverlay, "installer", { done = doneCount, total = #todo, failed = failCount })
				end
			end
		end

		local function worker()
			activeWorkers = activeWorkers + 1
			-- V4.3.496: defense-in-depth pcall wrapper around the whole worker
			-- loop. Audit Pass A #1 found one specific crash class (size-mismatch
			-- branch read `#data` after `data = nil`) that crashed the worker
			-- coroutine outside any pcall, leaving activeWorkers permanently
			-- elevated and hanging the boot thread's `while activeWorkers > 0`
			-- wait. The specific bug is fixed above, but wrapping the entire
			-- worker body ensures future bugs in this hot path can't permanently
			-- hang first-install boot. The `activeWorkers - 1` decrement runs
			-- inside the success path AND inside the `finally`-style cleanup
			-- below.
			local _workerOk, _workerErr = pcall(function()
			while true do
				-- V4.3.486: yield per iteration so the renderer can paint between
				-- decode/write bursts. Pre-fix workers spun through warm-CDN HTTP
				-- responses + synchronous `writefile` (non-yielding native call on
				-- most executors) without yielding back to the scheduler. With 12
				-- parallel workers all hammering writefile in tight loops on a
				-- first-run install (1161 files), the Lua VM stayed busy enough
				-- that Roblox flagged the window "Not Responding." Single yield
				-- per file slows install <5% but eliminates the freeze.
				task.wait()
				-- Atomic claim of next index (single-threaded Lua, no real race).
				local i = nextIdx
				if i > #todo or System._sessionAlive == false then break end
				nextIdx = i + 1
				local item = todo[i]
				if item._done then continue end  -- V4.4.x: already written by the pack fast-path; skip its per-file GET (doneCount was bumped there)

				-- V4.3.367: URL-encode spaces in the path. The 3 RoCat mesh files (see Changelog for full rationale)
				-- V4.3.368: retry-once-with-backoff + capture detailed error reason
				local _encUrl = CONTENT_BASE_URL .. item.p:gsub(" ", "%%20")
				-- V4.5.17: retry up to 3x with EXPONENTIAL BACKOFF + jitter (was retry-once). A transient blip on a
				-- couple of files (executor HTTP hiccup, a slow/challenged edge response, a brief rate-limit) otherwise
				-- failed the WHOLE install (any failCount>0 -> popup + no marker -> re-fails EVERY launch). Spacing the
				-- retries lets a momentary block clear; the jitter de-syncs the parallel workers hammering the same edge.
				local data, _fetchErr
				for _attempt = 1, 3 do
					data, _fetchErr = _fetch(_encUrl)
					if System._sessionAlive == false then return end
					if data and #data > 0 then break end
					if _attempt < 3 then task.wait(0.5 * (2 ^ (_attempt - 1)) + math.random() * 0.4) end  -- ~0.5s then ~1.0s (+0..0.4 jitter)
				end
				-- V4.3.441: verify against manifest-declared size. Same byte count =
				-- legitimate file; mismatch = a hostile CDN substitution, a partial
				-- response, or an HTML error page (which is often megabytes). Reject
				-- before writefile. Falls back to a generous 32 MB cap when entry.s is
				-- absent (legacy entries) - Roblox single-asset files are well under.
				local _expectSize = item.s
				if data and (_expectSize and #data ~= _expectSize) then
					-- V4.3.496: capture length BEFORE nilling data. Pre-fix the
					-- format string read `#data` AFTER `data = nil`, which
					-- threw "attempt to get length of nil" - outside any pcall.
					-- The worker coroutine crashed without decrementing
					-- activeWorkers, leaving `while activeWorkers > 0 do task.wait(0.1) end`
					-- looping forever and the boot thread hung. Audit Pass A #1.
					local _gotLen = #data
					data = nil
					failCount = failCount + 1
					table.insert(failedPaths, item.p .. " (size mismatch: got "..tostring(_gotLen).." expected "..tostring(_expectSize)..")")
				elseif data and not _expectSize and #data > 33554432 then
					local _gotLen = #data
					data = nil
					failCount = failCount + 1
					table.insert(failedPaths, item.p .. " (no size in manifest, body "..tostring(_gotLen).." > 32 MB rejected)")
				end
				if data and #data > 0 then
					-- V4.3.436: parent folders already created upfront - no per-file
					-- scan needed here anymore. Just writefile directly.
					local wok, _wErr = pcall(env.writefile, item.localPath, data)
					-- V4.3.555: dual-write VNS .mesh files to _vns_uniq/ with a
					-- flattened unique basename. Bypasses Xeno getcustomasset's
					-- basename-keyed cache (arm/leg/butt left.mesh / right.mesh
					-- collide otherwise). Uses the SAME in-memory HTTP bytes -
					-- binary-safe (Lua string from HttpGet). DO NOT use readfile
					-- on Xeno - its binary handling truncates at first \\0 byte
					-- (V4.3.554 confirmed). Mirror dir already ensured by the
					-- pre-install repair pass above. Failure is non-fatal - the
					-- repair pass on next boot will retry; runtime falls back to
					-- the original URL (with cross-contamination risk).
					if wok and item.p and item.p:match("^_vns/.+%.mesh$") then
						local _flat = item.localPath:gsub("[/\\]", "_")
						local _uniqPath = "RClothesContent/_vns_uniq/" .. _flat
						pcall(env.writefile, _uniqPath, data)
					end
					data = nil  -- V4.3.263 (mobile-perf O2): release the file body string ASAP so peak memory holding parallel workers' files in-flight is minimized.
					if wok then doneCount = doneCount + 1; _lastFile = item.p; _lastFileSize = item.s
					else
						failCount = failCount + 1
						table.insert(failedPaths, item.p .. " (writefile: " .. tostring(_wErr or "?") .. ")")  -- V4.3.267 + V4.3.368
					end
				else
					failCount = failCount + 1
					-- V4.3.368: surface the actual fetch error (was just "(fetch)").
					-- Truncate so the popup doesn't blow up if the error is huge.
					local _errStr = tostring(_fetchErr or "?"):sub(1, 200)
					table.insert(failedPaths, item.p .. " (fetch: " .. _errStr .. ")")
				end

				_maybeUpdateOverlay()
			end
			end)  -- V4.3.496: close defense-in-depth pcall
			if not _workerOk then
				warn("[RoClothes] install worker crashed: " .. tostring(_workerErr))
			end
			activeWorkers = activeWorkers - 1
		end

		-- === V4.4.x PACK FAST-PATH ===
		-- Satisfy `todo` from a few large concatenated packs (ONE GET per pack) instead of one GET per file
		-- - the real first-run bottleneck is per-file HTTP round-trips. Every file it can't cover (no pack
		-- entry, a slice that fails its size-check, or an unreachable manifest/pack) is left _done=false and
		-- picked up by the per-file worker loop below, so this can only ADD speed, never break the install.
		do
			-- V4.4.x: version-scoped pack path (_packs/g<gen>/<contentVersion>/) so a re-pack is always a FRESH
			-- URL and never collides with the 1-year immutable edge cache of a prior deploy. Bump the g<gen>
			-- segment (here + in build_content_packs.mjs) whenever repacking the SAME content version.
			-- Packs are stored UNCOMPRESSED; the worker serves them text/plain so Cloudflare gzips on the wire
			-- (meshes are 86% of the payload → ~2x faster) - transparent to HttpGet, which decompresses.
			local _packBase = CONTENT_BASE_URL .. "_packs/g2/" .. tostring(manifestVersion) .. "/"
			local _pmRaw = _fetch(_packBase .. "manifest.json")
			local _pm
			if _pmRaw then
				local _okJson, _decoded = pcall(function() return game:GetService("HttpService"):JSONDecode(_pmRaw) end)
				if _okJson then _pm = _decoded end
			end
			if type(_pm) == "table" and type(_pm.packs) == "table" and type(_pm.files) == "table" then
				-- index the not-yet-done todo items by content path, then group needed files by pack
				local _todoByPath = {}
				for _, it in ipairs(todo) do if not it._done then _todoByPath[it.p] = it end end
				local _byPack, _needPacks = {}, {}
				for _, f in ipairs(_pm.files) do
					local it = f and f.p and _todoByPath[f.p]
					if it and type(f.k) == "number" and type(f.o) == "number" and type(f.n) == "number" then
						if not _byPack[f.k] then _byPack[f.k] = {}; _needPacks[#_needPacks + 1] = f.k end
						table.insert(_byPack[f.k], { it = it, o = f.o, n = f.n })
					end
				end
				if #_needPacks > 0 then
					local _pkIdx, _pkActive = 1, 0
					local _packAbort = false   -- V4.4.x: set if packs are served gzipped (_pm.gzipped) but arrived UNdecompressed → bail the whole pack phase to the per-file fallback (don't waste bandwidth on packs this client can't slice)
					local function _packWorker()
						_pkActive = _pkActive + 1
						pcall(function()
							while true do
								task.wait()
								if _packAbort or System._sessionAlive == false then break end
								local w = _pkIdx; if w > #_needPacks then break end; _pkIdx = w + 1
								local packK = _needPacks[w]
								local packName = _pm.packs[packK + 1]  -- k is 0-based; Lua array is 1-based
								if type(packName) == "string" and packName ~= "" then
									local _url = _packBase .. packName:gsub(" ", "%%20")
									local _blob = _fetch(_url)
									if not (_blob and #_blob > 0) then task.wait(0.5); _blob = _fetch(_url) end  -- retry once
									if _blob and #_blob > 0 then
										local _blobLen = #_blob
										-- V4.4.x: packs are served UNCOMPRESSED (Cloudflare gzips them on the wire and HttpGet
										-- decompresses transparently). If the blob arrived SMALLER than its largest (offset+len),
										-- this client's HTTP layer did NOT decompress → abort the ENTIRE pack phase to the per-file
										-- path (which is served the same way but each file self-verifies). One wasted pack max.
										local _expLen = 0
										for _, e in ipairs(_byPack[packK]) do if (e.o + e.n) > _expLen then _expLen = e.o + e.n end end
										if _blobLen < _expLen then _packAbort = true; break end
										for _, e in ipairs(_byPack[packK]) do
											if not e.it._done and e.o >= 0 and e.n > 0 and (e.o + e.n) <= _blobLen then
												-- slice this file out of the pack by byte offset (1-indexed sub, binary-safe)
												local piece = string.sub(_blob, e.o + 1, e.o + e.n)
												-- size-check exactly like the per-file path; a bad slice just retries per-file
												if #piece == e.n and (not e.it.s or #piece == e.it.s) then
													local wok = pcall(env.writefile, e.it.localPath, piece)
													-- V4.3.555 parity: dual-write VNS .mesh to _vns_uniq/ (Xeno basename-collision bypass)
													if wok and e.it.p and e.it.p:match("^_vns/.+%.mesh$") then
														pcall(env.writefile, "RClothesContent/_vns_uniq/" .. e.it.localPath:gsub("[/\\]", "_"), piece)
													end
													if wok then
														e.it._done = true
														doneCount = doneCount + 1; _lastFile = e.it.p; _lastFileSize = e.it.s or e.n
													end
												end
											end
										end
										_blob = nil  -- release the pack body ASAP (peak mem ≈ one pack per active worker)
										_maybeUpdateOverlay()
									end
								end
							end
						end)
						_pkActive = _pkActive - 1
					end
					-- Packs share the same five-mobile/eight-desktop transport bound.
					for _ = 1, math.max(1, math.min(MAX_PARALLEL, #_needPacks)) do task.spawn(_packWorker) end
					while _pkActive > 0 do task.wait(0.1) end
					pcall(Function.diag, "install.pack_phase", { packs = #_needPacks, done = doneCount, total = #todo })
				end
			end
		end

		for _ = 1, math.min(MAX_PARALLEL, #todo) do task.spawn(worker) end

		-- Block until all workers exit.
		while activeWorkers > 0 do task.wait(0.1) end
		if System._sessionAlive == false then
			System._installInProgress = false
			if overlayGui then pcall(function() overlayGui:Destroy() end) end
			return
		end
		if doneCount > 0 then
			System._meshContentGeneration = (System._meshContentGeneration or 0) + 1
		end
		-- V4.4.x: all bytes are down + written → tell the Aurora loader the "installing" stage began.
		if onProgress then pcall(onProgress, doneCount, #todo, failCount, _lastFile, _lastFileSize, "installing") end
		-- V4.3.492: brand bar shows 50% at install completion (preload drives 50..100%).
		if _RC_Brand and _RC_Brand.exists() then _RC_Brand.setProgress(50) end
		-- V4.3.436: final overlay refresh to show 100% completion state (since the
		-- throttle may have skipped the last update).
		if overlayText then
			overlayText.Text = string.format("Installing RoClothes assets...  %d / %d", doneCount, #todo) .. ((failCount > 0) and ("  (" .. failCount .. " failed)") or "")
		end
		if overlayBar then overlayBar.Size = UDim2.new(math.clamp(doneCount / math.max(#todo, 1), 0, 1), 0, 1, 0) end  -- final push to 100%

		-- Step 7: write the cache marker only if everything succeeded. A partial
		-- install MUST NOT mark itself as complete - next run needs to retry the misses.
		-- V4.3.257: failure now shows a friendly popup with Discord report link
		-- (in addition to console warn for devs).
		if overlayGui then pcall(function() overlayGui:Destroy() end) end
		-- PHASE 10 (PART B): clear the merged GUI's installer overlay too (on a warm
		-- Redownload the GUI exists, so its themed progress overlay was being shown by
		-- _maybeUpdateOverlay; remove it on completion in lock-step with overlayGui).
		-- Guarded: System.hideOverlay only exists post-GUI-build (no-op on first run).
		-- V4.4.x: final push to the onProgress caller (Aurora first-run loader) so it lands on 100%;
		-- when onProgress owns the UI, DON'T also clear the themed toast (we never showed one).
		if onProgress then
			pcall(onProgress, doneCount, #todo, failCount)
		elseif System.hideOverlay then
			pcall(System.hideOverlay)
		end
		System._installInProgress = false  -- V4.3.441: clear in-progress flag
		if failCount == 0 then
			-- V4.3.558: routed through _writeMarker (Volt-safe temp + direct-write
			-- fallback). The old `MARKER_PATH..".tmp"` write was rejected by Volt
			-- ("Illegal path"), so a fully-successful install still left no marker →
			-- intro skipped + cold-path-every-launch. See _writeMarker rationale above.
			_writeMarker(manifestVersion)
			-- V4.3.421: invalidate the script-side rbxm cache. The auto-installer just (see Changelog for full rationale)
			pcall(function()
				local _RS = game:GetService("ReplicatedStorage")
				local _holder = _RS:FindFirstChild("_RCVnsModelCache")
				if _holder then
					for _, _c in ipairs(_holder:GetChildren()) do
						pcall(function() _c:Destroy() end)
					end
				end
			end)
		else
			-- V4.3.267: capture WHICH files failed (not just the count). Users were reporting
			-- "4-6 items fail to download" but couldn't tell us which - now the popup body
			-- lists up to 6 paths inline, AND a full file is written to
			-- `RClothesContent/last_install_failures.txt` so users can copy/paste the
			-- complete list into a Discord bug report.
			-- V4.3.556: non-dotfile name (was `.last_install_failures.txt`). Volt and
			-- other dot-incapable executors silently failed to write the dotfile, so
			-- their users never got the failure log - the exact users most likely to
			-- be hitting install failures worth reporting.
			local _failureSummary
			do
				local _lines = {}
				for _, p in ipairs(failedPaths) do table.insert(_lines, p) end
				_failureSummary = table.concat(_lines, "\n")
				pcall(env.writefile, "RClothesContent/last_install_failures.txt",
					"manifest=" .. manifestVersion .. "\n"
					.. "failed=" .. failCount .. "\n"
					.. "ok=" .. doneCount .. "\n"
					.. "paths:\n" .. _failureSummary)
			end
			warn(string.format(
				"[RoClothes] Content install: %d ok, %d failed. Failed paths:",
				doneCount, failCount
			))
			for _, p in ipairs(failedPaths) do warn("  " .. p) end
			-- V4.5.17: name ONE example for context, then point the user straight at the FULL log file to send us
			-- (the complete list + per-file reasons live in last_install_failures.txt - exactly what we need to
			-- diagnose their device). The old 6-path inline dump overflowed the card; the .txt carries the detail.
			local _eg = (failedPaths[1] and (" (e.g. " .. tostring(failedPaths[1]):sub(1, 52) .. ")")) or ""
			_showInstallError(
				string.format("%d of %d assets failed to download%s.\nThe script retries automatically on next launch.", failCount, #todo, _eg),
				"RClothesContent/last_install_failures.txt"
			)
		end
	end

	-- V4.3.254: kill prior breakers FIRST, BEFORE any model-loading or asset work. (see Changelog for full rationale)
	-- V4.3.167.6: BREAKER name is randomized per session (anti-fingerprint), so
	-- V4.3.217: also destroy orphan __m2f_* shadow folders from prior sessions
	for _, _c in ipairs(game.Workspace:GetChildren()) do
		if _c:IsA("Folder") and _c:GetAttribute("_rcBreaker") then
			pcall(function() _c:Destroy() end)
		elseif _c.Name:sub(1, 6) == "__m2f_" then
			pcall(function() _c:Destroy() end)
		end
	end

	-- V4.3.262 fix part 2/3: create OUR BREAKER folder immediately, BEFORE any (see Changelog for full rationale)
	local BREAKER = Instance.new("Folder", game.Workspace)
	BREAKER.Name = System.BreakerName
	BREAKER.Archivable = false
	BREAKER:SetAttribute("_rcBreaker", true)
	System._sessionAlive = true

	-- V4.3.254: defensive boot scrub for orphan per-frame connections that escaped
	-- both AllConnect and GlobalMaid in a prior crashed session. `getconnections` is
	-- a sUNC standard executor API; pcall-guarded since some restricted environments
	-- block it. Only disconnects callbacks whose function source belongs to OUR script.
	pcall(function()
		local _gc = getconnections
		if not _gc then return end
		local _RS = game:GetService("RunService")
		-- V4.3.504: one-shot warn flag - restricted-env getfenv failures are common
		-- enough that we shouldn't spam, but a single visibility ping helps audits.
		local _warnedGetfenv = false
		-- V4.5.17: also scrub leaked INPUT + VIEWPORT connections from a prior instance (the HSV picker's
		-- UIS.InputChanged/Ended and the Multi-Panel Camera:ViewportSize conns are cleaned only by destroyUI, so
		-- a double-EXECUTE - which fires only BREAKER.Destroying, not destroyUI - would stack them across re-execs).
		local _scrubSignals = { _RS.Heartbeat, _RS.RenderStepped, _RS.Stepped }
		pcall(function() local _UIS = game:GetService("UserInputService"); table.insert(_scrubSignals, _UIS.InputBegan); table.insert(_scrubSignals, _UIS.InputChanged); table.insert(_scrubSignals, _UIS.InputEnded); table.insert(_scrubSignals, _UIS.TouchMoved) end)
		pcall(function() local _cam = workspace.CurrentCamera; if _cam then table.insert(_scrubSignals, _cam:GetPropertyChangedSignal("ViewportSize")) end end)
		for _, _signal in ipairs(_scrubSignals) do
			local _ok, _conns = pcall(_gc, _signal)
			if _ok and type(_conns) == "table" then
				for _, _conn in ipairs(_conns) do
					-- Best-effort identify our own script's connections via getfenv on
					-- the callback. Not 100% reliable but catches the common case.
					-- V4.3.504: explicit inner pcall around JUST the getfenv call so a
					-- restricted-env throw can't propagate out of this iteration.
					local _fn = _conn.Function or _conn.ThreadFunction
					local _src = nil
					if _fn then
						local _okF, _envOrErr = pcall(getfenv, _fn)
						if _okF then
							_src = _envOrErr and _envOrErr.script or nil
						elseif not _warnedGetfenv then
							_warnedGetfenv = true
							warn("[RoClothes] boot-scrub: getfenv blocked by restricted env; per-connection skip. (" .. tostring(_envOrErr) .. ")")
						end
					end
					if _src == script then
						pcall(function() _conn:Disconnect() end)
					end
				end
			end
		end
	end)

	-- V4.3.502: the scrub above disconnects script-owned Heartbeats including
	-- the brand bounce installed at L1005 via _RC_Brand.build(). Re-arm it so
	-- the letters don't go static for the rest of boot on a re-execute.
	pcall(function()
		if _RC_Brand and _RC_Brand.rebuildBounce then
			_RC_Brand.rebuildBounce()
			Function.diag("intro.brand_rebuild", { count = 1 })
		end
	end)

	-- V4.3.305: call SYNCHRONOUSLY (no task.spawn at the call site). The (see Changelog for full rationale)
	-- V4.4.0: intro frames re-encoded WebP -> JPG (WebP stopped decoding on mobile) + re-hosted on the CDN,
	-- so the intro plays on ALL platforms again. The temporary mobile intro-skip was removed. See PATH_FMT (.jpg).
	-- [V3 MERGE] 591-frame video intro RETIRED - skip playback; tear down any brand overlay so nothing lingers.
	pcall(function() if _RC_Brand and _RC_Brand.destroy then _RC_Brand.destroy() end end)  -- was: _playIntroVideo(System.RCTag)

	-- V4.3.429: spawn the auto-installer ASYNC so it doesn't block the boot thread.
	-- Pre-fix `Function.InstallContentAssets()` was called synchronously on the boot
	-- thread, and its internal `while activeWorkers > 0 do task.wait(0.1) end` at
	-- L3493 (after spawning 8 parallel HTTP workers) parked the calling thread until
	-- ALL ~463 files (~120MB total) finished downloading. On a fresh Roblox session
	-- with no cached content this freeze can last tens of seconds to minutes, during
	-- which the entire main GUI / character setup / SmartBone API load are blocked.
	-- User reported "I freeze when I run it fresh in a new Roblox session" - caught
	-- by cold-boot-freeze audit 2026-05-14 (HIGH/HIGH).
	-- Downstream consumers (CharacterExecute body-mesh paths, rbxm loaders) already
	-- have a `rbxasset://` fallback chain in `_getVnsModel` (L8049-8052) when
	-- `getcustomasset` returns no usable URL - if a body type's rbxm isn't yet
	-- downloaded, the load attempt will simply fail and the body falls back to
	-- whatever non-SmartBone variant works. The `System._contentInstalled` flag is
	-- published below for any future consumer that wants to wait on the marker.
	-- A subsequent re-execute (after the install completes once) will find the
	-- marker file and skip the install entirely (fast path).
	System._contentInstalled = false
	-- V4.3.486: on FIRST-RUN (marker absent) install runs SYNCHRONOUSLY so the
	-- rest of the script (GUI build, data fetch, character setup) doesn't start
	-- until install finishes. Pre-fix V4.3.429's unconditional async install ran
	-- concurrently with the heavy boot work - fine for the 463-file install
	-- it was designed for, but on the current 1161-file install path the
	-- overlap was long enough that the user saw a partly-built GUI + a frozen
	-- "Not Responding" Roblox window mid-install. User report 2026-05-19 after
	-- deleting RClothesContent/ to simulate first-time install: "not only did
	-- GUI load which shouldnt happen, it also freeze the entire game, maybe
	-- crashed it too." On WARM-RUN (marker present) the install returns near-
	-- instantly via the existing fast-path, so the async-wrapped behavior is
	-- preserved (zero impact on existing users). Yielding worker loop above
	-- prevents Lua VM saturation even in sync mode.
	local _firstRunInstall = not (_rcMarkerExists(env.isfile))
	if _firstRunInstall then
		-- V4.3.504: install-generation counter - only the latest invocation may publish
		-- _contentInstalled. Stale concurrent installs (e.g. Redownload pressed before
		-- prior install finished) silently drop their result instead of overwriting.
		System._installGen = (System._installGen or 0) + 1
		local _myGen = System._installGen
		-- V4.4.x DEMO LOADER WIRING: DEFER this first-run download into a runner the Vampiric Aurora
		-- Type-1 loader (built later at _buildV3GUI L9668 → A.playIntro) calls at intro time, driving it
		-- with REAL progress (onProgress) instead of the old fake 8s sim + raw grey pill. SAFE ordering:
		-- warm-run (else-branch) already runs boot without blocking on install; running the download at
		-- INTRO time - after the GUI is built, behind the full-screen loader whose Skip stays LOCKED
		-- until this completes - avoids the V4.3.486 concurrent-GUI-build freeze and gates anything that
		-- needs content. Idempotent + re-entry-guarded; a backstop after L9668 runs it if the intro didn't.
		System._firstRunInstallPending = true
		System._runFirstRunInstall = function(onProgress)
		if System._firstRunInstallDone then return true end
		if System._firstRunInstallRunning then return false end
		System._firstRunInstallRunning = true
		local ok, err = pcall(Function.InstallContentAssets, true, onProgress)  -- V4.4.x: forceAll on first run → skip the wasted per-file verify + _vns_uniq scan (folder already exists by boot, so the isfolder check couldn't); everything's missing anyway
		-- V4.3.502: only flag content-installed when BOTH the pcall succeeded AND
		-- the marker file actually landed on disk. Pre-fix the flag was set
		-- unconditionally after the pcall, so a partial install (failCount > 0,
		-- marker never written) still reported as installed to downstream
		-- consumers - they'd then skip their own fallback chain and crash on
		-- missing rbxm. The marker check at L4401 was already correct for the
		-- intro replay; this aligns the published flag with the same gate.
		local _markerOkEarly = _rcMarkerExists(env.isfile) or false
		if _myGen == System._installGen then
			System._contentInstalled = (ok and _markerOkEarly) and true or false
		end
		if not ok then
			warn("[RoClothes] InstallContentAssets failed: " .. tostring(err))
			Function.diag("crash.outer_pcall", { fn = "InstallContentAssets", err = tostring(err):sub(1, 256) })
		end
		do
			local _instDur = (type(_diagInstallStart) == "number") and (os.clock() - _diagInstallStart) or -1
			Function.diag("install.complete", { ok = ok and true or false, markerOk = _markerOkEarly and true or false, duration_s = _instDur, failCount = 0 })
			-- 3s threshold for the perf.slow_apply event per §5.7.
			if _instDur > 3 then Function.diag("perf.slow_apply", { kind = "install_first_run", duration_s = _instDur }) end
		end
		if not _markerOkEarly then
			Function.diag("install.marker_missing_after_install", { ok = ok and true or false, path = "first_run" })
		end
		-- V4.3.487: replay the intro after first-run sync install. The earlier
		-- _playIntroVideo() call fired BEFORE install started; on first-run the
		-- marker was missing so the intro bailed at the marker check.
		-- V4.3.496: ALSO gate the replay on the marker file actually existing.
		-- Audit Pass A #2: a partial install (failCount > 0) leaves the marker
		-- UNWRITTEN but `ok` is still true (pcall caught nothing - the function
		-- returned cleanly with failure). Re-invoking the intro then bails at
		-- its marker gate, leaving `_RC_Brand` alive on screen forever behind
		-- the eventual GUI. Now we re-invoke only when both `ok` AND the
		-- marker file landed on disk; otherwise destroy the brand explicitly
		-- so it doesn't linger.
		local _markerOk = _rcMarkerExists(env.isfile)
		if ok and _markerOk then
			-- [V3 MERGE] video intro RETIRED - was: pcall(_playIntroVideo, System.RCTag). Just ensure the brand overlay is gone.
			pcall(function() if _RC_Brand and _RC_Brand.destroy then _RC_Brand.destroy() end end)
		else
			-- Install didn't fully succeed → no intro will run → tear down the
			-- global brand explicitly so it doesn't sit on screen indefinitely.
			pcall(function() if _RC_Brand and _RC_Brand.destroy then _RC_Brand.destroy() end end)
		end
		System._firstRunInstallDone = true
		System._firstRunInstallPending = false
		System._firstRunInstallRunning = false
		return (ok and _markerOkEarly) and true or false
		end  -- close System._runFirstRunInstall (deferred; driven by the Aurora loader at intro time)
	else
		-- V4.3.504: capture install generation BEFORE the spawn so stale async warm-runs
		-- (Redownload mid-flight) can't clobber a newer install's flag.
		System._installGen = (System._installGen or 0) + 1
		local _myGen = System._installGen
		task.spawn(function()
			local ok, err = pcall(Function.InstallContentAssets)
			-- V4.3.503: warm-run path now mirrors first-run marker gate (L4430). Without
			-- this, every returning user marks content installed even when the disk lost
			-- the manifest, causing silent state divergence.
			local _markerOkWarm = _rcMarkerExists(env.isfile)
			if _myGen == System._installGen then
				System._contentInstalled = (ok and _markerOkWarm) and true or false
			end
			if not ok then
				warn("[RoClothes] InstallContentAssets failed: " .. tostring(err))
				Function.diag("crash.outer_pcall", { fn = "InstallContentAssets(warm)", err = tostring(err):sub(1, 256) })
			end
			Function.diag("install.complete", { ok = ok and true or false, markerOk = _markerOkWarm and true or false, path = "warm" })
			if not _markerOkWarm then
				Function.diag("install.marker_missing_after_install", { ok = ok and true or false, path = "warm" })
			end
		end)
	end

	-- V4.3.310: pre-warm DISABLED. The pre-warm targeted SB body-type meshes for (see Changelog for full rationale)

	-- V4.3.218: aggressive cleanup of any stale VNS state from prior script sessions
	-- (Volt and similar executors don't always kill old script contexts on re-execute,
	-- so prior sessions' VNS modules + CharacterAdded handlers can keep running).
	pcall(function()
		local _cg = game:GetService("CoreGui")
		for _, c in ipairs(_cg:GetChildren()) do
			if c.Name == "_RCVns" or c.Name:sub(1,6) == "_RCVns" then
				pcall(function() c:Destroy() end)
			end
		end
		-- Current VNS rigs are character-owned; UUID names do not establish ownership.
	end)

	-- V4.3.218: body-part restoration. Runs on boot AND every CharacterAdded.
	-- Defined as Function.RestoreBodyParts (no local register cost - RoClothes is
	-- close to Luau's 200-local cap and direct locals here pushed it over).
	-- Restores Transparency=0 + LocalTransparencyModifier=0 on the local player's
	-- body parts. Defends against zombie VNS handlers from prior sessions.
	Function.RestoreBodyParts = function()
		pcall(function()
			local _restoreNames = {
				"Torso", "UpperTorso", "LowerTorso",
				"Left Arm", "LeftUpperArm", "LeftLowerArm", "LeftHand",
				"Right Arm", "RightUpperArm", "RightLowerArm", "RightHand",
				"Left Leg", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
				"Right Leg", "RightUpperLeg", "RightLowerLeg", "RightFoot",
				"Head"
			}
			local _player = game:GetService("Players").LocalPlayer
			if _player and _player.Character then
				for _, n in ipairs(_restoreNames) do
					local p = _player.Character:FindFirstChild(n)
					if p and p:IsA("BasePart") then
						p.Transparency = 0
						p.LocalTransparencyModifier = 0
					end
				end
			end
		end)
	end
	Function.RestoreBodyParts()
	-- Connection stored on System (not a local) for the same register-budget reason.
	-- Disconnected by BREAKER.Destroying via System._bodyRestoreConn.
	pcall(function()
		System._bodyRestoreConn = game:GetService("Players").LocalPlayer.CharacterAdded:Connect(function()
			task.wait(0.5)
			Function.RestoreBodyParts()
		end)
	end)

	-- V4.3.466: capture-detection feature. Listens to CaptureService for the
	-- Roblox built-in capture menu (Esc → Capture → Take Photo / Take Video) and
	-- displays UI consequences. Does NOT detect OBS/ShadowPlay/Game Bar/Snipping
	-- Tool/mobile system recording - those are OS-level and invisible to Lua VM.
	-- For coverage rationale + alternatives considered see ro_clothes.md V4.3.466
	-- audit notes.
	-- VIDEO: 25-second grace period after CaptureBegan(Video), then black overlay
	-- with red warning text. Modal input-eater locks mouse to screen. No manual
	-- dismiss - only CaptureEnded(Video) removes it. If user stops recording
	-- during the grace window, overlay is skipped entirely (rewards short clips,
	-- punishes sustained recording).
	-- SCREENSHOT: each CaptureBegan(Photo) adds a popup card at the top of a
	-- vertical stack. Newest at top pushes existing cards down. Each card
	-- auto-dismisses 5s after its own creation; remaining cards reflow upward.
	-- No limit (intentional - sane users don't screenshot 100 times).
	do
		local _TS = game:GetService("TweenService")
		local _capOk, CaptureService = pcall(game.GetService, game, "CaptureService")
		if not _capOk or not CaptureService then
			warn("[RoClothes] CaptureService unavailable - capture detection disabled.")
		else
			local _hostParent = (gethui and gethui()) or game:GetService("CoreGui")
			-- V4.3.467: Wipe any prior session's host. Pattern-match both the legacy
			-- fixed name AND the new randomized "_RC_CD_<N>" form (since prior session
			-- used a different random N).
			-- V4.3.474: extended sweep to cover V4.3.471 banner host (`_RC_NX_<N>`) and
			-- V4.3.470 Lighting tint (`_RC_LX_<N>` under game.Lighting). Pre-fix a prior
			-- session that crashed mid-attacker-mode would leave the stale red banner +
			-- Lighting tint visible to the new session - user sees red wash and warning
			-- card before they've done anything to trigger detection.
			-- V4.3.477: sweep BOTH gethui() AND CoreGui. If a prior session ran with a
			-- different executor gethui() and the current session falls back to CoreGui
			-- (or vice versa), the prior banner/host could live on the OTHER surface and
			-- survive a single-surface sweep. Also extend sweep to legacy intro splash
			-- and install popup that only get cleaned up by their own builders today.
			do
				local _sweepParents = {}
				if gethui then
					local _ok, _g = pcall(gethui)
					if _ok and _g then table.insert(_sweepParents, _g) end
				end
				table.insert(_sweepParents, game:GetService("CoreGui"))
				local _seen = {}
				for _, _parent in ipairs(_sweepParents) do
					if not _seen[_parent] then
						_seen[_parent] = true
						for _, _c in ipairs(_parent:GetChildren()) do
							local _nm = _c.Name
							if _nm == "_RC_CaptureDetection"
								or _nm:sub(1, 7) == "_RC_CD_"
								or _nm:sub(1, 7) == "_RC_NX_"
								or _nm == "_RoClothesIntroCover"
								or _nm == "_RoClothesInstallPopup"
							then
								pcall(function() _c:Destroy() end)
							end
						end
					end
				end
				-- V4.3.478: pcall-wrap Lighting children iteration. A hostile script could
				-- poison __index on a Lighting child or otherwise make Name access throw;
				-- without pcall the throw aborts the surrounding settings-load block.
				pcall(function()
					for _, _c in ipairs(game:GetService("Lighting"):GetChildren()) do
						if _c.Name:sub(1, 7) == "_RC_LX_" then
							pcall(function() _c:Destroy() end)
						end
					end
				end)
			end
			-- V4.3.478: REPLACED V4.3.477's global math.randomseed call with a scoped
			-- Random.new instance. Pre-fix the seed mutated process-wide RNG state,
			-- affecting downstream math.random consumers throughout the script (audit
			-- pass A LOW-1 + pass C MED-2 consensus). Scoped Random.new keeps the
			-- collision-resistant name generation without disturbing global RNG.
			-- V4.3.496: tick() nil-guard. Audit Pass D #11: `tick()` is deprecated
			-- and returns nil on newer executor builds → `nil * 1e3` aborts the
			-- whole capture-detection block. Mirror the L3232 pattern.
			local _RC_CapRand = Random.new(os.clock() * 1e6 + (((tick and tick()) or os.clock()) * 1e3))
			-- V4.3.467: randomize the host GUI name per session so a user can't FindFirstChild
			-- it by a known literal. Layered with the .Destroying auto-respawn below: forces
			-- attacker to either scan all CoreGui children or hook Instance.new, not just
			-- :Destroy() a named child. Doesn't stop a determined hooker but raises the bar.
			local _hostName = "_RC_CD_" .. tostring(_RC_CapRand:NextInteger(100000000, 999999999))
			-- V4.3.467: hoist _tornDown above _rebuildHost so the .Destroying handler
			-- closure can read the latest value as an upvalue (the teardown function
			-- below sets _tornDown = true; Lua's upvalue-by-reference means closures
			-- defined here see the updated value).
			local _tornDown = false
			local _host  -- forward-declared so the .Destroying handler closure can reassign
			local _rebuildHost
			-- V4.3.468: forward-declared so the .Destroying handler inside _rebuildHost can
			-- resolve _onHostDestroyed as an upvalue (assigned below after _rebuildHost def)
			local _onHostDestroyed
			_rebuildHost = function()
				if _tornDown then return end
				local h = Instance.new("ScreenGui")
				h.Name = _hostName
				h.IgnoreGuiInset = true
				h.ResetOnSpawn = false
				h.DisplayOrder = 2000000  -- above intro splash (999998) + install popup (1000000)
				h.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
				h.Parent = _hostParent
				_host = h
				System._captureDetectionHost = h
				-- V4.3.467 A: auto-respawn on Destroying. Anyone (or any script) calling
				-- :Destroy() on the host triggers this; we rebuild a fresh ScreenGui with
				-- the same random name. Active state (video overlay / shot stack) is lost
				-- since the children were destroyed - defensive nil-checks in the show
				-- functions handle the gap until the next CaptureBegan event repopulates.
				-- V4.3.468: escalation. Destruction events feed into _onHostDestroyed which
				-- counts them in a sliding 10s window. >5 destroys triggers attacker mode:
				-- stop respawning (no CPU-burn loop) and switch to notification spam via
				-- StarterGui:SetCore (different attack surface than ScreenGui destruction).
				pcall(function()
					h.Destroying:Connect(function()
						if _tornDown then return end
						_onHostDestroyed()
					end)
				end)
			end

			-- V4.3.468: anti-griefing escalation state (forward-declared so _rebuildHost's
			-- .Destroying closure can reference _onHostDestroyed).
			local _DESTROY_THRESHOLD = 5     -- destructions
			local _DESTROY_WINDOW    = 10    -- seconds - sliding-window size
			local _ATTACKER_IDLE     = 30    -- seconds with no destroy to exit attacker mode
			local _destroyTimes      = {}
			-- V4.3.504: explicit tail pointer - niling head entries makes #_destroyTimes UB.
			local _destroyTail       = 0
			-- V4.3.503: head-pointer prune to avoid O(n^2) table.remove under sustained attack.
			local _destroyHead       = 1
			local _activeAttackerMode = false
			local _lastDestroyTime   = 0
			-- V4.3.473 HOTFIX: V4.3.472 declared these two below at L~4236 (with VIDEO state),
			-- but referenced them at L4171/4172/4194 (inside _onHostDestroyed + idle watcher)
			-- which are lexically ABOVE the declarations. Both references bound to nil globals.
			-- Net effect: arithmetic-on-nil throw in idle watcher (silently swallowed by task
			-- scheduler) and concat-with-nil throw in the warn (before _startNotifSpam call,
			-- so spam NEVER STARTED). V4.3.470 Lighting tint + V4.3.471 banner = silently dead
			-- in V4.3.472. Caught by bug-hunter audit 2026-05-18. Hoisted to outer scope here.
			local _ATTACKER_STICKY_MIN   = 60    -- seconds; attacker-mode warnings min visible
			local _attackerModeStartTime = 0
			-- V4.3.471: replaced SetCore("SendNotification") with a custom full-width banner.
			-- Per user feedback: Roblox built-in notification was small/croppable. New banner
			-- spans full screen width, top of viewport, persists while attacker mode active.
			-- Lives in its OWN ScreenGui (separate random name from main host) so attacker
			-- has to find AND destroy a third surface (host + Lighting + Banner). All three
			-- auto-respawn on Destroying.
			local _bannerName = "_RC_NX_" .. tostring(_RC_CapRand:NextInteger(100000000, 999999999))
			local _bannerHost = nil
			local _bannerTweens = {}
			-- V4.3.470: Lighting effect for attacker-mode response. Sits in game.Lighting
			-- (different attack surface than ScreenGui/CoreGui) and tints EVERY pixel of
			-- the game world red - can't be cropped out of a recording without editing
			-- every frame. Auto-respawns on .Destroying via the same pattern as the host.
			-- User feedback: SetCore notifications were "small and easily cropped" -
			-- Lighting tint is the screen-wide alternative.
			local _Lighting       = game:GetService("Lighting")
			local _lightingName   = "_RC_LX_" .. tostring(_RC_CapRand:NextInteger(100000000, 999999999))
			local _lightingEffect = nil
			local _lightingTween  = nil
			-- V4.3.478: per-surface respawn timestamps for the time-debounced auto-respawn.
			-- Cap respawn rate at ~10/sec per surface (every 100ms minimum). Replaces V4.3.477's
			-- broken shared-counter gate that silently disabled respawn entirely.
			local _lastLightingRespawn = 0
			local _lastBannerRespawn   = 0

			local function _spawnLightingTint()
				if _lightingEffect or _tornDown or not _activeAttackerMode then return end
				local cc = Instance.new("ColorCorrectionEffect")
				cc.Name        = _lightingName
				cc.TintColor   = Color3.fromRGB(255, 100, 100)  -- red wash
				cc.Saturation  = -0.3
				cc.Brightness  = 0
				cc.Contrast    = 0.4
				cc.Enabled     = true
				cc.Parent      = _Lighting
				_lightingEffect = cc
				-- Pulse tween: oscillates intensity so the warning visually breathes
				pcall(function()
					_lightingTween = _TS:Create(cc,
						TweenInfo.new(1, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
						{TintColor = Color3.fromRGB(255, 40, 40), Brightness = -0.3, Contrast = 0.6}
					)
					_lightingTween:Play()
				end)
				-- Auto-respawn on Destroying with per-surface time-based throttle.
				-- V4.3.478: REPLACED V4.3.477's broken shared-counter gate. Pre-fix logic was
				-- `if _activeAttackerMode and #_destroyTimes < _DESTROY_THRESHOLD` - but
				-- banner/Lighting are ONLY spawned AFTER attacker mode triggers (which means
				-- `#_destroyTimes >= _DESTROY_THRESHOLD` is already true), so the second
				-- condition was always false → respawn NEVER fired → attacker's single
				-- :Destroy() killed the surface for the entire sticky window. Defeated the
				-- whole V4.3.470/471 auto-respawn design. Audit round 2 pass B caught it.
				-- New approach: per-surface monotonic-time debounce. Cap respawn to ~10/sec
				-- per surface (every 100ms minimum). Attacker still pays a destroy-loop CPU
				-- cost on their side; we pay a bounded respawn cost on ours. Both sides
				-- spin but the visual warning is preserved.
				pcall(function()
					cc.Destroying:Connect(function()
						if _tornDown then return end
						_lightingEffect = nil
						-- V4.3.477: Cancel + Destroy (V4.3.424 rule). Pre-fix orphan tween
						-- held a strong ref to the destroyed effect, blocking GC.
						if _lightingTween then pcall(function() _lightingTween:Cancel(); _lightingTween:Destroy() end); _lightingTween = nil end
						-- V4.3.478: per-surface time-debounced respawn (replaces V4.3.477's
						-- broken shared-counter gate). NOTE: removed the V4.3.477 _onHostDestroyed()
						-- call - feeding destroys from banner/Lighting into the same counter
						-- as the host artificially accelerated attacker-mode entry (1 user
						-- destroy of "everything" = 3 counter entries).
						if _activeAttackerMode then
							local _now = os.clock()
							if (_now - _lastLightingRespawn) > 0.1 then
								_lastLightingRespawn = _now
								task.defer(_spawnLightingTint)
							end
						end
					end)
				end)
			end

			local function _despawnLightingTint()
				-- V4.3.477: Cancel + Destroy (V4.3.424 rule)
				if _lightingTween then pcall(function() _lightingTween:Cancel(); _lightingTween:Destroy() end); _lightingTween = nil end
				if _lightingEffect then pcall(function() _lightingEffect:Destroy() end); _lightingEffect = nil end
			end

			-- V4.3.471: forward-declared so .Destroying closure can resolve as upvalue
			local _spawnBanner

			local function _despawnBanner()
				-- V4.3.477: Cancel + Destroy (V4.3.424 rule)
				for _, tw in ipairs(_bannerTweens) do pcall(function() tw:Cancel(); tw:Destroy() end) end
				_bannerTweens = {}
				if _bannerHost then
					pcall(function() _bannerHost:Destroy() end)
					_bannerHost = nil
				end
			end

			_spawnBanner = function()
				if _bannerHost or _tornDown or not _activeAttackerMode then return end
				local hostParent = (gethui and gethui()) or game:GetService("CoreGui")
				local gui = Instance.new("ScreenGui")
				gui.Name = _bannerName
				gui.IgnoreGuiInset = true
				gui.ResetOnSpawn = false
				gui.DisplayOrder = 2000001  -- above main capture host (2000000)
				gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
				gui.Parent = hostParent
				_bannerHost = gui

				-- Full-width banner at TOP of screen, 8% viewport height
				local banner = Instance.new("Frame", gui)
				banner.AnchorPoint = Vector2.new(0.5, 0)
				banner.Position = UDim2.fromScale(0.5, 0)
				banner.Size = UDim2.new(1, 0, 0.08, 0)
				banner.BackgroundColor3 = Color3.fromRGB(120, 20, 20)
				banner.BackgroundTransparency = 0.1
				banner.BorderSizePixel = 0
				banner.ZIndex = 100
				local _bc = Instance.new("UICorner", banner); _bc.CornerRadius = UDim.new(0, 14)  -- V4.5.16: rounded for a cleaner notification-bar look (kept the stark red deterrent + pulse intact)
				local stroke = Instance.new("UIStroke", banner)
				stroke.Color = Color3.fromRGB(255, 50, 50)
				stroke.Thickness = 3
				stroke.Transparency = 0.1

				local label = Instance.new("TextLabel", banner)
				label.AnchorPoint = Vector2.new(0.5, 0.5)
				label.Position = UDim2.fromScale(0.5, 0.5)
				label.Size = UDim2.new(0.95, 0, 0.75, 0)
				label.BackgroundTransparency = 1
				label.Text = "⚠ RECORDING DETECTED - Sharing screenshot or recording of RoClothes:Krul content is prohibited"
				label.TextColor3 = Color3.fromRGB(255, 230, 230)
				label.Font = Enum.Font.GothamBold
				label.TextScaled = true
				label.ZIndex = 101

				-- Pulse the stroke + background in sync with the Lighting tint cadence (1s sine)
				pcall(function()
					local t1 = _TS:Create(stroke,
						TweenInfo.new(0.7, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
						{Color = Color3.fromRGB(255, 100, 100), Thickness = 6}
					)
					local t2 = _TS:Create(banner,
						TweenInfo.new(0.7, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
						{BackgroundColor3 = Color3.fromRGB(180, 30, 30)}
					)
					t1:Play(); t2:Play()
					_bannerTweens = {t1, t2}
				end)

				-- Auto-respawn on Destroying with per-surface time-debounced throttle.
				-- V4.3.478: REPLACED V4.3.477's broken shared-counter gate (see Lighting
				-- handler above for full rationale). Cap respawn to ~10/sec via 100ms
				-- monotonic-time debounce. Removed the V4.3.477 _onHostDestroyed() call -
				-- banner destroys are now independent from the host's escalation counter.
				pcall(function()
					gui.Destroying:Connect(function()
						if _tornDown then return end
						_bannerHost = nil
						-- V4.3.477: Cancel + Destroy (V4.3.424 rule)
						for _, tw in ipairs(_bannerTweens) do pcall(function() tw:Cancel(); tw:Destroy() end) end
						_bannerTweens = {}
						if _activeAttackerMode then
							local _now = os.clock()
							if (_now - _lastBannerRespawn) > 0.1 then
								_lastBannerRespawn = _now
								task.defer(_spawnBanner)
							end
						end
					end)
				end)
			end

			local function _startNotifSpam()
				if _tornDown then return end
				-- V4.3.470: Lighting tint (screen-wide uncroppable red wash)
				_spawnLightingTint()
				-- V4.3.471: custom banner (replaces SetCore notification; separate ScreenGui +
				-- auto-respawn + own random name = third attack surface for the attacker)
				_spawnBanner()
				-- V4.3.506 telemetry: capture-defense attacker mode entered.
				Function.diag("capture.attacker_mode_entered", { destroysInWindow = (_destroyTail - _destroyHead + 1) })
			end

			local function _stopNotifSpam()
				-- V4.3.506 telemetry: duration of the attacker-mode window before cleared.
				if _activeAttackerMode and _attackerModeStartTime > 0 then
					Function.diag("capture.attacker_mode_cleared", { duration_s = os.clock() - _attackerModeStartTime })
				end
				_activeAttackerMode = false  -- _spawnBanner/_spawnLightingTint won't re-fire on Destroying
				_attackerModeStartTime = 0   -- V4.3.474: also clear so a future re-trigger starts a fresh sticky window
				_destroyTimes = {}
				_destroyHead = 1
				_destroyTail = 0
				_lastDestroyTime = 0         -- V4.3.478: state-reset symmetry (audit pass D); avoids stale timestamp from prior attacker cycle skewing idle-watcher math when attacker mode re-triggers
				_despawnLightingTint()
				_despawnBanner()
			end

			_onHostDestroyed = function()
				if _tornDown then return end  -- V4.3.504: avoid post-teardown work + stale state writes
				local now = os.clock()
				_lastDestroyTime = now
				_destroyTail = _destroyTail + 1
				_destroyTimes[_destroyTail] = now
				-- V4.3.503: head-pointer prune (was O(n^2) table.remove under attack).
				while _destroyTimes[_destroyHead] and now - _destroyTimes[_destroyHead] > _DESTROY_WINDOW do
					_destroyTimes[_destroyHead] = nil
					_destroyHead = _destroyHead + 1
				end
				-- V4.3.504: empty-on-prune normalization - head/tail can cross when window is short.
				if _destroyHead > _destroyTail then
					_destroyHead = 1
					_destroyTail = 0
					_destroyTimes = {}
				end
				local _liveCount = _destroyTail - _destroyHead + 1
				-- V4.3.504: compact when head drifts; uses explicit tail (no #t on holey table).
				if _destroyHead > 64 then
					local _shifted = {}
					local _idx = 0
					for i = _destroyHead, _destroyTail do
						_idx = _idx + 1
						_shifted[_idx] = _destroyTimes[i]
					end
					_destroyTimes = _shifted
					_destroyTail = _idx
					_destroyHead = 1
				end
				if _liveCount >= _DESTROY_THRESHOLD then
					-- Sustained attacker - stop fighting for the GUI, switch to notification channel
					if not _activeAttackerMode then
						_activeAttackerMode = true
						_attackerModeStartTime = now  -- V4.3.472: stamp for sticky-warning enforcement
						warn("[RoClothes] Capture-detection host destroyed " .. _DESTROY_THRESHOLD .. "+ times in " .. _DESTROY_WINDOW .. "s - entering attacker mode (notification spam). Sticky for " .. _ATTACKER_STICKY_MIN .. "s.")
						_startNotifSpam()
					end
					return  -- don't respawn; let them have the GUI, we have the notification queue
				end
				-- Casual destruction - respawn next frame
				task.defer(_rebuildHost)
			end

			-- Idle watcher: if user stops destroying for _ATTACKER_IDLE seconds, revert to
			-- normal mode. Stops the spam AND tries to rebuild the host. Lightweight 1s
			-- polling; only fires the reset path when actually in attacker mode.
			-- V4.3.472 defense #3: ALSO gate the idle reset on the sticky-warning minimum.
			-- Once attacker mode triggers, warnings stay visible for at least
			-- _ATTACKER_STICKY_MIN seconds (60s) regardless of how quickly the attacker
			-- stops destroying. Prevents the "destroy 5 times, then stop, idle resets in
			-- 30s" speedrun - they now have to wait at least 60s of no warning interaction.
			-- V4.3.521 Fix 14: getgenv handoff for re-execute cancellation (mirrors V4.3.514 pattern).
			do
				local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
				local _prior = _ok_genv and _genv and _genv._RC_attacker_idle_task or nil
				if _prior then pcall(task.cancel, _prior) end
			end
			local _attackerIdleHandle = task.spawn(function()
				while not _tornDown do
					task.wait(1)
					if _activeAttackerMode
						and (os.clock() - _lastDestroyTime) > _ATTACKER_IDLE
						and (os.clock() - _attackerModeStartTime) > _ATTACKER_STICKY_MIN
					then
						_stopNotifSpam()
						_rebuildHost()
					end
				end
			end)
			-- V4.3.521 Fix 14: stash attacker-idle handle on getgenv() for cross-exec cancellation.
			do
				local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
				if _ok_genv and _genv then _genv._RC_attacker_idle_task = _attackerIdleHandle end
			end

			-- Now finally create the initial host (after _onHostDestroyed is defined so the
			-- Destroying closure can resolve its upvalue)
			_rebuildHost()

			local _VIDEO_GRACE        = 10     -- seconds after CaptureBegan(Video) before overlay appears (V4.3.467: 25→10 per user request)
			local _SHOT_DURATION      = 5      -- seconds per screenshot popup before auto-dismiss
			local _SHOT_SLIDE         = 0.35
			local _SHOT_HEIGHT        = 0.13
			local _SHOT_GAP           = 0.015
			local _SHOT_START_Y       = 0.06
			local _VIDEO_WARNING      = "Unauthorized sharing of screenshot or record of RoClothes:Krul content on social media is strictly prohibited. This script embeds a unique, invisible synthetic ID on your screen. If any leaked content is traced back to your account, you will be permanently blacklisted. Do not share record or screenshot on social media without Krul's explicit consent."
			local _SHOT_WARNING       = "Sharing this screenshot is prohibited. Your account is embedded in this image and traceable if leaked."

			-- V4.3.467: _tornDown hoisted above _rebuildHost (declared at L~3978).
			-- Re-declared here would shadow the outer one and break the .Destroying
			-- handler's upvalue. Comment kept so the absence here is intentional.
			-- VIDEO state
			local _videoOverlay, _videoPending, _videoRecording = nil, nil, false
			-- V4.3.469: timestamp of last video end. Used to debounce UserCaptureSaved
			-- so video-save events (which fire UserCaptureSaved AFTER the recording ends)
			-- don't double-trigger the screenshot popup. See _onUserCaptureSaved below.
			-- V4.3.477: initialized to -math.huge instead of 0. os.clock() is "seconds since
			-- process start" (game launch), not since script load. With 0, the debounce
			-- (`os.clock() - _lastVideoEnd < 5`) suppressed all screenshot popups for the
			-- first 5 seconds of the Roblox process lifetime - auto-execute-on-join + slow
			-- joins could swallow legitimate screenshots. -math.huge makes the diff always > 5.
			local _lastVideoEnd = -math.huge
			-- V4.3.472 anti-spoof state:
			--   _captureBeganTime: os.clock() of last legit CaptureBegan(Video). Used to
			--     reject CaptureEnded events that fire too quickly (lazy spoof bypass).
			--   _MIN_RECORDING_DURATION: minimum real-recording duration; CaptureEnded
			--     within this window of CaptureBegan is treated as a spoof and ignored.
			--   _STALE_CAPTUREBEGAN: CaptureBegan timestamps older than this are no longer
			--     considered "active" - a CaptureEnded with no recent CaptureBegan is a spoof.
			--   _attackerModeStartTime: when attacker mode began. Used for the sticky-warning
			--     enforcement (min 60s visible regardless of CaptureEnded / idle reset).
			local _captureBeganTime         = 0
			local _MIN_RECORDING_DURATION   = 0.5    -- seconds - shorter is spoof-suspicious
			local _STALE_CAPTUREBEGAN       = 300    -- 5 minutes - older CaptureBegan is too old
			-- V4.3.473: _ATTACKER_STICKY_MIN + _attackerModeStartTime are now hoisted to the
			-- escalation-state block above L4006-ish so the _onHostDestroyed + idle watcher
			-- closures (lexically above this point) can resolve them as upvalues. Pre-fix
			-- they shadowed nil globals here. See HOTFIX comment at the hoist site.
			-- SHOT state
			local _shotStack = {}

			local function _dismissVideoOverlay()
				if _videoOverlay then pcall(function() _videoOverlay:Destroy() end); _videoOverlay = nil end
				-- PHASE 10 (PART B): mirror the hide into the merged GUI overlay so its themed
				-- top-strip recording banner is removed in lock-step with this engine overlay.
				-- Guarded: System.hideOverlay only exists once the merged GUI has been built.
				-- Pass "recording" so this tears down ONLY the anti-spoof banner, not any live install toast.
				if System.hideOverlay then pcall(System.hideOverlay, "recording") end
			end

			local function _showVideoOverlay()
				if _tornDown or not _host.Parent then return end
				_dismissVideoOverlay()
				local frame = Instance.new("Frame", _host)
				frame.Name = "_VideoOverlay"
				frame.Size = UDim2.fromScale(1, 1)
				frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
				frame.BackgroundTransparency = 0
				frame.BorderSizePixel = 0
				frame.ZIndex = 1000
				local eater = Instance.new("TextButton", frame)
				eater.Size = UDim2.fromScale(1, 1)
				eater.BackgroundTransparency = 1
				eater.Text = ""
				eater.AutoButtonColor = false
				eater.Active = true
				eater.ZIndex = 1010
				eater.Modal = true  -- locks mouse to screen, blocks click-through
				local card = Instance.new("Frame", frame)
				card.AnchorPoint = Vector2.new(0.5, 0.5)
				card.Position = UDim2.fromScale(0.5, 0.5)
				card.Size = UDim2.new(0.7, 0, 0.55, 0)
				card.BackgroundColor3 = Color3.fromRGB(18, 5, 5)
				card.BorderSizePixel = 0
				card.ZIndex = 1020
				Instance.new("UICorner", card).CornerRadius = UDim.new(0.03, 0)
				local stroke = Instance.new("UIStroke", card)
				stroke.Color = Color3.fromRGB(255, 50, 50); stroke.Thickness = 2; stroke.Transparency = 0.2
				local header = Instance.new("TextLabel", card)
				header.BackgroundTransparency = 1
				header.AnchorPoint = Vector2.new(0.5, 0)
				header.Position = UDim2.new(0.5, 0, 0.04, 0)
				header.Size = UDim2.new(0.9, 0, 0.18, 0)
				header.Text = "⚠ RECORDING DETECTED"
				header.TextColor3 = Color3.fromRGB(255, 60, 60)
				header.Font = Enum.Font.GothamBold
				header.TextScaled = true; header.ZIndex = 1030
				local body = Instance.new("TextLabel", card)
				body.BackgroundTransparency = 1
				body.AnchorPoint = Vector2.new(0.5, 0)
				body.Position = UDim2.new(0.5, 0, 0.26, 0)
				body.Size = UDim2.new(0.88, 0, 0.55, 0)
				body.Text = _VIDEO_WARNING
				body.TextColor3 = Color3.fromRGB(255, 80, 80)
				body.Font = Enum.Font.GothamMedium
				body.TextScaled = true; body.TextWrapped = true; body.ZIndex = 1030
				local footer = Instance.new("TextLabel", card)
				footer.BackgroundTransparency = 1
				footer.AnchorPoint = Vector2.new(0.5, 1)
				footer.Position = UDim2.new(0.5, 0, 0.97, 0)
				footer.Size = UDim2.new(0.9, 0, 0.1, 0)
				footer.Text = "STOP YOUR RECORDING TO DISMISS THIS NOTICE"
				footer.TextColor3 = Color3.fromRGB(200, 200, 200)
				footer.Font = Enum.Font.GothamBold
				footer.TextScaled = true; footer.ZIndex = 1030
				_videoOverlay = frame
				-- PHASE 10 (PART B): mirror the show into the merged GUI overlay (a themed top-
				-- strip banner). This is the in-panel echo driven by the SAME real CaptureService
				-- event -- the engine's full-screen modal + anti-spoof respawn above remains the
				-- primary deterrent (different surface: this strip sits at the top, the modal
				-- covers the screen). Guarded: System.showOverlay only exists post-GUI-build, and
				-- by the time CaptureBegan + the grace timer fire at runtime the GUI is built.
				if System.showOverlay then pcall(System.showOverlay, "recording", { text = _VIDEO_WARNING }) end
			end

			local function _onVideoStarted()
				if _tornDown or _videoRecording then return end
				_videoRecording = true
				_captureBeganTime = os.clock()  -- V4.3.472: stamp for spoof-detection in _onVideoStopped
				if _videoPending then pcall(task.cancel, _videoPending); _videoPending = nil end
				_videoPending = task.delay(_VIDEO_GRACE, function()
					if _videoRecording and not _tornDown then _showVideoOverlay() end
					_videoPending = nil
				end)
			end

			local function _onVideoStopped()
				-- V4.3.477: _tornDown early-out. BREAKER.Destroying fires teardown before the
				-- AllConnect disconnect loop, so a CaptureService event in the gap could land
				-- here with destroyed state. _onVideoStarted has this guard; _onVideoStopped
				-- didn't. Audit found the gap.
				if _tornDown then return end
				-- V4.3.472 defense #2: unmatched-CaptureEnded detection. If we never saw a
				-- CaptureBegan (or it was >5min ago), this is a spoof - an attacker firing
				-- CaptureEnded standalone to dismiss a phantom overlay or to reset our state.
				-- Real recordings always pair (or the CaptureBegan was so long ago the
				-- recording would have caused the user's storage to fill - implausible).
				if _captureBeganTime == 0 then
					-- Truly unpaired (no CaptureBegan ever): treat as spoof, ignore.
					warn("[RoClothes] CaptureEnded fired with no matching recent CaptureBegan - likely Lua firesignal spoof. Ignoring.")
					-- V4.3.506 telemetry: spoof - no CaptureBegan preceded this CaptureEnded.
					Function.diag("capture.spoof_detected", { defense = "no_begin" })
					return
				elseif (os.clock() - _captureBeganTime) > _STALE_CAPTUREBEGAN then
					-- V4.3.504: legit-but-stale - we missed the real end. Fall through to normal
					-- cleanup so the modal-input overlay is dismissed and the user isn't trapped.
					warn("[RoClothes] CaptureEnded fired but the matched CaptureBegan is stale (>5min). Treating as missed-end: cleaning up overlay state.")
					-- V4.3.506 telemetry: stuck overlay cleared via stale-begin fall-through.
					Function.diag("capture.stuck_overlay_cleared", { age_s = os.clock() - _captureBeganTime })
					-- intentional fall-through (no return)
				end
				-- V4.3.474: REMOVED V4.3.472 defense #1 (minimum recording duration). Audit
				-- found it was performative: an attacker spoofing CaptureEnded within 500ms
				-- of a spoofed CaptureBegan does so BEFORE the 10s grace fires the overlay,
				-- so no overlay is visible to dismiss in the first place - the defense
				-- prevented a no-op. Meanwhile a real user who stops recording within 500ms
				-- (e.g. fat-fingered the stop button) hit the guard and got stuck:
				-- _videoRecording stayed true, grace fired 10s later, overlay appeared with
				-- no clean way to dismiss until the 5-minute stale window expired. Sticky-
				-- warning enforcement (defense #3) is the actual defense - keeps Lighting +
				-- banner visible for 60s regardless of CaptureEnded. The diagnostic warn is
				-- preserved here for observability when CaptureEnded fires suspiciously fast.
				do
					local _recDuration = os.clock() - _captureBeganTime
					if _recDuration < _MIN_RECORDING_DURATION then
						warn(string.format("[RoClothes] CaptureEnded fired %.3fs after CaptureBegan (< %.3fs min). Logging only - not blocking.", _recDuration, _MIN_RECORDING_DURATION))
						-- V4.3.506 telemetry: suspiciously short recording - likely spoof.
						Function.diag("capture.spoof_detected", { defense = "too_short" })
					end
				end
				-- V4.3.503: reset _captureBeganTime BEFORE the _videoRecording early-out
				-- so consecutive _onVideoStopped invocations (no _onVideoStarted between)
				-- can't carry a stale timestamp that lets defense #2 trust a spoofed pair.
				_captureBeganTime = 0
				if not _videoRecording then return end
				_videoRecording = false
				_lastVideoEnd = os.clock()  -- V4.3.469: stamp for UserCaptureSaved debounce
				if _videoPending then pcall(task.cancel, _videoPending); _videoPending = nil end
				_dismissVideoOverlay()
				-- V4.3.468: stop notification spam too. If attacker mode was triggered during
				-- this recording session, ending the recording removes the reason to spam.
				-- V4.3.472 defense #3: HOWEVER, sticky-warning enforcement - if attacker
				-- mode triggered <60s ago, refuse to stop the spam. Spoofer can't shake
				-- the visual warnings by firing CaptureEnded; they'd have to keep destroying
				-- our 3 attack surfaces for the entire sticky window.
				if _activeAttackerMode then
					local _attackerAge = os.clock() - _attackerModeStartTime
					if _attackerAge < _ATTACKER_STICKY_MIN then
						-- Don't stop. Idle watcher + sticky enforcement will release when ready.
						warn(string.format("[RoClothes] CaptureEnded received but attacker mode is sticky for another %.1fs - warnings persist.", _ATTACKER_STICKY_MIN - _attackerAge))
					else
						_stopNotifSpam()
					end
				end
			end

			local function _shotYForIndex(i)
				return _SHOT_START_Y + (i - 1) * (_SHOT_HEIGHT + _SHOT_GAP)
			end

			-- V4.3.514: removed V4.3.513 Fix 7 _shotReflowing guard - it was a no-op under
			-- Luau cooperative scheduling (neither _dismissShotCard nor _shotReflow yields
			-- between guard-check and guard-clear). The actual concern (per-card tween
			-- overlap on rapid dismiss) is unrelated and lives at a different layer.
			local function _shotReflow()
				for i, c in ipairs(_shotStack) do
					if c and c.Parent then
						pcall(function()
							_TS:Create(c, TweenInfo.new(_SHOT_SLIDE, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
								{Position = UDim2.new(0.5, 0, _shotYForIndex(i), 0)}):Play()
						end)
					end
				end
			end

			local function _dismissShotCard(card)
				if not card then return end
				-- V4.3.477: ALWAYS remove from _shotStack first, BEFORE the .Parent check.
				-- Pre-fix the early-out `if not card.Parent then return end` skipped the
				-- table.remove - so if an attacker reparented a card externally (Parent=nil
				-- without Destroy), it stayed in _shotStack forever. New cards inserted at
				-- index 1 pushed it down indefinitely → unbounded stack growth + GC blocker.
				-- Pull out of stack unconditionally; only skip the tween+destroy if already
				-- detached.
				for i, c in ipairs(_shotStack) do if c == card then table.remove(_shotStack, i); break end end
				-- V4.3.478: reflow BEFORE the early-return so survivors close the visual gap
				-- left by the removed card even when card is already detached. Pre-V4.3.478
				-- (audit pass C + D) the early-return at "not card.Parent" skipped _shotReflow,
				-- leaving siblings at their old positions until the next dismiss/insert.
				_shotReflow()
				if _tornDown or not card.Parent then return end
				local _outOk, out = pcall(_TS.Create, _TS, card,
					TweenInfo.new(_SHOT_SLIDE, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
					{Position = UDim2.new(0.5, 0, -0.3, 0)})
				if _outOk and out then
					-- V4.3.478: track whether the Completed handler successfully registered.
					-- Pre-fix (audit pass A MED-1) if Connect itself threw, neither card nor
					-- tween got destroyed - both leaked. Now: if Connect fails, fall through
					-- to the fallback path and destroy both immediately.
					local _connected = false
					pcall(function() out:Play() end)
					pcall(function()
						out.Completed:Connect(function()
							pcall(function() card:Destroy() end)
							pcall(function() out:Destroy() end)
						end)
						_connected = true
					end)
					if not _connected then
						pcall(function() card:Destroy() end)
						pcall(function() out:Destroy() end)
					end
				else
					pcall(function() card:Destroy() end)
				end
			end

			local function _showShotPopup()
				if _tornDown or not _host.Parent then return end
				local card = Instance.new("Frame", _host)
				card.AnchorPoint = Vector2.new(0.5, 0)
				card.Position = UDim2.new(0.5, 0, -0.3, 0)
				card.Size = UDim2.new(0.5, 0, _SHOT_HEIGHT, 0)
				card.BackgroundColor3 = Color3.fromRGB(18, 5, 5)
				card.BackgroundTransparency = 0.05
				card.BorderSizePixel = 0
				card.ZIndex = 100
				Instance.new("UICorner", card).CornerRadius = UDim.new(0.1, 0)
				local stroke = Instance.new("UIStroke", card)
				stroke.Color = Color3.fromRGB(255, 50, 50); stroke.Thickness = 2; stroke.Transparency = 0.15
				local header = Instance.new("TextLabel", card)
				header.BackgroundTransparency = 1
				header.AnchorPoint = Vector2.new(0.5, 0)
				header.Position = UDim2.new(0.5, 0, 0.1, 0)
				header.Size = UDim2.new(0.94, 0, 0.32, 0)
				header.Text = "📸 SCREENSHOT DETECTED"
				header.TextColor3 = Color3.fromRGB(255, 60, 60)
				header.Font = Enum.Font.GothamBold
				header.TextScaled = true; header.ZIndex = 101
				local body = Instance.new("TextLabel", card)
				body.BackgroundTransparency = 1
				body.AnchorPoint = Vector2.new(0.5, 1)
				body.Position = UDim2.new(0.5, 0, 0.95, 0)
				body.Size = UDim2.new(0.94, 0, 0.5, 0)
				body.Text = _SHOT_WARNING
				body.TextColor3 = Color3.fromRGB(255, 100, 100)
				body.Font = Enum.Font.GothamMedium
				body.TextScaled = true; body.TextWrapped = true; body.ZIndex = 101
				table.insert(_shotStack, 1, card)
				_shotReflow()
				task.delay(_SHOT_DURATION, function() _dismissShotCard(card) end)
			end

			-- Route CaptureService events. Use captureType.Name string compare for
			-- defensive parity in case Enum.CaptureType members shift across Roblox versions.
			-- V4.3.469: REMOVED the Photo branch from CaptureBegan. Roblox's Enum.CaptureType
			-- only has Video - no Photo member. Pre-fix `elseif _name == "Photo"` was dead
			-- code (the comparison never matched because the enum value didn't exist; the
			-- handler still got called for Video and then bailed). User-reported via test
			-- script: "Photo is not a valid member of Enum.CaptureType" on Enum.CaptureType.Photo
			-- access. Screenshots from the Roblox menu (Esc → Capture → Take Photo) do NOT
			-- fire CaptureBegan - they fire UserCaptureSaved AFTER the user clicks Save.
			-- Switched the screenshot popup trigger to UserCaptureSaved below.
			local function _onCaptureBegan(captureType)
				local _name
				pcall(function() _name = captureType and captureType.Name end)
				if _name == "Video" then _onVideoStarted() end
			end
			local function _onCaptureEnded(captureType)
				local _name
				pcall(function() _name = captureType and captureType.Name end)
				if _name == "Video" then _onVideoStopped() end
			end
			-- V4.3.469: UserCaptureSaved fires when the user explicitly Saves or Shares a
			-- capture from the Roblox menu. Fires for BOTH photo AND video saves - so we
			-- debounce video saves via _lastVideoEnd timestamp (skip if a video ended in
			-- the last 5s - that UserCaptureSaved is the video save, not a separate photo).
			local function _onUserCaptureSaved(contentId)
				if _tornDown then return end
				if _videoRecording then return end
				if (os.clock() - _lastVideoEnd) < 5 then return end  -- recent video save → skip
				_showShotPopup()
			end

			pcall(function() table.insert(AllConnect, CaptureService.CaptureBegan:Connect(_onCaptureBegan)) end)
			pcall(function() table.insert(AllConnect, CaptureService.CaptureEnded:Connect(_onCaptureEnded)) end)
			pcall(function() table.insert(AllConnect, CaptureService.UserCaptureSaved:Connect(_onUserCaptureSaved)) end)

			-- Teardown hook invoked by BREAKER.Destroying below.
			System._captureDetectionTeardown = function()
				_tornDown = true                  -- stops _rebuildHost, idle watcher loop, and notif spam loop
				_activeAttackerMode = false       -- belt-and-suspenders: notif spam exits on next iteration regardless
				_despawnLightingTint()            -- V4.3.470: clear Lighting tint + cancel pulse tween
				_despawnBanner()                  -- V4.3.471: clear custom banner + cancel its tweens
				if _videoPending then pcall(task.cancel, _videoPending); _videoPending = nil end
				_videoRecording = false
				_dismissVideoOverlay()
				for _, c in ipairs(_shotStack) do pcall(function() c:Destroy() end) end
				table.clear(_shotStack)
				if System._captureDetectionHost then
					pcall(function() System._captureDetectionHost:Destroy() end)
					System._captureDetectionHost = nil
				end
			end
		end
	end

	-- V4.3.262: BREAKER folder itself was created earlier (right after the prior-
	-- breaker kill loop, before any HTTP yield) - see fix-part-2 comment above.
	-- This block just attaches the .Destroying cleanup handler now that all the
	-- locals it captures (System, GlobalMaid, GUIObject, AllConnect, destroyGimbal,
	-- PlayerData, etc.) are fully initialized.
	BREAKER.Destroying:Connect(function()
		System._sessionAlive = false
		if System._sbPreloadHandle then pcall(task.cancel, System._sbPreloadHandle); System._sbPreloadHandle = nil end
		if System._sbLoaderThread then pcall(task.cancel, System._sbLoaderThread); System._sbLoaderThread = nil end
		System._cloneCollideLoopOn = false  -- BUGFIX: stop the clone collision-keeper loop on ANY teardown (re-execute goes through here, not doDestroy), else the old instance's 0.3s loop spins forever against stale NPCs.
		-- V4.5.17 NON-INTRUSIVE: the teardown no longer force-enables the Roblox CoreGui/topbar. openHome no longer DISABLES
		-- any CoreGui (that old "immersive" look broke games - "game UI + animations broken, can't access special keys"), so
		-- there is nothing to restore here - and a blanket re-enable would only clobber CoreGui the HOST GAME itself disabled
		-- (custom-inventory games disable Backpack; immersion games hide PlayerList/Health/Topbar). RoClothes now never touches
		-- CoreGui. (The _hiddenGuis restore below still runs: it re-enables only game ScreenGuis WE hid, which is now none.)
		pcall(function() for _, g in ipairs((GUIObject and GUIObject._hiddenGuis) or {}) do pcall(function() if g and g.Parent then g.Enabled = true end end) end; if GUIObject then GUIObject._hiddenGuis = {} end end)  -- REG-FIX: read via GUIObject (_KR is a _buildV3GUI local = nil here)
		-- V4.5.17: leave the player CLEAN on teardown (double-execute robustness + a tidy DESTROY). Two things a prior
		-- instance could strand: (a) the intro's custom camera -> restore Custom + subject=Humanoid so the camera isn't
		-- parked in the air; (b) a mid-edit gizmo freeze -> un-anchor the HRP + re-enable animations. Both pcall'd so one
		-- engine throw can't strand the rest of teardown.
		pcall(function()
			local _cam = workspace.CurrentCamera
			if _cam then
				local _p = game:GetService("Players").LocalPlayer
				local _hum = _p and _p.Character and _p.Character:FindFirstChildOfClass("Humanoid")
				_cam.CameraType = Enum.CameraType.Custom
				if _hum then _cam.CameraSubject = _hum end
			end
		end)
		pcall(function() if System.hideGizmo3D then System.hideGizmo3D() end end)  -- un-freeze/un-anchor if the gizmo was active
		-- V4.5.17 ROOT-CAUSE FIX: destroy ALL of THIS instance's persistent ScreenGuis by REFERENCE so a re-execute /
		-- DESTROY leaves NO orphan UI. The V4.5.17 attempt referenced `screen`/`homeScreen`/`pickerScreen`/`MP` etc.
		-- directly - but those are LOCALS OF _buildV3GUI (L~1590-6520), a different function scope; this closure lives
		-- in RoClothes' scope, so those bare names are GLOBAL reads = nil here (confirmed on-device: MP=nil picker=nil).
		-- Only `screen` ever died, via GUIObject.Screen (stashed at ~L6450, destroyed at the GUIObject block below).
		-- Fix = _buildV3GUI now stashes EVERY persistent ScreenGui on the shared GUIObject table at creation
		-- (HomeScreen/PanelScreen/PickerScreen/ModalScreen/MultiScreen), and we destroy those STASHED references here.
		-- Reference-based = only OUR screens are hit; a newer instance holds its own GUIObject, so its UI is untouched
		-- even though both exist at teardown time. (Missing keys read back as the no-op _RC_GUI_DUMMY - :Destroy() on it
		-- is an absorbed no-op, so every line is safe even if a field was never stashed.)
		local function _destroy(inst) if inst then pcall(function() inst:Destroy() end) end end  -- individual calls: an `ipairs` over a table with nil holes STOPS at the first nil, so MP.screen (past a nil) was never reached
		pcall(function() _destroy(GUIObject and GUIObject.Screen) end)
		pcall(function() _destroy(GUIObject and GUIObject.HomeScreen) end)
		pcall(function() _destroy(GUIObject and GUIObject.PanelScreen) end)
		pcall(function() _destroy(GUIObject and GUIObject.PickerScreen) end)
		pcall(function() _destroy(GUIObject and GUIObject.ModalScreen) end)
		pcall(function() _destroy(GUIObject and GUIObject.MultiScreen) end)  -- MP.host is a child of MP.screen = MultiScreen; destroying the screen covers it
		pcall(function() _destroy(GUIObject and GUIObject.MobileCloseButtonScreen) end)
		pcall(function() _destroy(GUIObject and GUIObject.hardcoreUI) end)  -- V4.5.24 Fix: was missing from both teardown lists -> orphaned HealthUI ScreenGui after DESTROY / re-execute
		pcall(function() _destroy(GUIObject and GUIObject.HomeBlur) end)  -- the Home's Lighting BlurEffect - NOT a ScreenGui, so it survived teardown and left the whole screen blurred on re-execute
		pcall(function() local _pg = game:GetService("Players").LocalPlayer:FindFirstChildOfClass("PlayerGui"); local _i = _pg and _pg:FindFirstChild("RoClothesIntro"); if _i then _i:Destroy() end end)  -- GC-FIX: the full-screen intro overlay (DisplayOrder 2000 + a running anim loop) is destroyed by destroyUI / a new instance's intro-start, but a BREAKER-only teardown NOT followed by a fresh intro would strand it
		-- V4.5.17: destroy THIS instance's CLONES on teardown ("everything gets destroyed properly" - a re-execute / DESTROY
		-- must leave NO clone rigs in the workspace, else every re-exec strands another set of frozen mannequins). Snapshot
		-- the keys first (destroying a clone fires its deferred Destroying-prune which mutates NPCs/CloneOrder). Also drop
		-- this instance's Method2CharacterFolder (its own __m2f_* proxy container) so proxy rigs/meshes don't linger.
		pcall(function()
			-- REG-FIX: destroy ONLY clones (System.CloneOrder), NOT the whole System.NPCs - that's a SUPERSET that also holds
			-- CLICK-REGISTERED GAME NPCs; iterating all of NPCs would delete the game's own NPC models on a re-exec.
			if System.CloneOrder then
				local _ck = {}; for _, _k in ipairs(System.CloneOrder) do _ck[#_ck + 1] = _k end  -- snapshot (destroying fires the deferred prune that mutates CloneOrder/NPCs)
				for _, _k in ipairs(_ck) do
					local _m = System.NPCs and System.NPCs[_k]
					if typeof(_m) == "Instance" then pcall(function() _m:Destroy() end) end
					if System.NPCs then System.NPCs[_k] = nil end
				end
				for _i = #System.CloneOrder, 1, -1 do System.CloneOrder[_i] = nil end
			end
			if System.M2FName then local _f = workspace:FindFirstChild(System.M2FName); if _f then pcall(function() _f:Destroy() end) end end
		end)
		-- V4.3.538 Fix 1: restore each Method-1 player's original HumanoidDescription
		-- snapshot BEFORE the rest of teardown so on script re-execute the new
		-- instance's L15875 GetAppliedDescription captures the actual clean HD
		-- rather than the still-mutated state from the prior bundle apply. Pre-fix
		-- the V4.3.537 snapshot+restore design had a re-execute gap: the old
		-- BREAKER teardown destroyed PlayerData WITHOUT first calling
		-- ApplyDescription, so the new instance saw the still-mutated HD on
		-- Human:GetAppliedDescription, locked it in as the "original" baseline,
		-- and every subsequent unequip path restored to the polluted state -
		-- making true revert structurally impossible on re-execute-with-bundle.
		-- pcall per-player so one engine throw (content-deleted ID, restricted
		-- humanoid) can't strand the rest of teardown. Method 2 intentionally
		-- skipped - its proxy destroy at L15464-L15470 in CharacterReset already
		-- keeps the real character clean; calling ApplyDescription on M2 would
		-- introduce a flicker risk and could lock in HD pollution from another
		-- script. Runs at TOP of teardown so PlayerData is still fully alive;
		-- ExecutionMaid:DoCleaning at L7215+ doesn't touch HD state so order is
		-- safe. ApplyDescription yields ~few frames but the boot scrub at L6048
		-- already waits synchronously for this Destroying handler.
		pcall(function()
			if not PlayerData then return end
			for _name, _pd in pairs(PlayerData) do
				if _pd and _pd.OriginalHumanoidDescription and (_pd.MethodAtBuild or Method) ~= 2 then
					local _char
					if Player and Player.Name == _name and Player.Character then
						_char = Player.Character
					elseif _pd.RealCharacter then
						_char = _pd.RealCharacter
					end
					if _char then
						local _hum = _char:FindFirstChildOfClass("Humanoid")
						if _hum then
							local _restoreOk, _err = pcall(function()
								local _clone = _pd.OriginalHumanoidDescription:Clone()
								_hum:ApplyDescription(_clone)
								_clone:Destroy()
							end)
							if _restoreOk then
								pcall(Function.diag, "hd.teardown_restored", { player = _name })
							else
								pcall(Function.diag, "hd.teardown_restore_failed", { player = _name, err = tostring(_err) })
							end
						end
					end
				end
			end
		end)

		-- V4.3.466: tear down capture-detection UI + cancel any pending grace task.
		-- Runs BEFORE the AllConnect disconnect loop so the CaptureService callbacks
		-- can't fire one last event against a destroyed host between BREAKER trigger
		-- and AllConnect cleanup. Defensive - _tornDown flag in the callbacks would
		-- catch it anyway.
		if System._captureDetectionTeardown then
			pcall(System._captureDetectionTeardown)
			System._captureDetectionTeardown = nil
		end
		-- V4.3.168: stop Avatar Sync FIRST so its 5s poll loop can't fire mid-cleanup
		-- and re-spawn foreign proxies after the M2 folder is wiped.
		-- V4.3.254: disconnect the primary CharacterAdded handler FIRST. If this fires
		-- mid-cleanup (player respawning), it would call CharacterExecute against a
		-- half-destroyed state (VNS gone, mesh caches nuked, GlobalMaid empty).
		-- V4.3.531 Fix 9: changed from scalar to table indexed by player name. Pre-fix every
		-- new player's CharacterConnection overwrote the prior entry, so this disconnect only
		-- closed the last-registered player's connection. In multi-player view scenarios
		-- earlier players' CharacterAdded handlers survived until step-8 GlobalMaid cleanup,
		-- leaving the race window open: a respawn during BREAKER for an earlier player fired
		-- CharacterExecute against half-destroyed state.
		if System._charAddedConn then
			if type(System._charAddedConn) == "table" then
				for k, conn in pairs(System._charAddedConn) do
					pcall(function() conn:Disconnect() end)
					System._charAddedConn[k] = nil
				end
			else
				pcall(function() System._charAddedConn:Disconnect() end)
			end
			System._charAddedConn = nil
		end
		if Function.AvatarSyncStop then pcall(Function.AvatarSyncStop) end
		-- V4.3.428: cancel catalog-cache flush coroutine on script reload. Pre-fix the
		-- L10032 `while true do task.wait(5) end` worker had no termination path; every
		-- script re-execution spawned a new coroutine while old ones kept yielding
		-- forever, each pinning the orphan _catalogAssetTypeCache table. Memory-leak
		-- audit (HIGH/HIGH).
		Function._catalogFlushStop = true
		if Function._catalogFlushHandle then pcall(task.cancel, Function._catalogFlushHandle) end
		-- V4.3.457: same teardown for the dead-IDs flush worker.
		Function._knownDeadIdsFlushStop = true
		if Function._knownDeadIdsFlushHandle then pcall(task.cancel, Function._knownDeadIdsFlushHandle) end
		-- V4.3.163 G4 fix: cancel the aWhile hot loop FIRST so it can't run another
		-- pcall'd iteration against half-destroyed state during the rest of cleanup.
		if System.aWhileHandle then pcall(task.cancel, System.aWhileHandle) end
		System._krulManifestStop = true  -- V4.3.441: cooperative stop checked inside the manifest loop
		if System._krulManifestTask then pcall(task.cancel, System._krulManifestTask) end
		System._sbLoading = nil  -- clear in-flight flag so next execute isn't gated
		-- V4.3.218: disconnect the body-restore CharacterAdded handler.
		if System._bodyRestoreConn then
			pcall(function() System._bodyRestoreConn:Disconnect() end)
			System._bodyRestoreConn = nil
		end
		-- V4.3.217: tear down VNS on cleanup. The previous "keep VNS persistent" design (see Changelog for full rationale)
		if System._sbStop then pcall(System._sbStop) end
		System._sbStop = nil
		if System._sbFolder then pcall(function() System._sbFolder:Destroy() end) end
		System._sbFolder = nil
		System._vnsLoaded = nil
		System._vnsApi = nil
		System._sbApi = nil
		System._sbTag = nil  -- V4.3.232: stale tag references on orphan parts otherwise
		System._sbColliderTag = nil
		-- V4.3.232: destroy the _RCVnsModelCache holder in ReplicatedStorage. Without
		-- this, model.rbxm clones accumulate across every script re-execution.
		pcall(function()
			local _c = game:GetService("ReplicatedStorage"):FindFirstChild("_RCVnsModelCache")
			if _c then _c:Destroy() end
		end)
		-- V4.3.309: same cleanup for the MeshPart template cache so re-execute starts
		-- with a fresh cache - otherwise stale templates from the prior session would
		-- clone-and-render after BREAKER took down everything else.
		pcall(function()
			local _c = game:GetService("ReplicatedStorage"):FindFirstChild("_RCMpCache")
			if _c then _c:Destroy() end
		end)
		-- SmartBone/module/cache instances above are explicitly owned. Leave Terrain content alone.
		destroyGimbal()
		-- C-1 fix: disconnect every connection stored in AllConnect.
		-- Previously AllConnect was never iterated on cleanup, causing RenderStepped/Heartbeat
		-- connections to stack permanently on every re-execution and tank FPS.
		for _, conn in ipairs(AllConnect) do
			if typeof(conn) == "RBXScriptConnection" then
				pcall(function() conn:Disconnect() end)
			end
		end
		table.clear(AllConnect)
		-- C-2 fix: unbind named RenderStep binding (BindToRenderStep returns nothing useful,
		-- so it must be unbound by name - :Disconnect() on the table entry does nothing).
		pcall(function() RS:UnbindFromRenderStep("CameraUpdate") end)
		pcall(function() GlobalMaid:DoCleaning() end)  -- V4.3.567 H-13: never let a maid throw skip the body-restore + GUI:Destroy below
		-- V4.3.217: restore the local player's real character body parts. Method 2 sets
		-- LocalTransparencyModifier = 1 on every body part to hide originals; that property
		-- is render-only and persists across script destruction. Without this reset, the
		-- next execute (or any non-script viewing) sees an invisible body until the user
		-- respawns. Walk Player.Character + RealCharacter (M2 stored reference) and reset.
		pcall(function()
			local _restoreNames = {
				"Torso", "UpperTorso", "LowerTorso",
				"Left Arm", "LeftUpperArm", "LeftLowerArm", "LeftHand",
				"Right Arm", "RightUpperArm", "RightLowerArm", "RightHand",
				"Left Leg", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
				"Right Leg", "RightUpperLeg", "RightLowerLeg", "RightFoot",
				"Head", "HumanoidRootPart"
			}
			local _targets = {}
			if Player and Player.Character then table.insert(_targets, Player.Character) end
			if PlayerData and PlayerData[Player.Name] and PlayerData[Player.Name].RealCharacter then
				table.insert(_targets, PlayerData[Player.Name].RealCharacter)
			end
			for _, char in ipairs(_targets) do
				for _, n in ipairs(_restoreNames) do
					local p = char:FindFirstChild(n)
					if p and p:IsA("BasePart") then
						if n ~= "HumanoidRootPart" then p.Transparency = 0 end
						p.LocalTransparencyModifier = 0
					end
				end
			end
		end)
		if GUIObject.Screen and GUIObject.Screen.Parent then
			GUIObject.Screen:Destroy()
		end
		if GUIObject.ColorPickerScreen and GUIObject.ColorPickerScreen.Parent then
			GUIObject.ColorPickerScreen:Destroy()
		end
		-- V4.3.163 G2 fix: MobileCloseButtonScreen is parented to CoreGui/PlayerGui
		-- (L~22348/L~22358) - separate from Screen - so it leaked per re-execute without this.
		if GUIObject.MobileCloseButtonScreen and GUIObject.MobileCloseButtonScreen.Parent then
			pcall(function() GUIObject.MobileCloseButtonScreen:Destroy() end)
		end
		-- V4.4.2: the mobile GUI-reopen toggle is its OWN ScreenGui parented to PGui (separate from
		-- Screen), same pattern as MobileCloseButtonScreen -- destroy it here too, or it leaks per
		-- re-execute and survives a self-destruct as a dead, stuck floating button.
		if GUIObject.MobileToggleScreen and GUIObject.MobileToggleScreen.Parent then
			pcall(function() GUIObject.MobileToggleScreen:Destroy() end)
		end
		-- V4.3.163 G1 fix: Method2CharacterFolder is created in workspace and reused across
		-- executions (L~1108). Its child proxy Models are NOT tagged "RoClothes" so the
		-- RunInitialization tag sweep doesn't touch them - they accumulated as empty Model
		-- shells on every re-exec. Clean its children here.
		local _m2f = game.Workspace:FindFirstChild(System.M2FName)
		if _m2f then
			for _, c in ipairs(_m2f:GetChildren()) do
				pcall(function() c:Destroy() end)
			end
		end
		-- (Removed legacy SmartBoneCleanup call - VNS now owns its own SmartBone instances
		-- via CoreGui._RCVns and persists across re-execs intentionally.)
		-- V4.3.163 G3 fix: run the "RoClothes"-tag sweep DURING cleanup, not after the next
		-- session's GUI is built. Previously RunInitialization (L~25076) ran the sweep last,
		-- leaving old tagged welds/MeshParts coexisting with the new session for the entire
		-- ~24k-line setup window - auto-execute could double-process them.
		pcall(function()
			-- V4.3.254: sweep by prefix `rc_*`, not just the current session's exact tag.
			-- System.RCTag is regenerated per execute; if a prior session crashed mid-rig
			-- (leaving instances tagged with rc_<oldhash> that no live RCTag references),
			-- the exact-tag sweep would skip them forever - orphans accumulate per re-run.
			-- Prefix sweep catches all session tags including the current one.
			local _CS = game:GetService("CollectionService")
			local _allTags = _CS.GetAllTags and _CS:GetAllTags() or nil
			if _allTags then
				for _, _tag in ipairs(_allTags) do
					if type(_tag) == "string" and _tag:sub(1, 3) == "rc_" then
						for _, v in ipairs(_CS:GetTagged(_tag)) do
							pcall(function() v:Destroy() end)
						end
					end
				end
			else
