	-- variables --
	-- V4.3.220: derived from file-scope _RC_VER / _RC_VER_DATE (single source of truth at L82-83).
	-- V4.3.535 Opt-2: VersionInternal / VersionDate / hidden hoisted to file scope.

	-- V4.3.166: rehydrate() - reconstructs Roblox values from JSON-decoded data bundle. (see Changelog for full rationale)
	-- V4.3.382: depth-limited recursion guard. A malicious peer can ship a
	local function rehydrate(node, _depth)
		if type(node) ~= "table" then return node end
		_depth = _depth or 0
		if _depth > 64 then
			warn("[RoClothes] rehydrate: nesting depth exceeded 64; bundle data trimmed.")
			return nil
		end
		local tag = node.__t
		if tag == "V3" then
			-- V4.3.374: pcall-guard. Pre-fix malformed `{__t="V3", v=...}` from a
			-- peer/community bundle (v not a table, non-numeric components, wrong
			-- arity) raised an uncaught error inside rehydrate that aborted the
			-- whole bundle decode. The V4.3.355 fix only covered the Enum branch;
			-- this extends it to V3/CF/C3/C3n.
			local _ok, _vv = pcall(function()
				local v = node.v
				return Vector3.new(v[1], v[2], v[3])
			end)
			return _ok and _vv or nil
		elseif tag == "CF" then
			local _ok, _vv = pcall(function()
				local v = node.v
				if #v == 12 then
					return CFrame.new(v[1],v[2],v[3], v[4],v[5],v[6], v[7],v[8],v[9], v[10],v[11],v[12])
				elseif #v == 3 then
					return CFrame.new(v[1], v[2], v[3])
				elseif #v == 0 then
					return CFrame.new()
				else
					error("rehydrate: bad CF arity " .. tostring(#v))
				end
			end)
			return _ok and _vv or nil
		elseif tag == "C3" then
			local _ok, _vv = pcall(function()
				local v = node.v
				return Color3.fromRGB(v[1], v[2], v[3])
			end)
			return _ok and _vv or nil
		elseif tag == "C3n" then
			local _ok, _vv = pcall(function()
				local v = node.v
				return Color3.new(v[1], v[2], v[3])
			end)
			return _ok and _vv or nil
		elseif tag == "E" then
			-- V4.3.355: pcall-guard. Pre-fix a peer/foreign bundle with malformed
			-- `__t="E"` (missing .p, unknown enum type, or unknown enum item)
			-- raised an unrecoverable error inside rehydrate, aborting the whole
			-- bundle decode. All other branches handle inputs more defensively.
			local _okE, _ev = pcall(function() return Enum[node.p][node.v] end)
			return _okE and _ev or nil
		end
		-- plain table: recurse, restoring "#N" integer keys
		local out = {}
		for k, val in pairs(node) do
			local rk
			if type(k) == "string" and string.sub(k, 1, 1) == "#" then
				rk = tonumber(string.sub(k, 2))
			else
				rk = k
			end
			out[rk] = rehydrate(val, _depth + 1)
		end
		return out
	end

	-- V4.3.167.3: dehydrate - inverse of rehydrate. Encodes Roblox values as
	-- tagged dicts so HttpService:JSONEncode can serialize the result. Powers
	-- the in-script "Submit Bundle" feature that POSTs exported bundles to the
	-- dashboard's review queue. Mirrors the encoding spec in
	-- Wiki/tools/build_data_bundle.py so submitted bundles are drop-in
	-- mergeable as future chunks. Integer keys → "#N" string prefix so
	-- JSONEncode emits a real object (not an array) and rehydrate can restore
	-- the integer key on consumption.
	-- V4.3.515 Fix 9: depth + cycle cap. Symmetric to rehydrate's V4.3.382 guard.
	-- Without this, a cyclic peer payload re-broadcast could C-stack-overflow on publish.
	local function dehydrate(node, _depth, _seen)
		_depth = _depth or 0
		if _depth > 32 then return node end
		local tv = typeof(node)
		if tv == "Vector3" then
			return {__t = "V3", v = {node.X, node.Y, node.Z}}
		elseif tv == "CFrame" then
			return {__t = "CF", v = {node:GetComponents()}}
		elseif tv == "Color3" then
			return {__t = "C3n", v = {node.R, node.G, node.B}}
		elseif tv == "EnumItem" then
			return {__t = "E", p = (tostring(node.EnumType):gsub("^Enum%.", "")), v = node.Name}  -- V4.3.576: was :sub(6) -> "KeyCode" became "de"
		elseif tv ~= "table" then
			return node
		end
		_seen = _seen or {}
		if _seen[node] then return node end
		_seen[node] = true
		local out = {}
		for k, val in pairs(node) do
			local sk
			if type(k) == "number" then
				sk = "#" .. tostring(k)
			else
				sk = k
			end
			out[sk] = dehydrate(val, _depth + 1, _seen)
		end
		return out
	end

	-- Create the loading screen immediately so it shows during data fetch + GUIFunc,
