	-- Metadata bootstrap checks the manifest before choosing cached chunks.
	-- Changed chunks are fetched for this execution; valid disk data remains
	-- available as the offline fallback. Merge order follows the manifest.
	local _RoClothesData
	do
		local BASE_URL       = "https://krulhub.dev/roclothes/"
		local MANIFEST_URL   = BASE_URL .. "manifest.json"
		local CACHE_DIR      = "RoClothesCache"
		local MANIFEST_CACHE = CACHE_DIR .. "/manifest.json"

		if env.isfolder and env.makefolder and not env.isfolder(CACHE_DIR) then
			pcall(env.makefolder, CACHE_DIR)
		end

		local HttpService = game:GetService("HttpService")

		-- V4.3.484: wall-clock-bounded fetch. Pre-fix the bare `pcall(game.HttpGet, ...)`
		-- inherited whatever the executor's internal HTTP timeout was - for users
		-- with broken executor HttpGet stubs that hang instead of erroring, OR users
		-- whose network blocks krulhub.dev (firewall / region block / ISP), the call
		-- could hang for minutes, leaving the loading screen frozen forever. User
		-- report 2026-05-19: "after [install fail popup] its just stuck in a loading
		-- screen for me." Same wall-clock race pattern as the asset-content manifest
		-- fetch at L3566. 30s upper bound matches MANIFEST_TIMEOUT_S so both feel
		-- consistent.
		local _DATA_FETCH_TIMEOUT_S = 30
		local function fetchJson(url, minBytes)
			local _ok, _body
			local _done = false
			task.spawn(function()
				local pok, pbody = pcall(game.HttpGet, game, url)
				if not pok or type(pbody) ~= "string" or #pbody < (minBytes or 2) then
					local reqFn = System.Env.http_request or System.Env.request
						or (System.Env.syn and System.Env.syn.request)
						or (System.Env.http and System.Env.http.request)
					if reqFn then
						local okR, res = pcall(reqFn, {Url = url, Method = "GET"})
						if okR and res and type(res.Body) == "string" and #res.Body >= (minBytes or 2) then
							pok, pbody = true, res.Body
						end
					end
				end
				_ok, _body = pok, pbody
				_done = true
			end)
			local _t0 = os.clock()
			while not _done and (os.clock() - _t0) < _DATA_FETCH_TIMEOUT_S do task.wait(0.1) end
			if not _done then
				return nil, "timeout after " .. _DATA_FETCH_TIMEOUT_S .. "s"
			end
			if not _ok or type(_body) ~= "string" or #_body < (minBytes or 2) then
				return nil, "fetch failed: " .. tostring(_body)
			end
			local okD, decoded = pcall(HttpService.JSONDecode, HttpService, _body)
			if not okD or type(decoded) ~= "table" then
				return nil, "JSONDecode failed: " .. tostring(decoded)
			end
			return decoded, _body
		end

		local function deepMerge(target, src)
			for k, v in pairs(src) do
				if type(v) == "table" and type(target[k]) == "table"
						and not v.__t and not target[k].__t then
					deepMerge(target[k], v)
				else
					target[k] = v
				end
			end
		end

		local function fetchAndSaveChunks(chunks, cacheFile, manifestRaw)
			-- Parallel chunk fetch
			local results = table.create(#chunks)
			local pending = #chunks
			local _inflight = {}
			for i, chunk in ipairs(chunks) do
				local idx = i
				local url = (string.find(chunk, "://", 1, true)) and chunk or (BASE_URL .. chunk)
				_inflight[idx] = true
				task.spawn(function()
					-- V4.3.502: pcall the fetch body so a throw inside fetchJson can't
					-- leak the pending counter and park the repeat below forever.
					-- V4.5.24 (r2): nil-guarded slot write - a slow duplicate landing late must never
					-- clobber a valid result back to nil (last-writer-wins bug in the r1 refetch).
					pcall(function() local _v = fetchJson(url, 2); if _v ~= nil and results[idx] == nil then results[idx] = _v end end)
					_inflight[idx] = nil
					pending -= 1
				end)
			end
			-- V4.3.502: wall-clock deadline so a single hung worker (or all of them)
			-- can't strand the boot thread indefinitely.
			local _waitStart = os.clock()
			repeat
				task.wait(0.05)
				if os.clock() - _waitStart > 30 then
					warn("[RoClothes] fetchAndSaveChunks: 30s deadline hit with " .. tostring(pending) .. " chunk(s) still pending")
					Function.diag("install.deadline_hit", { done = #chunks - pending, total = #chunks })
					break
				end
			until pending == 0
			-- V4.5.24 Fix: one bounded refetch pass of the chunks still missing after the 30s
			-- deadline + the two per-chunk retries, BEFORE declaring total failure. A single
			-- slow worker (29/30 done) was previously reported as "Data servers unreachable"
			-- and halted first-run boot with a misleading popup. If these still fail, the
			-- nil-return + halt behavior below is unchanged.
			-- V4.5.24 (r2): refetch only chunks whose ORIGINAL worker genuinely finished empty (not ones
			-- still in flight past the deadline - those finish on their own). Use a SEPARATE pending
			-- counter (the originals' pending -= 1 must not bleed into this wave) and nil-guarded slot
			-- writes (a slow original landing later must not clobber this wave's good value).
			local _missing = {}
			for _i = 1, #chunks do if results[_i] == nil and not _inflight[_i] then _missing[#_missing + 1] = _i end end
			if #_missing > 0 then
				local _pending2 = #_missing
				for _, _mi in ipairs(_missing) do
					_inflight[_mi] = true
					local _chunk = chunks[_mi]
					local _u = (string.find(_chunk, "://", 1, true)) and _chunk or (BASE_URL .. _chunk)
					task.spawn(function()
						pcall(function()
							if results[_mi] == nil then
								local _v = fetchJson(_u, 2)
								if _v ~= nil and results[_mi] == nil then results[_mi] = _v end
							end
						end)
						_inflight[_mi] = nil
						_pending2 -= 1
					end)
				end
				local _w2 = os.clock()
				repeat
					task.wait(0.05)
					if os.clock() - _w2 > 12 then break end
				until _pending2 == 0
			end
			-- V4.3.503: deadline-hit observability. Surface N/M chunks done so devs can
			-- spot partial-success patterns. V4.5.24 added the bounded refetch pass above;
			-- only a chunk still empty after BOTH waves halts boot here.
			local _doneCount, _totalChunks = 0, #chunks
			for i = 1, _totalChunks do if results[i] then _doneCount = _doneCount + 1 end end
			if _doneCount < _totalChunks then
