		-- V4.3.283: rewritten cache load - was stale-while-revalidate (instant start (see Changelog for full rationale)
		local _cachedBody, _cachedFile, _cachedVersion
		local _allCacheFiles = {}  -- list of all data_*.json paths for sweep
		if env.isfile and env.readfile and env.listfiles and env.isfolder
				and env.isfolder(CACHE_DIR) then
			local okL, listing = pcall(env.listfiles, CACHE_DIR)
			if okL and type(listing) == "table" then
				-- Collect every candidate with its parsed version, then pick highest.
				local candidates = {}
				for _, path in ipairs(listing) do
					if type(path) == "string"
							and string.find(path, "data_", 1, true)
							and not string.find(path, MANIFEST_CACHE, 1, true) then
