				-- YYYY.MM.DD.N format → lexical sort gives highest version last.
				table.sort(candidates, function(a, b) return a.ver < b.ver end)
				for i = #candidates, 1, -1 do
					local c = candidates[i]
					local okR, body = pcall(env.readfile, c.path)
					if okR and type(body) == "string" and #body >= 1000 then
						local okD, decoded = pcall(HttpService.JSONDecode, HttpService, body)
						if okD and type(decoded) == "table" then
