				local _BG, _LINE, _TXT, _TXT2, _BAD = Color3.fromRGB(20, 20, 28), Color3.fromRGB(48, 48, 60), Color3.fromRGB(236, 236, 245), Color3.fromRGB(165, 165, 180), Color3.fromRGB(232, 72, 84)
				local _uic
				local g = Instance.new("ScreenGui"); g.Name = "_RoClothesDataPopup"
				g.IgnoreGuiInset = true; g.ResetOnSpawn = false; g.DisplayOrder = 1000001; g.Parent = _CG
				local d = Instance.new("Frame", g); d.Size = UDim2.fromScale(1, 1); d.BackgroundColor3 = Color3.fromRGB(6, 6, 10); d.BackgroundTransparency = 0.42; d.BorderSizePixel = 0
				local c = Instance.new("Frame", d)
