				local _icx = Instance.new("TextLabel", _ic); _icx.Size = UDim2.fromScale(1, 1); _icx.BackgroundTransparency = 1; _icx.Font = Enum.Font.GothamBold; _icx.Text = "!"; _icx.TextColor3 = Color3.new(1, 1, 1); _icx.TextSize = 26; _icx.TextXAlignment = Enum.TextXAlignment.Center
				local t = Instance.new("TextLabel", c)
				t.AnchorPoint = Vector2.new(0.5, 0); t.Position = UDim2.new(0.5, 0, 0, 78); t.Size = UDim2.new(1, -44, 0, 26); t.BackgroundTransparency = 1; t.Font = Enum.Font.GothamBold; t.TextSize = 19; t.TextColor3 = _TXT; t.Text = "Data servers unreachable"; t.TextXAlignment = Enum.TextXAlignment.Center
				local b = Instance.new("TextLabel", c)
				b.AnchorPoint = Vector2.new(0.5, 0); b.Position = UDim2.new(0.5, 0, 0, 112); b.Size = UDim2.new(1, -44, 0, 148); b.BackgroundTransparency = 1; b.Font = Enum.Font.Gotham; b.TextSize = 13.5; b.TextColor3 = _TXT2; b.TextWrapped = true; b.TextXAlignment = Enum.TextXAlignment.Center; b.TextYAlignment = Enum.TextYAlignment.Top
				b.Text = "Could not download bundle data from krulhub.dev.\n\nReason: "..tostring(reason).."\n\nUsually your executor blocks HTTP, your network/region blocks krulhub.dev, or a temporary CDN outage. Try again in a minute or check your connection."
				local _DISCORD = "discord.gg/SBUuYsnShf"
				local _lnk = Instance.new("TextButton", c)
				_lnk.AnchorPoint = Vector2.new(0.5, 0); _lnk.Position = UDim2.new(0.5, 0, 0, 268); _lnk.Size = UDim2.new(1, -60, 0, 26); _lnk.BackgroundColor3 = Color3.fromRGB(30, 30, 42); _lnk.BackgroundTransparency = 0.3; _lnk.AutoButtonColor = false; _lnk.Font = Enum.Font.GothamBold; _lnk.TextSize = 13; _lnk.TextColor3 = _AC1; _lnk.Text = _DISCORD .. "   (tap to copy)"; _lnk.BorderSizePixel = 0
				local _lc = Instance.new("UICorner", _lnk); _lc.CornerRadius = UDim.new(0, 8)
				local _lst = Instance.new("UIStroke", _lnk); _lst.Color = _LINE; _lst.Thickness = 1; _lst.Transparency = 0.4
				_lnk.MouseButton1Click:Connect(function()
					local _cb = setclipboard or toclipboard or writeclipboard or (System and System.Env and System.Env.setclipboard)
					local _ok = _cb and pcall(_cb, _DISCORD)
