					_lnk.TextColor3 = _ok and Color3.fromRGB(120, 220, 150) or _AC1
					task.delay(1.6, function() if _lnk.Parent then _lnk.Text = _DISCORD .. "   (tap to copy)"; _lnk.TextColor3 = _AC1 end end)
				end)
				local btn = Instance.new("TextButton", c)
				btn.AnchorPoint = Vector2.new(0.5, 1); btn.Position = UDim2.new(0.5, 0, 1, -20); btn.Size = UDim2.fromOffset(160, 40); btn.BackgroundColor3 = Color3.new(1, 1, 1); btn.AutoButtonColor = false; btn.Text = ""; btn.BorderSizePixel = 0
				_uic = Instance.new("UICorner", btn); _uic.CornerRadius = UDim.new(0, 11)
				local _bgrad = Instance.new("UIGradient", btn); _bgrad.Rotation = 25; _bgrad.Color = ColorSequence.new(_AC1, _AC2)
				local _blbl = Instance.new("TextLabel", btn); _blbl.Size = UDim2.fromScale(1, 1); _blbl.BackgroundTransparency = 1; _blbl.Font = Enum.Font.GothamBold; _blbl.Text = "Dismiss"; _blbl.TextColor3 = Color3.new(1, 1, 1); _blbl.TextSize = 15; _blbl.TextXAlignment = Enum.TextXAlignment.Center
				btn.MouseButton1Click:Connect(function() pcall(function() g:Destroy() end) end)
				-- PHASE 10 (PART B): also drive the merged GUI's themed data-offline overlay with
				-- the real failure reason. This data fetch runs AFTER the GUI is built (engine
				-- L~7616 < this block), so System.showOverlay exists. The engine popup above is
				-- the primary actionable card (it survives the boot-halt return below); this is
				-- the in-panel echo. Guarded for safety. SAME real offline event drives both.
				if System.showOverlay then pcall(System.showOverlay, "dataOffline", { reason = tostring(reason) }) end
			end
			if not manifest then
				_showDataOfflinePopup("manifest fetch failed (timeout or HTTP error)")
				-- V4.3.488: silent halt instead of error(). The popup already tells the
				-- user what happened with actionable next steps; the prior error() dumped
				-- a stack trace into the executor console which was redundant noise on
				-- top of the popup. User report 2026-05-19 after seeing the V4.3.484
				-- popup fire correctly: "okay so 2 separate problem" - first being the
				-- console error stack. Park the coroutine indefinitely so the popup
				-- stays visible until user dismisses it; the script's other coroutines
				-- (capture detection teardown, etc.) keep running cleanly.
				warn("[RoClothes] No cache and manifest fetch failed - popup shown, halting boot")
				return  -- exit the do-block-enclosing function chunk silently
			end
			local version  = tostring(manifest.version or "unversioned")
			local cacheFile = CACHE_DIR .. "/data_" .. version .. ".json"
			local merged = fetchAndSaveChunks(manifest.chunks or {}, cacheFile, manifestRaw)
			if not merged then
				_showDataOfflinePopup("bundle chunks failed mid-download")
				warn("[RoClothes] Chunk fetch failed on first run - popup shown, halting boot")
				return  -- V4.3.488: silent halt; see comment above
			end
			System.ManifestVersion = version
			_RoClothesData = rehydrate(merged)
		end
	end

	-- V4.3.514: gate moved here from L7529. PartListDefault deref at L7244 (via
	-- PlayerDataDefault) runs BEFORE the prior gate location, so a failed bootstrap
	-- crashed with "attempt to index nil" before reaching the gate. Must gate here.
	if not _RoClothesData then
		warn("[Ro-Clothes] data init aborted (offline popup shown); halting RoClothes() boot.")
		return
	end

	local Mouse = Player:GetMouse()

	local Method2CharacterFolder = game.Workspace:FindFirstChild(System.M2FName)

	if not Method2CharacterFolder then
		Method2CharacterFolder = Instance.new("Folder", game.Workspace)
		Method2CharacterFolder.Name = System.M2FName
		Method2CharacterFolder.Archivable = not hidden
	end

	-- V4.3.531 hotfix #3: IS/UIS/TS/MPS hoisted to file scope (L67-71). Removed
	-- 4 RoClothes-scope register slots at the function-wide peak. Closures inside
	-- RoClothes resolve UIS/etc. as file-scope upvalues identically to before.


	-- these settings are saved and loaded --
	local loadupBundle = ""
	local loadupExecute = false
	local loadupClosed = false
	local loadupFPerson = 0
	-- PHASE 4: loadup-flag setters (Options page "On Loadup" toggles + FPerson cyc).
	-- These reassign the captured RoClothes upvalues the loadup pipeline reads
	-- (original L27386/27459/19989-20059). They are loadup-time only -> NO hotSwap
	-- (changing them has no immediate render effect). Persistence to Settings.json
	-- is handled by the Options "Save" button path, not here. System exists (L~3960).
	System.setLoadupClosed  = function(v) loadupClosed  = v and true or false end
	System.setLoadupExecute = function(v) loadupExecute = v and true or false end
	System.setLoadupFPerson = function(v) loadupFPerson = tonumber(v) or 0 end
	System.getLoadupFPerson = function() return loadupFPerson end
	System.setLoadupBundle  = function(v) loadupBundle  = tostring(v or "") end
	System.getLoadup = function(which)
		if which == "Closed" then return loadupClosed
		elseif which == "Execute" then return loadupExecute
		elseif which == "FPerson" then return loadupFPerson
		elseif which == "Bundle" then return loadupBundle end
		return nil
	end
	local KEYBIND = Enum.KeyCode.Insert
	local hpKEYBIND = Enum.KeyCode.Equals
	local dpKEYBIND = Enum.KeyCode.Minus
	-- V4.3.453: Naked Mode keybind. PC only (gated by UIS.KeyboardEnabled at the
	-- InputBegan handler). Default `N` - not in conflict with the other 3 defaults
	-- (Insert / Equals / Minus). No reassignment UI in this version; future work
	-- can add a Keybind3Button mirror of the existing KeybindButton/hpKEYBIND UI.
	local nkKEYBIND = Enum.KeyCode.N

	-- ============================================================
	-- PHASE 3 GUI<->ENGINE BRIDGE. Additive; bridge methods are
	-- System.* fields so they cost 0 RoClothes register slots. The new
	-- GUI is file-scope in _buildKrulHubGUI so it cannot see these
	-- RoClothes locals; each method below captures the locals it needs
	-- as upvalues -- all already in scope at THIS line -- and the GUI
	-- calls them lazily via ctx.System.<method> at interaction time.
	-- Reassigning a captured local such as KEYBIND = kc updates the
	-- SAME upvalue the engine's own InputBegan handler reads at L~19447.
	-- ============================================================

	-- 1. KEYBINDS -- user-flagged: must be changeable. Reassigns the
	-- captured keybind upvalue so the engine toggle/heal/dmg/naked
	-- handlers honor the new key, then auto-persists via a lazy ref to
	-- System.persistKeybinds, which is defined later at L~19426.
	System.setKeybind = function(which, kc)
		if which == "GUI" then KEYBIND = kc
		elseif which == "Heal" then hpKEYBIND = kc
		elseif which == "Dmg" then dpKEYBIND = kc
		elseif which == "Naked" then nkKEYBIND = kc end
		if System.persistKeybinds then pcall(System.persistKeybinds) end
	end

	-- Read-back of the engine's current keybinds so the GUI can show
	-- the true bound key on build (KeyCode.Name, e.g. "Insert").
	System.getKeybindName = function(which)
		local kc = (which == "GUI" and KEYBIND)
			or (which == "Heal" and hpKEYBIND)
			or (which == "Dmg" and dpKEYBIND)
			or (which == "Naked" and nkKEYBIND) or nil
		if typeof(kc) == "EnumItem" then return kc.Name end
		return nil
	end

	-- 4. PLAYER TARGET SELECTOR. The engine has no getSelectPlayer or
	-- setSelectPlayer in this build -- they were ctx fields of the old
	-- extraction; here SelectPlayer is a plain RoClothes local -- so the
	-- bridge writes the captured SelectPlayer upvalue directly. The
	-- engine reads GUIObject.PlayerExecute.Text == "Self" at L~15294 in
	-- Function.CharacterReset, so we store "Self" for self there.
	-- Returns the display text the field should show.
	System.setSelect = function(name)
		-- switching away from a possessed clone auto-releases control (so you never lose track of which
		-- clone you're driving with a many-clone scene) - possession is a manual toggle otherwise.
		if System._possessed and name ~= System._possessed then pcall(function() if System.releaseClone then System.releaseClone() end end) end
		local _r
		if name == nil or name == "Self" or name == Player.Name then
			SelectPlayer = Player.Name
			if GUIObject.PlayerExecute then GUIObject.PlayerExecute.Text = "Self" end
			_r = "Self (you)"
		elseif System.NPCs and System.NPCs[name] then
			-- V4.5.x clone/NPC: a synthetic target (clone or clicked NPC) tracked in System.NPCs.
			-- No real Player object; PlayerData[name] already exists (created on register).
			SelectPlayer = name
			pcall(function() if GUIObject.PlayerExecute then GUIObject.PlayerExecute.Text = tostring(name) end end)
			_r = name
		else
			local plr = PS:FindFirstChild(name)
			if plr then
				SelectPlayer = name
				pcall(Function.PlayerDataAdd, name)   -- ensure PlayerData[name] exists
				if GUIObject.PlayerExecute then GUIObject.PlayerExecute.Text = name end
				_r = name
			end
		end
		-- refresh the clone selection outline/nametag so which clone you're editing is obvious
		if System._refreshCloneVisuals then pcall(System._refreshCloneVisuals) end
		return _r  -- nil = unknown/left player: caller keeps prior selection
	end

	-- V4.5.x clone/NPC target resolution. Clones + clicked NPCs are tracked as models in
	-- System.NPCs (keyed by an arbitrary string, NOT a real Player). ResolveTargetChar maps a
	-- select-key to the workspace character to build/edit onto, so the handful of sites that
	-- fetched Players:FindFirstChild(key).Character work for synthetic targets too.
	System.CloneOrder = System.CloneOrder or {}   -- ordered clone keys (subset of System.NPCs) for the clone UI
	Function.ResolveTargetChar = function(key)
		if key ~= nil and System.NPCs and System.NPCs[key] then return System.NPCs[key] end
		local p = PS:FindFirstChild(key or "")
		return p and p.Character or nil
	end

	-- V4.5.x CLONE: spawn a frozen, fully-editable 1:1 copy of the current target as an NPC.
	System._cloneCounter = System._cloneCounter or 0
	-- Build a clean base R6 rig (clone the player's character, strip everything RoClothes added).
	System._buildCloneRig = function(key, srcChar)
		local src = srcChar or Player.Character  -- BUG5: clone the SELECTED target's body, not always yours
		if not src then return nil end
		local wasArch = src.Archivable
		src.Archivable = true
		-- 1:1 POSE: the rig poser now edits real rig-joint C0s (Motor6D/AnimationConstraint), which :Clone()
		-- copies, so the clone rides along in your current gizmo pose (the old clean-rest-pose reset was for the
		-- retired mesh-weld gizmo that exploded when its weld-C0s were cloned - no longer needed). The live
		-- animation/emote pose lives in the non-serialized joint Transform, which :Clone() drops; the POSE BAKE
		-- below folds it into the clone's static C0 so the frozen statue matches your EXACT visible pose.
		local ok, rig = pcall(function() return src:Clone() end)
		src.Archivable = wasArch
		if not ok or not rig then return nil end
		rig.Name = key
		-- POSE BAKE: gizmo C0 edits are already in the cloned C0s; the Animator-written joint Transform is NOT
		-- serialized so :Clone() drops it -> an emote/animation pose would collapse to rest. Motor6D solves
		-- Part1 = Part0*C0*Transform*C1:Inverse(); with the clone's Transform identity (Animate stripped below),
		-- C0' = C0*Transform reproduces the EXACT visible frame. R15 AnimationConstraint: bake into Attachment0
		-- + IsKinematic so it holds with no Animator. Pair clone->src by Parent.Name+Name (skip ambiguous).
		pcall(function()
			local srcJ = {}
			for _, j in ipairs(src:GetDescendants()) do
				if j:IsA("Motor6D") or j:IsA("AnimationConstraint") then
					local k = (j.Parent and j.Parent.Name or "") .. "\0" .. j.Name
					srcJ[k] = (srcJ[k] == nil) and j or false  -- false = duplicate name, skip (ambiguous)
				end
			end
			for _, j in ipairs(rig:GetDescendants()) do
				if j:IsA("Motor6D") or j:IsA("AnimationConstraint") then
					local s = srcJ[(j.Parent and j.Parent.Name or "") .. "\0" .. j.Name]
					if s and s.ClassName == j.ClassName then
						pcall(function()
							if j:IsA("Motor6D") then
								j:SetAttribute("_RCoC0", s.C0)  -- V4.5.17: remember the UN-baked C0 so possession restores clean live animation (else live walk Transform stacks on the frozen pose)
								j.C0 = s.C0 * s.Transform
							else
								local a0, sa0 = j.Attachment0, s.Attachment0
								if a0 and sa0 then a0:SetAttribute("_RCoCF", sa0.CFrame); a0.CFrame = sa0.CFrame * s.Transform end
								j.IsKinematic = true
							end
						end)
					end
				end
			end
		end)
		-- HIDE-ORIGINALS CARRY-OVER: RoClothes hides the real body parts with LocalTransparencyModifier=1 (render-only,
		-- NOT copied by :Clone()), so a raw clone shows the ORIGINAL body under the custom RoClothes mesh. Bake the
		-- source's hidden base body into the clone as REAL Transparency (static mannequin, no Humanoid to fight it).
		-- SCOPE = only the ORIGINAL base-body part NAMES (R6 + R15): a flat all-names set wrongly hid legit parts that
		-- share a name (every accessory handle is "Handle" -> it hid all hair/accessories). FP GUARD: the ENGINE writes
		-- LTM=1 on EVERY part while you're in first person, so for your OWN char in FP we ignore LTM (only trust real
		-- Transparency>=1) - else cloning yourself zoomed-in would bake the whole clone invisible.
		-- REG-FIX (V4.5.17): SKIP the bake when the source is APPLIED (a Method2 proxy exists, or src has RCTag meshes). The
		-- managed apply (spawnClone/syncCloneFromSelf) rebuilds + hides the base itself; baking Transparency=1 here would be
		-- snapshotted by CharacterReset as the base's 'original', so a later clone Reset restored invisibility -> invisible
		-- mannequin. For a PLAIN (non-applied) source the base isn't hidden, so the bake is a no-op anyway.
		local _bakeApplied = false
		do local _m2f = System.M2FName and workspace:FindFirstChild(System.M2FName); _bakeApplied = (_m2f and src and _m2f:FindFirstChild(src.Name)) ~= nil
			if not _bakeApplied and src then for _, _d in ipairs(src:GetDescendants()) do if _d:IsA("BasePart") and _d:HasTag(System.RCTag) then _bakeApplied = true break end end end end
		if not _bakeApplied then pcall(function()
			local BODY = { Torso = true, ["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true, Head = true,
				UpperTorso = true, LowerTorso = true, LeftUpperArm = true, LeftLowerArm = true, LeftHand = true, RightUpperArm = true, RightLowerArm = true, RightHand = true,
				LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true, RightUpperLeg = true, RightLowerLeg = true, RightFoot = true }
			local inFP = false
			if src == Player.Character then local cam = workspace.CurrentCamera; local hd = src:FindFirstChild("Head"); if cam and hd then inFP = (cam.CFrame.Position - hd.Position).Magnitude < 1.5 end end
			for _, r in ipairs(rig:GetDescendants()) do
				if r:IsA("BasePart") and BODY[r.Name] then
					local s = src:FindFirstChild(r.Name)
					if s and s:IsA("BasePart") and (s.Transparency >= 1 or (not inFP and s.LocalTransparencyModifier >= 1)) then r.Transparency = 1 end
				end
			end
		end) end
		-- RAW 1:1 copy: KEEP the target's current worn look exactly as it renders now (game clothing,
		-- accessories, hair, skin/BodyColors, any live RoClothes mesh). Only remove live scripts so the
		-- mannequin stays a frozen statue (no Animate/idle, no game controllers). NO RoClothes rebuild
		-- on spawn - it copies what you ACTUALLY look like, not the RoClothes body-type defaults.
		for _, d in ipairs(rig:GetDescendants()) do
			if d:IsA("Script") or d:IsA("LocalScript") then pcall(function() d:Destroy() end)
			elseif d:IsA("Accessory") then  -- owner request: clones don't wear the Hat. TAILS DO COPY NOW (owner asked for them back V4.5.17).
				local drop = false
				local okAT, at = pcall(function() return d.AccessoryType end)  -- guarded: old clients lack AccessoryType
				if okAT and at == Enum.AccessoryType.Hat then drop = true end
				if drop then pcall(function() d:Destroy() end) end
			elseif d.ClassName == "Hat" then pcall(function() d:Destroy() end)  -- legacy Hat instances
			elseif d:IsA("BackpackItem") then pcall(function() d:Destroy() end)  -- V4.5.17: strip equipped Tools/HopperBins (e.g. a host game's native "STRG_"/Ctrl-key tool) so the frozen clone never carries a duplicate of whatever you're holding
			end
		end
		-- V4.5.17: CLONE = a real managed apply target (no static graft). The clone renders its body through the SAME
		-- RoClothes Method-1 pipeline as the real player, fired on spawn (see spawnClone's deferred CharacterReset+Execute).
		-- That pipeline is IDEMPOTENT (ExecutionMaid:DoCleaning + CharacterReset clear the prior set every apply), so the clone
		-- is correct on spawn AND cleanly re-customisable with NO duplicate meshes. But :Clone() of the source drags along
		-- RoClothes meshes / VNS rigs the managed apply does NOT track (they're not in this clone's ExecutionMaid) -> they'd
		-- DOUBLE the rebuilt set (z-fighting, 'old mesh remains', breast reads missing). Strip every RoClothes-created
		-- descendant here (RCTag-tagged by Function.Weld, or RC_VNS* sub-models) so the managed apply starts from a clean base.
		pcall(function()
			for _, d in ipairs(rig:GetDescendants()) do
				if (d:IsA("BasePart") or d:IsA("Model") or d:IsA("Accessory")) and (d:HasTag(System.RCTag) or (d.Name:find("RC_VNS", 1, true) == 1)) then
					pcall(function() d:Destroy() end)
				end
			end
			-- then remove any part left unwelded + unanchored (would fall). Loop: destroying one can orphan another (e.g. a Nipple).
			for _pass = 1, 4 do
				local _wref = {}
				for _, c in ipairs(rig:GetDescendants()) do
					if c:IsA("Weld") or c:IsA("WeldConstraint") or c:IsA("Motor6D") then
						if c.Part0 then _wref[c.Part0] = true end; if c.Part1 then _wref[c.Part1] = true end
					elseif c:IsA("AnimationConstraint") or c:IsA("RigidConstraint") then  -- CRITICAL: upgraded R15 rigs joint via AnimationConstraint (0 Motor6D), accessories via RigidConstraint - both use Attachment0/1 (parent = the part), NOT Part0/1. Without this the sweep saw every R15 body part as unreferenced + unanchored and DESTROYED the whole clone body.
						local _a0, _a1 = c.Attachment0, c.Attachment1
						if _a0 and _a0.Parent and _a0.Parent:IsA("BasePart") then _wref[_a0.Parent] = true end
						if _a1 and _a1.Parent and _a1.Parent:IsA("BasePart") then _wref[_a1.Parent] = true end
					end
				end
				local _any = false
				for _, m in ipairs(rig:GetDescendants()) do
					if m:IsA("BasePart") and not m.Anchored and not _wref[m] then pcall(function() m:Destroy() end); _any = true end
				end
				if not _any then break end
			end
		end)
		pcall(function() rig:AddTag(System.RCTag) end)
		rig.Parent = workspace
		return rig
	end
	System.spawnClone = function()
		local srcKey = SelectPlayer or Player.Name
		local srcPD = PlayerData[srcKey]
		if not srcPD then return nil end
		System._cloneCounter = System._cloneCounter + 1
		local key = "clone_" .. System._cloneCounter
		local rig = System._buildCloneRig(key, Function.ResolveTargetChar(srcKey))
		if not rig then System._cloneCounter = System._cloneCounter - 1; return nil end
		-- position: ALL clones spawn at the SAME spot in front of the player, facing them (face to face).
		-- They overlap on spawn (collision is off, below); possess a clone to walk it into place.
		local base = (Player.Character and Player.Character:GetPivot()) or CFrame.new()
		pcall(function()
			local pos = base.Position + base.LookVector * 6
			rig:PivotTo(CFrame.lookAt(pos, Vector3.new(base.Position.X, pos.Y, base.Position.Z)))
		end)
		-- register as an NPC (reuse the NPC system) + Destroying auto-prune
		System.NPCs[key] = rig
		table.insert(System.CloneOrder, key)
		pcall(function()
			local _conn; _conn = rig.Destroying:Connect(function()
				-- only prune if THIS rig is still the registered one (a "Copy my look" rig-swap
				-- destroys the old rig AFTER pointing the registry at the new one - don't nil that).
				if System.NPCs[key] ~= rig then if _conn then pcall(function() System.GlobalMaid:Remove(_conn) end) end return end
				System.NPCs[key] = nil
				for i, k in ipairs(System.CloneOrder) do if k == key then table.remove(System.CloneOrder, i) break end end
				local _pd = PlayerData[key]
				if _pd then
					if _pd.ExecutionMaid then pcall(function() _pd.ExecutionMaid:DoCleaning() end) end
					PlayerData[key] = nil
				end
				if _conn then pcall(function() System.GlobalMaid:Remove(_conn) end) end
			end)
			System.GlobalMaid:Give(_conn)
		end)
		-- DeepClone the current look into the clone's PD (mirror the click-NPC seed at L26854+)
		local cData = Function.DeepClone(srcPD, {
			CurrentPartList = true, ExecutionMaid = true, Connections = true, OldestClothings = true,
			ConvertedPart = true, OldTransparency = true, OriginalAttachmentCFrames = true,
			_strippedAccessories = true, OriginalHumanoidDescription = true,
			-- CLONE FIX: never inherit the source's pre-RoClothes BodyColors snapshot (it's the
			-- pristine/template colour = BLACK in this project). CharacterReset(rig) would BodyColorSet
			-- it onto the rig -> black skin + black VNS meshes (Function.Weld resolves mesh colour from
			-- Parent.Color). The rig was Clone()'d with the LIVE painted BodyColors, which is correct;
			-- the clone captures its OWN snapshot on first CharacterExecute.
			OriginalBodyColors = true,
			-- CLONE FIX: don't inherit Instance refs to the SOURCE character - CharacterReset resolves
			-- its target from DataList.Character/RealCharacter, so a leaked ref makes the reset (and
			-- transparency/HD restore) hit the source player instead of the clone.
			Character = true, RealCharacter = true,
		})
		cData.CurrentPartList             = Function.PlayerDataDefault().CurrentPartList
		cData.Connections                 = {}
		cData.OldestClothings             = { Shirt = nil, Pants = nil, ShirtGraphic = nil }
		cData.ConvertedPart               = {}
		cData.OldTransparency             = {}
		cData.OriginalAttachmentCFrames   = {}
		cData._strippedAccessories        = setmetatable({}, { __mode = "k" })
		cData.OriginalHumanoidDescription = nil
		-- CLONE FIX 3: seed a CORRECT, PERSISTENT skin snapshot from the SOURCE's live (painted)
		-- BodyColors instance. This is the lever the restore block in CharacterReset uses to repaint
		-- skin onto the rig's BodyColors instance AND base parts on EVERY reset -> the VNS meshes
		-- (Function.Weld reads Parent.Color) come out skin every rebuild. Kept non-nil forever (EDIT B
		-- gates the nil to non-clones) so SnapshotOriginalBodyColors (early-returns when non-nil) can
		-- never overwrite it with the rig's post-build BLACK classic BodyColors. Shape matches
		-- Function.SnapshotOriginalBodyColors.
		do
			local _srcChar = Function.ResolveTargetChar(srcKey)
			local _bc = _srcChar and _srcChar:FindFirstChildOfClass("BodyColors")
			if _bc then
				cData.OriginalBodyColors = {
					HeadColor3     = _bc.HeadColor3,
					TorsoColor3    = _bc.TorsoColor3,
					LeftArmColor3  = _bc.LeftArmColor3,
					RightArmColor3 = _bc.RightArmColor3,
					LeftLegColor3  = _bc.LeftLegColor3,
					RightLegColor3 = _bc.RightLegColor3,
				}
			else
				cData.OriginalBodyColors = nil  -- no instance: fall back to first-build snapshot
			end
		end
		cData.Character                   = rig   -- reset/execute target = the rig, never the source char
		cData.RealCharacter               = nil
		-- CLONE FIX 2: pin the skin explicitly. Otherwise skin is re-derived from the rig's
		-- BodyColors each build, and after the first build cycle the classic BodyColors goes
		-- black (hidden under the mesh) -> a later EDIT (CharacterReset+re-snapshot) locks black
		-- in. Setting SkinTone makes the colour pipeline deterministic across every rebuild.
		if not cData.SkinTone then
			local _srcChar = Function.ResolveTargetChar(srcKey)
			local _srcBC = _srcChar and _srcChar:FindFirstChildOfClass("BodyColors")
			if _srcBC then cData.SkinTone = _srcBC.TorsoColor3 end
		end
		cData.LastRequestID               = (cData.LastRequestID or 0) + 1
		cData.IsClone                     = true
		cData.CloneName                   = nil    -- custom name (System.renameClone); default "Clone N"
		cData.CloneNameHidden             = false  -- nametag shown by default (to identify); hideable
		-- Freeze: reuse the existing per-PD "Animations" master-freeze (early-outs the jiggle/
		-- breathing/overtone/tail loops at L26537/26660) so the mannequin stays still + cheap.
		cData.AnimationsFrozen            = true
		PlayerData[key] = cData
		-- V4.5.17: the rig is a clean base body (RoClothes meshes stripped in _buildCloneRig); the managed apply
		-- fired below (task.defer, end of this fn) builds the look through the tracked pipeline. Editing re-runs it.
		-- freeze: anchor + stop the humanoid so it stands still
		local hrp = rig:FindFirstChild("HumanoidRootPart")
		if hrp then hrp.Anchored = true end
		local hum = rig:FindFirstChildOfClass("Humanoid")
		if hum then hum.PlatformStand = true; hum.AutoRotate = false end
		-- collision OFF: overlap freely; the player + other clones pass through (re-asserted by a loop)
		for _, d in ipairs(rig:GetDescendants()) do if d:IsA("BasePart") then pcall(function() d.CanCollide = false end) end end
		-- hide the default Humanoid overhead name/health; we use our own renamable nametag instead
		if hum then pcall(function() hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None end) end
		pcall(function()
			local head = rig:FindFirstChild("Head") or hrp
			if head then
				local tag = Instance.new("BillboardGui")
				tag.Name = "_CloneTag"; tag.Adornee = head; tag.Size = UDim2.fromOffset(130, 28)
				tag.StudsOffsetWorldSpace = Vector3.new(0, 2.9, 0); tag.AlwaysOnTop = true; tag.MaxDistance = 250; tag.Parent = rig
				local bl = Instance.new("TextLabel")
				bl.Name = "L"; bl.Size = UDim2.fromScale(1, 1); bl.BackgroundColor3 = Color3.fromRGB(22, 22, 30); bl.BackgroundTransparency = 0.3
				bl.Font = Enum.Font.GothamBold; bl.TextSize = 13; bl.TextColor3 = Color3.fromRGB(240, 240, 245); bl.Text = key; bl.Parent = tag
				local uc = Instance.new("UICorner"); uc.CornerRadius = UDim.new(0, 7); uc.Parent = bl
			end
		end)
		if System._refreshCloneVisuals then pcall(System._refreshCloneVisuals) end
		-- (click-to-drag removed - possess a clone to walk it around instead)
		-- V4.5.17: MANAGED FIRST BUILD - but ONLY if the source is ACTUALLY wearing a RoClothes look right now.
		-- The managed apply rebuilds from the DeepCloned PD (settings), which is only == your current appearance when
		-- you've applied it. If you're a PLAIN avatar (look not applied - e.g. fresh join, or you reset yourself), your
		-- PD still holds default body settings, so a forced apply would dress the clone in a body you're NOT wearing ->
		-- "my clone is different from me". Detect applied-state by a live signal: a Method2 proxy for you exists, OR your
		-- character carries RoClothes meshes (RCTag). Not applied -> leave the clone as the raw 1:1 copy it already is
		-- (matches you exactly); a later customize still runs the managed apply on that clean base.
		local _srcApplied = false
		do
			local _m2f = System.M2FName and workspace:FindFirstChild(System.M2FName)
			_srcApplied = (_m2f and _m2f:FindFirstChild(srcKey)) ~= nil
			if not _srcApplied then
				local _sc = Function.ResolveTargetChar(srcKey)
				if _sc then for _, d in ipairs(_sc:GetDescendants()) do if d:IsA("BasePart") and d:HasTag(System.RCTag) then _srcApplied = true break end end end
			end
		end
		if _srcApplied then
			-- Fire the SAME Method-1 apply the customize path uses (doExecute L~10990): the clone renders its body through
			-- the ONE tracked, idempotent pipeline (no static graft, no duplicate meshes; later edits rebuild cleanly).
			cData.Cooldown = false  -- DeepClone may have carried a mid-apply true; clear so the first build isn't gated
			task.defer(function()
				if System.NPCs[key] ~= rig then return end  -- clone was replaced/destroyed before the defer ran
				local _rid = (PlayerData[key] and PlayerData[key].LastRequestID) or cData.LastRequestID
				pcall(Function.CharacterReset, rig)  -- Model form: resolves the NPC/clone by instance
				local _ok, _err = pcall(Function.CharacterExecute, rig, key, nil, _rid)
				if not _ok then warn("[RoClothes] clone first build:", _err) end
			end)
		end
		return key
	end
		-- Copy my CURRENT look onto an existing clone (re-sync a stale clone in one tap).
		-- Mirrors spawnClone's PD-seed but reuses the rig + preserves the clone's own identity
		-- (name / hidden / frozen). Source = Self (the player's own live avatar).
		System.syncCloneFromSelf = function(key)
			if not (key and System.NPCs and System.NPCs[key]) then return false end
			local oldRig = System.NPCs[key]
			local srcChar = Function.ResolveTargetChar(Player.Name)
			if not srcChar then return false end
			local oldPD = PlayerData[key] or {}
			if System._possessed == key and System.releaseClone then pcall(System.releaseClone) end
			-- RAW re-copy: rebuild the rig as a fresh 1:1 duplicate of your CURRENT look (same as spawn) -
			-- no RoClothes rebuild, so it copies what you ACTUALLY look like now (keeps game clothing, no phantom body).
			local cf = oldRig:GetPivot()
			local newRig = System._buildCloneRig(key, srcChar)
			if not newRig then return false end
			pcall(function() newRig:PivotTo(cf) end)  -- keep it where the old one stood
			System.NPCs[key] = newRig                 -- point registry at the new rig BEFORE destroying old
			pcall(function() oldRig:Destroy() end)    -- guarded Destroying hook no-ops (registry != oldRig)
			pcall(function()
				local _conn; _conn = newRig.Destroying:Connect(function()
					if System.NPCs[key] ~= newRig then if _conn then pcall(function() System.GlobalMaid:Remove(_conn) end) end return end
					System.NPCs[key] = nil
					for i, k in ipairs(System.CloneOrder) do if k == key then table.remove(System.CloneOrder, i) break end end
					local _pd = PlayerData[key]
					if _pd then if _pd.ExecutionMaid then pcall(function() _pd.ExecutionMaid:DoCleaning() end) end PlayerData[key] = nil end
					if _conn then pcall(function() System.GlobalMaid:Remove(_conn) end) end
				end)
				System.GlobalMaid:Give(_conn)
			end)
			-- V4.5.19 FIX: reseed the clone's PlayerData FROM the source (self) PD, mirroring spawnClone's
			-- DeepClone seed (L10633+). Pre-fix syncCloneFromSelf left PlayerData[key] as the clone's OWN
			-- stale PD and only patched a few fields, so when you were wearing an applied RoClothes look the
			-- deferred CharacterReset+CharacterExecute below rebuilt the clone from its OLD settings --
			-- "Copy my look" silently reverted the clone instead of matching you. Now the clone's PD == your
			-- PD (minus per-clone identity, transient tables, and live instance refs).
			local srcPD = PlayerData[Player.Name]
			if type(srcPD) == "table" then
				local cData = Function.DeepClone(srcPD, {
					CurrentPartList = true, ExecutionMaid = true, Connections = true, OldestClothings = true,
					ConvertedPart = true, OldTransparency = true, OriginalAttachmentCFrames = true,
					_strippedAccessories = true, OriginalHumanoidDescription = true,
					OriginalBodyColors = true, Character = true, RealCharacter = true,
				})
				cData.CurrentPartList             = Function.PlayerDataDefault().CurrentPartList
				cData.Connections                 = {}
				cData.OldestClothings             = { Shirt = nil, Pants = nil, ShirtGraphic = nil }
				cData.ConvertedPart               = {}
				cData.OldTransparency             = {}
				cData.OriginalAttachmentCFrames   = {}
				cData._strippedAccessories        = setmetatable({}, { __mode = "k" })
				cData.OriginalHumanoidDescription = nil
				cData.ExecutionMaid               = oldPD.ExecutionMaid   -- keep the clone's OWN maid (Destroying hook cleans via it)
				cData.Character                   = newRig
				cData.RealCharacter               = nil
				cData.IsClone                     = true
				cData.AnimationsFrozen            = true
				cData.CloneName                   = oldPD.CloneName
				cData.CloneNameHidden             = oldPD.CloneNameHidden or false
				cData.LastRequestID               = ((oldPD and oldPD.LastRequestID) or 0) + 1
				PlayerData[key] = cData
			end
			local pd = PlayerData[key]
			if pd then
				pd.Character = newRig; pd.RealCharacter = nil; pd.IsClone = true; pd.AnimationsFrozen = true
				pd.CloneName = oldPD.CloneName; pd.CloneNameHidden = oldPD.CloneNameHidden or false
				local _bc = srcChar:FindFirstChildOfClass("BodyColors")
				if _bc then
					pd.OriginalBodyColors = { HeadColor3=_bc.HeadColor3, TorsoColor3=_bc.TorsoColor3, LeftArmColor3=_bc.LeftArmColor3, RightArmColor3=_bc.RightArmColor3, LeftLegColor3=_bc.LeftLegColor3, RightLegColor3=_bc.RightLegColor3 }
					pd.SkinTone = _bc.TorsoColor3
				end
			end
			local hrp = newRig:FindFirstChild("HumanoidRootPart"); if hrp then hrp.Anchored = true end
			local hum = newRig:FindFirstChildOfClass("Humanoid")
			if hum then hum.PlatformStand = true; hum.AutoRotate = false; pcall(function() hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None end) end
			for _, d in ipairs(newRig:GetDescendants()) do if d:IsA("BasePart") then pcall(function() d.CanCollide = false end) end end
			pcall(function()
				local head = newRig:FindFirstChild("Head") or hrp
				if head and not newRig:FindFirstChild("_CloneTag") then
					local tag = Instance.new("BillboardGui")
					tag.Name = "_CloneTag"; tag.Adornee = head; tag.Size = UDim2.fromOffset(130, 28)
					tag.StudsOffsetWorldSpace = Vector3.new(0, 2.9, 0); tag.AlwaysOnTop = true; tag.MaxDistance = 250; tag.Parent = newRig
					local bl = Instance.new("TextLabel")
					bl.Name = "L"; bl.Size = UDim2.fromScale(1, 1); bl.BackgroundColor3 = Color3.fromRGB(22, 22, 30); bl.BackgroundTransparency = 0.3
					bl.Font = Enum.Font.GothamBold; bl.TextSize = 13; bl.TextColor3 = Color3.fromRGB(240, 240, 245); bl.Text = key; bl.Parent = tag
					local uc = Instance.new("UICorner"); uc.CornerRadius = UDim.new(0, 7); uc.Parent = bl
				end
			end)
			if System._refreshCloneVisuals then pcall(System._refreshCloneVisuals) end
			-- V4.5.17: managed rebuild ONLY if you're actually wearing a RoClothes look (proxy or RCTag meshes); else the
			-- raw copy already matches your plain avatar. Same gate as spawnClone - keeps a re-synced clone == you.
			local _srcApplied = false
			do
				local _m2f = System.M2FName and workspace:FindFirstChild(System.M2FName)
				_srcApplied = (_m2f and _m2f:FindFirstChild(Player.Name)) ~= nil
				if not _srcApplied and srcChar then
					for _, d in ipairs(srcChar:GetDescendants()) do if d:IsA("BasePart") and d:HasTag(System.RCTag) then _srcApplied = true break end end
				end
			end
			if pd and _srcApplied then
				pd.Cooldown = false; pd.LastRequestID = (pd.LastRequestID or 0) + 1
				local _rid = pd.LastRequestID
				task.defer(function()
					if System.NPCs[key] ~= newRig then return end
					pcall(Function.CharacterReset, newRig)
					local _ok, _err = pcall(Function.CharacterExecute, newRig, key, nil, _rid)
					if not _ok then warn("[RoClothes] clone resync build:", _err) end
				end)
			end
			return true
		end

	-- Clone manager: list (Self + clones), remove one, clear all.
	System.getCloneList = function()
		-- RECONCILE first: drop any registered clone whose model is gone (destroyed externally, teardown race, or a
		-- deferred-Destroying prune that bailed because NPCs[key] was niled first). Otherwise the row lingers as a
		-- "ghost" you can see but cannot click into. Prune CloneOrder + NPCs + PlayerData together so it self-heals.
		do local i = 1; while i <= #System.CloneOrder do
			local k = System.CloneOrder[i]; local m = System.NPCs[k]
			if not (m and m.Parent) then
				table.remove(System.CloneOrder, i); System.NPCs[k] = nil
				local _pd = PlayerData[k]; if _pd then pcall(function() if _pd.ExecutionMaid then _pd.ExecutionMaid:DoCleaning() end end); PlayerData[k] = nil end
				if SelectPlayer == k then SelectPlayer = Player.Name end
			else i = i + 1 end
		end end
		local sel = SelectPlayer or Player.Name
		local out = { { key = Player.Name, label = "Self", selected = (sel == Player.Name) } }
		for _, k in ipairs(System.CloneOrder) do
			out[#out + 1] = {
				key = k,
				label = System._cloneDisplayName(k),
				selected = (sel == k),
				nameHidden = (PlayerData[k] and PlayerData[k].CloneNameHidden) or false,
			}
		end
		return out
	end
	System.removeClone = function(key)
		if not (System.NPCs and System.NPCs[key]) then return false end
		local model = System.NPCs[key]
		pcall(function() if model then model:Destroy() end end)  -- fires the Destroying auto-prune
		-- belt-and-suspenders in case the Destroying hook is deferred:
		System.NPCs[key] = nil
		for i, k in ipairs(System.CloneOrder) do if k == key then table.remove(System.CloneOrder, i) break end end
		local _pd = PlayerData[key]
		if _pd then
			if _pd.ExecutionMaid then pcall(function() _pd.ExecutionMaid:DoCleaning() end) end
			PlayerData[key] = nil
		end
		if SelectPlayer == key then System.setSelect(nil) end
		return true
	end
	System.clearClones = function()
		local keys = {}
		for _, k in ipairs(System.CloneOrder) do keys[#keys + 1] = k end
		for _, k in ipairs(keys) do System.removeClone(k) end
	end
	-- Display name: custom (renamed) or "Clone N" by list order.
	System._cloneDisplayName = function(key)
		local pd = PlayerData[key]
		if pd and pd.CloneName and pd.CloneName ~= "" then return pd.CloneName end
		for i, k in ipairs(System.CloneOrder) do if k == key then return "Clone " .. i end end
		return "Clone"
	end
	-- Refresh per-clone world visuals: nametag text/visibility + a Highlight outline on the
	-- currently-selected clone (so which one you're editing is obvious, even with names hidden).
	System._refreshCloneVisuals = function()
		local sel = SelectPlayer
		for _, key in ipairs(System.CloneOrder) do
			local model = System.NPCs[key]
			if model and model.Parent then
				local isSel = (sel == key)
				local pd = PlayerData[key]
				local tag = model:FindFirstChild("_CloneTag")
				if tag then
					tag.Enabled = not (pd and pd.CloneNameHidden)
					local bl = tag:FindFirstChild("L")
					if bl then
						bl.Text = System._cloneDisplayName(key)
						bl.TextColor3 = isSel and Color3.fromRGB(255, 150, 190) or Color3.fromRGB(240, 240, 245)
						bl.BackgroundColor3 = isSel and Color3.fromRGB(70, 22, 44) or Color3.fromRGB(22, 22, 30)
					end
				end
				local hl = model:FindFirstChild("_CloneSel")
				if isSel then
					if not hl then hl = Instance.new("Highlight"); hl.Name = "_CloneSel"; hl.Parent = model end
					hl.FillColor = Color3.fromRGB(255, 90, 150); hl.FillTransparency = 0.75
					hl.OutlineColor = Color3.fromRGB(255, 130, 180); hl.OutlineTransparency = 0
					pcall(function() hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop end)
				elseif hl then
					hl:Destroy()
				end
			end
		end
	end
	System.renameClone = function(key, newName)
		local pd = PlayerData[key]; if not pd then return false end
		newName = tostring(newName or ""):sub(1, 40)
		pd.CloneName = (newName ~= "" and newName) or nil
		if System._refreshCloneVisuals then System._refreshCloneVisuals() end
		if System.renderCloneList then pcall(System.renderCloneList) end
		return true
	end
	System.setCloneNameHidden = function(key, hidden)
		local pd = PlayerData[key]; if not pd then return false end
		pd.CloneNameHidden = hidden and true or false
		if System._refreshCloneVisuals then System._refreshCloneVisuals() end
		return true
	end
	-- POSSESS: take direct control of a clone (WASD walk + Space jump, camera-relative), with walk/jump
	-- animation. Release (or switching selection away) re-freezes it in its new spot. The player's own
	-- character is frozen meanwhile. Collision is ON only for the possessed clone (so it walks/jumps on
	-- the floor); all other clones stay collision-OFF so you pass through them.
	System._possessed = nil
	System.isPossessing = function(key) return System._possessed == key end
	System.releaseClone = function()
		local key = System._possessed
		if not key then return false end  -- BUG6: not possessing - don't touch camera/anchor with stale state
		System._possessed = nil
		-- V4.5.17: RE-BAKE the clone in its CURRENT animated pose BEFORE stopping the tracks. Fold the live Animator
		-- Transform back into C0 (C0 = origC0*Transform); once the tracks stop and Transform decays to 0 the joints hold
		-- this frozen pose (mirrors the spawn-time bake). Without this, un-baked joints would snap to rest on release.
		do local _m = key and System.NPCs[key]; if _m then pcall(function()
			for _, j in ipairs(_m:GetDescendants()) do
				if j:IsA("Motor6D") then
					local o = j:GetAttribute("_RCoC0"); if typeof(o) == "CFrame" then j.C0 = o * j.Transform end
				elseif j:IsA("AnimationConstraint") then
					local a0 = j.Attachment0; local o = a0 and a0:GetAttribute("_RCoCF"); if a0 and typeof(o) == "CFrame" then a0.CFrame = o * j.Transform end
						pcall(function() j.IsKinematic = true end)  -- REG-FIX: re-freeze EVERY AnimationConstraint on release, even ones the spawn bake skipped (possess set IsKinematic=false unconditionally -> a skipped joint was left limp with no animator)
				end
			end
		end) end end
		if System._possessConn then pcall(function() System._possessConn:Disconnect() end); System._possessConn = nil end
		if System._possessTracks then for _, t in pairs(System._possessTracks) do pcall(function() t:Stop() end) end; System._possessTracks = nil end
		-- BUG2b: re-freeze jiggle/breathing so an idle parked clone stays a still mannequin.
		local _rpd = PlayerData[key]
		if _rpd then
			-- V4.5.24 Fix: a captured nil (target never set AnimationsFrozen = was NOT frozen) used to
			-- restore TRUE here, silently freezing jiggle/breathing the user never froze. Restore nil
			-- as false (falsy = unfrozen, identical semantics to the nil default). true stays true.
			_rpd.AnimationsFrozen = (System._possessPrevFrozen == nil) and false or System._possessPrevFrozen
		end
		System._possessPrevFrozen = nil
		local model = key and System.NPCs[key]
		if model then
			local hum = model:FindFirstChildOfClass("Humanoid")
			local hrp = model:FindFirstChild("HumanoidRootPart")
			if hum then pcall(function() hum:Move(Vector3.zero, false) end); hum.PlatformStand = true; hum.AutoRotate = false end
			if hrp then
				pcall(function()  -- BUG8: mid-air release - snap to the ground below before freezing
					local rp = RaycastParams.new()
					rp.FilterType = Enum.RaycastFilterType.Exclude
					rp.FilterDescendantsInstances = { model, Player.Character }
					local hit = workspace:Raycast(hrp.Position, Vector3.new(0, -60, 0), rp)
					if hit and (hrp.Position.Y - hit.Position.Y) > 3.2 then
						model:PivotTo(CFrame.new(hit.Position + Vector3.new(0, 3, 0)) * model:GetPivot().Rotation)
					end
				end)
				hrp.Anchored = true  -- re-freeze in the NEW position/facing
			end
			for _, d in ipairs(model:GetDescendants()) do if d:IsA("BasePart") then pcall(function() d.CanCollide = false end) end end
		end
		local cam = workspace.CurrentCamera
		local _prevSubj = System._possessPrevSubject
		if _prevSubj and (typeof(_prevSubj) ~= "Instance" or not _prevSubj.Parent) then _prevSubj = nil end  -- BUG6: destroyed/stale
		if cam then pcall(function() cam.CameraSubject = _prevSubj or (Player.Character and Player.Character:FindFirstChildOfClass("Humanoid")) end) end
		local pc = Player.Character
		local pHrp = pc and pc:FindFirstChild("HumanoidRootPart")
		if pHrp then pHrp.Anchored = System._possessPrevAnchor and true or false end
		System._possessPrevSubject = nil
		System._possessPrevAnchor = nil
		if System.renderCloneList then pcall(System.renderCloneList) end
		return true
	end
	System.possessClone = function(key)
		local model = System.NPCs[key]; if not model then return false end
		if System._possessed == key then return true end  -- BUGFIX: already driving this clone; without this guard a re-possess re-captures _possessPrevAnchor/_possessPrevSubject from the ALREADY-modified state (player HRP already anchored, camera already on the clone) -> a later releaseClone leaves the player frozen.
		if System._possessed and System._possessed ~= key then System.releaseClone() end
		local hum = model:FindFirstChildOfClass("Humanoid")
		local hrp = model:FindFirstChild("HumanoidRootPart")
		if not (hum and hrp) then return false end
		System._possessed = key
		-- BUG2b: unfreeze jiggle/breathing/tail while driving (motion exists now); restored on release.
		local _ppd = PlayerData[key]
		if _ppd then
			System._possessPrevFrozen = _ppd.AnimationsFrozen
			_ppd.AnimationsFrozen = false
		end
		hrp.Anchored = false; hum.PlatformStand = false; hum.AutoRotate = true
		-- BUG3: only the classic rig limbs collide (walk on floor); welded organ/cloth meshes never do.
		local _COLLIDE_OK = { HumanoidRootPart = true, Torso = true, Head = true,
			["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
			UpperTorso = true, LowerTorso = true, LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
			RightUpperLeg = true, RightLowerLeg = true, RightFoot = true }
		for _, d in ipairs(model:GetDescendants()) do
			if d:IsA("BasePart") then
				local _on = (_COLLIDE_OK[d.Name] == true) and (d.Parent == model)
				pcall(function() d.CanCollide = _on end)
			end
		end
		local pc = Player.Character
		local pHrp = pc and pc:FindFirstChild("HumanoidRootPart")
		System._possessPrevAnchor = pHrp and pHrp.Anchored or false
		if pHrp then pHrp.Anchored = true end
		local cam = workspace.CurrentCamera
		System._possessPrevSubject = cam and cam.CameraSubject or nil
		if cam then cam.CameraSubject = hum end
		-- V4.5.17: UN-BAKE the frozen pose. On spawn each joint folds the Animator Transform into C0 (C0 = origC0*Transform)
		-- so the clone holds its pose with no animator. Restore the ORIGINAL C0/attachment here so the live walk/idle
		-- Animator (below) drives the joints cleanly instead of STACKING on the frozen pose (that was the "still stuck in
		-- suspended animation while WASD-driving" bug). Re-baked on release so it re-freezes where you parked it.
		pcall(function()
			for _, j in ipairs(model:GetDescendants()) do
				if j:IsA("Motor6D") then
					local o = j:GetAttribute("_RCoC0"); if typeof(o) == "CFrame" then j.C0 = o end
				elseif j:IsA("AnimationConstraint") then
					j.IsKinematic = false
					local a0 = j.Attachment0; local o = a0 and a0:GetAttribute("_RCoCF"); if a0 and typeof(o) == "CFrame" then a0.CFrame = o end
				end
			end
		end)
		-- animation driver (best-effort; the default anim assets may not load in an unpublished Studio place)
		local SET = (hum.RigType == Enum.HumanoidRigType.R15)
			and { idle = "rbxassetid://507766388", walk = "rbxassetid://913402848", jump = "rbxassetid://507765000", fall = "rbxassetid://507767968" }
			or  { idle = "rbxassetid://180435571", walk = "rbxassetid://180426354", jump = "rbxassetid://125750702", fall = "rbxassetid://180436148" }
		local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
		local tracks, cur = {}, nil
		pcall(function() for nm, id in pairs(SET) do local a = Instance.new("Animation"); a.AnimationId = id; tracks[nm] = animator:LoadAnimation(a) end end)
		System._possessTracks = tracks
		local function play(nm)
			if cur == nm then return end
			cur = nm
			for n, t in pairs(tracks) do if n == nm then pcall(function() t:Play(0.1) end) else pcall(function() t:Stop(0.1) end) end end
		end
		local RunS, UIS = game:GetService("RunService"), game:GetService("UserInputService")
		if System._possessConn then pcall(function() System._possessConn:Disconnect() end) end
		System._possessConn = RunS.RenderStepped:Connect(function()
			if System._possessed ~= key or not model.Parent then System.releaseClone(); return end
			if UIS:GetFocusedTextBox() then pcall(function() hum:Move(Vector3.zero, false) end); play("idle"); return end
			local cam2 = workspace.CurrentCamera
			local dir = Vector3.zero
			if cam2 then
				if UIS:IsKeyDown(Enum.KeyCode.W) then dir += cam2.CFrame.LookVector end
				if UIS:IsKeyDown(Enum.KeyCode.S) then dir -= cam2.CFrame.LookVector end
				if UIS:IsKeyDown(Enum.KeyCode.D) then dir += cam2.CFrame.RightVector end
				if UIS:IsKeyDown(Enum.KeyCode.A) then dir -= cam2.CFrame.RightVector end
			end
			dir = Vector3.new(dir.X, 0, dir.Z)
			local moving = dir.Magnitude > 0.05
			pcall(function() hum:Move(moving and dir.Unit or Vector3.zero, false) end)
			if UIS:IsKeyDown(Enum.KeyCode.Space) then pcall(function() hum.Jump = true end) end
			local st = hum:GetState()
			if st == Enum.HumanoidStateType.Jumping then play("jump")
			elseif st == Enum.HumanoidStateType.Freefall then play("fall")
			elseif moving then play("walk")
			else play("idle") end
		end)
		if System.renderCloneList then pcall(System.renderCloneList) end
		return true
	end

	-- Keep clones collision-OFF across rebuilds (an edit re-adds CanCollide=true mesh parts). The
	-- possessed clone is skipped so it can still walk/jump on the floor.
	-- BUG7: gated on a liveness flag (cleared in doDestroy) so it doesn't spin forever after teardown.
	System._cloneCollideLoopOn = true
	task.spawn(function()
		while System._cloneCollideLoopOn do
			task.wait(0.3)
			for _, k in ipairs(System.CloneOrder) do
				if k ~= System._possessed then
					local m = System.NPCs[k]
					if m then for _, d in ipairs(m:GetDescendants()) do if d:IsA("BasePart") and d.CanCollide then pcall(function() d.CanCollide = false end) end end end
				end
			end
		end
	end)

	-- 2a. EXECUTE -- Player page Actions card. Reproduces the original
	-- Execute button handler from V4.3.576 L4118-4138: selected player,
	-- bump LastRequestID, CharacterReset, CharacterExecute, then
	-- AvatarSyncPublish if self. Function.* resolved from the shared
	-- Function table at call time. Defined later: CharacterReset L15271,
	-- CharacterExecute L15782, AvatarSyncPublish L17662.
	System._execBusy = false
	System.doExecute = function()
		if System._execBusy then return end
		local sp = SelectPlayer
		local pd = PlayerData[sp]
		if pd and pd.Cooldown then return end
		System._execBusy = true
		task.delay(1, function() System._execBusy = false end)
		-- V4.5.x: resolve the target character (real player OR synthetic clone/NPC).
		local ExecuteCharacter = Function.ResolveTargetChar(sp)
		if ExecuteCharacter and pd then
			pd.LastRequestID = (pd.LastRequestID or 0) + 1
			local CurrentRequestID = pd.LastRequestID
			local isNPC = System.NPCs and System.NPCs[sp] ~= nil
			-- CharacterReset resolves an NPC by its MODEL instance, a player by NAME string.
			pcall(Function.CharacterReset, isNPC and ExecuteCharacter or sp)
			local ok, err = pcall(Function.CharacterExecute, ExecuteCharacter, sp, nil, CurrentRequestID)
			if not ok then warn("[RoClothes] CharacterExecute error:", err) end
			if sp == Player.Name then pcall(Function.AvatarSyncPublish, true) end
		end
	end

	-- 2b. RESET -- Player page Actions card. Reproduces the original Reset
	-- button handler from V4.3.576 L4140-4178: bump RID, clear bundle/
	-- clothes/catalog identity, CharacterReset, drop Method2 folder,
	-- zero gizmo offsets, refresh gizmo sliders, AvatarSyncPublish if
	-- self.
	-- NOTE: the original also calls Function.ResetBundleSettableFields. It
	-- lived in the removed GUI layer (original def at L26719) and was absent
	-- from the torn-down engine, so the call below was a guarded no-op. PHASE 10
	-- (PART A) re-added the real Function.ResetBundleSettableFields (def in the
	-- P6 do...end at engine L~23808), so this guard now resolves to the real
	-- field-reset. Guard kept as defensive belt-and-suspenders.
	System.doReset = function()
		local sp = SelectPlayer
		if PlayerData[sp] then
			PlayerData[sp].LastRequestID = (PlayerData[sp].LastRequestID or 0) + 1
			PlayerData[sp].CurrentBundle = "nil"
			PlayerData[sp].CurrentPreset = nil
			PlayerData[sp].CurrentClothingBundles = {}
			PlayerData[sp].CurrentClothes = {}
			if Function.ResetBundleSettableFields then
				pcall(Function.ResetBundleSettableFields, sp)
			end
			PlayerData[sp].SkinTone = nil
			PlayerData[sp].CatalogOutfitId = ""
			PlayerData[sp].CatalogBundleId = ""
			PlayerData[sp].CatalogUsername = ""
		end
		pcall(Function.CharacterReset, sp)  -- BUGFIX: guard like doExecute does; an engine throw here otherwise aborts the rest of doReset (Method2 folder drop, gizmo zeroing, refreshers) and escapes to the button handler.
		if Method2CharacterFolder and Method2CharacterFolder:FindFirstChild(sp) then
			Method2CharacterFolder[sp]:Destroy()
		end
		if PlayerData[sp] then
			PlayerData[sp].GizmoOffsets = {}
			PlayerData[sp].GizmoTarget = nil
			PlayerData[sp].GizmoOffset = { PosX=0, PosY=0, PosZ=0, RotX=0, RotY=0, RotZ=0, RotCF=CFrame.new() }
		end
		for _, refresh in ipairs(GizmoSliderRefreshers) do
			pcall(refresh)
		end
		if sp == Player.Name then
			Function.AvatarSyncPublish(true, true)
		end
	end

	-- 3. DESTROY -- user-flagged; Options "Danger" card. Reproduces the
	-- original Destroy button from V4.3.576 L4181: nuke BREAKER for a
	-- full script teardown. BREAKER captured from L~5298.
	System.doDestroy = function()
		System._cloneCollideLoopOn = false  -- BUG7: stop the clone collision-keeper loop on teardown
		if BREAKER then BREAKER:Destroy() end
	end
	-- ============================================================
	-- end PHASE 3 bridge
	-- ============================================================

	-- ============================================================
	-- PHASE 4 GENERIC GUI<->ENGINE BRIDGE (per-page setters).
	-- The dominant wiring model (GUI_Merge_Plan.md S10): a control mutates
	-- PlayerData[SelectPlayer].<field> (or a module flag) then calls
	-- System.hotSwap() -- the debounced reset->execute pipeline re-renders.
	-- All bridge methods are System.* fields => 0 RoClothes register slots.
	-- The new GUI is file-scope (_buildKrulHubGUI) so it cannot see these
	-- RoClothes locals; each method captures the upvalues it needs (all in
	-- scope at THIS line: SelectPlayer L~3875, PlayerData L~3827, Player,
	-- Function) and the GUI calls them lazily via ctx.System.<method>.
	-- ============================================================

	-- Current target player (the SelectPlayer upvalue, written by setSelect
	-- above). Defined here so System.setPD's getSelectPlayer lookup resolves
	-- to the real engine selection instead of always falling back to Self.
	System.getSelectPlayer = function() return SelectPlayer end

	-- GENERIC PlayerData reader: the new GUI cannot see the PlayerData upvalue,
	-- so it reads current engine state through this for (a) seeding each control's
	-- displayed value on build and (b) computing the next value of momentary
	-- toggle-style buttons (BundleBodyColor / Face). Returns nil if no PD yet.
	System.getPD = function(field)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		if pd then return pd[field] end
		return nil
	end

	-- PHASE 13 (ISSUE 5): live body-part-physics count for the GUI footer's "Phys" readout.
	-- Reproduces the original diagnostics loop's count (orig L3382-3392): number of keys in the
	-- active player's CurrentPartList.BodyPartPhysics. A System.* field = 0 RoClothes registers.
	-- (A reading of 0 is correct/expected when no body-part physics is active -- not a bug.)
	System.getPhysCount = function()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		if not (pd and pd.CurrentPartList and pd.CurrentPartList.BodyPartPhysics) then return 0 end
		local n = 0
		for _ in pairs(pd.CurrentPartList.BodyPartPhysics) do n = n + 1 end
		return n
	end

	-- ============================================================
	-- PHASE 14 (ISSUE 6): BODY-TYPE DRAWER bridge. The merged Body page replaced the
	-- original's NAMED drawer with blind numeric cyclers ("Torso Type: 1"). These three
	-- methods restore the original drawer's data + the Type-6 breast Bra cycle so the GUI can
	-- list each type by NAME and pick it. The drawer SELECTION reuses System.setPD (already the
	-- _typeCyc path) -- engine wiring is unchanged. All System.* fields = 0 RoClothes registers.
	-- ============================================================

	-- Per-type NAMED labels, reproduced 1:1 from the original drawer's `_typeLabels` (orig
	-- L24153-24171). A label of `false` means that index has NO mesh data and must be HIDDEN in the
	-- drawer (ButtType 4 & 5). Returned fresh each call so the GUI can't mutate the canonical table.
	-- The GUI caps each type at the engine's Max*Type (file-scope consts L1016-1020): BreastsType 6,
	-- TorsoType 9, ArmType 5, LegsType 8, ButtType 6.
	System.getBodyTypeLabels = function()
		return {
			BreastsType = {
				[1]="Type 1",   [2]="Type 2",   [3]="Type 3",
				[4]="Type 4",   [5]="Type 5",   [6]="Type 6  [SmartBone]",
			},
			ButtType = {
				[1]="Type 1",   [2]="Type 2",   [3]="Type 3",
				[4]=false,      [5]=false,       -- no data entries for 4/5; hidden in drawer
				[6]="Type 6  [SmartBone]",
			},
			TorsoType = {[1]="Type 1",[2]="Type 2",[3]="Type 3",
				[4]="Type 4",[5]="Type 5",[6]="Type 6",[7]="Type 7",[8]="Type 8",
				[9]="Type 9  [SmartBone]"},
			ArmType   = {[1]="Type 1",[2]="Type 2",[3]="Type 3",[4]="Type 4",
				[5]="Type 5  [SmartBone]"},
			LegsType  = {[1]="Type 1",[2]="Type 2",[3]="Type 3",[4]="Type 4",
				[5]="Type 5",[6]="Type 6",[7]="Type 7",
				[8]="Type 8  [SmartBone]"},
		}
	end

	-- Max value per type (file-scope consts) so the GUI knows how many rows to offer per type.
	System.getBodyTypeMax = function()
		return { BreastsType = MaxBreastsType, TorsoType = MaxTorsoType, ArmType = MaxArmType,
			LegsType = MaxLegsType, ButtType = MaxButtType }
	end

	-- Bra state for the BreastsType=6 row (orig `_bcLabel` L24255-24263): exactly-one-equipped wins;
	-- both (corrupt) or none -> "none". Returns "none" | "bra1" | "bra2".
	System.getBraState = function()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		local cc = (pd and pd.CurrentClothes) or {}
		local h1 = table.find(cc, "Breast Clothes SB1") ~= nil
		local h2 = table.find(cc, "Breast Clothes SB2") ~= nil
		if h1 and not h2 then return "bra1" end
		if h2 and not h1 then return "bra2" end
		return "none"
	end

	-- Cycle the breast bra None -> Bra 1 -> Bra 2 -> None (orig drawer sub-button L24275-24311).
	-- Mutates pd.CurrentClothes + writes the ClothesHP {HP="TopHP",Inverse=false} default for the
	-- equipped bra (the cycle is the ONLY equip path for the Hidden SB1/SB2 -- see orig V4.3.566
	-- comment), clears both first so swaps leave no stale entry, busts the _equippedSet cache, then
	-- hotSwaps. Returns the NEW state string so the GUI can repaint the sub-button.
	System.cycleBra = function()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]; if not pd then return "none" end
		local cc = pd.CurrentClothes; if type(cc) ~= "table" then cc = {}; pd.CurrentClothes = cc end
		local has1 = table.find(cc, "Breast Clothes SB1")
		local has2 = table.find(cc, "Breast Clothes SB2")
		-- only treat as "current" if exactly one is equipped; both -> 0 (restart at Bra 1).
		local cur = (has1 and not has2) and 1 or ((has2 and not has1) and 2 or 0)
		local nxt = (cur + 1) % 3
		-- always remove BOTH first (clears any corrupt double-equip), re-finding after the first removal.
		if has1 then table.remove(cc, has1) end
		local i2 = table.find(cc, "Breast Clothes SB2")
		if i2 then table.remove(cc, i2) end
		if nxt == 1 then table.insert(cc, "Breast Clothes SB1")
		elseif nxt == 2 then table.insert(cc, "Breast Clothes SB2") end
		pd.ClothesHP = pd.ClothesHP or {}
		pd.ClothesHP["Breast Clothes SB1"] = nil
		pd.ClothesHP["Breast Clothes SB2"] = nil
		if nxt == 1 then pd.ClothesHP["Breast Clothes SB1"] = {HP = "TopHP", Inverse = false}
		elseif nxt == 2 then pd.ClothesHP["Breast Clothes SB2"] = {HP = "TopHP", Inverse = false} end
		pd._equippedSetSrc = nil  -- force _equippedSet rebuild (same-length Bra1<->Bra2 swap would miss it)
		if System.hotSwap then pcall(System.hotSwap) end
		return (nxt == 1 and "bra1") or (nxt == 2 and "bra2") or "none"
	end

	-- GENERIC PlayerData setter: write one field on the selected player's
	-- PlayerData, then hotSwap. Used by the bulk of the per-page controls.
	System.setPD = function(field, value)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		if pd then pd[field] = value end
		if System.hotSwap then System.hotSwap() end
	end

	-- [V3 MERGE - Phase 4] AutoExecute regression FIX: restore V1's Settings.json PERSIST + local-only PEER-GUARD
	-- (V4.3.511 Fix 8/11) that the generic setPD path dropped. Mirrors V1 L4361-4413 + the telem-persist env-safe
	-- pattern (L14910-14933): local-only (AutoExecute is a LOCAL-install setting; refuse to stamp it from a peer's
	-- PD), state set immediately, persist trailing-edge debounced (0.25s) + serialized via _withSettingsLock +
	-- _atomicWriteJSON using the captured `env` (Volt hides writefile from getgenv). Boot restores it (L26234).
	-- No hotSwap (AutoExecute is a loadup-mode flag, not a character change). Stamp on System.* = 0 RoClothes registers.
	System._autoExecuteStamp = 0
	System.setAutoExecute = function(st)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		if sp ~= Player.Name then return end  -- local-only: never stamp the local autoExecute from a peer's PD
		local pd = PlayerData[sp]; if not pd then return end
		pd.AutoExecute = st and true or false
		System._autoExecuteStamp = System._autoExecuteStamp + 1
		local _myStamp = System._autoExecuteStamp
		task.delay(0.25, function()
			if _myStamp ~= System._autoExecuteStamp then return end  -- superseded by a later toggle
			if not (env and env.writefile and env.readfile and env.isfile) then return end
			if type(_atomicWriteJSON) ~= "function" then return end
			local _runner = function()
				local HSr = game:GetService("HttpService")
				local merged
				if env.isfile("RClothesLerp/Settings.json") then
					local _okR, _raw = pcall(env.readfile, "RClothesLerp/Settings.json")
					if not _okR then return end
					local _okD, _dec = pcall(HSr.JSONDecode, HSr, _raw)
					if not _okD or type(_dec) ~= "table" then return end
					merged = _dec
				else merged = {} end
				local _pdLive = PlayerData and PlayerData[Player.Name]
				if not _pdLive then return end
				merged.autoExecute = _pdLive.AutoExecute
				pcall(_atomicWriteJSON, "RClothesLerp/Settings.json", merged)
			end
			if type(_withSettingsLock) == "function" then
				local _lockOk = _withSettingsLock(_runner)
				if not _lockOk then task.wait(0.5); _withSettingsLock(_runner) end  -- retry once on lock timeout
			else pcall(_runner) end
		end)
	end

	-- PHASE 15 (live-physics fix): PHYSICS slider bridge. The plain setPD path writes
	-- PlayerData[sp][field] but the *running* jiggle springs captured their Speed/Damper at
	-- SpringCreate time (L12490-12491) and never re-read SpringConfigs, so dragging a stiffness/
	-- damping slider did nothing to the live wobble until a full rebuild. This setter does what
	-- the engine's own V4.3.1 loadup path does (L20654-20664: write the shared SpringConfigs group
	-- so the NEXT SpringCreate uses it) AND pushes the value onto every currently-running spring on
	-- the selected player so the change is LIVE this frame. Re-setting Spring.Speed/.Damper goes
	-- through Function.Spring.__newindex (L11649-11660) which snapshots pos/vel then updates _speed/
	-- _damper -- the exact property-set path the engine uses; _positionVelocity reads them every
	-- frame (L11676-11677). Spring2 (overtone) is re-derived with the same SpringCreate formula
	-- (Speed*3.2 / min(Damper*2,0.95), L12499-12500). Mapping (per the SpringCreate call sites):
	--   BreastsStiffness->Breasts.Speed   BreastsDamping->Breasts.Damper   (L18545/18558, L11177)
	--   ButtsStiffness  ->Buttocks.Speed  ButtsDamping  ->Buttocks.Damper  (L18504/18518)
	--   CockStiffness   ->Default.Speed   CockDamping   ->Default.Damper   (L17557/17600; the cock
	--     spring reads DataDetail.CockStiffness/CockDamping FIRST, so the PD write above already
	--     feeds the next rebuild -- the Default write keeps the documented fallback in sync.)
	-- Running springs carry no group tag, so we route by Part.Name exactly as the engine groups
	-- them at SpringCreate: breasts = Left/Right Breast + Left/Right Nipple; butts = Left/Right Butt;
	-- everything else with physics (Rod/Cock/Balls/...) is the cock group.
	-- NOTE: deliberately NO module-level lookup tables here -- the RoClothes function (def L5106)
	-- sits right at Luau's 200-local-register ceiling, so the field/part mapping is computed INLINE
	-- inside the function body (those locals are function-scoped = 0 RoClothes registers). A
	-- System.X field assignment also costs 0 RoClothes registers (the established pattern).
	System.setPhysicsField = function(field, value)
		-- map the slider field -> (spring group, which spring property). Returns nil group for any
		-- non-physics field (then we fall back to the normal setPD path).
		local grp, prop
		if     field == "BreastsStiffness" then grp, prop = "Breasts",  "Speed"
		elseif field == "BreastsDamping"   then grp, prop = "Breasts",  "Damper"
		elseif field == "ButtsStiffness"   then grp, prop = "Buttocks", "Speed"
		elseif field == "ButtsDamping"     then grp, prop = "Buttocks", "Damper"
		elseif field == "CockStiffness"    then grp, prop = "Default",  "Speed"
		elseif field == "CockDamping"      then grp, prop = "Default",  "Damper" end
		if not grp then return System.setPD(field, value) end  -- not a physics field: normal path
		if type(value) ~= "number" or value ~= value then return end  -- guard NaN / non-number
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		if pd then pd[field] = value end
		-- (1) shared SpringConfigs group -> next SpringCreate/rebuild uses the new value (engine V4.3.1 parity)
		local cfg = System.Physics and System.Physics.SpringConfigs and System.Physics.SpringConfigs[grp]
		if cfg then cfg[prop] = value end
		-- (2) push onto the selected player's RUNNING springs so it is live without a rebuild.
		-- Running springs carry no group tag, so route by Part.Name exactly as the engine grouped
		-- them at SpringCreate: breasts = Left/Right Breast + Left/Right Nipple; butts = Left/Right
		-- Butt; everything else with physics (Rod/Cock/Balls/BBC Balls/ballsKnot/HorseRod/...) = cock.
		if pd and pd.CurrentPartList and pd.CurrentPartList.BodyPartPhysics then
			local isSpeed = (prop == "Speed")
			for Part, Property in pairs(pd.CurrentPartList.BodyPartPhysics) do
				if Part and Property and Property.Spring then
					local nm = Part.Name
					local pg
					if nm == "Left Breast" or nm == "Right Breast" or nm == "Left Nipple" or nm == "Right Nipple" then
						pg = "Breasts"
					elseif nm == "Left Butt" or nm == "Right Butt" then
						pg = "Buttocks"
					else
						pg = "Default"
					end
					if pg == grp then
						if isSpeed then
							Property.Spring.Speed = value
							if Property.Spring2 then Property.Spring2.Speed = value * 3.2 end
						else
							Property.Spring.Damper = value
							if Property.Spring2 then Property.Spring2.Damper = math.min(value * 2, 0.95) end
						end
					end
				end
			end
		end
		-- no hotSwap: a rebuild would re-run SpringCreate (which now reads the updated config anyway)
		-- but would also rebuild the whole body -- the live spring writes above already applied it.
	end

	-- NESTED PlayerData setter for sub-tables (e.g. tailSettings.tailPhysicsEnabled,
	-- which the engine toggles at original L27693 -- it is NOT a top-level field).
	System.setPDNested = function(tbl, field, value)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		if pd and type(pd[tbl]) == "table" then pd[tbl][field] = value end
		if System.hotSwap then System.hotSwap() end
	end

	-- V4.4.2 (round 2): LocalTransparency is LOCAL-only -- the render loop applies it ONLY for the local
	-- player and reads it every frame -- so write PlayerData[Player.Name].LocalTransparency with NO hotSwap.
	-- Routing it through setPDNested (SelectPlayer + always-hotSwap) caused a full-body rebuild FLICKER on
	-- every body-map tap AND a silent no-op when a peer was selected.
	System.getLocalTransparency = function()
		local pd = PlayerData[Player.Name]; return (pd and type(pd.LocalTransparency)=="table") and pd.LocalTransparency or nil
	end
	System.setLocalTransparency = function(part, hidden)
		local pd = PlayerData[Player.Name]
		if pd and type(pd.LocalTransparency)=="table" then pd.LocalTransparency[part] = hidden and true or false end
		-- V4.4.2 (round 3): Method 2 (default) applies LocalTransparency LIVE from the render loop, so no
		-- rebuild. But a non-Method-2 build (Method 3) decides visibility at BUILD time (hidden parts are
		-- welded into a separate character) and its per-frame LTM reset is Method-2-only (L~23981), so it
		-- needs a hotSwap to apply the change. Gate on the ACTUAL build method (MethodAtBuild is set once the
		-- character exists) so we don't rebuild on a tap before the first execute.
		if pd and pd.MethodAtBuild and pd.MethodAtBuild ~= 2 and System.hotSwap then System.hotSwap() end
	end
	-- V4.4.2: "Animations" master freeze. This script plays NO Roblox Humanoid animations -- the motion is
	-- PROCEDURAL (jiggle springs, breathing, overtone, tail wag) driven per-frame. A single AnimationsFrozen
	-- flag, checked as an early-out in the two hot loops, kills/resumes ALL of it with NO rebuild (instant,
	-- reversible; resume restores the user's exact settings since no individual flag is touched).
	-- V4.4.2 (round 2): Avatar Sync (BETA) on/off. The whole subsystem (AvatarSyncStart/Stop + the poll/
	-- heartbeat loops gated on AS.enabled) is intact but was DORMANT -- nothing set AS.enabled=true or called
	-- Start after the old avatarSyncButton died in the teardown. enabled MUST be set true BEFORE Start (loops
	-- are `while AS.enabled`); Stop sets enabled=false + tears down synced peers/handles.
	System.getAvatarSync = function() return System.AvatarSync and System.AvatarSync.enabled == true end
	System.setAvatarSync = function(on)
		local AS = System.AvatarSync; if not AS then return end
		on = on and true or false
		if on == (AS.enabled == true) then return end
		if on then
			AS.enabled = true
			if Function.AvatarSyncStart then pcall(Function.AvatarSyncStart) end
			if Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true) end
		else
			if Function.AvatarSyncStop then pcall(Function.AvatarSyncStop) end
		end
	end

	-- V4.4.2: telemetry + diagnostics bridges (the Settings > Diagnostics HUD switch + both buttons were
	-- inert). _telemEnabled is the LOCAL user's own opt-in -- always PlayerData[Player.Name], never the
	-- selected peer (plain setPD would target the wrong PD) -- and the capture gate reads it live. On
	-- opt-OUT, discard the queued events so nothing captured before the user changed their mind uploads later.
	System.getTelemEnabled = function()
		local pd = PlayerData[Player.Name]; return pd and pd._telemEnabled == true
	end
	System.setTelemEnabled = function(v)
		v = v and true or false
		local pd = PlayerData[Player.Name]; if pd then pd._telemEnabled = v end
		if (not v) and Function.diagUploadClear then pcall(Function.diagUploadClear) end
		if System.persistTelem then System.persistTelem() end  -- V4.4.2 (round 2): persist the flag (esp. opt-OUT) so it sticks across executes
	end
	System.diagPendingCount = function()
		if not Function.diagUploadSnapshot then return 0 end
		local ok, snap = pcall(Function.diagUploadSnapshot)
		return (ok and type(snap) == "table") and #snap or 0
	end
	System.diagSendNow = function()
		if not Function.diagUploadNow then return false end
		return select(1, pcall(Function.diagUploadNow))
	end

	-- NAKED MODE: an ACTION pair (strip / restore), NOT a settable field.
	-- Faithful to the surviving keybind handler at L~19680-19694:
	-- ON  -> Function.StripAllClothes(sp) + hotSwap;
	-- OFF -> clear pd._nakedMode + CharacterReset(sp) + hotSwap.
	System.setNaked = function(on)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		if not pd then return end
		if on then
			pcall(Function.StripAllClothes, sp)
		else
			pd._nakedMode = nil
			pcall(Function.CharacterReset, sp)
		end
		if System.hotSwap then pcall(System.hotSwap) end
	end

	-- ============================================================
	-- PHASE 4b: editable INPUT-FIELD setters. Each replicates the exact
	-- validation the ORIGINAL FocusLost/Text-changed handler used (verified
	-- in V4.3.576.0627), then hotSwaps. The new GUI's UI.field/UI.fieldL now
	-- render real TextBoxes whose onCommit(text) calls into these.
	-- ============================================================

	-- TOP-LEVEL numeric-or-blank field: tonumber(text) when valid, else "" (the
	-- original pattern for TopHP/BottomHP/DamageSFX/Volume, V4.3.576 L27475-27539).
	System.setPDNum = function(field, text)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]; if not pd then return end
		pd[field] = tonumber(text) or ""
		if System.hotSwap then System.hotSwap() end
	end

	-- DELAY: tonumber only, NO else-clear (the original DelayTime handler skips the
	-- write entirely on a non-numeric value, V4.3.576 L4184-4191).
	System.setDelay = function(text)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]; if not pd then return end
		if tonumber(text) then pd.DelayTime = tonumber(text) end
		if System.hotSwap then System.hotSwap() end
	end

	-- NESTED catalog clothes: PlayerData[sp].CatalogClothes[key] = tonumber(text) or ""
	-- (original _buildCatalogClothesPanel._bind, V4.3.576 L4499-4517; stored as a NUMBER
	-- when valid because MarketplaceService asset lookups compare with == against ids).
	System.setCatalogClothes = function(key, text)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]; if not pd then return end
		pd.CatalogClothes = pd.CatalogClothes or {}
		pd.CatalogClothes[key] = tonumber(text) or ""
		if System.hotSwap then System.hotSwap() end
	end

	-- NESTED per-cloth HP ids: PlayerData[sp].HPClothes[key] = tonumber(text) or ""
	-- (original TopClothesText/BottomClothesText handlers, V4.3.576 L27497-27517).
	System.setHPClothes = function(key, text)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]; if not pd then return end
		pd.HPClothes = pd.HPClothes or {}
		pd.HPClothes[key] = tonumber(text) or ""
		if System.hotSwap then System.hotSwap() end
	end

	-- STRING catalog field (CatalogOutfitId): direct string assignment (original
	-- OutfitId handler stores the raw text, V4.3.576 L25547+). hotSwap to re-apply.
	System.setCatalogString = function(field, text)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]; if not pd then return end
		pd[field] = text or ""
		if field == "CatalogOutfitId" then pd.CatalogBundleId = "" end
