	-- CATALOG USERNAME: direct string assign, BUT on a non-empty -> empty CLEAR transition
	-- the original (V4.3.576 L23958-23977) bumps LastRequestID, CharacterReset(sp), hotSwap()
	-- so the standard restore path fires (otherwise the bugged catalog skin lingers). Faithful.
	System.setCatalogUsername = function(text)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]; if not pd then return end
		local prev = pd.CatalogUsername
		pd.CatalogUsername = text or ""
		if prev ~= "" and (text or "") == "" then
			pd.LastRequestID = (pd.LastRequestID or 0) + 1
			pcall(Function.CharacterReset, sp)
		end
		if System.hotSwap then System.hotSwap() end
	end

	-- CATALOG ACCESSORY: the original is an ADD-by-id action (FocusLost -> table.insert a
	-- numeric id into PlayerData[sp].CatalogAccessory, dedup via table.find, V4.3.576 L24383-24394).
	-- It is NOT a scalar field; this appends one id per commit (ignores blank / non-numeric / dup).
	System.addCatalogAccessory = function(text)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]; if not pd then return end
		local id = tonumber(text); if not id then return end
		pd.CatalogAccessory = pd.CatalogAccessory or {}
		if not table.find(pd.CatalogAccessory, id) then table.insert(pd.CatalogAccessory, id) end
		if System.hotSwap then System.hotSwap() end
	end

	-- PHYSICS MULTIPLIERS (Settings page sliders). PositionPhysicsMultiply /
	-- RotationPhysicsMultiply are FILE-scope upvalues (declared at L~2205-2206,
	-- before _buildKrulHubGUI) -- reassigning them here updates the SAME variables
	-- the physics tick reads (original setters L~32083/32087: function(v) X = v end;
	-- engine range 0..20). Defined in this block (not at the file-scope declaration)
	-- because `System` does not exist yet at L2205; the captured upvalue is identical.
	System.setPositionPhysicsMultiply = function(v) PositionPhysicsMultiply = tonumber(v) or PositionPhysicsMultiply; if System.hotSwap then System.hotSwap() end end
	System.setRotationPhysicsMultiply = function(v) RotationPhysicsMultiply = tonumber(v) or RotationPhysicsMultiply; if System.hotSwap then System.hotSwap() end end
	System.getPositionPhysicsMultiply = function() return PositionPhysicsMultiply end
	System.getRotationPhysicsMultiply = function() return RotationPhysicsMultiply end

	-- REDOWNLOAD ALL CONTENT (Options "Redownload All Content" button). Re-runs the
	-- asset installer. Core of the original handler (L~29570-29599): reset the installed
	-- flag, bump the install generation guard, then pcall(Function.InstallContentAssets)
	-- (it is async-safe + shows its own overlay). Re-entry guarded so a double-click can't
	-- stack two installers. The button-text choreography is omitted (the new GUI is momentary).
	System.doRedownload = function(onProgress)  -- onProgress(done,total,failed,file,size,stage): "downloading"/"installing" live, then "complete"/"error" once. Passing it routes progress to the caller (the toast) instead of the raw pill.
		if Function._redlInProgress then return end
		Function._redlInProgress = true
		System._contentInstalled = false
		System._installGen = (System._installGen or 0) + 1
		task.spawn(function()
			local ok = pcall(Function.InstallContentAssets, true, onProgress)  -- V4.4.x: force a full re-fetch so the user sees real progress, not an instant no-op
			Function._redlInProgress = false
			if onProgress then pcall(onProgress, nil, nil, nil, nil, nil, ok and "complete" or "error") end  -- final signal so the caller can close out the progress toast
		end)
	end

	-- ============================================================
	-- GIZMO / EDIT-TAB BRIDGE. The Edit tab was 100% demo scaffold after the
	-- GUI merge (mock target list, sliders with no onChange, static Properties).
	-- The continuous gizmo->mesh weld loop SURVIVED the teardown (mesh body
	-- parts L~22849-22859 keyed by Part.Name; accessories L~23075-23135 keyed by
	-- "acc:"..accName) -- it welds C0 = baseC0 * C1Inv * CFrame.new(Pos) * RotCF
	-- * baseC1 from PlayerData[sp].GizmoOffsets[key]. So the GUI only has to WRITE
	-- GizmoOffsets[target] and the loop renders the change live.
	--
	-- These reproduce the ORIGINAL V4.3.576 Edit-tab driving semantics (target
	-- dropdown L25817-25963, MakeGizmoSlider L32123, Clear L26115, Export L26146,
	-- Multi L26186, Copy/Paste-Mirror/Undo L32560-32681, presets L26019/26077).
	-- All public methods are System.* FIELDS = 0 RoClothes registers (PlayerData /
	-- SelectPlayer / GizmoSliderRefreshers / Function / env / hotSwap all in scope
	-- here). The 3 helper locals live inside the `do...end` below so they cost 0
	-- RoClothes registers too (the established "new locals only in do...end" rule,
	-- so this block stays well clear of Luau's 200-local cap). Ranges: Pos -2..2
	-- studs, Rot -180..180 deg (orig L32244-32250). LANDMINE V4.3.135: every write
	-- to a GizmoOffset table is IN-PLACE -- the singular GizmoOffset is a write-
	-- through reference INTO GizmoOffsets[target] and must never be replaced
	-- wholesale, or per-target persistence breaks.
	do
	-- axis ranges + a zero-offset factory shared by the gizmo methods below.
	local _GIZMO_RANGE = { Pos = {-2, 2}, Rot = {-180, 180} }
	local function _gizZero()
		return { PosX=0, PosY=0, PosZ=0, RotX=0, RotY=0, RotZ=0, RotCF=CFrame.new() }
	end
	-- The GUI registers per-slider refreshers here so BOTH the engine's reset
	-- path (System.doReset iterates GizmoSliderRefreshers) AND a gizmo-bridge
	-- mutation can re-sync the sliders + Properties to the live offset in place.
	System.gizmoRegisterRefresher = function(fn)
		if type(fn) == "function" then table.insert(GizmoSliderRefreshers, fn) end
	end
	-- The Edit page is rebuilt on every nav visit (go("edit")), so it deregisters
	-- its prior refresher before registering the fresh one to avoid accumulating
	-- dead closures that point at destroyed sliders.
	System.gizmoUnregisterRefresher = function(fn)
		if type(fn) ~= "function" then return end
		local i = table.find(GizmoSliderRefreshers, fn)
		if i then table.remove(GizmoSliderRefreshers, i) end
	end

	-- Enumerate the REAL selectable targets for the selected player (orig
	-- rebuildGizmoDropdown L25817-25963): body-part mesh names from the live
	-- RealtimeUpdateList.Mesh keys + Roblox accessories (key "acc:"..name).
	-- Returns an ARRAY of {key, label, kind="mesh"|"acc", selected(bool for multi)}.
	System.getGizmoTargets = function()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local out = {}
		local char = (Function.ResolveTargetChar and Function.ResolveTargetChar(sp)) or (Player and Player.Character)
		if not char then return out end
		local cur = (PlayerData[sp] and PlayerData[sp].GizmoTarget) or nil
		-- RIG POSER targets = body parts that own a rig joint (Motor6D.Part1). Editing that joint
		-- moves the part + everything Motor6D-d below it (Torso -> whole body). Body-only: arm/leg/head/torso.
		local names, seen = {}, {}
		for _, m in ipairs(char:GetDescendants()) do
			-- R6 rigs joint via Motor6D (part = Part1); upgraded-R15 rigs joint via AnimationConstraint (part = Attachment1's parent).
			local p = (m:IsA("Motor6D") and m.Part1) or (m:IsA("AnimationConstraint") and m.Attachment1 and m.Attachment1.Parent)
			if p and p:IsA("BasePart") then
				local nm = p.Name
				local _l = nm:lower()
				if not seen[nm] and (_l:find("arm") or _l:find("leg") or _l:find("torso") or _l:find("head") or _l:find("hand") or _l:find("foot")) then
					seen[nm] = true; table.insert(names, nm)
				end
			end
		end
		table.sort(names, function(a, b) return a:lower() < b:lower() end)
		for _, nm in ipairs(names) do
			table.insert(out, { key = nm, label = nm, kind = "joint", selected = (cur == nm) })
		end
		return out
	end

	System.getGizmoTarget = function()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		return pd and pd.GizmoTarget or nil
	end

	-- Select a target. Mirrors the dropdown click
	-- closures (orig L25862-25956): create the per-target offset if absent
	-- (accessories also stash baseC0/baseC1 from the Handle weld), set GizmoTarget,
	-- and LINK the singular GizmoOffset to GizmoOffsets[key] (write-through ref).
	-- Returns true if a single target was selected (caller should reseed sliders),
	-- false for a multi-mode toggle (caller re-renders the dropdown only).
	System.setGizmoTarget = function(key)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		if not pd or type(key) ~= "string" then return false end
		pd.GizmoOffsets = pd.GizmoOffsets or {}
		if not pd.GizmoOffsets[key] then
			if key:sub(1, 4) == "acc:" then
				-- capture the live accessory weld bases so the gizmo math has a stable frame
				local char = Function.ResolveTargetChar(sp)
				local acc = char and char:FindFirstChild(key:sub(5))
				local handle = acc and acc:IsA("Accessory") and acc:FindFirstChild("Handle")
				local weld = handle and handle:FindFirstChildWhichIsA("Weld")
				if not weld then return false end
				local z = _gizZero()
				z.baseC0 = weld.C0
				z.baseC1 = weld.C1
				pd.GizmoOffsets[key] = z
			else
				pd.GizmoOffsets[key] = _gizZero()
			end
		end
		pd.GizmoTarget = key
		pd.GizmoOffset = pd.GizmoOffsets[key]
		return true
	end




	-- Reset a single axis to 0 (orig MakeGizmoSlider R button L32185-32200):
	-- for Rot, un-multiply the RotCF by the inverse of the old rotation.
	-- =====================================================================
	-- SP2: 3D DIRECT-MANIPULATION GIZMO (engine ArcHandles + Handles), modeled on
	-- the Catalog Avatar Creator gizmo. Adorns the engine gizmo to the live target
	-- pipeline (RenderStepped apply) is reused unchanged. Move + Rotate, toggled.
	-- =====================================================================
	System._giz3dMode = System._giz3dMode or "Pos"
	-- =====================================================================
	-- SP2 GIZMO = RIG POSER, ported 1:1 from the Catalog Avatar Creator PoseTool
	-- (decompiled to GAME_POSETOOL_REFERENCE.md). It edits the selected body
	-- part's rig JOINT (Motor6D.C0), NOT any mesh. Because the rig is a Motor6D
	-- hierarchy, editing a joint moves that part + everything Motor6D-d below it,
	-- rigidly: Torso RootJoint moves the WHOLE body; a leaf (arm/leg/head) moves
	-- only itself. Move + Rotate via engine Handles/ArcHandles, snap-step, HRP
	-- anchored during the drag, animations frozen so the pose holds.
	-- =====================================================================
	local function _giz3dChar()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		return (Function.ResolveTargetChar and Function.ResolveTargetChar(sp)) or (Player and Player.Character)
	end
	-- JOINT ADAPTER (rig-agnostic): R6 rigs joint via Motor6D; upgraded-R15 rigs joint via AnimationConstraint.
	-- Mirrors the game's JointAdapter so the poser works on BOTH. Motor6D "C0/C1" = .C0/.C1; AnimationConstraint
	-- "C0/C1" = Attachment0/Attachment1.CFrame. _jKinematic (AnimationConstraint only) lets a C0 edit hold as a pose.
	local function _isPoseJoint(j) return j:IsA("Motor6D") or j:IsA("AnimationConstraint") end
	local function _jPart(j) if j:IsA("Motor6D") then return j.Part1 end local a = j.Attachment1; return a and a.Parent end
	local function _jGetC0(j) if j:IsA("Motor6D") then return j.C0 end local a = j.Attachment0; return (a and a.CFrame) or CFrame.new() end
	local function _jSetC0(j, cf) if j:IsA("Motor6D") then j.C0 = cf return end local a = j.Attachment0; if a then a.CFrame = cf end end
	local function _jGetC1(j) if j:IsA("Motor6D") then return j.C1 end local a = j.Attachment1; return (a and a.CFrame) or CFrame.new() end
	local function _jSetC1(j, cf) if j:IsA("Motor6D") then j.C1 = cf return end local a = j.Attachment1; if a then a.CFrame = cf end end
	local function _jKinematic(j) if j:IsA("AnimationConstraint") then pcall(function() j.IsKinematic = true end) end end
	-- part NAME -> its rig joint (Motor6D with Part1==part, OR the AnimationConstraint that moves the part) + the part.
	local function _giz3dResolveJoint(key)
		if type(key) ~= "string" then return nil, nil end
		local char = _giz3dChar(); if not char then return nil, nil end
		local part = char:FindFirstChild(key)
		if not (part and part:IsA("BasePart")) then
			part = nil
			for _, d in ipairs(char:GetDescendants()) do if d:IsA("BasePart") and d.Name == key then part = d; break end end
		end
		if not part then return nil, nil end
		for _, m in ipairs(char:GetDescendants()) do
			if _isPoseJoint(m) and _jPart(m) == part then return m, part end
		end
		return nil, part
	end
	local function _giz3dContainer()
		return (Player and Player:FindFirstChildOfClass("PlayerGui")) or ((gethui and gethui()) or game:GetService("CoreGui"))
	end
	-- Snap STEP (the game "0.001 studs / 0.001 degrees"): the engine handles track the mouse 1:1;
	-- this only rounds the applied delta (0.001 = smooth, higher = coarser precise steps).
	System._giz3dStep = System._giz3dStep or 0.001
	System.getGizmoStep = function() return System._giz3dStep or 0.001 end
	System.setGizmoStep = function(v) System._giz3dStep = math.clamp(tonumber(v) or 0.001, 0.001, 90); return System._giz3dStep end
	local function _snap(v, step) step = step or 0.001; return math.floor(v / step + 0.5) * step end
	System._giz3dOrig = System._giz3dOrig or {}  -- joint -> {C0,C1} captured before first edit, for reset
	-- Freeze/thaw anims so an edited C0 holds statically (animation writes Motor6D.Transform on top
	-- of C0 each frame otherwise). Mirrors the game ToggleCharacterAnimations.
	local function _giz3dSetAnims(char, on)
		if not char then return end
		local an = char:FindFirstChild("Animate"); if an then pcall(function() an.Enabled = on end) end
		pcall(function() char:SetAttribute("PoseApplied", not on) end)
		if on then return end
		local hum = char:FindFirstChildOfClass("Humanoid")
		local animator = hum and hum:FindFirstChildOfClass("Animator")
		if animator then for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do pcall(function() tr:Stop(0) end) end end
	end
	-- Bake a joint C1 rotation into C0 so the drag axes are clean (game NormalizeMotorC1Orientation).
	local function _giz3dNormalize(joint)
		if not System._giz3dOrig[joint] then System._giz3dOrig[joint] = { C0 = _jGetC0(joint), C1 = _jGetC1(joint) } end
		local c1 = _jGetC1(joint)
		if c1.Rotation == CFrame.new().Rotation then return end
		_jSetC0(joint, _jGetC0(joint) * c1.Rotation:Inverse())
		_jSetC1(joint, c1 * c1.Rotation:Inverse())
	end
	System.hideGizmo3D = function(keepFrozen)  -- keepFrozen: an INTERNAL handle rebuild (show / mode-switch) keeps the pose frozen; a USER close (Hide Gizmo / Reset Pose / leaving Edit) un-freezes.
		if System._giz3dConns then for _, c in ipairs(System._giz3dConns) do pcall(function() c:Disconnect() end) end System._giz3dConns = nil end
		if System._giz3dHandle then pcall(function() System._giz3dHandle:Destroy() end) System._giz3dHandle = nil end
		-- Restore the HRP anchor from IsClone (clone = stays a frozen statue; PLAYER = un-anchors so they can walk). NEVER read
		-- live hrp.Anchored - it LATCHES `true` after a missed Handles MouseButton1Up, which used to freeze players forever.
		local hrp = System._giz3dHrp or (System._giz3dFrozeChar and System._giz3dFrozeChar:FindFirstChild("HumanoidRootPart"))
		if hrp then pcall(function() hrp.Anchored = System._giz3dIsClone and true or false end) end
		System._giz3dHrp = nil
		if not keepFrozen and System._giz3dFrozeChar then  -- user closed the gizmo → re-enable animations on the char we actually froze
			pcall(_giz3dSetAnims, System._giz3dFrozeChar, true); System._giz3dFrozeChar = nil
		end
	end
	System.showGizmo3D = function()
		System.hideGizmo3D(true)  -- rebuilding the handle: keep the current freeze (don't restore anims/anchor)
		local key = System.getGizmoTarget and System.getGizmoTarget()
		if not key then return false end
		local joint, part = _giz3dResolveJoint(key)
		if not (joint and part) then return false end
		local char = part:FindFirstAncestorWhichIsA("Model") or _giz3dChar()
		_giz3dSetAnims(char, false)     -- freeze so the pose holds
		System._giz3dFrozeChar = char   -- remember EXACTLY who we froze so Hide/Reset un-freeze the right character
		System._giz3dIsClone = false    -- clone (frozen statue) vs real player (must walk after)? Decides the anchor-restore value - NOT the latch-prone live hrp.Anchored.
		if System.NPCs then for _, m in pairs(System.NPCs) do if m == char then System._giz3dIsClone = true; break end end end
		_giz3dNormalize(joint)          -- clean axes (+ stores original C0/C1 for reset)
		_jKinematic(joint)              -- R15 AnimationConstraint: make it kinematic so the C0 edit holds
		local col = Color3.fromRGB(13, 105, 172)
		System._giz3dConns = {}
		local function _anchor(on)
			local hrp = char and char:FindFirstChild("HumanoidRootPart")
			if not hrp then return end
			if on then
				System._giz3dHrp = hrp
				pcall(function() hrp.Anchored = true end)
			else  -- restore: clone stays anchored (statue), player un-anchors (walks). From IsClone, never the latch-prone live value.
				pcall(function() hrp.Anchored = System._giz3dIsClone and true or false end)
				System._giz3dHrp = nil
			end
		end
		-- BACKSTOP: Handles/ArcHandles MouseButton1Up is unreliable (frequently missed when the release lands off the
		-- adornment) - that missed Up is what used to leave the player permanently anchored. A global release ends the drag too.
		table.insert(System._giz3dConns, game:GetService("UserInputService").InputEnded:Connect(function(io)
			if (io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch) and System._giz3dHrp then _anchor(false) end
		end))
		if System._giz3dMode == "Rot" then
			local h = Instance.new("ArcHandles")
			h.Axes = Axes.new(Enum.Axis.X, Enum.Axis.Y, Enum.Axis.Z)
			h.Color3 = col; h.Adornee = part; h.Parent = _giz3dContainer()
			local startC0 = _jGetC0(joint)
			table.insert(System._giz3dConns, h.MouseButton1Down:Connect(function() _anchor(true); startC0 = _jGetC0(joint) end))
			table.insert(System._giz3dConns, h.MouseDrag:Connect(function(axis, relAngle)
				pcall(function() _jSetC0(joint, startC0 * CFrame.fromAxisAngle(Vector3.FromAxis(axis), math.rad(_snap(math.deg(relAngle or 0), System._giz3dStep or 0.001)))) end)
			end))
			table.insert(System._giz3dConns, h.MouseButton1Up:Connect(function() _anchor(false) end))
			System._giz3dHandle = h
		else
			local h = Instance.new("Handles")
			h.Style = Enum.HandlesStyle.Movement
			h.Faces = Faces.new(Enum.NormalId.Right, Enum.NormalId.Left, Enum.NormalId.Top, Enum.NormalId.Bottom, Enum.NormalId.Front, Enum.NormalId.Back)
			h.Color3 = col; h.Adornee = part; h.Parent = _giz3dContainer()
			local startC0 = _jGetC0(joint)
			table.insert(System._giz3dConns, h.MouseButton1Down:Connect(function() _anchor(true); startC0 = _jGetC0(joint) end))
			table.insert(System._giz3dConns, h.MouseDrag:Connect(function(face, distance)
				pcall(function() _jSetC0(joint, startC0 * CFrame.new(Vector3.FromNormalId(face) * _snap(distance or 0, System._giz3dStep or 0.001))) end)
			end))
			table.insert(System._giz3dConns, h.MouseButton1Up:Connect(function() _anchor(false) end))
			System._giz3dHandle = h
		end
		-- Re-adorn across character reloads: if the adorned part is destroyed, re-resolve joint + part.
		table.insert(System._giz3dConns, game:GetService("RunService").Heartbeat:Connect(function()
			local h = System._giz3dHandle; if not h then return end
			local ad = h.Adornee
			if (not ad) or (not ad.Parent) then
				local nj, np = _giz3dResolveJoint(key)
				if nj and np then joint = nj; part = np; h.Adornee = np end
			end
		end))
		return true
	end
	System.setGizmoMode3D = function(mode)
		System._giz3dMode = (mode == "Rot") and "Rot" or "Pos"
		System.showGizmo3D()
		return System._giz3dMode
	end
	-- Restore every edited joint to its captured original C0/C1 and re-enable animations.
	System.resetGizmoPose = function()
		for joint, o in pairs(System._giz3dOrig) do
			if typeof(joint) == "Instance" and joint.Parent then pcall(function() _jSetC0(joint, o.C0); _jSetC1(joint, o.C1) end) end
		end
		System._giz3dOrig = {}
		_giz3dSetAnims(System._giz3dFrozeChar or _giz3dChar(), true)  -- re-enable anims on the char we actually froze (not just the currently-selected one)
		local hrp = System._giz3dFrozeChar and System._giz3dFrozeChar:FindFirstChild("HumanoidRootPart")
		if hrp and not System._giz3dIsClone then pcall(function() hrp.Anchored = false end) end  -- the player can walk again
		System._giz3dFrozeChar = nil
	end
	System.getGizmoMode3D = function() return System._giz3dMode or "Pos" end










