	-- V4.3.167 fix: PartListDefault must return a FRESH table per call. (see Changelog for full rationale)
	local function deepCloneData(t)
		if type(t) ~= "table" then return t end
		local out = {}
		for k, v in pairs(t) do out[k] = deepCloneData(v) end
		return out
	end

