	PlayerData = {
		[Player.Name] = Function.PlayerDataDefault()
	}

	-- V4.3.507: wire the file-scope uploader's getters now that PlayerData exists.
	-- The uploader coroutine reads these every cycle to gate uploads on opt-in
	-- and to resolve the install ID lazily (generated + persisted on first opt-in).
	_DIAG_UP_ENABLED_GETTER = function()
		local _pd = PlayerData and PlayerData[Player.Name]
		return _pd and _pd._telemEnabled == true
	end
	_DIAG_UP_INSTALLID_GETTER = function()
		local _pd = PlayerData and PlayerData[Player.Name]
		if not _pd then return nil end
		-- V4.3.511 Fix 5/6/9: shared spawn-persist helper.
		--   - re-fetches live PD (avoid stale upvalue post-catalog-reset)
		--   - re-checks opt-in (user may have toggled OFF mid-yield)
		--   - re-checks install ID match (rapid-toggle generated a NEWER id; don't write the stale one)
		--   - serializes via _withSettingsLock (V4.3.511 Fix 8)
		--   - defers setting _DIAG_INSTALL_ID until disk-write succeeds (V4.3.511 Fix 9)
		local function _spawnPersistInstallId(targetId, mirrorOnSuccess)
			task.spawn(function()
				local _pdLive = PlayerData and PlayerData[Player.Name]
				if not _pdLive then return end
				if not _pdLive._telemEnabled then return end
				if _pdLive._telemInstallId ~= targetId then return end  -- V4.3.511 Fix 5: superseded
				if not (env and env.writefile and env.readfile and env.isfile and env.delfile) then return end
				if type(_atomicWriteJSON) ~= "function" then return end
				_withSettingsLock(function()
					local HSr = game:GetService("HttpService")
					local merged
					if env.isfile("RClothesLerp/Settings.json") then
						local _okR, _raw = pcall(env.readfile, "RClothesLerp/Settings.json")
						if not _okR then return end
						local _okD, _dec = pcall(HSr.JSONDecode, HSr, _raw)
						if not _okD or type(_dec) ~= "table" then return end
						merged = _dec
					else
						merged = {}
					end
					merged.telemEnabled = _pdLive._telemEnabled
					merged.telemInstallId = targetId
					-- V4.3.531 Fix 2: capture `_atomicWriteJSON`'s OWN return, not pcall's ok-bool. The
					-- prior single-binding `local writeOk = pcall(...)` captured pcall's success flag
					-- (true unless _atomicWriteJSON throws - which it never does, it returns false on
					-- write failure). Result: `_DIAG_INSTALL_ID_DISK_VERIFIED = true` was set on EVERY
					-- call even when the canonical write actually failed, permanently sealing the
					-- L7939 heal-once gate. Users hitting transient I/O failures never persisted their
					-- install ID and lost session continuity silently.
					local _pcOk, writeOk = pcall(_atomicWriteJSON, "RClothesLerp/Settings.json", merged)
					if _pcOk and writeOk then
						-- V4.3.513 Fix 10: flag disk-verified so the lazy-getter fast-paths
						-- stop spawning redundant persists on every uploader cycle.
						_DIAG_INSTALL_ID_DISK_VERIFIED = true
						if mirrorOnSuccess then
							_DIAG_INSTALL_ID = targetId  -- V4.3.511 Fix 9: cache mirrors disk only on success
						end
					end
				end)
			end)
		end

		if type(_pd._telemInstallId) == "string" and #_pd._telemInstallId > 0 then
			_DIAG_INSTALL_ID = _pd._telemInstallId  -- mirror to file-scope for Phase 1 disk logs
			-- V4.3.512 Fix 3: heal disk symmetrically with path (b). PD may hold the ID but
			-- disk could be stale (previous session's persist failed). Spawn-persist re-checks
			-- writefile env + opt-in inside the lock, so this is a no-op when unneeded.
			-- V4.3.513 Fix 10: gate on _DIAG_INSTALL_ID_DISK_VERIFIED so the heal fires AT MOST
			-- once per opt-in session instead of every uploader cycle. Successful persist sets
			-- the flag; diagUploadClear (opt-out) clears it so re-opt-in re-verifies.
			if not _DIAG_INSTALL_ID_DISK_VERIFIED then
				_spawnPersistInstallId(_pd._telemInstallId, false)
			end
			return _pd._telemInstallId
		end
		-- Lazy generation: only when needed and only if user is opted in.
		if not _pd._telemEnabled then return nil end
		-- V4.3.508: race protection - if Settings.json restore raced ahead and
		-- populated the file-scope cache before the PD field, adopt it rather than
		-- generating a fresh UUID. New ID per session would break dashboard continuity.
		if type(_DIAG_INSTALL_ID) == "string" and #_DIAG_INSTALL_ID > 0 then
			_pd._telemInstallId = _DIAG_INSTALL_ID
			-- V4.3.511 Fix 6: the toggle handler relies on getInstallId() to spawn-persist
			-- when the user opts in with no PD-side install ID. Pre-fix, this fast-path
			-- returned without spawning - if file-scope cache held an ID (from a prior
			-- Settings.json restore) but disk was missing/stale, the toggle thought persist
			-- happened but it didn't. Schedule a persist so disk matches the cache.
			-- V4.3.513 Fix 10: gated on disk-verified flag - heal once, not every cycle.
			if not _DIAG_INSTALL_ID_DISK_VERIFIED then
				_spawnPersistInstallId(_DIAG_INSTALL_ID, false)
			end
			return _DIAG_INSTALL_ID
		end
		local newId = _diagGenUUIDv4()
		_pd._telemInstallId = newId
		-- V4.3.511 Fix 9: do NOT mirror to _DIAG_INSTALL_ID synchronously. Defer to
		-- the spawn so cache and disk stay consistent. Until the spawn lands,
		-- _diagSerializeRing uses empty iid (correct fallback per V4.3.509 Fix 3).
		_spawnPersistInstallId(newId, true)
		return newId
	end

	-- V4.3.514: V4.3.513's gate moved to immediately-after-bootstrap-do-block at ~L6977
	-- (above local Mouse). Reason: PartListDefault deref at L7244 (via PlayerDataDefault)
	-- runs BEFORE this line, so a nil _RoClothesData crashed there before reaching here.
	--[[ROCLOTHES_DATA_START:DummyMesh]]
	local DummyMesh = _RoClothesData.DummyMesh
