	--[[ROCLOTHES_DATA_START:Bundle]]
	local Bundle
	do
		Bundle = _RoClothesData.Bundle
		-- V4.3.369: defensive auto-wrap for flattened Save Outfit bundles. The
		-- krulhub.dev community-bundle serve path serializes published outfits
		-- with the Preset fields at the TOP LEVEL of the bundle object instead
		-- of nested under `Preset = {...}`. `checkBundle` only processes data
		-- inside `v.Preset` - flat bundles therefore silently no-op on click
		-- (clicking does nothing, no error, no rebuild). User report: 3
		-- community-published bundles "Black Moth ()" / "BLACK MOTH () SSS" /
		-- "Black Shark Bikini ()" all flat. Detect via presence of CatalogClothes
		-- or CatalogAccessory at top level + absence of Preset / ClothingBundle /
		-- IsPreset / Clothing markers (so we don't false-positive on legacy
		-- bundle shapes). When detected, move the canonical Save Outfit preset
		-- fields into a `Preset = {...}` sub-table in place. Server-side fix
		-- forwarded to the website session; this client-side migration handles
		-- bundles already in the wild + provides a permanent safety net.
		if type(Bundle) == "table" then
			local _presetKeys = {
				CatalogClothes=true, CatalogAccessory=true, CatalogTail=true,
				CatalogOutfitId=true, CatalogAssetTypes=true,
				BodyPartPhysics=true,
				BreastsType=true, TorsoType=true, ArmType=true, LegsType=true, ButtType=true,
				BreastsScale=true, ButtsScale=true, LegsScale=true, TorsoScale=true, LeftArmScale=true, RightArmScale=true, CockScale=true,
				Tone=true, HardcoreHP=true, TopHP=true, BottomHP=true,
				DamageSFX=true, Volume=true,
				TearParticles=true, HealParticles=true,
				RealtimeBodyTransparency=true, Face=true, PhysicsObeyGravity=true,
				AccessorySizeLock=true, MeshSizeLock=true, MeshBasePartInvisible=true,
				BreastsStiffness=true, BreastsDamping=true,
				ButtsStiffness=true, ButtsDamping=true,
				CockStiffness=true, CockDamping=true,
				SmartBoneEnabled=true, StripCategories=true,
				NippleColor=true, SkinTone=true,
				AutoStripOnRip=true, StripOnRipMap=true,  -- V4.3.370
			}
			for _bName, _b in pairs(Bundle) do
				if type(_b) == "table"
					and _b.Preset == nil
					and _b.ClothingBundle ~= true
					and _b.IsPreset ~= true
					and _b.Clothing == nil
					and (_b.CatalogClothes ~= nil or _b.CatalogAccessory ~= nil)
				then
					local _wrapped = {}
					for _k in pairs(_presetKeys) do
						if _b[_k] ~= nil then
							_wrapped[_k] = _b[_k]
							_b[_k] = nil
						end
					end
					_b.Preset = _wrapped
				end
			end
		end
		-- V4.3.541 Fix 1A: per-user identity routing for community bundles.
		-- The krulhub.dev manifest serves bundles with whatever Personal flag was
		-- on the SUBMITTER's machine at upload time - a pre-V4.3.474 bug (the
		-- Submit-Community local-copy retention path at L26755-L26766 calls
		-- _writeImportedBundleToDisk BEFORE the strip-to-false on _submit) lets
		-- Personal=true leak through, contaminating community-published bundles
		-- for ALL viewers. Empirical scan 2026-06-07: of 102 manifest bundles,
		-- 23 carry Personal=true on the server (Sylvie, Rosalina, Astri, Makima,
		-- Gardevoir Shiny, Trans Girl, Bunny Noob, etc.) - those route to the
		-- Mine tab on every viewer's machine via getBundleTab L7864, regardless
		-- of whether that viewer actually submitted them. User report 2026-06-07
		-- "some community bundle still show up in personal private bundle tab"
		-- + "a lot of community bundle missing" (the same 23 missing from
		-- Community because they're in Mine). Fix is fully client-side, no
		-- server changes needed: maintain a LOCAL list of bundle names this
		-- user has submitted in RClothesLerp/MySubmissions.json. Personal=true
		-- ONLY for entries in that list; all other manifest entries forced
		-- Personal=false. New executor install = empty MySubmissions.json =
		-- everything in Community correctly; user marks any past-submitted
		-- bundles via the Mark-as-Mine UI (right-click / long-press on bundle
		-- button, Fix 2 below) to restore Mine routing. IsPreset and
		-- ClothingBundle entries skipped - they use their own routing via
		-- L7862-L7863. Per-file disk walk at L19280 still wins for actual
		-- on-disk personal bundles (like the user's own "Krul Tepes" save),
		-- so the Mine tab still surfaces those correctly.
		if type(Bundle) == "table" then
			local _mySubsSet = {}
			if env and env.isfile and env.readfile
				and env.isfile("RClothesLerp/MySubmissions.json")
			then
				local _okR, _raw = pcall(env.readfile, "RClothesLerp/MySubmissions.json")
				if _okR and type(_raw) == "string" and #_raw > 0 then
					local _okD, _list = pcall(HS.JSONDecode, HS, _raw)
					if _okD and type(_list) == "table" then
						for _, _n in ipairs(_list) do
							if type(_n) == "string" then _mySubsSet[_n] = true end
						end
					end
				end
			end
			local _mineCount, _commCount = 0, 0
			for _bName, _b in pairs(Bundle) do
				if type(_b) == "table"
					and _b.IsPreset ~= true
					and _b.ClothingBundle ~= true
				then
					if _mySubsSet[_bName] then
						_b.Personal = true
						_mineCount = _mineCount + 1
					else
						_b.Personal = false
						_commCount = _commCount + 1
					end
				end
			end
			local _mySubsCount = 0
			for _ in pairs(_mySubsSet) do _mySubsCount = _mySubsCount + 1 end
			_diagPublicCall("bundle.personal_routing", {
				mine = _mineCount, community = _commCount,
				my_subs_total = _mySubsCount,
			})
		end

		-- V4.3.532 Fix 1: deleted-bundles blocklist. Community/builtin bundles come from
		-- _RoClothesData.Bundle (krulhub.dev manifest) and re-load on every execute. The
		-- L25257 delete-handler only delfile()'s `RClothesLerp/Bundles/<name>.json` and
		-- nils the in-memory entry - for community bundles there's no such file, so the
		-- delete is in-memory-only and the bundle re-appears on next execute. Fix: persist
		-- a list of user-deleted bundle names in RClothesLerp/DeletedBundles.json. On load,
		-- iterate and remove from the freshly-loaded Bundle table BEFORE the user sees it.
		-- The delete-handler is updated below (L25257 region) to append to this list.
		if type(Bundle) == "table" and env and env.isfile and env.readfile
				and env.isfile("RClothesLerp/DeletedBundles.json") then
			local _okR, _raw = pcall(env.readfile, "RClothesLerp/DeletedBundles.json")
			if _okR and type(_raw) == "string" and #_raw > 0 then
				local _okD, _list = pcall(HS.JSONDecode, HS, _raw)
				if _okD and type(_list) == "table" then
					local _suppressed = 0
					for _, _name in ipairs(_list) do
						if type(_name) == "string" and Bundle[_name] ~= nil then
							Bundle[_name] = nil
							_suppressed = _suppressed + 1
						end
					end
					if _suppressed > 0 then
						_diagPublicCall("bundle.deleted_suppressed", { count = _suppressed })
						-- V4.3.541 Fix 4: surface the silent suppression count to
						-- the user via a deferred boot toast (waits for MainFrame
						-- to exist, then shows a clickable status message that
						-- routes to the V4.3.541 Fix 3 Manage Deleted modal).
						-- Pre-V4.3.541 the count was console-diag-only - a user
						-- who deleted community bundles by mistake had no UI
						-- signal that anything was hidden. Defers via task.spawn
						-- because GUIObject.MainFrame isn't built yet at this
						-- bootstrap site (it's created downstream during the
						-- giant GUI build at L26500+).
						System._pendingDeletedBundlesToast = _suppressed
					end
				end
			end
		end
	end
	--[[ROCLOTHES_DATA_END:Bundle]]

