	function Function.CumDripDisplay(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local attach = Instance.new("Attachment",ObjectInstance)
		attach.Name = "cTrail"
		-- V4.3.441: key by the Attachment instance itself, not the literal string
		-- "Attachment". Pre-fix every new equip of a CumDripDisplay-producing item
		-- overwrote the single Special["Attachment"] slot - prior cTrail Attachments
		-- + ParticleEmitters became orphans (not iterated by the per-frame loop,
		-- not :Destroy()'d), and two simultaneous CumDrip items only had the second
		-- updating. The iteration at L15901 only uses the value, not the key.
		DataDetail.CurrentPartList.RealtimeUpdateList.Special[attach] = attach

		local particle = Instance.new("ParticleEmitter",attach)
		particle.Orientation = Enum.ParticleOrientation.VelocityPerpendicular
		particle.Size = NumberSequence.new(
			{NumberSequenceKeypoint.new(0,1.5,1),
				NumberSequenceKeypoint.new(1,1.5,1)}
		)
		particle.Texture = Function.GetAsset("rbxasset://RClothesContent/16235774309.png")
		particle.Transparency = NumberSequence.new(
			{NumberSequenceKeypoint.new(0,1),
				NumberSequenceKeypoint.new(.2,.5),
				NumberSequenceKeypoint.new(1,1)}
		)
		particle.ZOffset = .1
