		particle.Squash = NumberSequence.new(
			{NumberSequenceKeypoint.new(0,.7),
				NumberSequenceKeypoint.new(.752,.95),
				NumberSequenceKeypoint.new(1,.45)}
		)
		particle.Transparency = NumberSequence.new(
			{NumberSequenceKeypoint.new(0,.169),
				NumberSequenceKeypoint.new(.251,.557),
				NumberSequenceKeypoint.new(.519,.814),
				NumberSequenceKeypoint.new(.772,.918),
				NumberSequenceKeypoint.new(1,1)}
		)
		particle.Lifetime = NumberRange.new(.8)
		particle.Rate = 50
		particle.Rotation = NumberRange.new(90)
		particle.Speed = NumberRange.new(1,5)
		particle.SpreadAngle = Vector2.new(-30,30)
		particle.Acceleration = Vector3.new(0,-25,0)
		particle.Drag = 2
		particle.VelocityInheritance = .3
		task.delay(0,function()
			local DataDetail = PlayerData[Data]
			if not DataDetail then return end
			-- V4.5.24 (r2) Fix: harden the WHOLE 1-frame race, not just one deref - ObjectInstance/
			-- particle can die in the delay window and Mesh[ObjectInstance] may be nil (part
			-- destroyed/re-registered). Pre-fix a throw here killed the callback before the C0 bake.
			if not (ObjectInstance and ObjectInstance.Parent) then return end
			if not particle.Parent then return end
			pcall(function() particle.Color = ColorSequence.new(ObjectInstance.Color) end)
			if DataDetail.BreastsType == 5 then
				particle.Size = NumberSequence.new(.1)
				particle.EmissionDirection = Enum.NormalId.Top
				local _mesh = DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[ObjectInstance]
				local _pp = ObjectInstance.Parent and ObjectInstance.Parent.Parent
				if _mesh and _mesh.Weld then
					if _pp and _pp.Name == "Left Breast" then
						_mesh.Weld.C0 = CFrame.new(0.123999998, 0.244960785, -0.0383028984, 0.866025388, 0.5, -0, -0.5, 0.866025388, -0, 0, 0, 1)
						_mesh.CFrame = CFrame.new(0.123999998, 0.244960785, -0.0383028984, 0.866025388, 0.5, -0, -0.5, 0.866025388, -0, 0, 0, 1)
					else
						_mesh.Weld.C0 = CFrame.new(-0.124103546, 0.244960785, -0.0383028984, 0.866027117, -0.499990761, -1.61431331e-06, 0.499992698, 0.866029799, -3.49144102e-06, 2.21932714e-06, 2.92656478e-06, 0.99999994)
						_mesh.CFrame = CFrame.new(-0.124103546, 0.244960785, -0.0383028984, 0.866027117, -0.499990761, -1.61431331e-06, 0.499992698, 0.866029799, -3.49144102e-06, 2.21932714e-06, 2.92656478e-06, 0.99999994)
					end
				end
			end
		end)
	end

	function Function.OilUp(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local function oil(v)
			if RS:IsStudio() then
				local mat
				-- V4.5.24 Fix: MS (MaterialService) is pcall-guarded at file scope (L78) and can be
				-- nil on executors that block it. Guard every deref so the oil pass degrades instead
				-- of throwing on the first part.
				if MS and MS:FindFirstChild("wetSmoothROCLOTHES") then
					mat = MS["wetSmoothROCLOTHES"]
				elseif MS then
					mat = Instance.new("MaterialVariant", MS)
					mat.Name="wetSmoothROCLOTHES"
					mat.BaseMaterial = Enum.Material.SmoothPlastic
					mat.MaterialPattern = Enum.MaterialPattern.Organic
					mat.RoughnessMap = "rbxassetid://14142895952"
					mat:AddTag(System.RCTag)
				end

				v.Material = Enum.Material.SmoothPlastic
				v.MaterialVariant = "wetSmoothROCLOTHES"
				local sa = v:FindFirstChildOfClass("SurfaceAppearance")
				if sa and not v:HasTag("ImportantSurfaceAppearance") then
					if sa.AlphaMode == Enum.AlphaMode.Transparency then
						v.TextureID = sa.ColorMap
						v.Transparency = 0.011
						v:SetAttribute("Alpha",0.011)
					elseif sa.AlphaMode == Enum.AlphaMode.Overlay then
						local overlay = v:Clone()
						overlay.Name = v.Name.."OILOVERLAY"
						overlay:ClearAllChildren()
						overlay.Parent = v
						local overlayWeld = Instance.new("Weld",overlay)
						overlayWeld.Part0 = overlay
						overlayWeld.Part1 = v
						overlay.Size = v.Size + Vector3.new(.001,.001,.001)
						overlay.Transparency = 0.01
						DataDetail.CurrentPartList.Link[overlay] = {T=v,Define=.01}
						DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[overlay] = {Base=v.Parent,Size=overlay.Size,CFrame=CFrame.new(0,0,0),CFrame1=CFrame.new(0,0,0),Weld=overlayWeld}
						overlay.TextureID = sa.ColorMap
					end
					sa:Destroy()
				end
			else
				v.Material = Enum.Material.Glass
				if v.Transparency >= 1 then
					v:AddTag("RCGlassMat")
					v.Material = Enum.Material.Neon
				end
				local sa = v:FindFirstChildOfClass("SurfaceAppearance")
				if sa and not v:HasTag("ImportantSurfaceAppearance") then
					if sa.AlphaMode == Enum.AlphaMode.Transparency then
						v.TextureID = sa.ColorMap
						v.Transparency = 0.011
						v:SetAttribute("Alpha",0.011)
					elseif sa.AlphaMode == Enum.AlphaMode.Overlay then
						local overlay = v:Clone()
						overlay.Name = v.Name.."OILOVERLAY"
						overlay:ClearAllChildren()
						overlay.Parent = v
						local overlayWeld = Instance.new("Weld",overlay)
						overlayWeld.Part0 = overlay
						overlayWeld.Part1 = v
						overlay.Size = v.Size + Vector3.new(.001,.001,.001)
						overlay.Transparency = 0.01
						DataDetail.CurrentPartList.Link[overlay] = {T=v,Define=.01}
						DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[overlay] = {Base=v.Parent,Size=overlay.Size,CFrame=CFrame.new(0,0,0),CFrame1=CFrame.new(0,0,0),Weld=overlayWeld}
						overlay.TextureID = sa.ColorMap
					end
					sa:Destroy()
				end
			end
		end
		task.delay(0,function()
			for i, v in pairs(DataDetail.CurrentPartList.Organ) do
				oil(v)
			end
		end)
	end
