				-- block MaterialService child creation. Fall back to Glass-only if blocked -
				-- Glass at least gives a visible shiny/oily appearance even without the texture.
				local matOk = MS ~= nil and MS:FindFirstChild("wetSmoothROCLOTHES") ~= nil
				if not matOk then
					matOk = pcall(function()
						local mat = Instance.new("MaterialVariant", MS)
						mat.Name="wetSmoothROCLOTHES"
						mat.BaseMaterial = Enum.Material.SmoothPlastic
						mat.MaterialPattern = Enum.MaterialPattern.Organic
						mat.RoughnessMap = "rbxassetid://14142895952"
						mat:AddTag(System.RCTag)
					end)
				end

				local sa = v:FindFirstChildOfClass("SurfaceAppearance")
				if matOk then
					v.Material = Enum.Material.SmoothPlastic
					v.MaterialVariant = "wetSmoothROCLOTHES"
					if sa and not v:HasTag("ImportantSurfaceAppearance") then
						v.TextureID = sa.ColorMap
						if sa.AlphaMode == Enum.AlphaMode.Transparency then
							v.Transparency = 0.011
							v:SetAttribute("Alpha",0.011)
						end
						sa:Destroy()
					end
				else
					v.Material = Enum.Material.Glass
					if v.Transparency >= 1 then
						v:AddTag("RCGlassMat")
						v.Material = Enum.Material.Neon
					end
					if sa and not v:HasTag("ImportantSurfaceAppearance") then
						sa:Destroy()
					end
				end
			end
		end
		task.delay(0,function()
			local DataDetail = PlayerData[Data]
			if not DataDetail then return end
			for i, v in pairs(DataDetail.CurrentPartList.Organ) do
				oil(v)
			end
			for i, v in pairs(DataDetail.CurrentPartList.Clothes) do
				if string.find(string.lower(v.Name),"shirt") then
					oil(v)
					v.Transparency = 0.011
				end
			end
		end)
	end

	function Function.HideBreastPants(ObjectInstance, Character, Extra, Data)
		task.delay(0,function()
			local DataDetail = PlayerData[Data]
			if not DataDetail then return end
			if not DataDetail.CurrentPartList.Clothes["Breasts Pants"] 
				and not DataDetail.CurrentPartList.Clothes["Breasts Pants 2"]
				and not DataDetail.CurrentPartList.Clothes["Breasts Pants 3"] then
				local void = 100
				repeat
					task.wait()
					void -= 1
				until void <= 0
					or DataDetail.CurrentPartList.Clothes["Breasts Pants"]
					or DataDetail.CurrentPartList.Clothes["Breasts Pants 2"]
					or DataDetail.CurrentPartList.Clothes["Breasts Pants 3"]
			end

			local organ
			local function getOrgan()
				if DataDetail.CurrentPartList.Clothes["Breasts Pants"] then
					organ = DataDetail.CurrentPartList.Clothes["Breasts Pants"]
				elseif DataDetail.CurrentPartList.Clothes["Breasts Pants 2"] then
					organ = DataDetail.CurrentPartList.Clothes["Breasts Pants 2"]
				elseif DataDetail.CurrentPartList.Clothes["Breasts Pants 3"] then
					organ = DataDetail.CurrentPartList.Clothes["Breasts Pants 3"]
				end
			end
			getOrgan()

			if organ then
				local void = 100
				repeat
					task.wait()
					void -= 1
					getOrgan()
				until void <= 0 or DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[organ]
				local _mesh = DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[organ]
				if _mesh then
					_mesh.Size = Vector3.new(0,0,0)
					organ.Size = Vector3.new(0,0,0)
				end
				-- V4.3.539 Fix 3: harden HideBreast against KrulHosted 2D-tab race.
				-- Pre-fix the 2D-tab KrulHosted texture pipeline at L16912-16986 paints
				-- a SurfaceAppearance with a 2D PNG synchronously inside CharacterExecute
				-- onto "Breasts Pants[ 2 3]" parts. HideBreast* runs deferred via
				-- task.delay(0) and zeros _mesh.Size + organ.Size. In the SUCCESS path
				-- the part is Size=0 so the SA is invisible - but in the TIMEOUT
				-- WINDOW above (`void <= 0` exit with no Mesh-table entry) the Size=0
				-- writes are SKIPPED by the `if _mesh then` guard, leaving the SA
				-- visible at full size = the community-reported "broken breast map".
				-- Fix: unconditionally scrub any KrulHosted-tagged SA on the organ
				-- AFTER the size-zero attempt, AND wipe organ from CurrentPartList.Clothes
				-- so the second-pass retry at L16998+ can't re-paint. Community report
				-- Victoria 2026-06-06: "Hide breast shirt/pants + clothing from 2D tab
				-- causes broken breast map."
				for _, child in ipairs(organ:GetChildren()) do
					if child:IsA("SurfaceAppearance") and child:GetAttribute("KrulHosted") then
						pcall(function() child:Destroy() end)
					end
				end
				if DataDetail.CurrentPartList and DataDetail.CurrentPartList.Clothes then
					for k, v in pairs(DataDetail.CurrentPartList.Clothes) do
						if v == organ then DataDetail.CurrentPartList.Clothes[k] = nil end
					end
				end
			else
				-- V4.3.540 Fix 4: organ-nil fallback. The V4.3.539 Fix 3 KrulHosted
				-- SA scrub is gated by `if organ then` - meaning when organ never
				-- gets registered in DataDetail.CurrentPartList.Clothes (the 100-
				-- tick wait above expires without resolution), the scrub never
				-- fires. But the KrulHosted by-name paint at L16912-area writes
				-- the SA onto whatever Character-rooted MeshPart matches "Breasts
				-- Pants[ 2 3]" by Name, regardless of CurrentPartList registration.
				-- Result: the original community-report scenario the V4.3.539 fix
				-- targeted is still NOT covered when organ resolution times out.
				-- Walk the Character directly by part-name pattern as a fallback,
				-- scoped to Character only (not workspace) to avoid scrubbing
				-- unrelated parts elsewhere in the game.
				if Character then
					local _hits = 0
					for _, p in ipairs(Character:GetDescendants()) do
						if p:IsA("BasePart") and (
							p.Name == "Breasts Pants" or p.Name == "Breasts Pants 2" or p.Name == "Breasts Pants 3"
						) then
							for _, child in ipairs(p:GetChildren()) do
								if child:IsA("SurfaceAppearance") and child:GetAttribute("KrulHosted") then
									pcall(function() child:Destroy() end)
									_hits += 1
								end
							end
						end
					end
					if _hits > 0 then
						pcall(Function.diag, "hd.sa_scrub_no_organ", { count = _hits, region = "pants" })
					end
				end
			end
		end)
	end

