	function Function.addFrecklesC(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local oldObjectInstance
		if ObjectInstance.Name == "UnnecessaryPart" then
			oldObjectInstance = ObjectInstance
			ObjectInstance = ObjectInstance.Parent
		end
		local transparency = .55
		if oldObjectInstance then
			transparency = oldObjectInstance.Transparency
			oldObjectInstance.Transparency = 1
		end
		for i = 1, 6 do
			local Texture = Instance.new("Decal", ObjectInstance)
			Texture.Texture = Function.GetAsset("rbxasset://RClothesContent/colorableFreckles.png")
			-- V4.3.511 Fix 10: Parent + pcall guard. The Texture/oldObjectInstance
			-- can be reparented or destroyed in the 1-frame deferred window
			-- (Drip/StripCategories sweep, character respawn); writing Color3 on
			-- a destroyed Instance throws.
			task.delay(0,function()
				if Texture and Texture.Parent and oldObjectInstance and oldObjectInstance.Parent then
					pcall(function() Texture.Color3 = oldObjectInstance.Color end)
				end
			end)
			Texture.Transparency = transparency
			DataDetail.CurrentPartList.Link[Texture] = {T=ObjectInstance,Define=transparency}

			if i == 1 then
				Texture.Face = "Left"
			elseif i == 2 then
				Texture.Face = "Right"
			elseif i == 3 then
				Texture.Face = "Back"
			elseif i == 4 then
				Texture.Face = "Front"
			elseif i == 5 then
				Texture.Face = "Bottom"
			elseif i == 6 then
				Texture.Face = "Top"
			end
		end
	end

	function Function.nippleCensor(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local Ui = Instance.new("ScreenGui",GUIObject.Screen)
		Ui.Name = "nCensor"
		Ui.DisplayOrder = -9999
		local objctValue = Instance.new("ObjectValue",Ui)
		objctValue.Value = ObjectInstance
		DataDetail.CurrentPartList.RealtimeUpdateList.Special[Ui] = Ui  -- V4.3.567 H-11: key by instance, not "nippleCensor" string (2nd nipple overwrote the 1st slot -> first ScreenGui leaked). Cleanup loops iterate by value (L16521/L22581). Mirrors L8971.

		local frame = Instance.new("Frame",Ui)
		frame.Size = UDim2.fromScale(0,0)
		frame.BackgroundColor3 = Color3.fromRGB(0,0,0)
		frame.BorderSizePixel = 0
	end

	function Function.twitchEffect(ObjectInstance, Character, Extra, Data)
		task.spawn(function()
			local DataDetail = PlayerData[Data]
			if not DataDetail then return end
			repeat
				task.wait(math.random(5,40)*0.1)
				for Part, Property in pairs(DataDetail.CurrentPartList.BodyPartPhysics) do
					-- Rod Physics Guard: Ensure part still exists before accessing properties like Name
					if Part and Part.Parent and (Part.Name == "Rod" or Part.Name == "HorseRod" or Part.Name == "Main" or Part.Name == "BBC Rod") then
						local Spring = Property.Spring
						if Spring then
							for i=1, math.random(2,10) do
								Spring:Impulse(Vector3.new(0,0.05,0))
								task.wait()
							end
						end
					end
				end
			until ObjectInstance == nil or Function.IsParentNil(ObjectInstance) or Function.FallenPartCheck(ObjectInstance)
		end)
	end

