	function Function.AreolaDecalCreate(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if (not table.find(DataDetail.CurrentClothes, "Roblox Breasts Clothing") and ObjectInstance.Transparency ~= 1) or (table.find(DataDetail.CurrentClothes, "Roblox Breasts Clothing") and (ObjectInstance.Name ~= "Left Breast" and ObjectInstance.Name ~= "Right Breast") and ObjectInstance.Transparency ~= 1) then
			for i = 1, 2 do
				local Decal = Instance.new("Decal", ObjectInstance)
				Decal.Color3 = Color3.fromRGB(255, 167, 169)
				Decal.Texture = Function.GetAsset("rbxasset://RClothesContent/6667257628.png")
				Decal.Face = "Left"
				Decal.Name = "Areola Decal".." "..tostring(i)
				DataDetail.CurrentPartList.AreolaDecal[Decal] = ObjectInstance

				if Extra.Tone == "Dark" then
					local H,S,V = ObjectInstance.Color:ToHSV()
					local DarkerColorCode = Color3.fromHSV(H,S,V+(-DarkerColorPercentage * V/100))

					Decal.Color3 = DarkerColorCode
				elseif Extra.Tone == "Use NippleColor" then
					if Extra.NippleColor ~= nil then
						Decal.Color3 = Extra.NippleColor
					end
				end
			end
		else
			for i = 1, 2 do
				local Decal = Instance.new("Decal", ObjectInstance)
				Decal.Transparency = 1
				Decal.Color3 = Color3.fromRGB(255, 167, 169)
				Decal.Texture = Function.GetAsset("rbxasset://RClothesContent/6667257628.png")
				Decal.Face = "Left"
				Decal.Name = "Areola Decal".." "..tostring(i)
				DataDetail.CurrentPartList.AreolaDecal[Decal] = ObjectInstance

				if Extra.Tone == "Dark" then
					local H,S,V = ObjectInstance.Color:ToHSV()
					local DarkerColorCode = Color3.fromHSV(H,S,V+(-DarkerColorPercentage * V/100))

					Decal.Color3 = DarkerColorCode
				elseif Extra.Tone == "Use NippleColor" then
					if Extra.NippleColor ~= nil then
						Decal.Color3 = Extra.NippleColor
					end
				end
			end
		end
	end

	-- VNS breast type 6 - uses its own areola PNG from _vns/model/breast/1/areola.png
	function Function.AreolaDecalCreateVNS(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		local _ok, texture = pcall(System.getcustomasset, "RClothesContent/_vns/model/breast/1/areola.png")
		if not _ok then texture = Function.GetAsset("rbxasset://RClothesContent/6667257628.png") end
		if ObjectInstance.Transparency ~= 1 then
			-- V4.3.225: Decal.Face = Back. The rbxm's breast MeshPart has a 180° Y
			-- rotation in its CFrame, which flips local -Z (NormalId.Front) to point
			-- world +Z (BEHIND the character). What renders on the FRONT of the body
			-- is the local +Z face = NormalId.Back. V4.3.224's "Front" placed the
			-- decal on the back of the body - invisible from camera.
			local Decal = Instance.new("Decal", ObjectInstance)
			Decal.Texture = texture
			Decal.Face = Enum.NormalId.Back
			Decal.Name = "Areola Decal"
			-- V4.3.337: Tone-aware coloring (parity with AreolaDecalCreate / Type3Create).
			-- Default pink → Tone "Dark" darkens via HSV → Tone "Use NippleColor" uses
			-- the user's picked NippleColor.
			Decal.Color3 = Color3.fromRGB(255, 167, 169)
			if Extra and Extra.Tone == "Dark" then
				local H, S, V = ObjectInstance.Color:ToHSV()
				Decal.Color3 = Color3.fromHSV(H, S, V + (-DarkerColorPercentage * V / 100))
			elseif Extra and Extra.Tone == "Use NippleColor" and Extra.NippleColor ~= nil then
				Decal.Color3 = Extra.NippleColor
			end
			DataDetail.CurrentPartList.AreolaDecal[Decal] = ObjectInstance
		end
	end

