	function Function.NippleType5Mesh(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local SpecialMesh = Instance.new("SpecialMesh")
		local Scale = DataDetail["BreastsScale"]
		local type5Scale = System.Transformation.MeshScale.Breasts.Type5

		SpecialMesh.MeshType = Enum.MeshType.FileMesh

		if ObjectInstance.Parent.Name == "Left Breast" then
			SpecialMesh.MeshId = Function.GetAsset("rbxasset://RClothesContent/13779756984.mesh")
		else
			SpecialMesh.MeshId = Function.GetAsset("rbxasset://RClothesContent/13779756939.mesh")
		end

		if Scale ~= nil then
			SpecialMesh.Scale = Function.Vector3Multiply(type5Scale, {X = Scale, Y = Scale, Z = Scale})
		else
			SpecialMesh.Scale = type5Scale
		end

		SpecialMesh.Parent = ObjectInstance
		DataDetail.CurrentPartList.RealtimeUpdateList.SpecialMesh[SpecialMesh] = {
			Base=Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso"),
			Size=SpecialMesh.Scale,
		}
		-- V4.3.214: also apply Tone-based coloring to the nipple mesh itself.
		-- Without this, the nipple Part stays skin-colored (inherits "Parent")
		-- and only the areola decal responds to Tone/NippleColor - which made the
		-- nipple look half-recolored. Mirrors Function.DarkPart's behavior used by
		-- Types 1/3/4 nipples (which get DarkPart in their PartListDefault Function chain).
		if Extra.Tone == "Dark" then
			local H, S, V = ObjectInstance.Parent.Color:ToHSV()
			ObjectInstance.Color = Color3.fromHSV(H, S, V + (-DarkerColorPercentage * V / 100))
		elseif Extra.Tone == "Use NippleColor" and Extra.NippleColor ~= nil then
			ObjectInstance.Color = Extra.NippleColor
		end
	end

