	function Function.AreolaDecalUVCreate(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if ObjectInstance:FindFirstChildOfClass("SurfaceAppearance") then return end
		local Decal = Instance.new("SurfaceAppearance", ObjectInstance)
		Decal.Color = Color3.fromRGB(255, 167, 169)
		Decal.ColorMap = "rbxassetid://9065282081"
		Decal.Name = "Areola Decal"
		Decal:AddTag("ImportantSurfaceAppearance")
		-- V4.3.348: register into CurrentPartList.AreolaDecal so the realtime visibility-sync
		-- loop, NewWomanBreast* hide-loop, and the L11764 "areola" Unvisible hide-path can find
		-- it. Pre-fix UV-mapped breasts visually decoupled from clothing/transparency state
		-- because every other AreolaDecal* variant registered but this one didn't.
		if DataDetail and DataDetail.CurrentPartList and DataDetail.CurrentPartList.AreolaDecal then
			DataDetail.CurrentPartList.AreolaDecal[Decal] = ObjectInstance
		end

		if Extra.Tone == "Dark" then
			local H,S,V = ObjectInstance.Color:ToHSV()
			local DarkerColorCode = Color3.fromHSV(H,S,V+(-DarkerColorPercentage * V/100))

			Decal.Color = DarkerColorCode
		elseif Extra.Tone == "Use NippleColor" then
			if Extra.NippleColor ~= nil then
				Decal.Color = Extra.NippleColor
			end
		end
	end

	-- V4.3.451: dead code - grep confirms zero call sites in this file. V4.3.447-449
	-- hardened the body (R6/R15 bail, orphan-Parent bail, pcall'd WaitForChilds) but
	-- the function is unreachable from any user-facing flow. Left in place because
	-- it may be invoked via runtime dispatch from `System.MeshOffsets.ToarBreasts`
	-- consumers we haven't audited; deleting would break those if they exist.
	function Function.ToarBreastsOffset(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		-- V4.3.447: R6-only function. R15 has UpperTorso (no "Torso"), and the
		-- children "Left Breast"/"Right Breast" don't exist there either - so each
		-- WaitForChild burned its full 5s timeout before returning nil. 5 sequential
		-- calls = 25s perceived freeze per R15-bundle equip that went through this
		-- path. Fast-bail when the avatar isn't R6.
		-- V4.3.448: bail ONLY when neither Torso nor UpperTorso exists (truly unknown
		-- rig). The V4.3.447 strict "no Torso → bail" regressed R6 mid-respawn:
		-- during respawn the character is parented but limbs haven't fully streamed,
		-- so `FindFirstChild("Torso")` returns nil and we'd skip offset setup
		-- entirely. Original `WaitForChild("Torso", 5)` correctly handled the
		-- streaming-in case for R6. Now: if UpperTorso exists and Torso doesn't,
		-- it's R15 → bail. If neither exists, character is being torn down → bail.
		-- Otherwise let the WaitForChild handle the R6 streaming window.
		-- V4.3.449: also bail on orphaned character (Parent=nil). Pre-V4.3.449 an
		-- orphan Character (post-destroy / mid-cleanup) would fall through to
		-- WaitForChild("Torso", 5) which yields the FULL 5s before returning nil,
		-- and the next 4 sequential WaitForChild calls each yield 2s on orphans →
		-- up to 13s of wasted thread time per orphan invocation. Also pcall the
		-- WaitForChild calls - orphaned instances can throw under some engine paths.
		if not Character or not Character.Parent then return end
		if not Character:FindFirstChild("Torso")
		   and Character:FindFirstChild("UpperTorso") then
			return  -- R15 confirmed
		end
		local _ok, Torso = pcall(function() return Character:WaitForChild("Torso", 5) end)
		if not _ok or not Torso then return end
		-- V4.3.448: restore generous timeouts. V4.3.447's 0.5s caps assumed R6
		-- presence guaranteed the breast children were already there, but mid-equip
		-- the welded breast meshes can land a beat after Torso streams in.
		-- V4.3.449: pcall the remaining WaitForChild calls. Same orphan-throw class
		-- as the Torso fetch above.
		local _ok2, LB = pcall(function() return Torso:WaitForChild("Left Breast", 2) end)
		local _ok3, RB = pcall(function() return Torso:WaitForChild("Right Breast", 2) end)
		if not _ok2 or not _ok3 or not LB or not RB then return end
		local _ok4, LBW = pcall(function() return LB:WaitForChild("Left Breast Weld", 2) end)
		local _ok5, RBW = pcall(function() return RB:WaitForChild("Right Breast Weld", 2) end)
		if not _ok4 or not _ok5 or not LBW or not RBW then return end

		local offsets = System.MeshOffsets.ToarBreasts
		local LCF0, LCF1 = offsets.LCF0, offsets.LCF1
		local RCF0, RCF1 = offsets.RCF0, offsets.RCF1

		local XM, YM, ZM = Function.MultiplyCalculate(Torso.Size, BodyPartSize[Torso.Name])

		local RealtimeProperty = DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[LB]
		if RealtimeProperty then
			RealtimeProperty.CFrame = LCF0

			RealtimeProperty.CFrame1 = LCF1

			DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[LB] = RealtimeProperty
		end

		local RealtimeProperty2 = DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[RB]
		if RealtimeProperty2 then
			RealtimeProperty2.CFrame = RCF0
			RealtimeProperty2.CFrame1 = RCF1
			DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[RB] = RealtimeProperty2
		end

		if DataDetail.MeshSizeLock == false then
			LBW.C0 = CFrame.new(LCF0.Position.X * XM, LCF0.Position.Y * YM, LCF0.Position.Z * ZM) * LCF0.Rotation
			LBW.C1 = CFrame.new(LCF1.Position.X * XM, LCF1.Position.Y * YM, LCF1.Position.Z * ZM) * LCF1.Rotation
			RBW.C0 = CFrame.new(RCF0.Position.X * XM, RCF0.Position.Y * YM, RCF0.Position.Z * ZM) * RCF0.Rotation
			RBW.C1 = CFrame.new(RCF1.Position.X * XM, RCF1.Position.Y * YM, RCF1.Position.Z * ZM) * RCF1.Rotation
		else
			LBW.C0 = LCF0
			LBW.C1 = LCF1
			RBW.C0 = RCF0
			RBW.C1 = RCF1
		end
	end

	function Function.BunnyBandPin(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local BasePart

		if ObjectInstance.Name == "Left Bunny Band" then
			BasePart = Character:FindFirstChild("Left Arm")
		else
			BasePart = Character:FindFirstChild("Right Arm")
		end

		local Pin = Instance.new("Part", ObjectInstance)
		Pin.Shape = Enum.PartType.Cylinder
		Pin.Color = Color3.fromRGB(253, 234, 141)
		Pin.Material = Enum.Material.Metal
		Pin.CanCollide = false
		Pin.CanQuery = false
		Pin.CanTouch = false
		Pin.Massless = true
		Pin.CustomPhysicalProperties = System.Physics.DefaultProperties
		Pin.Size = System.Transformation.MeshScale.BunnyBandPin

		local Weld = Instance.new("Weld", Pin)
		Weld.Part0 = ObjectInstance
		Weld.Part1 = Pin
		Weld.C0 = System.MeshOffsets.BunnyBandPin.WeldC0

		DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[Pin] = {Size = Pin.Size, CFrame = Weld.C0, CFrame1 = CFrame.new(0,0,0), Base = BasePart, Weld = Weld}
	end

	function Function.SurfaceTexture(ObjectInstance, Character, Extra, Data)
		if ObjectInstance:FindFirstChildOfClass("SurfaceAppearance") then return end
		-- V4.5.2: this converts a part's TextureID into a SurfaceAppearance (moves it to ColorMap
		-- then clears TextureID). ColorMap is a PROTECTED asset property - on a non-elevated thread
		-- (Studio / published place) the write throws, and the resulting empty SA would MASK the
		-- texture the part already had -> the part greys out (WORSE than doing nothing). If we
		-- already know ColorMap is unwritable (latched by _setOrCreateSA), skip the conversion and
		-- leave the part on its working TextureID. Otherwise probe: keep the SA on success, or drop
		-- it + preserve the TextureID on failure. Executors write ColorMap fine -> unchanged there.
		if System._saCMW == false then return end
		local _tex = ObjectInstance.TextureID
		local SP = Instance.new("SurfaceAppearance", ObjectInstance)
		if pcall(function() SP.ColorMap = _tex end) then
			System._saCMW = true
			ObjectInstance.TextureID = ""
		else
			System._saCMW = false
			SP:Destroy()
		end
	end

	-- V4.3.319: Roblox shirt/pants application now overwrites an EXISTING (see Changelog for full rationale)
	-- V4.5.2: SurfaceAppearance.ColorMap is a PROTECTED asset property. A plain LocalScript
	-- thread (Studio harness, published place) throws "lacking capability Plugin" on the
	-- assignment; the injected executor thread has the capability and succeeds. Pre-fix the
	-- throw landed INSIDE a caller pcall, so the half-built SA (ColorMap unset, default
	-- AlphaMode, no marker) survived and SILENTLY MASKED the part's TextureID -> clothing
	-- rendered blank with NO error surfaced (worst failure mode). Now: probe the capability
	-- via the first real write; on success latch true and behave byte-for-byte as before
	-- (executors always hit this on call 1). On failure latch false and DEGRADE to
	-- MeshPart.TextureID + the ship's own OilUp equivalence (a Transparency>0 part honors the
	-- template's alpha). Returns "sa" or "tex" so callers pick the matching Transparency
	-- (0 for an alpha-mode SA; 0.011 for the TextureID alpha-blend trick).
	-- latch lives on System (System._saCMW) not a new upvalue, to avoid adding a local register
	-- to this already-at-ceiling scope (the Studio -g2 build caps at 200 locals/function).
	-- Opaque MeshPart.TextureID ignores clothing alpha on restricted threads.
	-- Keep the skin intact and paint a separately owned, alpha-blended shell.
	function Function._ClothingTextureLayer(part)
		local existing = part:FindFirstChild("RCClothingTextureLayer")
		if existing and existing:GetAttribute("RCClothingLayer") then return existing end
		local archivable = part.Archivable
		part.Archivable = true
		local layer = part:Clone()
		part.Archivable = archivable
		layer.Name = "RCClothingTextureLayer"
		for _, child in ipairs(layer:GetChildren()) do
			if not child:IsA("Bone") then child:Destroy() end
		end
		for _, tag in ipairs(game:GetService("CollectionService"):GetTags(layer)) do
			game:GetService("CollectionService"):RemoveTag(layer, tag)
		end
		layer:SetAttribute("RCClothingLayer", true)
		layer.Color = Color3.new(1, 1, 1)
		layer.TextureID = ""
		layer.Anchored = false
		layer.Massless = true
		layer.CanCollide = false
		layer.CanTouch = false
		layer.CanQuery = false
		local connections = {}
		local function bind(object, property, update)
			update()
			table.insert(connections, object:GetPropertyChangedSignal(property):Connect(update))
		end
		bind(part, "Size", function() layer.Size = part.Size * 1.0005 end)
		bind(part, "Transparency", function() layer.Transparency = part.Transparency >= 1 and 1 or 0.011 end)
		bind(part, "Material", function() layer.Material = part.Material end)
		-- Skinned variants need the same bone pose, but must never register a second solver.
		local function bindBones(source, target)
			for _, bone in ipairs(source:GetChildren()) do
				if bone:IsA("Bone") then
					local copy = target:FindFirstChild(bone.Name)
					if copy and copy:IsA("Bone") then
						bind(bone, "CFrame", function() copy.CFrame = bone.CFrame end)
						bind(bone, "Transform", function() copy.Transform = bone.Transform end)
						bindBones(bone, copy)
					end
				end
			end
		end
		bindBones(part, layer)
		layer.CFrame = part.CFrame
		local weld = Instance.new("WeldConstraint")
		weld.Part0, weld.Part1 = part, layer
		weld.Parent = layer
		layer.Destroying:Connect(function()
			for _, connection in ipairs(connections) do connection:Disconnect() end
		end)
		layer.Parent = part
		return layer
	end

	function Function._ClearClothingTextureLayer(part, marker)
		local layer = part:FindFirstChild("RCClothingTextureLayer")
		if layer and layer:GetAttribute("RCClothingLayer") and (not marker or layer:GetAttribute(marker)) then
			layer:Destroy()
		end
	end

	function Function._ClearClothingAppearance(part, marker)
		local layer = part:FindFirstChild("RCClothingTextureLayer")
		local sa = part:FindFirstChildOfClass("SurfaceAppearance")
		local sm = part:FindFirstChildOfClass("SpecialMesh")
		local painted = layer and layer:GetAttribute(marker) and layer
			or sa and sa:GetAttribute(marker) and sa
			or sm and sm:GetAttribute(marker) and sm
			or part:GetAttribute(marker) and part
		-- Hosted PNGs have no Shirt/Pants instance for the heal path to read.
		-- Keep the removed template on its owning part until healing or rebuild.
		if painted and painted:GetAttribute("KrulHosted") then
			local ok, template = pcall(function()
				return painted == sa and sa.ColorMap or painted == sm and sm.TextureId or painted.TextureID
			end)
			if ok and type(template) == "string" and template ~= "" then
				part:SetAttribute("_RC_HPRestore_" .. marker, template)
				part:SetAttribute("_RC_HPAlpha_" .. marker, painted == part or (painted == sa and sa.AlphaMode == Enum.AlphaMode.Transparency))
				part:SetAttribute("_RC_HPSpecial_" .. marker, painted == sm)
			end
		end
		Function._ClearClothingTextureLayer(part, marker)
		if sa and sa:GetAttribute(marker) then sa:Destroy() end
		if sm and sm:GetAttribute(marker) then
			local original = sm:GetAttribute("_RC_ClothingBaseTexture")
			if original ~= nil then sm.TextureId = original end
			sm:SetAttribute("_RC_ClothingBaseTexture", nil)
			sm:SetAttribute(marker, nil)
			sm:SetAttribute("KrulHosted", nil)
		end
		if part:GetAttribute(marker) then
			local original = part:GetAttribute("_RC_ClothingBaseTexture")
			if original ~= nil then
				pcall(function() part.TextureID = original end)
				part:SetAttribute("_RC_ClothingBaseTexture", nil)
			end
			part:SetAttribute(marker, nil)
			part:SetAttribute("KrulHosted", nil)
		end
		for _, child in ipairs(part:GetChildren()) do
			if not child:GetAttribute("RCClothingLayer") then
				Function._ClearClothingAppearance(child, marker)
			end
		end
	end

	local function _setOrCreateSA(part, template, alphaMode, marker)
		if System._saCMW ~= false then
			local sa = part:FindFirstChildOfClass("SurfaceAppearance")
			local _created = false
			if not sa then
				sa = Instance.new("SurfaceAppearance", part)
				_created = true
			end
			local _ok = pcall(function() sa.ColorMap = template end)
			if _ok then
				System._saCMW = true
				Function._ClearClothingTextureLayer(part)
				if alphaMode then sa.AlphaMode = alphaMode end
				sa:SetAttribute(marker, true)
				return "sa"
			end
			System._saCMW = false
			-- a half-built SA masks TextureID entirely; remove the one WE just made (or a
			-- prior RoClothes-marked one). Never touch a game-baked/unmarked skin SA.
			if _created or sa:GetAttribute(marker) then sa:Destroy() end
		end
		-- fallback (no ColorMap capability): clear any stale RoClothes-marked SA that would
		-- mask TextureID, then paint the template straight onto the part's TextureID.
		local _stale = part:FindFirstChildOfClass("SurfaceAppearance")
		if _stale and (_stale:GetAttribute("RoClothesShirt") or _stale:GetAttribute("RoClothesPants") or _stale:GetAttribute("RoClothesTShirt") or _stale:GetAttribute("KrulHosted")) then
			_stale:Destroy()
		end
		pcall(function()
			local target = part
			if alphaMode ~= Enum.AlphaMode.Transparency then target = Function._ClothingTextureLayer(part) end
			if target == part and part:GetAttribute("_RC_ClothingBaseTexture") == nil then
				part:SetAttribute("_RC_ClothingBaseTexture", part.TextureID)
			end
			target.TextureID = template
			for _, oldMarker in ipairs({"RoClothesShirt", "RoClothesPants", "RoClothesTShirt", "KrulHosted"}) do
				target:SetAttribute(oldMarker, nil)
			end
			target:SetAttribute(marker, true)
		end)
		return alphaMode == Enum.AlphaMode.Transparency and "tex" or "layer"
	end

	function Function._RestoreHPHosted(part, marker)
		local restored = false
		local template = part:GetAttribute("_RC_HPRestore_" .. marker)
		if template then
			local painted
			if part:GetAttribute("_RC_HPSpecial_" .. marker) then
				painted = part:FindFirstChildOfClass("SpecialMesh") or Instance.new("SpecialMesh", part)
				painted:SetAttribute("_RC_ClothingBaseTexture", painted.TextureId)
				painted.TextureId = template
				painted:SetAttribute(marker, true)
			else
				local alpha = part:GetAttribute("_RC_HPAlpha_" .. marker) and Enum.AlphaMode.Transparency or Enum.AlphaMode.Overlay
				local mode = _setOrCreateSA(part, template, alpha, marker)
				painted = mode == "layer" and part:FindFirstChild("RCClothingTextureLayer")
					or mode == "sa" and part:FindFirstChildOfClass("SurfaceAppearance") or part
			end
			if painted then painted:SetAttribute("KrulHosted", true) end
			part:SetAttribute("_RC_HPRestore_" .. marker, nil)
			part:SetAttribute("_RC_HPAlpha_" .. marker, nil)
			part:SetAttribute("_RC_HPSpecial_" .. marker, nil)
			restored = true
		end
		for _, child in ipairs(part:GetChildren()) do
			if not child:GetAttribute("RCClothingLayer") then
				restored = Function._RestoreHPHosted(child, marker) or restored
			end
		end
		return restored
	end

	function Function.ShirtTexture(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local template = Extra.Shirt and Extra.Shirt.ShirtTemplate
		if not template and Extra.Pants and Extra.Pants.PantsTemplate then
			template = Extra.Pants.PantsTemplate
		end
		if template and table.find(DataDetail.CurrentClothes, "Roblox Shirt") then
			if ObjectInstance.Material == Enum.Material.Glass then
				ObjectInstance.TextureID = template
			else
				_setOrCreateSA(ObjectInstance, template, nil, "RoClothesShirt")
			end
		end
	end

	function Function.PantsTexture(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if Extra.Pants and Extra.Pants.PantsTemplate and table.find(DataDetail.CurrentClothes, "Roblox Pants") then
			if ObjectInstance.Material == Enum.Material.Glass then
				ObjectInstance.TextureID = Extra.Pants.PantsTemplate
			else
				_setOrCreateSA(ObjectInstance, Extra.Pants.PantsTemplate, nil, "RoClothesPants")
			end
		end
	end

	function Function.TorsoShirtTexture(ObjectInstance, Character, Extra, Data, transparency)
		local DataDetail = PlayerData[Data]
		local template = Extra.Shirt and Extra.Shirt.ShirtTemplate
		-- V4.5.24: Pants-slot fallback exists for legacy torso/breast-shirt routes,
		-- but the two VNS bra meshes are shirt-only clothing overlays.
		if not template and ObjectInstance.Name ~= "BreastClothes" and Extra.Pants and Extra.Pants.PantsTemplate then
			template = Extra.Pants.PantsTemplate
		end
		if template and (table.find(DataDetail.CurrentClothes, "Roblox Shirt") or table.find(DataDetail.CurrentClothes, "New Woman") or table.find(DataDetail.CurrentClothes, "Roblox Breasts Clothing") or table.find(DataDetail.CurrentClothes, "Roblox Breasts Clothing Type 2") or table.find(DataDetail.CurrentClothes, "Roblox Breasts Clothing Type 3")) then
			if ObjectInstance.Material == Enum.Material.Glass or ObjectInstance:HasTag("RCGlassMat") then
				ObjectInstance.TextureID = template
				if (transparency == nil or transparency ~= false) and ObjectInstance.Transparency < 1 then
					ObjectInstance.Transparency = 0.011
				end
			else
				local _mode = _setOrCreateSA(ObjectInstance, template, Enum.AlphaMode.Transparency, "RoClothesShirt")
				if transparency == nil or transparency ~= false then
					-- "tex" fallback: 0.011 enables texture-alpha blending (same equivalence OilUp uses)
					ObjectInstance.Transparency = (_mode == "tex") and 0.011 or 0
				end
			end
		end
	end

	function Function.TorsoPantsTexture(ObjectInstance, Character, Extra, Data, transparency)
		local DataDetail = PlayerData[Data]
		if Extra.Pants and Extra.Pants.PantsTemplate and (table.find(DataDetail.CurrentClothes, "Roblox Pants") or table.find(DataDetail.CurrentClothes, "New Woman") or table.find(DataDetail.CurrentClothes, "Roblox Breasts Clothing") or table.find(DataDetail.CurrentClothes, "Roblox Breasts Clothing Type 2") or table.find(DataDetail.CurrentClothes, "Roblox Breasts Clothing Type 3")) then  -- V4.3.339: parity with TorsoShirtTexture gate at L5908
			if ObjectInstance.Material == Enum.Material.Glass or ObjectInstance:HasTag("RCGlassMat") then
				ObjectInstance.TextureID = Extra.Pants.PantsTemplate
				-- V4.3.343: parity with TorsoShirtTexture L5911 - was `transparency ~= true` (wrong polarity).
				if (transparency == nil or transparency ~= false) and ObjectInstance.Transparency < 1 then
					ObjectInstance.Transparency = 0.011
				end
			else
				local _mode = _setOrCreateSA(ObjectInstance, Extra.Pants.PantsTemplate, Enum.AlphaMode.Transparency, "RoClothesPants")
				-- V4.3.343: parity with TorsoShirtTexture L5916.
				if transparency == nil or transparency ~= false then
					-- "tex" fallback: 0.011 enables texture-alpha blending (parity w/ TorsoShirtTexture)
					ObjectInstance.Transparency = (_mode == "tex") and 0.011 or 0
				end
			end
		end
	end

	function Function.TorsoShirtGraphic(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if Extra.TShirt and table.find(DataDetail.CurrentClothes, "Roblox Shirt") then
			-- V4.3.347: tag with marker + replace existing T-shirt SA on re-equip.
			-- the `not :FindFirstChildOfClass("SurfaceAppearance")` guard meant the FIRST SA
			-- won - changing the T-shirt id did nothing until respawn. And the SA was untagged
			-- so cleanup couldn't distinguish ours from game-baked. Now we destroy any prior
			-- T-shirt-tagged SA, then create+tag a fresh one carrying the latest Graphic.
			local _existing = ObjectInstance:FindFirstChildOfClass("SurfaceAppearance")
			if _existing and _existing:GetAttribute("RoClothesTShirt") then _existing:Destroy() end
			-- Bail if a non-RoClothes SA already lives here (don't clobber baked skin SAs).
			if ObjectInstance:FindFirstChildOfClass("SurfaceAppearance") then return end
			local Decal = Instance.new("SurfaceAppearance", ObjectInstance)
			Decal.ColorMap = Extra.TShirt.Graphic
			pcall(function() Decal:SetAttribute("RoClothesTShirt", true) end)
		end
	end

	function Function.NewWomanShirtClothing(ObjectInstance, Character, Extra, Data)
		-- V4.3.539 Fix 2: structural fix for community-reported "New Woman arm
		-- blocky + can't remove + can't move with edit tool" (Victoria 2026-06-06).
		-- This function IS LIVE - base.json on krulhub.dev contains 2 dispatch
		-- references via the manifest's `"Function":"NewWomanShirtClothing"` string
		-- (verified 2026-06-06 by direct fetch). The earlier verification agent's
		-- "dead code" verdict only searched the local source file and missed the
		-- manifest dispatch - same structural blindness V4.3.535 caught for the
		-- other 25 orphan-looking handlers. See [[reference_krulhub_manifest_dispatch]].
		--
		-- Pre-fix three bugs (all from a stale CharacterMesh-based design):
		-- (1) BLOCKY: CharacterMesh only applies when parented under a Humanoid
		--     that lives in a real character rig consumed by Avatar service. The
		--     handler parented a stub Humanoid+CharacterMesh into a wrapper Model
		--     parented to ObjectInstance (the arm part), NOT the real character
		--     rig. Engine silently ignored the CharacterMesh, so the cloned Arm
		--     rendered as a blocky clone of the original (no SpecialMesh, no
		--     CharacterMesh applied). Switched to SpecialMesh with the same
		--     R6 arm asset IDs (83001137 / 83001181) which DOES apply directly
		--     to a non-character BasePart.
		-- (2) CAN'T REMOVE: The cloned Arm part was never registered in
		--     DataDetail.CurrentPartList.Clothes, so unequip path at L4365-4373
		--     (scrubClothState → mesh sweep) had no handle and skipped it on
		--     destroy. Now registered under "New Woman <armSide>" key.
		-- (3) CAN'T GIZMO-MOVE: The cloned Arm was never registered in
		--     RealtimeUpdateList.Mesh, so the gizmo target dropdown (L24445 reads
		--     this map) couldn't see it and the Weld.C0 write path (L8565/L10164)
		--     had no entry to mutate. Now registered with Base + Size + CFrame +
		--     Weld fields matching sibling Mesh entries.
		-- (4) DEAD HUMANOID: dropped - was residue from the CharacterMesh strategy.
		--     Would otherwise let engine try to ragdoll the wrapper Model.
		local DataDetail = PlayerData[Data]
		local Model = Instance.new("Model", ObjectInstance)
		local Arm
		local weld
		if ObjectInstance.Name == "New Woman Left Arm Mesh" then
			Arm = ObjectInstance:Clone()
			Arm.Transparency = 0
			Arm.Parent = Model
			Arm.Name = "Left Arm"
			weld = Instance.new("Weld", Model)
			weld.Part0 = ObjectInstance
			weld.Part1 = Arm
			-- V4.3.540 Fix 7: explicit identity baseline for weld.C0/C1. Pre-fix
			-- the V4.3.539 Fix 2 registration captured `weld.C0` immediately after
			-- Weld instantiation when both C0 and C1 were implicit identity. The
			-- gizmo "Reset Offset" path (L8565 / L10164) reads the cached CFrame
			-- from RealtimeUpdateList.Mesh and writes it back to weld.C0 - without
			-- an explicit baseline this is technically a no-op (identity → identity)
			-- but a future refactor that switches to relative-to-cached-offset math
			-- would teleport the Arm to origin on first nudge. Make intent explicit.
			weld.C0 = CFrame.new()
			weld.C1 = CFrame.new()
			-- V4.3.539 Fix 2: SpecialMesh on the cloned part (was CharacterMesh + stub
			-- Humanoid in wrapper Model - non-functional outside real character rig).
			local sm = Instance.new("SpecialMesh", Arm)
			sm.MeshId = "rbxassetid://83001137"
		else
			Arm = ObjectInstance:Clone()
			Arm.Transparency = 0
			Arm.Parent = Model
			Arm.Name = "Right Arm"
			weld = Instance.new("Weld", Model)
			weld.Part0 = ObjectInstance
			weld.Part1 = Arm
			weld.C0 = CFrame.new()  -- V4.3.540 Fix 7: explicit baseline; see Left Arm branch comment
			weld.C1 = CFrame.new()
			local sm = Instance.new("SpecialMesh", Arm)
			sm.MeshId = "rbxassetid://83001181"
		end
		-- V4.3.539 Fix 2: register the spawned Arm so unequip + gizmo can see it.
		-- Mirrors the sibling registration pattern at L13021 (SB dispatcher).
		if DataDetail and DataDetail.CurrentPartList then
			if DataDetail.CurrentPartList.Clothes then
				DataDetail.CurrentPartList.Clothes["New Woman " .. Arm.Name] = Arm
				-- V4.3.540 Fix 7: ALSO register the wrapper Model under a distinct
				-- key so scrubClothState's destroy sweep (L4365-area) cleans up the
				-- Model whose Destroy() cascades to Arm + Weld + SpecialMesh. Pre-
				-- fix the scrub destroyed Arm alone, leaving zombie Models
				-- accumulating under ObjectInstance per equip cycle.
				DataDetail.CurrentPartList.Clothes["New Woman " .. Arm.Name .. " Wrapper"] = Model
			end
			if DataDetail.CurrentPartList.RealtimeUpdateList
				and DataDetail.CurrentPartList.RealtimeUpdateList.Mesh then
				DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[Arm] = {
					Base = ObjectInstance, Size = Arm.Size,
					CFrame = weld.C0, CFrame1 = weld.C1, Weld = weld,
				}
			end
		end
		if Extra.Shirt and table.find(DataDetail.CurrentClothes, "New Woman") then
			Extra.Shirt:Clone().Parent = Model
		end
	end

	function Function.NewWomanBreastShirtClothing(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if Extra.Shirt and table.find(DataDetail.CurrentClothes, "New Woman") then
			if not ObjectInstance:FindFirstChildOfClass("SurfaceAppearance") then
				local Decal = Instance.new("SurfaceAppearance", ObjectInstance)
