	function Function.TopLayer(Visible, c, Data)
		local PData = PlayerData[Data]
		local appliedOrgans = {}
		for _, k in ipairs({"Left Arm","Right Arm"}) do
			local v = PData.CurrentPartList["Organ"][k]; if v then table.insert(appliedOrgans, v) end
		end
		local appliedTOrgans = {}
		-- V4.5.24: Bra 1/2 are the two VNS breast clothing-overlay meshes. V4.5.21
		-- removed them to stop the old AlphaMode.Overlay path making their cutouts solid;
		-- TorsoShirtTexture now routes them through the capability-safe Transparency path.
		for _, k in ipairs({"Torso Shirt","Breasts Shirt","Breasts Shirt 2","Breasts Shirt 3","Breast Clothes SB1","Breast Clothes SB2"}) do
			local v = PData.CurrentPartList["Clothes"][k]; if v then table.insert(appliedTOrgans, v) end
		end
		-- Hosted shirts can paint the skin torso when no Torso Shirt exists.
		-- Channel ownership keeps the pants layer intact on a shirt rip.
		local torso = PData.CurrentPartList.Organ.Torso
		if torso then
			if Visible == false then Function._ClearClothingAppearance(torso, "RoClothesShirt")
			else Function._RestoreHPHosted(torso, "RoClothesShirt") end
		end
		if Visible == false then
			-- V4.3.526 Fix 4: V4.3.519 Fix 9 changed HPClothes.Shirt storage to number.
			-- Consumer `not tonumber(...)` was always false → texture-apply branch unreachable.
			-- V4.3.526 Fix 4 was ROLLED BACK: the flip would crash on .ShirtTemplate deref when Shirt
			-- is a number, so all 4 Shirt sites below keep `not tonumber(...)`. Deferred to V4.3.527+.
			for i, v in pairs(appliedOrgans) do
				Function._ClearClothingAppearance(v, "RoClothesShirt")
				Function._ClearClothingAppearance(v, "RoClothesTShirt")
				if v:FindFirstChild(v.Name.. "OILOVERLAY") then
					local s = v:FindFirstChild(v.Name.. "OILOVERLAY")
					if PData.HPClothes.Shirt ~= "" and not tonumber(PData.HPClothes.Shirt) then -- V4.3.526 Fix 4 ROLLBACK: flip would crash on .ShirtTemplate; deferred to V4.3.527+
						s.TextureID = PData.HPClothes.Shirt.ShirtTemplate
					else
						s.Transparency = 1
						s:SetAttribute("MaxTransparencyRC",1)
					end
				else
					-- V4.3.347: respect RoClothes marker - don't destroy game-baked SAs (e.g. SB body
					-- skin SA from RigVnsModel cloneRoot). Pre-fix this loop nuked any SA on every
					-- TopLayer pass, wiping V4.3.345 _paintSBOverlay marker (RoClothesShirt) every
					-- time a cloth toggle fired and exposing the rbxm-default white skin until next
					-- full reset. Now only destroy SAs we created ourselves.
					local _existingSA = v:FindFirstChildOfClass("SurfaceAppearance")
					if _existingSA and (_existingSA:GetAttribute("RoClothesShirt") or _existingSA:GetAttribute("RoClothesTShirt")) then
						_existingSA:Destroy()
					end
					if PData.HPClothes.Shirt ~= "" and not tonumber(PData.HPClothes.Shirt) then -- V4.3.526 Fix 4 ROLLBACK: flip would crash on .ShirtTemplate; deferred to V4.3.527+
						Function.ShirtTexture(v,nil,{Shirt = PData.HPClothes.Shirt},Data)
					end
				end
			end
			for i, v in pairs(appliedTOrgans) do
				Function._ClearClothingAppearance(v, "RoClothesShirt")
				Function._ClearClothingAppearance(v, "RoClothesTShirt")
				Function._ClearClothingAppearance(v, "KrulHosted")
				if v:FindFirstChild(v.Name.. "OILOVERLAY") then
					local s = v:FindFirstChild(v.Name.. "OILOVERLAY")
					if PData.HPClothes.Shirt ~= "" and not tonumber(PData.HPClothes.Shirt) then -- V4.3.526 Fix 4 ROLLBACK: flip would crash on .ShirtTemplate; deferred to V4.3.527+
						s.TextureID = PData.HPClothes.Shirt.ShirtTemplate
					else
						s.Transparency = 1
						s:SetAttribute("MaxTransparencyRC",1)
					end
				else
					if PData.HPClothes.Shirt ~= "" and not tonumber(PData.HPClothes.Shirt) then -- V4.3.526 Fix 4 ROLLBACK: flip would crash on .ShirtTemplate; deferred to V4.3.527+
						if v.Name == "Torso Shirt" then
							v:SetAttribute("maxDeterminedRC",false)
							v:SetAttribute("MaxTransparencyRC",nil)
							--v.Transparency = v.Parent.Transparency
						end
						Function.TorsoShirtTexture(v,nil,{Shirt = PData.HPClothes.Shirt},Data,false)
					end
				end
			end

		else
			local shirtObj = c:FindFirstChildOfClass("Shirt")
			local pantsObj = c:FindFirstChildOfClass("Pants")
			local fallbackExtra = shirtObj and {Shirt = shirtObj} or (pantsObj and {Pants = pantsObj} or nil)
			local template = shirtObj and shirtObj.ShirtTemplate or (pantsObj and pantsObj.PantsTemplate)
			for i, v in pairs(appliedOrgans) do
				if Function._RestoreHPHosted(v, "RoClothesShirt") then continue end
				if v:FindFirstChild(v.Name.. "OILOVERLAY") then
					local s = v:FindFirstChild(v.Name.. "OILOVERLAY")
					if template then
						s:SetAttribute("MaxTransparencyRC",nil)
						s.TextureID = template
					end
				else
					-- V4.3.347: respect RoClothes marker (see L6196 comment).
					local sa = v:FindFirstChildOfClass("SurfaceAppearance")
					if sa and (sa:GetAttribute("RoClothesShirt") or sa:GetAttribute("RoClothesPants") or sa:GetAttribute("RoClothesTShirt") or sa:GetAttribute("KrulHosted")) then
						sa:Destroy()
					end
					if fallbackExtra then
						Function.ShirtTexture(v,c,fallbackExtra,Data)
					end
				end
			end
			for i, v in pairs(appliedTOrgans) do
				if Function._RestoreHPHosted(v, "RoClothesShirt") then continue end
				if v:FindFirstChild(v.Name.. "OILOVERLAY") then
					local s = v:FindFirstChild(v.Name.. "OILOVERLAY")
					-- VNS bras are shirt-only; never feed the TopLayer pants fallback
					-- into an oil-overlay clone of BreastClothes.
					if template and (shirtObj or v.Name ~= "BreastClothes") then
						s:SetAttribute("MaxTransparencyRC",nil)
						s.TextureID = template
					end
				else
					-- V4.3.347: marker-gated SA destroy.
					local sa = v:FindFirstChildOfClass("SurfaceAppearance")
					if sa and (sa:GetAttribute("RoClothesShirt") or sa:GetAttribute("RoClothesPants") or sa:GetAttribute("RoClothesTShirt") or sa:GetAttribute("KrulHosted")) then
						sa:Destroy()
					end
					if fallbackExtra then
						Function.TorsoShirtTexture(v,c,fallbackExtra,Data,false)
					end
				end
			end

		end
	end

	function Function.BottomLayer(Visible, c, Data)
		local PData = PlayerData[Data]
		local appliedOrgans = {}
		-- V4.5.21 (owner call 2026-08-10): removed "Breast Clothes SB1"/"SB2" (SB bras) from the PANTS-paint
		-- list too -- a Roblox Pants would otherwise overwrite the bra's SurfaceAppearance the same way a shirt
		-- did. The bra keeps its own texture. (Sibling fix: TopLayer L14386, KrulHosted L22174.)
		for _, k in ipairs({"Torso","Left Leg","Right Leg","Left Butt","Right Butt","Breasts Pants","Breasts Pants 2","Breasts Pants 3"}) do
			local v = PData.CurrentPartList["Organ"][k] or PData.CurrentPartList["Clothes"][k]; if v then table.insert(appliedOrgans, v) end
		end

		if Visible == false then
			for i, v in pairs(appliedOrgans) do
				Function._ClearClothingAppearance(v, "RoClothesPants")
				if v:FindFirstChild(v.Name.. "OILOVERLAY") then
					local s = v:FindFirstChild(v.Name.. "OILOVERLAY")
					-- V4.3.531 Fix 1: V4.3.526 Fix 4 ROLLBACK sibling missed at this site. The Shirt
					-- equivalents at L9549/9565/9573 were rolled back (`not tonumber(...)`) because the
					-- flip would crash on `.PantsTemplate` deref on a numeric. This Pants site kept the
					-- flipped form and would set TextureID to nil whenever Pants is a numeric ID (the
					-- V4.3.519 Fix 9 storage form), silently wiping the texture. Restored to match Shirt.
					if PData.HPClothes.Pants ~= "" and not tonumber(PData.HPClothes.Pants) then
						s.TextureID = PData.HPClothes.Pants.PantsTemplate
					else
						s.Transparency = 1
						s:SetAttribute("MaxTransparencyRC",1)
					end
				else
					-- V4.3.347: marker-gated SA destroy.
					local _ssa = v:FindFirstChildOfClass("SurfaceAppearance")
					if _ssa and _ssa:GetAttribute("RoClothesPants") then
						_ssa:Destroy()
					end
					if PData.HPClothes.Pants ~= "" and not tonumber(PData.HPClothes.Pants) then -- V4.3.526 Fix 4 ROLLBACK: flip would crash on .PantsTemplate; deferred to V4.3.527+
						Function.PantsTexture(v,nil,{Pants = PData.HPClothes.Pants},Data)
					end
				end
			end
		else
			for i, v in pairs(appliedOrgans) do
				if Function._RestoreHPHosted(v, "RoClothesPants") then continue end
				if v:FindFirstChild(v.Name.. "OILOVERLAY") then
					local s = v:FindFirstChild(v.Name.. "OILOVERLAY")
					if c:FindFirstChildOfClass("Pants") then
						s:SetAttribute("MaxTransparencyRC",nil)
						s.TextureID = c:FindFirstChildOfClass("Pants").PantsTemplate
					end
				else
					-- V4.3.347: marker-gated SA destroy.
					local _ssa = v:FindFirstChildOfClass("SurfaceAppearance")
					if _ssa and (_ssa:GetAttribute("RoClothesShirt") or _ssa:GetAttribute("RoClothesPants") or _ssa:GetAttribute("RoClothesTShirt") or _ssa:GetAttribute("KrulHosted")) then
						_ssa:Destroy()
					end
					if c:FindFirstChildOfClass("Pants") then
						Function.PantsTexture(v,c,{Pants = c:FindFirstChildOfClass("Pants")},Data)
					end
				end
			end
		end
	end

