	--module part--

	function Function.Spring.new(initial, clock)
		local target = initial or 0
		clock = clock or os.clock
		return setmetatable({
			_clock = clock;
			_time0 = clock();
			_position0 = target;
			_velocity0 = 0*target;
			_target = target;
			_damper = 1;
			_speed = 1;
		}, Function.Spring)
	end
	function Function.Spring:Impulse(velocity)
		self.Velocity = self.Velocity + velocity
	end
	function Function.Spring:TimeSkip(delta)
		local now = self._clock()
		local position, velocity = self:_positionVelocity(now+delta)
		self._position0 = position
		self._velocity0 = velocity
		self._time0 = now
	end
	function Function.Spring:__index(index)
		if Function.Spring[index] then
			return Function.Spring[index]
		elseif index == "Value" or index == "Position" or index == "p" then
			local position, _ = self:_positionVelocity(self._clock())
			return position
		elseif index == "Velocity" or index == "v" then
			local _, velocity = self:_positionVelocity(self._clock())
			return velocity
		elseif index == "Target" or index == "t" then
			return self._target
		elseif index == "Damper" or index == "d" then
			return self._damper
		elseif index == "Speed" or index == "s" then
			return self._speed
		elseif index == "Clock" then
			return self._clock
		else
			error(("%q is not a valid member of Spring"):format(tostring(index)), 2)
		end
	end
	function Function.Spring:__newindex(index, value)
		local now = self._clock()

		if index == "Value" or index == "Position" or index == "p" then
			local _, velocity = self:_positionVelocity(now)
			self._position0 = value
			self._velocity0 = velocity
			self._time0 = now
		elseif index == "Velocity" or index == "v" then
			local position, _ = self:_positionVelocity(now)
			self._position0 = position
			self._velocity0 = value
			self._time0 = now
		elseif index == "Target" or index == "t" then
			local position, velocity = self:_positionVelocity(now)
			self._position0 = position
			self._velocity0 = velocity
			self._target = value
			self._time0 = now
		elseif index == "Damper" or index == "d" then
			local position, velocity = self:_positionVelocity(now)
			self._position0 = position
			self._velocity0 = velocity
			-- V4.5.24 Fix: clamp Damper exactly like Speed above. A NaN or negative Damping value
			-- (bad slider/loadup) made exp((-d+h)*t) diverge to inf/NaN in _positionVelocity, which
			-- then propagated into the weld C0 written every physics frame (part explode/teleport).
			-- d=0 is safe: d2<1 branch gives h=1, no division-by-zero.
			self._damper = (value == value and value >= 0) and value or 0
			self._time0 = now
		elseif index == "Speed" or index == "s" then
			local position, velocity = self:_positionVelocity(now)
			self._position0 = position
			self._velocity0 = velocity
			-- V4.5.24 Fix: same NaN defense the Damper branch got - `value < 0` passes NaN through,
			-- which then misses the s==0 guard and NaNs the weld C0 in _positionVelocity.
			self._speed = (value == value and value >= 0) and value or 0
			self._time0 = now
		elseif index == "Clock" then
			local position, velocity = self:_positionVelocity(now)
			self._position0 = position
			self._velocity0 = velocity
			self._clock = value
			self._time0 = value()
		else
			error(("%q is not a valid member of Spring"):format(tostring(index)), 2)
		end
	end
	function Function.Spring:_positionVelocity(now)
		local p0 = self._position0
		local v0 = self._velocity0
		local p1 = self._target
		local d = self._damper
		local s = self._speed

		if s == 0 then return p1, v0*0 end  -- avoid si/s division by zero

		local t = s*(now - self._time0)
		local d2 = d*d

		local h, si, co
		if d2 < 1 then
			h = math.sqrt(1 - d2)
			local ep = math.exp(-d*t)/h
			co, si = ep*math.cos(h*t), ep*math.sin(h*t)
		elseif d2 == 1 then
			h = 1
			local ep = math.exp(-d*t)/h
			co, si = ep, ep*t
		else
			h = math.sqrt(d2 - 1)
			local u = math.exp((-d + h)*t)/(2*h)
			local v = math.exp((-d - h)*t)/(2*h)
			co, si = u + v, u - v
		end

		local a0 = h*co + d*si
		local a1 = 1 - (h*co + d*si)
		local a2 = si/s

		local b0 = -s*si
		local b1 = s*si
		local b2 = h*co - d*si

		return a0*p0 + a1*p1 + a2*v0,b0*p0 + b1*p1 + b2*v0
	end

	-- tail module --

	local modelInstance = Instance.new("Model")
	local modelGetScale = modelInstance.GetScale
	modelInstance:Destroy()  -- only the method reference is needed; destroy the instance

	local cframeIdentity = CFrame.identity
	local cframeToObjectSpace = cframeIdentity.ToObjectSpace
	local cframeVectorToObjectSpace = cframeIdentity.VectorToObjectSpace
	local cframeInverse = cframeIdentity.Inverse
	local cframeToEulerAnglesXYZ = cframeIdentity.ToEulerAnglesXYZ
	local cframeFromEulerAngles = CFrame.fromEulerAngles
	local cframeNew = CFrame.new

	-- Caculate Elasticity
	local function calculateElasticity(
		position: Vector3,
		velocity: Vector3,
		stiffness: number,
		damping: number
	): (Vector3, Vector3)
		local springForce = stiffness * position -- position is the displacement since anchor is (0, 0, 0) otherwise this would be (position - anchor).
		local dampingForce = damping * velocity
		-- v_new = v - (k*x + c*v)*dt  (restoring force opposes displacement; damping opposes velocity)
		local acceleration = springForce + dampingForce

		local newVelocity = velocity - acceleration * timeStep
		local newValue = position + newVelocity * timeStep

		return newValue, newVelocity
	end

	local function vector3ToAngles(vector3:Vector3):CFrame
		return cframeFromEulerAngles(vector3.X, vector3.Y, vector3.Z)
	end

	-- Linear interpolation.
	local function lerp(from:number, to:number, alpha:number):number
		return from + (to - from) * alpha
	end

	local function cframeOrAttachmentOrNilParameterToCFrame(parameter:CFrame|Attachment?):CFrame
		return parameter and (typeof(parameter) == "CFrame" and parameter or parameter.CFrame) or CFrame.identity
	end

	-- V4.3.375: removed dead `Function.getTailPivotOffsetFromRoot(size)` stub.
	-- It was never called (the live consumer is the local `getTailPivotOffsetFromRoot(root)`
	-- declared further down at the same lexical level, with a different signature).

	-- Converts a string to a wag seed which is used to desync tails.
	local function nameToTailWagSeed(name:string):number
		local wagSeed = 0
		for _, byte:string in {string.byte(name, 1, string.len(name))} do
			wagSeed += (byte * byte)
		end
		return wagSeed
	end


	-- Fast system for checking if an accessory's name is an included accessory.
	local includedAccessoryNames = {}
	local excludeAccessoryNames = {}
	local includedAccessoryNamesValidationSet:{[Instance]:boolean} = {}

	-- The table includedAccessoryNames could have changes and this allows the set to only be computed when necessary.
	local includedAccessoryNamesValidationSetNeedsUpdating = true

	-- Creates the set that allows for indexing with an accessory name to receive true or nil.
	local function updateIncludedAccessoryNamesValidationSet()
		includedAccessoryNamesValidationSet = {}
		for _, accessoryName in includedAccessoryNames do
			includedAccessoryNamesValidationSet[accessoryName] = true
		end
		for _, accessoryName in excludeAccessoryNames do
			includedAccessoryNamesValidationSet[accessoryName] = false
		end
		includedAccessoryNamesValidationSetNeedsUpdating = false
	end

	local function isTailAccessory(accessory:Accessory):boolean
		local _okAT, accessoryType = pcall(function() return accessory.AccessoryType end)  -- BUGFIX: guard like every other AccessoryType read - old executors lack the member and would throw here, killing the accessory-apply pass
		if not _okAT then return false end
		local accessoryName = accessory.Name
		if accessoryType == Enum.AccessoryType.Back or accessoryType == Enum.AccessoryType.Waist then
			if includedAccessoryNamesValidationSetNeedsUpdating then updateIncludedAccessoryNamesValidationSet() end
			if string.find(string.lower(accessoryName), "tail", 1, true) then
				if includedAccessoryNamesValidationSet[accessoryName] == nil
					or includedAccessoryNamesValidationSet[accessoryName] == true then
					return true
				end
			elseif includedAccessoryNamesValidationSet[accessoryName] then
				return true
			end
		end
		return false
	end

	-- R6 Torso tail pivot offset.
	-- Gets the tail pivot offset from a root part for both R15 and R6.
	local function getTailPivotOffsetFromRoot(root:Part):CFrame?
		if root then
			-- R15  LowerTorso and UpperTorso have WaistRigAttachment.
			local waistRigAttachment:Attachment = root:FindFirstChild("WaistRigAttachment")
			if waistRigAttachment then
				return waistRigAttachment.CFrame * CFrame.new(0, 0, root.Size.Z * 0.5)
			end

			-- R6  Torso.
			local waistBackAttachment:Attachment = root:FindFirstChild("WaistBackAttachment")
			if waistBackAttachment then
				return waistBackAttachment.CFrame * System.Transformation.CFramePresets.r6TailPivotOffset
			end
		end
	end

	local function setUpWeld(character:Model, weld:Weld, tailPart:BasePart, customPivotOffset:CFrame|Attachment?, Data)
		local DataDetail = PlayerData[Data]
		-- Get root part.
		local flipAccessoryWeldParts = false
		local root:Part
		local retries = 0
		local function loadRoot(c)
			if c then
				if retries > 10 then
					warn(string.format("[RoClothes] Weld '%s' on character '%s' failed to resolve Part%d after 10 retries.",
						tostring(weld.Name), tostring(character.Name), c))
					return
				else
					retries += 1
					task.wait()
				end
			end

			root = weld.Part0
			if not root then loadRoot(0) end
			if root == tailPart then
				root = weld.Part1
				if not root then loadRoot(1) end
				flipAccessoryWeldParts = true
			end
		end
		loadRoot()
		if not root then return end

		-- Get pivot offset.
		local pivotOffset:CFrame?
		if customPivotOffset then
			pivotOffset = cframeOrAttachmentOrNilParameterToCFrame(customPivotOffset)
		else
			pivotOffset = getTailPivotOffsetFromRoot(root)
		end
		if not pivotOffset then warn("Could not find attachment on part \""..root.Name.."\" for the character \""..character.Name.."\". Make sure the character has finished loading and you've set Part0.") return end

		-- Get weld original cframe.
		local weldOriginalCFrame:CFrame
		if flipAccessoryWeldParts then
			weldOriginalCFrame = weld.C1 * cframeInverse(weld.C0) -- C1 * C0^-1

			-- Switch around because physics tails handles Part0 as the root.
			weld.Part0, weld.Part1 = root, tailPart
		else
			weldOriginalCFrame = weld.C0 * cframeInverse(weld.C1) -- C0 * C1^-1
		end

		-- Update weld.
		weld.C0 = weldOriginalCFrame -- Not really required but theoretically it could render 1 frame before it's updated by the physics tails engine.
		weld.C1 = cframeIdentity -- Clearing C1 is required (merged with C0), the tails do not use C1. Available for people if they want.

		-- Adjust pivot to be relative to weldOriginalCFrame.
		pivotOffset = cframeToObjectSpace(weldOriginalCFrame, cframeNew(pivotOffset.Position))

		-- Get wag seed.
		local wagSeed = nameToTailWagSeed(character.Name)
		local player = PS:GetPlayerFromCharacter(character)
		if player then
			wagSeed += player.UserId
		end

		-- Add to physicsTails table.
		local physicsTail = {
			root = root,
			rootPreviousCFrame = root.CFrame,
			rootPreviousDeltaCFrame = cframeIdentity,

			weld = weld,
			weldOriginalCFrame = weldOriginalCFrame,
			weldPreviousCFrame = weldOriginalCFrame,

			weldCurrentCFrame = weldOriginalCFrame,

			currentAngle = Vector3.zero,
			angularVelocity = Vector3.zero,
			wagAnimationBlendAlpha = 0,
			wagSeed = wagSeed,

			--pivotOffset = pivotOffset,
			pivotCFrame = weldOriginalCFrame * pivotOffset,
			inversePivotOffsetCFrame = cframeInverse(pivotOffset),

			character = character,
			-- V4.3.348: guard against modelGetScale returning 0 (mid-respawn / empty model on
			-- legacy executors) which would propagate inf/NaN through every per-tick weld
			-- multiply downstream (tail snaps to world origin permanently).
			inverseCharacterScale = (function() local s = modelGetScale(character); return (s and s > 0) and (1 / s) or 1 end)(),
		}
		DataDetail.CurrentPartList.physicsTails[tailPart.Parent] = physicsTail
	end

	local function setUpTailAccessory(character:Model, accessory:Accessory, Data)
		-- Get weld.
		local handle:Part = accessory:FindFirstChild("Handle")
		if not handle then
			-- Accessory is most likely still loading. We will just wait until the handle is added.
			accessory.ChildAdded:Once(function()
				setUpTailAccessory(character, accessory, Data)
			end)
			return
		end

		local weld:Weld = handle:FindFirstChildOfClass("Weld")
		if not weld then
			-- Accessory is most likely still loading. We will just wait until the weld is added.
			handle.ChildAdded:Once(function()
				setUpTailAccessory(character, accessory, Data)
			end)
			return
		end

		-- Set up accessory weld.
		setUpWeld(character, weld, handle, nil, Data)
	end


	-- Updates the physics tail to display as its static form.
	local function updatePhysicsTailToStatic(physicsTail:physicsTail)
		-- Get character scale.
		local characterScale = physicsTail.inverseCharacterScale * modelGetScale(physicsTail.character)

		local weldOriginalCFrame = physicsTail.weldOriginalCFrame -- Avoiding table lookups is faster.
		physicsTail.weld.C0 = weldOriginalCFrame.Rotation + weldOriginalCFrame.Position * characterScale
	end

	-- Computes a frame of the tail animation.
	local function getTailAnimationOffset(physicsTail:physicsTail,Data):Vector3
		local variables = System.tailVariables[Data]
		local wagAnimationBlendAlpha = physicsTail.wagAnimationBlendAlpha -- Avoiding table lookups is faster.
		if physicsTail.angularVelocity.Magnitude > 0.3 then
			-- Lerp algorithm simplified.
			wagAnimationBlendAlpha = wagAnimationBlendAlpha < 0.01 and 0 or wagAnimationBlendAlpha * (1 - wagAnimationBlendOutAlpha)
		else
			wagAnimationBlendAlpha = wagAnimationBlendAlpha > 0.99 and 1 or lerp(wagAnimationBlendAlpha, 1, wagAnimationBlendInAlpha)
		end
		physicsTail.wagAnimationBlendAlpha = wagAnimationBlendAlpha

		-- Check if it has to do anything otherwise if wagAnimationBlendAlpha is 0 then there is no animation offset.
		if wagAnimationBlendAlpha > 0 then
			local wagTime = variables.tailScaledAnimationTime + physicsTail.wagSeed

			-- FluctuatingWagTime allows the tail to move visually randomly instead of a plain linear timeline.
			local fluctuatingWagTime = wagTime + math.sin(wagTime) * math.sin(wagTime * 0.22727272727272727) * 0.9

			-- Add to newCurrentAngle since it will add to the tail from there anyway.
			return Vector3.new(
				(math.sin(fluctuatingWagTime * 2) + 0.8) * wagAnimationDropAmplitude * wagAnimationBlendAlpha,
				math.cos(fluctuatingWagTime) * wagAnimationSwayAmplitude * wagAnimationBlendAlpha,
				math.sin(fluctuatingWagTime) * -wagAnimationRollAmplitude * wagAnimationBlendAlpha
			)
		end

		return Vector3.zero
	end

	-- Updates the physics tail to display as its interpolated cframe.
	local function updatePhysicsTailToInterpolation(physicsTail:physicsTail, interpolationAlpha:number, Data)
		local DataDetail = PlayerData[Data]
		-- Get character scale.
		local characterScale = physicsTail.inverseCharacterScale * modelGetScale(physicsTail.character)

		-- Interpolate.
		local weldCFrame = physicsTail.weldPreviousCFrame:Lerp(physicsTail.weldCurrentCFrame, interpolationAlpha)

		-- Wag animation.
		if DataDetail.tailSettings.wagAnimationEnabled then
			-- Take the animation-pivoted rotation and figure out what rotation difference it represents in the current tail's space, then apply it to the tail.
			weldCFrame *= cframeInverse(
				cframeToObjectSpace(weldCFrame,
					physicsTail.pivotCFrame * vector3ToAngles(getTailAnimationOffset(physicsTail,Data)) * physicsTail.inversePivotOffsetCFrame
				)
			)
		end

		-- Update weld.
		physicsTail.weld.C0 = weldCFrame.Rotation + weldCFrame.Position * characterScale
	end



	local persistentTailWindUnit:Vector3 = Vector3.zero -- Wind direction (safe default; .Unit on zero vector = NaN).
	local persistentTailWindAlpha:number -- Wind from 0 to 1 defining how significant it is.
	local persistentTailWindAlpha_Times_04:number -- Pre-computation.
	local persistentTailWindAlpha_Squared_Times_006:number -- Pre-computation.
	local persistentTailWindForceRelevant = false -- If wind force magnitude is 0 then this is false.

	local function updateTailPersistentWindForceInformation()
		local persistentTailWindForce = globalWindEnabled and (workspace.GlobalWind + customPersistentWindForce) or customPersistentWindForce

		-- Wind magnitude.
		persistentTailWindAlpha = persistentTailWindForce.Magnitude * 0.5

		-- Wind direction (guard: .Unit on zero vector produces NaN).
		if persistentTailWindAlpha > 0 then
			persistentTailWindUnit = persistentTailWindForce.Unit
		end

		-- Pre-computations.
		persistentTailWindAlpha_Times_04 = persistentTailWindAlpha * 0.4
		persistentTailWindAlpha_Squared_Times_006 = persistentTailWindAlpha * persistentTailWindAlpha * 0.06

		-- Wind relevance.
		persistentTailWindForceRelevant = persistentTailWindAlpha > 0
	end
	updateTailPersistentWindForceInformation()

	-- Update wind information on change.
	-- V4.3.168.14: inlined the Connect-handle local into the GlobalMaid:Give call.
	-- Named RoClothes-scope local was write-once and only referenced once next line.
	System.GlobalMaid:Give(workspace:GetPropertyChangedSignal("GlobalWind"):Connect(updateTailPersistentWindForceInformation))

	local gravityForce:Vector3 -- Gravity force.
	local persistentTailLinearForce:Vector3 -- Linear force.
	local persistentTailLinearForceRelevant = false -- If linear force magnitude is 0 then this is false.
	local function updateTailPersistentLinearForceInformation()
		-- Linear force.
		persistentTailLinearForce = gravityEnabled and (gravityForce + customPersistentLinearForce) or customPersistentLinearForce

		-- Linear force relevance.
		persistentTailLinearForceRelevant = persistentTailLinearForce.Magnitude > 0
	end

	local function updateGravityInformation()
		local gravity = workspace.Gravity

		gravityForce = Vector3.new(0,
		--[[
			This calculates the effect of the gravity and returns:
			-1 to 0.1 (tail slightly lifted in low gravity and pulled in high gravity for a nice visual aesthetic).
		]]
			math.max((196.2 - gravity) * 0.004, -1))

		-- Update persistentTailLinearForce after gravityForce update.
		updateTailPersistentLinearForceInformation()
	end
	updateGravityInformation()

	-- Update gravity information on change.
	-- V4.3.168.14: inlined the Connect-handle local into the AllConnect insert.
	table.insert(AllConnect, workspace:GetPropertyChangedSignal("Gravity"):Connect(updateGravityInformation))


	local vector3Zero = Vector3.zero
	local vector3Cross = vector3Zero.Cross
	local vector3New = Vector3.new
	-- Update/step a physics tail.
	local function updatePhysicsTail(physicsTail:physicsTail, updateWeld:boolean, interpolationAlpha:number, Data)
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		-- V4.3.339: nil-guard destroyed parts. After respawn the prior character's `root` /
		-- `weld` are destroyed but still referenced by `physicsTail`; first frame after
		-- respawn would error "attempt to index nil with 'CFrame'". Body-physics path had
		-- this guard at L2282; tails didn't.
		if not (physicsTail.root and physicsTail.root.Parent) then return end
		if not (physicsTail.weld and physicsTail.weld.Parent) then return end
		local tailSettings = DataDetail.tailSettings
		local variables = System.tailVariables[Data]

		-- Get new state of the root part.
		local rootCFrame = physicsTail.root.CFrame

		-- Change in position, which is velocity (without change in time).
		local rootDeltaCFrame = cframeToObjectSpace(physicsTail.rootPreviousCFrame, rootCFrame)

		-- Max a tail can have physics from movement.
		if rootDeltaCFrame.Position.Magnitude > math.max(1,physicsTail.root.AssemblyLinearVelocity.Magnitude) --[[movementDistanceThreshold]] then
			-- H-5 fix: removed leftover debug warn() - was firing every frame during teleports/respawns,
			-- spamming the console and allocating strings in the hot path.
			rootDeltaCFrame = rootDeltaCFrame.Rotation -- clear position
		end

		-- Change in velocity, which is acceleration (without change in time).
		local rootAcceleration = cframeToObjectSpace(physicsTail.rootPreviousDeltaCFrame, rootDeltaCFrame)

		-- Force from walking around + any other forces that will be added before calculating it all to angular velocity.
		local tailForce = rootAcceleration.Position * tailSettings.linearAmplitude

		-- Compute wind force fluctuation.
		if persistentTailWindForceRelevant then
			-- Cache sin(unixTime * 4).
			local sinUnixTime4 = math.sin(variables.tailScaledTime * 4)

			-- Jittery effect for when the wind is strong.
			local unstableWindFlow = math.sin(variables.tailScaledTime * 2 * sinUnixTime4) * persistentTailWindAlpha_Times_04

			-- Calm wind effect.
			local stableWindFlow = math.sin(variables.tailScaledTime * 2) * sinUnixTime4

			-- Add wind force.
			tailForce -= cframeVectorToObjectSpace(rootCFrame, persistentTailWindUnit * persistentTailWindAlpha_Squared_Times_006 * (1 + (stableWindFlow + unstableWindFlow) * 0.4))
		end

		-- Add persistent linear force.
		if persistentTailLinearForceRelevant then tailForce -= cframeVectorToObjectSpace(rootCFrame, persistentTailLinearForce) end

		-- Cache pivotCFrame to use in displacement and weld CFrame
		local pivotCFrame = physicsTail.pivotCFrame -- Avoiding table lookups is faster.

		-- Forces for walking around.
		local displacement = pivotCFrame.Position - physicsTail.weldPreviousCFrame.Position
		local torque = vector3Cross(displacement, tailForce)

		-- Forces for turning around.
		local angularAcceleration = vector3New(cframeToEulerAnglesXYZ(rootAcceleration)) * tailSettings.angularAmplitude

		-- Update old forces. Originally had it as: physicsTail.currentAngle, physicsTail.angularVelocity = fun(...) however avoiding table lookups is faster.
		local newCurrentAngle, newAngularVelocity = calculateElasticity(physicsTail.currentAngle, physicsTail.angularVelocity, tailSettings.stiffness, tailSettings.damping)

		-- Update newCurrentAngle before we make further changes to it with the wag animation.
		physicsTail.currentAngle = newCurrentAngle

		-- Get character scale.
		local characterScale = physicsTail.inverseCharacterScale * modelGetScale(physicsTail.character)
		if not (characterScale > 0) then characterScale = 1 end  -- BUGFIX: inverseCharacterScale is guarded at setup (V4.3.348), but this per-tick modelGetScale re-call can still return 0 mid-respawn -> `torque / 0` = NaN poisons angularVelocity forever. Guard 0/neg/NaN.

		-- Update and apply new forces.
		physicsTail.angularVelocity = newAngularVelocity + torque / characterScale - angularAcceleration

		-- Update weld.
		local currentAngleCFrame = vector3ToAngles(newCurrentAngle) -- newCurrentAngle here is the one modified by wag animation.
		local newWeldCurrentCFrame = pivotCFrame * currentAngleCFrame * physicsTail.inversePivotOffsetCFrame
		local newWeldPreviousCFrame = physicsTail.weldCurrentCFrame
		if updateWeld then
			-- Interpolate.
			local weldCFrame = newWeldPreviousCFrame:Lerp(newWeldCurrentCFrame, interpolationAlpha)

			-- Wag animation.
			if tailSettings.wagAnimationEnabled then
				-- Take the animation-pivoted rotation and figure out what rotation difference it represents in the current tail's space, then apply it to the tail.
				weldCFrame *= cframeInverse(
					cframeToObjectSpace(weldCFrame,
						pivotCFrame * vector3ToAngles(getTailAnimationOffset(physicsTail,Data)) * physicsTail.inversePivotOffsetCFrame
					)
				)
			end

			-- Update weld.
			physicsTail.weld.C0 = weldCFrame.Rotation + weldCFrame.Position * characterScale
		end

		-- Update previous.
		physicsTail.rootPreviousCFrame = rootCFrame
		physicsTail.rootPreviousDeltaCFrame = rootDeltaCFrame

		physicsTail.weldPreviousCFrame = newWeldPreviousCFrame
		physicsTail.weldCurrentCFrame = newWeldCurrentCFrame
	end

	local cameraPosition = Vector3.zero
	local function physicsTailsDistanceToCameraComparer(a:physicsTail, b:physicsTail):boolean
		return a.distanceToCamera < b.distanceToCamera
	end


	--function part--

	function Function.convertToJSON(value:UDim2)
		if typeof(value) == "Color3" then
			return {["R"] = value.R, ["G"] = value.G, ["B"] = value.B}
		elseif typeof(value) == "Vector3" then
			return {["X"] = value.X, ["Y"] = value.Y, ["Z"] = value.Z}
		elseif typeof(value) == "EnumItem" then
			-- Serialize an EnumItem as { EnumType = <bare type name>, Value = <number> }, which
			-- convertFromJSON reconstructs via Enum[name] + GetEnumItems. Used for preset/bundle
			-- enums; keybinds take a simpler plain-name path (see saveData / _kbFromSaved).
			-- V4.3.576: tostring of an Enum TYPE is the BARE name ("KeyCode"), NOT "Enum.KeyCode".
			-- The old V4.3.566 `:sub(6)` assumed an "Enum." prefix and chopped "KeyCode" -> "de",
			-- poisoning every saved enum. gsub strips the prefix only if present, so it is correct
			-- whether tostring returns the bare or the prefixed form.
			return {["EnumType"] = (tostring(value.EnumType):gsub("^Enum%.", "")), ["Value"] = value.Value}  -- V4.3.576: was :sub(6) -> "de" bug
		elseif typeof(value) == "UDim2" then
			return {["Scale"]={["X"] = value.X.Scale, ["Y"] = value.Y.Scale},
				["Offset"]={["X"] = value.X.Offset, ["Y"] = value.Y.Offset}}
		elseif typeof(value) == "CFrame" then
			-- V4.3.534 F5: CFrame round-trip. Pre-fix HS:JSONEncode silently stripped CFrame
			-- userdata (returns null), so any preset/bundle field holding a CFrame (notably
			-- GizmoOffsets.<target>.RotCF - per-part gizmo rotation) was silently lost on
			-- save → reload. _atomicWriteJSON readback decoded the null back to nil, and
			-- consumers got a missing-rotation surprise. Use the 12-component "CF" array
			-- form (matches CFrame.new(x,y,z, R00,R01,R02, R10,R11,R12, R20,R21,R22)) for
			-- maximum round-trip precision. convertFromJSON below recognizes the {CF=...}
			-- shape and reconstructs the CFrame.
			return {["CF"] = {value:GetComponents()}}
		end
		return value
	end

	-- V4.3.518 Fix 2: pcall + ambiguity guard. Pre-fix, any table with R/G/B keys
	-- coerced to Color3 - including user dicts that legitimately used those names
	-- as numeric IDs. Now: only coerce when the key signature is UNAMBIGUOUS
	-- (Color3 keys present AND no Vector3 keys, etc.) and the constructor doesn't
	-- throw on the values. Ambiguous tables fall through to plain-table return.
	function Function.convertFromJSON(value)
		if typeof(value) == "table" then
			local _hasRGB = (value.R ~= nil and value.G ~= nil and value.B ~= nil)
			local _hasXYZ = (value.X ~= nil and value.Y ~= nil and value.Z ~= nil)
			if _hasRGB and not _hasXYZ then
				local _r, _g, _b = tonumber(value.R), tonumber(value.G), tonumber(value.B)
				if _r and _g and _b then
					local _ok, _c = pcall(Color3.new, _r, _g, _b)
					if _ok then return _c end
				end
			elseif _hasXYZ and not _hasRGB then
				local _x, _y, _z = tonumber(value.X), tonumber(value.Y), tonumber(value.Z)
				if _x and _y and _z then
					local _ok, _v = pcall(Vector3.new, _x, _y, _z)
					if _ok then return _v end
				end
			elseif value["EnumType"] and value["Value"] then
				-- V4.3.520 Fix 6: backward-compat with the legacy "Enum.Foo" string format
				-- that was silently failing prior. Strip the "Enum." prefix if present.
				local _eName = value.EnumType
				if type(_eName) == "string" then
					_eName = _eName:gsub("^Enum%.", "")
				end
				local _enumType; if type(_eName) == "string" then pcall(function() _enumType = Enum[_eName] end) end  -- V4.5.19: guard - Enum[badName] RAISES (and a non-string EnumType from a corrupt/hostile community bundle skipped the gsub but still indexed Enum), aborting the whole preset/bundle load
				if _enumType then
					-- Reconstruct the EnumItem from {EnumType, Value}. Roblox Enum has NO built-in
					-- :FromValue (only the third-party EnumExtender adds it), so go value->item via
					-- GetEnumItems() (a real API) matching .Value. Used for preset/bundle enums;
					-- keybinds take the simpler plain-name path (see _kbFromSaved in the settings load).
					local _okItems, _items = pcall(_enumType.GetEnumItems, _enumType)
					if _okItems and type(_items) == "table" then
						local _want = tonumber(value.Value)
						for _, _it in ipairs(_items) do
							if _it.Value == _want then return _it, false end
						end
					end
				end
			elseif type(value["CF"]) == "table" and #value.CF == 12 then
				-- V4.3.534 F5: CFrame restore (mirror of convertToJSON's "CF" array form).
				-- Type-guarded entries; pcall-protected constructor; falls through to
				-- plain-table return on any malformed component (NaN, non-number, wrong
				-- count). Worst case is a silent identity-CFrame fallback at the consumer.
				local _cf = value.CF
				local _ok, _c = pcall(CFrame.new,
					tonumber(_cf[1]) or 0, tonumber(_cf[2]) or 0, tonumber(_cf[3]) or 0,
					tonumber(_cf[4]) or 1, tonumber(_cf[5]) or 0, tonumber(_cf[6]) or 0,
					tonumber(_cf[7]) or 0, tonumber(_cf[8]) or 1, tonumber(_cf[9]) or 0,
					tonumber(_cf[10]) or 0, tonumber(_cf[11]) or 0, tonumber(_cf[12]) or 1)
				if _ok then return _c, false end
			elseif value["Scale"] and value["Offset"] then
				if typeof(value.Scale) == "table" and typeof(value.Offset) == "table" then
					local _sx, _ox = tonumber(value.Scale.X), tonumber(value.Offset.X)
					local _sy, _oy = tonumber(value.Scale.Y), tonumber(value.Offset.Y)
					-- V4.3.519 Fix 1: NaN/inf guard. V4.3.518 Fix 2 stopped erroring on bad UDim2 input,
					-- but silent fallthrough to raw-table means downstream Position writes throw later
					-- with worse stack traces. Detect and emit a diag instead of silent corruption.
					if _sx and _ox and _sy and _oy then
						-- NaN self-compare: NaN ~= NaN
						if _sx == _sx and _ox == _ox and _sy == _sy and _oy == _oy
						   and math.abs(_sx) ~= math.huge and math.abs(_ox) ~= math.huge
						   and math.abs(_sy) ~= math.huge and math.abs(_oy) ~= math.huge then
							local _ok, _u = pcall(UDim2.new, _sx, _ox, _sy, _oy)
							if _ok then return _u end
						else
							_diagPublicCall("convertFromJSON.udim2_invalid", { sx=tostring(_sx), ox=tostring(_ox), sy=tostring(_sy), oy=tostring(_oy) })
						end
					end
				end
			end
		end
		return value,true
	end

	function Function.toFormatString(value)
		if typeof(value) == "Color3" then
			-- V4.3.302: round to integers - `R*255` is float (e.g. 127.5); Color3.fromRGB
			-- expects ints, and float args round inconsistently across executors.
			return string.format("Color3.fromRGB(%d, %d, %d)",
				math.floor(value.R * 255 + 0.5),
				math.floor(value.G * 255 + 0.5),
				math.floor(value.B * 255 + 0.5))
		elseif typeof(value) == "Vector3" then
			return string.format("Vector3.new(%s, %s, %s)", value.X, value.Y, value.Z)
		elseif typeof(value) == "string" then
			return string.format("%q", value)
		elseif typeof(value) == "CFrame" then
			return string.format("CFrame.new(%s)", tostring(value))
		end
		return tostring(value)
	end

	function Function.JaroSimilarity(original: string, target: string): number
		local original_len = original:len()
		local target_len = target:len()

		if (original_len == 0 and target_len == 0) or (original == target) then return 1 end

		local match_distance = (math.floor(math.max(original_len, target_len) / 2)) - 1
		local original_matches = table.create(original_len, false)
		local target_matches = table.create(target_len, false)

		local matches = 0
		local transpositions = 0

		local min = math.min
		local max = math.max
		for i = 1, original_len do
			local _start = max(1, i - match_distance)
			local _end = min(i + match_distance, target_len)  -- V4.3.302: was +1, off-by-one extending Jaro window

			for j = _start, _end do
				if target_matches[j] then
					continue end
				if original:sub(i, i) ~= target:sub(j, j)  then
					continue end
				original_matches[i] = true
				target_matches[j] = true
				matches += 1
				break
			end
		end

		if matches == 0 then
			return 0
		end

		local k = 1
		for i = 1, original_len do
			if not original_matches[i] then continue end

			while target_matches[k] == false do
				k += 1
			end

			if original:sub(i, i) ~= target:sub(k, k) then
				transpositions += 1
			end
			k += 1
		end

		local similarity = ((matches / original_len) + (matches / target_len) + ((matches - transpositions / 2) / matches)) / 3

		return similarity
	end

	function Function.JaroDistance(original: string, target: string): number
		return 1 - Function.JaroSimilarity(original, target)
	end

	function Function.AttachmentCreate(Character)
		for Attach, ParentName in pairs(AttachmentParent) do
			local Base = Character:FindFirstChild(ParentName)

			if Base and not Base:FindFirstChild(Attach) then
				local Attachment = Instance.new("Attachment", Base)
				Attachment.Name = Attach
				Attachment.CFrame = AttachmentCFrame[Attach]
			end
		end
	end

	function Function.HeadMesh(Part)
		local SpecialMesh = Instance.new("SpecialMesh", Part)
		SpecialMesh.MeshType = Enum.MeshType.Head
		SpecialMesh.Scale = Vector3.new(1.25, 1.25, 1.25)
	end

	function Function.Dummy(CF)
		local DummyModel = Instance.new("Model")
		DummyModel.Archivable = not hidden
		DummyModel:AddTag(System.RCTag)
		local DummyHumanoid = Instance.new("Humanoid", DummyModel)

		local RootPart = Instance.new("Part", DummyModel)
		RootPart.Name = "HumanoidRootPart"
		RootPart.Size = Vector3.new(2,2,1)
		RootPart.Anchored = true
		RootPart.Transparency = 1

		DummyModel.PrimaryPart = RootPart

		for Name, Property in pairs(DummyMesh) do
			local Part = Instance.new("Part", DummyModel)
			Part.Size = Property.Size
			Part.CFrame = RootPart.CFrame * Property.Offset
			Part.Anchored = true
			Part.Name = Name

			if Name == "Head" then
				Function.HeadMesh(Part)
			end
		end

		Function.AttachmentCreate(DummyModel)

		return DummyModel
	end

	function Function.CharacterPreview(Data)
		if CharacterPreviewLoading == false then
			CharacterPreviewLoading = true
			GUIObject.ViewportFrame:ClearAllChildren()

			local Dummy = Function.Dummy()

			local DataCharacter = PS:FindFirstChild(Data)

			if DataCharacter and DataCharacter.Character then
				for _, v in pairs(DataCharacter.Character:GetChildren()) do
					if v:IsA("Shirt") or v:IsA("Pants") or v:IsA("ShirtGraphic") or v:IsA("Accessory") or v:IsA("BodyColors") then
						local cv = v:Clone()

						cv.Parent = Dummy

						if cv:IsA("Accessory") then
							local Handle = cv:FindFirstChildOfClass("Part") or cv:FindFirstChildOfClass("MeshPart")

							if Handle then
								local Weld = Handle:FindFirstChildOfClass("Weld") or Handle:FindFirstChildOfClass("WeldConstraint")

								if Weld and Weld.Part0 then
									Weld.Part0 = Dummy:FindFirstChild(Weld.Part0.Name)
								end
							end
						end
					elseif v:IsA("Part") then
						local Base = Dummy:FindFirstChild(v.Name)

						if Base then
							Base.Color = v.Color
						end
					end
				end
			end

			Dummy.Parent = game.Workspace
			-- V4.3.339: bump LastRequestID before Reset+Execute so any in-flight prior CharacterExecute
			-- against this Data goes stale at its next post-yield RID checkpoint and stops mutating PD.
			-- Without this bump, the prior call's RID stays valid and its post-yield writes race the
			-- Dummy build (V4.3.199-style fix that was missing on this Dummy preview path).
			if PlayerData[Data] then
				PlayerData[Data].LastRequestID = (PlayerData[Data].LastRequestID or 0) + 1
			end
			local _previewRID = PlayerData[Data] and PlayerData[Data].LastRequestID
			-- V4.3.343: Reset target was wrong - passed `SelectPlayer` as PlayerName and `Data`
			-- as NPCClear, so the wrong player's PD was reset (and the V4.3.339 RID bump on
			-- PlayerData[Data] wasn't matched by an actual reset on Data). Fixed: reset Data to
			-- match the Execute target below.
			Function.CharacterReset(Data)
			Function.CharacterExecute(Dummy, Data, nil, _previewRID)

			task.wait()
			Dummy.Parent = GUIObject.ViewportFrame

			CharacterPreviewLoading = false

			return Dummy
		end
	end

	function Function.SpringCreate(Object, Base, Target, Velocity, Speed, Damper, PositionOffset, Position, RotationOffset, Rotation, Data)
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		if not Object then return end

		local Weld = Object:FindFirstChildOfClass("Weld") or Object:FindFirstChildOfClass("WeldConstraint")
		if Weld then
				local CF = Weld.C0
			local CF1 = Weld.C1

			local Spring = Function.Spring.new(Vector3.new(0,0,0))
			Spring.Target = Target;
			Spring.Velocity = Velocity;
			Spring.Speed = Speed;
			Spring.Damper = Damper;

			-- Secondary overtone spring (higher freq, feeds off primary velocity)
			local Spring2 = nil
			if DataDetail.OvertoneEnabled then
				Spring2 = Function.Spring.new(Vector3.new(0,0,0))
				Spring2.Target   = Vector3.new(0,0,0)
				Spring2.Velocity = Vector3.new(0,0,0)
				Spring2.Speed    = Speed * 3.2
				Spring2.Damper   = math.min(Damper * 2, 0.95)
			end

			DataDetail.CurrentPartList.BodyPartPhysics[Object] = {
				Spring = Spring,
				Spring2 = Spring2,
				Base = Base,
				Weld = Weld,
				CF = CF,
				CF1 = CF1,
				OriginCFrame = Base.CFrame,
				PositionOffset = PositionOffset,
				Position = Position,
				RotationOffset = RotationOffset,
				Rotation = Rotation,
				BreastsType = DataDetail.BreastsType,
				-- V4.3.460: precomputed offset dispatch. Pre-fix, _doPhysicsTickPart
				-- ran two `for From, To in pairs(...)` + if/elseif string-compare chains
				-- per part per frame (6 hash lookups + 6 string compares each). Now
				-- flattened to direct fields: _poX_to / _poY_to / _poZ_to give the
				-- target axis for each from-axis. Same for rotation.
				_poX_to = PositionOffset and PositionOffset.X,
				_poY_to = PositionOffset and PositionOffset.Y,
				_poZ_to = PositionOffset and PositionOffset.Z,
				_roX_to = RotationOffset and RotationOffset.X,
				_roY_to = RotationOffset and RotationOffset.Y,
				_roZ_to = RotationOffset and RotationOffset.Z,
			}

		end
	end

	function Function.MinMaxCalulate(Base, Min, Max)
		return math.max(math.min(Base, Max), Min)
	end

	function Function.CFrameOrientation(CF)
		local x, y, z = CF:ToOrientation()
		return Vector3.new(math.deg(x), math.deg(y), math.deg(z))
	end

	-- ─────────────────────────────────────────────────────────────────────────
	-- SmartBone-based body physics (VNS mesh integration) - Phase 2
	-- ─────────────────────────────────────────────────────────────────────────

	-- VNS bundle supplies physics modules/assets. RoClothes retains character
	-- rigging and GUI ownership; never invoke the standalone VNS Init/Run path.
	-- V4.3.535 Opt-1: VNS_URL/VNS_LOCAL_PATH/VNS_CACHE/VNS_CACHE_DIR hoisted to file scope (L4528-4531).

	-- Load only SmartBone once per session, initializing its tag contract first.
	-- Returns true on success, nil on failure. Result cached in System._vnsLoaded.
	-- V4.3.219: re-enabled with a key change. Does NOT call vnsApi:Run() (which (see Changelog for full rationale)
	function Function.LoadSmartBoneApi()
		if not System._sessionAlive or not BREAKER.Parent then return end
		-- V4.3.518 Fix 3: cache load-failure flag. Without this every CharacterReset
		-- on a restricted executor re-fires the 2-tier GitHub fetch + DeserializeAsync.
		if System._vnsLoadFailed then return end
		if System._vnsLoaded then return System._vnsLoaded end
		if System._sbLoading then
			local t = 0
			repeat task.wait(0.05); t += 0.05
			until System._sbApi or not System._sbLoading or t > 10
			return System._sbApi
		end
		System._sbLoading = true
		local _loaderThread = coroutine.running()
		System._sbLoaderThread = _loaderThread
		-- Delegate the heavy load (rbxm fetch + custom require setup + content
		-- patches) to the disabled version's body, but stop it before vnsApi:Run().
		-- We do this by inlining the loader and replacing the Run call.
		local ok, err = pcall(function()
			return Function._LoadVnsAndInstallSmartBone_Inner()
		end)
		System._sbLoading = false
		if System._sbLoaderThread == _loaderThread then System._sbLoaderThread = nil end
		if not System._sessionAlive or not BREAKER.Parent then return nil end
		if not ok or err ~= true then
			-- V4.3.261: latch failure for the rest of the session so RigVnsModel's
			-- defensive _sbTag wait can short-circuit (otherwise offline users hit a
			-- 2 s freeze on every body-type / bra build). Cleared on next session via
			-- BREAKER.Destroying or naturally on a fresh execute (System is local).
			System._vnsLoadFailed = true
			warn("[RoClothes] LoadSmartBoneApi failed:", err)
			return nil
		end
		System._vnsLoadFailed = nil
		System._vnsLoaded = true
		return true
	end

	function Function._LoadVnsAndInstallSmartBone_Inner()
		local CG = game:GetService("CoreGui")
		local function _sbSessionAlive()
			return System._sessionAlive == true and BREAKER.Parent ~= nil
		end
		if not _sbSessionAlive() then return end
		-- V4.3.497: SerializationService is Synapse-specific; non-Synapse executors throw on GetService.
		local _ssOk, SS = pcall(game.GetService, game, "SerializationService")
		if not _ssOk then
			SS = nil
			-- V4.3.506 telemetry: SerializationService unavailable (non-Synapse).
			Function.diag("exec.serialization_unavailable", {})
		end
		local _gca = getcustomasset or getsynasset

		-- Reuse vnsRoot if already in CoreGui (defensive - boot cleanup destroys it).
		local vnsRoot = CG:FindFirstChild("_RCVns")
		local _ownsVnsRoot = false
		local _ownedVnsToken = System.BreakerName
		local function _abortDeadSmartBoneLoad()
			if _sbSessionAlive() then return false end
			if _ownsVnsRoot and vnsRoot then
				local _owner
				pcall(function() _owner = vnsRoot:GetAttribute("_RCSessionOwner") end)
				if vnsRoot.Parent == nil or _owner == _ownedVnsToken then pcall(function() vnsRoot:Destroy() end) end
			end
			return true
		end
		local function _hasModuleScript(inst)
			if not inst then return false end
			if inst:IsA("ModuleScript") then return true end
			return inst:FindFirstChildWhichIsA("ModuleScript", true) ~= nil
		end
		if vnsRoot and not _hasModuleScript(vnsRoot) then
			pcall(function() vnsRoot:Destroy() end); vnsRoot = nil
		end

		-- V4.3.520 Fix 10: skip disk cache for VNS until SHA-pinned. Disk-cached rbxm
		-- has no integrity check; any other tool writing to the cache path can ship
		-- ModuleScripts that execute with full script env. HTTP-only refetch costs
		-- ~1s per session but eliminates the cache-poisoning vector.
		local _skipDiskCache = true
		-- Three-tier load: workspace cache, Roblox content folder, GitHub.
		if not _skipDiskCache and not vnsRoot and _gca and env.isfile and env.isfile(VNS_CACHE) then
			local okU, customUrl = pcall(_gca, VNS_CACHE)
			if okU and type(customUrl) == "string" and #customUrl > 0 then
				local okG, objects = pcall(game.GetObjects, game, customUrl)
				if okG and objects and #objects > 0 and _hasModuleScript(objects[1]) then
					vnsRoot = objects[1]
					_ownsVnsRoot = true
				end
				if _abortDeadSmartBoneLoad() then return end
			end
		end
		if not vnsRoot then
			local okG, objects = pcall(game.GetObjects, game, "rbxasset://" .. VNS_LOCAL_PATH)
			if okG and objects and #objects > 0 and _hasModuleScript(objects[1]) then
				vnsRoot = objects[1]
				_ownsVnsRoot = true
			end
			if _abortDeadSmartBoneLoad() then return end
		end
		if not vnsRoot then
			local raw
			-- V4.3.520 Fix 10: same disk-cache skip - disk rbxm is unpinned and trusted
			-- only via path; readfile would feed it to DeserializeInstancesAsync below.
			if not _skipDiskCache and env.isfile and env.isfile(VNS_CACHE) then
				local okR, data = pcall(env.readfile, VNS_CACHE)
				if okR and type(data) == "string" and #data > 1000 then raw = data end
			end
			if not raw then
				local ok, data = pcall(game.HttpGet, game, VNS_URL)
				if _abortDeadSmartBoneLoad() then return end
				if ok and type(data) == "string" and #data > 1000 then
					raw = data
					-- V4.3.521 Fix 4: don't write the disk cache while V4.3.520 Fix 10's _skipDiskCache
					-- is true. Pre-fix the writefile still ran even though the read path was disabled -
					-- dead writes accumulating bytes that are never re-read.
					if not _skipDiskCache and env.writefile then
						if env.makefolder and env.isfolder and not env.isfolder(VNS_CACHE_DIR) then
							pcall(env.makefolder, VNS_CACHE_DIR)
						end
						pcall(env.writefile, VNS_CACHE, raw)
					end
				end
			end
			if raw and buffer and SS then
				local okD, instances = pcall(function()
					return SS:DeserializeInstancesAsync(buffer.fromstring(raw))
				end)
				if okD and instances and #instances > 0 then
					for _, inst in ipairs(instances) do
						if _hasModuleScript(inst) then vnsRoot = inst; _ownsVnsRoot = true; break end
					end
				end
				if _abortDeadSmartBoneLoad() then return end
			end
		end
		if not vnsRoot then error("vns.rbxm could not be loaded") end
		if _abortDeadSmartBoneLoad() then return end
		pcall(function() vnsRoot:SetAttribute("_RCSessionOwner", _ownedVnsToken) end)

		vnsRoot.Name = "_RCVns"
		-- V4.5.22: strip any GUI baked into the VNS rbxm BEFORE parenting vnsRoot into CoreGui below.
		-- Veillith's VNS 0.006 update shipped a ScreenGui inside vns.rbxm (0.005 had none). We fetch the
		-- UNPINNED github `main` (VNS_URL) and parent the WHOLE vnsRoot into CoreGui, so that ScreenGui
		-- rendered as an uncloseable stuck panel (community report "Stupid tab"). We only ever need the
		-- ModuleScripts + meshes from this rbxm, never Veillith's standalone control GUI (we call
		-- smartbone:install(), never vnsApi:Run(), so nothing builds a GUI at runtime). Destroy any
		-- LayerCollector (ScreenGui/SurfaceGui/BillboardGui) -- version-agnostic, so a future upstream GUI
		-- can't resurface this either.
		for _, _d in ipairs(vnsRoot:GetDescendants()) do
			if _d:IsA("LayerCollector") then pcall(function() _d:Destroy() end) end
		end
		if vnsRoot.Parent ~= CG then pcall(function() vnsRoot.Parent = CG end) end
		if _abortDeadSmartBoneLoad() then return end
		System._sbFolder = vnsRoot

		-- Custom require - sandbox env that stubs task.synchronize/desynchronize and
		-- resolves @self/./../etc paths the way require.luau does.
		local _moduleCache = {}
		local _customRequire
		local function _resolvePath(path, base)
			if typeof(path) == "Instance" then return path end
			if type(path) ~= "string" then return nil end
			local current, remaining = nil, path
			local prefixes = {
				{ "@self", function(b) return b end },
				{ "@game", function(_) return game end },
				{ "..",    function(b) return b.Parent and b.Parent.Parent or nil end },
				{ ".",     function(b) return b.Parent end },
			}
			while true do
				local matched = false
				for _, e in ipairs(prefixes) do
					local key, fn = e[1], e[2]
					if remaining:sub(1, #key) == key
					   and (#remaining == #key or remaining:sub(#key + 1, #key + 1) == "/") then
						current = fn(base)
						remaining = (#remaining == #key) and "" or remaining:sub(#key + 2)
						matched = true; break
					end
				end
				if not matched then break end
			end
			if not current then return nil end
			for segment in string.gmatch(remaining, "[^/]+") do
				if segment == ".." then current = current and current.Parent
				else current = current and current:FindFirstChild(segment) end
				if not current then return nil end
			end
			return current
		end
		_customRequire = function(module)
			if _moduleCache[module] then return _moduleCache[module] end
			-- V4.3.496: capability-guard loadstring. Audit Pass D #2: some
			-- restricted executors (Krampus-class, some Velocity builds)
			-- expose `loadstring` as nil. Pre-fix this site called it directly,
			-- erroring at script init for any type-6 breast / VNS module load.
			-- Mirror the L23514 getgenv fallback pattern.
			local _ls = (getgenv and getgenv().loadstring) or loadstring
			if type(_ls) ~= "function" then
				error("loadstring unavailable on this executor - VNS module '"..tostring(module.Name).."' cannot be loaded.")
			end
			local chunk, lerr = _ls(module.Source, module.Name)
			if not chunk then error("loadstring failed for "..tostring(module.Name)..": "..tostring(lerr)) end
			local moduleEnv = {}
			moduleEnv.script = module
			moduleEnv.require = function(target)
				if typeof(target) == "Instance" and target:IsA("ModuleScript") then
					return _customRequire(target)
				end
				if type(target) == "string" then
					local resolved = _resolvePath(target, module)
					if not resolved then error("path resolve failed: "..tostring(target)) end
					if resolved:IsA("ModuleScript") then return _customRequire(resolved) end
					return require(resolved)
				end
				return require(target)
			end
			moduleEnv.task = setmetatable({
				synchronize = function() end,
				desynchronize = function() end,
			}, { __index = task })
			-- V4.3.339: pcall-guard getfenv/setfenv. Restricted-env executors (Volt/Xeno
			-- sandbox) can throw "upvalue out of range" or sandbox violations on these for
			-- foreign closures; outer pcall(chunk) won't catch since the throw happens here.
			pcall(function() setmetatable(moduleEnv, { __index = getfenv(chunk) }) end)
			pcall(setfenv, chunk, moduleEnv)
			local ok, result = pcall(chunk)
			if not ok then error("module "..tostring(module.Name).." errored: "..tostring(result)) end
			if module:IsA("ModuleScript") then _moduleCache[module] = result end
			return result
		end

		local vnsModule = vnsRoot:IsA("ModuleScript") and vnsRoot
			or vnsRoot:FindFirstChild("vns") or vnsRoot:FindFirstChildWhichIsA("ModuleScript")
		if not vnsModule then error("no entry ModuleScript in vns.rbxm") end

		-- env.g.vns must be set (sub-modules read this).
		do
			local genv = (getgenv and getgenv()) or _G
			pcall(function() genv.vns = vnsModule end)
		end

		-- Pre-require env to set inject flag and vns ref (mirrors what vns.lua Init does).
		local moduleAggr = vnsModule:FindFirstChild("module")
		if not moduleAggr then error("vns module aggregator missing") end
		local envMod = moduleAggr:FindFirstChild("env")
		if envMod then
			local _envSub = _customRequire(envMod)
			if _envSub and _envSub.g then
				_envSub.g.vns = vnsModule
				_envSub.g.inject = true  -- we're always in injector mode (executor)
			end
		end

		-- Patch content BEFORE smartbone:install (which calls content:loadRbxm).
		local contentMod = moduleAggr:FindFirstChild("content")
		if contentMod then
			local okC, content = pcall(_customRequire, contentMod)
			if okC and type(content) == "table" then
				content.folder = "RClothesContent/_vns"
				if type(content.checkVersion) == "function" then
					content.checkVersion = function() return true end
				end
				local _origLoadRbxm = content.loadRbxm
				content.loadRbxm = function(self, path)
					local workspacePath = self.folder .. "/" .. path
					if path:sub(1, #self.folder + 1) == self.folder .. "/" then workspacePath = path end
					if _gca and System.isfile and System.isfile(workspacePath) then
						local okU, customUrl = pcall(_gca, workspacePath)
						if okU and type(customUrl) == "string" and #customUrl > 0 then
							local okG, objects = pcall(game.GetObjects, game, customUrl)
							if okG and objects and #objects > 0 then return objects end
						end
					end
					local okG2, objects2 = pcall(game.GetObjects, game, "rbxasset://" .. workspacePath)
					if okG2 and objects2 and #objects2 > 0 then return objects2 end
					return _origLoadRbxm(self, path)
				end
			end
		end

		-- V4.3.259: silence vns/SmartBone debug prints. SmartBone's RuntimeLocal +
		-- RuntimeModule print "[vns][print][smartbone] runtime inited" once per Actor
		-- spawned (one per bone-tagged BasePart). With breast/butt/bra all in play and
		-- re-rigs on every CharacterReset, the console floods. Print is gated by
		-- `vns.config.debug` - flip it off before install() runs.
		do
			local cfgMod = vnsModule:FindFirstChild("config")
			if cfgMod then
				local okCfg, cfg = pcall(_customRequire, cfgMod)
				if okCfg and type(cfg) == "table" then
					cfg.debug = false
				end
			end
		end

		-- The KEY DIFFERENCE from disabled version: instead of calling vnsApi:Run()
		-- (which takes over character/UI setup), initialize only the physics contract.
		-- VNS 1.005 moved tag creation into Init(). Its installer catches Start errors
		-- after setting isinstalled, so call the engine directly and verify its handle.
		local sbMod = moduleAggr:FindFirstChild("smartbone")
		if not sbMod then error("vns.module.smartbone missing") end
		local smartbone = _customRequire(sbMod)
		if _abortDeadSmartBoneLoad() then return end
		if type(smartbone) ~= "table" then error("invalid vns smartbone wrapper") end
		local variableMod = vnsModule:FindFirstChild("variable")
		if not variableMod then error("vns.variable missing") end
		local variable = _customRequire(variableMod)
		local function physicsTag(value)
			if type(value) == "string" and #value > 0 then return value end
			return game:GetService("HttpService"):GenerateGUID(false)
		end
		variable.smartboneTag = physicsTag(variable.smartboneTag)
		variable.smartcolliderTag = physicsTag(variable.smartcolliderTag)
		local envSub = _customRequire(moduleAggr:FindFirstChild("env"))
		envSub.g.smartboneTag = variable.smartboneTag
		envSub.g.smartcolliderTag = variable.smartcolliderTag
		-- Older distributed VNS uses gamefolder and relative loadRbxm paths.
		local physicsFolder = variable.resourcefolder or variable.gamefolder
		if not physicsFolder then error("VNS physics resource folder missing") end
		local sb = physicsFolder:FindFirstChild("SmartBone")
		if not sb then
			local content = _customRequire(moduleAggr:FindFirstChild("content"))
			local path = "module/SmartBone.rbxm"
			if variable.resourcefolder then path = content:getPath(path) end
			sb = content:loadRbxm(path)[1]
		end
		if _abortDeadSmartBoneLoad() then return end
		if not sb then error("SmartBone asset missing") end
		sb.Parent = physicsFolder
		-- Both the old cached engine and VNS 1.005 must see tags before require.
		sb:SetAttribute("tag", variable.smartboneTag)
		sb:SetAttribute("smartboneTag", variable.smartboneTag)
		sb:SetAttribute("smartcolliderTag", variable.smartcolliderTag)
		sb:SetAttribute("inject", true)
		local engine = _customRequire(sb)
		if _abortDeadSmartBoneLoad() then return end
		local runtime = engine.Start()
		if type(runtime) ~= "table" or type(runtime.Stop) ~= "function" then
			error("SmartBone Start did not return a running handle")
		end
		if _abortDeadSmartBoneLoad() then pcall(runtime.Stop); return end
		smartbone.module = engine
		smartbone.isinstalled = true
		System._sbStop = runtime.Stop
		System._sbTag = variable.smartboneTag
		System._sbColliderTag = variable.smartcolliderTag
		System._vnsApi = nil  -- We're not running full VNS, no API table.
		System._sbApi = smartbone  -- Caller-visible: the smartbone wrapper
		return true
	end


	-- Ensure physics is ready. RigVnsModel handles RoClothes-owned body models
	-- and tagging; VNS does not install a character handler. `entries` is legacy.
	function Function.SmartBoneSetup(Data, entries)
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		Function.LoadSmartBoneApi()
	end

	-- Cache: modelPath -> loaded RBXM root (so we don't re-load every CharacterExecute)
	-- V4.3.263+264 (mobile-perf M1): LRU-capped at 4 entries on mobile (8 on desktop).
	-- Each cached model.rbxm carries 1-3 MB of MeshPart + Bone data; unbounded
	-- growth would hit ~30 MB resident on mobile after exploring a few body types.
	-- V4.3.264: collapsed prior 5 RoClothes-scope locals (cache/order/max/touch/evict)
	-- into a single _vnsLRU table - Luau caps at 200 locals per function and we hit it.
	local _vnsLRU = {
		cache = {},                                                            -- [modelPath] = root Instance
		order = {},                                                            -- array of modelPath; MRU at end
		max   = (UIS and UIS.TouchEnabled and not UIS.KeyboardEnabled) and 4 or 8,
		touch = function(self, modelPath)
			for i, p in ipairs(self.order) do
				if p == modelPath then table.remove(self.order, i); break end
			end
			table.insert(self.order, modelPath)
		end,
		evict = function(self)
			while #self.order > self.max do
				local lru = table.remove(self.order, 1)
				local cached = self.cache[lru]
				self.cache[lru] = nil
				if cached and cached.Parent then pcall(function() cached:Destroy() end) end
			end
		end,
	}
	-- V4.3.529 Fix 1: helper to detect ghost-cached rbxm roots. The engine's
	-- `game:GetObjects` can return a valid-looking Instance that has zero
	-- MeshPart descendants - happens when the cached load was partial / corrupted /
	-- the underlying file was mid-write during install. RigVnsModel downstream
	-- then fails with "loaded but contains no MeshParts" and the user sees no
	-- breast / butt / etc. mesh, only an empty fallback. Treat any root with no
	-- MeshPart descendant as a cache poisoning hit.
	local function _hasUsableMeshes(root)
		if not root then return false end
		for _, p in ipairs(root:GetDescendants()) do
			if p:IsA("MeshPart") then return true end
		end
		return false
	end

	-- V4.3.531 Fix 10: isolated PRNG + monotonic counter for cache-bust fresh-path naming.
	-- Avoids mutating Luau's global `math.random` state and collision risk.
	local _vnsCBRng
	local _vnsCBCounter = 0
	local function _getVnsModel(modelPath)
		local cached = _vnsLRU.cache[modelPath]
		-- V4.3.529 Fix 1: re-validate cached root has MeshParts. If the cached
		-- entry is a ghost (engine returned an empty Instance on the first load),
		-- evict it so the fresh-path bust below can recover. Without this the LRU
		-- protects the poisoned result for the whole session.
		if cached and cached.Parent and _hasUsableMeshes(cached) then
			_vnsLRU:touch(modelPath); return cached
		elseif cached then
			-- Drop the ghost from the LRU so we re-attempt the load.
			pcall(function() if cached.Parent then cached:Destroy() end end)
			_vnsLRU.cache[modelPath] = nil
			for i, p in ipairs(_vnsLRU.order) do
				if p == modelPath then table.remove(_vnsLRU.order, i); break end
			end
			_diagPublicCall("vns.ghost_cache_evicted", { path = modelPath })
		end
		local objects
		-- V4.3.217: workspace-first via getcustomasset (since the auto-installer
		-- writes _vns/ to the executor workspace, not the Roblox content folder).
		-- Fall back to rbxasset:// for users still using the legacy install path.
		local _gca = getcustomasset or getsynasset
		if _gca and System.isfile and System.isfile(modelPath) then
			local okU, customUrl = pcall(_gca, modelPath)
			if okU and type(customUrl) == "string" and #customUrl > 0 then
				pcall(function() objects = game:GetObjects(customUrl) end)
			end
		end
		if not objects or #objects == 0 then
			pcall(function() objects = game:GetObjects("rbxasset://" .. modelPath) end)
		end
		-- V4.3.528 Fix 1 + V4.3.529 Fix 1: Roblox's `game:GetObjects(customUrl)` caches
		-- the result per-URL for the entire process lifetime. If the first attempt
		-- returned empty OR returned a valid-looking Instance with no MeshPart
		-- descendants (ghost cache from a file-mid-write window during install, a
		-- partial customUrl response, or an executor hiccup), the cached miss/ghost
		-- survives EVEN AFTER Redownload writes a clean file to disk. The engine
		-- never re-reads the URL until process restart. Community reports 2026-05-30
		-- (#BloodyJuice, SHIRO) + follow-up 2026-06-02: butt and breasts SmartBone
		-- meshes missing across V4.3.487 and latest; arm SmartBone meshes work fine
		-- (those rbxms loaded cleanly first try). V4.3.528 only caught the empty
		-- case; V4.3.529 also catches the ghost case where objects[1] exists but
		-- contains zero MeshParts.
		local function _objectsHaveUsableContent(objs)
			if not objs or #objs == 0 then return false end
			for _, o in ipairs(objs) do
				if _hasUsableMeshes(o) then return true end
			end
			return false
		end
		if not _objectsHaveUsableContent(objects) and _gca and System.isfile and System.isfile(modelPath)
				and readfile and writefile then
			local _wasEmpty = (not objects or #objects == 0)
			_diagPublicCall(_wasEmpty and "vns.load_empty_initial" or "vns.load_ghost_initial",
				{ path = modelPath })
			local _okR, _bytes = pcall(readfile, modelPath)
			if _okR and type(_bytes) == "string" and #_bytes > 0 then
				-- V4.3.531 Fix 10: replaced `math.random` with an isolated Random.new() instance
				-- + monotonic suffix. `math.random` mutates Luau's global PRNG state shared with
				-- every other caller in the file. Plus the bare random value was a collision risk
				-- if two concurrent _getVnsModel calls landed in the same RNG state.
				_vnsCBRng = _vnsCBRng or Random.new()
				_vnsCBCounter = (_vnsCBCounter or 0) + 1
				local _freshPath = modelPath .. ".cb" .. tostring(_vnsCBRng:NextInteger(1, 1000000000)) .. "_" .. tostring(_vnsCBCounter) .. ".rbxm"
				local _okW = pcall(writefile, _freshPath, _bytes)
				if _okW then
					local _okU2, _freshUrl = pcall(_gca, _freshPath)
					if _okU2 and type(_freshUrl) == "string" and #_freshUrl > 0 then
						local _freshObjects
						pcall(function() _freshObjects = game:GetObjects(_freshUrl) end)
						-- Only replace `objects` if the fresh-path load produced usable content.
						-- Avoids the case where the fresh load itself comes back empty/ghost.
						if _objectsHaveUsableContent(_freshObjects) then
							objects = _freshObjects
						end
					end
					if delfile then pcall(delfile, _freshPath) end
				end
			end
			if _objectsHaveUsableContent(objects) then
				_diagPublicCall("vns.load_recovered_via_freshpath",
					{ path = modelPath, was_ghost = not _wasEmpty })
			else
				_diagPublicCall("vns.load_empty_retry_failed",
					{ path = modelPath, was_ghost = not _wasEmpty })
			end
		end
		-- V4.3.544 Fix 1: DeserializeInstancesAsync fallback for executors
		-- where game:GetObjects(customasset URL) returns empty for .rbxm files
		-- (Xeno-class executors with asymmetric customasset/GetObjects support).
		-- User report 2026-06-07: "every smartbone type mesh dont work on
		-- certain executor, like xeno, as for the smartbone physics, i do not
		-- know, because the mesh does not display at all." Empirical proof:
		-- C:\Users\User\AppData\Local\Xeno\workspace\RClothesContent\_vns\
		-- has the .rbxm + .mesh files installed (3.7 MB) but they don't
		-- display - confirms install works but engine load fails. The
		-- existing fresh-path cache-bust (L11884-L11920) re-uses the same
		-- broken _gca → GetObjects chain, so it can't recover this case.
		-- Same pattern as L11591 HTTP-fetch fallback for the VNS framework
		-- itself. Requires SerializationService + buffer.fromstring - both
		-- pcall-guarded so absent APIs (older Roblox builds, restricted
		-- executors) degrade silently to existing behavior. On success the
		-- deserialized objects table is consumed identically to GetObjects'
		-- output by the downstream code at L11933+ (single-Model unwrap or
		-- multi-Model _VNS_MultiRoot folder).
		if not _objectsHaveUsableContent(objects) and readfile and buffer and buffer.fromstring then
			local _okR2, _bytes2 = pcall(readfile, modelPath)
			if _okR2 and type(_bytes2) == "string" and #_bytes2 > 0 then
				local _okSS, _SS = pcall(function() return game:GetService("SerializationService") end)
				if _okSS and _SS then
					local _okBuf, _buf = pcall(buffer.fromstring, _bytes2)
					if _okBuf and _buf then
						local _okD, _deserialized = pcall(function()
							return _SS:DeserializeInstancesAsync(_buf)
						end)
						if _okD and type(_deserialized) == "table"
							and _objectsHaveUsableContent(_deserialized)
						then
							objects = _deserialized
							_diagPublicCall("vns.load_recovered_via_deserialize",
								{ path = modelPath })
						else
							-- V4.3.545 Fix 2 (F3.3): branch the diag by failure
							-- mode. Pre-fix the single payload used tostring on
							-- _deserialized for ALL failure paths - useful when
							-- _okD=false (it's an error string) but useless when
							-- _okD=true with non-table or empty-table result
							-- (tostring(table) → "table: 0x..."). Per-executor
							-- correlation in the krulhub.dev dashboard needs the
							-- distinct modes ("throw" vs "not_table" vs
							-- "empty_table") to identify whether the issue is
							-- SerializationService throwing, the engine returning
							-- garbage, or the file being a ghost. Broad-scan
							-- workflow waq6vz1ri verifier confirmed F3.3 as the
							-- highest-leverage telemetry fix for unblocking
							-- future Xeno-class executor work.
							local _failMode
							local _sample = ""
							if not _okD then
								_failMode = "throw"
								_sample = tostring(_deserialized):sub(1, 80)
							elseif type(_deserialized) ~= "table" then
								_failMode = "not_table"
								_sample = tostring(_deserialized):sub(1, 80)
							else
								_failMode = "empty_table"
								_sample = tostring(#_deserialized)
							end
							_diagPublicCall("vns.deserialize_failed",
								{ path = modelPath, mode = _failMode, sample = _sample })
						end
					end
				else
					_diagPublicCall("vns.serialization_service_unavailable",
						{ path = modelPath })
				end
			end
		end
		-- V4.3.544 Fix 2 (Fix C from synthesis): surface terminal failure
		-- with capability snapshot. Pre-fix this returned nil silently,
		-- leaving "mesh does not display" with no actionable user signal
		-- and no production telemetry - the existing per-attempt diag
		-- events (vns.load_empty_initial / load_empty_retry_failed / etc.)
		-- don't capture the WHOLE chain's exhaustion. New
		-- vns.load_terminal_failure event carries which APIs were available
		-- so we can correlate failure modes per-executor in the dashboard.
		-- Plus a one-shot warn via diagOnce so the user knows to screenshot
		-- + report instead of staring at a non-displaying mesh wondering.
		if not objects or #objects == 0 then
			_diagPublicCall("vns.load_terminal_failure", {
				path = modelPath,
				gca_present = (_gca ~= nil),
				had_readfile = (readfile ~= nil),
				had_writefile = (writefile ~= nil),
				had_buffer = (buffer ~= nil and buffer.fromstring ~= nil),
			})
			-- V4.3.544 post-verify fix (verification workflow wf_8a194d53-c2e
			-- found both bugs): (1) Function.diagOnce takes a STRING per L5691
			-- working example + _diagRecordOnce string-type-check at L326, NOT
			-- a {api=...} table - table form silently no-ops. Use string. (2)
			-- diagOnce only dedupes the telemetry event; the warn() itself
			-- has no one-shot gate, so on a Xeno user it spams once per failed
			-- body-part mesh (3-6 per character per re-execute). Gate the
			-- WARN explicitly via a module-level System flag so only the FIRST
			-- failing mesh path in a session triggers the visible message;
			-- subsequent failures still emit the terminal-failure diag (one
			-- per call, useful for dashboard correlation) but don't repeat
			-- the user-facing warn.
			Function.diagOnce("vns.terminal_warn")
			if not System._vnsTerminalWarned then
				System._vnsTerminalWarned = true
				warn("[RoClothes] VNS model failed to load: " .. tostring(modelPath) ..
					" - all 4 attempts exhausted (workspace customasset+GetObjects, " ..
					"rbxasset:// fallback, fresh-path cache-bust, DeserializeInstancesAsync). " ..
					"Likely Xeno-class executor with asymmetric customasset/GetObjects " ..
					"support and no SerializationService. Screenshot Output + report at " ..
					"discord.gg/SBUuYsnShf. (Subsequent mesh load failures suppressed; " ..
					"check the telemetry dashboard for vns.load_terminal_failure events.)")
			end
			return nil
		end
		-- V4.3.379: handle multi-Model rbxms. Pre-fix objects[1] discarded any
		-- siblings. Wrap multi-object rbxms in a fresh Folder so RigVnsModel's
		-- subModelName by-FindFirstChild lookup can resolve any variant.
		-- Single-object rbxms keep the legacy single-root return.
		local root
		if #objects > 1 then
			root = Instance.new("Folder")
			root.Name = "_VNS_MultiRoot"
			for _, _o in ipairs(objects) do _o.Parent = root end
		else
			root = objects[1]
		end
		-- V4.3.546: VNS asset URL rewrite walk. The .rbxm files have baked-in
		-- `rbxasset://_vns/...` references on MeshPart.MeshId, SpecialMesh
		-- .MeshId/.TextureId, SurfaceAppearance.ColorMap/.NormalMap/.MetalnessMap
		-- /.RoughnessMap, Decal/Texture.Texture, ImageLabel/ImageButton.Image.
		-- Those resolve to Roblox's content folder root, but our install layout
		-- is `<workspace>/RClothesContent/_vns/...` per the V4.3.218 prefix
		-- bridge. Pre-V4.3.546, only the cloneRoot-side Function.ApplyAssets
		-- walked descendants and rewrote - and it OMITTED SurfaceAppearance
		-- entirely (gap confirmed by recon workflow wf_c0b53469). Plus the
		-- V4.3.308 MeshPart rebuild at L12316 SKIPS skinned MeshParts, which
		-- means SmartBone breast meshes (leftb/rightb skinned) fall back to
		-- ApplyAssets's pcall MeshId write, which Xeno's tightened skinned-
		-- MeshPart restrictions silently reject (the L12376-12378 comment
		-- acknowledges this exact failure mode).
		--
		-- Empirical evidence: Xeno user 2026-06-07 reported
		--   "MeshContentProvider failed to process rbxasset://_vns/model/breast/1/leftb.mesh because 'could not fetch'"
		--   "Failed to load ... Mesh.SurfaceAppearance. PBR textures may not be visible"
		-- after VNS framework loaded successfully ("smartbone2 v0.5.2 starting").
		-- So the model load works, but Roblox's renderer can't resolve the
		-- baked URLs against the executor workspace.
		--
		-- Fix: walk root descendants ONCE before LRU cache write; rewrite every
		-- baked `rbxasset://_vns/...` to `_gca(\"RClothesContent/_vns/...\")` via
		-- Content.fromUri when available, plain string fallback. Per-property
		-- pcall-guarded. Gated on file-exists check (don't overwrite a working
		-- URL with a missing-file one). Telemetry counter per load (not per-
		-- property - would flood the ring buffer).
		--
		-- Insertion point chosen so single walk covers both single-root and
		-- _VNS_MultiRoot branches, and rewritten root lands in cache (every LRU
		-- hit gets pre-rewritten root, no per-hit re-walk).
		-- V4.3.547 diagnostic enhancement: V4.3.546's walk was confirmed to ship
		-- but Xeno user's 22:10:19 Output screenshot showed MeshContentProvider
		-- failures still firing for the SAME 4 mesh files. SurfaceAppearance
		-- errors DID disappear (so SA rewrite worked) but MeshPart.MeshId rewrites
		-- aren't sticking. We need ground truth: per-class counters, sample
		-- capture of silent_reject cases, an inline Output print so user can
		-- screenshot results without digging into diagnostics.log. Also: Content-
		-- typed read handling as a defensive cover (probably not the bug since
		-- the existing V4.3.308 GetAsset path reads MeshId-as-string successfully
		-- on non-skinned MeshParts, but cheap insurance).
		if not _gca then
			_diagPublicCall("vns.url_rewrite_skipped_no_gca", { path = modelPath })
		else
			local _okEnv, _env = pcall(getfenv)
			local _ContentApi = (_okEnv and rawget(_env, "Content")) or _G.Content
			-- Per-class breakdown. The pre-V4.3.547 single counters couldn't
			-- distinguish "MeshPart writes silent-rejected" from "SurfaceAppearance
			-- writes silent-rejected" - debugging the Xeno case requires that
			-- separation. Each class tracks rewrites/silent_reject/skipped_nofile
			-- /content_read/string_read independently.
			local _stats = {
				MeshPart            = {rw=0,sr=0,nf=0,ct=0,st=0,ot=0,err=0,seen=0},
				SpecialMesh         = {rw=0,sr=0,nf=0,ct=0,st=0,ot=0,err=0,seen=0},
				SurfaceAppearance   = {rw=0,sr=0,nf=0,ct=0,st=0,ot=0,err=0,seen=0},
				Decal               = {rw=0,sr=0,nf=0,ct=0,st=0,ot=0,err=0,seen=0},
				Texture             = {rw=0,sr=0,nf=0,ct=0,st=0,ot=0,err=0,seen=0},
				ImageLabel          = {rw=0,sr=0,nf=0,ct=0,st=0,ot=0,err=0,seen=0},
				ImageButton         = {rw=0,sr=0,nf=0,ct=0,st=0,ot=0,err=0,seen=0},
			}
			local _samples_sr   = {}  -- silent-reject samples: {class, prop, before, after, target, isSkinned}
			local _samples_nf   = {}  -- not-found samples: {class, prop, fsPath, orig}
			local _samples_err  = {}  -- error samples: {class, prop, errMsg}
			local function _normalizeRead(_cur)
				if type(_cur) == "string" then return _cur, "string" end
				if typeof and typeof(_cur) == "Content" then
					local _okUri, _uri = pcall(function() return _cur.Uri end)
					if _okUri and type(_uri) == "string" then
						return _uri, "content"
					end
					return nil, "content"  -- Content with no readable .Uri
				end
				return nil, type(_cur)
			end
			-- V4.3.548: V4.3.547's Xeno data was decisive AND surprising:
			--   model/breast/1/model.rbxm seen=16 rw=0 sr=0 nf=0 ct=0 st=16 err=4
			--   model/torso/1/model.rbxm  seen=2  rw=0 sr=0 nf=0 ct=0 st=2  err=1
			--   model/arm/1/model.rbxm    seen=4  rw=0 sr=0 nf=0 ct=0 st=4  err=0  ← arm works
			--   model/leg/1/model.rbxm    seen=4  rw=0 sr=0 nf=0 ct=0 st=4  err=2
			--   model/butt/1/model.rbxm   seen=4  rw=0 sr=0 nf=0 ct=0 st=4  err=2
			-- Refuted all 3 V4.3.547 hypotheses (Content-typed reads, isfile false,
			-- silent reject). New finding: gca or write THROWS for every VNS-pattern
			-- property. Arm has zero VNS-pattern URLs (uses Roblox catalog rbxassetid
			-- assets) so it doesn't hit the err path - that's why it works.
			-- V4.3.547's _samples_err only goes to diag log (user can't easily share).
			-- V4.3.548 extends: (1) capture the actual write-pcall error message
			-- instead of just "pcall_write_threw" sentinel - pcall returns false +
			-- error string in the second return, so capture and surface it; (2) include
			-- target path in error samples so we can see exactly what was passed to
			-- gca / written to the property; (3) bump truncation 40→100 chars to fit
			-- typical Xeno error messages; (4) print the first error sample inline
			-- in Output when _totals.err > 0 so user can screenshot without diag log.
			-- This is still diagnostic-only - no behavioral fix until we know whether
			-- it's gca throwing or the property write throwing.
			local function _rewriteAssetProp(inst, propName)
				local _cls = inst.ClassName
				local _s = _stats[_cls]
				if not _s then return end
				_s.seen = _s.seen + 1
				local _okRead, _cur = pcall(function() return inst[propName] end)
				if not _okRead then
					_s.err = _s.err + 1
					if #_samples_err < 3 then
						table.insert(_samples_err, {
							class = _cls, prop = propName,
							err = tostring(_cur):sub(1, 100), phase = "read",
						})
					end
					return
				end
				local _curStr, _curKind = _normalizeRead(_cur)
				if _curKind == "string" then
					_s.st = _s.st + 1
				elseif _curKind == "content" then
					_s.ct = _s.ct + 1
				else
					_s.ot = _s.ot + 1
				end
				if not _curStr or _curStr == "" then return end
				local _rel = _curStr:match("^rbxasset://_vns/(.+)$")
				if not _rel then return end
				local _fsPath = "RClothesContent/_vns/" .. _rel
				if not (System.isfile and System.isfile(_fsPath)) then
					_s.nf = _s.nf + 1
					if #_samples_nf < 3 then
						table.insert(_samples_nf, {
							class = _cls, prop = propName,
							orig = _curStr:sub(1, 70),
							target = _fsPath:sub(1, 70),
						})
					end
					return
				end
				local _okUrl, _url = pcall(_gca, _fsPath)
				if not _okUrl or type(_url) ~= "string" or _url == "" then
					_s.err = _s.err + 1
					if #_samples_err < 3 then
						table.insert(_samples_err, {
							class = _cls, prop = propName,
							err = tostring(_url):sub(1, 100), phase = "gca",
							target = _fsPath:sub(1, 80),
						})
					end
					return
				end
				-- V4.3.548: capture write-pcall error string. pcall returns
				-- (false, errMsg) on throw; old V4.3.547 code just discarded errMsg
				-- and lost the diagnostic signal.
				local _wrote, _writeErrC, _writeErrS = false, nil, nil
				if _ContentApi and type(_ContentApi.fromUri) == "function" then
					local _okC, _content = pcall(_ContentApi.fromUri, _url)
					if _okC and _content ~= nil then
						_wrote, _writeErrC = pcall(function() inst[propName] = _content end)
					end
				end
				if not _wrote then
					_wrote, _writeErrS = pcall(function() inst[propName] = _url end)
				end
				if _wrote then
					local _okPost, _post = pcall(function() return inst[propName] end)
					local _postStr = _okPost and _normalizeRead(_post) or nil
					if _okPost and type(_postStr) == "string" and _postStr ~= _curStr then
						_s.rw = _s.rw + 1
					else
						_s.sr = _s.sr + 1
						if #_samples_sr < 3 then
							local _isSkinned = nil
							if _cls == "MeshPart" then
								pcall(function() _isSkinned = inst.HasSkinnedMesh end)
							end
							table.insert(_samples_sr, {
								class = _cls, prop = propName,
								before = _curStr:sub(1, 70),
								after = (_postStr or "<nil>"):sub(1, 70),
								target = _url:sub(1, 70),
								skinned = _isSkinned,
							})
						end
					end
				else
					_s.err = _s.err + 1
					if #_samples_err < 3 then
						local _isSkinned = nil
						if _cls == "MeshPart" then
							pcall(function() _isSkinned = inst.HasSkinnedMesh end)
						end
						local _bestErr = _writeErrS or _writeErrC or "<no_error_captured>"
						table.insert(_samples_err, {
							class = _cls, prop = propName,
							err = tostring(_bestErr):sub(1, 100), phase = "write",
							target = _url:sub(1, 80),
							skinned = _isSkinned,
						})
					end
				end
			end
			local _okWalk, _walkErr = pcall(function()
				for _, _d in ipairs(root:GetDescendants()) do
					if _d:IsA("MeshPart") then
						_rewriteAssetProp(_d, "MeshId")
						_rewriteAssetProp(_d, "TextureID")
					elseif _d:IsA("SpecialMesh") then
						_rewriteAssetProp(_d, "MeshId")
						_rewriteAssetProp(_d, "TextureId")
					elseif _d:IsA("SurfaceAppearance") then
						_rewriteAssetProp(_d, "ColorMap")
						_rewriteAssetProp(_d, "NormalMap")
						_rewriteAssetProp(_d, "MetalnessMap")
						_rewriteAssetProp(_d, "RoughnessMap")
					elseif _d:IsA("Decal") or _d:IsA("Texture") then
						_rewriteAssetProp(_d, "Texture")
					elseif _d:IsA("ImageLabel") or _d:IsA("ImageButton") then
						_rewriteAssetProp(_d, "Image")
					end
				end
			end)
			-- V4.3.547: roll up per-class stats into totals + per-class breakdown
			-- in the diag payload. Also emit a one-line Output print so the user
			-- can screenshot it alongside the MeshContentProvider error and we
			-- can correlate live without waiting for the diagnostics.log share.
			local _totals = {rw=0, sr=0, nf=0, ct=0, st=0, ot=0, err=0, seen=0}
			for _cls, _s in pairs(_stats) do
				for _k, _v in pairs(_s) do _totals[_k] = _totals[_k] + _v end
			end
			-- Console summary: visible in Roblox Output, prefixed for grep.
			-- Only print if the walk actually saw asset-property reads (avoids
			-- noise on rbxms with zero relevant descendants). For multi-load
			-- characters, ~6-10 lines per session. Tolerable.
			if _totals.seen > 0 then
				local _shortPath = modelPath:gsub("^RClothesContent/_vns/", "")
				print(string.format(
					"[RoClothes][vns.rewrite] %s seen=%d rw=%d sr=%d nf=%d ct=%d st=%d err=%d",
					_shortPath, _totals.seen, _totals.rw, _totals.sr,
					_totals.nf, _totals.ct, _totals.st, _totals.err))
				-- V4.3.553: stripped V4.3.547/548 per-class + sample-err + sample-sr
				-- inline prints. They were diagnostic for the V4.3.546→552 debugging
				-- arc and are no longer needed. _diagPublicCall payload below still
				-- carries full sample data for the diagnostics.log file + dashboard.
			end
			-- V4.3.549: CapSec detection. V4.3.548 confirmed Xeno's error is
			-- "The current thread cannot write 'MeshId' (lacking capability
			-- NotAccessible)". This is Roblox's capability-based security
			-- denying MeshPart.MeshId writes from script context. Once we see
			-- this error even once, we know the executor enforces CapSec on
			-- MeshId - set a session-scoped flag so the V4.3.308 block in
			-- RigVnsModel can route AROUND the locked write by rebuilding
			-- skinned MeshParts via IS:CreateMeshPartAsync (engine-API
			-- construction-time MeshId set, not script write, bypasses CapSec).
			-- Pre-V4.3.549 V4.3.382 always skipped skinned for skinning-loss
			-- concern - that's correct for executors where MeshId writes work,
			-- but leaves Xeno users with invisible SmartBone meshes. Gating on
			-- this flag lets us help Xeno without regressing the majority.
			for _, _smp in ipairs(_samples_err) do
				if _smp.phase == "write" and _smp.class == "MeshPart"
				   and type(_smp.err) == "string"
				   and (_smp.err:find("NotAccessible", 1, true)
				        or _smp.err:find("lacking capability", 1, true)) then
					if not System._vnsCapsecMeshIdLocked then
						System._vnsCapsecMeshIdLocked = true
						print("[RoClothes][vns.rewrite] CapSec MeshId-locked executor detected; " ..
							"V4.3.308 block will rebuild skinned MeshParts via CreateMeshPartAsync.")
						_diagPublicCall("vns.capsec_meshid_detected", {
							first_model = modelPath,
							err_snippet = _smp.err:sub(1, 80),
						})
					end
					break
				end
			end
			_diagPublicCall("vns.url_rewrite", {
				path = modelPath,
				totals = _totals,
				stats = _stats,
				samples_sr = _samples_sr,
				samples_nf = _samples_nf,
				samples_err = _samples_err,
				walk_ok = _okWalk,
				walk_err = (not _okWalk) and tostring(_walkErr):sub(1, 80) or nil,
				capsec_locked = System._vnsCapsecMeshIdLocked == true,
			})
		end
		-- Park it in a hidden ReplicatedStorage child so it persists for re-reads.
		local RS = game:GetService("ReplicatedStorage")
		local holder = RS:FindFirstChild("_RCVnsModelCache") or Instance.new("Folder")
		holder.Name = "_RCVnsModelCache"
		holder.Parent = RS
		root.Parent = holder
		_vnsLRU.cache[modelPath] = root
		_vnsLRU:touch(modelPath)   -- V4.3.263+264 M1: register in LRU order
		_vnsLRU:evict()            -- V4.3.263+264 M1: destroy over-cap entries
		return root
	end

	-- V4.3.216: ApplyVnsLayout disabled - chain extraction from model.rbxm produced
	-- wrong CFrames for all SB body types. V4.3.217 supersedes both this AND the
	-- Function.Weld pathway for SB types: see Function.RigVnsModel below for the
	-- replacement architecture (clone the rbxm Model directly, resolve character
	-- attribute, parent into character). Kept as a no-op for legacy callsites.
	function Function.ApplyVnsLayout(part, modelPath, partName, character)
		return
	end

	-- V4.3.217: clean SmartBone body-part renderer. Replaces Function.Weld + (see Changelog for full rationale)
	-- V4.3.378: optional subModelName picks a specific top-level Model child from
	function Function.RigVnsModel(modelPath, character, requestID, subModelName, dataKey)
		if not character then return nil, {} end

		-- V4.3.220+232: cascade-rig dedup. Cache key MUST match the cloneRoot.Name (see Changelog for full rationale)
		-- V4.3.232: dedup no longer EARLY-returns. We still need to run the bone-tag
		-- V4.3.252: include bra variant in cache name. Pre-fix, breastclothes/1 and
		local _cacheName
		do
			local _bcVar = modelPath:match("breastclothes/(%d+)")
			if _bcVar then
				_cacheName = "RC_VNS_breastclothes_" .. _bcVar
			else
				_cacheName = "RC_VNS_" .. (modelPath:match("model/([^/]+)") or "model")
			end
			-- V4.3.378: when subModelName is given, the cloneRoot cache must be
			-- per-variant so cycling regular ↔ smaller doesn't dedup-hit. Suffix
			-- a sanitized variant token onto the cache name. Pairs with the
			-- _RC_VNS_SourcePath attribute check below for variant integrity.
			if subModelName and subModelName ~= "" then
				_cacheName = _cacheName .. "_v_" .. (subModelName:gsub("[^%w]", "_"))
			end
		end
		local cloneRoot
		local _vnsOwnedClone = false
		local _vnsOwnedCollider
		do
			local existing = character:FindFirstChild(_cacheName)
			if existing then
				-- V4.3.378: dedup-check is variant-aware. Pre-fix, multiple variants of (see Changelog for full rationale)
				local _existingPath
				pcall(function() _existingPath = existing:GetAttribute("_RC_VNS_SourcePath") end)
				if _existingPath == nil or _existingPath == modelPath then
					local _hasMesh = false
					for _, p in ipairs(existing:GetDescendants()) do
						if p:IsA("MeshPart") then _hasMesh = true; break end
					end
					if _hasMesh then cloneRoot = existing end
				end
			end
		end
		-- V4.5.24 Fix: asset/model work below can yield long enough for CharacterReset
		-- to invalidate this execute. Do not let a stale request destroy a current rig or
		-- parent its private clone after the reset has completed.
		local function _vnsRequestIsStale()
			if not requestID or not dataKey then return false end
			local _pd = PlayerData[dataKey]
			return not _pd or _pd.LastRequestID ~= requestID
		end
		local function _abortStaleRig()
			if not _vnsRequestIsStale() then return false end
			if _vnsOwnedClone and cloneRoot then pcall(function() cloneRoot:Destroy() end) end
			if _vnsOwnedCollider then pcall(function() _vnsOwnedCollider:Destroy() end) end
			return true
		end

		-- V4.3.219: ensure SmartBone runtime is loaded before we parent bones into
		-- the character. SmartBone auto-detects bones via DescendantsAdded scan.
		-- Idempotent: noop after first successful load.
		pcall(Function.LoadSmartBoneApi)
		if _abortStaleRig() then return nil, {} end
		-- V4.3.258: defensive - if pcall yield-propagation broke (some executor (see Changelog for full rationale)
		-- V4.3.261: skip the wait entirely if the load already failed permanently
		-- V4.3.429: cap dropped 2s → 0.5s. On cold-boot first-character path this
		-- busy-wait was a noticeable stall per CharacterExecute when SmartBone API
		-- hadn't loaded yet. 0.5s is enough for the typical executor; if SB API
		-- isn't ready by then, the bone-tag block is a no-op without `_sbTag` and
		-- will succeed on the next CharacterExecute (cached). Body still renders.
		if not System._sbTag and not System._vnsLoadFailed then
			local _t = 0
			repeat task.wait(0.05); _t += 0.05 until System._sbTag or _t > 0.5
		end
		if _abortStaleRig() then return nil, {} end

		-- _realChar resolved once, used by both the fresh-clone weld block and the
		-- collider rigging block below.
		local _realChar = nil
		do
			local _player = game:GetService("Players").LocalPlayer
			if _player and character.Name == _player.Name and _player.Character then
				_realChar = _player.Character
			end
		end

		-- V4.3.232: skip the rbxm clone path entirely if we have a cached cloneRoot
		-- from the dedup check above. Bone-tag + collider blocks below ALWAYS run.
		if not cloneRoot then
			local rbxmRoot = _getVnsModel(modelPath)
			if _abortStaleRig() then return nil, {} end
			if not rbxmRoot then
				warn("[RoClothes] RigVnsModel: failed to load " .. tostring(modelPath))
				return nil, {}
			end

			-- The rbxm root is a ModuleScript. The actual content is either:
			--   (a) a Model child (breast/butt/leg/torso/breastclothes/vagina pattern), OR
			--   (b) MeshParts directly as children of the ModuleScript (arm pattern)
			-- V4.3.378: if subModelName is given, pick that specific child by name.
			-- V4.3.381: also accept Folder as sourceContainer (was Model-only) - some
			-- rbxms ship Folder-rooted variants. When a Folder is matched we still
			-- need cloneRoot to be a Model (downstream code expects `cloneRoot:AddTag`
			-- etc.); unwrap the Folder's contents into a fresh Model.
			local sourceContainer
			if subModelName and subModelName ~= "" then
				sourceContainer = rbxmRoot:FindFirstChild(subModelName)
				if sourceContainer and not (sourceContainer:IsA("Model") or sourceContainer:IsA("Folder")) then
					sourceContainer = nil
				end
				-- V4.3.421: fail closed when an explicit variant is requested but missing.
				-- Pre-fix the silent fallback to `rbxmRoot:FindFirstChildOfClass("Model")`
				-- below would pick the FIRST model in file order and cache it under the
				-- requested-variant cache key (L8127 includes subModelName suffix). User
				-- cycling variant A → B → A then keeps getting variant A under variant B's
				-- key until re-execute. No warn fired. Caught by bug-hunter audit
				-- 2026-05-14 (HIGH/HIGH). Latent currently - no production callsite passes
				-- subModelName after V4.3.414's Type 7 deprecation - but the parameter
				-- exists and any future reintroduction would silently misbehave.
				if not sourceContainer then
					warn(string.format("[RoClothes] RigVnsModel: subModelName %q not found in %s - refusing to fall back (would poison variant cache).",
						tostring(subModelName), tostring(modelPath)))
					return nil, {}
				end
			end
			if not sourceContainer then
				sourceContainer = rbxmRoot:FindFirstChildOfClass("Model")
			end
			_vnsOwnedClone = true
			if sourceContainer then
				if sourceContainer:IsA("Model") then
					cloneRoot = sourceContainer:Clone()
				else
					-- Folder source: unwrap its children into a fresh Model so the
					-- rest of the pipeline (tagging, motor resolution, MeshPart
					-- replacement, etc.) treats cloneRoot consistently.
					cloneRoot = Instance.new("Model")
					local _sc = sourceContainer:Clone()
					for _, _c in ipairs(_sc:GetChildren()) do
						_c.Parent = cloneRoot
					end
					_sc:Destroy()
				end
			else
				cloneRoot = Instance.new("Model")
				for _, c in ipairs(rbxmRoot:GetChildren()) do
					if c:IsA("BasePart") or c:IsA("Folder") then
						c:Clone().Parent = cloneRoot
					end
				end
			end
			cloneRoot.Name = _cacheName  -- matches the dedup lookup name

		-- Resolve {character}.<name> attributes on Motor6Ds/Welds to the actual
		-- character body parts. V4.3.224: prefer the REAL character body part over
		-- the M2 shadow placeholder. V4.3.231: pre-position the welded Part1 BEFORE
		-- setting Part0 (mirrors VNS's modelWeld at vns_module_rig.lua L168).
		-- V4.3.237: deep-search helper for SB-clothes anchors. breastclothes references
		-- parts that live INSIDE a sibling VNS model (e.g. `{character}.Left Breast`
		-- resolves to the Left Breast MeshPart inside RC_VNS_breast, not on character).
		-- If the direct/R15 lookup misses, fall back to any RC_VNS_* model descendant.
		local function _findInSiblingVns(host, partName)
			if not host then return nil end
			for _, sib in ipairs(host:GetChildren()) do
				if sib:IsA("Model") and sib.Name:sub(1, 7) == "RC_VNS_" and sib ~= cloneRoot then
					local found = sib:FindFirstChild(partName, true)
					if found and found:IsA("BasePart") then return found end
				end
			end
			return nil
		end
		-- V4.3.237: per-VNS-source `modelWeld` iterates ALL string attributes on each
		-- weld, not just Part0. The breastclothes rbxm may anchor via Part1 or even a
		-- custom attribute name. Walk every attribute whose value matches `{character}.X`.
		local _r15 = {
			["Torso"] = "UpperTorso",
			["Left Arm"] = "LeftUpperArm",
			["Right Arm"] = "RightUpperArm",
			["Left Leg"] = "LeftUpperLeg",
			["Right Leg"] = "RightUpperLeg",
		}
		-- V4.3.376: gate _findInSiblingVns to breastclothes only. (see Changelog for full rationale)
		local _allowSiblingFallback = modelPath:find("breastclothes") ~= nil
		local function _resolveCharPart(name)
			local target = (_realChar and _realChar:FindFirstChild(name))
				or character:FindFirstChild(name)
			if not target then
				local _alt = _r15[name]
				if _alt then
					target = (_realChar and _realChar:FindFirstChild(_alt))
						or character:FindFirstChild(_alt)
				end
			end
			if not target and _allowSiblingFallback then
				target = _findInSiblingVns(character, name)
					or _findInSiblingVns(_realChar, name)
			end
			return target
		end
		-- V4.3.239: VNS holder-path resolver. Per V4.3.238 BC-DUMP, the breastclothes (see Changelog for full rationale)
		local _holderToRC = {
			breast1 = "RC_VNS_breast",
			butt1   = "RC_VNS_butt",
			arm1    = "RC_VNS_arm",
			leg1    = "RC_VNS_leg",
			torso1  = "RC_VNS_torso",
			breastclothes1 = "RC_VNS_breastclothes",
			collider = "RC_VNS_collider",
		}
		local function _resolveHolderPath(path)
			local vnsName, rest = path:match("^{holder}%.([^%.]+)%.(.+)$")
			if not vnsName then return nil end
			rest = rest:gsub("^Model%.", "")
			local rcName = _holderToRC[vnsName]
			if not rcName then return nil end
			local rcModel = (_realChar and _realChar:FindFirstChild(rcName))
				or character:FindFirstChild(rcName)
			if not rcModel then return nil end
			local cur = rcModel
			for seg in rest:gmatch("[^%.]+") do
				if not cur then return nil end
				cur = cur:FindFirstChild(seg, true)
			end
			if cur and cur:IsA("BasePart") then return cur end
			return nil
		end
		-- V4.3.377: gate {holder}.X resolution to breastclothes (same class as (see Changelog for full rationale)
		-- V4.3.376's _findInSiblingVns gating). Body-type rbxms that reference
		local _allowHolderPath = modelPath:find("breastclothes") ~= nil
		for _, m in ipairs(cloneRoot:GetDescendants()) do
			if m:IsA("Motor6D") or m:IsA("Weld") then
				for _attrKey, _attrVal in pairs(m:GetAttributes()) do
					if typeof(_attrVal) == "string" then
						local target
						local charName = _attrVal:match("^{character}%.(.+)$")
						local isHolder = _attrVal:sub(1, 8) == "{holder}"
						if charName then
							target = _resolveCharPart(charName)
						elseif isHolder and _allowHolderPath then
							target = _resolveHolderPath(_attrVal)
						end
						if target then
							-- Pre-position the WELDED part so Roblox's weld evaluation
							-- lands at the correct world CFrame.
							if _attrKey == "Part0" then
								local _p1 = m.Part1
								if _p1 and _p1:IsA("BasePart") then
									pcall(function() _p1.CFrame = target.CFrame * m.C0 * m.C1 end)
								end
							elseif _attrKey == "Part1" then
								local _p0 = m.Part0
								if _p0 and _p0:IsA("BasePart") then
									pcall(function() _p0.CFrame = target.CFrame * m.C1:Inverse() * m.C0:Inverse() end)
								end
							end
							pcall(function() m[_attrKey] = target end)
						elseif charName or isHolder then
							warn(string.format("[RoClothes] RigVnsModel: unresolved %s='%s' (model=%s, motor=%s)",
								_attrKey, _attrVal, tostring(modelPath), m:GetFullName()))
						end
					end
				end
			end
		end

		-- V4.3.252: bra geometric C0 recompute moved out of this block - see below
		-- after the `if not cloneRoot then` close, so it ALSO runs on dedup-hit
		-- (scale/recolor changes that mutate L/R Breast positions need to propagate).

		-- V4.3.553: permanent fix for Xeno cross-contamination. Rewrote the
		-- entire rebuild architecture to GUARANTEE no mesh mixing between body
		-- parts. Background:
		-- - V4.3.308 (original) rebuilt non-skinned MeshParts via
		--   IS:CreateMeshPartAsync(URL, ...) where URL came from
		--   Function.GetAsset → getcustomasset. Worked everywhere because
		--   getcustomasset URLs were per-path on most executors.
		-- - V4.3.549 extended this to skinned MeshParts on CapSec executors
		--   (Xeno) where MeshId script-writes are denied by NotAccessible.
		-- - V4.3.551 added bytes-rebuild fallback for placeholder cases on
		--   skinned + CapSec - fixed butt visibility.
		-- - V4.3.552 user retest: butt visible BUT now arm and leg show butt
		--   mesh. Root cause: Xeno's getcustomasset keys URLs by BASENAME, not
		--   full path. arm/leg/butt ALL have `left.mesh` and `right.mesh` -
		--   they collide at `rbxasset://{UUID}/left.mesh`. First call wins
		--   the engine cache, subsequent calls return the same wrong bytes.
		--   V4.3.308 URL-rebuild poisons cache. Only the skinned+placeholder
		--   path got bytes-rebuild → only butt was fixed. Arm/leg (non-skinned
		--   OR not-placeholder per the V4.3.551 gate) kept URL-rebuilt MPs
		--   with cross-contaminated mesh data.
		-- V4.3.553 fix: on CapSec executors, ALL VNS MeshParts (skinned + non-
		-- skinned) go through bytes-rebuild as PRIMARY. URL-rebuild is NEVER
		-- used on CapSec - that's what poisons the cache. Bytes-content path
		-- has zero URL involvement and zero cache key, so cross-contamination
		-- is structurally impossible. On non-CapSec executors V4.3.382 +
		-- V4.3.308 behavior preserved (skinned skipped, non-skinned URL-built)
		-- - those executors don't have the basename-collision bug. Per user
		-- 2026-06-08: "I need a CLEAR separation, arm for arm, leg for leg,
		-- butt for butt, no mixing, not even a chance."
		do
			local _capsecLocked = System._vnsCapsecMeshIdLocked == true
			local _partMap = {}
			local _toReplace = {}
			for _, _d in ipairs(cloneRoot:GetDescendants()) do
				if _d:IsA("MeshPart") then
					local _skinned = false
					pcall(function() _skinned = _d.HasSkinnedMesh end)
					if not _skinned or _capsecLocked then
						-- Non-skinned: always rebuild (V4.3.308 behavior).
						-- Skinned on CapSec: V4.3.549 inclusion.
						-- Skinned on non-CapSec: skipped (V4.3.382 behavior preserved).
						table.insert(_toReplace, _d)
					end
				end
			end
			local _rebuilt, _failedBuild, _failedSkinning = 0, 0, 0
			-- V4.3.555: simplified rebuild. The install pipeline now writes a
			-- unique-basename mirror of every VNS .mesh file to RClothesContent/
			-- _vns_uniq/<flattened> using binary-safe HTTP bytes. Function.GetAsset
			-- routes CapSec lookups through that mirror automatically, so this
			-- rebuild loop reverts to V4.3.308's simple form: call GetAsset on
			-- oldMP.MeshId, pass the resolved URL to CreateMeshPartAsync. No
			-- runtime readfile (Xeno's binary readfile truncates at \\0 - V4.3.554
			-- learned this the hard way). No Content.fromBuffer (unavailable on
			-- Xeno - V4.3.553 learned this). Just URL via the cache-collision-safe
			-- _vns_uniq mirror that the install pipeline already set up. CapSec
			-- inclusion of skinned MeshParts (V4.3.549) preserved via the
			-- _toReplace gate above.
			-- Pass 1: create replacement MeshParts via URL.
			for _, oldMP in ipairs(_toReplace) do
				local _isSkinnedSource = false
				pcall(function() _isSkinnedSource = oldMP.HasSkinnedMesh end)
				local _resolvedMeshId = Function.GetAsset(oldMP.MeshId)
				local _newMP
				local _ok = pcall(function()
					_newMP = Function.CachedCreateMeshPartAsync(_resolvedMeshId,
						Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
				end)
				if _abortStaleRig() then
					if _newMP then pcall(function() _newMP:Destroy() end) end
					return nil, {}
				end
				if not _ok or not _newMP then
					_failedBuild = _failedBuild + 1
				end
				-- Skinning preservation gate (only for skinned sources). On
				-- non-CapSec, if rebuild dropped skinning we cancel the swap
				-- (preserves V4.3.382 intent). On CapSec we commit anyway
				-- because oldMP would be invisible.
				if _newMP and _isSkinnedSource then
					local _newSkinned = false
					pcall(function() _newSkinned = _newMP.HasSkinnedMesh end)
					if not _newSkinned and not _capsecLocked then
						pcall(function() _newMP:Destroy() end)
						_newMP = nil
						_failedSkinning = _failedSkinning + 1
					end
				end
				if _newMP then
					-- Copy mutable properties. CFrame copied last so children
					-- that move with the part don't pick up an intermediate pos.
					_newMP.Name                       = oldMP.Name
					pcall(function() _newMP.Size = oldMP.Size end)
					_newMP.Color                      = oldMP.Color
					_newMP.Material                   = oldMP.Material
					_newMP.Transparency               = oldMP.Transparency
					_newMP.Reflectance                = oldMP.Reflectance
					_newMP.Anchored                   = oldMP.Anchored
					_newMP.CanCollide                 = oldMP.CanCollide
					_newMP.CanQuery                   = oldMP.CanQuery
					_newMP.CanTouch                   = oldMP.CanTouch
					_newMP.Massless                   = oldMP.Massless
					_newMP.CustomPhysicalProperties   = oldMP.CustomPhysicalProperties
					_newMP.EnableFluidForces          = oldMP.EnableFluidForces
					-- TextureID may be capability-restricted on Xeno; pcall it.
					pcall(function() _newMP.TextureID = Function.GetAsset(oldMP.TextureID) end)
					-- Attributes: SmartBone reads `Roots`, `ColliderShape`, etc.
					for _attr, _val in pairs(oldMP:GetAttributes()) do
						pcall(function() _newMP:SetAttribute(_attr, _val) end)
					end
					-- Tags: System.RCTag is added later, but rbxm-baked tags need preserving.
					do
						local _CS = game:GetService("CollectionService")
						for _, _tag in ipairs(_CS:GetTags(oldMP)) do
							pcall(function() _CS:AddTag(_newMP, _tag) end)
						end
					end
					-- Re-parent children (Welds, Motor6Ds, Bones, SurfaceAppearance, Decals).
					-- For skinned MeshParts, this transfers the Bone hierarchy from
					-- old → new. SmartBone's skin binding is by bone-name match
					-- against mesh weights, so structure preserved = skinning works.
					for _, _child in ipairs(oldMP:GetChildren()) do
						_child.Parent = _newMP
					end
					_newMP.CFrame = oldMP.CFrame
					_newMP.Parent = oldMP.Parent
					_partMap[oldMP] = _newMP
					_rebuilt = _rebuilt + 1
				end
				-- Failure path: leave oldMP in place. On CapSec this MP is
				-- invisible (original rbxasset URL can't fetch). On non-CapSec
				-- the V4.3.546 walk's MeshId rewrite handles it.
			end
			-- One-line summary per VNS model. Kept for ongoing observability.
			if #_toReplace > 0 or _failedBuild > 0 or _failedSkinning > 0 then
				local _shortPath = (modelPath or "?"):gsub("^RClothesContent/_vns/", "")
				print(string.format(
					"[RoClothes][vns.rebuild] %s capsec=%s total=%d built=%d failBuild=%d failSkin=%d",
					_shortPath, tostring(_capsecLocked), #_toReplace,
					_rebuilt, _failedBuild, _failedSkinning))
			end
			_diagPublicCall("vns.rebuild", {
				path = modelPath,
				capsec = _capsecLocked,
				total = #_toReplace,
				built = _rebuilt,
				failed_build = _failedBuild,
				failed_skinning = _failedSkinning,
			})
			-- Pass 2: retarget Motor6D/Weld references on every joint in the tree.
			for _, _d in ipairs(cloneRoot:GetDescendants()) do
				if _d:IsA("Motor6D") or _d:IsA("Weld") then
					local _new0 = _partMap[_d.Part0]
					local _new1 = _partMap[_d.Part1]
					if _new0 then _d.Part0 = _new0 end
					if _new1 then _d.Part1 = _new1 end
				end
			end
			-- Pass 3: destroy old MeshParts (now empty + unreferenced).
			for _oldMP, _ in pairs(_partMap) do _oldMP:Destroy() end
		end

		-- Route MeshIds / TextureIDs / Decal.Texture / etc. through Function.GetAsset
		-- (workspace-first via getcustomasset, fallback to rbxasset://).
		-- V4.3.308: MeshPart MeshIds already resolved above; this call now just
		-- handles SpecialMesh / Decal / Texture / ImageLabel / ImageButton.
		if _abortStaleRig() then return nil, {} end
		Function.ApplyAssets(cloneRoot)
		if _abortStaleRig() then return nil, {} end

		-- V4.3.263 (mobile-perf M6): within-session SmartBone Actor sweep. Before (see Changelog for full rationale)
		if _abortStaleRig() then return nil, {} end
		do
			local _existing = character:FindFirstChild(_cacheName)
			while _existing and _existing ~= cloneRoot do
				pcall(function() _existing:Destroy() end)
				_existing = character:FindFirstChild(_cacheName)
			end
		end
		-- Tag for BREAKER cleanup. Done BEFORE parenting so the tags are in place
		-- by the time anything observes the new instance.
		pcall(function() cloneRoot:AddTag(System.RCTag) end)
		for _, p in ipairs(cloneRoot:GetDescendants()) do
			if p:IsA("BasePart") then
				pcall(function() p:AddTag(System.RCTag) end)
			end
		end
		-- V4.3.378: stamp source modelPath so the variant-aware dedup check above
		-- can verify on the next rig that this cloneRoot was built from the same
		-- rbxm. Needed when multiple variants share the same _cacheName slot.
		pcall(function() cloneRoot:SetAttribute("_RC_VNS_SourcePath", modelPath) end)

		-- Parent FIRST while parts are still anchored at their rbxm coords. Then
		-- unanchor + apply VNS's defaultPartProperties (per vns_module_rig.lua L14-24).
		-- Critical: Massless=true + near-zero CustomPhysicalProperties prevents the
		-- sim Part from being pushed by gravity (visible as breast wobbling freely
		-- instead of staying welded to chest). Zero velocities prevent initial momentum.
		if _abortStaleRig() then return nil, {} end
		cloneRoot.Parent = character
		local _PP = PhysicalProperties.new(0.001, 0, 0)
		for _, p in ipairs(cloneRoot:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Anchored = false
				p.CanCollide = false
				p.CanQuery = false
				p.CanTouch = false
				p.EnableFluidForces = false
				p.Massless = true
				p.CustomPhysicalProperties = _PP
				p.AssemblyLinearVelocity = Vector3.zero
				p.AssemblyAngularVelocity = Vector3.zero
			end
		end

		-- V4.3.377: guard-weld fallback for body-type rigs - if NO external-anchor
		-- motor resolved, weld cloneRoot to HumanoidRootPart (fallback: PrimaryPart /
		-- UpperTorso / Torso) so parts don't float at rbxm-baked coords. Skips
		-- breastclothes (its V4.3.241+252 retarget below handles anchoring geometrically).
		-- See Changelog for the V4.3.376 cross-link regression history.
		if not modelPath:find("breastclothes") then
			local _hasExternalAnchor = false
			for _, _m in ipairs(cloneRoot:GetDescendants()) do
				if (_m:IsA("Motor6D") or _m:IsA("Weld")) and _m.Part0 then
					if not _m.Part0:IsDescendantOf(cloneRoot) then
						_hasExternalAnchor = true
						break
					end
				end
			end
			if not _hasExternalAnchor then
				local _charAnchor = (_realChar and (_realChar:FindFirstChild("HumanoidRootPart")
						or _realChar.PrimaryPart
						or _realChar:FindFirstChild("UpperTorso")
						or _realChar:FindFirstChild("Torso")))
					or character:FindFirstChild("HumanoidRootPart")
					or character.PrimaryPart
					or character:FindFirstChild("UpperTorso")
					or character:FindFirstChild("Torso")
				if _charAnchor and _charAnchor:IsA("BasePart") then
					-- Pick the first MeshPart inside cloneRoot as the "root" to weld.
					local _rootPart = nil
					for _, _d in ipairs(cloneRoot:GetDescendants()) do
						if _d:IsA("MeshPart") then _rootPart = _d; break end
					end
					if _rootPart then
						-- Position the rootPart at the character anchor first so the
						-- weld engages at the right world location. Other parts in
						-- cloneRoot follow via internal welds (or float right where
						-- the rbxm placed them relative to rootPart, which is fine
						-- since they were authored as a self-contained assembly).
						pcall(function()
							_rootPart.CFrame = _charAnchor.CFrame
						end)
						local _w = Instance.new("Weld")
						_w.Name = "RC_VNS_GuardAnchor_V4_3_377"
						_w.Part0 = _charAnchor
						_w.Part1 = _rootPart
						_w.C0 = CFrame.identity
						_w.C1 = CFrame.identity
						_w.Parent = _rootPart
						pcall(function() _w:AddTag(System.RCTag) end)
						warn(string.format(
							"[RoClothes] RigVnsModel: %s had no external-anchor motors; V4.3.377 guard-welded to %s.",
							tostring(modelPath), _charAnchor:GetFullName()))
					end
				end
			end
		end
		end -- close `if not cloneRoot then` (V4.3.232 - fresh-clone path only)

		-- V4.3.241+252: bra geometric C0 recompute. Per V4.3.240 POST-RIG dump, the (see Changelog for full rationale)
		-- V4.3.252: moved outside `if not cloneRoot then` so this also runs on dedup-
		if modelPath:find("breastclothes") then
			local rcBreast = (_realChar and _realChar:FindFirstChild("RC_VNS_breast"))
				or character:FindFirstChild("RC_VNS_breast")
			if rcBreast then
				local _breasts = rcBreast:FindFirstChild("Breasts", true)
				local _lb = rcBreast:FindFirstChild("Left Breast", true)
				local _rb = rcBreast:FindFirstChild("Right Breast", true)
				if _breasts and _lb and _rb then
					local _midPos = (_lb.Position + _rb.Position) / 2
					local _targetCF = CFrame.new(_midPos) * (_breasts.CFrame - _breasts.Position)
					-- V4.3.377: scope retarget to EXTERNAL-anchor motors only (Part0
					-- outside cloneRoot). Pre-fix every Motor6D/Weld got Part0=_breasts +
					-- Part1.CFrame=_targetCF - collapsed internal welds and stacked bra
					-- parts at chest-midpoint. Fallback: if NO external motor, retarget
					-- the first Motor6D found (legacy single-motor case).
					local _externalMotors = {}
					for _, m in ipairs(cloneRoot:GetDescendants()) do
						if (m:IsA("Motor6D") or m:IsA("Weld")) and m.Part1 and m.Part1:IsA("BasePart") then
							local _p0 = m.Part0
							if _p0 and not _p0:IsDescendantOf(cloneRoot) then
								table.insert(_externalMotors, m)
							end
						end
					end
					if #_externalMotors == 0 then
						-- Legacy fallback: rbxm authored Part0 internally - pick the
						-- first Motor6D as the anchor (the V4.3.241+252 original
						-- single-motor behavior).
						for _, m in ipairs(cloneRoot:GetDescendants()) do
							if m:IsA("Motor6D") and m.Part1 and m.Part1:IsA("BasePart") then
								table.insert(_externalMotors, m)
								break
							end
						end
					end
					for _, m in ipairs(_externalMotors) do
						pcall(function()
							m.Part0 = _breasts
							m.C0 = _breasts.CFrame:Inverse() * _targetCF * m.C1
							m.Part1.CFrame = _targetCF
						end)
					end
				end
			end
		end

		-- V4.3.226: load colliders FIRST, before tagging bones. SmartBone's SetupObject (see Changelog for full rationale)
		if not character:FindFirstChild("RC_VNS_collider") then
			local _colRoot = _getVnsModel("RClothesContent/_vns/model/collider.rbxm")
			if _abortStaleRig() then return nil, {} end
			if _colRoot then
				local _colSrc = _colRoot:FindFirstChildOfClass("Model")
				local _colClone
				if _colSrc then
					_colClone = _colSrc:Clone()
				else
					_colClone = Instance.new("Model")
					for _, c in ipairs(_colRoot:GetChildren()) do
						if c:IsA("BasePart") or c:IsA("Folder") then
							c:Clone().Parent = _colClone
						end
					end
				end
				_colClone.Name = "RC_VNS_collider"
				_vnsOwnedCollider = _colClone
				-- Resolve to real character + pre-position welded part (VNS modelWeld pattern).
				for _, m in ipairs(_colClone:GetDescendants()) do
					if m:IsA("Motor6D") or m:IsA("Weld") then
						local attrVal = m:GetAttribute("Part0")
						if attrVal then
							local name = tostring(attrVal):match("{character}%.(.+)")
							if name then
								local target = (_realChar and _realChar:FindFirstChild(name))
									or character:FindFirstChild(name)
								if not target and name == "Torso" then
									target = (_realChar and _realChar:FindFirstChild("UpperTorso"))
										or character:FindFirstChild("UpperTorso")
								end
								if target then
									local _p1 = m.Part1
									if _p1 and _p1:IsA("BasePart") then
										pcall(function() _p1.CFrame = target.CFrame * m.C0 * m.C1 end)
									end
									m.Part0 = target
								end
							end
						end
					end
				end
				-- V4.3.232: apply ALL physics + visibility properties BEFORE tagging (see Changelog for full rationale)
				pcall(function() _colClone:AddTag(System.RCTag) end)
				local _CPP = PhysicalProperties.new(0.001, 0, 0)
				for _, p in ipairs(_colClone:GetDescendants()) do
					if p:IsA("BasePart") then
						pcall(function() p:AddTag(System.RCTag) end)
						p.Transparency = 1
						p.CanCollide = false
						p.CanQuery = false
						p.CanTouch = false
						p.Massless = true
						p.CustomPhysicalProperties = _CPP
						p.AssemblyLinearVelocity = Vector3.zero
						p.AssemblyAngularVelocity = Vector3.zero
						-- ColliderShape attribute lets SmartBone Utilities.GetCollider
						-- detect non-Part shapes correctly. For Part instances Roblox
						-- already exposes .Shape; for MeshParts/Unions it falls back
						-- to "Box". Prefer existing attribute if rbxm sets one.
						if not p:GetAttribute("ColliderShape") then
							if p:IsA("Part") then
								p:SetAttribute("ColliderShape", p.Shape.Name)
							else
								p:SetAttribute("ColliderShape", "Box")
							end
						end
					end
				end
				if _abortStaleRig() then return nil, {} end
				-- A concurrent newer request may have committed while the model load
				-- yielded. Keep that replacement and discard only our private clone.
				if character:FindFirstChild("RC_VNS_collider") then
					pcall(function() _colClone:Destroy() end)
					_vnsOwnedCollider = nil
				else
				_colClone.Parent = character
				-- Now safe to unanchor (welds will engage correctly post-parenting).
				for _, p in ipairs(_colClone:GetDescendants()) do
					if p:IsA("BasePart") then p.Anchored = false end
				end
				-- Tag LAST - SmartBone's add-signal callback reads properties immediately.
				local _CS = game:GetService("CollectionService")
				for _, p in ipairs(_colClone:GetDescendants()) do
					if p:IsA("BasePart") then
						pcall(function() _CS:AddTag(p, "SmartCollider") end)
						if System._sbColliderTag then
							pcall(function() _CS:AddTag(p, System._sbColliderTag) end)
						end
					end
				end
				_vnsOwnedCollider = nil
				end
			end
		end

		-- V4.3.219+229: register sim Parts with SmartBone for physics. SmartBone uses (see Changelog for full rationale)
		-- V4.3.229: gate on PlayerData.SmartBoneEnabled (the GUI toggle was previously
		if System._sbTag then
			local _sbEnabled = false
			-- V4.3.241: M2 shadow character's name doesn't match player.Name, so the
			-- old `PlayerData[character.Name]` lookup always missed → SmartBoneEnabled
			-- was never seen as true → no body type ever got tagged. Use the same
			-- robust resolver as the recolor block: walk Players, match by Character
			-- equality OR RealCharacter ref OR name.
			local _pd
			for _, _pname in ipairs(game:GetService("Players"):GetPlayers()) do
				if PlayerData and PlayerData[_pname.Name] and (character == _pname.Character
					or (PlayerData[_pname.Name].RealCharacter == character)
					or character.Name == _pname.Name) then
					_pd = PlayerData[_pname.Name]
					break
				end
			end
			-- CLONE/NPC: synthetic targets are keyed in System.NPCs (rig model is NAMED the key);
			-- resolve their own PD before the local-player fallback.
			if not _pd and System and System.NPCs then
				for _k, _m in pairs(System.NPCs) do
					if _m == character or (character and _k == character.Name) then
						_pd = PlayerData and PlayerData[_k]
						break
					end
				end
			end
			_pd = _pd or (PlayerData and PlayerData[game.Players.LocalPlayer.Name])
			if _pd then _sbEnabled = _pd.SmartBoneEnabled == true end
			local CS = game:GetService("CollectionService")
			for _, p in ipairs(cloneRoot:GetDescendants()) do
				if p:IsA("BasePart") and p:FindFirstChildOfClass("Bone") then
					-- V4.3.234: respect the rbxm's pre-set Roots attribute. The breast/1 (see Changelog for full rationale)
					local _hasRoots = p:GetAttribute("Roots") ~= nil
					if not _hasRoots then
						local rootNames = {}
						for _, c in ipairs(p:GetChildren()) do
							if c:IsA("Bone") then
								table.insert(rootNames, c.Name)
							end
						end
						if #rootNames > 0 then
							p:SetAttribute("Roots", table.concat(rootNames, ","))
							_hasRoots = true
						end
					end
					if _hasRoots then
						-- Only tag (= activate physics) when SmartBoneEnabled is on.
						-- Without the tag, SetupObject never fires → no physics.
						if _sbEnabled then
							pcall(function() CS:AddTag(p, System._sbTag) end)
						else
							pcall(function() CS:RemoveTag(p, System._sbTag) end)  -- V4.4.2 FIX: actually turn SmartBone physics OFF (dedup-hit reused the tagged part + only skipped AddTag)
						end
					end
				end
			end
		end

		-- V4.3.220: apply scale and recolor from PlayerData. Mirrors what Function.Weld
		-- does for default body types (Tone-based body color, NippleColor for nipples,
		-- BreastsScale/ButtsScale/LegsScale size multipliers). Without this, SB meshes
		-- render at default rbxm values regardless of user settings.
		do
			local _data = nil
			for _, _pname in ipairs(game:GetService("Players"):GetPlayers()) do
				if PlayerData and PlayerData[_pname.Name] and (character == _pname.Character
					or (PlayerData[_pname.Name].RealCharacter == character)
					or character.Name == _pname.Name) then
					_data = PlayerData[_pname.Name]
					break
				end
			end
			-- CLONE/NPC: synthetic targets are keyed in System.NPCs (rig model is NAMED the key;
			-- the Method-2 proxy is also named the key) - resolve their own PD before falling back.
			if not _data and System and System.NPCs then
				for _k, _m in pairs(System.NPCs) do
					if _m == character or (character and _k == character.Name) then
						_data = PlayerData and PlayerData[_k]
						break
					end
				end
			end
			-- Fallback to local player's data if no match.
			_data = _data or (PlayerData and PlayerData[game.Players.LocalPlayer.Name])
			if _data then
				-- Resolve body color from BodyColors instance (Tone="Base" uses these,
				-- "Dark" darkens, custom SkinTone overrides).
				local _bodyColor
				if _data.SkinTone and typeof(_data.SkinTone) == "Color3" then
					_bodyColor = _data.SkinTone
				else
					local _bc = character:FindFirstChildOfClass("BodyColors")
						or (_data.RealCharacter and _data.RealCharacter:FindFirstChildOfClass("BodyColors"))
					if _bc then
						_bodyColor = _bc.TorsoColor3
					end
				end
				-- V4.3.319: removed the `if _data.Tone == "Dark" then darken _bodyColor` (see Changelog for full rationale)
				-- V4.3.227: only use _data.NippleColor if user picked one; default to pink
				-- CLONE: never depend on the live BodyColors instance state - fall back to the
				-- persistent skin snapshot (CLONE FIX 3) when no SkinTone override exists.
				if not _bodyColor and _data.IsClone and _data.OriginalBodyColors then
					_bodyColor = _data.OriginalBodyColors.TorsoColor3
				end
				local _nippleColor = _data.NippleColor or Color3.fromRGB(255, 167, 169)
				-- Per-body-type scale multipliers from PlayerData. Default 1.
				local _bScale = tonumber(_data.BreastsScale) or 1
				local _btScale = tonumber(_data.ButtsScale) or 1
				local _lScale = tonumber(_data.LegsScale) or 1
				local _tScale = tonumber(_data.TorsoScale) or 1
				local _laScale = tonumber(_data.LeftArmScale) or 1
				local _raScale = tonumber(_data.RightArmScale) or 1

				-- V4.3.228: rewrite to match VNS modeldata Property table (per (see Changelog for full rationale)
				local function _darken(c, vPct)
					local h, s, v = Color3.toHSV(c)
					return Color3.fromHSV(h, s, math.max(0, v * (1 - vPct / 100)))
				end
				-- V4.3.319: Tone="Dark" boosts the nipple/SA darken percentage from
				-- the default 17.75% to 40% so the user-visible "Dark" tone only
				-- affects the nipple + areola, not the body color.
				local _darkPct = (_data.Tone == "Dark") and 40 or 17.75
				local _darkBody = _bodyColor and _darken(_bodyColor, _darkPct) or nil

				for _, p in ipairs(cloneRoot:GetDescendants()) do
					if p:IsA("MeshPart") then
						local nm = p.Name
						-- BasePart.Color: nipples get darker shade, everything else body color.
						-- V4.3.339: gate NippleColor on Tone="Use NippleColor" - Types 1-5 do this
						-- (L5502/L5577), Type 6 was applying NippleColor unconditionally so a stale
						-- pd.NippleColor from a prior bundle painted nipples even when Tone="Base"/"Dark".
						if nm:find("Nipple") then
							if _data.Tone == "Use NippleColor" and _data.NippleColor then
								p.Color = _data.NippleColor
							elseif _darkBody then
								p.Color = _darkBody
							end
						elseif _bodyColor then
							p.Color = _bodyColor
						end
						-- SurfaceAppearance.Color: tint the ColorMap (which has the areola
						-- baked in) by darker body color so areola shows through correctly.
						-- V4.3.341: nipple meshes' SA tint follows NippleColor when Tone="Use (see Changelog for full rationale)
						local sa = p:FindFirstChildOfClass("SurfaceAppearance")
						if sa then
							if nm:find("Nipple") and _data.Tone == "Use NippleColor" and _data.NippleColor then
								pcall(function() sa.Color = _data.NippleColor end)
							elseif _darkBody then
								pcall(function() sa.Color = _darkBody end)
							end
						end
						-- Scale: only breast/butt/leg meshes. V4.4.2 FIX: apply from a STORED BASELINE, not the
						-- live size. RigVnsModel re-runs this on every re-execute (incl. the dedup-hit path that
						-- reuses persisted MeshParts on Method 1/3), so `p.Size = p.Size * scale` compounded
						-- exponentially on any hotSwap (body ballooned). Cache the pristine size once (attribute
						-- survives across re-execs like the part) so scale is absolute + reversible.
						local _scaleFor
						if nm:find("Breast") and not nm:find("Nipple") then _scaleFor = _bScale
						elseif nm:find("Butt") then _scaleFor = _btScale
						elseif nm == "Left Leg" or nm == "Right Leg" then _scaleFor = _lScale
						elseif nm == "Torso" or nm == "Torso Mesh" then _scaleFor = _tScale
						elseif nm == "Left Arm" or nm == "Left Arm Mesh" then _scaleFor = _laScale
						elseif nm == "Right Arm" or nm == "Right Arm Mesh" then _scaleFor = _raScale end
						if _scaleFor then
							local _b = p:GetAttribute("RC_VNS_BaseSize")
							if not _b then _b = p.Size; p:SetAttribute("RC_VNS_BaseSize", _b) end
							p.Size = _b * _scaleFor
						end
					end
				end
			end
		end

		-- Build the name → MeshPart map for caller use (organ registration).
		local meshParts = {}
		for _, p in ipairs(cloneRoot:GetDescendants()) do
			if p:IsA("MeshPart") then
				meshParts[p.Name] = p
			end
		end

		if not next(meshParts) then
			warn("[RoClothes] RigVnsModel: " .. tostring(modelPath) .. " loaded but contains no MeshParts.")
		end

		return cloneRoot, meshParts
	end



	function Function.MultiplyCalculate(Base, Default)
		-- V4.3.347: nil-guard + zero-axis guard. Pre-fix Default could be nil if
		-- BodyPartSize[PARENT[1]] entry was missing (custom rig with new body-part name),
		-- crashing the entire weld pipeline. Zero-axis would propagate inf/NaN into
		-- Size assignments downstream. Fall back to 1 (identity multiplier).
		if not (Base and Default) then return 1, 1, 1 end
		local X = (Default.X and Default.X ~= 0) and (Base.X / Default.X) or 1
		local Y = (Default.Y and Default.Y ~= 0) and (Base.Y / Default.Y) or 1
		local Z = (Default.Z and Default.Z ~= 0) and (Base.Z / Default.Z) or 1

		return X,Y,Z
	end

