	-- V4.3.168.16: extracted from the inline client-parenting block at ~L13295 which
	-- tripped the 200-register cap at `local uiParent`. Moves 4 short-lived locals
	-- (uiParent/missing/gethui/protectgui) into THIS helper's register pool.
	function Function.ParentGuisToScreen(go, player)
		if RS:IsClient() and not RS:IsStudio() then
			local uiParent
			local function missing(t, f, fallback)
				if type(f) == t then return f end
				return fallback
			end
			local _gethui = missing("function", gethui or get_hidden_gui)
			local _protectgui = missing("function", protect_gui or (syn and syn.protect_gui))
			if _gethui then
				uiParent = _gethui()
			else
				uiParent = game:GetService("CoreGui")
			end

			go.Screen.Parent = uiParent
			go.MobileCloseButtonScreen.Parent = uiParent
			go.ColorPickerScreen.Parent = uiParent

			if _protectgui then
				pcall(_protectgui, go.Screen)
				pcall(_protectgui, go.MobileCloseButtonScreen)
				pcall(_protectgui, go.ColorPickerScreen)
			end
		else
			local pg = player:WaitForChild("PlayerGui")
			go.Screen.Parent = pg
			go.MobileCloseButtonScreen.Parent = pg
			go.ColorPickerScreen.Parent = pg
		end
	end

