	function Function.CatalogAccessoryFrameAdd(Data)
		if not GUIObject.Catalog_3 then return end  -- [V3 MERGE FIX] old-GUI catalog container not built in V3 (V3 uses its own catalog grid); nil-guard the unguarded :FindFirstChild below.
		if not GUIObject.Catalog_3:FindFirstChild(Data) then
			local CatalogListFrame = Instance.new("ScrollingFrame")

			CatalogListFrame.Name = Data
			CatalogListFrame.Parent = GUIObject.Catalog_3
			CatalogListFrame.Active = true
			CatalogListFrame.AnchorPoint = Vector2.new(0.5, 0.5)
			CatalogListFrame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
			CatalogListFrame.BackgroundTransparency = 1.000
			CatalogListFrame.BorderSizePixel = 0
			-- V4.3.543 Fix 1: move CatalogListFrame below BrowseCatalogButton.
			-- Pre-fix the ScrollingFrame anchored at (0.5, 0.76) center with
			-- 0.45 height spanned Y=0.535 to Y=0.985 in the parent Catalog_3
			-- tab, OVERLAPPING the BrowseCatalogButton at Y=0.55 to Y=0.62
			-- (created at L30331 via UI.makeActionButton with Position(0.5,
			-- 0.55) AnchorPoint(0.5,0) Size(0.7, 0.07)). In V4.3.541 the 3-
			-- column tight cellsize packed accessory buttons into 1 row with
			-- a higher ZIndex that hid Browse Catalog behind them. V4.3.542's
			-- cellsize reduction (0.262→0.18 height) made cells shorter and
			-- gaps wider, exposing Browse Catalog peeking between the 2 rows
			-- of accessory buttons (user screenshot 2026-06-07 "looks soooo
			-- off"). The design comment at L30325-L30328 explicitly states
			-- Browse Catalog should sit "below the 6 textboxes" with the
			-- accessory list below THAT - fix matches the intent. New center
			-- at Y=0.815 with Size Y=0.33 → spans Y=0.65 to Y=0.98, giving a
			-- 0.03 gap below Browse Catalog's bottom edge (Y=0.62) for
			-- breathing room. Available space below Browse Catalog is Y=0.62
			-- to Y=1.0 = 0.38 height; this uses 0.33 leaving 0.05 below for
			-- the bottom edge.
			CatalogListFrame.Position = UDim2.new(0.499999911, 0, 0.815, 0)
			CatalogListFrame.Size = UDim2.new(0.949999988, 0, 0.33, 0)
			CatalogListFrame.BottomImage = "rbxassetid://5946093983"
			CatalogListFrame.MidImage = ""
			CatalogListFrame.ScrollBarThickness = 0
			CatalogListFrame.CanvasSize = UDim2.new(1, 0, 1, 0)
			CatalogListFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
			CatalogListFrame.TopImage = "rbxassetid://5946093983"

			local UIGridLayout_3 = Instance.new("UIGridLayout")

			UIGridLayout_3.Parent = CatalogListFrame
			UIGridLayout_3.SortOrder = Enum.SortOrder.LayoutOrder
			-- V4.3.542 Fix 1: enlarge per-cell size + add horizontal padding.
			-- Pre-fix the 3-column grid at 0.315×0.262 cells with zero horizontal
			-- padding made buttons too narrow to display long accessory IDs or
			-- names (e.g. "11210791935" 11 chars / "135997254195298" 15 chars
			-- overflowed and adjacent cells touched → text from one button
			-- visually clipped into its neighbor, the "wse"/"k Cat" partial-
			-- text artifacts in user's screenshot 2026-06-07). New 2-column
			-- grid at 0.47×0.18 cells with small horizontal+vertical padding
			-- gives ~50% more horizontal room per button and a small gutter,
			-- making accessory names legible + tap targets bigger for mobile.
			-- Net density: was 3×4=12 buttons visible, now 2×5=10 visible at a
			-- time - similar density, much better readability. AutomaticCanvasSize
			-- = Y already set on the parent ScrollingFrame so vertical overflow
			-- scrolls cleanly.
			UIGridLayout_3.CellPadding = UDim2.new(0.02, 0, 0.04, 0)
			UIGridLayout_3.CellSize = UDim2.new(0.47, 0, 0.18, 0)
		end
	end

	function Function.PlayerDataAdd(Name)
		if not PlayerData[Name] then
			PlayerData[Name] = Function.PlayerDataDefault()
			PlayerData[Name].AutoExecute = false
		end
	end

	function Function.CFrameMultiply(CF, Multiply)
		return CFrame.new(
			CF.Position.X * Multiply.X,
			CF.Position.Y * Multiply.Y,
			CF.Position.Z * Multiply.Z
		) * CF.Rotation
	end

	function Function.Vector3Multiply(Vector, Multiply)
		return Vector3.new(
			Vector.X * Multiply.X,
			Vector.Y * Multiply.Y,
			Vector.Z * Multiply.Z
		)
	end

	function Function.Round(num: number, places: number): number
		local decimalPivot = 10^places
		return math.floor(num * decimalPivot + 0.5) / decimalPivot
	end

	-- V4.3.265: removed dead `local printed = {}` - the only consumer was V4.3.260's
	-- already-deleted Debug-gated `print(i)` block at L6792. Frees 1 register slot.

	-- V4.3.49: Weld re-clone rate limiter - prevents CPU lockup when a game destroys our welds every frame.
	-- Budget is per-container, weakly referenced so GC can collect entries when the Part is destroyed.
	-- V4.3.50: reCloneBudget / RECLONE_* moved to file scope (see top of file) for register-cap reasons.
	function Function.TryRecloneWeld(container, weldChild)
		if not container or not container.Parent or not weldChild then return false end
		local state = reCloneBudget[container]
		local now = os.clock()
		if not state then
			state = {count = 0, windowStart = now}
			reCloneBudget[container] = state
		end
		if now - state.windowStart > RECLONE_WINDOW_SECONDS then
			state.count = 0
			state.windowStart = now
		end
		if state.count >= RECLONE_MAX_PER_WINDOW then
			return false
		end
		state.count += 1
		weldChild:Clone().Parent = container
		return true
	end

	-- V4.3.452: shared stale-or-gone guard. Replaces the V4.3.349-era
	-- `RequestID ~= DataDetail.LastRequestID` pattern that reads from a captured
	-- DataDetail upvalue - PlayerRemoving mid-yield leaves the captured upvalue
	-- pointing to an orphan PD whose LastRequestID never advances, so the check
	-- never trips and the function continues writing into the orphan (memory leak
	-- + pinned Instance refs). Returns true when player left OR RID is stale.
	-- Callers should `if Function.IsStaleOrGone(Data, RequestID) then return end`.
	function Function.IsStaleOrGone(Data, RequestID)
		local _pd = PlayerData[Data]
		if not _pd then
			-- V4.3.506 telemetry: player-data gone (peer left mid-apply, etc.).
			Function.diag("hd.stale_rid_bail", { site = "no_pd" })
			return true
		end
		if RequestID and RequestID ~= _pd.LastRequestID then
			-- V4.3.506 telemetry: RID superseded mid-pipeline (rapid click churn).
			Function.diag("hd.stale_rid_bail", { site = "rid_mismatch" })
			return true
		end
		return false
	end

	function Function.Weld(MeshDetail, Character, Extra, Data, RequestID)
		if not MeshDetail then return nil end
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		if Character.Parent ~= nil then
			setmetatable(MeshDetail, MetaClothes)

			local INSTANCE = MeshDetail["Instance"]
			local NAME = MeshDetail["Name"]

			local SIZE = MeshDetail["Size"]
			local CFRAME = MeshDetail["CFrame"]
			local CFRAME1 = MeshDetail["CFrame1"]
			local OFFSET = MeshDetail["Offset"]
			local ROTATION = MeshDetail["Rotation"]
			if OFFSET then
				CFRAME = CFRAME+OFFSET
			end
			if ROTATION then
				CFRAME = CFRAME*CFrame.Angles(math.rad(ROTATION.X),math.rad(ROTATION.Y),math.rad(ROTATION.Z))
			end
			local TRANSPARENCY = MeshDetail["Transparency"]
			local REFLECTANCE = MeshDetail["Reflectance"]
			local MESHBASEPARTTRANSPARENCY = MeshDetail["MeshBasePartTransparency"]
			local MATERIAL = MeshDetail["Material"]
			local COLOR = MeshDetail["Color"]
			local PARENT = MeshDetail["Parent"]
			local PARENTTRANSPARENCY = MeshDetail["ParentTransparency"]
			local FUNCTION = MeshDetail["Function"]
			local SCALE = MeshDetail["Scale"]
			local ADJUSTSCALE = MeshDetail["AdjustScale"]

			local MESHID = MeshDetail["MeshId"]
			local TEXTUREID = MeshDetail["TextureId"]
			local DOUBLESIDED = MeshDetail["DoubleSided"]

			local SHAPE = MeshDetail["Shape"]


			-- V4.3.344: SB body parts (TorsoType=9 / ArmType=5 / LegsType=8 / ButtType=6) are
			-- nested INSIDE the rbxm cloneRoot which is parented to Character - `:FindFirstChild`
			-- only walks direct children, so the lookup fails for SB body. Fall back to the
			-- pre-registered Organ map (CharacterExecute populates it at L11207/11231/11256/11305
			-- with the actual SB MeshParts), then to a recursive search as last resort.
			local BodyPart = Character:FindFirstChild(PARENT[1])
				or (DataDetail.CurrentPartList and DataDetail.CurrentPartList["Organ"] and DataDetail.CurrentPartList["Organ"][PARENT[1]])
				or Character:FindFirstChild(PARENT[1], true)

			local OldCharacter
			if ((DataDetail and DataDetail.MethodAtBuild) or Method) == 3 then  -- CLONE-aware: honor per-build method (clones forced to 1)
				if BodyPart and DataDetail.LocalTransparency[BodyPart.Name] == true then
					OldCharacter = Character

					Character = Method2CharacterFolder:FindFirstChild(Data)

					if not Character then
						Character = Instance.new("Model", Method2CharacterFolder)
						Character:AddTag(System.RCTag)
						Character.Archivable = not hidden
						Character.Name = Data

						local CharacterValue = Instance.new("ObjectValue", Character)
						CharacterValue.Value = OldCharacter

						for _, v in pairs(CharacterValue.Value:GetChildren()) do
							if v:IsA("BasePart") and (table.find(Method2BodyPart, v.Name) or v.Name == "HumanoidRootPart") then
								DataDetail.CurrentPartList.ParentTransparency[v] = {v = v.Transparency}
								if v.Name ~= "Head" then
									DataDetail.CurrentPartList.ParentTransparency[v] = {v = v.Transparency, T = 1}
								end

								local Part = Instance.new("Part", Character)
								Part.Size = v.Size
								Part.Name = v.Name
								Part.Transparency = 1
								Part.CanCollide = false
								Part.CanQuery = false
								Part.CanTouch = false
								Part.Massless = true
								Part.CustomPhysicalProperties = System.Physics.DefaultProperties
								Part.Color = v.Color

								local Weld = Instance.new("Weld", Part)
								Weld.Part1 = Part

								if Part.Name == "HumanoidRootPart" then
									if CharacterValue.Value:FindFirstChild("Torso") then
										Weld.Part0 = CharacterValue.Value:FindFirstChild("Torso")
									else
										Weld.Part0 = v
									end
									Character.PrimaryPart = Part
								else
									Weld.Part0 = v
								end

								local detectRemoval
								detectRemoval = Part.ChildRemoved:Connect(function(c)
									-- V4.3.424: was `if Part.Parent ~= nil then ... else GlobalMaid:Remove ...`. (see Changelog for full rationale)
									if Part:IsDescendantOf(game) then
										if c:IsA("Weld") and c.Part0 == v then
											Function.TryRecloneWeld(Part, c)
										end
									else
										System.GlobalMaid:Remove(detectRemoval)
									end
								end)
								System.GlobalMaid:Give(detectRemoval)
							end
						end
					end
				end
			elseif ((DataDetail and DataDetail.MethodAtBuild) or Method) == 2 then  -- V4.3.451: captured
				OldCharacter = DataDetail.Character
			end

			if BodyPart then
				if ((DataDetail and DataDetail.MethodAtBuild) or Method) == 2 or OldCharacter then  -- V4.3.451: captured
					BodyPart = (OldCharacter and OldCharacter:FindFirstChild(PARENT[1])) or BodyPart  -- BUGFIX: the `==2` disjunct enters this branch even when DataDetail.Character (OldCharacter) is nil (respawn race) -> nil:FindFirstChild threw. Guard OldCharacter.
				end
				local XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(BodyPart.Size, BodyPartSize[PARENT[1]])

				local ObjectInstance

				local Parent = Character
				local Scale = 1

				for Index = 1, #PARENT do
					-- V4.3.344: same Organ-map fallback as L9139 - SB body parts are nested
					-- in the rbxm cloneRoot, so direct FindFirstChild misses them. Try the
					-- pre-registered Organ map first for the FIRST hop (since the chain root
					-- is the body part), then fall through to the standard nested walk.
					local _next = Parent:FindFirstChild(PARENT[Index])
					if not _next and Index == 1 and DataDetail.CurrentPartList and DataDetail.CurrentPartList["Organ"] then
						_next = DataDetail.CurrentPartList["Organ"][PARENT[Index]]
					end
					if not _next then _next = Parent:FindFirstChild(PARENT[Index], true) end
					Parent = _next
					if not Parent then return end
				end

				if SCALE then
					Scale = DataDetail[SCALE]
				end

				if SIZE == "Overlay" then
					local pData = DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[Parent]
					if pData then
						SIZE = Vector3.new(pData.Size.X+0.003,pData.Size.Y+0.003,pData.Size.Z+0.003)
					else
						SIZE = Vector3.new(Parent.Size.X+0.003,Parent.Size.Y+0.003,Parent.Size.Z+0.003)
					end
				elseif SIZE == "Underlay" then
					local pData = DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[Parent]
					if pData then
						SIZE = Vector3.new(pData.Size.X-0.003,pData.Size.Y-0.003,pData.Size.Z-0.003)
					else
						SIZE = Vector3.new(Parent.Size.X-0.003,Parent.Size.Y-0.003,Parent.Size.Z-0.003)
					end
				end

				for i, Adjust in pairs(ADJUSTSCALE) do
					-- Array entries use the ordinary scale; keyed numeric entries
					-- specify an offset compensation gain (e.g. CFrame1=300).
					local field = type(i) == "string" and i or Adjust
					local numeric = type(i) == "string" and type(Adjust) == "number"
					local factor = numeric and (1 + (Scale - 1) * Adjust) or Scale
					local y = factor
					if SCALE == "LegsScale" and (not numeric or field == "Size") then
						y = 1 + (factor - 1) * .2
					end
					local multiply = {X = factor, Y = y, Z = factor}
					if field == "Size" then
						SIZE = Function.Vector3Multiply(SIZE, multiply)
					elseif field == "CFrame" then
						CFRAME = Function.CFrameMultiply(CFRAME, multiply)
					elseif field == "CFrame1" then
						CFRAME1 = Function.CFrameMultiply(CFRAME1, multiply)
					end
				end

				if PARENTTRANSPARENCY ~= nil then
					if OldCharacter and OldCharacter:FindFirstChild(Parent.Name) then
						DataDetail.CurrentPartList.ParentTransparency[OldCharacter:FindFirstChild(Parent.Name)] = {D = OldCharacter:FindFirstChild(Parent.Name).Transparency, T = PARENTTRANSPARENCY}
						--OldCharacter:FindFirstChild(Parent.Name).Transparency = PARENTTRANSPARENCY
					end
					DataDetail.CurrentPartList.ParentTransparency[Parent] = {D = Parent.Transparency, T = PARENTTRANSPARENCY}
					--Parent.Transparency = PARENTTRANSPARENCY
				end

				if INSTANCE == "Mesh" then
					if MESHID == "Parent" then
						MESHID = Parent.MeshId
					end
					local resolvedMeshId = Function.GetAsset(MESHID)
					-- V4.3.309: route through MeshPart cache. First-time meshes still yield
					-- on CreateMeshPartAsync; repeat requests across bundles clone instantly.
					ObjectInstance = Function.CachedCreateMeshPartAsync(resolvedMeshId,
						Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
					local _viaSpecialMesh = false
					if not ObjectInstance then
						-- Retry with raw path in case the resolved path is what's broken.
						if resolvedMeshId ~= MESHID then
							ObjectInstance = Function.CachedCreateMeshPartAsync(MESHID,
								Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
						end
						if not ObjectInstance and Function._cmpaBroken then
							-- V4.4.1 (Delta fix): CreateMeshPartAsync hangs on this executor (flagged in
							-- CachedCreateMeshPartAsync). Build the mesh via Part + SpecialMesh instead --
							-- confirmed rendering on Delta; valid for these non-skinned body meshes (SmartBone
							-- rigs load through RigVnsModel, a different path). Mesh renders at its native size
							-- (SpecialMesh.Scale=1); the Part.Size below is the weld/collision box.
							ObjectInstance = Instance.new("Part")
							ObjectInstance.Shape = Enum.PartType.Block
							local _sm = Instance.new("SpecialMesh")
							_sm.MeshType = Enum.MeshType.FileMesh
							_sm.MeshId = resolvedMeshId
							local _tex = Function.GetAsset(TEXTUREID)
							if type(_tex) == "string" and _tex ~= "" then _sm.TextureId = _tex end
							_sm.Parent = ObjectInstance
							_viaSpecialMesh = true
							if Function._showDeltaMeshNotice then Function._showDeltaMeshNotice() end
						end
						if not ObjectInstance then
							warn("[RoClothes] CreateMeshPartAsync failed for mesh:", MESHID, "resolved:", resolvedMeshId)
							return nil
						end
					end
					if Function.IsStaleOrGone(Data, RequestID) then return nil end  -- V4.3.452
					ObjectInstance:AddTag(System.RCTag)

					-- V4.3.214: route TextureID through Function.GetAsset (workspace-first via
					-- getcustomasset, fallback to rbxasset://). Without this, MeshPart-based
					-- clothes like Cow Bra / Cow Panty render as untextured gray when the active
					-- Roblox version's content folder is empty (post-update). GetAsset handles
					-- nil/empty input safely so clothes without a TextureID don't break.
					if not _viaSpecialMesh then
						-- MeshPart-only properties (SpecialMesh carries its own TextureId, set above).
						ObjectInstance.TextureID = Function.GetAsset(TEXTUREID)
						ObjectInstance.DoubleSided = DOUBLESIDED
					end
				elseif INSTANCE == "Part" then
					ObjectInstance = Instance.new("Part")
					ObjectInstance:AddTag(System.RCTag)
					ObjectInstance.Shape = SHAPE
				end

				local Color

				if COLOR["Color"] == "Parent" then
					Color = Parent.Color
				else
					Color = COLOR["Color"]
				end

				local H,S,V = Color:ToHSV()

				if COLOR["Tone"] == "Darker" then
					Color = Color3.fromHSV(H,S,V+(-DarkerColorPercentage * V/100))
				elseif COLOR["Tone"] == "Darker2" then
					Color = Color3.fromHSV(H,S,V+(-Darker2ColorPercentage * V/100))
				end

				ObjectInstance.Color = Color

				ObjectInstance.CanCollide = false
				ObjectInstance.CanQuery = false
				ObjectInstance.CanTouch = false
				ObjectInstance.Massless = true
				ObjectInstance.CustomPhysicalProperties = System.Physics.DefaultProperties

				ObjectInstance.Name = NAME
				ObjectInstance.Transparency = TRANSPARENCY
				if DataDetail.MeshBasePartInvisible and MESHBASEPARTTRANSPARENCY then
					ObjectInstance.Transparency = MESHBASEPARTTRANSPARENCY
				end
				ObjectInstance.Reflectance = REFLECTANCE
				ObjectInstance.Material = MATERIAL

				if Parent and not Function.IsParentNil(Parent) and not Function.FallenPartCheck(Parent) then
					ObjectInstance.CFrame = Parent.CFrame
				end
				local WeldInstance = Instance.new("Weld", ObjectInstance)
				WeldInstance.Name = NAME.." Weld"
				WeldInstance.Part0 = Parent
				WeldInstance.Part1 = ObjectInstance

				ObjectInstance.Size = SIZE

				WeldInstance.C0 = CFRAME

				WeldInstance.C1 = CFRAME1

				local detectRemoval
				detectRemoval = ObjectInstance.ChildRemoved:Connect(function(c)
					-- V4.3.424: was `ObjectInstance.Parent ~= nil` self-check, never fired during
					-- destroy (parent not nil mid-tear-down) so GlobalMaid:Remove leaked. Replaced
					-- with `IsDescendantOf(game)` for reliable destroy detection. See sibling
					-- comment at the L9395 detectRemoval block.
					if ObjectInstance:IsDescendantOf(game) then
						if c:IsA("Weld") and c.Part1 == ObjectInstance then
							Function.TryRecloneWeld(ObjectInstance, c)
						end
					else
						System.GlobalMaid:Remove(detectRemoval)
					end
				end)
				System.GlobalMaid:Give(detectRemoval)



				if DataDetail.MeshSizeLock == false then
					ObjectInstance.Size = Function.Vector3Multiply(SIZE, {X = XMultiply, Y = YMultiply, Z = ZMultiply})
					WeldInstance.C0 = Function.CFrameMultiply(CFRAME, {X = XMultiply, Y = YMultiply, Z = ZMultiply})
					WeldInstance.C1 = Function.CFrameMultiply(CFRAME1, {X = XMultiply, Y = YMultiply, Z = ZMultiply})
				end


				ObjectInstance.Parent = Parent

				if FUNCTION ~= "" then
					if typeof(FUNCTION) == "string" then
						if Function[FUNCTION] then pcall(Function[FUNCTION], ObjectInstance, Character, Extra, Data) end
					elseif typeof(FUNCTION) == "table" then
						for i, v in pairs(FUNCTION) do
							if Function[v] then pcall(Function[v], ObjectInstance, Character, Extra, Data) end
						end
					end
				end
				DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[ObjectInstance] = {Size = SIZE, CFrame = CFRAME, CFrame1 = CFRAME1, Base = BodyPart, Weld = WeldInstance}
				DataDetail.ExecutionMaid:Give(ObjectInstance)
				return ObjectInstance
			end 
		end

	end

	-- V4.3.356: direct strip applied to the LIVE Player.Character - independent (see Changelog for full rationale)
	function Function.ApplyStripToLiveCharacter(playerName)
		local _ply = PS:FindFirstChild(playerName)
		if not _ply then return end
		local _char = _ply.Character
		if not _char then return end
		local _pd = PlayerData[playerName]
		if not _pd then return end
		_pd._strippedAccessories = _pd._strippedAccessories or setmetatable({}, {__mode = "k"})
		local _strip = _pd.StripCategories
		-- (a) RESTORE: re-parent stashed accessories whose category is no
		--     longer set (or strip cleared entirely).
		for acc in pairs(_pd._strippedAccessories) do
			if acc and acc.Parent == nil then
				local _atName
				pcall(function()
					local _at = acc.AccessoryType
					_atName = _at and _at.Name or nil
				end)
				if not (_atName and _strip and _strip[_atName]) then
					pcall(function() acc.Parent = _char end)
					_pd._strippedAccessories[acc] = nil
				end
			else
				_pd._strippedAccessories[acc] = nil
			end
		end
		-- (b) STRIP: orphan live accessories in stripped categories.
		--     V4.3.361: skip accessories tagged `_RC_FromHD = true` - those are
		--     ones the script itself just equipped via HumanoidDescriptionLoader
		--     (catalog accessory equip path). Stripping them would defeat the
		--     user's equip click. Strip is for the user's PRE-EXISTING default
		--     avatar accessories only.
		if _strip and next(_strip) then
			for _, child in ipairs(_char:GetChildren()) do
				if child:IsA("Accessory") then
					local _isOurs = false
					pcall(function() _isOurs = child:GetAttribute("_RC_FromHD") == true end)
					if not _isOurs then
						local _atName
						pcall(function()
							local _at = child.AccessoryType
							_atName = _at and _at.Name or nil
						end)
						if _atName and _strip[_atName] then
							_pd._strippedAccessories[child] = true
							pcall(function() child.Parent = nil end)
						end
					end
				end
			end
		end
	end

	function Function.CharacterFunction(Character, Data)
		local DataDetail = PlayerData[Data]
		-- V4.3.355: strip default avatar accessories per category BEFORE the descendant (see Changelog for full rationale)
		if DataDetail then
			DataDetail._strippedAccessories = DataDetail._strippedAccessories or setmetatable({}, {__mode = "k"})
			local _strip = DataDetail.StripCategories
			-- (a) RESTORE: any previously-stripped accessory whose category is no
			--     longer in StripCategories (or strip cleared entirely) - re-parent
			--     to Character. Walks the weak-keyed stash so dead refs auto-clean.
			for acc, _ in pairs(DataDetail._strippedAccessories) do
				if acc and acc.Parent == nil then
					local _atName
					pcall(function()
						local _at = acc.AccessoryType
						_atName = _at and _at.Name or nil
					end)
					if not (_atName and _strip and _strip[_atName]) then
						pcall(function() acc.Parent = Character end)
						DataDetail._strippedAccessories[acc] = nil
					end
				else
					-- Accessory is gone (player respawned + Roblox GC'd it). Drop the entry.
					DataDetail._strippedAccessories[acc] = nil
				end
			end
			-- (b) STRIP: any LIVE accessory on the character whose category is set in
			--     StripCategories - orphan via Parent=nil + stash.
			--     V4.3.361: skip accessories tagged `_RC_FromHD = true` (script-
			--     equipped via HumanoidDescriptionLoader). Same fix as the live-
			--     character path above.
			if _strip and next(_strip) then
				for _, child in ipairs(Character:GetChildren()) do
					if child:IsA("Accessory") then
						local _isOurs = false
						pcall(function() _isOurs = child:GetAttribute("_RC_FromHD") == true end)
						if not _isOurs then
							local _atName
							pcall(function()
								local _at = child.AccessoryType
								_atName = _at and _at.Name or nil
							end)
							if _atName and _strip[_atName] then
								DataDetail._strippedAccessories[child] = true
								pcall(function() child.Parent = nil end)
							end
						end
					end
				end
			end
		end
		local CharacterAttachment = {}
		local CollectedAccessories = {}

		for _, v in pairs(Character:GetDescendants()) do
			if v:IsA("Attachment") and v.Parent.Name ~= "Handle" and System.BodyPartSize[v.Parent.Name] and not CharacterAttachment[v.Name] then
				CharacterAttachment[v.Name] = v
			elseif v:IsA("Accessory") then
				table.insert(CollectedAccessories, v)
			end
		end

		-- Process accessories after the single pass (CharacterAttachment is now fully populated)
		for _, v in pairs(CollectedAccessories) do
			local Handle = v:FindFirstChildOfClass("Part") or v:FindFirstChildOfClass("MeshPart")

			if Handle then
				if DataDetail.CurrentBundle ~= "nil" then
					--Handle.Transparency = 1

					DataDetail.CurrentPartList.ParentTransparency[Handle] = {D = 0, T = 1}
				else
					local Attachment = Handle:FindFirstChildOfClass("Attachment")
					if Attachment then
						local SpecialMesh = Handle:FindFirstChildOfClass("SpecialMesh")
						local Weld = Handle:FindFirstChildOfClass("Weld") or Handle:FindFirstChildOfClass("WeldConstraint")
						local ParentAttachment = CharacterAttachment[Attachment.Name]

						if Weld and SpecialMesh and ParentAttachment and Attachment then

							local HandleParent = ParentAttachment.Parent
							local Size = HandleParent.Size

							if Size and BodyPartSize[HandleParent.Name] then
								local XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(Size, BodyPartSize[HandleParent.Name])

								local AttachCF = Attachment.CFrame
								local Scale = SpecialMesh.Scale

								Handle:SetAttribute("_RC_HPBaseTransparency", Handle.Transparency)
								DataDetail.CurrentPartList.RealtimeUpdateList.Accessory[Handle] = {Scale = Scale, SpecialMesh = SpecialMesh, Size = Size, CFrame = AttachCF, Attachment = Attachment, ParentAttachment = ParentAttachment, Base = HandleParent, Weld = Weld}
							end
						end
					end
				end
			end
		end

		return CharacterAttachment
	end

	local BodyColorPart = {
		HeadColor3 = "Head",
		TorsoColor3 = "Torso",
		LeftArmColor3 = "Left Arm",
		RightArmColor3 = "Right Arm",
		LeftLegColor3 = "Left Leg",
		RightLegColor3 = "Right Leg",
	}

	function Function.BodyColorForceSet(Character, Color)
		for i, v in pairs(BodyColorPart) do
			local Base = Character:FindFirstChild(v)

			if Base then
				Base.Color = Color
			end
		end
	end

	function Function.BodyColorSet(Character, BodyColor)
		for i, v in pairs(BodyColorPart) do
			local Base = Character:FindFirstChild(v)

			if Base then
				Base.Color = BodyColor[i]
			end
		end
	end

	-- V4.3.446: hoisted from a per-call local inside HumanoidDescriptionLoader (V4.3.445)
	-- to a Function-scope helper so BodyColorsFunction (regular-bundle path) AND
	-- the BodyColorForceSet/SkinTone path can both call it. Without this hoist,
	-- the V4.3.445 R15 fallback only protected catalog bundles - regular Krul/community
	-- bundles still stranded the skin on R15 avatars, and SkinTone changes had no
	-- snapshot at all. Prefers BodyColors instance reads; falls back to per-part
	-- .Color reads mapping both R6 (Head/Torso/Left Arm) AND R15 (UpperTorso/
	-- LeftUpperArm) part names. Only writes when OriginalBodyColors is nil so
	-- consecutive bundle swaps don't overwrite the truly-original snapshot.
	function Function.SnapshotOriginalBodyColors(DataDetail, Character)
		if not DataDetail or DataDetail.OriginalBodyColors then return end
		local _realChar = DataDetail.RealCharacter or Character
		if not _realChar then return end
		local _realBC = _realChar:FindFirstChildOfClass("BodyColors")
		if _realBC then
			DataDetail.OriginalBodyColors = {
				HeadColor3     = _realBC.HeadColor3,
				TorsoColor3    = _realBC.TorsoColor3,
				LeftArmColor3  = _realBC.LeftArmColor3,
				RightArmColor3 = _realBC.RightArmColor3,
				LeftLegColor3  = _realBC.LeftLegColor3,
				RightLegColor3 = _realBC.RightLegColor3,
			}
			return
		end
		-- R15 / no-BodyColors fallback: read part .Color directly.
		local function _pc(name, fallback)
			local p = _realChar:FindFirstChild(name)
			if p and p:IsA("BasePart") then return p.Color end
			return fallback
		end
		local _torso = _pc("UpperTorso", _pc("Torso", Color3.new(1,1,1)))
		DataDetail.OriginalBodyColors = {
			HeadColor3     = _pc("Head", _torso),
			TorsoColor3    = _torso,
			LeftArmColor3  = _pc("LeftUpperArm",  _pc("Left Arm",  _torso)),
			RightArmColor3 = _pc("RightUpperArm", _pc("Right Arm", _torso)),
			LeftLegColor3  = _pc("LeftUpperLeg",  _pc("Left Leg",  _torso)),
			RightLegColor3 = _pc("RightUpperLeg", _pc("Right Leg", _torso)),
		}
	end

	function Function.BodyColorsFunction(Character, SelectBundle, Data)
		local DataDetail = PlayerData[Data]
		if Bundle[SelectBundle] and Bundle[SelectBundle]["Body Color"] ~= nil and DataDetail.BundleBodyColor then
			local RealChar = DataDetail.RealCharacter or Character
			-- V4.3.446: use the shared snapshot helper (R15-safe). Pre-V4.3.446 this
			-- branch only read RealBodyColors and silently skipped the snapshot when
			-- the avatar had no BodyColors instance - leaving R15 users with bundle
			-- skin permanently stuck (same V4.3.445 fix class but for non-catalog).
			Function.SnapshotOriginalBodyColors(DataDetail, Character)
			local RealBodyColors = RealChar:FindFirstChildOfClass("BodyColors")

			local BC_NORM = {
				Head="HeadColor3", Torso="TorsoColor3",
				LeftArm="LeftArmColor3", RightArm="RightArmColor3",
				LeftLeg="LeftLegColor3", RightLeg="RightLegColor3",
			}
			local BodyColors = Character:FindFirstChildOfClass("BodyColors") or Instance.new("BodyColors", Character)
			for i, v in pairs(Bundle[SelectBundle]["Body Color"]) do
				BodyColors[BC_NORM[i] or i] = v
			end
			Function.BodyColorSet(Character, BodyColors)

			if RealChar ~= Character then
				local RealBC = RealChar:FindFirstChildOfClass("BodyColors") or Instance.new("BodyColors", RealChar)
				for i, v in pairs(Bundle[SelectBundle]["Body Color"]) do
					RealBC[BC_NORM[i] or i] = v
				end
				Function.BodyColorSet(RealChar, RealBC)
			end
		end
	end

	function Function.AccessoryAdd(Character, v, CharacterAttachment, Data)
		local DataDetail = PlayerData[Data]
		local CAccessory = v:Clone()
		local CHandle = CAccessory:FindFirstChildOfClass("Part") or CAccessory:FindFirstChildOfClass("MeshPart")
		if not CHandle then return end
		local CAttachment = CHandle:FindFirstChildOfClass("Attachment")
		if not CAttachment then return end
		local CSpecialMesh = CHandle:FindFirstChildOfClass("SpecialMesh")
		CAccessory:AddTag(System.RCTag)
		Function.ApplyAssets(CAccessory)
		DataDetail.ExecutionMaid:Give(CAccessory)

		DataDetail.CurrentPartList["Accessory"][CAccessory] = CAccessory

		if isTailAccessory(CAccessory) then
			setUpTailAccessory(Character, CAccessory, Data)
		end

		local CParentAttachment = CharacterAttachment[CAttachment.Name]

		if CParentAttachment then
			local HandleParent = CParentAttachment.Parent
			local Size = HandleParent.Size
			local HandleSize = CHandle.Size

			local BodySize = BodyPartSize[HandleParent.Name]
			local CalcSize = Size
			local specialHead = false
			if not BodySize then
				if HandleParent.Name == "UpperTorso" or HandleParent.Name == "LowerTorso" then
					BodySize = BodyPartSize["Torso"]
				elseif HandleParent.Name == "LeftUpperArm" or HandleParent.Name == "LeftLowerArm" then -- H-1 fix: was "RightUpperArm" (copy-paste error) - LeftUpperArm was never reached, nil BodySize crash
					BodySize = BodyPartSize["Left Arm"]
				elseif HandleParent.Name == "RightUpperArm" or HandleParent.Name == "RightLowerArm" then
					BodySize = BodyPartSize["Right Arm"]
				elseif HandleParent.Name == "LeftUpperLeg" or HandleParent.Name == "LeftLowerLeg" then
					BodySize = BodyPartSize["Left Leg"]
				elseif HandleParent.Name == "RightUpperLeg" or HandleParent.Name == "RightLowerLeg" then
					BodySize = BodyPartSize["Right Leg"]
				end
			elseif HandleParent.Name == "Head" and HandleParent:IsA("MeshPart") then
				if HandleParent:FindFirstChild("OriginalSize") then
					BodySize = HandleParent:FindFirstChild("OriginalSize").Value
				else
					BodySize = BodyPartSize["HeadMeshFix"]
				end
			elseif HandleParent.Name == "Head" and HandleParent:FindFirstChildOfClass("SpecialMesh") then
				local SM:SpecialMesh = HandleParent:FindFirstChildOfClass("SpecialMesh")
				if SM.MeshType == Enum.MeshType.Head then
					specialHead = true
					BodySize = BodyPartSize["HeadScale"]
				else
					CalcSize = SM.Scale
					BodySize = BodyPartSize["HeadScale"]
				end
			end

			local XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(CalcSize, BodySize)
			if specialHead == true then
				local SM:SpecialMesh = HandleParent:FindFirstChildOfClass("SpecialMesh")

				if CalcSize.X > CalcSize.Z then
					CalcSize = Vector3.new(CalcSize.Z,CalcSize.Y,CalcSize.Z)
				end
				if CalcSize.Z > CalcSize.X then
					CalcSize = Vector3.new(CalcSize.X,CalcSize.Y,CalcSize.X)
				end
				XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(CalcSize, BodySize)

				local S = SM.Scale
				if S.X > S.Z then
					S = Vector3.new(S.Z,S.Y,S.Z)
				end
				if S.Z > S.X then
					S = Vector3.new(S.X,S.Y,S.X)
				end
				local XMS, YMS, ZMS = Function.MultiplyCalculate(S, vector3New(1.25,1.25,1.25))

				XMultiply = XMultiply*XMS
				YMultiply = YMultiply*YMS
				ZMultiply = ZMultiply*ZMS
			end

			local CAttachCF = CAttachment.CFrame
			local PAttachCF = AttachmentCFrame[CParentAttachment.Name] or CFrame.new()  -- BUGFIX (bug-scan V4.5.17): guard nil - a non-standard/renamed parent-attachment name (common on a host-game NPC/clone target) is absent from the preset -> this was nil -> `.Position` threw below (swallowed by the per-child pcall) -> that accessory silently never appeared. Mirrors the already-hardened sibling attachment site.
			local Scale = CSpecialMesh and CSpecialMesh.Scale or Vector3.one

			if DataDetail.OriginalAttachmentCFrames == nil then
				DataDetail.OriginalAttachmentCFrames = {}
			end
			if DataDetail.OriginalAttachmentCFrames[CParentAttachment] == nil then
				DataDetail.OriginalAttachmentCFrames[CParentAttachment] = CParentAttachment.CFrame
			end

			if DataDetail.AccessorySizeLock == false then
				CHandle.Size = Vector3.new(HandleSize.X * XMultiply, HandleSize.Y * YMultiply, HandleSize.Z * ZMultiply)
				if CSpecialMesh then
					CSpecialMesh.Scale = Vector3.new(Scale.X * XMultiply, Scale.Y * YMultiply, Scale.Z * ZMultiply)
				end
				CAttachment.CFrame = CFrame.new(CAttachCF.Position.X * XMultiply, CAttachCF.Position.Y * YMultiply, CAttachCF.Position.Z * ZMultiply) * CAttachCF.Rotation
				if not DataDetail.CurrentPartList.physicsTails[CAccessory] then
					CParentAttachment.CFrame = CFrame.new(PAttachCF.Position.X * XMultiply, PAttachCF.Position.Y * YMultiply, PAttachCF.Position.Z * ZMultiply) * PAttachCF.Rotation
				end
			else
				CHandle.Size = HandleSize
				if CSpecialMesh then
					CSpecialMesh.Scale = Scale
				end
			end

			CHandle.CanCollide = false
			CHandle.CanQuery = false
			CHandle.CanTouch = false
			CHandle.Massless = true
			CHandle.CustomPhysicalProperties = System.Physics.DefaultProperties

			CAccessory.Parent = Character
			v:Destroy()

			CHandle.CFrame = CParentAttachment.Parent.CFrame
			local Weld = Instance.new("Weld", CHandle)
			Weld.Part0 = CHandle
			Weld.Part1 = CParentAttachment.Parent

			Weld.C0 = CAttachment.CFrame
			Weld.C1 = CParentAttachment.CFrame

			local detectRemoval
			detectRemoval = CHandle.ChildRemoved:Connect(function(c)
				-- V4.3.496: was `if CHandle.Parent ~= nil then ... else <cleanup>`.
				-- Audit Pass B #2: `Parent` is not nil during mid-destroy (it stays
				-- pointing at the soon-to-be-orphan parent), so the cleanup branch
				-- never fired and the connection leaked. V4.3.424 fixed sibling
				-- sites with IsDescendantOf(game); this site was missed.
				if CHandle:IsDescendantOf(game) then
					if c:IsA("Weld") and c.Part0 == CHandle then
						Function.TryRecloneWeld(CHandle, c)
					end
				else
					-- V4.3.518 Fix 4: detectRemoval is GlobalMaid-tracked now; direct :Disconnect
					-- is sufficient. The maid will skip already-disconnected handles at teardown.
					-- V4.3.520 Fix 16: gate the in-handler disconnect since GlobalMaid (V4.3.518
					-- Fix 4) also disconnects at teardown. Calling Disconnect on an already-closed
					-- RBXScriptConnection raises on Volt/Xeno. Connected check avoids the second call.
					if detectRemoval and detectRemoval.Connected then
						detectRemoval:Disconnect()
					end
				end
			end)
			-- V4.3.518 Fix 4: route through GlobalMaid instead of AllConnect. The cleanup
			-- path's table.find+remove was O(N) on every weld-removal; GlobalMaid:Give
			-- handles teardown without the linear scan. Matches sibling sites L11984/L12183.
			-- V4.3.521 Fix 8: route detectRemoval through DataDetail.ExecutionMaid instead
			-- of GlobalMaid. The connection's lifetime should match the accessory's, not the
			-- script's. V4.3.518 Fix 4 + V4.3.520 Fix 16 incorrectly tied it to script-wide
			-- teardown, causing unbounded accumulation of dead Connect handles in GlobalMaid
			-- across many re-equip cycles.
			if DataDetail and DataDetail.ExecutionMaid and DataDetail.ExecutionMaid.Give then
				DataDetail.ExecutionMaid:Give(detectRemoval)
			else
				-- Fallback if ExecutionMaid is unavailable at this point
				System.GlobalMaid:Give(detectRemoval)
			end

			CHandle:SetAttribute("_RC_HPBaseTransparency", CHandle.Transparency)
			DataDetail.CurrentPartList.RealtimeUpdateList.Accessory[CHandle] = {Scale = Scale, SpecialMesh = CSpecialMesh, Size = Size, CFrame = CAttachCF, Attachment = CAttachment, ParentAttachment = CParentAttachment, Base = HandleParent, Weld = Weld}
		end
	end

	-- V4.3.536 Fix 1: optional `SharedDeadline` (6th arg, monotonic os-clock timestamp).
	-- When the caller invokes HumanoidDescriptionSet twice sequentially (acc list +
	-- tail list at L14330-L14331 and the CatalogLoader branch at L14573-L14574),
	-- each call paid its own 5s wait independently - a fully-dead bundle stalled
	-- for ~10s before any downstream HumanoidDescriptionLoader spun up. Threading
	-- the same Deadline through both calls caps total wait at 5s. Workers spawned
	-- at L13447 still drain in background per V4.3.327; only the SYNCHRONOUS join
	-- wait at L13585 is shortened. Default (nil) preserves pre-V4.3.536 per-call
	-- 5s semantics for any caller we missed during the rewire.
	function Function.HumanoidDescriptionSet(AccessoryList, ClothesList, HumanoidDescription, Data, RequestID, SharedDeadline)
		local IsAdded = false
		-- V4.3.534 F15: track accessory-specific landing separately from the conflated
		-- `IsAdded`. Pre-fix the single `IsAdded` flag let "clothes landed, accessories
		-- all failed" be indistinguishable from "everything landed." When the per-
		-- accessory pcall workers yield past the 5-second cap at L13510-L13512 (slow
		-- cold MPS:GetProductInfo, network blip, etc.), the function returns with
		-- `IsAdded` true (from clothes) and `_accHD` slot-empty in caller - caller
		-- dispatched ApplyDescription against an empty accessory description and the
		-- workers' later writes were no-ops (ApplyDescription is a snapshot).
		-- Now we surface the silent-drop case as a diag + warn so the user sees a
		-- diagnostic instead of a mystery missing-accessories character.
		local _accAdded = false
		local _accListLen = 0
		local _layeredAcc = {}  -- V4.4.x: layered-clothing accessories collected during classification, applied via one guarded SetAccessories after the join barrier (string members throw for these types).

		if AccessoryList ~= nil then
			for _ in pairs(AccessoryList) do _accListLen = _accListLen + 1 end
			local amountFinished = 0
			-- V4.3.361: REMOVED V4.3.355's strip filter. The filter was dropping
			-- accessory IDs whose category was in pd.StripCategories before they
			-- reached HumanoidDescription, which broke the user-expected mental
			-- model: "strip default avatar items, then equip NEW catalog items
			-- on top." Pre-fix, with Strip Hair on, equipping any catalog Hair
			-- silently no-op'd - the ID never made it into HD, no accessory
			-- spawned. Strip should only target the user's pre-existing default
			-- avatar accessories (handled by Function.ApplyStripToLiveCharacter),
			-- NOT script-explicitly-equipped catalog items. Function.HumanoidDescriptionLoader
			-- now tags accessories it adds with `_RC_FromHD = true`, and
			-- ApplyStripToLiveCharacter skips tagged ones.
			-- V4.3.443: persistent known-dead-ID cache. Pre-fix every re-equip of a
			-- bundle with content-deleted accessories re-paid the MPS:GetProductInfo
			-- call (potentially 30s timeout per dead ID) only to fail again. Now we
			-- record dead IDs in `Function._knownDeadIds` and skip them at the top of
			-- the loop. Cap at 4096 entries (same FIFO pattern as V4.3.428) so the
			-- set doesn't grow unbounded across a session.
			Function._knownDeadIds = Function._knownDeadIds or {}
			local _deadCount = 0
			local _liveCount = 0
			for _, Id in pairs(AccessoryList) do
				-- V4.3.440: validate Id is a positive integer before spawning. Pre-fix a
				-- non-numeric / negative / fractional / huge Id flowed straight into
				-- MPS:GetProductInfo (30s timeout against Roblox catalog endpoint) and
				-- could pollute _catalogAssetTypeCache with a bogus key. Common trigger:
				-- bundle JSON imports with hand-edited or migrated entries.
				local _idNum = tonumber(Id)
				if not _idNum or _idNum <= 0 or _idNum ~= math.floor(_idNum) or _idNum >= 2^53 then
					warn('[RoClothes] Skipping invalid accessory ID: '..tostring(Id))
					continue
				end
				-- V4.3.443: skip known content-deleted IDs (no MPS call, no spawn).
				if Function._knownDeadIds[_idNum] then
					_deadCount = _deadCount + 1
					continue
				end
				_liveCount = _liveCount + 1
				task.spawn(function()
					local success, output = pcall(function()
						-- V4.3.326: skip the 30s-timeout-prone MPS:GetProductInfo (see Changelog for full rationale)
						local cachedTypeId = Function._catalogAssetTypeCache and
							Function._catalogAssetTypeCache[tonumber(Id) or Id]
						local typeId
						if cachedTypeId then
							typeId = cachedTypeId
						else
							-- V4.3.504: distinguish transport throws (network blip, timeout, 429)
							-- from real "asset not found" errors. Pre-fix a flaky network would
							-- propagate the throw → caught by outer pcall → _isUnmapped=false →
							-- the healthy ID got registered as content-deleted permanently.
							local _gpOk, _gpResOrErr = pcall(MPS.GetProductInfo, MPS, Id)
							if _gpOk then
								local AccessoryInfo = _gpResOrErr
								typeId = AccessoryInfo.AssetTypeId
								-- Backfill cache so a re-execute / re-apply skips the MPS roundtrip.
				if Function._catalogAssetTypeCache and typeId then
					Function._catalogTypeCachePut(Id, typeId)
								end
							else
								-- V4.4.x EXECUTOR-SUPPORT: MPS:GetProductInfo is blocked / timing out / HTTP-400ing
								-- on lower-quality executors (Volt allowed it, "random" executors don't), so the
								-- accessory never got a type and never equipped. Before giving up, resolve the
								-- SAME AssetTypeId via the executor-HTTP economy.roproxy path (CatalogFetchAssetDetails)
								-- - no engine MPS call. This is what lets catalog + bundle accessories equip where
								-- GetProductInfo is unavailable. It also backfills _catalogAssetTypeCache itself,
								-- so the next equip is a straight cache hit.
								local _pxOk, _px = pcall(Function.CatalogFetchAssetDetails, Id)
								if _pxOk and type(_px) == "table" and _px.assetType then
									typeId = _px.assetType
					if Function._catalogAssetTypeCache then
						Function._catalogTypeCachePut(Id, typeId)
									end
								else
									-- Neither MPS nor the proxy resolved a type: preserve the original
									-- transport-vs-not-found classification exactly (the outer handler relies
									-- on these sentinels to decide dead-ID caching vs retry).
									local _es = tostring(_gpResOrErr or "")
									-- V4.3.505: anchor / word-boundary the transport substring checks so they
									-- can't collide with payload data carrying these tokens. Status codes use a
									-- bounded HTTP %d%d%d pattern instead of bare "429".
									local _looksTransport =
										_es:find("HttpError", 1, true) or
										_es:match("[Tt]imeout") or
										_es:find("Too many", 1, true) or _es:match("HTTP%s+%d%d%d") or _es:find(" 429", 1, true) or
										_es:find("ConnectFail", 1, true) or _es:find("DNS", 1, true) or
										_es:match("[Dd]isconnected") or
										-- [AUDIT - precautionary] a hooked/blocked MPS:GetProductInfo (`:7455/:7405 BLOCKED`) is a CAPABILITY
										-- gap, not a content-deleted asset - treat as transport so a valid ID is RETRIED next equip, not
										-- permanently disk-cached to _knownDeadIds. (MPS usually surfaces HTTP errors above; this is belt-and-braces.)
										_es:lower():find("blocked", 1, true) or _es:find("7455", 1, true) or _es:find("7405", 1, true)
									if _looksTransport then
										error("__TRANSPORT__[RoClothes] MPS:GetProductInfo transport failure for " .. tostring(Id) .. ": " .. _es)
									end
									-- Non-transport throw: re-raise (legitimate "asset not found").
									error(_es)
								end
							end
						end
						-- V4.3.504: bail if the user's RID was superseded during the MPS yield.
						-- Pre-fix stale equip data could write to HumanoidDescription[Type] or
						-- poison _catalogAssetTypeCache long after the player switched bundles.
						if Function.IsStaleOrGone and Function.IsStaleOrGone(Data, RequestID) then return end
						local Type = System.AccessoryType[typeId]  -- V4.3.535 Opt-3: inlined (cold path, alias dropped)
						-- V4.3.361: dropped V4.3.355's strip-category gate here (see (see Changelog for full rationale)
						-- V4.3.425: guard Type == nil. AccessoryType[typeId] returns nil
						if Type == nil then
							-- Evict the bad cache entry so a re-fetch may map the typeId
							-- correctly on next attempt (e.g. user updates the script).
							if Function._catalogAssetTypeCache then
								Function._catalogTypeCacheRemove(Id)
							end
							-- V4.3.446: prefix error with a sentinel so the outer pcall
							-- handler can distinguish "unmapped type - recoverable" from
							-- "MPS failure - content-deleted". Without this prefix the
							-- V4.3.443 dead-ID cache poisoned legitimate accessories whose
							-- AssetTypeId Roblox added after the script's AccessoryType map
							-- was last updated - the next equip skipped them entirely with
							-- no recovery path.
							error("__UNMAPPED__[RoClothes] Accessory ID " .. tostring(Id) .. " has unmapped AssetTypeId=" .. tostring(typeId) .. " - Roblox added a new accessory class or this isn't an Accessory asset.")
						end

						-- V4.4.x EXECUTOR-SUPPORT: layered-clothing types (TShirt..DressSkirt, AssetTypeId
						-- 64-72) are NOT valid HumanoidDescription string members - writing e.g.
						-- HumanoidDescription.DressSkirtAccessory THROWS "not a valid member" (caught by this
						-- pcall → the item was silently dropped, sometimes dead-cached). Collect them for a
						-- single guarded SetAccessories after the barrier; only rigid types use string members.
						local _layeredEnum = System.LayeredAccessoryEnum and System.LayeredAccessoryEnum[typeId]
						if _layeredEnum then
							_layeredAcc[#_layeredAcc + 1] = { Order = #_layeredAcc + 1, AssetId = _idNum, AccessoryType = _layeredEnum, IsLayered = true }
						elseif HumanoidDescription[Type] == "" then
							HumanoidDescription[Type] = Id
						else
							HumanoidDescription[Type] = HumanoidDescription[Type]..", "..Id
						end
					end)
					if not success then
						-- V4.3.446: distinguish unmapped-AssetTypeId (recoverable on next
						-- script update) from genuine MPS failures (content-deleted). The
						-- unmapped case should NOT be cached as dead - caching it would
						-- permanently mask legitimate accessories whose type Roblox just
						-- added. Only register actual MPS-failure IDs.
						local _outStr = tostring(output)
						-- V4.3.505: anchored matching + UNMAPPED-first priority. Pre-fix the
						-- substring `:find` could collide with sentinel tokens that legitimately
						-- appear inside the OTHER classification's message body. Anchor both
						-- to the message prefix (sentinels are always at column 1 of the error
						-- string per the producing `error()` calls above).
						-- Roblox's error() prepends "<script>:<line>: " before the message; match
						-- the sentinel anywhere it could appear after the location prefix but NOT
						-- as arbitrary substring (sentinels are bracketed by `__` on both sides).
						local _isUnmapped  = _outStr:match("__UNMAPPED__%[") ~= nil
						-- V4.3.504: transport sentinel - flaky network must NOT poison dead-ID cache.
						local _isTransport = (not _isUnmapped) and (_outStr:match("__TRANSPORT__%[") ~= nil)
						local _idn = tonumber(Id)
						if _idn and not _isUnmapped and not _isTransport then
							-- V4.3.443: register the dead ID so re-equips skip the MPS roundtrip.
							-- V4.3.496: O(1) running counter `_knownDeadIdsCount` replaces the
							-- O(N=4096) pairs walk that fired per failing accessory (audit Pass D #3).
							if Function._knownDeadIds[_idn] == nil then
								if (Function._knownDeadIdsCount or 0) >= 4096 then
									for k in pairs(Function._knownDeadIds) do
										Function._knownDeadIds[k] = nil
										Function._knownDeadIdsCount = (Function._knownDeadIdsCount or 1) - 1
										break
									end
								end
								Function._knownDeadIds[_idn] = true
								Function._knownDeadIdsCount = (Function._knownDeadIdsCount or 0) + 1
								Function._knownDeadIdsDirty = true  -- V4.3.457: schedule disk flush
								-- V4.3.506 telemetry: first time we've seen this accessory die.
								Function.diag("bundle.dead_id_skip", { count = Function._knownDeadIdsCount or 1, isFirstSee = true })
							end
						end
						if _isUnmapped then
							warn('Accessory ID "'..Id..'" has unmapped AssetType - not cached as dead, will retry on next equip. ('.. _outStr .. ")")
						elseif _isTransport then
							-- V4.3.504: transport failure - not the asset's fault; never cached.
							warn('Accessory ID "'..Id..'" MPS transport failure - not cached as dead, will retry on next equip. ('.. _outStr .. ")")
						else
							warn('Accessory ID "'..Id..'" is invalid. Please make sure ID is an ACCESSORY and is not content deleted. ('.. _outStr .. ")")
						end
					else
						IsAdded = true
						-- V4.3.534 F15: mark accessory-specific landing.
						_accAdded = true
					end
					amountFinished +=1
				end)
			end
			-- V4.3.443: aggregated diagnostic. Helps the user understand why a bundle
			-- looks partial - silent miss was the original "whackamole" complaint.
			if _deadCount > 0 then
				warn('[RoClothes] Bundle skipped '..tostring(_deadCount)..' known-dead accessory ID(s); '..tostring(_liveCount)..' live ID(s) queued')
			end
			-- V4.3.506 telemetry: bundle apply queued (live + dead counts).
			Function.diag("bundle.equip_complete", { accCount = _liveCount, deadCount = _deadCount })
			local _alLen = _liveCount  -- V4.3.443: only wait on live IDs, not skipped dead ones
			-- V4.3.327: cap the accessory-resolution wait at ~8 seconds. A single (see Changelog for full rationale)
			-- V4.3.457: shorten 8s → 5s. With `_knownDeadIds` now persisted to disk,
			-- the second-session-onward case (dead IDs already cached) never enters
			-- this wait - the workers don't even spawn for cached-dead IDs. The
			-- first-session case sees fewer dead-ID timeouts on average (faster
	  -- MPS asset-not-found responses tend to come in under 5s). Still
			-- generous for legitimate slow networks; in-flight workers continue
			-- registering dead IDs in the background after we return.
			local _waitStart = (tick and tick()) or os.clock()  -- V4.3.348: tick() fallback
			-- V4.3.536 Fix 1: shared-deadline path. If SharedDeadline (6th arg) is
			-- supplied, use it as the absolute cutoff so both this call and the
			-- caller's NEXT HumanoidDescriptionSet call share the same 5s budget.
			-- Default (no SharedDeadline) preserves the per-call 5s cap.
			local _deadlineNow = function() return (tick and tick()) or os.clock() end
			repeat task.wait() until amountFinished >= _alLen
				or (SharedDeadline and _deadlineNow() >= SharedDeadline)
				or (not SharedDeadline and (_deadlineNow() - _waitStart) > 5)  -- V4.3.457: was 8
				or (RequestID and Data and PlayerData[Data] and RequestID ~= PlayerData[Data].LastRequestID)
			-- V4.3.534 F15: surface the silent-drop case. If we had live accessory work
			-- but NONE of the workers reported success by the wait cap, the caller's
			-- HumanoidDescription will be missing all accessory slots - emit a warn +
			-- diag so the user gets a real diagnostic instead of an unexplained-
			-- missing-accessory character. _accListLen excludes invalid IDs (the
			-- `continue` skip at L13366) and known-dead IDs (L13371), so this fires
			-- only on the genuine "live workers timed out / all failed" case.
			-- V4.4.x EXECUTOR-SUPPORT: apply the collected layered-clothing accessories via the ONE
			-- valid path (SetAccessories with an explicit Enum.AccessoryType). Runs after the join
			-- barrier so every layered worker has landed. `false` = set ONLY layered accessories and
			-- LEAVE the rigid string-member accessories (Hat/Hair/etc.) untouched. Fully pcall-guarded:
			-- if an executor's HumanoidDescription lacks SetAccessories or rejects the call, the rigid
			-- accessories still apply - worst case layered clothing just doesn't show (today's behaviour),
			-- never a regression to the rest of the equip.
			if #_layeredAcc > 0 then
				local _laOk, _laErr = pcall(function() HumanoidDescription:SetAccessories(_layeredAcc, false) end)
				if _laOk then
					IsAdded = true
					_accAdded = true
				else
					warn("[RoClothes] SetAccessories (layered clothing) failed - layered items skipped, rigid accessories unaffected: " .. tostring(_laErr))
					pcall(Function.diag, "hd.layered_setaccessories_failed", { err = tostring(_laErr):sub(1, 256), count = #_layeredAcc })
				end
			end
			if _liveCount > 0 and not _accAdded then
				warn(string.format(
					"[RoClothes] HumanoidDescriptionSet: %d live accessory worker(s) queued but NONE landed within 5s - "
					.. "cold MPS:GetProductInfo, network issue, or every ID actually content-deleted. "
					.. "Character will spawn without these accessories.", _liveCount))
				pcall(Function.diag, "hd.acc_all_dropped", {
					queued = _liveCount,
					completed = amountFinished,
					-- V4.3.536 telemetry: ms remaining on shared deadline at return.
					-- Near-zero across N bundles = Fix #1 cap firing on dead bundles.
					deadlineRemainingMs = SharedDeadline and math.max(0, math.floor((SharedDeadline - _deadlineNow()) * 1000)) or -1,
				})
			end
		end

		if ClothesList ~= nil then
			for Type, Id in pairs(ClothesList) do
				if (Type == "Shirt" or Type == "Pants" or Type == "ShirtGraphic") and Id ~= "" and Id ~= 0 and Id ~= "0" then
					if Type == "Shirt" then
						HumanoidDescription.Shirt = Id
					elseif Type == "Pants" then
						HumanoidDescription.Pants = Id
					elseif Type == "ShirtGraphic" then
						HumanoidDescription.GraphicTShirt = Id
					end

					IsAdded = true
				end
			end
		end

		return IsAdded
	end

	function Function.HumanoidDescriptionLoader(Character, HumanoidDescription, CharacterAttachment, UseBodyColor, Data, isCatalogUsername, oChar, tailCheck, RequestID, MethodOverride)
		-- V4.3.448: accept the captured method from CharacterExecute. Pre-fix the
		-- catalog Username Head branch at L10213 read live `Method` upvalue - if
		-- user flipped Method dropdown during the ~5s yields inside
		-- CreateHumanoidModelFromDescription / WaitForChild("Head"), the branch
		-- could disagree with the rest of the equip pipeline (M2 proxy built but
		-- M1 Decal-restore branch fires, parenting into the wrong Character).
		-- All four call sites (AccessoryLoaderFunction L10382/10391, CatalogLoader
		-- L10499/L10543) thread _MethodAtExec.
		local _Method = MethodOverride or Method
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		-- V4.3.496: helper to refresh DataDetail after any yield (audit Pass C #7).
		-- HumanoidDescriptionLoader yields at ApplyDescription, WaitForChild, and
		-- inside _runHDApply's quiescence loop. Between yields, PlayerData[Data]
		-- can be replaced by a same-tick rejoin or CharacterReset, leaving the
		-- captured `DataDetail` upvalue pointing at a dead/orphan table. Existing
		-- V4.3.452 `IsStaleOrGone` checks bail correctly but the upvalue isn't
		-- refreshed alongside, so subsequent writes can land on the orphan. The
		-- helper closure rebinds DataDetail to the latest PlayerData[Data] (or
		-- returns false if the entry is gone - caller should bail).
		local function _refreshDD()
			local _new = PlayerData[Data]
			if not _new then return false end
			if _new ~= DataDetail then
				-- V4.3.506 telemetry: PlayerData was replaced mid-pipeline.
				Function.diag("hd.refresh_dd_fired", { site = "PlayerData_replaced" })
				DataDetail = _new
			end
			return true
		end
		-- V4.3.361: REVERTED V4.3.359's ReplicatedStorage parent. User report: (see Changelog for full rationale)

		-- V4.3.359: factored out so we can retry once on timeout. Returns the
		-- populated AccessoryLoaderModel + the description (caller takes
		-- ownership), or nil on stale-RID / timeout.
		local function _runHDApply(_attemptDescription, _maxFrames)
			local _model = Instance.new("Model", game)  -- V4.3.361: back to game-root parent (pre-V4.3.359 behavior)
			_model.Archivable = not hidden
			pcall(function() _model:AddTag(System.RCTag) end)
			local _humanoid = Instance.new("Humanoid", _model)
			-- V4.3.488: pre-create a placeholder Head Part so the engine's compose-
			-- decal step (which runs INSIDE ApplyDescription when the HD has a Face
			-- decal or face-attached accessory) has a target. Pre-fix Roblox printed
			-- "Humanoid Description apply new asset's compose decal failed: Missing
			-- Head" at engine level whenever ApplyDescription tried to compose a
			-- decal onto a Head that hadn't been built yet (ApplyDescription builds
			-- the rig + composes assets in interleaved order, sometimes asset-
			-- composition fires before the Head part lands). ApplyDescription itself
			-- replaces / repositions this placeholder during the rig build, so it
			-- doesn't interfere with normal avatar construction - it just gives the
			-- compose step something to address. User report 2026-05-19: Missing
			-- Head warn spamming the executor console during bundle equip.
			local _placeholderHead = Instance.new("Part", _model)
			_placeholderHead.Name = "Head"
			_placeholderHead.Size = Vector3.new(2, 1, 1)
			_placeholderHead.Anchored = true
			_placeholderHead.Transparency = 1
			_placeholderHead.CanCollide = false
			_placeholderHead.CanQuery = false
			_placeholderHead.CanTouch = false
			-- V4.3.431: event-driven quiescence instead of 400-frame busy-poll. Pre-fix the
			-- `repeat task.wait() until #_model:GetChildren() > 2` parked the bundle-equip
			-- thread for up to _maxFrames=400 frames (~6.6s) even when accessories landed in
			-- a few frames. The `> 2` check exits as soon as ANY two children land but Roblox
			-- internal yields can delay the last accessory arbitrarily - burning the full
			-- timeout for the slowest item. Event-driven approach: connect ChildAdded once,
			-- debounce quiescence (no new children for 4 frames = done). Typical reclaim
			-- 100ms-3s per HD load. Caught by bundle-equip audit 2026-05-14 (HIGH).
			local _lastAddFrame = 0
			local _frameCount = 0
			local _addedConn
			_addedConn = _model.ChildAdded:Connect(function() _lastAddFrame = _frameCount end)
			-- V4.3.443: pcall-wrap ApplyDescription. Content-deleted accessory IDs
			-- (DMCA / TOS-flagged assets) can make Roblox throw INSIDE the synchronous
			-- ApplyDescription call. Pre-fix the throw propagated out of _runHDApply
			-- and killed the parent worker BEFORE its `_hdDone.acc = true` flag flip
			-- ran → AccessoryLoaderFunction's barrier waited the full 600 frames (~10s)
			-- per bundle equip. User report: "bundle is just like a whackamole, some
			-- bundle doesnt load, or load very slow". Catch the throw, return a tagged
			-- error so the caller can skip the retry (re-applying the same broken HD
			-- wastes another 6.6s) - surfaced as `_err == "applyerror"`.
			local _applyOk, _applyErr = pcall(function() _humanoid:ApplyDescription(_attemptDescription) end)
			if not _applyOk then
				if _addedConn then _addedConn:Disconnect() end
				_model:Destroy()
				warn("[RoClothes] ApplyDescription threw - likely content-deleted accessory in bundle: "..tostring(_applyErr))
				-- V4.3.506 telemetry: ApplyDescription thrown error.
				Function.diag("hd.apply_throw", { path = "hd_loader", err = tostring(_applyErr):sub(1, 256) })
				return nil, "applyerror"
			end
			-- After ApplyDescription kicks off the accessory load, watch for quiescence.
			-- V4.3.443: TWO terminal conditions:
			--   (a) Healthy: kids > 2 AND 4 idle frames (existing V4.3.431 logic).
			--   (b) All-content-deleted: only Humanoid + maybe Head landed (kids <= 2)
			--       AND 40 idle frames (~0.66s) - no further accessories will ever land
			--       because their IDs are dead. Pre-fix this case waited the full
			--       400-frame cap, then the retry burned another 6.6s. Now bail early
			--       with `noadds` so caller can skip retry and surface a warn.
			-- V4.3.444: track the FIRST add frame separately so we can hard-cap the
			-- "slow trickle" case. Pre-V4.3.444 a bundle whose accessories landed
			-- 1-2s apart kept resetting `_lastAddFrame` so `_idleFrames >= 4` never
			-- fired; the loop ran to the full 400-frame cap, AccessoryLoaderFunction's
			-- 600-frame defensive barrier truncated the wait at 10s, and the user saw
			-- a floating head until the cap fired. Symptom screenshot 2026-05-15.
			-- Now: once the first accessory has landed, allow at MOST 180 frames
			-- (~3s) before bailing with a partial. The fast-path 4-idle terminal
			-- still wins when the rest of the bundle is healthy and quick.
			local _firstAddFrame = -1
			-- V4.3.517 Fix 10: connect-before-disconnect to close the gap where ChildAdded
			-- events fired during the swap window were lost. Bundle could declare "done"
			-- prematurely if accessories landed in the gap.
			local _newConn = _model.ChildAdded:Connect(function()
				_lastAddFrame = _frameCount
				if _firstAddFrame < 0 then _firstAddFrame = _frameCount end
			end)
			_addedConn:Disconnect()
			_addedConn = _newConn
			repeat
				task.wait()
				_frameCount += 1
				-- V4.3.446: player-leave bail. Pre-fix the captured `DataDetail`
				-- upvalue (L9712) still pointed to an orphan PD if PlayerRemoving
				-- fired during the yield - `DataDetail.LastRequestID` never
				-- advanced → stale-RID check at L9838 never tripped → loop ran
				-- the full _maxFrames cap and then post-loop code (catalog-username
				-- branch in particular) mutated the orphan PD's CurrentPartList,
				-- pinning MeshParts under a destroyed character. Same V4.3.441
				-- catalog-Head-path fix extended one level deeper into _runHDApply.
				if not PlayerData[Data] then
					if _addedConn then _addedConn:Disconnect() end
					_model:Destroy()
					return nil, "stale"
				end
				local _kids = #_model:GetChildren()
				local _idleFrames = _frameCount - _lastAddFrame
				if _kids > 2 and _idleFrames >= 4 then break end
				if _kids <= 2 and _idleFrames >= 40 then
					if _addedConn then _addedConn:Disconnect() end
					_model:Destroy()
					-- V4.3.506 telemetry: HD loader gave up with no accessories.
					Function.diag("bundle.barrier_timeout", { kind = "runHD", idleFrames = _idleFrames })
					return nil, "noadds"
				end
				-- V4.3.444: hard-cap the post-first-add window. If accessories trickle
				-- in over 3s+ we accept whatever has landed and exit - Roblox's
				-- retry-internal-yields on dead IDs can keep ChildAdded firing
				-- intermittently and starve the 4-idle terminal forever otherwise.
				if _firstAddFrame >= 0 and (_frameCount - _firstAddFrame) >= 180 then break end
			until _frameCount >= _maxFrames
				or (RequestID and PlayerData[Data] and RequestID ~= PlayerData[Data].LastRequestID)
			if _addedConn then _addedConn:Disconnect() end
			-- V4.3.446: re-fetch PD for the post-loop guards (mirror V4.3.434 pattern).
			local _pdNow = PlayerData[Data]
			if not _pdNow or (RequestID and RequestID ~= _pdNow.LastRequestID) then
				_model:Destroy()
				return nil, "stale"
			end
			if _frameCount >= _maxFrames then
				_model:Destroy()
				return nil, "timeout"
			end
			return _model, nil
		end

		-- V4.3.359: 400 frames (~6.6s) instead of 200 (~3.3s). User report:
		-- SB physics toggle + catalog accessory + body-rebuild churn was
		-- consistently tripping 3.3s. One retry on timeout covers transient
		-- Roblox-side ApplyDescription stalls - usually the second attempt
		-- lands fast since the asset cache is warm.
		local AccessoryLoaderModel, _err = _runHDApply(HumanoidDescription, 400)
		-- V4.3.444: shorter retry (100 frames / ~1.66s instead of 400). The first
		-- attempt has already burned 6.6s; if a second pass with a warm asset cache
		-- can't land anything in 1.66s it never will. Total worst-case across both
		-- attempts: 6.6 + 1.66 = 8.3s, well under the outer 600-frame barrier (~10s)
		-- and well under what felt "broken" to users in the V4.3.443 follow-up
		-- testing ("most bundle load decently, some bundle dont load till like 10
		-- secs later, those accessories have dead accessories", screenshot 2026-05-15).
		if not AccessoryLoaderModel and _err == "timeout" then
			warn("[RoClothes] HumanoidDescriptionLoader timed out - retrying once (short attempt)")
			-- The first attempt destroyed its model. ApplyDescription mutates
			-- the description in-place sometimes, so clone before retry to
			-- avoid passing a partially-mutated descriptor on round 2.
			local _retryDesc = HumanoidDescription
			local _okClone, _cloned = pcall(function() return HumanoidDescription:Clone() end)
			if _okClone and _cloned then _retryDesc = _cloned end
			AccessoryLoaderModel, _err = _runHDApply(_retryDesc, 100)  -- V4.3.444: 100 frames not 400
			if _retryDesc ~= HumanoidDescription then pcall(function() _retryDesc:Destroy() end) end
		end
		if not AccessoryLoaderModel then
			-- V4.3.443: distinct messaging per failure mode + no retry for known-bad
			-- inputs. `applyerror` (ApplyDescription threw, content-deleted asset) and
			-- `noadds` (only Humanoid landed after 0.66s idle) both mean retry will
			-- repeat the same waste; skip the retry chain entirely.
			if _err == "timeout" then
				warn("[RoClothes] HumanoidDescriptionLoader timed out after retry - accessories will retry on next CharacterExecute")
			elseif _err == "applyerror" then
				warn("[RoClothes] HumanoidDescriptionLoader: bundle has content-deleted accessory IDs - partial apply only")
			elseif _err == "noadds" then
				warn("[RoClothes] HumanoidDescriptionLoader: no accessories landed (all content-deleted or invalid IDs) - bundle will show partial")
			end
			HumanoidDescription:Destroy()
			return
		end

		if not PlayerData[Data] then
			AccessoryLoaderModel:Destroy()
			HumanoidDescription:Destroy()
			return
		end
		if Function.IsStaleOrGone(Data, RequestID) then  -- V4.3.452: catches player-leave too
			AccessoryLoaderModel:Destroy()
			HumanoidDescription:Destroy()
			return
		end
		-- V4.3.496: refresh DataDetail upvalue in case PlayerData[Data] was
		-- replaced during the yields above (audit Pass C #7).
		if not _refreshDD() then
			AccessoryLoaderModel:Destroy()
			HumanoidDescription:Destroy()
			return
		end

		-- V4.3.446: snapshot helper hoisted to Function.SnapshotOriginalBodyColors
		-- (L9420) so BodyColorsFunction (regular bundles) + SkinTone path can share
		-- the R15-safe per-part-fallback. Inline alias kept for readability.
		local function _snapshotOriginalBodyColors()
			Function.SnapshotOriginalBodyColors(DataDetail, Character)
		end

		-- V4.3.445: track whether the BodyColors apply branch ran. Used by Fix A
		-- (synthesize from HD Color3 props if no BodyColors child landed) AND by
		-- Fix B (CharacterExecute's BodyColorForceSet at L11521 must NOT overwrite
		-- a catalog-supplied skin with the user's saved SkinTone).
		local _appliedBC = false

		for _, v in pairs(AccessoryLoaderModel:GetChildren()) do
			-- V4.3.476: per-child pcall around the whole iteration body. Pre-fix any
			-- throw inside Function.AccessoryAdd / Function.ApplyAssets / Function.BodyColorSet
			-- (most commonly: executor security hooks blocking `rbxassetid://NUMBER` loads
			-- when the accessory's MeshId or TextureID is routed through ApplyAssets) would
			-- propagate out of this loop, aborting iteration at the first failing accessory
			-- → all subsequent accessories in the bundle never get added → user sees
			-- "bundle doesnt show every accessory" with `[RoClothes] HumanoidDescriptionLoader
			-- (acc) threw: loadstring:3206: BLOCKED file path (rbxassetid://...)` in console.
			-- User-reported 2026-05-18 with screenshot showing the pattern (~20 BLOCKED warns
			-- across multiple bundles, each cutting the equip short). Per-child pcall isolates
			-- the failure so other accessories in the same bundle still equip cleanly. The
			-- one failing accessory just gets skipped with a cooldown-throttled warn.
			local _iterOk, _iterErr = pcall(function()
			if v:IsA("Accessory") then
				if tailCheck == true then
					v.Name = v.Name.."RCTailCertified"
				end
				-- V4.3.361: tag script-equipped accessories so
				-- Function.ApplyStripToLiveCharacter can skip them in the strip
				-- phase. Without the tag, the user's strip toggle would orphan
				-- the catalog accessory the script JUST added → "I equipped a
				-- catalog hair but it disappears on next strip pass / respawn."
				pcall(function() v:SetAttribute("_RC_FromHD", true) end)
				Function.AccessoryAdd(Character, v, CharacterAttachment, Data)
			elseif v:IsA("Shirt") or v:IsA("Pants") or v:IsA("ShirtGraphic") then
				local function convertId(id)
					local success, decalObject = pcall(function()
						local decalObject = game:GetObjects("rbxassetid://"..id)[1]
						return decalObject
					end)
					if success and decalObject and decalObject:IsA("Decal") then
						return decalObject.Texture
					elseif string.gsub(tostring(id), "%D", "") == tostring(id) then  -- V4.5.24 Fix: id can be a NUMBER -> tostring() before gsub (avoid "string expected" throw).
						warn("Clothing ID ".. id.. " returned as invalid clothing! Decal method was detected invalid as well."..
							" If you're using an image ID, this is a false positive.")
						return "rbxassetid://".. id
					else
						return id
					end
				end
				if v:IsA("Shirt") and string.gsub(v.ShirtTemplate,"%D","") == "855777285" and HumanoidDescription.Shirt then
					v.ShirtTemplate = convertId(HumanoidDescription.Shirt)
				elseif v:IsA("Pants") and string.gsub(v.PantsTemplate,"%D","") == "867826313" and HumanoidDescription.Pants then
					v.PantsTemplate = convertId(HumanoidDescription.Pants)
				end
				-- V4.3.497: refresh DataDetail after convertId's game:GetObjects yield.
				if not _refreshDD() then return end
				-- V4.3.504: bail if the player respawned during the yield. Pre-fix
				-- Character.Parent==nil here parented the cloned Shirt/Pants to an
				-- orphan model, silently dropping it.
				if not (Character and Character.Parent) then return end
				local OldCloth = Character:FindFirstChildOfClass(v.ClassName)

				if OldCloth then
					if DataDetail.OldestClothings[v.ClassName] == nil and not OldCloth:GetAttribute("_RC_AppliedClothing") then  -- naked-base reset fix: never snapshot OUR OWN applied garment as the "original" (else switching bundles resurrects bundle #1's clothing on a shirtless base)
						DataDetail.OldestClothings[v.ClassName] = OldCloth:Clone()
					end
					OldCloth:Destroy()
				end

				pcall(function() v:SetAttribute("_RC_AppliedClothing", true) end)  -- naked-base reset fix: mark RoClothes-applied 2D garments so CharacterReset strips them when there is no original to restore
				v.Parent = Character
			elseif v:IsA("BodyColors") and UseBodyColor == true then
				-- V4.3.438: snapshot RealCharacter's BodyColors into
				-- DataDetail.OriginalBodyColors BEFORE destroying. Without this
				-- snapshot, catalog bundles (Username / OutfitId paths) applied
				-- the HD's skin tone but left no restoration record - switching
				-- to another bundle skipped the L10713 restore branch
				-- (`if DataList.OriginalBodyColors and restoreTarget then`)
				-- and the catalog skin persisted forever. User report
				-- 2026-05-14: "catalog feature bundle skin color isnt properly
				-- cleaned up when switching to other bundle". Mirrors the
				-- snapshot pattern in Function.BodyColorsFunction (L9324) -
				-- prefer RealCharacter, only set if nil so we keep the
				-- truly-original colors across consecutive bundle swaps.
				_snapshotOriginalBodyColors()

				local OldBC = Character:FindFirstChildOfClass("BodyColors")

				if OldBC then
					OldBC:Destroy()
				end

				v.Parent = Character

				Function.BodyColorSet(Character, v)
				_appliedBC = true  -- V4.3.445: signal CharacterExecute that catalog supplied skin
				-- V4.3.447: only write the flag if this worker is still the live RID owner.
				-- Pre-fix a late-finishing CatalogLoader worker (from a superseded equip)
				-- could write `true` AFTER the next equip's CharacterExecute read-cleared
				-- it, leaking the catalog skin into the next bundle's BodyColorForceSet
				-- gate → V4.3.445's "becomes my primary skin color" symptom returned.
				if (not RequestID) or (PlayerData[Data] and RequestID == PlayerData[Data].LastRequestID) then
					DataDetail._catalogAppliedBodyColor = true
				end
			end
			end)  -- V4.3.476: close per-iteration pcall wrapper
			if not _iterOk then
				-- V4.4.x: a :7455/:7405 BLOCKED here CONFIRMS the executor blocks rbxassetid content loads
				-- (accessories can't equip) - the one gap we can't probe up-front. Flag it so the Home warning
				-- + a toast surface it (one-shot, deduped inside _flagCapGap).
				do
					local _es = string.lower(tostring(_iterErr))
					if (_es:find("blocked", 1, true) or _es:find("7455", 1, true) or _es:find("7405", 1, true)) and System._flagCapGap then
						pcall(System._flagCapGap, "Catalog accessories", "rbxAsset")
					end
				end
				-- V4.3.488: cooldown bumped 5s → 30s. User report 2026-05-19 showed
				-- the executor console flooded with 4+ distinct "BLOCKED file path"
				-- warns within a single bundle equip - each unique blocked ID gets
				-- its own warn line, and the 5s window didn't damp the spike enough
				-- when many different IDs blocked simultaneously. 30s window keeps
				-- diagnostic surface (still surfaces the first occurrence of each
				-- unique ID) but stops the wall-of-text. Reuses physicsWarnState as
				-- a shared cooldown table (already capped + FIFO'd via V4.3.447).
				local _key = "[hdLoader] " .. tostring(_iterErr)
				local _now = os.clock()
				if not physicsWarnState[_key] or (_now - physicsWarnState[_key]) > 30 then
					if not physicsWarnState[_key] then
						local _n = 0; for _ in pairs(physicsWarnState) do _n = _n + 1 end
						if _n >= 256 then for k in pairs(physicsWarnState) do physicsWarnState[k] = nil; break end end
					end
					physicsWarnState[_key] = _now
					warn("[RoClothes] HumanoidDescriptionLoader: skipping accessory due to error: " .. tostring(_iterErr) .. " (subsequent identical errors suppressed for 30s)")
				end
			end
		end

		-- V4.3.497: refresh DataDetail after the for-loop's accumulated yields,
		-- before the synth-BC fallback reads/writes DataDetail.OriginalBodyColors.
		if not _refreshDD() then
			AccessoryLoaderModel:Destroy()
			HumanoidDescription:Destroy()
			return
		end

		-- V4.3.445: post-loop fallback for catalog HDs that don't include a
		-- BodyColors child instance (Roblox sometimes ships HDs with skin tones
		-- as the HD's own Color3 properties - HeadColor / TorsoColor / etc. -
		-- instead of a child instance). Pre-fix the v:IsA("BodyColors") branch
		-- never fired, the catalog avatar's skin was silently dropped, and the
		-- user saw their previous skin ("bundle skin either doesnt apply").
		-- Synthesize a BodyColors apply from the HD's properties.
		-- V4.3.446: dropped V4.3.445's `_hdHead ~= Color3.new(1,1,1)` deviation gate
		-- because Color3 `~=` is exact-float comparison - pure-white-skinned avatars
		-- (albinism / ghost cosmetic / legitimate white) would silently fall through
		-- the synth fallback and lose their skin entirely. The `_appliedBC` sentinel
		-- alone is sufficient: if the v:IsA("BodyColors") branch in the for-loop
		-- already fired, we skip; otherwise we synth from HD props. HD.HeadColor
		-- defaulting to Color3.new(1,1,1) is fine - applying white-on-white is a no-op.
		-- V4.3.447: smarter gate. Snapshot FIRST, then compare HD props to the
		-- snapshot - only synth if they actually differ. Pre-V4.3.447 the V4.3.446
		-- removal of the "deviation from white" check made the synth fire for EVERY
		-- catalog HD without a BodyColors child, even accessory-only / hair-only
		-- equips that should preserve user skin (Roblox HDs default Head/Torso
		-- Color to white; the synth then force-overwrote the user's skin with
		-- white). New gate: take the snapshot regardless, then check if any HD
		-- property diverges from the snapshot - only apply when actually different.
		-- This correctly handles BOTH (a) pure-white user skin + catalog with real
		-- skin colors, AND (b) any user skin + catalog with no skin override.
		if UseBodyColor == true and not _appliedBC then
			local _hdHead = HumanoidDescription.HeadColor
			local _hdTorso = HumanoidDescription.TorsoColor
			if _hdHead and _hdTorso then
				_snapshotOriginalBodyColors()
				-- V4.3.447: compare HD props field-by-field against the snapshot. If
				-- every field matches, the catalog is "skin-preserving" - skip synth.
				local _snap = DataDetail.OriginalBodyColors
				local function _colorEq(a, b)
					if not a or not b then return a == b end
					return a.R == b.R and a.G == b.G and a.B == b.B
				end
				-- V4.3.448: when snapshot is nil (RealCharacter unset + no BodyColors on
				-- live char + no R6/R15 parts readable, e.g., character mid-respawn),
				-- DEFER rather than force-synth. Pre-V4.3.448 `_diff = not _snap or ...`
				-- short-circuited to true on nil snapshot, reintroducing the V4.3.446
				-- "synth-always" regression in this narrow window. Now: nil snapshot →
				-- skip synth this pass; the next equip after the character stabilizes
				-- will populate snapshot and apply correctly.
				local _diff = _snap and (
					not _colorEq(_hdHead,  _snap.HeadColor3)
					or not _colorEq(_hdTorso, _snap.TorsoColor3)
					or not _colorEq(HumanoidDescription.LeftArmColor  or _hdTorso, _snap.LeftArmColor3)
					or not _colorEq(HumanoidDescription.RightArmColor or _hdTorso, _snap.RightArmColor3)
					or not _colorEq(HumanoidDescription.LeftLegColor  or _hdTorso, _snap.LeftLegColor3)
					or not _colorEq(HumanoidDescription.RightLegColor or _hdTorso, _snap.RightLegColor3)
				)
				if _diff then
				local OldBC = Character:FindFirstChildOfClass("BodyColors")
				if OldBC then OldBC:Destroy() end
				local NewBC = Instance.new("BodyColors", Character)
				NewBC.HeadColor3     = _hdHead
				NewBC.TorsoColor3    = _hdTorso
				NewBC.LeftArmColor3  = HumanoidDescription.LeftArmColor  or _hdTorso
				NewBC.RightArmColor3 = HumanoidDescription.RightArmColor or _hdTorso
				NewBC.LeftLegColor3  = HumanoidDescription.LeftLegColor  or _hdTorso
				NewBC.RightLegColor3 = HumanoidDescription.RightLegColor or _hdTorso
				Function.BodyColorSet(Character, NewBC)
				_appliedBC = true
				-- V4.3.447: RID-gate the flag write - same as the for-loop branch above.
				if (not RequestID) or (PlayerData[Data] and RequestID == PlayerData[Data].LastRequestID) then
					DataDetail._catalogAppliedBodyColor = true
				end
				end -- V4.3.447: close _diff block
			end
		end

		if isCatalogUsername == true then

			if Character:FindFirstChild("Head") then
				-- V4.3.497: pcall-guard CreateHumanoidModelFromDescription - Roblox can throw
				-- on malformed HDs or restricted-content avatars, previously uncaught.
				local _okCHM, LoadedAvatar = pcall(function()
					return game:GetService("Players"):CreateHumanoidModelFromDescription(HumanoidDescription, Enum.HumanoidRigType.R6)
				end)
				if not _okCHM or not LoadedAvatar then
					AccessoryLoaderModel:Destroy()
					HumanoidDescription:Destroy()
					return
				end
				-- V4.3.375: bounded WaitForChild - malformed models with no Head used to
				-- hang the execute coroutine forever. 5s cap + nil bail-out unblocks.
				local head = LoadedAvatar:WaitForChild("Head", 5)
				if not head then
					LoadedAvatar:Destroy()
					AccessoryLoaderModel:Destroy()
					HumanoidDescription:Destroy()
					return
				end
				if Function.IsStaleOrGone(Data, RequestID) then  -- V4.3.452
					LoadedAvatar:Destroy()
					AccessoryLoaderModel:Destroy()
					HumanoidDescription:Destroy()
					return
				end
				-- V4.3.496: refresh DataDetail after the long yield (audit Pass C #7).
				if not _refreshDD() then
					LoadedAvatar:Destroy()
					AccessoryLoaderModel:Destroy()
					HumanoidDescription:Destroy()
					return
				end
				-- V4.3.441: also bail if the player left mid-yield. CreateHumanoidModelFromDescription
				-- + WaitForChild("Head", 5) can yield up to 5s. The captured DataDetail still has the
				-- pre-leave LastRequestID (matches RequestID), so the guard above PASSES while
				-- PlayerData[Data] is now nil - subsequent writes (charHead, CurrentPartList.Organ,
				-- RealtimeUpdateList.Mesh/ParentTransparency) populate an orphan PD with strong refs
				-- to MeshParts under a destroyed character. Same V4.3.152 H4 / V4.3.425 Gap 4 pattern.
				if not PlayerData[Data] then
					LoadedAvatar:Destroy()
					AccessoryLoaderModel:Destroy()
					HumanoidDescription:Destroy()
					return
				end

				local charHead = Character:FindFirstChild("Head")
				local OldFC = charHead:FindFirstChildOfClass("Decal")
				local OldSM = charHead:FindFirstChildOfClass("SpecialMesh")

				if charHead:IsA("MeshPart") then
					local v = charHead
					local newHead = Instance.new("Part",v)
					newHead:AddTag(System.RCTag)
					newHead.Size = v.Size
					newHead.Name = "RCFake"..v.Name
					newHead.CanCollide = false
					newHead.CanQuery = false
					newHead.CanTouch = false
					newHead.Massless = true
					newHead.CustomPhysicalProperties = System.Physics.DefaultProperties
					newHead.Color = v.Color
					newHead.Material = v.Material
					newHead.Reflectance = v.Reflectance
					DataDetail.CurrentPartList.Organ["Head"] = newHead
					DataDetail.CurrentPartList.Link[newHead] = {T=v, Color=v}

					newHead.CFrame = v.CFrame
					local Weld = Instance.new("Weld", newHead)
					Weld.Part0 = v
					Weld.Part1 = newHead

					if DataDetail.Face == true then
						if head:FindFirstChildOfClass("Decal") then
							if OldFC then
								OldFC:Destroy()
							end
							local newDC=head:FindFirstChildOfClass("Decal"):Clone()
							newDC.Parent = newHead
							DataDetail.CurrentPartList.Link[newDC] = {T=newHead}
						elseif OldFC then
							OldFC.Parent = newHead
						end
					elseif OldFC then
						OldFC:Destroy()
					end
					if head:FindFirstChildOfClass("SpecialMesh") then
						DataDetail.CurrentPartList.ParentTransparency[v] = {v = v.Transparency, T = 1}
						local mesh = head:FindFirstChildOfClass("SpecialMesh"):Clone()
						mesh.Parent = newHead
						if mesh.MeshType == Enum.MeshType.Head then
							mesh.Scale = Vector3.new(1,1,1)
						end
						DataDetail.CurrentPartList.RealtimeUpdateList.SpecialMesh[mesh] = {
							Base=v,
							Size=mesh.Scale,
							CFrame = CFrame.new(0,0,0),
							CFrame1 = CFrame.new(0,0,0),
							Weld = Weld,
						}
					else
						local mesh = Instance.new("SpecialMesh",newHead)
						mesh.MeshId = v.MeshId
					end
				elseif _Method == 2 and oChar then  -- V4.3.448: captured method
					local h = Character:FindFirstChild("Head")
					--DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[h] = {Base = h}
					--h.Transparency = 0

					local function newhed(id,texture)
						-- V4.3.309: route through MeshPart cache. Catalog-username heads typically
						-- repeat across users (default Roblox heads), so cache hits are very common.
						local newHead = Function.CachedCreateMeshPartAsync(id,
							Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
						if not newHead then
							newHead = Function.CachedCreateMeshPartAsync("rbxasset://fonts//head.mesh",
								Enum.CollisionFidelity.Box, Enum.RenderFidelity.Automatic)
						end
						-- V4.3.164 C3 fix: post-yield RID guard. Both CreateMeshPartAsync calls yield;
						-- if a newer execution bumped LastRequestID during the wait, parenting + tagging
						-- + writing to DataDetail.CurrentPartList.Organ["Head"] pollutes the new state
						-- and leaves an orphan tagged MeshPart on the destroyed proxy.
						if Function.IsStaleOrGone(Data, RequestID) then  -- V4.3.452
							if newHead then pcall(function() newHead:Destroy() end) end
							return nil
						end
						-- V4.3.496: refresh DataDetail before the post-yield writes (audit Pass C #7).
						if not _refreshDD() then
							if newHead then pcall(function() newHead:Destroy() end) end
							return nil
						end
						-- V4.4.2: guard the nil-deref. Once Function._cmpaBroken is set (Delta CMPA hang),
						-- BOTH CachedCreateMeshPartAsync attempts above return nil, so newHead.Parent would
						-- error. Bail cleanly (a catalog-username custom head just won't apply on that executor).
						if not newHead then return nil end
						newHead.Parent = h
						local appearance = Instance.new("SurfaceAppearance",newHead)
						appearance.ColorMap = texture
						newHead:AddTag("ImportantSurfaceAppearance")
						newHead:AddTag(System.RCTag)
						--newHead.Size = h.Size
						newHead.Name = h.Name
						newHead.CanCollide = false
						newHead.CanQuery = false
						newHead.CanTouch = false
						newHead.Massless = true
						newHead.CustomPhysicalProperties = System.Physics.DefaultProperties
						newHead.Color = h.Color
						newHead.Material = h.Material
						newHead.Reflectance = h.Reflectance
						DataDetail.CurrentPartList.Organ["Head"] = newHead

						newHead.CFrame = h.CFrame
						local Weld = Instance.new("Weld", newHead)
						Weld.Part0 = h
						Weld.Part1 = newHead
						DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[newHead] = {Base = h,Size=newHead.Size,CFrame=CFrame.new(0,0,0),CFrame1=CFrame.new(0,0,0),Weld=Weld}
						return newHead
					end

					DataDetail.CurrentPartList.ParentTransparency[h] = {D = 1}
					local _oHead76 = oChar:FindFirstChild("Head")
					if _oHead76 then
					    DataDetail.CurrentPartList.ParentTransparency[_oHead76] = {D = _oHead76.Transparency, T = 1}
					end

					local oHead = oChar:FindFirstChild("Head")
					local OldFC = oHead and oHead:FindFirstChildOfClass("Decal")
					local OldSM = oHead and oHead:FindFirstChildOfClass("SpecialMesh")
					-- V4.3.446: snapshot Face Decal + Head SpecialMesh before destroying
					-- them. Pre-fix the catalog Username path destroyed these without
					-- saving clones, so switching off the catalog bundle left the user
					-- with no face decal / wrong head shape until respawn. Stored in
					-- OldestClothings so CharacterReset's restore branch (which already
					-- walks Shirt/Pants/ShirtGraphic) can re-parent them.
					if OldFC and not DataDetail.OldestClothings.HeadDecal then
						DataDetail.OldestClothings.HeadDecal = OldFC:Clone()
					end
					if OldSM and not DataDetail.OldestClothings.HeadSpecialMesh then
						DataDetail.OldestClothings.HeadSpecialMesh = OldSM:Clone()
					end
					if OldFC then
						OldFC:Destroy()
					end
					if OldSM then
						OldSM:Destroy()
					end

					local headMesh = head:FindFirstChildOfClass("SpecialMesh")
					if headMesh then
						h = newhed(headMesh.MeshId, headMesh.TextureId)
					elseif OldSM then
						h = newhed(OldSM.MeshId,OldSM.TextureId)
					end
					if DataDetail.Face == true then
						-- V4.5.24 Fix: on executors where BOTH newhed mesh attempts fail, h is nil.
						-- Guard the decal-copy branches so we never register a Link entry with T=nil
						-- (and an unparented decal) on a proxy head that never loaded. The outer
						-- `elseif OldFC` face-hide branch below intentionally still runs (no h needed).
						if h and head:FindFirstChildOfClass("Decal") then
							if OldFC then
								OldFC.Transparency = 1
								DataDetail.CurrentPartList.ParentTransparency[OldFC] = {D = 0,T=1}
							end
							local d = head:FindFirstChildOfClass("Decal"):Clone()
							DataDetail.CurrentPartList.Link[d] = {T=h}
							d.Parent = h
						elseif h and OldFC then
							if OldFC then
								OldFC.Transparency = 1
								DataDetail.CurrentPartList.ParentTransparency[OldFC] = {D = 0,T=1}
							end
							local o = OldFC:Clone()
							DataDetail.CurrentPartList.ParentTransparency[o] = {D = 1}
							DataDetail.CurrentPartList.Link[o] = {T=h}
							o.Parent = h
						end
					elseif OldFC then
						OldFC.Transparency = 1
						DataDetail.CurrentPartList.ParentTransparency[OldFC] = {D = 0,T=1}
					end
				else
					if head:FindFirstChildOfClass("Decal") and DataDetail.Face == true then
						-- V4.3.446: snapshot original Face Decal before destroy (M1/non-MeshPart path).
						if OldFC and not DataDetail.OldestClothings.HeadDecal then
							DataDetail.OldestClothings.HeadDecal = OldFC:Clone()
						end
						if OldFC then
							OldFC:Destroy()
						end
						head:FindFirstChildOfClass("Decal"):Clone().Parent = Character:FindFirstChild("Head")
					elseif OldFC then
						-- V4.3.446: snapshot before destroy on the no-catalog-decal branch too.
						if not DataDetail.OldestClothings.HeadDecal then
							DataDetail.OldestClothings.HeadDecal = OldFC:Clone()
						end
						-- V4.5.18: DYNAMIC-FACE / faceless import fix. Pre-fix this destroyed the user's face
						-- Decal UNCONDITIONALLY. When the imported avatar has a DYNAMIC face (FaceControls, no
						-- Decal) or no face at all, the Decal branch above copies nothing, so the user was left
						-- permanently FACELESS (community report: "importing a dynamic-face avatar overrides /
						-- breaks the face"). A classic Part head can't render a dynamic face anyway, so the
						-- right behavior is to KEEP the user's existing face. Only destroy it when Face-apply is
						-- OFF (the user explicitly chose to hide their face -- the original intent of this branch).
						if DataDetail.Face == false then
							OldFC:Destroy()
						end
					end
					if head:FindFirstChildOfClass("SpecialMesh") then
						-- V4.3.446: snapshot Head SpecialMesh before destroy. Pre-fix the
						-- catalog HD's SpecialMesh replaced the user's original (e.g. a custom
						-- head shape) with no restoration record - switching off the catalog
						-- bundle left the user with the catalog head shape until respawn.
						if OldSM and not DataDetail.OldestClothings.HeadSpecialMesh then
							DataDetail.OldestClothings.HeadSpecialMesh = OldSM:Clone()
						end
						if OldSM then
							OldSM:Destroy()
						end
						head:FindFirstChildOfClass("SpecialMesh"):Clone().Parent = Character:FindFirstChild("Head")
					end
				end

				LoadedAvatar:Destroy()
			end
		end

		AccessoryLoaderModel:Destroy()
		HumanoidDescription:Destroy()
	end

	function Function.AccessoryLoaderFunction(Character, CharacterAttachment, SelectBundle, Data, RequestID, MethodOverride)
		-- V4.3.448: thread captured method through to HumanoidDescriptionLoader so
		-- a mid-equip Method-dropdown change doesn't tear the proxy/non-proxy state.
		local _Method = MethodOverride or Method
		if not Bundle[SelectBundle] then return end

		local HumanoidDescription = Instance.new("HumanoidDescription")
		local HumanoidDescriptionTail = Instance.new("HumanoidDescription")

		-- V4.3.456: NakedMode flag suppresses Bundle.Clothes propagation. Bundle's
		-- accessories (hair, face decorations, hats) still apply via the first arg,
		-- but Shirt/Pants/ShirtGraphic from Bundle.Clothes are dropped.
		local _pdNM = PlayerData[Data]
		-- BUGFIX: the `C and nil or Y` idiom can NEVER return nil (nil is falsy, so `or Y` always wins),
		-- so NakedMode never actually suppressed the bundle's Shirt/Pants/ShirtGraphic. Use an explicit if.
		local _bundleClothes = Bundle[SelectBundle]["Clothes"]
		if _pdNM and _pdNM._nakedMode then _bundleClothes = nil end
		-- V4.3.536 Fix 1: thread a single 5s deadline through both calls. Pre-fix
		-- acc+tail each paid their own 5s cap sequentially → a fully-dead bundle
		-- stalled here for ~10s before any downstream HumanoidDescriptionLoader
		-- spun up. Now both share one cutoff; total wait capped at 5s. Background
		-- workers continue draining per V4.3.327 - only the SYNCHRONOUS join wait
		-- is shortened, late-arriving accessory data still writes into the HD.
		local _hdSetDeadline = (((tick and tick()) or os.clock()) + 5)
		local IsAdded = Function.HumanoidDescriptionSet(Bundle[SelectBundle]["Accessory"], _bundleClothes, HumanoidDescription, Data, RequestID, _hdSetDeadline)
		local IsTail = Function.HumanoidDescriptionSet(Bundle[SelectBundle]["TailAccessory"], nil, HumanoidDescriptionTail, Data, RequestID, _hdSetDeadline)

		-- V4.3.432: parallelize the main-accessory + tail HumanoidDescriptionLoader calls.
		-- Pre-fix they ran sequentially in this coroutine, each yielding up to 6.6s (per the
		-- V4.3.431 event-driven quiescence + the V4.3.359 _maxFrames=400 cap). Both calls
		-- touch DISJOINT state (separate HumanoidDescription instances, separate accessory
		-- pools) so they're safe to run in parallel via task.spawn. Join via a 2-element
		-- flag table + a barrier loop. Caught by bundle-equip audit 2026-05-14 (HIGH, ~3-5s
		-- typical reclaim per equip with both accessories AND tail).
		local _hdDone = {acc = (IsAdded ~= true), tail = (IsTail ~= true)}
		if IsAdded == true then
			task.spawn(function()
				-- V4.3.443: pcall-wrap so any throw inside HumanoidDescriptionLoader
				-- (content-deleted accessories that propagate past the inner pcall guards)
				-- still flips _hdDone.acc - without this the outer barrier waited the full
				-- 600 frames for a worker that already died. Same finally pattern for tail.
				local _ok, _err = pcall(function()
					Function.HumanoidDescriptionLoader(Character, HumanoidDescription, CharacterAttachment, false, Data, nil, nil, nil, RequestID, _Method)  -- V4.3.448
				end)
				if not _ok then warn("[RoClothes] HumanoidDescriptionLoader (acc) threw: "..tostring(_err)) end
				_hdDone.acc = true
			end)
		end
		if IsTail == true then
			task.spawn(function()
				local _ok, _err = pcall(function()
					Function.HumanoidDescriptionLoader(Character, HumanoidDescriptionTail, CharacterAttachment, false, Data, nil, nil, true, RequestID, _Method)  -- V4.3.448
				end)
				if not _ok then warn("[RoClothes] HumanoidDescriptionLoader (tail) threw: "..tostring(_err)) end
				_hdDone.tail = true
			end)
		end
		-- Barrier: wait for both workers (or stale-RID, or timeout matching the inner cap).
		-- V4.3.434: fix crash from V4.3.432. Pre-fix this loop indexed `DataDetail`
		-- which is NOT a local in this function (`Function.AccessoryLoaderFunction`
		-- has only `Data`, not `DataDetail`). Reading the global resolved to nil, so
		-- on the second loop iteration `nil.LastRequestID` crashed with
		-- "attempt to index nil with 'LastRequestID'" - and the crash left the
		-- bundle-equip Cooldown true, blocking subsequent bundle clicks. User report:
		-- "if i equip bundle made from the roblox catalog i cannot equip other bundle".
		-- Catalog bundles trigger this more reliably because MPS:GetProductInfo yields
		-- give the loop time to iterate past frame 1. Fix: look up PlayerData[Data]
		-- safely on each iteration (handles player-leave race too).
		local _waitCount = 0
		while not (_hdDone.acc and _hdDone.tail) do
			task.wait()
			_waitCount += 1
			if _waitCount > 540 then  -- V4.3.536 Fix 4: widened 510 → 540. V4.3.444 self-flagged "tiny safety margin"; inner caps sum to 500 (400+100), worker startup eats ~1-2 frames, leaving ~8-10 frames of real slack that chopped legitimate slow-network tail workers. 540 gives ~0.5s genuine slack while staying well below the V4.3.444-era 600-frame "floating head" budget.
				pcall(Function.diag, "hd.outer_barrier_timeout", { frames = _waitCount, accDone = _hdDone and _hdDone.acc, tailDone = _hdDone and _hdDone.tail })
				break
			end
			-- V4.3.505: was raw RID check + nil check; IsStaleOrGone handles both (PD-orphan + stale-RID)
			if Function.IsStaleOrGone(Data, RequestID) then break end
		end

		-- Destroy only if both workers finished. If we exited via timeout / stale-RID
		-- a worker may still be running with the HD instance in scope - Destroy now
		-- would crash inside `ApplyDescription` or the post-apply loop. Leaking the
		-- HD instance is harmless (no parent, GC'd when worker drops its ref).
		if _hdDone.acc and _hdDone.tail then
			-- V4.3.448: pcall-wrap because HumanoidDescriptionLoader already destroys
			-- its HumanoidDescription parameter on normal completion (L10363) and on
			-- error/stale paths (L9954-9965, L10142-10160). Calling Destroy on an
			-- already-destroyed instance is benign on most Roblox API but the
			-- in-progress engine deprecation could throw. Defensive.
			pcall(function() HumanoidDescription:Destroy() end)
			pcall(function() HumanoidDescriptionTail:Destroy() end)
		else
			-- Defer the cleanup to a follow-up task that re-checks the flags.
			task.spawn(function()
				local _dt = 0
				while not (_hdDone.acc and _hdDone.tail) and _dt < 10 do
					task.wait(0.1); _dt += 0.1
				end
				pcall(function() HumanoidDescription:Destroy() end)
				pcall(function() HumanoidDescriptionTail:Destroy() end)
			end)
		end
	end

	function Function.CatalogFaceLoader(Character, Data, RequestID)
		local pd = PlayerData[Data]
		local id = pd and pd.CatalogClothes and tonumber(pd.CatalogClothes.Face)
		if not id or id <= 0 or id >= 2^53 or id ~= math.floor(id) or pd.Face == false then return end
		-- Resolve a classic face through the same native description API as
		-- avatar imports, but copy only the decal so head shape stays intact.
		local done, abandoned, avatar = false, false, nil
		task.spawn(function()
			local hd = Instance.new("HumanoidDescription")
			hd.Face = id
			local ok, model = pcall(PS.CreateHumanoidModelFromDescription, PS, hd, Enum.HumanoidRigType.R6)
			hd:Destroy()
			if abandoned then
				if ok and model then model:Destroy() end
			elseif ok then
				avatar = model
			end
			done = true
		end)
		local started = os.clock()
		while not done and os.clock() - started < 6 do
			if Function.IsStaleOrGone(Data, RequestID) then break end
			task.wait()
		end
		abandoned = true
		if not avatar then return end
		if Function.IsStaleOrGone(Data, RequestID) then avatar:Destroy(); return end
		pd = PlayerData[Data]
		if pd.Face == false or tonumber(pd.CatalogClothes and pd.CatalogClothes.Face) ~= id then avatar:Destroy(); return end
		local sourceHead = avatar:FindFirstChild("Head")
		local sourceFace = sourceHead and sourceHead:FindFirstChildOfClass("Decal")
		local originalHead = Character:FindFirstChild("Head")
		local head = pd.CurrentPartList.Organ.Head or originalHead
		if sourceFace and head and head.Parent then
			local originalFace = originalHead and originalHead:FindFirstChildOfClass("Decal")
			if originalFace and not originalFace:GetAttribute("_RC_CatalogFace") and not pd.OldestClothings.HeadDecal then
				pd.OldestClothings.HeadDecal = originalFace:Clone()
			end
			local oldFace = head:FindFirstChildOfClass("Decal")
			if oldFace then oldFace:Destroy() end
			local face = sourceFace:Clone()
			face:AddTag(System.RCTag)
			face:SetAttribute("_RC_CatalogFace", true)
			face.Parent = head
			pd.CurrentPartList.Link[face] = {T = head}
		end
		avatar:Destroy()
	end

	function Function.CatalogLoader(Character, CharacterAttachment, Data, oChar, RequestID, MethodOverride)
		-- V4.3.448: thread captured method through to HumanoidDescriptionLoader.
		local _Method = MethodOverride or Method
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end

		-- V4.3.437: parallelize the entire CatalogLoader. Pre-fix it ran THREE
		-- sequential yields (CatalogUsername → CatalogOutfitId → Accessory/Tail-HD)
		-- each yielding 1-7s. Total worst-case ~15-20s. User: "fix the roblox catalog
		-- bundle issue, like why cant you make it the same as regular bundle" -
		-- regular bundles got the parallel-HD treatment in V4.3.432; catalog bundles
		-- were still sequential. All three branches touch DISJOINT state (separate
		-- HumanoidDescription instances, separate sources) so they're safe to run
		-- concurrently via task.spawn. Join via flag-table barriers (same pattern as
		-- V4.3.432, including the worker-safe Destroy on timeout/stale-RID and the
		-- V4.3.434 PlayerData[Data] lookup instead of DataDetail to avoid the
		-- nil-index crash that bit V4.3.432).
		local _catChores = {}

		-- Branch 1: CatalogUsername path (yields on GetUserIdFromNameAsync +
		-- GetHumanoidDescriptionFromUserId + nested HumanoidDescriptionLoader).
		if DataDetail.CatalogUsername ~= "" then
			local _job = {done = false}
			table.insert(_catChores, _job)
			task.spawn(function()
				pcall(function()
					local UsernameId = PS:GetUserIdFromNameAsync(DataDetail.CatalogUsername)
					if Function.IsStaleOrGone(Data, RequestID) then return end  -- V4.3.505
					local _pd = PlayerData[Data]

					local _hd = PS:GetHumanoidDescriptionFromUserId(UsernameId)
					if Function.IsStaleOrGone(Data, RequestID) then return end  -- V4.3.505
					_pd = PlayerData[Data]

					-- V4.3.456: strip clothes from the HD when NakedMode is active.
					-- The Roblox catalog HD includes the user's avatar Shirt/Pants/
					-- GraphicTShirt; without this, switching to NakedMode while a
					-- CatalogUsername is set would re-equip the user's avatar clothes.
					-- V4.3.520 Fix 12: refetch _pd before _nakedMode read. V4.3.517 Fix 9 added
					-- refetch before the iteration loops but missed this branch - _pd was read
					-- BEFORE GetHumanoidDescriptionFromUserId yield, so if StripAllClothes ran
					-- during the yield the _nakedMode flag was stale.
					_pd = PlayerData[Data]
					if not _pd then return end
					if _pd._nakedMode then
						pcall(function() _hd.Shirt = 0; _hd.Pants = 0; _hd.GraphicTShirt = 0 end)
					end

					-- V4.3.517 Fix 9: re-fetch _pd after yield - PlayerData[Data] may have been
					-- replaced (rejoin / Reset / new RID) and stale upvalue would write to orphan.
					_pd = PlayerData[Data]
					if not _pd then return end
					for Type, Id in pairs(_pd.CatalogClothes) do
						if Id ~= "" and Id ~= 0 and Id ~= "0" then
							if Type == "Shirt" then _hd.Shirt = Id
							elseif Type == "Pants" then _hd.Pants = Id
							elseif Type == "ShirtGraphic" then _hd.GraphicTShirt = Id
							elseif Type == "Face" then _hd.Face = tonumber(Id) or 0 end
						end
					end

					-- V4.3.517 Fix 9: re-fetch _pd after yield - PlayerData[Data] may have been
					-- replaced (rejoin / Reset / new RID) and stale upvalue would write to orphan.
					_pd = PlayerData[Data]
					if not _pd then return end
					if #_pd.CatalogRemove > 0 then
						local accessories = _hd:GetAccessories(true)
						local removeSet = {}
						for _, remove in pairs(_pd.CatalogRemove) do
							removeSet[remove] = true
						end
						local toRemove = {}
						for idx, accessory in ipairs(accessories) do
							if removeSet[accessory.AssetId] then
								table.insert(toRemove, 1, idx)
							end
						end
						for _, idx in ipairs(toRemove) do
							table.remove(accessories, idx)
						end
						_hd:SetAccessories(accessories, true)
					end

					Function.HumanoidDescriptionLoader(Character, _hd, CharacterAttachment, true, Data, true, oChar, nil, RequestID, _Method)  -- V4.3.448
				end)
				_job.done = true
			end)
		end

		-- Branch 2: CatalogOutfitId path (yields on GetHumanoidDescriptionFromOutfitId
		-- + nested HumanoidDescriptionLoader).
		-- V4.3.446: mutually exclusive with Branch 1. Pre-fix, an imported bundle that
		-- populated both CatalogUsername AND CatalogOutfitId fired BOTH workers; each
		-- destroyed the other's freshly-created BodyColors / Shirt / Pants on the
		-- same Character, "last write wins" non-deterministically (skin doesn't apply
		-- or applies wrong avatar's skin). Username takes precedence (matches the UI
		-- ordering: Username field is above OutfitId).
		if DataDetail.CatalogOutfitId ~= "" and DataDetail.CatalogUsername == "" then
			local _job = {done = false}
			table.insert(_catChores, _job)
			task.spawn(function()
				pcall(function()
					local _hd = PS:GetHumanoidDescriptionFromOutfitId(DataDetail.CatalogOutfitId)
					if Function.IsStaleOrGone(Data, RequestID) then return end  -- V4.3.505
					local _pd = PlayerData[Data]

					-- V4.3.456: NakedMode strip - see CatalogUsername branch comment.
					-- V4.3.520 Fix 12: refetch _pd before _nakedMode read (sibling fix to the
					-- CatalogUsername branch above).
					_pd = PlayerData[Data]
					if not _pd then return end
					if _pd._nakedMode then
						pcall(function() _hd.Shirt = 0; _hd.Pants = 0; _hd.GraphicTShirt = 0 end)
					end

					-- V4.3.517 Fix 9: re-fetch _pd after yield - PlayerData[Data] may have been
					-- replaced (rejoin / Reset / new RID) and stale upvalue would write to orphan.
					_pd = PlayerData[Data]
					if not _pd then return end
					for Type, Id in pairs(_pd.CatalogClothes) do
						if Id ~= "" and Id ~= 0 and Id ~= "0" then
							if Type == "Shirt" then _hd.Shirt = Id
							elseif Type == "Pants" then _hd.Pants = Id
							elseif Type == "ShirtGraphic" then _hd.GraphicTShirt = Id
							elseif Type == "Face" then _hd.Face = tonumber(Id) or 0 end
						end
					end

					-- V4.3.517 Fix 9: re-fetch _pd after yield - PlayerData[Data] may have been
					-- replaced (rejoin / Reset / new RID) and stale upvalue would write to orphan.
					_pd = PlayerData[Data]
					if not _pd then return end
					if #_pd.CatalogRemove > 0 then
						local accessories = _hd:GetAccessories(true)
						local removeSet = {}
						for _, remove in pairs(_pd.CatalogRemove) do
							removeSet[remove] = true
						end
						local toRemove = {}
						for idx, accessory in ipairs(accessories) do
							if removeSet[accessory.AssetId] then
								table.insert(toRemove, 1, idx)
							end
						end
						for _, idx in ipairs(toRemove) do
							table.remove(accessories, idx)
						end
						_hd:SetAccessories(accessories, true)
					end

					Function.HumanoidDescriptionLoader(Character, _hd, CharacterAttachment, true, Data, true, oChar, nil, RequestID, _Method)  -- V4.3.448
				end)
				_job.done = true
			end)
		end

		-- Branch 3: CatalogAccessory + CatalogTail (V4.3.432 pattern - main + tail
		-- parallel sub-workers internally). Each uses HumanoidDescriptionSet to build
		-- a fresh HD from the user's per-accessory ID list, then runs
		-- HumanoidDescriptionLoader. Disjoint instances, safe to parallelize.
		-- V4.3.517 Fix 8: HD doesn't need a Workspace parent for ApplyDescription. Workspace
		-- parenting was replicated and leaked 10s on stale-RID timeout. nil parent works.
		local _accHD  = Instance.new("HumanoidDescription")
		_accHD.Parent = nil
		local _tailHD = Instance.new("HumanoidDescription")
		_tailHD.Parent = nil
		-- V4.3.536 Fix 1: same shared 5s deadline pattern as AccessoryLoaderFunction
		-- callers above. CatalogLoader's CatalogAccessory + CatalogTail are also
		-- sequential - dead Catalog IDs stalled here for ~10s before V4.3.536.
		local _hdSetDeadline = (((tick and tick()) or os.clock()) + 5)
		local _accIsAdded = Function.HumanoidDescriptionSet(DataDetail.CatalogAccessory, DataDetail.CatalogClothes, _accHD, Data, RequestID, _hdSetDeadline)
		local _tailIsAdded = Function.HumanoidDescriptionSet(DataDetail.CatalogTail, nil, _tailHD, Data, RequestID, _hdSetDeadline)
		local _accJob  = {done = (_accIsAdded ~= true)}
		local _tailJob = {done = (_tailIsAdded ~= true)}
		table.insert(_catChores, _accJob)
		table.insert(_catChores, _tailJob)
		if _accIsAdded == true then
			task.spawn(function()
				Function.HumanoidDescriptionLoader(Character, _accHD, CharacterAttachment, false, Data, nil, nil, nil, RequestID, _Method)  -- V4.3.448
				_accJob.done = true
			end)
		else
			_accHD:Destroy()
		end
		if _tailIsAdded == true then
			task.spawn(function()
				Function.HumanoidDescriptionLoader(Character, _tailHD, CharacterAttachment, false, Data, nil, nil, true, RequestID, _Method)  -- V4.3.448
				_tailJob.done = true
			end)
		else
			_tailHD:Destroy()
		end

		-- Single barrier: wait for ALL chores to complete (or timeout / stale-RID).
		local _waitCount = 0
		while true do
			local _allDone = true
			for _, _job in ipairs(_catChores) do
				if not _job.done then _allDone = false; break end
			end
			if _allDone then break end
			task.wait()
			_waitCount += 1
			if _waitCount > 540 then  -- V4.3.536 Fix 4: widened 510 → 540 (sibling of L14403). Same V4.3.444 inner-cap-slack reasoning; tiny safety margin chopped legit slow tail.
				pcall(Function.diag, "hd.outer_barrier_timeout", { frames = _waitCount, site = "catalog_loader" })
				break
			end
			local _pd = PlayerData[Data]
			if not _pd then break end  -- player left mid-equip
			if RequestID and RequestID ~= _pd.LastRequestID then break end
		end

		-- Cleanup: destroy the workspace-parented HD instances. Only safe if their
		-- workers finished - otherwise defer cleanup (mirrors V4.3.432 pattern).
		local _doneAcc, _doneTail = _accJob.done, _tailJob.done
		if _doneAcc and _doneTail then
			pcall(function() _accHD:Destroy() end)
			pcall(function() _tailHD:Destroy() end)
		else
			task.spawn(function()
				local _dt = 0
				while not (_accJob.done and _tailJob.done) and _dt < 10 do
					task.wait(0.1); _dt += 0.1
				end
				pcall(function() _accHD:Destroy() end)
				pcall(function() _tailHD:Destroy() end)
			end)
		end
		if not Function.IsStaleOrGone(Data, RequestID) then
			Function.CatalogFaceLoader(Character, Data, RequestID)
		end
	end
	function Function.TableFind(Table, Value)
		for i, v in pairs(Table) do
			if v == Value then
				return i
			end
		end
	end
	function Function.TableClone(Table)
		local newtable = {}
		for i, v in pairs(Table) do
			newtable[i] = v
		end
		return newtable
	end

	-- V4.3.287: deep clone for click-execute on real players. TableClone above is (see Changelog for full rationale)
	-- V4.3.295: optional `skipKeys` set - top-level keys to omit from the clone.
	-- V4.3.447: cycle detection via `seen` map. Pre-fix any caller passing a cyclic
	-- graph (peer-broadcast attacker, or future code that aliases pd.x = pd) would
	-- stack-overflow. The PD currently has no cycles but `_strippedAccessories`
	-- (V4.3.446 skip target) was one near-miss; defensive guard avoids future
	-- regressions of this class.
	function Function.DeepClone(t, skipKeys, seen)
		if type(t) ~= "table" then return t end
		seen = seen or {}
		if seen[t] then return seen[t] end
		local out = {}
		seen[t] = out
		for k, v in pairs(t) do
			if not (skipKeys and skipKeys[k]) then
				if type(v) == "table" then
					out[k] = Function.DeepClone(v, nil, seen)  -- nested levels: no skip; share seen-map
				else
					out[k] = v
				end
			end
		end
		return out
	end

	-- V4.3.295: same-length-swap cache invalidation pattern. Call sites use the inline
	-- form `pd._equippedSetSrc = nil` directly (V4.3.302: deleted dead helper that no
	-- one called - convention is the inline write at the 5 mutation sites). Identity
	-- + length check at the read sites catches whole-table replacement / pure-insert /
	-- pure-remove; this manual nil-out covers the equip-then-blacklist-remove pair.

	-- 
	-- V4.3.317 - Catalog Browser data layer (see Changelog for full rationale)
	-- V4.3.535 Opt-1: _CATALOG_HOST + _ECONOMY_HOST hoisted to file scope (L4533-4534).

	-- Minimal HTTP GET that picks whichever executor function is available.
	-- Avoids `game:HttpGet` first-attempts because that auto-injects Roblox-Place-Id
	-- on some executors (defeats the worker's header-strip).
	function Function.CatalogHttpGet(url)
		local ok, r = pcall(function()
			if syn and syn.request then return syn.request({Url = url, Method = "GET"})
			elseif http and http.request then return http.request({Url = url, Method = "GET"})
			elseif request then return request({Url = url, Method = "GET"})
			elseif http_request then return http_request({Url = url, Method = "GET"})
			elseif game.HttpGet then return {Body = game:HttpGet(url)}
			end
		end)
		if not ok or not r then return nil end
		-- V4.3.505: structured fallbacks (syn.request / http.request / request / http_request)
		-- return {Body, StatusCode}; HttpGet path throws on non-2xx and is handled by pcall.
		-- Pre-fix a 5xx response's bogus error body was JSONDecoded as if it were catalog data.
		local _sc = tonumber(r.StatusCode or r.Status or r.statusCode)  -- BUGFIX (bug-scan V4.5.17): tonumber - an executor returning a STRING StatusCode ("200") would throw "compare string < number" on the line below, which is PAST the pcall, so the throw escaped and killed the whole worker catalog fallback for that user. Matches the tonumber norm at every other StatusCode site.
		if _sc and (_sc < 200 or _sc >= 300) then return nil end
		local b = r.Body or r.body
		if not b or b == "" then return nil end
		-- V4.3.439: 1 MB cap on response body before JSONDecode. Same class as V4.3.423
		-- (AvatarSync `_safeDecodeJsonBody`). A hijacked Cloudflare worker or hostile
		-- proxy upstream returning a multi-MB response would OOM the executor inside
		-- HttpService:JSONDecode. Catalog responses in normal use are well under 200 KB.
		if #b > 1048576 then return nil end
		local dok, dec = pcall(HS.JSONDecode, HS, b)
		return dok and dec or nil
	end

	-- Catalog session caches - names / prices / asset types resolved once per
	-- session via per-asset GET to economy.roproxy. Re-paginating doesn't refetch.
	local _catalogNameCache  = {}
	local _catalogPriceCache = {}
	local _catalogTypeCache  = {}
	-- V4.3.350: expose name cache on Function table so the equipped-sidebar search
	-- (and other UI consumers outside this block's closure) can resolve labels.
	Function._catalogNameCache = _catalogNameCache
	-- V4.3.326: Function-table-scoped asset-type cache so the apply pipeline (see Changelog for full rationale)
	Function._catalogAssetTypeCache = Function._catalogAssetTypeCache or {}
	-- V4.3.350: persistent on-disk cache. Cold-start hydrates Function._catalogAssetTypeCache
	-- from RClothesLerp/CatalogAssetTypeCache.json; CatalogFetchAssetDetails sets a dirty flag
	-- and a 5s debounce flushes back to disk. Survives across executes so already-seen IDs
	-- never need MPS:GetProductInfo again.
	pcall(function()
		local env = System.Env
		if env.isfile and env.readfile and env.isfile("RClothesLerp/CatalogAssetTypeCache.json") then
			local _ok, _raw = pcall(env.readfile, "RClothesLerp/CatalogAssetTypeCache.json")
			if _ok and type(_raw) == "string" and #_raw > 0 then
				local _dok, _dec = pcall(HS.JSONDecode, HS, _raw)
				if _dok and type(_dec) == "table" then
					for k, v in pairs(_dec) do
						local kn = tonumber(k) or k
						Function._catalogAssetTypeCache[kn] = v
					end
				end
			end
		end
	end)
	-- Debounced flush task. Runs while script alive; checks dirty flag every 5s.
	-- V4.3.428: cancellable on script reload + cache size cap. Pre-fix the `while true do
	-- task.wait(5) end` had no termination path - every script re-execution (the most
	-- common user action) spawned a new coroutine while the prior one kept yielding forever,
	-- each pinning the orphan _catalogAssetTypeCache table + upvalues. Live per-exec leak.
	-- Also: the cache itself was unbounded; over weeks of catalog browsing it could grow
	-- to MB-class (numeric assetId → small int typeId, ~tens of bytes per entry × thousands
	-- of unique IDs) AND get serialized to disk every 5s. Caught by memory-leak audit
	-- 2026-05-14 (HIGH/HIGH coroutine leak + MED/HIGH unbounded cache).
	local _CATALOG_CACHE_MAX = 4096
	Function._catalogAssetTypeCacheRevision = Function._catalogAssetTypeCacheRevision or 0
	do
		local count = 0
		for _ in pairs(Function._catalogAssetTypeCache) do count = count + 1 end
		Function._catalogAssetTypeCacheCount = count
	end
	function Function._catalogTypeCachePut(id, value)
		local cache = Function._catalogAssetTypeCache
		if type(cache) ~= "table" or id == nil or value == nil then return false end
		id = tonumber(id) or id
		if cache[id] == value then return false end
		if cache[id] == nil then
			while (Function._catalogAssetTypeCacheCount or 0) >= _CATALOG_CACHE_MAX do
				local removed = false
				for key in pairs(cache) do
					if key ~= id then
						cache[key] = nil
						Function._catalogAssetTypeCacheCount = math.max(0, (Function._catalogAssetTypeCacheCount or 1) - 1)
						removed = true
						break
					end
				end
				if not removed then break end
			end
			Function._catalogAssetTypeCacheCount = (Function._catalogAssetTypeCacheCount or 0) + 1
		end
		cache[id] = value
		Function._catalogAssetTypeCacheRevision = (Function._catalogAssetTypeCacheRevision or 0) + 1
		Function._catalogAssetTypeCacheDirty = true
		return true
	end
	function Function._catalogTypeCacheRemove(id)
		local cache = Function._catalogAssetTypeCache
		if type(cache) ~= "table" then return false end
		id = tonumber(id) or id
		if cache[id] == nil then return false end
		cache[id] = nil
		Function._catalogAssetTypeCacheCount = math.max(0, (Function._catalogAssetTypeCacheCount or 1) - 1)
		Function._catalogAssetTypeCacheRevision = (Function._catalogAssetTypeCacheRevision or 0) + 1
		Function._catalogAssetTypeCacheDirty = true
		return true
	end
	-- Trim oversized legacy cache files at hydration time; later inserts are capped above.
	do
		local cache = Function._catalogAssetTypeCache
		local count = 0
		for _ in pairs(cache) do count = count + 1 end
		while count > _CATALOG_CACHE_MAX do
			local removed = false
			for key in pairs(cache) do
				cache[key] = nil
				count = count - 1
				Function._catalogAssetTypeCacheRevision = (Function._catalogAssetTypeCacheRevision or 0) + 1
				removed = true
				break
			end
			if not removed then break end
			Function._catalogAssetTypeCacheDirty = true
		end
		Function._catalogAssetTypeCacheCount = count
	end
	function Function._flushCatalogAssetTypeCache()
		if not Function._catalogAssetTypeCacheDirty then return true end
		local cache = Function._catalogAssetTypeCache
		local env = System and System.Env
		if type(cache) ~= "table" or type(env) ~= "table" or not env.writefile or not env.makefolder then return false end
		local revision = Function._catalogAssetTypeCacheRevision or 0
		pcall(env.makefolder, "RClothesLerp")
		local ok, saved = pcall(_atomicWriteJSON, "RClothesLerp/CatalogAssetTypeCache.json", cache)
		if not ok or saved ~= true then return false end
		if (Function._catalogAssetTypeCacheRevision or 0) == revision then
			Function._catalogAssetTypeCacheDirty = false
		end
		return true
	end
	-- Reset the stop flag from any prior execution before spawning. The handler at
	-- BREAKER.Destroying sets `Function._catalogFlushStop = true` to terminate the prior
	-- worker; without this reset, the new exec's worker would immediately exit.
	Function._catalogFlushStop = false
	-- V4.3.521 Fix 14: getgenv handoff for re-execute cancellation (mirrors V4.3.514
	-- pattern for _RC_diag_*_task). Pre-fix, this coroutine was stashed on a per-exec
	-- Function table - old exec's worker couldn't see new exec's stop flag.
	do
		local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
		local _prior = _ok_genv and _genv and _genv._RC_catalog_flush_task or nil
		if _prior then pcall(task.cancel, _prior) end
	end
	local _flushHandle = task.spawn(function()
		while true do
			task.wait(5)
			-- Exit on script reload: BREAKER's Destroying handler (L3662) sets this flag.
			if Function._catalogFlushStop then return end
			if Function._catalogAssetTypeCacheDirty then
				local ok, saved = pcall(Function._flushCatalogAssetTypeCache)
				if not ok or not saved then Function._catalogAssetTypeCacheDirty = true end
			end
		end
	end)
	-- Wire cancellation to script-teardown signal. System.GlobalMaid would also work,
	-- but BREAKER.Destroying is the canonical script-reload hook used elsewhere
	-- (L3662 handler). Storing handle on Function namespace so future audits can find it.
	Function._catalogFlushHandle = _flushHandle
	-- V4.3.521 Fix 14: stash handle on getgenv() for cross-exec cancellation.
	do
		local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
		if _ok_genv and _genv then _genv._RC_catalog_flush_task = _flushHandle end
	end

	-- V4.3.457: persist `Function._knownDeadIds` (V4.3.443) to disk so users don't
	-- re-discover content-deleted bundle accessories on every script reload. User
	-- report: "some bundle doesnt load at all, takes like a long time to load, if
	-- that specific bundle have deleted content." First-time slowness is the MPS:
	-- GetProductInfo timeout chain per dead ID; without disk persistence the user
	-- pays that cost every session. Now: cold-start hydrates from disk → known
	-- dead IDs skipped instantly on first equip. Same pattern as V4.3.350's
	-- `CatalogAssetTypeCache.json`. Pre-init the table BEFORE loading from disk.
	Function._knownDeadIds = Function._knownDeadIds or {}
	-- V4.3.496: O(1) running counter for the cap check (audit Pass D #3).
	Function._knownDeadIdsCount = Function._knownDeadIdsCount or 0
	pcall(function()
		local env = (getgenv and getgenv()) or _G
		if env.isfile and env.readfile and env.isfile("RClothesLerp/KnownDeadIds.json") then
			local _ok, _raw = pcall(env.readfile, "RClothesLerp/KnownDeadIds.json")
			if _ok and type(_raw) == "string" and #_raw > 0 then
				local _dok, _dec = pcall(HS.JSONDecode, HS, _raw)
				if _dok and type(_dec) == "table" then
					local _seeded = 0
					for k, _ in pairs(_dec) do
						local kn = tonumber(k) or k
						if type(kn) == "number" then
							if Function._knownDeadIds[kn] == nil then _seeded = _seeded + 1 end
							Function._knownDeadIds[kn] = true
						end
					end
					Function._knownDeadIdsCount = Function._knownDeadIdsCount + _seeded
				end
			end
		end
	end)
	-- Debounced flush task - mirrors the catalog-cache flush at L10837. 5s wait per
	-- iteration; flushes when `Function._knownDeadIdsDirty` is set true by a worker
	-- registering a new dead ID. Cap at 4096 entries (FIFO drop, V4.3.443 pattern).
	Function._knownDeadIdsFlushStop = false
	local _DEAD_CACHE_MAX = 4096
	-- V4.3.521 Fix 14: getgenv handoff for re-execute cancellation (mirrors V4.3.514 pattern).
	do
		local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
		local _prior = _ok_genv and _genv and _genv._RC_dead_flush_task or nil
		if _prior then pcall(task.cancel, _prior) end
	end
	local _deadFlushHandle = task.spawn(function()
		while true do
			task.wait(5)
			if Function._knownDeadIdsFlushStop then return end
			if Function._knownDeadIdsDirty then
				Function._knownDeadIdsDirty = false
				pcall(function()
					-- V4.3.513 Fix 9: refetch + type-check (mirror of catalog-flush guard).
					local _cache = Function._knownDeadIds
					if type(_cache) ~= "table" then return end
					-- V4.3.504: O(1) running counter (V4.3.496) replaces the pairs walk -
					-- the counter is already maintained at every insert/evict site.
					local _count = Function._knownDeadIdsCount or 0
					if _count > _DEAD_CACHE_MAX then
						local _toDrop = _count - _DEAD_CACHE_MAX
						local _dropped = 0
						for k in pairs(_cache) do
							if _toDrop <= 0 then break end
							_cache[k] = nil
							_toDrop = _toDrop - 1
							_dropped = _dropped + 1
						end
						-- V4.3.503: fall back to live in-memory count (was _dropped, which made the
						-- nil branch evaluate to 0 regardless of actual size); clamp at zero.
						Function._knownDeadIdsCount = math.max(0, (Function._knownDeadIdsCount or _count) - _dropped)
					end
					local env = (getgenv and getgenv()) or _G
					if not (env.writefile and env.makefolder) then return end
					pcall(env.makefolder, "RClothesLerp")
					-- Serialize as `{[id]=true, ...}` (matches in-memory shape).
					-- V4.3.504: route through atomic-write.
					_atomicWriteJSON("RClothesLerp/KnownDeadIds.json", _cache)
				end)
			end
		end
	end)
	Function._knownDeadIdsFlushHandle = _deadFlushHandle
	-- V4.3.521 Fix 14: stash handle on getgenv() for cross-exec cancellation.
	do
		local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
		if _ok_genv and _genv then _genv._RC_dead_flush_task = _deadFlushHandle end
	end

	-- V4.3.351: consolidated all catalog state into ONE table on Function namespace.
	-- Pre-fix V4.3.350 added 9 RoClothes-scope locals (cache tables + helper functions
	-- + AvatarEditorService ref) which pushed the function past Luau's 200-register cap
	-- at L16142. Single-table form keeps the same behavior with 1 register slot, and
	-- Function.X helpers cost 0 RoClothes-scope locals.
	Function._CB = Function._CB or {
		pageCache = {},        -- key -> {items, nextCursor}
		pageCacheOrder = {},   -- FIFO list of keys
		pageCacheCap = 64,   -- V4.4.2: raised from 8. It's a single FIFO shared across ALL queries and the native cursor is forward-only, so once evicted, clicking Prev to that page silently showed the wrong content. 64 makes eviction rare in normal browsing.
		nativePages = {},      -- query-signature -> CatalogPages
		nativePageNum = {},    -- PHASE 14 (ISSUE 7): query-signature -> current native page number (1-based). Used to mint a UNIQUE per-page cursor on the native path (see CatalogFetchPageNative) so the FIFO page cache does not collapse every page >=2 onto a single "NEXT" key.
		avatarEditorService = nil,
	}
	Function._CB.nativeQueryCap = 64
	Function._CB.nativeQueryOrder = Function._CB.nativeQueryOrder or {}
	Function._CB.nativeBusy = Function._CB.nativeBusy or {}
	Function._CB.nativeLastCursor = Function._CB.nativeLastCursor or {}
	Function._CB.workerCursorPrefix = "RCW:"
	pcall(function() Function._CB.avatarEditorService = game:GetService("AvatarEditorService") end)
	function Function._CB_pageKey(category, subcategory, assetTypes, keyword, cursor, useFilters, filters, provider)
		local _at = (assetTypes and #assetTypes > 0) and table.concat(assetTypes, ",") or ""
		local _ff = ""
		if useFilters and filters then
			_ff = string.format("|free=%s|min=%s|max=%s|cre=%s",
				tostring(filters.freeOnly), tostring(filters.minPrice or ""), tostring(filters.maxPrice or ""), tostring(filters.creator or ""))
		end
		return string.format("%s|%s|%s|%s|%s%s|provider=%s",
			tostring(category), tostring(subcategory or ""), _at,
			tostring(keyword or ""), tostring(cursor or ""), _ff, tostring(provider or "auto"))
	end
	function Function._CB_pageGet(k)
		local _e = Function._CB.pageCache[k]
		if _e then return _e.items, _e.nextCursor end
		return nil
	end
	function Function._CB_pagePut(k, items, nextCursor)
		if Function._CB.pageCache[k] then return end
		Function._CB.pageCache[k] = {items = items, nextCursor = nextCursor}
		table.insert(Function._CB.pageCacheOrder, k)
		while #Function._CB.pageCacheOrder > Function._CB.pageCacheCap do
			local _old = table.remove(Function._CB.pageCacheOrder, 1)
			Function._CB.pageCache[_old] = nil
		end
	end
	function Function._CB_nativeDrop(sigKey)
		Function._CB.nativePages[sigKey] = nil
		Function._CB.nativePageNum[sigKey] = nil
		Function._CB.nativeLastCursor[sigKey] = nil
		for i = #Function._CB.nativeQueryOrder, 1, -1 do
			if Function._CB.nativeQueryOrder[i] == sigKey then table.remove(Function._CB.nativeQueryOrder, i) end
		end
	end
	function Function._CB_nativeRemember(sigKey, pagesObj, pageNum)
		if not Function._CB.nativePages[sigKey] then table.insert(Function._CB.nativeQueryOrder, sigKey) end
		Function._CB.nativePages[sigKey] = pagesObj
		Function._CB.nativePageNum[sigKey] = pageNum
		while #Function._CB.nativeQueryOrder > Function._CB.nativeQueryCap do
			local oldest = table.remove(Function._CB.nativeQueryOrder, 1)
			Function._CB.nativePages[oldest] = nil
			Function._CB.nativePageNum[oldest] = nil
			Function._CB.nativeLastCursor[oldest] = nil
		end
	end
	function Function._CB_nativeKey(category, subcategory, assetTypes, keyword, filters)
		return Function._CB_pageKey(category, subcategory, assetTypes, keyword, "", true, filters, "native")
	end
	function Function.CatalogFetchPageNative(category, subcategory, assetTypes, keyword, cursor, limit, filters)
		if not Function._CB.avatarEditorService then return nil, nil, "no AvatarEditorService" end
		local sigKey = Function._CB_nativeKey(category, subcategory, assetTypes, keyword, filters)
		local isFirstCall = (not cursor or cursor == "" or cursor == "FIRST")
		local requestedPage = nil
		if not isFirstCall then
			local token = tostring(cursor)
			requestedPage = tonumber(token:match("^NEXT(%d+)$"))
			if token == "NEXT" then requestedPage = (Function._CB.nativePageNum[sigKey] or 1) + 1 end
			if not requestedPage then return nil, nil, "not a native cursor" end
		end
		local waitedForQuery = false
		while Function._CB.nativeBusy[sigKey] do waitedForQuery = true; task.wait() end
		Function._CB.nativeBusy[sigKey] = true
		local result = table.pack(pcall(function()
			local pagesObj = Function._CB.nativePages[sigKey]
			local currentPage = Function._CB.nativePageNum[sigKey] or 0
			local requestCursor = (not cursor or cursor == "" or cursor == "FIRST") and "FIRST" or tostring(cursor)
			local replaySameRequest = waitedForQuery and Function._CB.nativeLastCursor[sigKey] == requestCursor
			if not isFirstCall and not pagesObj then
				return nil, nil, "native page-set lost - reset pagination"
			end
			if not isFirstCall and requestedPage < currentPage then
				return nil, nil, "native cursor expired - reset pagination"
			end
			if isFirstCall and not replaySameRequest then
				Function._CB_nativeDrop(sigKey)
				-- V4.5.17: CatalogSearchParams is a DATATYPE (like Random/TweenInfo), NOT an Instance -> `Instance.new` throws
			-- "Unable to create an Instance of type CatalogSearchParams" on EVERY client, which silently killed this whole
			-- native in-engine path and forced everything onto the krulhub.dev/roproxy fallbacks (the source of the
			-- missing names/prices + fixed order). The correct constructor is `CatalogSearchParams.new()`. With this, the
			-- official AvatarEditorService:SearchCatalog does the browse - no proxy, full Name/Price/AssetType per item.
			local _ok, _params = pcall(function() return CatalogSearchParams.new() end)
			if not _ok or not _params then return nil, nil, "CatalogSearchParams unavailable" end
			pcall(function() if keyword and keyword ~= "" then _params.SearchKeyword = keyword end end)
			pcall(function() _params.SortType = Enum.CatalogSortType.Relevance end)  -- V4.5.17: algorithm/recommended order (owner wanted "the algorithm's suggestion", not the price-ascending default)
			pcall(function() _params.IncludeOffSale = not (filters and filters.freeOnly) end)  -- BUGFIX: `X and false or true` can NEVER be false, so IncludeOffSale was ALWAYS true (Free-Only had no effect on the native path). Use `not`.
			pcall(function()
				if filters and tonumber(filters.minPrice) then _params.MinPrice = tonumber(filters.minPrice) end
				if filters and tonumber(filters.maxPrice) then _params.MaxPrice = tonumber(filters.maxPrice) end
					if filters and filters.freeOnly then _params.MaxPrice = 0 end  -- BUGFIX: Free-Only must cap price at 0 to actually filter (the worker path already does this; the native path was missing it).
				if filters and filters.creator and filters.creator ~= "" then _params.CreatorName = filters.creator end
			end)
			-- AssetTypes: numeric IDs from worker map directly to Enum.AvatarAssetType for the
			-- common cases (Hat=8, ShirtAccessory=41, etc). Pcall-guarded since some IDs may
			-- not have a matching enum on older Roblox builds.
			if assetTypes and #assetTypes > 0 then
				pcall(function()
					local _enums = {}
					for _, _id in ipairs(assetTypes) do
						for _, _enum in ipairs(Enum.AvatarAssetType:GetEnumItems()) do
							if _enum.Value == _id then table.insert(_enums, _enum) break end
						end
					end
					if #_enums > 0 then _params.AssetTypes = _enums end
				end)
			end
			local _searchOk, _pages = pcall(Function._CB.avatarEditorService.SearchCatalog, Function._CB.avatarEditorService, _params)
			if not _searchOk or not _pages then return nil, nil, "native SearchCatalog failed: " .. tostring(_pages) end
			pagesObj = _pages
			currentPage = 1
			Function._CB_nativeRemember(sigKey, pagesObj, currentPage)
			elseif not isFirstCall then
				while currentPage < requestedPage do
					local _aOk, _aErr = pcall(pagesObj.AdvanceToNextPageAsync, pagesObj)
					if not _aOk then
						Function._CB_nativeDrop(sigKey)
						return nil, nil, "AdvanceToNextPageAsync failed: " .. tostring(_aErr)
					end
					currentPage = currentPage + 1
					Function._CB_nativeRemember(sigKey, pagesObj, currentPage)
				end
			end
		local _gpOk, _page = pcall(pagesObj.GetCurrentPage, pagesObj)
		if not _gpOk or type(_page) ~= "table" then return nil, nil, "GetCurrentPage failed" end
		local items = {}
		for _, d in ipairs(_page) do
			local _atyp = d.AssetType
			if typeof(_atyp) == "EnumItem" then _atyp = _atyp.Value end
			table.insert(items, {
				id           = d.Id,
				itemType     = (typeof(d.ItemType) == "EnumItem" and d.ItemType.Name) or d.ItemType or "Asset",
				name         = d.Name or ("ID " .. tostring(d.Id)),
				priceInRobux = d.Price,
				assetType    = _atyp,
				creator      = d.CreatorName or "",
			})
		end
		-- Native API doesn't expose nextPageCursor; we use a sentinel to signal
		-- "try advance on next call". If pages are exhausted, the next call's
		-- AdvanceToNextPageAsync will error and we'll return nil cursor then.
		-- PHASE 14 (ISSUE 7): the sentinel encodes the NEXT page number ("NEXT2", "NEXT3", ...)
		-- instead of a constant "NEXT". Function.CatalogFetchPage keys its FIFO page cache by the
		-- cursor string (Function._CB_pageKey); a constant "NEXT" made every page >=2 share one key,
		-- so page 3+ served page 2's cached items forever (Next/Prev appeared stuck). A per-page
		-- cursor keeps each page's cache entry distinct while still being treated as "not first"
		-- by the isFirstCall guard above (which only special-cases ""/"FIRST"), so AdvanceToNextPageAsync
		-- still runs for every page. (The worker path already returns a real unique cursor and was unaffected.)
		local _nextPageNum = (Function._CB.nativePageNum[sigKey] or 1) + 1
		local _nextCursor = (#items > 0) and ("NEXT" .. tostring(_nextPageNum)) or nil
		-- V4.5.17: shuffle BROWSE results for a random/discovery order (owner request); keyword search keeps relevance.
		-- (The wrapper caches this shuffled order, so it's stable across re-renders and re-randomises only on fresh fetch.)
		if (not keyword or keyword == "") and #items > 1 then
			local _rng = Random.new()  -- self-seeded (real entropy) so the order varies per fetch/session
			for _i = #items, 2, -1 do local _j = _rng:NextInteger(1, _i); items[_i], items[_j] = items[_j], items[_i] end
		end
		Function._CB.nativeLastCursor[sigKey] = requestCursor
		return items, _nextCursor, nil
		end))
		Function._CB.nativeBusy[sigKey] = nil
		if not result[1] then return nil, nil, "native catalog failure: " .. tostring(result[2]) end
		return result[2], result[3], result[4]
	end

	-- Fetch one page of catalog results. category/subcategory/assetTypes are
	-- numeric IDs from /v1/categories + /v1/subcategories (verified 2026-05-08).
	-- Returns: items[], nextCursor, errMsg.
	-- V4.3.350: tries native AvatarEditorService.SearchCatalog first (no proxy, no
	-- per-IP rate limit), falls back to Cloudflare worker on failure. Wrapped with
	-- FIFO page cache so back/forward replays cached pages instantly.
	function Function.CatalogFetchPage(category, subcategory, assetTypes, keyword, cursor, limit, filters)
		local workerPrefix = Function._CB.workerCursorPrefix or "RCW:"
		local workerCursor = cursor
		local forcedWorker = type(cursor) == "string" and cursor:sub(1, #workerPrefix) == workerPrefix
		if forcedWorker then workerCursor = cursor:sub(#workerPrefix + 1) end
		local nativeCursor = not forcedWorker and (not cursor or cursor == "" or cursor == "FIRST"
			or cursor == "NEXT" or (type(cursor) == "string" and cursor:match("^NEXT%d+$") ~= nil))
		if nativeCursor then
			local nativeKey = Function._CB_pageKey(category, subcategory, assetTypes, keyword, cursor, true, filters, "native")
			local cached, cachedNext = Function._CB_pageGet(nativeKey)
			if cached then return cached, cachedNext, nil end
			local items, nextCursor, err = Function.CatalogFetchPageNative(category, subcategory, assetTypes, keyword, cursor, limit, filters)
			if items and #items > 0 then
				Function._CB_pagePut(nativeKey, items, nextCursor)
				return items, nextCursor, nil
			end
			-- A native NEXT sentinel carries only a native page position. Never pass it to
			-- the HTTP provider as an opaque worker cursor; only an initial request can fall back.
			if cursor and cursor ~= "" and cursor ~= "FIRST" then return nil, nil, err or "native page expired - reset pagination" end
		end
		local workerKey = Function._CB_pageKey(category, subcategory, assetTypes, keyword, workerCursor, true, filters, "worker")
		local cached, cachedNext = Function._CB_pageGet(workerKey)
		if cached then return cached, cachedNext and (workerPrefix .. tostring(cachedNext)) or nil, nil end
		local items, nextCursor, err = Function._CatalogFetchPageWorker(category, subcategory, assetTypes, keyword, workerCursor, limit, filters, workerKey)
		return items, nextCursor and (workerPrefix .. tostring(nextCursor)) or nil, err
	end

	-- Original worker-backed implementation, kept as fallback.
	function Function._CatalogFetchPageWorker(category, subcategory, assetTypes, keyword, cursor, limit, filters, _cacheKey)
		limit = limit or 30
		-- SortType: Relevance (0) ONLY for keyword search (best matches first). For BROWSE the proxy returns a FIXED
		-- order regardless of SortType (verified: SortType=0 didn't reorder), so we DON'T send it for browse - instead
		-- the results are SHUFFLED client-side below (owner wanted a random/discovery order, not the oldest-free-first
		-- look the fixed default gives). Keyword results are NOT shuffled (relevance ranking must survive).
		local p = {
			"Category=" .. tostring(category),
			"Limit=" .. tostring(limit),
			"IncludeNotForSale=true",
		}
		if keyword and keyword ~= "" then
			table.insert(p, "SortType=0")  -- Relevance for keyword search
		end
		if subcategory then table.insert(p, "Subcategory=" .. tostring(subcategory)) end
		if assetTypes and #assetTypes > 0 then
			table.insert(p, "AssetTypes=" .. table.concat(assetTypes, ","))
		end
		if keyword and keyword ~= "" then
			table.insert(p, "Keyword=" .. HS:UrlEncode(keyword))
		end
		if cursor and cursor ~= "" then
			table.insert(p, "Cursor=" .. HS:UrlEncode(cursor))
		end
		-- V4.3.350: filters (price range, creator, free-only).
		if filters then
			if filters.freeOnly then
				-- V4.3.567 H-16: removed `p[#p] = nil` here -- it dropped whatever the LAST param was
				-- (Cursor for page 2+, Keyword, AssetTypes), breaking free-item pagination/filters. The
				-- reverse-scan loop below already removes "IncludeNotForSale=true" by value, regardless of position.
				for _i = #p, 1, -1 do
					if p[_i] == "IncludeNotForSale=true" then table.remove(p, _i) end
				end
				table.insert(p, "MaxPrice=0")
			else
				if tonumber(filters.minPrice) then table.insert(p, "MinPrice=" .. tostring(tonumber(filters.minPrice))) end
				if tonumber(filters.maxPrice) then table.insert(p, "MaxPrice=" .. tostring(tonumber(filters.maxPrice))) end
			end
			if filters.creator and filters.creator ~= "" then
				table.insert(p, "CreatorName=" .. HS:UrlEncode(filters.creator))
			end
		end
		local query = table.concat(p, "&")
		-- /v1/search/items/details returns full data when it can; falls through to
		-- /v1/search/items (IDs-only) when /details returns empty.
		local data = Function.CatalogHttpGet(_CATALOG_HOST .. "/v1/search/items/details?" .. query)
		local hasDetails = data and data.data and #data.data > 0
		if not hasDetails then
			data = Function.CatalogHttpGet(_CATALOG_HOST .. "/v1/search/items?" .. query)
		end
		if not data then return nil, nil, "no response" end
		if type(data.errors) == "table" and data.errors[1] then
			return nil, nil, "api error: " .. tostring(data.errors[1].message)
		end
		if type(data.data) ~= "table" then return nil, nil, "no data array" end
		-- PHASE 15 (pager fix): the next-page cursor must survive whichever endpoint won. When the
		-- /details endpoint returns data it normally also carries nextPageCursor, but some proxy/
		-- response shapes (and the IDs-only fallback paths) can return a full page of items with the
		-- cursor missing -- which silently froze the GUI on "Page 1" with no Next button even though
		-- more pages existed. If we got a FULL page (== limit) but no cursor, fetch the lightweight
		-- /items endpoint purely to recover its nextPageCursor (it reliably includes one). We still
		-- prefer the cursor the winning response already gave us.
		local _nextCursor = data.nextPageCursor
		if (_nextCursor == nil or _nextCursor == "") and #data.data >= limit then
			local _idsData = Function.CatalogHttpGet(_CATALOG_HOST .. "/v1/search/items?" .. query)
			if _idsData and (_idsData.nextPageCursor ~= nil and _idsData.nextPageCursor ~= "") then
				_nextCursor = _idsData.nextPageCursor
			end
		end
		local items = {}
		for _, d in ipairs(data.data) do
			local id = d.id or d.Id
			-- Apply session cache (cheaper than re-fetching per-asset details).
			local n = d.name or d.Name or _catalogNameCache[id]
			local pr = d.priceInRobux or d.Price or _catalogPriceCache[id]
			local at = d.assetType or d.AssetType or _catalogTypeCache[id]
			table.insert(items, {
				id           = id,
				itemType     = d.itemType or d.ItemType or "Asset",
				name         = n or ("ID " .. tostring(id)),
				priceInRobux = pr,
				assetType    = at,
				creator      = d.creatorName or d.creatorTargetName or "",
			})
		end
		-- V4.5.17: shuffle BROWSE results (owner wanted a random/discovery order, not the proxy's fixed oldest-free-first
		-- default; SortType doesn't reorder browse on this proxy). Keyword search is left in relevance order. Shuffled
		-- BEFORE caching so the order is stable across re-renders (equip/unequip won't re-shuffle) - it re-randomises only
		-- on a fresh fetch (new page / cache miss).
		if (not keyword or keyword == "") and #items > 1 then
			local _rng = Random.new()  -- self-seeded (real entropy) so the order varies per fetch/session, not a fixed math.random default
			for _i = #items, 2, -1 do local _j = _rng:NextInteger(1, _i); items[_i], items[_j] = items[_j], items[_i] end
		end
		-- V4.3.350: cache the result if cacheKey was passed.
		if _cacheKey then Function._CB_pagePut(_cacheKey, items, _nextCursor) end
		return items, _nextCursor, nil
	end

	-- Per-asset GET on economy.roproxy.com. Used when /v1/search/items returned
	-- IDs-only and we need names/prices/assetTypes for the cells. Returns
	-- {name, price, assetType} or nil.
	function Function.CatalogFetchAssetDetails(id)
		-- V4.4.2: CACHE-FIRST. Name/price/type are cached on every prior fetch, but the equipped
		-- sidebar + catalog grid re-resolve the same ids on EVERY hotSwap -- without this each one
		-- re-issues a blocking HTTP GET per item, storming the (main-thread-blocking on mobile)
		-- executor HTTP. If we already know this id's name, return from cache and skip the network.
		if _catalogNameCache[id] ~= nil then
			return { name = _catalogNameCache[id], price = _catalogPriceCache[id], assetType = _catalogTypeCache[id] }
		end
		-- V4.3.350: 2-attempt retry on transient failure. First attempt has no delay,
		-- second waits 1s. Prior single-shot would silently mistype assets when the
		-- economy.roproxy backend was momentarily slow.
		local d
		for attempt = 1, 2 do
			d = Function.CatalogHttpGet(_ECONOMY_HOST .. "/v2/assets/" .. tostring(id) .. "/details")
			if d and not d.errors then break end
			if attempt == 1 then task.wait(1) end
		end
		if not d or d.errors then return nil end
		local out = {name = d.Name, price = d.PriceInRobux, assetType = d.AssetTypeId}
		-- V4.3.439: FIFO-drop cap on Name/Price/Type session caches. V4.3.428 capped
		-- Function._catalogAssetTypeCache at 4096 entries but missed these three siblings
		-- (same input domain - every browsed Roblox asset ID - same monotonic growth).
		-- Drop one oldest entry per insertion once over cap. Conservative single-drop
		-- mirrors the V4.3.428 sweep pattern.
		local function _capCache(_t)
			local _n = 0
			for _ in pairs(_t) do _n = _n + 1 end
			if _n >= _CATALOG_CACHE_MAX then
				for k in pairs(_t) do _t[k] = nil; break end
			end
		end
		if out.name      then _capCache(_catalogNameCache);  _catalogNameCache[id]  = out.name end
		if out.price     then _capCache(_catalogPriceCache); _catalogPriceCache[id] = out.price end
		if out.assetType then
			_capCache(_catalogTypeCache)
			_catalogTypeCache[id]  = out.assetType
			-- V4.3.326: also stash on the Function table so Function.HumanoidDescriptionSet
			-- (and other downstream consumers) can skip MPS:GetProductInfo.
			Function._catalogTypeCachePut(id, out.assetType)
			-- V4.3.350: persist the asset-type cache to disk so cold-start MPS lookups
			-- disappear forever for already-seen IDs. Debounced via dirty flag.
		end
		return out
	end

	-- Map a catalog item's numeric AssetType to which PlayerData.Catalog* field
	-- the existing apply pipeline reads. Anything in this table flows through
	-- the script's regular CharacterExecute → HumanoidDescriptionLoader path
	-- (no parallel apply system).
	--   8/41/42/43/44/45/46/47   classic accessories → CatalogAccessory[]
	--   64/65/66/67/68/69/72     layered clothing    → CatalogAccessory[]
	--   11                       Classic Shirt       → CatalogClothes.Shirt
	--   12                       Classic Pants       → CatalogClothes.Pants
	--   2                        Classic T-Shirt     → CatalogClothes.ShirtGraphic
	--   Bundle (itemType)        Outfit              → CatalogOutfitId
	function Function.CatalogIsAccessoryAssetType(atyp)
		if type(atyp) ~= "number" then return false end
		return atyp == 8 or atyp == 41 or atyp == 42 or atyp == 43
			or atyp == 44 or atyp == 45 or atyp == 46 or atyp == 47
			or atyp == 64 or atyp == 65 or atyp == 66 or atyp == 67
			or atyp == 68 or atyp == 69 or atyp == 72
	end

	-- V4.3.453: Naked Mode. One-shot "strip clothes only" feature.
	-- User request 2026-05-15: "a way to get rid of all clothes with the press of a
	-- button so you can be fully naked".
	-- V4.3.456 REWRITE: V4.3.453/454 cleared CurrentBundle + CatalogAccessory, which
	-- ALSO tore down hair / face / other identity accessories the bundle provided.
	-- User followup: "the strip feature still remove hair too. and face too." New
	-- approach: KEEP CurrentBundle / Catalog accessory fields (they provide hair,
	-- face, hats, etc.), CLEAR only cloth-class state (Krul cloth meshes + Roblox
	-- Shirt/Pants/ShirtGraphic), and set a `pd._nakedMode` flag that the bundle
	-- apply pipeline reads to suppress Bundle.Clothes propagation into the HD.
	-- Flag auto-clears on next bundle click via handleBundleClick (so re-equipping
	-- a bundle restores normal behavior).
	function Function.StripAllClothes(sp)
		local pd = PlayerData[sp]
		if not pd then return end
		pd.LastRequestID = (pd.LastRequestID or 0) + 1
		-- Krul cloth-mesh state (the green shirt/apron/etc. from Bundle.Clothes
		-- table or individual cloth checkboxes).
		pd.CurrentClothes = {}
		pd.CurrentPreset = nil
		pd.CurrentClothingBundles = {}
		pd.ClothesHP = {}
		pd.ClothesRecolor = {}
		-- Cache invalidation: equipped-set cache is identity+length keyed; force rebuild.
		pd._equippedSetSrc = nil
		-- Roblox catalog Shirt/Pants/ShirtGraphic IDs (user-set clothing). KEEP
		-- CatalogAccessory / CatalogTail / CatalogUsername / CatalogOutfitId -
		-- these provide accessories (hair, hats, face decorations) the user wore.
		pd.CatalogClothes = {Shirt = "", Pants = "", ShirtGraphic = "", Face = pd.CatalogClothes and pd.CatalogClothes.Face or ""}
		-- StripCategories: only strip ACTUAL clothing-class accessories. Hair / Face /
		-- Hat preserved so the user keeps their identity. Neck / Shoulder / Front /
		-- Back / Waist are clothing-class (ties, jackets, vests, capes, belts, skirts).
		pd.StripCategories = {Hat=false, Hair=false, Face=false, Neck=true, Shoulder=true, Front=true, Back=true, Waist=true}
		-- V4.3.456: flag the equip pipeline to suppress Bundle.Clothes propagation
		-- (the Shirt/Pants/ShirtGraphic that come FROM the bundle, applied via
		-- HumanoidDescriptionSet at L10441). Flag is consumed (read-only) by the
		-- bundle apply path and cleared automatically when a user clicks any bundle
		-- (handleBundleClick at L19488-area) so re-equipping restores normal.
		pd._nakedMode = true
		-- V4.3.456: also nuke any existing Shirt/Pants/ShirtGraphic instances on
		-- the live character. Without this, users with NO active bundle (CurrentBundle
		-- still "nil") have their default-Roblox-avatar clothes persist - the
		-- equip pipeline doesn't nuke them unless a bundle is being applied.
		pcall(function()
			local _ply = PS:FindFirstChild(sp)
			local _char = _ply and _ply.Character
			if _char then
				local _shirt = _char:FindFirstChildOfClass("Shirt")
				local _pants = _char:FindFirstChildOfClass("Pants")
				local _graphic = _char:FindFirstChildOfClass("ShirtGraphic")
				if _shirt then _shirt:Destroy() end
				if _pants then _pants:Destroy() end
				if _graphic then _graphic:Destroy() end
			end
			-- Also nuke on RealCharacter (Method-2 proxy parent target).
			local _real = pd.RealCharacter
			if _real and _real ~= _char then
				local _shirt = _real:FindFirstChildOfClass("Shirt")
				local _pants = _real:FindFirstChildOfClass("Pants")
				local _graphic = _real:FindFirstChildOfClass("ShirtGraphic")
				if _shirt then _shirt:Destroy() end
				if _pants then _pants:Destroy() end
				if _graphic then _graphic:Destroy() end
			end
		end)
		-- Tear down current state then re-execute. Accessories from bundle / catalog
		-- come back on re-equip; clothes don't because of the flag + cleared fields.
		pcall(Function.CharacterReset, sp)
	end

	function Function.CharacterReset(PlayerName,NPCClear)
		-- V4.3.261: invalidate the V4.3.256 HP-skip cache so the per-frame Threshold (see Changelog for full rationale)
		do
			local _name = (typeof(PlayerName) == "Instance") and PlayerName.Name or PlayerName
			local _pd = _name and PlayerData[_name]
			if _pd then
				-- V4.3.263: scalar cache fields (replaced V4.3.256 _hpKey string for mobile GC).
				_pd._lastH, _pd._lastMaxH = nil, nil
				_pd._lastTop, _pd._lastBot = nil, nil
				_pd._lastSTop, _pd._lastSBot = nil, nil
				_pd._lastHC = nil
			end
		end

		local ExecutePlayer
		if typeof(PlayerName) ~= "Instance" then
			-- CLONE/NPC: a string key registered in System.NPCs resolves to its MODEL so the
			-- IsCharacter branch below finds PlayerData[key] (CharacterExecute passes the raw key).
			if System.NPCs and System.NPCs[PlayerName] then
				PlayerName = System.NPCs[PlayerName]
			else
				ExecutePlayer = PS:FindFirstChild(PlayerName) -- check if this function is called by Player name target(most of time 'Self')
			end
		end

		local DataList = nil
		local PartListPlayer = nil

		if not PlayerName then
			if GUIObject.PlayerExecute.Text == "Self" then
				ExecutePlayer = Player
				DataList = PlayerData[ExecutePlayer.Name]
				if not DataList then return end
				PartListPlayer = DataList.CurrentPartList
			end
		elseif ExecutePlayer then
			if PlayerData[ExecutePlayer.Name] == nil then
				return
			end
			DataList = PlayerData[ExecutePlayer.Name]
			PartListPlayer = DataList.CurrentPartList
		end
		if type(PlayerName) ~= "string" and Function.IsCharacter(PlayerName) then
			local npcIdx = Function.TableFind(System.NPCs, PlayerName)
			if npcIdx == nil or not PlayerData[npcIdx] then
				return
			else
				DataList = PlayerData[npcIdx]
				PartListPlayer = DataList.CurrentPartList
				if NPCClear == true then
					-- V4.3.302: tear down Maid before drop.
					if DataList and DataList.ExecutionMaid then
						pcall(function() DataList.ExecutionMaid:DoCleaning() end)
					end
					PlayerData[npcIdx] = nil
					-- V4.3.374: also drop System.NPCs[npcIdx] - pre-fix only PD was
					-- nilled, leaving a strong-ref to a possibly-destroyed Model in
					-- the NPCs registry; grew unbounded across sessions.
					if System.NPCs then System.NPCs[npcIdx] = nil end
				end
			end
		end

		if PartListPlayer then
			local SpecialList = PartListPlayer.RealtimeUpdateList and PartListPlayer.RealtimeUpdateList["Special"]
			local OrganList = PartListPlayer["Organ"]
			local ClothesList = PartListPlayer["Clothes"]
			local AccessoryList = PartListPlayer["Accessory"]
			local ParentTransparencyList = PartListPlayer["ParentTransparency"]

			if SpecialList then
				for _, v in pairs(SpecialList) do
					v:Destroy()
				end
			end

			if OrganList then
				for _, v in pairs(OrganList) do
					v:Destroy()
				end
			end

			if ClothesList then
				for _, v in pairs(ClothesList) do
					v:Destroy()
				end
			end

			if AccessoryList then
				for _, v in pairs(AccessoryList) do
					v:Destroy()
				end
			end

			if ParentTransparencyList then
				for Object, Property in pairs(ParentTransparencyList) do
					pcall(function()
						local D = Property.D
						if D ~= nil then
							Object.Transparency = D
							Object.LocalTransparencyModifier = Object.Transparency
						end
					end)
				end
			end

			if PartListPlayer.OriginalTransparency then
				for i, v in pairs(PartListPlayer.OriginalTransparency) do
					pcall(function()
						i.Transparency = v
						-- V4.3.349: explicit LTM=0 restore. Pre-fix wrote `LTM = v` which set (see Changelog for full rationale)
						i.LocalTransparencyModifier = 0
					end)
				end
			end

			local char = DataList.Character
			-- V4.3.168.11: refresh `char` if the tracked reference is to a destroyed or (see Changelog for full rationale)
			if not char or not char.Parent then
				char = nil
				if type(PlayerName) ~= "string" and Function.IsCharacter(PlayerName) then
					char = PlayerName
				elseif PS:FindFirstChild(PlayerName) then
					char = PS:FindFirstChild(PlayerName).Character
				end
			end

			-- V4.3.168.11: same staleness check for RealCharacter - it can be orphaned
			-- the same way. Fall back to the live character if so.
			local realChar = DataList.RealCharacter
			if not realChar or not realChar.Parent then
				realChar = char
			end
			local bodyParts = {
				"Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg",
				"UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand",
				"RightUpperArm", "RightLowerArm", "RightHand", "LeftUpperLeg", "LeftLowerLeg",
				"LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot"
			}
			if realChar then
				for _, partName in ipairs(bodyParts) do
					local p = realChar:FindFirstChild(partName)
					if p and p:IsA("BasePart") then
						p.Transparency = 0
						p.LocalTransparencyModifier = 0
					end
				end
			end
			if char and char ~= realChar then
				for _, partName in ipairs(bodyParts) do
					local p = char:FindFirstChild(partName)
					if p and p:IsA("BasePart") then
						p.Transparency = 0
						p.LocalTransparencyModifier = 0
					end
				end
			end

			-- Restore original body colors
			local restoreTarget = DataList.RealCharacter or char
			if DataList.OriginalBodyColors and restoreTarget then
				local BodyColors = restoreTarget:FindFirstChildOfClass("BodyColors")
				if not BodyColors and DataList.IsClone then
					-- CLONE: HD/catalog builds can destroy the rig's BodyColors; recreate so the
					-- persistent skin snapshot always lands on every rebuild.
					BodyColors = Instance.new("BodyColors")
					BodyColors.Parent = restoreTarget
				end
				if BodyColors then
					for prop, color in pairs(DataList.OriginalBodyColors) do
						BodyColors[prop] = color
					end
					Function.BodyColorSet(restoreTarget, BodyColors)
				end
				-- Also restore on proxy if different
				if char and char ~= restoreTarget then
					local proxyBC = char:FindFirstChildOfClass("BodyColors")
					if proxyBC then
						for prop, color in pairs(DataList.OriginalBodyColors) do
							proxyBC[prop] = color
						end
						Function.BodyColorSet(char, proxyBC)
					end
				end
				-- CLONE FIX 3: clones keep their seeded skin snapshot permanently so every edit-
				-- rebuild repaints skin (see spawnClone EDIT A). Normal players/NPCs still clear it.
				if not DataList.IsClone then
					DataList.OriginalBodyColors = nil
				end
			end
			DataList.RealCharacter = nil

			if DataList.NippleColorFromBundle then
				DataList.NippleColor = nil
				DataList.NippleColorFromBundle = false
			end

			-- Restore original Attachment CFrames
			if DataList.OriginalAttachmentCFrames then
				for attachment, cframe in pairs(DataList.OriginalAttachmentCFrames) do
					if attachment and attachment.Parent ~= nil then
						attachment.CFrame = cframe
					end
				end
				DataList.OriginalAttachmentCFrames = {}
			end

			-- Destroy ConvertedParts
			if DataList.ConvertedPart then
				for name, entry in pairs(DataList.ConvertedPart) do
					if entry and entry.Part and entry.Part.Parent ~= nil then
						entry.Part:Destroy()
					end
					DataList.ConvertedPart[name] = nil
				end
			end

			local targetName = PlayerName
			if targetName == "Self" then
				targetName = Player.Name
			end

			if Method2CharacterFolder then
				for _, child in pairs(Method2CharacterFolder:GetChildren()) do
					if child.Name == (targetName or "NIL_FALLBACK") then
						child:Destroy()
					end
				end
			end

			DataList.CurrentPartList.BodyPartPhysics = {}
			-- Character reset releases per-character state. Session teardown separately
			-- stops the owned SmartBone runtime and destroys System._sbFolder.

			-- M-2 fix: explicitly destroy the cached MeshPart before discarding CurrentPartList.
			-- CreateMeshPartAsync returns an unparented Part that the GC may not reclaim promptly.
			if DataList.CurrentPartList["TrueMeshSize"] then
				pcall(function() DataList.CurrentPartList["TrueMeshSize"].Part:Destroy() end)
				DataList.CurrentPartList["TrueMeshSize"] = nil
			end
			DataList.CurrentPartList["TrueMeshSizePending"] = nil
			DataList.CurrentPartList.TrueMeshSizeRequest = nil
			DataList.CurrentPartList.TrueMeshSizeFailure = nil

			-- V4.3.278: disconnect orphaned RealtimeBodyTransparency signals before (see Changelog for full rationale)
			if DataList.CurrentPartList.RealtimeUpdateList and DataList.CurrentPartList.RealtimeUpdateList.Mesh then
				for _, Property in pairs(DataList.CurrentPartList.RealtimeUpdateList.Mesh) do
					if Property and Property.transparencyConn then
						pcall(function() Property.transparencyConn:Disconnect() end)
						Property.transparencyConn = nil
						Property._connectedBase = nil
					end
				end
			end

			DataList.CurrentPartList = Function.PlayerDataDefault().CurrentPartList
			-- V4.3.147: Cooldown clear removed from CharacterReset. (see Changelog for full rationale)

			local char = DataList.Character
			if not char then
				if type(PlayerName) ~= "string" and Function.IsCharacter(PlayerName) then
					char = PlayerName
				elseif game:GetService("Players"):FindFirstChild(PlayerName) then
					char = game:GetService("Players"):FindFirstChild(PlayerName).Character
				end
			end
			for i, v in pairs(game:GetService("CollectionService"):GetTagged("Visibility")) do
				v.Transparency = v:GetAttribute("Visibility")
				v.LocalTransparencyModifier = v:GetAttribute("Visibility")
				v:SetAttribute("Visibility",nil)
				v:RemoveTag("Visibility")
			end
			-- V4.3.449: read DataList.MethodAtBuild so the OldestClothings restore
			-- targets the character based on the method it was BUILT with, not the
			-- (possibly newly-changed) live Method. Pre-fix: user changes Method mid-
			-- session → CharacterReset's Shirt/Pants restore aimed at the wrong char.
			if char and ((DataList.MethodAtBuild or Method) ~= 2) then
				-- V4.3.537 Fix 1: Method-1 ONLY HD baseline restore. Replays the
				-- pre-bundle HumanoidDescription snapshot captured at first
				-- CharacterExecute (~L15828-L15843). This is the structural fix
				-- for "every time i unequip a bundle, i never revert back to my
				-- original avatar" - pre-V4.3.537 the real Humanoid kept every
				-- HD-applied accessory, body scale, face, and HD-managed body
				-- part forever because no code path inverted the bundle's
				-- ApplyDescription call at L13726. Now ApplyDescription is
				-- called BEFORE the OldestClothings clone-restore below so the
				-- HD lays the full baseline (hats, face, scale, body colors,
				-- BodyTypeScale, HeightScale, WidthScale, HeadScale, etc.) and
				-- the explicit Shirt/Pants/ShirtGraphic clones override the HD's
				-- clothing slots - script trusts its own clone-restore more for
				-- those 3 slots because they predate the V4.3.537 HD snapshot.
				-- pcall-wrapped: ApplyDescription throws on content-deleted IDs
				-- or restricted humanoids; we tolerate failure and let the
				-- OldestClothings restore + part destroy still run. Clone the
				-- snapshot before each apply so the cached Instance survives
				-- repeat resets without engine reparenting/mutation. Method 2
				-- branch at L15571 is intentionally skipped - its proxy destroy
				-- at L15464-L15470 already gives a clean visual revert without
				-- touching the real Humanoid; calling ApplyDescription here on
				-- M2 would add a flicker risk and lock in any HD pollution from
				-- another script that ran between our snapshot and now.
				if DataList.OriginalHumanoidDescription then
					local realHum = char:FindFirstChildOfClass("Humanoid")
					if realHum then
						local _applyOk, _err = pcall(function()
							local _hdClone = DataList.OriginalHumanoidDescription:Clone()
							realHum:ApplyDescription(_hdClone)
							_hdClone:Destroy()
						end)
						if _applyOk then
							pcall(Function.diag, "hd.original_restored", { player = tostring(PlayerName) })  -- V4.3.570 L-2: was tostring(Data) (undefined in CharacterReset -> "nil")
						else
							pcall(Function.diag, "hd.original_restore_failed", { player = tostring(PlayerName), err = tostring(_err) })
						end
					end
				else
					pcall(Function.diag, "hd.original_restore_skip_no_snapshot", { player = tostring(PlayerName) })
				end
				if DataList.OldestClothings.Shirt then
					if char:FindFirstChildOfClass("Shirt") then
						char:FindFirstChildOfClass("Shirt"):Destroy()
					end
					DataList.OldestClothings.Shirt:Clone().Parent = char
					DataList.OldestClothings.Shirt = nil
				else  -- naked-base reset fix: no original to restore -> strip a RoClothes-applied Shirt so a shirtless base reverts to shirtless (leaves genuine untouched clothing alone; it carries no tag)
					local _cur = char:FindFirstChildOfClass("Shirt")
					if _cur and _cur:GetAttribute("_RC_AppliedClothing") then _cur:Destroy() end  -- V4.5.17: strip RoClothes-applied 2D clothing on reset for CLONES TOO. The old "not IsClone" guard kept a raw clone's captured shirt, but clones are now managed apply targets: the bundle's 2D clothing IS _RC_AppliedClothing-tagged and must revert to base on reset, exactly like the real character (else "reset wears the last bundle's 2D clothing"). A plain clone's genuine game clothing is untagged -> left untouched.
				end
				if DataList.OldestClothings.Pants then
					if char:FindFirstChildOfClass("Pants") then
						char:FindFirstChildOfClass("Pants"):Destroy()
					end
					DataList.OldestClothings.Pants:Clone().Parent = char
					DataList.OldestClothings.Pants = nil
				else  -- naked-base reset fix
					local _cur = char:FindFirstChildOfClass("Pants")
					if _cur and _cur:GetAttribute("_RC_AppliedClothing") then _cur:Destroy() end  -- V4.5.17: strip RoClothes-applied 2D clothing on reset for CLONES TOO. The old "not IsClone" guard kept a raw clone's captured shirt, but clones are now managed apply targets: the bundle's 2D clothing IS _RC_AppliedClothing-tagged and must revert to base on reset, exactly like the real character (else "reset wears the last bundle's 2D clothing"). A plain clone's genuine game clothing is untagged -> left untouched.
				end
				if DataList.OldestClothings.ShirtGraphic then
					if char:FindFirstChildOfClass("ShirtGraphic") then
						char:FindFirstChildOfClass("ShirtGraphic"):Destroy()
					end
					DataList.OldestClothings.ShirtGraphic:Clone().Parent = char
					DataList.OldestClothings.ShirtGraphic = nil
				else  -- naked-base reset fix
					local _cur = char:FindFirstChildOfClass("ShirtGraphic")
					if _cur and _cur:GetAttribute("_RC_AppliedClothing") then _cur:Destroy() end  -- V4.5.17: strip RoClothes-applied 2D clothing on reset for CLONES TOO. The old "not IsClone" guard kept a raw clone's captured shirt, but clones are now managed apply targets: the bundle's 2D clothing IS _RC_AppliedClothing-tagged and must revert to base on reset, exactly like the real character (else "reset wears the last bundle's 2D clothing"). A plain clone's genuine game clothing is untagged -> left untouched.
				end
				-- V4.3.446: restore catalog-Username-path Head Decal + SpecialMesh.
				-- M1 path destroyed the originals when the catalog Head was applied;
				-- without this restore the user kept the catalog face / head shape
				-- until respawn even after switching off the catalog bundle.
				local _restoreHead = char and char:FindFirstChild("Head")
				if DataList.OldestClothings.HeadDecal and _restoreHead then
					local _existing = _restoreHead:FindFirstChildOfClass("Decal")
					if _existing then _existing:Destroy() end
					DataList.OldestClothings.HeadDecal:Clone().Parent = _restoreHead
					DataList.OldestClothings.HeadDecal = nil
				elseif _restoreHead then
					-- Dynamic/faceless originals have no saved decal to restore.
					-- Remove only our explicit catalog face, preserving game-owned decals.
					local _existing = _restoreHead:FindFirstChildOfClass("Decal")
					if _existing and _existing:GetAttribute("_RC_CatalogFace") then _existing:Destroy() end
				end
				if DataList.OldestClothings.HeadSpecialMesh and _restoreHead then
					local _existing = _restoreHead:FindFirstChildOfClass("SpecialMesh")
					if _existing then _existing:Destroy() end
					DataList.OldestClothings.HeadSpecialMesh:Clone().Parent = _restoreHead
					DataList.OldestClothings.HeadSpecialMesh = nil
				end
			else
				-- V4.3.142: Method 2 - clear stale OldestClothings without restoring.
				-- Real char retains its original shirt naturally; stale refs just wasted memory.
				DataList.OldestClothings.Shirt = nil
				DataList.OldestClothings.Pants = nil
				DataList.OldestClothings.ShirtGraphic = nil
				-- V4.3.446: M2 path's catalog Head modifications were on proxy oChar's
				-- Head, which is destroyed with the proxy. The cloned originals stored
				-- via OldestClothings would re-pollute the next equip if not cleared.
				-- Real character's head was never touched in M2 path; clear without restore.
				DataList.OldestClothings.HeadDecal = nil
				DataList.OldestClothings.HeadSpecialMesh = nil
			end

		end
	end

	function Function.RodPhysics(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		if DataDetail.BodyPartPhysics then
			local rotationMappings = System.Transformation.RotationMappings
			local PhysicsRotationOffset
			local Rotation = System.Transformation.PhysicsRotation.RodDefault

			if ObjectInstance.Name == "Rod" then
				Rotation = System.Transformation.PhysicsRotation.Rod
				PhysicsRotationOffset = rotationMappings.Rod
			elseif ObjectInstance.Name == "HorseRod" then
				Rotation = System.Transformation.PhysicsRotation.Rod
				PhysicsRotationOffset = rotationMappings.HorseRod
			else
				PhysicsRotationOffset = rotationMappings.OrganTorso
			end

			local rodBase = DataDetail.CurrentPartList["Organ"]["Torso"]
			if not rodBase then return end
			Function.SpringCreate(
				ObjectInstance,
				rodBase,
				Vector3.new(0,0,0),
				Vector3.new(0,0,0),
				DataDetail.CockStiffness or System.Physics.SpringConfigs.Default.Speed,
				DataDetail.CockDamping or System.Physics.SpringConfigs.Default.Damper,
				{X="X", Y="Y", Z="Z"},
				System.Transformation.PhysicsPosition.Default,
				PhysicsRotationOffset,
				Rotation,
				Data
			)
		end
	end

	function Function.BBCBallPhysics(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		if DataDetail.BodyPartPhysics then
			local rotationMappings = System.Transformation.RotationMappings
			local Rod
			local PhysicsRotationOffset

			if ObjectInstance.Name == "BBC Balls" then
				Rod = DataDetail.CurrentPartList["Clothes"]["BBC Rod"]
				PhysicsRotationOffset = rotationMappings.BBCBalls
			elseif ObjectInstance.Name == "ballsKnot" or ObjectInstance.Name == "ballsKnotR" then
				if ObjectInstance.Name == "ballsKnot" then
					Rod = DataDetail.CurrentPartList["Clothes"]["mainKnot"]
				else
					Rod = DataDetail.CurrentPartList["Clothes"]["mainKnotRetracted"]
				end
				PhysicsRotationOffset = rotationMappings.BallsKnot
			elseif ObjectInstance.Name == "HorseBall" then
				Rod = DataDetail.CurrentPartList["Clothes"]["HorseRod"]
				PhysicsRotationOffset = rotationMappings.HorseBall
			else
				Rod = DataDetail.CurrentPartList["Clothes"]["Cock"]
				PhysicsRotationOffset = rotationMappings.Default
			end

			if not Rod then return end
			Function.SpringCreate(
				ObjectInstance,
				Rod,
				Vector3.new(0,0,0),
				Vector3.new(0,0,0),
				DataDetail.CockStiffness or System.Physics.SpringConfigs.Default.Speed,
				DataDetail.CockDamping or System.Physics.SpringConfigs.Default.Damper,
				{
					X = "X",
					Y = "Y",
					Z = "Z",
				},
				Vector3.new(0,0,0),
				PhysicsRotationOffset,
				System.Transformation.PhysicsRotation.BBCBalls,
				Data
			)
		end
	end

	-- V4.3.447: accept optional `MethodOverride` arg. Pre-fix Converter read the live
	-- outer-scope `Method` upvalue at L11441, so if the user changed the Method
	-- dropdown between CharacterExecute's `_MethodAtExec` capture and Converter
	-- running, the LocalTransparencyModifier set here used the new value while
	-- downstream paths used the captured value - inconsistent state. Caller passes
	-- the captured method; fallback to outer-scope for paths that don't.
	function Function.Converter(Character, Data, RequestID, MethodOverride)
		local _Method = MethodOverride or Method
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		for _, v in pairs(Character:GetChildren()) do
			if v:IsA("BasePart") and R15Transparency[v.Name] then
				--v.Transparency = 1
				DataDetail.CurrentPartList.ParentTransparency[v] = {D=0,T=1}
			end
		end
		if Character:FindFirstChild("UpperTorso") and not Character:FindFirstChild("Torso") then
			-- V4.3.535 Opt-3: inlined System.ConvertPart / System.R6Mesh / System.R6Size /
			-- System.Materials.Mappings (cold path, R15→R6 conversion runs on R15-only avatars).
			for New, Base in pairs(System.ConvertPart) do
				local BasePart = Character:FindFirstChild(Base)

				if BasePart then
					local Part

					-- V4.3.309: route R6→R15 conversion meshes through cache. R6Mesh URLs
					-- are fixed Roblox stock asset IDs; first call yields, every subsequent
					-- character respawn / bundle apply clones from cache instantly.
					if New == "Torso" then
						Part = Function.CachedCreateMeshPartAsync(System.R6Mesh[New.."Female"],
							Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
					else
						Part = Function.CachedCreateMeshPartAsync(System.R6Mesh[New],
							Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
					end
					if not Part then return end  -- cache miss + create fail; bail
					if Function.IsStaleOrGone(Data, RequestID) then return end  -- V4.3.452

					Part.Name = New
					Part.Color = BasePart.Color
					Part.CanCollide = false
					Part.CanQuery = false
					Part.CanTouch = false
					Part.Massless = true
					Part.CustomPhysicalProperties = DefaultProperties
					Part.Size = System.R6Size[New]
					Part.Material = System.Materials.Mappings.SmoothPlastic
					Part:SetAttribute("Visibility",1)
					Part:AddTag("Visibility")

					Part.CFrame = BasePart.CFrame
					local Weld = Instance.new("Weld", Part)
					Weld.Part0 = BasePart
					Weld.Part1 = Part
					Weld.C0 = System.WeldCFrame[New]  -- V4.3.535 Opt-3: inlined

					Part.Parent = Character
					if _Method == 2 then Part.LocalTransparencyModifier = 1 end  -- V4.3.447: captured

					Part:AddTag(System.RCTag)
					DataDetail.ConvertedPart[New] = {Part = Part, Weld = Weld, Base = BasePart}
				end
			end
		elseif Character:FindFirstChild("UpperTorso") and Character:FindFirstChild("Torso") then
			for i, v in pairs(DataDetail.ConvertedPart) do
				v.Part.Transparency = 0
				v.Part:SetAttribute("Visibility",1)
				v.Part:AddTag("Visibility")
			end
		end
	end

	function Function.CharacterExecute(Character, Data, bool, RequestID)
		local completion = {done = false, ok = false}
		local DataDetail = PlayerData[Data]
		if not DataDetail then completion.done = true; completion.error = "missing PlayerData"; return completion end

		-- V4.3.447: belt-and-suspenders reset of the catalog-applied flag at entry.
		-- Any stale `true` left by a late-finishing worker from a superseded equip
		-- would mis-gate this execute's BodyColorForceSet decision. The RID-gated
		-- write at HD-loader-time (V4.3.447 fix above) is the primary safeguard;
		-- this is the secondary.
		DataDetail._catalogAppliedBodyColor = nil

		-- V4.3.446: capture Method at function entry. Pre-fix the outer-scope `Method`
		-- upvalue was read on each `if Method == 2 then` check; if the user switched
		-- the Method dropdown mid-equip, downstream checks read the NEW value while
		-- earlier ones used the old → torn proxy/non-proxy branches mid-run. Capture
		-- once, read `_MethodAtExec` everywhere inside this function. Mutation:
		-- `Method == 2` is rewritten below to `_MethodAtExec == 2` in subsequent
		-- edits. The outer-scope `Method` is left as the source-of-truth for the
		-- NEXT execute.
		local _MethodAtExec = (DataDetail and DataDetail.IsClone) and 1 or Method  -- CLONE: always build/render Method 1 (direct onto the rig); Method-2/3 proxy maps onto the LOCAL player, never a clone
		-- V4.3.449: persist the captured method onto DataDetail so per-frame loops
		-- (PreRender/Heartbeat/RenderStepped) read the value the character was BUILT
		-- with, not the live `Method` upvalue (which may have changed since). This
		-- closes the V4.3.448 "MethodOverride only fixed equip chain" gap - without
		-- this, per-frame logic at L15252/L15819/L16046/L16211/L16295/L16417 still
		-- consulted live `Method`, causing visual mismatch during/after a Method
		-- dropdown change.
		DataDetail.MethodAtBuild = _MethodAtExec

		if DataDetail.ExecutionMaid then
			DataDetail.ExecutionMaid:DoCleaning()
		end
		DataDetail.ExecutionMaid = Maid.new()

		task.defer(function()
			local _ceOk, _ceErr = pcall(function()
			if Function.IsStaleOrGone(Data, RequestID) then return end  -- V4.3.452: catches player-leave during the task.defer schedule

			-- V4.3.263 (mobile-perf O1): two-phase apply on mobile. Bundle apply + (see Changelog for full rationale)
			if UIS and UIS.TouchEnabled and not UIS.KeyboardEnabled then
				task.wait()
			end

			if not Character or not Function.CharacterIsBuilt(Character) then
				-- V4.3.431: streaming-wait poll cadence dropped 0.2s → 0.05s. Pre-fix the
				-- 5s budget was hit via 25 × 200ms polls, which on average wastes ~100ms
				-- past actual completion and up to 200ms on every cold spawn. 100 × 50ms
				-- still gives the same 5s timeout but reduces typical waste 4×. Caught by
				-- bundle-equip audit 2026-05-14 (HIGH ~100-800ms typical reclaim).
				local count = 0
				repeat
					task.wait(0.05)
					count = count + 1
				until Function.CharacterIsBuilt(Character) or count > 100
					or Function.IsStaleOrGone(Data, RequestID)  -- V4.3.452
				if Function.IsStaleOrGone(Data, RequestID) then return end  -- V4.3.452
				if not Function.CharacterIsBuilt(Character) then
					-- V4.3.168.22: surface timeout so users see WHY the bundle didn't apply
					-- after clicking. Previously silent return left user thinking the click
					-- didn't register. With the 5s wait (25 × 0.2s), this only fires if
					-- character streaming genuinely didn't complete - rare but meaningful
					-- signal when it does.
					warn("[RoClothes] CharacterExecute: character not fully built after 5s (streaming race); bundle apply skipped. Try clicking the bundle again.")
					return
				end
			end

			if Function.IsStaleOrGone(Data, RequestID) then return end  -- V4.3.452

			local Human = Character:FindFirstChildOfClass("Humanoid")
			if not Human then return end

			Function.PlayerDataAdd(Data)

			local DataDetail = PlayerData[Data]

			-- V4.3.537 Fix 1: snapshot the player's pre-bundle HumanoidDescription
			-- ONCE per fresh character so CharacterReset's Method-1 branch can
			-- restore it on unequip. Pre-V4.3.537 no code path captured this, so
			-- every HD-applied accessory / face / scale / body-part stayed
			-- permanently mutated on Method 1 (Method 2 hid the bug via its
			-- proxy-destroy lifecycle). User report 2026-06-05: "every time i
			-- unequip a bundle, i never revert back to my original avatar."
			-- Guard: only fires on first execute per character - the field is
			-- cleared on respawn (see CharacterAdded handler at ~L16626-area
			-- where DataList is replaced from PlayerDataDefault). If another
			-- script has already mutated the HD before us, we capture that
			-- polluted baseline - acceptable limitation; we can only restore
			-- what we can observe. ClothesList branch of bundle apply mutates
			-- via ApplyDescription downstream (L13726-area), AFTER this snapshot.
			if not DataDetail.OriginalHumanoidDescription then
				local _hdOk, _hd = pcall(function() return Human:GetAppliedDescription() end)
				if _hdOk and _hd then
					local _cloneOk, _clone = pcall(function() return _hd:Clone() end)
					if _cloneOk and _clone then
						DataDetail.OriginalHumanoidDescription = _clone
						pcall(Function.diag, "hd.original_captured", { player = tostring(Data) })
					else
						pcall(Function.diag, "hd.original_clone_failed", { player = tostring(Data), err = tostring(_clone) })
					end
				else
					pcall(Function.diag, "hd.original_capture_failed", { player = tostring(Data), err = tostring(_hd) })
				end
			end

			-- V4.3.148: Serialize deferred executions via wait loop. (see Changelog for full rationale)
			-- V4.3.299: timeout reduced from 150 frames (~2.5s) to 30 frames (~0.5s).
			do
				local waitCount = 0
				while DataDetail.Cooldown == true and waitCount < 30 do
					if Function.IsStaleOrGone(Data, RequestID) then return end  -- V4.3.452
					task.wait()
					waitCount = waitCount + 1
				end
				if DataDetail.Cooldown == true then DataDetail.Cooldown = false end
			end

			if Function.IsStaleOrGone(Data, RequestID) then return end  -- V4.3.452

			DataDetail["Cooldown"] = true

			-- V4.3.349: helper for RID-stale early returns inside CharacterExecute body. (see Changelog for full rationale)
			-- V4.3.452: also bail on player-leave (PlayerData[Data] nil). Pre-V4.3.452
			-- the captured `DataDetail` upvalue still pointed to an orphan PD after
			-- PlayerRemoving - its LastRequestID never advanced, so the stale-RID
			-- check never tripped, but the function continued writing into the orphan
			-- (pinning Instance refs in CurrentPartList). Re-fetch PD each call so a
			-- player-leave mid-yield is caught alongside RID-stale.
			local function _bailIfStale()
				local _pd = PlayerData[Data]
				if not _pd then return true end  -- player left
				if RequestID and RequestID ~= _pd.LastRequestID then
					if _pd.Cooldown == true then _pd.Cooldown = false end
					return true
				end
				return false
			end

			pcall(Function.CharacterReset, Data)
			-- V4.3.424: stale-RID guard between CharacterReset and the Method-2 proxy build. (see Changelog for full rationale)
			if _bailIfStale() then return end

				-- V4.3.142: re-hide real-char body parts after CharacterReset.
				if _MethodAtExec == 2 and Character and Character.Parent ~= nil then  -- V4.3.446
					for _, v in pairs(Character:GetChildren()) do
						if v:IsA("BasePart") and v.Name ~= "Head" and (table.find(Method2BodyPart, v.Name) or v.Name == "HumanoidRootPart") then
							v.LocalTransparencyModifier = 1
						end
					end
				end

			DataDetail["Character"] = Character

			local _convOk, _convErr = pcall(Function.Converter, Character, Data, RequestID, _MethodAtExec)  -- V4.3.447: pass captured method
			if not _convOk then
				warn("[RoClothes] Converter error (mesh load failed):", _convErr)
				DataDetail["Cooldown"] = false return
			end
			if PlayerData[Data] ~= DataDetail then DataDetail["Cooldown"] = false return end
			if _bailIfStale() then return end
			Function.AttachmentCreate(Character)

			local CharacterAttachment = Function.CharacterFunction(Character, Data)

			if Human then
				DataDetail.SavedPreviousHP = Human.Health
				if DataDetail.TopHP ~= "" then
					DataDetail.SavedTopHP = tonumber(DataDetail.TopHP) or 0  -- BUGFIX: TopHP is a TextBox STRING but every Saved*HP consumer compares numerically (`<=0`, `< _top`) -> "compare string with number" throw; coerce at the seed (default is already 0).
				end
				if DataDetail.BottomHP ~= "" then
					DataDetail.SavedBottomHP = tonumber(DataDetail.BottomHP) or 0  -- BUGFIX: same string-vs-number crash as SavedTopHP above.
				end
			end
			DataDetail.TopRipped = false
			DataDetail.BottomRipped = false
			local OldCharacter
			if _MethodAtExec == 2 then  -- V4.3.446: use captured method
				OldCharacter = Character
				DataDetail.RealCharacter = Character

				if _bailIfStale() then return end

				Character = Method2CharacterFolder:FindFirstChild(Data)

				if Character then
					Character:Destroy()
					Character = nil
				end

				if not Character then
					Character = Instance.new("Model", Method2CharacterFolder)
					Character:AddTag(System.RCTag)
					Character.Archivable = not hidden
					Character.Name = Data
					local CharacterValue = Instance.new("ObjectValue", Character)
					CharacterValue.Value = OldCharacter

					for _, v in pairs(CharacterValue.Value:GetChildren()) do
						-- V4.3.420: pre-V4.3.349 inline RID-stale check replaced with (see Changelog for full rationale)
						if _bailIfStale() then
							Character:Destroy() -- Self-Cleanup before exit
							return
						end

						if v:IsA("BasePart") and (table.find(Method2BodyPart, v.Name) or v.Name == "HumanoidRootPart") then
							if v.Name ~= "Head" then
								DataDetail.CurrentPartList.ParentTransparency[v] = {D = v.Transparency,T = 1}
							end

							local Part = Instance.new("Part", Character)
							Part.Size = v.Size
							Part.Name = v.Name
							Part.Transparency = 1
							Part.CanCollide = false
							Part.CanQuery = false
							Part.CanTouch = false
							Part.Massless = true
							Part.CustomPhysicalProperties = DefaultProperties
							Part.Color = v.Color

							Part.CFrame = v.CFrame
							local Weld = Instance.new("Weld", Part)
							Weld.Part0 = v
							Weld.Part1 = Part

							if Part.Name == "HumanoidRootPart" then
								local RootWeldTarget = CharacterValue.Value:FindFirstChild("Torso") or CharacterValue.Value:FindFirstChild("UpperTorso")
								if RootWeldTarget then
									Weld.Part0 = RootWeldTarget
								else
									Weld.Part0 = v
								end
								Character.PrimaryPart = Part
							else
								Weld.Part0 = v
							end

							local detectRemoval
							detectRemoval = Part.ChildRemoved:Connect(function(c)
								-- V4.3.496: was `Part.Parent ~= nil` (audit Pass B #2,
								-- same bug class as L11122 / V4.3.424 fix).
								if Part:IsDescendantOf(game) then
									if c:IsA("Weld") and c.Part0 == v then
										Function.TryRecloneWeld(Part, c)
									end
								else
									GlobalMaid:Remove(detectRemoval)
								end
							end)
							GlobalMaid:Give(detectRemoval)
						end
					end
				end
				if OldCharacter:FindFirstChildOfClass("Shirt") then
					if _bailIfStale() then Character:Destroy() return end  -- V4.3.349
					if Character:FindFirstChildOfClass("Shirt") then
						Character:FindFirstChildOfClass("Shirt"):Destroy()
					end
					OldCharacter:FindFirstChildOfClass("Shirt"):Clone().Parent = Character
				end
				if OldCharacter:FindFirstChildOfClass("Pants") then
					if _bailIfStale() then Character:Destroy() return end  -- V4.3.349
					if Character:FindFirstChildOfClass("Pants") then
						Character:FindFirstChildOfClass("Pants"):Destroy()
					end
					OldCharacter:FindFirstChildOfClass("Pants"):Clone().Parent = Character
				end
			end

			-- V4.3.221: clear stale HPClothes (Shirt/Pants) before applying current bundle's
			-- TClothes. Without this, prior bundle's Shirt/Pants persist if the new bundle
			-- only overrides one or none - community report: switching bundles caused the
			-- HP strip to swap in shirt/pants from a PREVIOUS bundle instead of the current.
			DataDetail.HPClothes.Shirt = ""
			DataDetail.HPClothes.Pants = ""
			if Bundle[DataDetail.CurrentBundle] and Bundle[DataDetail.CurrentBundle]["TClothes"] then
				for i, v in pairs(Bundle[DataDetail.CurrentBundle]["TClothes"]) do
					DataDetail.HPClothes[i] = v
				end
			end

			if DataDetail.NippleColorFromBundle then
				DataDetail.NippleColor = nil
				DataDetail.NippleColorFromBundle = false
			end
			if Bundle[DataDetail.CurrentBundle] and Bundle[DataDetail.CurrentBundle]["NippleColor"] and DataDetail.Tone == "Use NippleColor" then
				DataDetail.NippleColor = Bundle[DataDetail.CurrentBundle]["NippleColor"]
				DataDetail.NippleColorFromBundle = true
			end

			local TShirt = Character:FindFirstChildOfClass("ShirtGraphic")
			local Shirt = Character:FindFirstChildOfClass("Shirt")
			local Pants = Character:FindFirstChildOfClass("Pants")

			local function applyBundleClothesNuke()
				-- V4.3.59: deduped from two identical override-block bodies. Returns true if caller should early-exit.
				if TShirt then
					if DataDetail.OldestClothings.ShirtGraphic == nil and not TShirt:GetAttribute("_RC_AppliedClothing") then  -- naked-base reset fix: don't snapshot our own applied garment as the original
						DataDetail.OldestClothings.ShirtGraphic = TShirt:Clone()
					end
					TShirt:Destroy()
					TShirt = nil
				end
				if Shirt then
					if DataDetail.OldestClothings.Shirt == nil and not Shirt:GetAttribute("_RC_AppliedClothing") then  -- naked-base reset fix
						DataDetail.OldestClothings.Shirt = Shirt:Clone()
					end
					Shirt:Destroy()
					Shirt = nil
				end
				if Pants then
					if DataDetail.OldestClothings.Pants == nil and not Pants:GetAttribute("_RC_AppliedClothing") then  -- naked-base reset fix
						DataDetail.OldestClothings.Pants = Pants:Clone()
					end
					Pants:Destroy()
					Pants = nil
				end
				if DataDetail.CurrentBundle ~= "Bald" then
					Function.AccessoryLoaderFunction(Character, CharacterAttachment, DataDetail.CurrentBundle, Data, RequestID, _MethodAtExec)  -- V4.3.448
					-- V4.3.420: was inline `if RequestID and RequestID ~= DataDetail.LastRequestID then return true end` -
					-- the V4.3.152 H1 / landmine #30 pattern (RID-stale exit missing Cooldown clear).
					-- AccessoryLoaderFunction yields on HTTP / asset loads; a competing bundle click bumps
					-- LastRequestID; this raw inline returned true WITHOUT releasing Cooldown, so the
					-- caller exited CharacterExecute with Cooldown still set → next click waited up to
					-- 5s for the safety net. Replaced with `_bailIfStale()` which releases Cooldown via
					-- the captured-RID guard (V4.3.349 pattern). Caught by bug-hunter 2026-05-14 (HIGH).
					if _bailIfStale() then return true end
					Function.BodyColorsFunction(Character, DataDetail.CurrentBundle, Data)
				end
				return false
			end

			if DataDetail.CurrentBundle ~= "nil" and Bundle[DataDetail.CurrentBundle] and (not Bundle[DataDetail.CurrentBundle]["Override"] or Bundle[DataDetail.CurrentBundle]["Override"] == false) then
				if applyBundleClothesNuke() then return end
			end

			Function.CatalogLoader(Character, CharacterAttachment, Data, OldCharacter, RequestID, _MethodAtExec)  -- V4.3.448
			if PlayerData[Data] ~= DataDetail then DataDetail["Cooldown"] = false return end
			if _bailIfStale() then return end
			local _bundleHasBodyColor = DataDetail.CurrentBundle and DataDetail.CurrentBundle ~= "nil"
				and Bundle[DataDetail.CurrentBundle] and Bundle[DataDetail.CurrentBundle]["Body Color"] ~= nil
				and DataDetail.BundleBodyColor
			-- V4.3.445: also gate against catalog-supplied skin. CatalogLoader's
			-- HumanoidDescriptionLoader writes `_catalogAppliedBodyColor = true` when
			-- the catalog HD actually contributed body colors. Pre-fix, if the user
			-- had a saved SkinTone, this BodyColorForceSet ran AFTER CatalogLoader
			-- finished and overwrote the catalog skin with the user's saved tone -
			-- "becomes my primary skin color" symptom. The flag is read-then-cleared
			-- so a subsequent equip of a non-catalog bundle re-applies SkinTone
			-- correctly.
			local _catalogAppliedBC = DataDetail._catalogAppliedBodyColor == true
			DataDetail._catalogAppliedBodyColor = nil
			if DataDetail.SkinTone ~= nil and not _bundleHasBodyColor and not _catalogAppliedBC then
				-- V4.3.446: snapshot the pristine character colors BEFORE the SkinTone
				-- forced-write. Pre-fix this path mutated per-part .Color directly with
				-- no snapshot anywhere; clearing SkinTone left the original colors
				-- unrecoverable (CharacterReset's L11031 restore is gated on the
				-- snapshot existing). User-visible: pick orange in the color picker,
				-- clear it → skin stayed orange. Same gap class as V4.3.438 / V4.3.445.
				Function.SnapshotOriginalBodyColors(DataDetail, Character)
				Function.BodyColorForceSet(Character, DataDetail.SkinTone)
				if OldCharacter and OldCharacter ~= Character then
					Function.BodyColorForceSet(OldCharacter, DataDetail.SkinTone)
				end
			end

			if DataDetail.CurrentBundle ~= "nil" and Bundle[DataDetail.CurrentBundle] and Bundle[DataDetail.CurrentBundle]["Override"] == true then
				if applyBundleClothesNuke() then return end
			end

			TShirt = Character:FindFirstChildOfClass("ShirtGraphic")
			Shirt = Character:FindFirstChildOfClass("Shirt")
			Pants = Character:FindFirstChildOfClass("Pants")

			local Extra = {["TShirt"] = TShirt, ["Shirt"] = Shirt, ["Pants"] = Pants, ["Tone"] = DataDetail.Tone, ["SkinTone"] = DataDetail.SkinTone, ["NippleColor"] = DataDetail.NippleColor}

			if DataDetail.HPClothes.Shirt ~= "" or DataDetail.HPClothes.Pants ~= "" then
				local HumanoidDescription = Instance.new("HumanoidDescription")
				for Type, Id in pairs(DataDetail.HPClothes) do
					if Id ~= "" and (type(Id) == "string" or type(Id) == "number") then
						if Type == "Shirt" then
							HumanoidDescription.Shirt = Id
						elseif Type == "Pants" then
							HumanoidDescription.Pants = Id
						elseif Type == "ShirtGraphic" then
							HumanoidDescription.GraphicTShirt = Id
						end
					end
				end
				local AccessoryLoaderModel = Instance.new("Model", workspace)
				AccessoryLoaderModel:AddTag(System.RCTag)
				AccessoryLoaderModel.Archivable = not hidden
				
				-- Error Fix: ApplyDescription requires a "Head" part in the model
				local headLoader = Instance.new("Part", AccessoryLoaderModel)
				headLoader.Name = "Head"
				headLoader.Transparency = 1
				headLoader.CanCollide = false
				
				local HumanoidAccessoryLoader = Instance.new("Humanoid", AccessoryLoaderModel)
				-- V4.3.504: mirror V4.3.443 bundle-path guard - content-deleted Shirt/Pants
				-- IDs in CatalogUsername imports can make ApplyDescription throw, which
				-- otherwise propagates out of the worker and leaks AccessoryLoaderModel
				-- + HumanoidDescription.
				local _applyOkCU, _applyErrCU = pcall(function() HumanoidAccessoryLoader:ApplyDescription(HumanoidDescription) end)
				if not _applyOkCU then
					warn("[RoClothes] CatalogUsername ApplyDescription threw - likely content-deleted clothing ID: " .. tostring(_applyErrCU))
					pcall(function() AccessoryLoaderModel:Destroy() end)
					pcall(function() HumanoidDescription:Destroy() end)
					return
				end
				if Function.IsStaleOrGone(Data, RequestID) then  -- V4.3.452
					AccessoryLoaderModel:Destroy() HumanoidDescription:Destroy()
					return
				end

				-- V4.3.168.2: hoisted out of the for-loop below - was allocating a fresh
				-- closure per iteration for no reason (Gemini audit finding #5).
				local function convertId(id)
					local success, decalObject = pcall(function()
						local decalObject = game:GetObjects("rbxassetid://"..id)[1]
						return decalObject
					end)
					if success and decalObject and decalObject:IsA("Decal") then
						return decalObject.Texture
					elseif string.gsub(tostring(id), "%D", "") == tostring(id) then  -- V4.5.24 Fix: id can be a NUMBER (numeric asset id) when game:GetObjects fails - string.gsub on a number throws "string expected". tostring() first (keeps the V4.3.504 semantics).
						return "rbxassetid://".. id
					else
						return id
					end
				end
				for _, v in pairs(AccessoryLoaderModel:GetChildren()) do
					if v:IsA("Shirt") or v:IsA("Pants") or v:IsA("ShirtGraphic") then
						if v:IsA("Shirt") and string.gsub(v.ShirtTemplate,"%D","") == "855777285" and HumanoidDescription.Shirt then
							v.ShirtTemplate = convertId(HumanoidDescription.Shirt)
						elseif v:IsA("Pants") and string.gsub(v.PantsTemplate,"%D","") == "867826313" and HumanoidDescription.Pants then
							v.PantsTemplate = convertId(HumanoidDescription.Pants)
						end
						local _hpClone = v:Clone()  -- V4.3.567 H-3: clone before AccessoryLoaderModel:Destroy() below kills `v`; consumers read .ShirtTemplate/.PantsTemplate off the destroyed Instance otherwise.
						_hpClone.Parent = nil
						DataDetail.HPClothes[v.ClassName] = _hpClone
					end
				end
				AccessoryLoaderModel:Destroy()
				HumanoidDescription:Destroy()
			end

			local PartListData = DataDetail.PartList

			-- V4.2.7 (Breast Physics Restoration): Lerp-original per-BreastsType axis map + rotation.
			-- Default covers BreastsType 1/3/4; Types 2 and 5 override below in their respective branches.
			-- Note: these locals were deleted during an earlier Krul refactor, which made the inline
			-- RIGHTBREAST/LEFTBREAST SpringCreate calls reference a dangling "Rotation" global (nil,
			-- silently caught by pcall in the physics render loop). Restoring them fixes both the
			-- axis-swap symptom AND the hidden nil-crash.
			local PhysicsRotationOffset = {
				X = "Z",
				Y = "X",
				Z = "Y",
			}
			local Rotation = {
				X = 5,
				Y = -5,
				Z = 5
			}

			local TORSO
			local LEFTLEG
			local RIGHTLEG
			local LEFTARM
			local RIGHTARM
			local LEFTBUTT
			local RIGHTBUTT

			local LEFTBREAST
			local RIGHTBREAST

			-- V4.3.314: hide the live character's underlying Roblox limbs when an SB (see Changelog for full rationale)
			local _hideLiveLimbs = function(_names)
				if _MethodAtExec == 2 then return end  -- V4.3.446: captured method
				if not Character then return end
				local _origMap = DataDetail.CurrentPartList and DataDetail.CurrentPartList.OriginalTransparency
				if not _origMap then return end
				for _, _n in ipairs(_names) do
					local _bp = Character:FindFirstChild(_n)
					if _bp and _bp:IsA("BasePart") then
						if _origMap[_bp] == nil then
							_origMap[_bp] = _bp.Transparency
						end
						pcall(function() _bp.LocalTransparencyModifier = 1 end)
					end
				end
			end

			-- V4.3.345: helper to overlay a Roblox shirt/pants template on an SB body (see Changelog for full rationale)
			local function _paintSBOverlay(_part, _template, _marker)
				if not (_part and _template and _template ~= "") then return end
				local _sa = _part:FindFirstChildOfClass("SurfaceAppearance")
				-- V4.3.355: respect non-RoClothes SurfaceAppearance ownership. (see Changelog for full rationale)
				if _sa then
					local _isOurs = false
					pcall(function()
						_isOurs = _sa:GetAttribute("RoClothesShirt") or _sa:GetAttribute("RoClothesPants")
							or _sa:GetAttribute("RoClothesTShirt") or _sa:GetAttribute("KrulHosted")
							or _sa:GetAttribute(_marker)
					end)
					if not _isOurs then return end  -- foreign SA, hands off
				end
				-- V4.5.24: use the shared capability probe. A rejected protected
				-- ColorMap write must remove its blank masking SA before TextureID fallback.
				local _mode = _setOrCreateSA(_part, _template, Enum.AlphaMode.Overlay, _marker)
				_part.Transparency = (_mode == "tex") and 0.011 or 0
			end
			local _shirtTpl = (Extra.Shirt and Extra.Shirt.ShirtTemplate)
				or (Extra.Pants and Extra.Pants.PantsTemplate)  -- some SB clothes route via Pants slot
			local _pantsTpl = Extra.Pants and Extra.Pants.PantsTemplate
			local _hasShirtToggle = DataDetail.CurrentClothes
				and (table.find(DataDetail.CurrentClothes, "Roblox Shirt") ~= nil)
			local _hasPantsToggle = DataDetail.CurrentClothes
				and (table.find(DataDetail.CurrentClothes, "Roblox Pants") ~= nil)

			-- V4.3.217: SB types (TorsoType 9, ArmType 5, LegsType 8) load via
			-- RigVnsModel - clones model.rbxm directly into character.
			if DataDetail.TorsoType == 1 then
				TORSO = Function.Weld(PartListData["Torso"], Character, Extra, Data, RequestID)
			elseif DataDetail.TorsoType == 9 then
				local _, parts = Function.RigVnsModel("RClothesContent/_vns/model/torso/1/model.rbxm", Character, RequestID, nil, Data)
				if _bailIfStale() then return end  -- V4.3.349
