			-- V4.3.341: REVERTED V4.3.340 - TorsoShirtTexture replaces the SB body's (see Changelog for full rationale)

			if DataDetail.ArmType == 1 then
				LEFTARM = Function.Weld(PartListData["Left Arm"], Character, Extra, Data, RequestID)
				RIGHTARM = Function.Weld(PartListData["Right Arm"], Character, Extra, Data, RequestID)
			elseif DataDetail.ArmType == 5 then
				local _, parts = Function.RigVnsModel("RClothesContent/_vns/model/arm/1/model.rbxm", Character, RequestID, nil, Data)
				if _bailIfStale() then return end  -- V4.3.349
