				})
			else
				LEFTARM = Function.Weld(PartListData["Left Arm".. DataDetail.ArmType], Character, Extra, Data, RequestID)
				RIGHTARM = Function.Weld(PartListData["Right Arm".. DataDetail.ArmType], Character, Extra, Data, RequestID)
			end
			if LEFTARM then DataDetail.CurrentPartList["Organ"]["Left Arm"] = LEFTARM end
			if RIGHTARM then DataDetail.CurrentPartList["Organ"]["Right Arm"] = RIGHTARM end
			if DataDetail.ArmType == 5 and _hasShirtToggle and _shirtTpl then
				if LEFTARM  then _paintSBOverlay(LEFTARM,  _shirtTpl, "RoClothesShirt") end
				if RIGHTARM then _paintSBOverlay(RIGHTARM, _shirtTpl, "RoClothesShirt") end
			end
			-- V4.3.341: REVERTED V4.3.340 SB Arm shirt-paint (see Torso revert comment above).

			if DataDetail.LegsType == 1 then
				LEFTLEG = Function.Weld(PartListData["Left Leg"], Character, Extra, Data, RequestID)
				RIGHTLEG = Function.Weld(PartListData["Right Leg"], Character, Extra, Data, RequestID)
			elseif DataDetail.LegsType == 8 then
				local _, parts = Function.RigVnsModel("RClothesContent/_vns/model/leg/1/model.rbxm", Character, RequestID, nil, Data)
				if _bailIfStale() then return end  -- V4.3.349
				LEFTLEG  = parts["Left Leg"]
				RIGHTLEG = parts["Right Leg"]
				if not LEFTLEG then
					warn("[RoClothes] LegsType 8: RigVnsModel returned no parts - falling back to Function.Weld.")
					LEFTLEG  = Function.Weld(PartListData["Left Leg8"],  Character, Extra, Data, RequestID)
					RIGHTLEG = Function.Weld(PartListData["Right Leg8"], Character, Extra, Data, RequestID)
				end
				_hideLiveLimbs({  -- V4.3.314
					"Left Leg", "Right Leg",
					"LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
					"RightUpperLeg", "RightLowerLeg", "RightFoot",
				})
			else
				LEFTLEG = Function.Weld(PartListData["Left Leg".. DataDetail.LegsType], Character, Extra, Data, RequestID)
				RIGHTLEG = Function.Weld(PartListData["Right Leg".. DataDetail.LegsType], Character, Extra, Data, RequestID)
			end
			if LEFTLEG then DataDetail.CurrentPartList["Organ"]["Left Leg"] = LEFTLEG end
			if RIGHTLEG then DataDetail.CurrentPartList["Organ"]["Right Leg"] = RIGHTLEG end
			if DataDetail.LegsType == 8 and _hasPantsToggle and _pantsTpl then
				if LEFTLEG  then _paintSBOverlay(LEFTLEG,  _pantsTpl, "RoClothesPants") end
				if RIGHTLEG then _paintSBOverlay(RIGHTLEG, _pantsTpl, "RoClothesPants") end
			end
			-- V4.3.341: REVERTED V4.3.340 SB Leg pants-paint (see Torso revert comment above).

			if DataDetail.ButtType == 1 then
				LEFTBUTT = Function.Weld(PartListData["Left Butt"], Character, Extra, Data, RequestID)
				RIGHTBUTT = Function.Weld(PartListData["Right Butt"], Character, Extra, Data, RequestID)
			elseif DataDetail.ButtType >= 2 and DataDetail.ButtType <= 3 then
				-- Types 2-3 exist in PartList; types 4/5 do not → fall back to type 1
				LEFTBUTT  = Function.Weld(PartListData["Left Butt"  .. DataDetail.ButtType], Character, Extra, Data, RequestID)
				RIGHTBUTT = Function.Weld(PartListData["Right Butt" .. DataDetail.ButtType], Character, Extra, Data, RequestID)
			elseif DataDetail.ButtType == 6 then  -- SmartBone type
				-- V4.3.217: load full butt/1/model.rbxm (sim Part with Bones + welded MeshParts).
				local _, parts = Function.RigVnsModel("RClothesContent/_vns/model/butt/1/model.rbxm", Character, RequestID, nil, Data)
				if _bailIfStale() then return end  -- V4.3.349
				LEFTBUTT  = parts["Left Butt"]
				RIGHTBUTT = parts["Right Butt"]
				if not LEFTBUTT then
					warn("[RoClothes] ButtType 6: RigVnsModel returned no parts - falling back to Function.Weld(SB1).")
					LEFTBUTT  = Function.Weld(PartListData["Left Butt SB1"],  Character, Extra, Data, RequestID)
					RIGHTBUTT = Function.Weld(PartListData["Right Butt SB1"], Character, Extra, Data, RequestID)
				end
			else
				-- Undefined type (4/5) - fall back to type 1
				LEFTBUTT  = Function.Weld(PartListData["Left Butt"],  Character, Extra, Data, RequestID)
				RIGHTBUTT = Function.Weld(PartListData["Right Butt"], Character, Extra, Data, RequestID)
			end
			if LEFTBUTT then DataDetail.CurrentPartList["Organ"]["Left Butt"] = LEFTBUTT end
			if RIGHTBUTT then DataDetail.CurrentPartList["Organ"]["Right Butt"] = RIGHTBUTT end
			if DataDetail.ButtType == 6 and _hasPantsToggle and _pantsTpl then
				if LEFTBUTT  then _paintSBOverlay(LEFTBUTT,  _pantsTpl, "RoClothesPants") end
				if RIGHTBUTT then _paintSBOverlay(RIGHTBUTT, _pantsTpl, "RoClothesPants") end
			end
			-- V4.3.341: REVERTED V4.3.340 SB Butt pants-paint (see Torso revert comment above).

			if DataDetail.BreastsType == 1 then
				LEFTBREAST = Function.Weld(PartListData["Left Breast"], Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast"], Character, Extra, Data, RequestID)
				if LEFTBREAST then DataDetail.CurrentPartList["Organ"]["Left Breast"] = LEFTBREAST end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end

				local LEFTNIPPLE = Function.Weld(PartListData["Left Nipple"], Character, Extra, Data, RequestID)
				local RIGHTNIPPLE = Function.Weld(PartListData["Right Nipple"], Character, Extra, Data, RequestID)
				if LEFTNIPPLE then DataDetail.CurrentPartList["Organ"]["Left Nipple"] = LEFTNIPPLE end
				if RIGHTNIPPLE then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RIGHTNIPPLE end
			elseif DataDetail.BreastsType == 2 then
				LEFTBREAST = Function.Weld(PartListData["Left Breast Type 2"], Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast Type 2"], Character, Extra, Data, RequestID)
				if LEFTBREAST then DataDetail.CurrentPartList["Organ"]["Left Breast"] = LEFTBREAST end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end

				-- V4.2.7: Lerp-original BreastsType 2 axis override
				PhysicsRotationOffset = {
					X = "Y",
					Y = "X",
					Z = "Z",
				}

			elseif DataDetail.BreastsType == 3 then
				LEFTBREAST = Function.Weld(PartListData["Left Breast Type 3"], Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast Type 3"], Character, Extra, Data, RequestID)
				if LEFTBREAST then DataDetail.CurrentPartList["Organ"]["Left Breast"] = LEFTBREAST end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end

				local LEFTNIPPLE = Function.Weld(PartListData["Left Nipple Type 3"], Character, Extra, Data, RequestID)
				local RIGHTNIPPLE = Function.Weld(PartListData["Right Nipple Type 3"], Character, Extra, Data, RequestID)
				if LEFTNIPPLE then DataDetail.CurrentPartList["Organ"]["Left Nipple"] = LEFTNIPPLE end
				if RIGHTNIPPLE then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RIGHTNIPPLE end

				-- V4.3.531 hotfix #7: Rotation.Y flipped from default -5 to +5 for Type 3 ONLY.
				-- Axis-math derivation from Lerp's PhysicsRotationOffset = {X="Z", Y="X", Z="Y"}:
				-- the vertical-jump V.Y impulse flows into rotZ via `Rotation.Y * V.Y`. On jump up,
				-- V.Y is negative, so default Rotation.Y=-5 gives positive rotZ. Type 1's mesh
				-- orientation makes that produce visible DOWN motion (correct gravity). Type 3's
				-- mesh asset (5270415437.mesh / 5270413797.mesh with scale 0.541) is rotated
				-- relative to Type 1's, so the same +rotZ produces visible UP motion (reversed).
				-- Flipping Rotation.Y to +5 inverts the rotZ direction without affecting the X/Z
				-- contributions that drive yaw/roll. Lerp precedent at L15495-L15499: Type 5 also
				-- has a Y-flip override (`Rotation = {X=5, Y=5, Z=5}` plus axis-map change) for the
				-- exact same mesh-orientation reason. V4.3.363's original "invert X" attempt
				-- (since reverted in hotfix #6) was flipping the wrong axis - X drives yaw, not
				-- the up-down jump direction. This matches the Y-flip that V4.3.530 attempted but
				-- got reverted along with the other failed attempts during cleanup.
				Rotation = {X=5, Y=5, Z=5}
			elseif DataDetail.BreastsType == 4 then
				LEFTBREAST = Function.Weld(PartListData["Left Breast Type 4"], Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast Type 4"], Character, Extra, Data, RequestID)
				if LEFTBREAST then DataDetail.CurrentPartList["Organ"]["Left Breast"] = LEFTBREAST end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end

				local LEFTAREOLA = Function.Weld(PartListData["Left Areola Type 4"], Character, Extra, Data, RequestID)
				local RIGHTAREOLA = Function.Weld(PartListData["Right Areola Type 4"], Character, Extra, Data, RequestID)
				local LEFTNIPPLE = Function.Weld(PartListData["Left Nipple Type 4"], Character, Extra, Data, RequestID)
				local RIGHTNIPPLE = Function.Weld(PartListData["Right Nipple Type 4"], Character, Extra, Data, RequestID)
				if LEFTAREOLA and LEFTNIPPLE then DataDetail.CurrentPartList.Link[LEFTAREOLA] = {T=LEFTNIPPLE} end
				if RIGHTAREOLA and RIGHTNIPPLE then DataDetail.CurrentPartList.Link[RIGHTAREOLA] = {T=RIGHTNIPPLE} end
				if LEFTAREOLA then DataDetail.CurrentPartList["Organ"]["Left Areola"] = LEFTAREOLA end
				if RIGHTAREOLA then DataDetail.CurrentPartList["Organ"]["Right Areola"] = RIGHTAREOLA end
				if LEFTNIPPLE then DataDetail.CurrentPartList["Organ"]["Left Nipple"] = LEFTNIPPLE end
				if RIGHTNIPPLE then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RIGHTNIPPLE end
			elseif DataDetail.BreastsType == 5 then
				LEFTBREAST = Function.Weld(PartListData["Left Breast Type 5"], Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast Type 5"], Character, Extra, Data, RequestID)
				if LEFTBREAST then DataDetail.CurrentPartList["Organ"]["Left Breast"] = LEFTBREAST end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end

				local LEFTNIPPLE = Function.Weld(PartListData["Left Nipple Type 5"], Character, Extra, Data, RequestID)
				local RIGHTNIPPLE = Function.Weld(PartListData["Right Nipple Type 5"], Character, Extra, Data, RequestID)
				if LEFTNIPPLE then DataDetail.CurrentPartList["Organ"]["Left Nipple"] = LEFTNIPPLE end
				if RIGHTNIPPLE then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RIGHTNIPPLE end

				-- V4.2.7: Lerp-original BreastsType 5 overrides (different axis map + positive Y rotation)
				PhysicsRotationOffset = {X="Y", Y="X", Z="Z"}
				Rotation = {X=5, Y=5, Z=5}

			elseif DataDetail.BreastsType == 6 then  -- SmartBone type
				-- V4.3.217: load full breast/1/model.rbxm (sim Part with Bones + 4 welded MeshParts).
				-- V4.3.464: pcall-wrap. Any throw inside RigVnsModel (deep iteration over rbxm
				-- descendants, Motor6D resolution, MeshPart replacement, SmartBone tagging) would
				-- previously kill the entire BreastsType=6 dispatch - user sees zero breast.
				-- Community report 2026-05-17 (reporter unreachable, no console output available)
				-- pointed here as one of the few silent-failure paths that could produce
				-- "type 6 breast doesnt load" across a Redownload + step-by-step retry.
				local _rvOk, _rvA, _rvB = pcall(Function.RigVnsModel, "RClothesContent/_vns/model/breast/1/model.rbxm", Character, RequestID, nil, Data)
				if not _rvOk then
					warn("[RoClothes] BreastsType 6: RigVnsModel threw - " .. tostring(_rvA))
				end
				local parts = (_rvOk and _rvB) or {}
				if _bailIfStale() then return end  -- V4.3.349
				LEFTBREAST  = parts["Left Breast"]
				RIGHTBREAST = parts["Right Breast"]
				local _sb1Nipples = {}  -- V4.3.464: tracked so the visibility-reset loop can include them
				if not LEFTBREAST then
					warn("[RoClothes] BreastsType 6: RigVnsModel returned no parts - falling back to Function.Weld(SB1).")
					LEFTBREAST  = Function.Weld(PartListData["Left Breast SB1"],  Character, Extra, Data, RequestID)
					RIGHTBREAST = Function.Weld(PartListData["Right Breast SB1"], Character, Extra, Data, RequestID)
					local LN = Function.Weld(PartListData["Left Nipple SB1"],  Character, Extra, Data, RequestID)
					local RN = Function.Weld(PartListData["Right Nipple SB1"], Character, Extra, Data, RequestID)
					if LN then DataDetail.CurrentPartList["Organ"]["Left Nipple"]  = LN; _sb1Nipples[#_sb1Nipples+1] = LN end
					if RN then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RN; _sb1Nipples[#_sb1Nipples+1] = RN end
				else
					if parts["Left Nipple"]  then DataDetail.CurrentPartList["Organ"]["Left Nipple"]  = parts["Left Nipple"]  end
					if parts["Right Nipple"] then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = parts["Right Nipple"] end
				end
				if LEFTBREAST  then DataDetail.CurrentPartList["Organ"]["Left Breast"]  = LEFTBREAST  end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end
				-- FP FIX: RigVnsModel (Type-6) parts are parented straight to the character and NEVER registered in
				-- RealtimeUpdateList, so the per-frame first-person exemption/fade block (~L25764) never runs for them ->
				-- the engine's default first-person fade (LocalTransparencyModifier=1) sticks and the breasts/nipples
				-- vanish in FP, toggle or not. Register a BASE-ONLY entry: geometry writes are gated on CFRAME/SIZE/Weld
				-- (~L25676) so SmartBone deform is untouched; only the show-in-FP LTM block applies. FPOnly skips the
				-- RealtimeBodyTransparency mirror so it can't clobber a bra's Transparency=1.
				local _rvFPBase = Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso")
				if _rvFPBase and DataDetail.CurrentPartList.RealtimeUpdateList and DataDetail.CurrentPartList.RealtimeUpdateList.Mesh then
					for _, _rvNm in ipairs({ "Left Breast", "Right Breast", "Left Nipple", "Right Nipple" }) do
						local _rvbp = parts[_rvNm]
						if _rvbp and _rvbp:IsA("BasePart") then DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[_rvbp] = { Base = _rvFPBase, FPOnly = true } end
					end
				end
				-- V4.3.464: if BOTH paths failed, surface a loud error so future reports include
				-- enough console context to pinpoint the failure mode. Pre-fix the SB1 fallback's
				-- silent-nil return left the user with no breast and no diagnostic.
				if not LEFTBREAST and not RIGHTBREAST then
					warn("[RoClothes] BreastsType 6: BOTH RigVnsModel AND Function.Weld(SB1) failed - breast will be missing. Check that RClothesContent/_vns/model/breast/1/ exists on disk and that the executor's getcustomasset / game:GetObjects work. As a workaround, switch to BreastsType 1-5.")
				end
				-- V4.3.338: REVERTED V4.3.337 Decal-overlay approach - the (see Changelog for full rationale)
				PhysicsRotationOffset = {X="Y", Y="X", Z="Z"}
				-- V4.3.242: default breast/nipple visibility ON each execute. The bra
				-- dispatch in the Clothes loop will hide them again if SB1/SB2 is in
				-- CurrentClothes; this re-show ensures unequipping the bra restores them.
				-- V4.3.464: ALSO reset the SB1-fallback parts here. Pre-fix the loop only
				-- iterated `parts` from RigVnsModel - when the fallback fired, the freshly-
				-- welded SB1 parts were never visibility-reset. If a prior bra-equip wrote
				-- Transparency=1 onto them via the direct L12674-12680 path and the bra was
				-- later removed, the next CharacterExecute would keep those parts at
				-- Transparency=1 → "breast doesnt load". Now LEFTBREAST/RIGHTBREAST/SB1
				-- nipples are reset alongside the RigVnsModel parts.
				for _, _show in ipairs({"Left Breast","Right Breast","Left Nipple","Right Nipple"}) do
					local _bp = parts and parts[_show]
					if _bp and _bp:IsA("BasePart") then _bp.Transparency = 0 end
				end
				for _, _p in ipairs({LEFTBREAST, RIGHTBREAST, table.unpack(_sb1Nipples)}) do
					if _p and _p:IsA("BasePart") then _p.Transparency = 0 end
				end
				-- V4.3.253: scrub any leftover BreastClothes meshes from RC_VNS_breast. (see Changelog for full rationale)
				local _rcBreastClean = Character:FindFirstChild("RC_VNS_breast")
				if _rcBreastClean then
					for _, _c in ipairs(_rcBreastClean:GetChildren()) do
						if _c.Name == "BreastClothes" then _c:Destroy() end
					end
				end
			elseif DataDetail.BreastsType == 7 then
				-- V4.3.414: Type 7 (Phys UV V2) DEPRECATED. The full custom dispatch
				-- block (V4.3.378-413) was ~540 lines that resolved to a wired-but-
				-- non-deformable mesh (skin weights bound only to the static Bone,
				-- not the swinging Bone.001 - proven definitively by the V4.3.409
				-- ±45° oscillation test producing zero visible deformation). The
				-- mesh asset (rbxassetid://100345615750774) cannot be re-skinned
				-- from Lua so SmartBone physics on Phys UV V2 was architecturally
				-- impossible. MaxBreastsType lowered to 6 at file scope (L156) so
				-- the cycle UI no longer reaches 7. This branch is unreachable from
				-- the normal cycle but kept as a safe fallback: if a saved bundle
				-- restores BreastsType=7, fall through to SB1 weld so the body
				-- renders with familiar breast physics instead of breaking.
				warn("[RoClothes] BreastsType 7 deprecated as of V4.3.414 - falling back to SB1 weld.")
				LEFTBREAST  = Function.Weld(PartListData["Left Breast SB1"],  Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast SB1"], Character, Extra, Data, RequestID)
				local LN = Function.Weld(PartListData["Left Nipple SB1"],  Character, Extra, Data, RequestID)
				local RN = Function.Weld(PartListData["Right Nipple SB1"], Character, Extra, Data, RequestID)
				-- V4.3.418: stale-RID guard after the 4 Function.Weld calls. Each Weld (see Changelog for full rationale)
				if _bailIfStale() then return end
				if LN then DataDetail.CurrentPartList["Organ"]["Left Nipple"]  = LN end
				if RN then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RN end
				if LEFTBREAST  then DataDetail.CurrentPartList["Organ"]["Left Breast"]  = LEFTBREAST  end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end
				PhysicsRotationOffset = {X="Y", Y="X", Z="Z"}
			end

			if DataDetail.BodyPartPhysics then
				local Torso = Character:FindFirstChild("Torso")

				if Torso then
					-- V4.3.232: gate SpringCreate by body type. SmartBone (BreastsType=6, (see Changelog for full rationale)
					if DataDetail.ButtType ~= 6 then
						if RIGHTBUTT then Function.SpringCreate(
							RIGHTBUTT,
							Torso,
							Vector3.new(0,0,0),
							Vector3.new(0,0,0),
							SpringConfigs.Buttocks.Speed,
							SpringConfigs.Buttocks.Damper,
							{X="X", Y="Y", Z="Z"},
							PhysicsPosition.Buttocks,
							{X="Y", Y="X", Z="Z"},
							PhysicsRotation.Buttocks,
							Data
						)
						end
						if LEFTBUTT then Function.SpringCreate(
							LEFTBUTT,
							Torso,
							Vector3.new(0,0,0),
							Vector3.new(0,0,0),
							SpringConfigs.Buttocks.Speed,
							SpringConfigs.Buttocks.Damper,
							{X="X", Y="Y", Z="Z"},
							PhysicsPosition.Buttocks,
							{X="Y", Y="X", Z="Z"},
							PhysicsRotation.Buttocks,
							Data
						) end
					end
					-- just so i remember, the default breastphyiscs speed&damper were 10, 0.20
					-- default rotation were 5, -5, 5
					-- V4.2.7: reverted to Lerp-original - PhysicsRotationOffset and Rotation are
					-- per-BreastsType locals defined earlier in this function.
					-- Lerp-original values restored: Position all zeros, original Rotation per type.
					-- V4.3.414: removed the V4.3.382 Type 7 exclusion. Type 7 dispatch
					-- now falls back to SB1 weld (which needs spring physics like
					-- BreastsType 1-5), so excluding Type 7 from SpringCreate would
					-- leave saved-bundle Type-7 bodies frozen. Only Type 6 (SmartBone)
					-- remains gated - SB drives Bone.CFrame deformation, the legacy
					-- spring physics fights it. Type 7 is no longer reachable from the
					-- cycle UI (MaxBreastsType=6) but kept fallback-compatible.
					if DataDetail.BreastsType ~= 6 then
						if RIGHTBREAST then Function.SpringCreate(
							RIGHTBREAST,
							Torso,
							Vector3.new(0,0,0),
							Vector3.new(0,0,0),
							SpringConfigs.Breasts.Speed,
							SpringConfigs.Breasts.Damper,
							{X="X", Y="Y", Z="Z"},
							{X=0, Y=0, Z=0},
							PhysicsRotationOffset,
							Rotation,
							Data
						) end
						if LEFTBREAST then Function.SpringCreate(
							LEFTBREAST,
							Torso,
							Vector3.new(0,0,0),
							Vector3.new(0,0,0),
							SpringConfigs.Breasts.Speed,
							SpringConfigs.Breasts.Damper,
							{X="X", Y="Y", Z="Z"},
							{X=0, Y=0, Z=0},
							PhysicsRotationOffset,
							Rotation,
							Data
						) end
					end
				end
			end

			if DataDetail.MeshBasePartInvisible then
				for _, part in ipairs({TORSO, LEFTLEG, RIGHTLEG, LEFTARM, RIGHTARM}) do
					if part then
						part.Transparency = 1
						DataDetail.CurrentPartList.ParentTransparency[part] = {D = 0, T = 1}
					end
				end
			end

			-- Sweep KrulHosted SurfaceAppearances from both Organ and Clothes MeshParts.
			pcall(function()
				local function sweepMeshPart(meshPart)
					for _, child in ipairs(meshPart:GetChildren()) do
						if (child:IsA("SurfaceAppearance") or child:IsA("SpecialMesh") or child:GetAttribute("RCClothingLayer")) and child:GetAttribute("KrulHosted") then
							child:Destroy()
						elseif child:IsA("MeshPart") then
							sweepMeshPart(child) -- recurse into child MeshParts (ButtType1 two-piece)
						end
					end
				end
				local function sweepTable(t)
					if not t then return end
					for _, meshPart in pairs(t) do
						if typeof(meshPart) == "Instance" and meshPart:IsA("MeshPart") then
							sweepMeshPart(meshPart)
						end
					end
				end
				sweepTable(DataDetail.CurrentPartList["Organ"])
				sweepTable(DataDetail.CurrentPartList["Clothes"])
			end)

			-- Build both supported bra meshes before any hosted shirt paints them.
			-- Preserve user selection order for the remaining clothing and texture precedence.
			local _clothingBuildOrder = {}
			for _, name in ipairs(DataDetail.CurrentClothes) do
				if name == "Breast Clothes SB1" or name == "Breast Clothes SB2" then table.insert(_clothingBuildOrder, name) end
			end
			for _, name in ipairs(DataDetail.CurrentClothes) do
				if name ~= "Breast Clothes SB1" and name ~= "Breast Clothes SB2" then table.insert(_clothingBuildOrder, name) end
			end
			for _, SelectClothes in ipairs(_clothingBuildOrder) do
				if _bailIfStale() then return end
				if SelectClothes ~= "nil" then

					-- V4.3.237: SmartBone clothing-layer dispatch. Breast Clothes SB1/SB2 (see Changelog for full rationale)
					if SelectClothes == "Breast Clothes SB1" or SelectClothes == "Breast Clothes SB2" then
						-- V4.3.250: bras only valid alongside SmartBone breast (Type 6).
						-- If user changed body type away from 6 with a bra still in CurrentClothes,
						-- skip silently (RC_VNS_breast doesn't exist; nothing to anchor to).
						if DataDetail.BreastsType ~= 6 then continue end
						local _bcPath = (SelectClothes == "Breast Clothes SB1")
							and "RClothesContent/_vns/model/breastclothes/1/model.rbxm"
							or  "RClothesContent/_vns/model/breastclothes/2/model.rbxm"
						local _root, _parts = Function.RigVnsModel(_bcPath, Character, RequestID, nil, Data)
						if _root then
							local _cmap = DataDetail.CurrentPartList["Clothes"]
							-- V4.3.248: re-parent the bra MeshPart into RC_VNS_breast so it sits (see Changelog for full rationale)
							-- V4.3.249: store the MeshPart directly in _cmap (not the cloneRoot
							-- V4.3.253: clean any prior BreastClothes meshes from RC_VNS_breast
							local _rcBreast = Character:FindFirstChild("RC_VNS_breast")
							if _rcBreast then
								for _, _c in ipairs(_rcBreast:GetChildren()) do
									if _c.Name == "BreastClothes" then _c:Destroy() end
								end
							end
							-- Drop stale _cmap references too (other bra's MeshPart was just destroyed).
							for _, _other in ipairs({"Breast Clothes SB1","Breast Clothes SB2"}) do
								if _other ~= SelectClothes then _cmap[_other] = nil end
							end
							local _braMP = _root:FindFirstChild("BreastClothes", true)
							if _braMP and _braMP:IsA("MeshPart") and _rcBreast then
								_braMP.Parent = _rcBreast
								_cmap[SelectClothes] = _braMP
							else
								_cmap[SelectClothes] = _root
							end
							-- V4.5.24: restore the intended 2D-shirt overlay on Bra 1/2. The old
							-- _paintSBOverlay path used AlphaMode.Overlay and made transparent cutouts
							-- solid; the shared helper preserves alpha and removes a failed masking SA
							-- before falling back to TextureID on restricted executors.
							if _braMP and _braMP:IsA("MeshPart") and _hasShirtToggle and Extra.Shirt and Extra.Shirt.ShirtTemplate then
								local _braPaintMode = _setOrCreateSA(_braMP, Extra.Shirt.ShirtTemplate, Enum.AlphaMode.Transparency, "RoClothesShirt")
								_braMP.Transparency = (_braPaintMode == "tex") and 0.011 or 0
							end
							-- V4.5.21 (owner call 2026-08-10): do NOT hide the breast under a bra. Pre-fix (V4.3.342) set
							-- Left/Right Breast + Nipple to Transparency=1 on every bra apply, so the breast mesh vanished
							-- under any bra (community report). The breast type already paints the Roblox clothing onto the
							-- breast itself, and the bra sits on top with its own texture, so both stay visible now.
							-- V4.3.249: skinning now drives bra deformation natively - removed the
							-- per-frame Heartbeat C0-update loop (was fighting skinning, producing
							-- wrinkle artifacts). Bra Motor6D's C0 is set once during RigVnsModel
							-- via geometric placement (V4.3.241) and stays put while bones deform
							-- the mesh from that anchor.
						end
						continue
					end

					local function weldClothes(w)
						-- V4.3.59: hoist ClothesPartMap and recolorEntry out of the per-part loop;
						-- collapse triple Primary/Secondary/Tertiary checks into a single dispatch on partMeta.Recolor.
						local ClothesPartMap = DataDetail.CurrentPartList["Clothes"]
						local recolorEntry = DataDetail.ClothesRecolor[SelectClothes]
						-- Two passes: some parts (e.g. sheathKnot) need a sibling part (mainKnot)
						-- as parent. If pairs() processes them out of order, pass 2 retries failures.
						for _pass = 1, 2 do
						for i, v in pairs(w) do
							if ClothesPartMap[v] then continue end  -- already created
							if _bailIfStale() then return end
							local partMeta = PartListData[v]
							if not partMeta then
								warn("[RoClothes] Missing PartList entry for clothing part:", v, "- skipping")
								continue
							end
							local ClothesPart = Function.Weld(partMeta, Character, Extra, Data, RequestID)
							if ClothesPart then
								ClothesPartMap[v] = ClothesPart
								if recolorEntry and partMeta.Recolor then
									local slot = partMeta.Recolor
									if slot == "Primary" then
										if typeof(recolorEntry.Primary) == "Color3" then
											ClothesPart.Color = recolorEntry.Primary
										end
									elseif slot == "Secondary" then
										if typeof(recolorEntry.Secondary) == "Color3" then
											ClothesPart.Color = recolorEntry.Secondary
										end
									elseif slot == "Tertiary" then
										if typeof(recolorEntry.Tertiary) == "Color3" then
											ClothesPart.Color = recolorEntry.Tertiary
										end
									end
								end
							else
								-- V4.3.146: Function.Weld returns nil on stale-request cancellation (see Changelog for full rationale)
								if _bailIfStale() then return end
								-- V4.3.345: warn silenced. The pass-2 retry already handles the
								-- common case (PartList ordering); when both passes fail it's
								-- typically the SB body / Method 2 anchor-resolution issue which
								-- floods F9 console without giving the user any actionable info.
								-- Function.Weld nil return is normal under rapid bundle swaps.
							end
						end
						end  -- end two-pass loop
					end

					if Clothes[SelectClothes] and Clothes[SelectClothes]["Weld"] then
						if Clothes[SelectClothes].Alternative and Clothes[SelectClothes].Alternative.Condition then
							local _condFn = Function[Clothes[SelectClothes].Alternative.Condition]
							local a = false
							if _condFn then local _ok, _r = pcall(_condFn, Data); if _ok then a = _r end end
							if a and a == true then
								weldClothes(Clothes[SelectClothes].Alternative["Weld"])
							else
								weldClothes(Clothes[SelectClothes]["Weld"])
							end
						else
							local metCondition = false
							if Clothes[SelectClothes].Alternative then
								for i, alts in ipairs(Clothes[SelectClothes].Alternative) do  -- V4.3.349: deterministic iteration
									if metCondition == false then
										local _altFn = alts.Condition and Function[alts.Condition]
										local a = false
										if _altFn then local _ok, _r = pcall(_altFn, Data); if _ok then a = _r end end
										if a and a == true then
											metCondition = true
											weldClothes(alts["Weld"])
										end
									end
								end
							end
							if metCondition == false then
								weldClothes(Clothes[SelectClothes]["Weld"])
							end
						end
					end

					if Clothes[SelectClothes] and Clothes[SelectClothes]["Unvisible"] ~= nil then
						for i, v in pairs(Clothes[SelectClothes]["Unvisible"]) do
							local UnvisiblePart = DataDetail.CurrentPartList["Organ"][v]

							if UnvisiblePart then
								UnvisiblePart.Transparency = 1
							elseif string.find(string.lower(v),"areola") then
								for areola, parent in pairs(DataDetail.CurrentPartList["AreolaDecal"]) do
									-- V4.3.302: wrapped disjunction - pre-fix `parent and (left) or (right)`
									-- parsed as `(parent AND left) OR right`, evaluating right-hand `parent.Name`
									-- without the parent guard.
									if parent and (
										(string.find(string.lower(v),"left")  and string.find(string.lower(parent.Name),"left"))
										or (string.find(string.lower(v),"right") and string.find(string.lower(parent.Name),"right"))
									) then
										-- V4.3.353: AreolaDecalUVCreate registers a SurfaceAppearance
										-- (no Transparency property); only write to Decal entries.
										if areola:IsA("Decal") then
											areola.Transparency = 1
										elseif areola:IsA("SurfaceAppearance") then
											-- Best-effort hide for SA (no Transparency) - destroy the SA.
											areola:Destroy()
											DataDetail.CurrentPartList["AreolaDecal"][areola] = nil
										end
									end
								end
							end
						end
					end

					-- V4.3.191: KrulHosted custom clothing (PNG hosted on krulhub.dev)
					-- Target CurrentPartList["Organ"] - these MeshParts are ALWAYS present after any
					-- bundle applies, regardless of what clothing items are toggled. This is the same
					-- set that Function.PantsTexture / Function.ShirtTexture use from BottomLayer/TopLayer.
					if Clothes[SelectClothes] and Clothes[SelectClothes].KrulHosted then
						local cDef = Clothes[SelectClothes]
						local okA, assetUrl = pcall(System.getcustomasset, cDef.LocalPath)
						if okA and type(assetUrl) == "string" and #assetUrl > 5 then
							local organs = DataDetail.CurrentPartList["Organ"]
						local resolvedType = _krulClothTypes[SelectClothes] or cDef.ClothType
						local function applyKrulTex(meshPart, preserveAlpha)
							if not meshPart or not meshPart:IsA("MeshPart") then return end
							if meshPart:GetAttribute("RCClothingLayer") then return end
							local existing = meshPart:FindFirstChildOfClass("SurfaceAppearance")
							if existing and existing:GetAttribute("KrulHosted") then existing:Destroy() end
							local sa = Instance.new("SurfaceAppearance")
							sa:SetAttribute("KrulHosted", true)
							local marker = resolvedType == "Shirt" and "RoClothesShirt" or "RoClothesPants"
							sa:SetAttribute(marker, true)
							-- V4.5.2: ColorMap is a protected asset property - it throws on a non-elevated
							-- thread (Studio / published place). Pre-fix the bare `sa.ColorMap = assetUrl`
							-- either errored the apply or (under an upstream pcall) left a blank SA, and the
							-- SpecialMesh fallback below only fired on a PARENT failure, never a ColorMap one.
							-- Now guard the ColorMap write + latch the capability: on ColorMap-failure paint
							-- the mesh's own TextureID; on SA-parent-failure (some executors block it) keep
							-- the original SpecialMesh path.
							local okCM = System._saCMW ~= false and pcall(function() sa.ColorMap = assetUrl end)
							System._saCMW = okCM and true or false
							if preserveAlpha and okCM then sa.AlphaMode = Enum.AlphaMode.Transparency end
							local ok2 = okCM and pcall(function() sa.Parent = meshPart end)
							if not ok2 then
								sa:Destroy()
								if not okCM then
									local mode = _setOrCreateSA(meshPart, assetUrl, preserveAlpha and Enum.AlphaMode.Transparency or Enum.AlphaMode.Overlay, marker)
									local painted = mode == "layer" and meshPart:FindFirstChild("RCClothingTextureLayer")
										or mode == "sa" and meshPart:FindFirstChildOfClass("SurfaceAppearance") or meshPart
									if painted then painted:SetAttribute("KrulHosted", true) end
								else
									local sm = meshPart:FindFirstChildOfClass("SpecialMesh")
									if not sm then sm = Instance.new("SpecialMesh", meshPart) end
									sm:SetAttribute("KrulHosted", true)
									sm:SetAttribute(marker, true)
									if sm:GetAttribute("_RC_ClothingBaseTexture") == nil then
										sm:SetAttribute("_RC_ClothingBaseTexture", sm.TextureId)
									end
									pcall(function() sm.TextureId = assetUrl end)
								end
							end
							if preserveAlpha then meshPart.Transparency = ok2 and 0 or 0.011 end
							-- Recurse into child MeshParts (handles ButtType1 two-piece sphere)
							for _, child in ipairs(meshPart:GetChildren()) do
								if child:IsA("MeshPart") then applyKrulTex(child, preserveAlpha) end
							end
						end

						-- Mirror TopLayer/BottomLayer part lists exactly - no overlap between shirt/pants.
						-- Shirt: Organ arms + Clothes torso/breast-shirt parts
						-- Pants: Organ torso/legs/butt/breast-pants parts (Torso is pants territory)
						if resolvedType == "Shirt" then
							for _, n in ipairs({"Left Arm","Right Arm"}) do
								applyKrulTex(organs and organs[n])
							end
							local clothesParts = DataDetail.CurrentPartList["Clothes"]
							if clothesParts then
								for _, n in ipairs({"Torso Shirt","Breasts Shirt","Breasts Shirt 2","Breasts Shirt 3"}) do
									local mp = clothesParts[n]
									if typeof(mp) == "Instance" then
										if mp:IsA("MeshPart") then
											applyKrulTex(mp)
										else
											for _, _d in ipairs(mp:GetDescendants()) do
												if _d:IsA("MeshPart") then applyKrulTex(_d) end
											end
										end
									end
								end
								-- V4.5.24: only the two VNS bra meshes support breast clothing overlays.
								-- Keep them separate so ordinary shirt targets retain their existing alpha mode.
								for _, n in ipairs({ "Breast Clothes SB1", "Breast Clothes SB2" }) do
									local mp = clothesParts[n]
									if typeof(mp) == "Instance" then
										if mp:IsA("MeshPart") then
											applyKrulTex(mp, true)
										else
											for _, _d in ipairs(mp:GetDescendants()) do
												if _d:IsA("MeshPart") then applyKrulTex(_d, true) end
											end
										end
									end
								end
							end
							-- Fallback: bundle has no "Torso Shirt" Clothes part → texture Torso Organ directly
							if not (clothesParts and clothesParts["Torso Shirt"]) then
								applyKrulTex(organs and organs["Torso"])
							end
						else
							for _, n in ipairs({"Torso","Left Leg","Right Leg","Left Butt","Right Butt","Breasts Pants","Breasts Pants 2","Breasts Pants 3"}) do
								applyKrulTex(organs and organs[n])
							end
							-- Breasts Pants can also live in Clothes (bundle-dependent) - check both tables
							local _bpClothes = DataDetail.CurrentPartList["Clothes"]
							if _bpClothes then
								for _, n in ipairs({"Breasts Pants","Breasts Pants 2","Breasts Pants 3"}) do
									local mp = _bpClothes[n]
									if typeof(mp) == "Instance" and mp:IsA("MeshPart") then applyKrulTex(mp) end
								end
							end
						end
						end
					end
				end
			end
			if _bailIfStale() then return end

			-- Second pass: retry clothing whose weld parts were nil after pass 1
			-- due to pairs() ordering (e.g. "Furry Knot" needs "Cock" which may be
			-- iterated later - by pass 2 all clothing parents are in the proxy).
			-- Mirror the same Alternative condition dispatch as the first pass so we
			-- retry the correct weld list (base OR alternative) rather than always base.
			do
				local ClothesPartMap = DataDetail.CurrentPartList["Clothes"]
				for _, SelectClothes in ipairs(DataDetail.CurrentClothes) do
					if _bailIfStale() then return end
					if SelectClothes == "nil" then continue end
					-- V4.3.252: SB bras must NEVER fall through to Function.Weld in pass 2.
					-- Their PartListData entries are placeholder Parts (size 1.24x1.38x1.89) that
					-- would render as floating cubes if welded directly. Pass 1's bra dispatch
					-- routes them through Function.RigVnsModel; if that didn't run (e.g. body
					-- type ≠ 6), the bra is simply skipped - no fallback weld.
					if SelectClothes == "Breast Clothes SB1" or SelectClothes == "Breast Clothes SB2" then continue end
					local cDef = Clothes[SelectClothes]
					if not cDef or not cDef["Weld"] then continue end
					-- Resolve which weld list was used in the first pass
					local weldList = cDef["Weld"]
					if cDef.Alternative then
						if cDef.Alternative.Condition then
							local _fn = Function[cDef.Alternative.Condition]
							local _r2 = false
							if _fn then local _ok, _rv = pcall(_fn, Data); if _ok then _r2 = _rv end end
							if _r2 == true then weldList = cDef.Alternative["Weld"] end
						else
							for _, alts in pairs(cDef.Alternative) do
								if alts.Condition then
									local _fn = Function[alts.Condition]
									local _r2 = false
									if _fn then local _ok, _rv = pcall(_fn, Data); if _ok then _r2 = _rv end end
									if _r2 == true then weldList = alts["Weld"]; break end
								end
							end
						end
					end
					if not weldList then continue end
					local hasMissing = false
					for _, v in pairs(weldList) do
						if not ClothesPartMap[v] and PartListData[v] then hasMissing = true; break end
					end
					if hasMissing then
						for _, v in pairs(weldList) do
							if ClothesPartMap[v] or not PartListData[v] then continue end
							if _bailIfStale() then return end
							local ClothesPart = Function.Weld(PartListData[v], Character, Extra, Data, RequestID)
							if ClothesPart then ClothesPartMap[v] = ClothesPart end
						end
					end
				end
			end

			local function transparent(o,v)
				if v >= 1 and o.Material == Enum.Material.Glass then
					o:AddTag("RCGlassMat")
					o.Material = Enum.Material.Neon
				elseif v < 1 and o.Material == Enum.Material.Neon and o:HasTag("RCGlassMat") then
					o:RemoveTag("RCGlassMat")
					o.Material = Enum.Material.Glass
				end
				o:SetAttribute("MaxTransparencyRC",v)
				o.Transparency = v
			end
			-- V4.3.59: deduped from two near-identical TopHP/BottomHP loop bodies.
			-- Caches Clothes[c], CurrentPartList["Clothes"], CurrentPartList["Organ"] per iteration
			-- (was up to 6+ table lookups per part previously).
			local function processHPClothes(hpType)
				local clothesPartMap = DataDetail.CurrentPartList["Clothes"]
				local organMap = DataDetail.CurrentPartList["Organ"]
				for c, set in pairs(DataDetail.ClothesHP) do
					if set["HP"] ~= hpType then continue end
					if not table.find(DataDetail.CurrentClothes,c) then continue end
					local clothesC = Clothes[c]
					if not clothesC then continue end
					local w = clothesC.Weld or {}  -- V4.3.567 M-11: default {} so pairs(w) below cannot crash on an entry with no Weld
					if clothesC.Alternative and clothesC.Alternative.Condition then
						local _hpCondFn = Function[clothesC.Alternative.Condition]
						local a = false
						if _hpCondFn then local _ok, _rv = pcall(_hpCondFn, Data); if _ok then a = _rv end end
						if a == true then
							w = clothesC.Alternative.Weld
						end
					elseif clothesC.Alternative then
						local metCondition = false
						for i, alts in ipairs(clothesC.Alternative) do  -- V4.3.349: deterministic iteration
							if metCondition == false then
								local _hpAltFn = alts.Condition and Function[alts.Condition]
								local a = false
								if _hpAltFn then local _ok, _r = pcall(_hpAltFn, Data); if _ok then a = _r end end
								if a == true then
									metCondition = true
									w = alts["Weld"]
								end
							end
						end
					end
					local inverse = (set["Inverse"] == true)
					local hpFlag = not inverse
					for i, v in pairs(w or {}) do  -- V4.3.567 M-11: also covers an Alternative.Weld that resolved to nil
						local cp = clothesPartMap[v]
						if cp then
							if inverse then
								transparent(cp, 1)
							else
								local t = cp:GetAttribute("Alpha") or 0
								transparent(cp, t)
							end
						end
					end
					if clothesC.Unvisible then
						for i, v in pairs(clothesC.Unvisible) do
							local op = organMap[v]
							if op then
								if inverse then
									local t = op:GetAttribute("Alpha") or 0
									transparent(op, t)
								else
									transparent(op, 1)
								end
							end
						end
					end
					if clothesC.HPFunction then
						local hpFn = clothesC.HPFunction
						if typeof(hpFn) == "string" then
							if Function[hpFn] then pcall(Function[hpFn], hpFlag,Character,Data,c) end
						elseif typeof(hpFn) == "table" then
							for i, v in pairs(hpFn) do
								if Function[v] then pcall(Function[v], hpFlag,Character,Data,c) end
							end
						end
					end
				end
			end
			if DataDetail.TopHP ~= "" then
				processHPClothes("TopHP")
			end
			if DataDetail.BottomHP ~= "" then
				processHPClothes("BottomHP")
			end

			-- V4.5.24 (r2) Fix: FindFirstChildOfClass is non-recursive; the face Decal lives inside
			-- Head, so a plain lookup resolved nil on every rig and the branch stayed dead. Use a
			-- recursive WhichIsA scan so face-hide actually finds the decal.
			local FaceDecal = Character and Character:FindFirstChildWhichIsA("Decal", true)
			if FaceDecal and DataDetail.Face == false then
				FaceDecal.Transparency = 1
				DataDetail.CurrentPartList.ParentTransparency[FaceDecal] = {D = 0, T = 1}
			end
			task.wait()
			DataDetail["Cooldown"] = false  -- always release; stale RID has already been superseded
			return true -- only the completed build path acknowledges success
			end)  -- end pcall body
			completion.ok = _ceOk and _ceErr == true and not Function.IsStaleOrGone(Data, RequestID)
			if not completion.ok then completion.error = _ceOk and "build aborted or character unavailable" or tostring(_ceErr) end
			completion.done = true
			if not _ceOk then
				warn("[RoClothes] CharacterExecute error:", _ceErr)
				DataDetail["Cooldown"] = false
			end
		end)

		-- Cooldown safety net: only clear the lock, never destroy the proxy.
		-- V4.3.151: removed CharacterReset from here (V4.3.140 regression) - safety net fires
		-- after 5s of Cooldown==true, which happens during normal slow loads
		-- (Converter × 5 async yields + organ welds + clothing welds). Calling
		-- CharacterReset mid-weld destroys the active proxy, causing all subsequent
		-- PARENT traversals to return nil and fire "what the bloody hell just happened".
		task.delay(5, function()
			-- V4.3.280: skip if our session has been torn down - DataDetail may be a
			-- closure ref to an orphaned PlayerData entry from a prior re-execute.
			if not _isActiveSession() then return end
			if DataDetail and DataDetail["Cooldown"] == true then
				DataDetail["Cooldown"] = false
			end
		end)
		return completion
	end

	function Function.CharacterConnection(Player)
		local CharacterConnect = Player.CharacterAdded:Connect(function(Character)
			-- V4.3.537 Fix 1: clear stale HD snapshot on fresh respawn so the
			-- next CharacterExecute captures the new spawn's clean HD. Without
			-- this clear, the L15828 capture-guard (`if not DataDetail.
			-- OriginalHumanoidDescription`) would keep the PREVIOUS character's
			-- snapshot - which on Roblox respawn could be from a character that
			-- had been bundle-mutated, so the "restore" path would lock the new
			-- character into the prior bundle. The clear runs regardless of
			-- AutoExecute state: even manual-equip users need the next equip
			-- to recapture against the fresh humanoid.
			if PlayerData[Player.Name] ~= nil then
				PlayerData[Player.Name].OriginalHumanoidDescription = nil
			end
			if PlayerData[Player.Name] ~= nil and PlayerData[Player.Name].AutoExecute then
				local waitCount = 0
				while not Function.CharacterIsBuilt(Character) do
					task.wait(0.1)
					waitCount = waitCount + 1
					if waitCount > 50 then return end
				end

				Function.PlayerDataAdd(Player.Name)
				-- V4.3.168.3: honor DelayTime - community report ("auto execute always (see Changelog for full rationale)
				PlayerData[Player.Name].LastRequestID = PlayerData[Player.Name].LastRequestID + 1
				local autoID = PlayerData[Player.Name].LastRequestID
				local delay = tonumber(PlayerData[Player.Name].DelayTime) or 0
				if delay < 0 then delay = 0 end
				if delay > 30 then delay = 30 end  -- clamp; protects against typo'd "9999"
				if delay > 0 then task.wait(delay) end
				-- Bail if anything changed during the delay window: PlayerData destroyed,
				-- user toggled AutoExecute off, a fresh respawn superseded us, or the
				-- Character we were waiting for is gone.
				if not PlayerData[Player.Name] then return end
				if not PlayerData[Player.Name].AutoExecute then return end
				if PlayerData[Player.Name].LastRequestID ~= autoID then return end
				if not Character or not Character.Parent then return end
				local ok, err = pcall(Function.CharacterExecute, Character, Player.Name, nil, autoID)
				if not ok then
					warn("[RoClothes] Auto-execute failed:", err)
					if PlayerData[Player.Name] then
						PlayerData[Player.Name]["Cooldown"] = false
					end
				end
			end
		end)

		GlobalMaid:Give(CharacterConnect)
		-- V4.3.254: also publish the connection on System so BREAKER.Destroying can
		-- disconnect it as the FIRST cleanup step (before VNS teardown / mesh destroys).
		-- Without this, a respawn during BREAKER (or a queued spawn event) could fire
		-- CharacterAdded → CharacterExecute against half-destroyed state. GlobalMaid
		-- only gets to it as step 8 of cleanup, leaving a 50-line race window.
		-- V4.3.531 Fix 9: per-player slot instead of scalar overwrite. See BREAKER cleanup
		-- block at L6813 for the matching teardown.
		if type(System._charAddedConn) ~= "table" then System._charAddedConn = {} end
		local _pName = (Player and Player.Name) or tostring(Player or "unknown")
		if System._charAddedConn[_pName] then
			pcall(function() System._charAddedConn[_pName]:Disconnect() end)
		end
		System._charAddedConn[_pName] = CharacterConnect
	end

	-- V4.3.419: shared preset-value shape validator. Pre-fix the V4.3.355 / V4.3.374 / (see Changelog for full rationale)
	-- V4.3.370 / V4.3.372 shape-validation lived only inside checkBundle's allowlist
	local function _validatePresetValue(setting, value)
		if setting == "CatalogClothes" then
			-- V4.3.505: bound length + charset on Shirt/Pants/ShirtGraphic ID strings. Pre-fix
			-- a peer could broadcast `{Shirt = ("x"):rep(1e6)}` to bloat local PD. Mirrors the
			-- CatalogOutfitId validator below.
			if type(value) ~= "table" then return false end
			local function _validId(v)
				if v == nil then return true end
				if type(v) == "number" then return v == v and v >= 0 and v < 2^53 and v == math.floor(v) end
				if type(v) == "string" then return #v <= 32 and v:match("^%d*$") ~= nil end
				return false
			end
			return _validId(value.Shirt) and _validId(value.Pants) and _validId(value.ShirtGraphic) and _validId(value.Face)
		elseif setting == "CatalogOutfitId" then
			return type(value) == "string" and #value <= 32 and value:match("^%d*$") ~= nil
		elseif setting == "SkinTone" or setting == "NippleColor" then
			return typeof(value) == "Color3"
		elseif setting == "BundleBodyColor" then
			-- V4.3.534 F8: BundleBodyColor is a BOOLEAN toggle (apply-this-bundle's-body-color
			-- on/off), not a Color3. The Color3 lumping in V4.3.354 was a type-confusion
			-- regression: every checkBundle / ApplyBundleToPeerData / presetOverlay write
			-- gated on `typeof(value) == "Color3"` rejected `false`, so the user's
			-- BundleBodyColor=false choice could never persist across save→reload or
			-- broadcast to peers. ResetBundleSettableFields (L24930) left it at default
			-- `true`, so users effectively had a non-functional toggle.
			return type(value) == "boolean"
		elseif setting == "BreastsType" then
			return type(value) == "number" and value >= 1 and value <= MaxBreastsType
				and value == math.floor(value)
		elseif setting == "TorsoType" then
			return type(value) == "number" and value >= 1 and value <= MaxTorsoType
				and value == math.floor(value)
		elseif setting == "ArmType" then
			return type(value) == "number" and value >= 1 and value <= MaxArmType
				and value == math.floor(value)
		elseif setting == "LegsType" then
			return type(value) == "number" and value >= 1 and value <= MaxLegsType
				and value == math.floor(value)
		elseif setting == "ButtType" then
			return type(value) == "number" and value >= 1 and value <= MaxButtType
				and value == math.floor(value)
		elseif setting == "BreastsScale" or setting == "ButtsScale"
			or setting == "LegsScale" or setting == "TorsoScale" or setting == "LeftArmScale"
			or setting == "RightArmScale" or setting == "CockScale"
			or setting == "BreastsStiffness" or setting == "BreastsDamping"
			or setting == "ButtsStiffness" or setting == "ButtsDamping"
			or setting == "CockStiffness" or setting == "CockDamping"
			or setting == "Volume"
		then
			return type(value) == "number" and value == value
				and value >= 0 and value <= 10
		elseif setting == "StripCategories" then
			if type(value) ~= "table" then return false end
			local _allowed = {Hat=true,Hair=true,Face=true,Neck=true,Shoulder=true,Front=true,Back=true,Waist=true}
			for k, vv in pairs(value) do
				if not (_allowed[k] and type(vv) == "boolean") then return false end
			end
			return true
		elseif setting == "AutoStripOnRip" then
			return type(value) == "boolean"
		elseif setting == "StripOnRipMap" then
			if type(value) ~= "table" then return false end
			local _vals = {None=true,Top=true,Bottom=true,Both=true}
			local _count = 0
			for k, vv in pairs(value) do
				_count = _count + 1
				if _count > 200
					or type(k) ~= "string" or #k == 0 or #k > 64
					or k:find("[%c]") ~= nil
					or not _vals[vv]
				then
					return false
				end
			end
			return true
		-- V4.3.447: shape-validate V4.3.446 preset additions. Without these, a hostile
		-- peer broadcasting `CatalogUsername = {nested}` / `CatalogRemove = "x"` /
		-- `MeshEdit = function() end` would write garbage into PlayerData via the
		-- _PEER_ALLOWED_PRESET_KEYS allowlist path.
		elseif setting == "CatalogUsername" then
			return type(value) == "string" and #value <= 32 and value:match("^[%w_]*$") ~= nil
		elseif setting == "CatalogRemove" then
			if type(value) ~= "table" then return false end
			local _n = 0
			for k, vv in pairs(value) do
				_n = _n + 1
				if _n > 256 then return false end  -- defensive cap
				if type(k) ~= "number" or k ~= math.floor(k) then return false end
				local _id = tonumber(vv)
				if not _id or _id <= 0 or _id ~= math.floor(_id) or _id >= 2^53 then return false end
			end
			return true
		elseif setting == "CatalogHistory" then
			-- V4.3.505: producer `_cb_pushHistory` inserts table entries of shape
			-- {id, name, assetType, itemType, priceInRobux}, NOT bare numeric IDs.
			-- Pre-fix validator rejected every legitimate entry → silent drop on
			-- peer broadcast + local re-import.
			if type(value) ~= "table" then return false end
			local _len = 0
			for _, vv in ipairs(value) do
				_len = _len + 1
				if _len > 64 then return false end  -- ring buffer cap is 20; allow some slack
				if type(vv) ~= "table" then return false end
				if not tonumber(vv.id) or tonumber(vv.id) <= 0 then return false end
				if vv.name ~= nil and type(vv.name) ~= "string" then return false end
				if vv.name and #vv.name > 128 then return false end
				if vv.assetType ~= nil and not tonumber(vv.assetType) then return false end
				-- V4.5.24 Fix: itemType is the literal "Bundle" (from _cb_pushHistory) OR a numeric
				-- assetType. tonumber("Bundle") = nil rejected every Bundle-type history entry on peer
				-- broadcast / re-import. Accept a short bounded string as well.
				if vv.itemType ~= nil and not (tonumber(vv.itemType) or (type(vv.itemType) == "string" and #vv.itemType > 0 and #vv.itemType <= 16)) then return false end
				if vv.priceInRobux ~= nil and not tonumber(vv.priceInRobux) then return false end
			end
			return true
		elseif setting == "MeshEdit" then
			-- MeshEdit is a {[partName]=table} map. Reject non-table / functions /
			-- absurdly large payloads. Per-field shape is validated by the existing
			-- L19735+ logic when applied; this gate is the first line of defense.
			if type(value) ~= "table" then return false end
			local _n = 0
			for k, vv in pairs(value) do
				_n = _n + 1
				if _n > 256 then return false end
				if type(k) ~= "string" or #k > 64 then return false end
				if type(vv) ~= "table" then return false end
			end
			return true
		end
		-- V4.3.520 Fix 8: generic shape gate for unvalidated keys. Pre-fix the default
		-- return-true at the bottom made the allowlist cosmetic for ~70% of keys -
		-- a hostile peer could ship math.huge numerics, megabyte strings, or huge
		-- cyclic tables. This catches the common griefing shapes without per-key
		-- per-shape work; specific validators can replace this incrementally.
		-- V4.3.521 Fix 2: V4.3.520 Fix 8 rejected legitimate asset IDs (Roblox catalog IDs
		-- are 1e10-1e11). Whitelist catalog-related keys to bypass the 1e6 magnitude cap.
		local _LARGE_NUMERIC_OK = { CatalogOutfitId=true, CatalogClothes=true, CatalogRemove=true,
			CatalogAccessory=true, CatalogTail=true, CatalogHistory=true }
		local _t = type(value)
		if _t == "number" then
			if value ~= value or math.abs(value) == math.huge then return false end  -- NaN / inf
			if not _LARGE_NUMERIC_OK[setting] and math.abs(value) > 1e15 then return false end  -- absurdly large magnitudes
		elseif _t == "string" then
			if #value > 256 then return false end
		elseif _t == "boolean" or value == nil then
			-- pass
		elseif _t == "table" then
			local _count = 0
			for _ in pairs(value) do _count = _count + 1; if _count > 200 then return false end end
		else
			return false  -- function / userdata / thread → reject
		end
		return true
	end

	-- V4.3.419: shared GizmoOffsets sanitizer. Pre-fix only _overlayTweaks at L13185 (see Changelog for full rationale)
	local function _sanitizeGizmoOffsets(input)
		if type(input) ~= "table" then return {} end
		local _safe = {}
		local function _isFiniteNum(x)
			return type(x) == "number" and x == x and x ~= math.huge and x ~= -math.huge
		end
		for k, v in pairs(input) do
			if type(k) == "string" and #k <= 128 and type(v) == "table" then
				local _entry = {}
				local _ok = true
				for fk, fv in pairs(v) do
					if type(fk) ~= "string" or #fk > 64 then _ok = false; break end
					if fk == "RotCF" or fk == "baseC0" or fk == "baseC1" then
						if typeof(fv) == "CFrame" then _entry[fk] = fv end
					else
						if not _isFiniteNum(fv) then _ok = false; break end
						if fv < -100 or fv > 100 then _ok = false; break end
						_entry[fk] = fv
					end
				end
				if _ok then _safe[k] = _entry end
			end
		end
		return _safe
	end

	-- V4.3.419: shared ClothesRecolor sanitizer. Pre-fix the 3 acceptance sites at (see Changelog for full rationale)
	local function _sanitizeClothesRecolor(colors)
		if type(colors) ~= "table" then return nil end
		local _safe = {}
		local _anyValid = false
		for _, slot in ipairs({"Primary", "Secondary", "Tertiary"}) do
			local v = colors[slot]
			if typeof(v) == "Color3" then
				_safe[slot] = v
				_anyValid = true
			elseif v == "nil" then
				_safe[slot] = "nil"
				_anyValid = true
			end
		end
		if not _anyValid then return nil end
		return _safe
	end

	-- V4.3.168.1: mirror of checkBundle's PURE state-transfer logic - no UI spawning, (see Changelog for full rationale)
	function Function.ApplyBundleToPeerData(name, bundleData)
		local pd = PlayerData[name]
		if not pd or type(bundleData) ~= "table" then return end
		-- Reset every sync-controlled field from one fresh canonical default. Only
		-- allowlisted/presentation fields are replaced: execution maids, request IDs,
		-- original-avatar snapshots, character refs, and sync runtime remain intact.
		local _peerDefaults = Function.PlayerDataDefault()
		for _key in pairs(_PEER_ALLOWED_PRESET_KEYS) do
			pd[_key] = _peerDefaults[_key]
		end
		pd.CatalogAccessory         = _peerDefaults.CatalogAccessory
		pd.CatalogTail              = _peerDefaults.CatalogTail
		pd.CatalogBundleId          = _peerDefaults.CatalogBundleId
		pd.CurrentClothes           = _peerDefaults.CurrentClothes
		pd.GizmoTarget              = _peerDefaults.GizmoTarget
		pd.PartList                 = _peerDefaults.PartList

		-- Preset scalar fields: copy generically, skipping keys that drive local-only
		-- globals (Method / includedAccessoryNames / etc.) or require UI-side work
		-- (CatalogUsername spawns catalog buttons - peer renders without those).
		if bundleData.Preset then
			for setting, value in pairs(bundleData.Preset) do
				if setting == "PositionPhysicsMultiply"
					or setting == "RotationPhysicsMultiply"
					or setting == "Method"
					or setting == "includedAccessoryNames"
					or setting == "excludeAccessoryNames"
					or setting == "CurrentBundle"
					or setting == "CatalogUsername"
					or setting == "CatalogAccessory"
					or setting == "CatalogTail" then
					-- Skip: these either mutate globals meant for local-user rendering
					-- or require GUI spawning we don't do for peers. CatalogAccessory
					-- data IS still applied below via PlayerData copy so accessories
					-- still load via the HumanoidDescription pipeline.
					-- V4.3.521 Fix 13: skip-list branch bypassed _validatePresetValue. Inline shape
					-- gates: cap array length, type-check each entry, reject control chars in strings.
					if (setting == "CatalogAccessory" or setting == "CatalogTail") and type(value) == "table" then
						pd[setting] = {}
						local _count = 0
						for _, x in pairs(value) do
							_count = _count + 1
							if _count > 100 then break end
							local _n = tonumber(x)
							if _n and _n == _n and math.abs(_n) <= 1e15 then
								table.insert(pd[setting], _n)
							end
						end
					elseif setting == "CatalogUsername" then
						if type(value) == "string" and #value <= 64 and value:match("^[%w_]*$") then
							pd.CatalogUsername = value
						end
					end
				elseif _PEER_ALLOWED_PRESET_KEYS[setting] then
					-- V4.3.302: allowlist gate - pre-fix this branch did `pd[setting] = value`
					-- for any non-blacklisted key, letting foreign data write LastRequestID,
					-- Cooldown, AutoExecute, etc. into PlayerData via avatar-sync.
					-- V4.3.419: also apply the shared shape validator (was checkBundle-only
					-- pre-fix; peer-broadcast skipped validation). Drop on bad shape.
					if _validatePresetValue(setting, value) then
						pd[setting] = value
					end
				end
			end
		end

		-- V4.4.2: tailSettings round-trip (additive merge -- was neither captured nor restored). Only Personal
		-- full-save bundles carry Preset.tailSettings; merge its fields into the live tailSettings (the runtime
		-- isTailCurrentlyEnabled is preserved and the physics loop reconciles it).
		if type(bundleData.Preset) == "table" and type(bundleData.Preset.tailSettings) == "table" and type(pd.tailSettings) == "table" then
			-- V4.4.2: type-gate each field against its existing (default) type. Community/imported bundles are
			-- UNTRUSTED and this merge bypasses the peer allowlist/validator; a mistyped field (e.g. a string
			-- linearAmplitude) would otherwise reach the tail multiply and throw in the PreRender loop.
			-- V4.5.24 Fix (CRITICAL): the type gate alone let a crafted numeric field (timeScale = 1e308 /
			-- math.huge / NaN) reach the PreRender accumulator while-loop (stepCount was uncapped) and
			-- hard-freeze the client. Numbers must now be finite AND bounded (defaults max out at 96).
			for _tk, _tv in pairs(bundleData.Preset.tailSettings) do
				if type(_tv) == type(pd.tailSettings[_tk]) then
					if type(_tv) == "number" then
						if _tv == _tv and _tv ~= math.huge and _tv ~= -math.huge and math.abs(_tv) <= 1e4 then
							pd.tailSettings[_tk] = _tv
						end
					else
						pd.tailSettings[_tk] = _tv
					end
				end
			end
		end

		-- Clothing: populate CurrentClothes + ClothesHP (mirror checkBundle L11588).
		if bundleData.Clothing then
			for _, cname in pairs(bundleData.Clothing) do
				if Clothes[cname] then
					if Clothes[cname].Blacklist then
						for _, b in pairs(Clothes[cname].Blacklist) do
							local idx = table.find(pd.CurrentClothes, b)
							if idx then
								table.remove(pd.CurrentClothes, idx)
								pd.ClothesHP[b] = nil
								pd.ClothesRecolor[b] = nil
							end
						end
						-- V4.3.295: same-length-swap defense; see `_buildClothesButtonsPanel`.
						pd._equippedSetSrc = nil
					end
					if not table.find(pd.CurrentClothes, cname) then
						table.insert(pd.CurrentClothes, cname)
					end
					pd.ClothesHP[cname] = nil
					local hp = Clothes[cname].HP
					-- V4.3.339: write the cycle-button format {HP="TopHP"|"BottomHP", Inverse=bool}.
					-- V4.3.338 _applyHPClothes skips entries with `set.Threshold > 0` AND requires
					-- `set["HP"] == hpType`, so the V4.3.214 {Threshold, Inverse}-only format silently
					-- broke the rip pipeline on bundle round-trip. Match the cycle UI format exactly.
					if hp == 1 then
						pd.ClothesHP[cname] = {HP = "TopHP",    Inverse = false}
					elseif hp == 2 then
						pd.ClothesHP[cname] = {HP = "BottomHP", Inverse = false}
					elseif hp == 3 then
						pd.ClothesHP[cname] = {HP = "TopHP",    Inverse = true}
					elseif hp == 4 then
						pd.ClothesHP[cname] = {HP = "BottomHP", Inverse = true}
					elseif hp and hp ~= 0 then
						pd.ClothesHP[cname] = {HP = "TopHP",    Inverse = false}
					end
				end
			end
		end

		-- Recolor: per-cloth color overrides.
		if bundleData.Recolor then
			for cloth, colors in pairs(bundleData.Recolor) do
				if type(cloth) ~= "string" or #cloth > 128 then continue end  -- V4.3.569 M-21: reject malformed/oversize peer key
				-- V4.3.347: validate `colors` shape - must be table with at least one Color3 slot.
				do local _safe = _sanitizeClothesRecolor(colors); if _safe then pd.ClothesRecolor[cloth] = _safe end end -- V4.3.419: was `pd.ClothesRecolor[cloth] = colors` with permissive sentinel check that let unvalidated peer fields ride along
			end
		end

		-- MeshEdit: writes to PartList + CockScale. Mirrors checkBundle L11648.
		-- V4.3.279: same sanity gate as checkBundle - peer/foreign bundles can carry
		-- engine-crashing values (NaN/oversize Size, malformed MeshId).
		if bundleData.MeshEdit then
			for partName, propTbl in pairs(bundleData.MeshEdit) do
				if type(partName) ~= "string" or #partName > 64 or type(propTbl) ~= "table" then continue end  -- V4.3.569 M-23
				for propName, propVal in pairs(propTbl) do
					if type(propName) ~= "string" or #propName > 64 then continue end  -- V4.3.569 M-23
					if propName == "CockScale" then
						if type(propVal) == "number" and propVal == propVal and math.abs(propVal) ~= math.huge then
							pd.CockScale = math.clamp(propVal, 0.1, 10)
						end
					elseif propName == "Color" then
						-- V4.3.349: accept BOTH plain {R,G,B} table AND rehydrated Color3 userdata.
						-- Pre-fix `type(propVal) == "table"` excluded Color3 (typeof returns "Color3"),
						-- so peer/foreign bundles whose Color3 fields had been rehydrated couldn't
						-- match this branch - MeshEdit Color silently no-op'd on every peer apply.
						if pd.PartList[partName] and pd.PartList[partName][propName] then
							if typeof(propVal) == "Color3" then
								pd.PartList[partName][propName].Color = propVal
							elseif type(propVal) == "table"
								and type(propVal.R) == "number" and type(propVal.G) == "number" and type(propVal.B) == "number"
								and propVal.R == propVal.R and propVal.G == propVal.G and propVal.B == propVal.B then
								local rgb = Function.StringTo(tostring(propVal.R * 255 .. "," .. propVal.G * 255 .. "," .. propVal.B * 255), "RGB")
								-- V4.3.510 Fix 6: StringTo returns nil on parse failure (V4.3.509
								-- nil-safety pass). Pre-guard the .Color assignment so it doesn't
								-- throw when the input string is malformed.
								if rgb then
									pd.PartList[partName][propName].Color = rgb
								end
							end
						end
					else
						if pd.PartList[partName] then
							local _safe, _ok = Function.SanitizeMeshEditValue(propName, propVal)
							if _ok then pd.PartList[partName][propName] = _safe end
						end
					end
				end
			end
		end

		if bundleData.HPClothes then
			for cname, val in pairs(bundleData.HPClothes) do
				if type(cname) ~= "string" or #cname > 128 then continue end  -- V4.3.569 M-21
				-- V4.3.343: write the V4.3.339 cycle-button format {HP="TopHP"|"BottomHP", Inverse=bool}
				-- so `_applyHPClothes` actually triggers rips. Pre-fix this block downgraded incoming
				-- {HP, Inverse} entries (the V4.3.339 format) back to {Threshold, Inverse}, which the
				-- skip guard at L14271 + the `set["HP"] == hpType` requirement at L14366 bypass -
				-- silently breaking rip behavior on every bundle round-trip via peers / AvatarSync.
				if type(val) == "table" then
					if val.HP == "TopHP" or val.HP == "BottomHP" then
						-- Already in cycle format - pass through with Inverse-coerce.
						pd.ClothesHP[cname] = {HP = val.HP, Inverse = val.Inverse == true}
					elseif val.Type and (val.Type == "TopHP" or val.Type == "BottomHP") then
						-- Legacy {Type, Inverse} variant.
						pd.ClothesHP[cname] = {HP = val.Type, Inverse = val.Inverse == true}
					else
						-- Legacy {Threshold, Inverse}-only - synthesize HP from Inverse. Default to TopHP.
						pd.ClothesHP[cname] = {HP = "TopHP", Inverse = val.Inverse == true}
					end
				end
			end
		end

		-- AccessoryHP / GizmoOffsets / GizmoOffset - mirror the new fields added to
		-- _saveLiveBundle so peer-applied bundles round-trip these settings too.
		if bundleData.AccessoryHP then
			pd.AccessoryHP = pd.AccessoryHP or {}
			for accName, hpType in pairs(bundleData.AccessoryHP) do
				if type(accName) ~= "string" or #accName > 128 then continue end  -- V4.3.569 M-22
				-- V4.3.422: accept cycle-format `{HP="TopHP"|"BottomHP", Inverse=bool}` table AND
				-- the legacy numeric percent threshold. Mirrors the checkBundle local-import fix
				-- at L20023. Pre-V4.3.422 peer-broadcast bundles with cycle-format AccessoryHP
				-- entries silently dropped them on this path too.
				if type(hpType) == "table" and (hpType.HP == "TopHP" or hpType.HP == "BottomHP") then
					pd.AccessoryHP[accName] = {HP = hpType.HP, Inverse = hpType.Inverse == true}
				elseif type(hpType) == "number" and hpType > 0 then
					pd.AccessoryHP[accName] = hpType
				end
			end
		end
		if bundleData.GizmoOffsets then
			-- V4.3.419: sanitize peer-controlled GizmoOffsets (was wholesale assignment).
			pd.GizmoOffsets = _sanitizeGizmoOffsets(bundleData.GizmoOffsets)
			if pd.GizmoTarget and pd.GizmoOffsets[pd.GizmoTarget] then
				pd.GizmoOffset = pd.GizmoOffsets[pd.GizmoTarget]
			elseif bundleData.GizmoOffset then
				-- V4.3.526 Fix 7: route singular GizmoOffset through _sanitizeGizmoOffsets.
				-- Bypass class confirmed by 3 independent scans; combined with unguarded
				-- :Inverse() sites in render loops, a hostile peer GizmoOffset = {RotCF = junk}
				-- poisons render every frame.
				local _gizSan = _sanitizeGizmoOffsets({_single = bundleData.GizmoOffset})
				if _gizSan and _gizSan._single then pd.GizmoOffset = _gizSan._single end
			end
		elseif bundleData.GizmoOffset then
			-- V4.3.526 Fix 7: route singular GizmoOffset through sanitizer (see sibling above).
			local _gizSan = _sanitizeGizmoOffsets({_single = bundleData.GizmoOffset})
			if _gizSan and _gizSan._single then pd.GizmoOffset = _gizSan._single end
		end
	end

	-- V4.3.168: Avatar Sync - publish/poll/apply foreign bundles.
	-- Endpoints (krulhub_dev v3.15.0+): POST /avatar/publish, GET /avatar/server.
	do
		local PUBLISH_URL          = "https://krulhub.dev/avatar/publish"
		local POLL_URL             = "https://krulhub.dev/avatar/server"

		-- V4.3.423: bounded + content-type-checked JSON decode helper for Avatar Sync. (see Changelog for full rationale)
		local _MAX_BODY_BYTES = 512 * 1024  -- 512 KB ceiling. Worker bodies are ~few KB.
		local function _safeDecodeJsonBody(res)
			if type(res) ~= "table" or res.Body == nil then return false, nil end
			local body = tostring(res.Body)
			if #body > _MAX_BODY_BYTES then return false, nil end
			-- Content-Type check (best-effort - some executors don't expose Headers; we
			-- accept missing header rather than reject so executor-quirk doesn't break sync).
			if type(res.Headers) == "table" then
				local _ct = res.Headers["Content-Type"] or res.Headers["content-type"]
				if type(_ct) == "string" and not _ct:find("application/json", 1, true) then
					return false, nil
				end
			end
			local okJson, parsed = pcall(HS.JSONDecode, HS, body)
			if not okJson or type(parsed) ~= "table" then return false, nil end
			return true, parsed
		end
		-- V4.3.170: aggressive sync intervals - Cloudflare can absorb the request volume. (see Changelog for full rationale)
		-- V4.3.564: 2s → 1s for low-latency peer render (the user asked for "no/low
		-- delay"). Requires the worker's per-IP poll cap raised 30→80/min (handleAvatarServer)
		-- - shipped together. If the worker isn't redeployed yet, the poll loop backs off to
		-- POLL_INTERVAL_BACKOFF on a 429 so we never spam the server; sync still works, just
		-- self-throttled to ~the old cadence until the deploy lands.
		local POLL_INTERVAL_SEC     = 1
		local POLL_INTERVAL_BACKOFF = 2.5
		local PUBLISH_DEBOUNCE_SEC  = 0.15
		-- V4.3.168.19: was 30000 (30s) - way too aggressive. Peer publishes on bundle (see Changelog for full rationale)
		local FOREIGN_STALE_MS     = 600000  -- 10min (2× server TTL as safety margin)

		local function _httpReq()
			return System.Env.http_request
				or System.Env.request
				or (System.Env.syn and System.Env.syn.request)
				or (System.Env.http and System.Env.http.request)
		end

		-- Cheap fingerprint to skip no-op republishes; server does its own SHA-256.
		local function _hashBundle(s)
			return s
		end

		-- V4.3.174: publish entry point. `userInitiated` (default false) sets `AS.userActed` (see Changelog for full rationale)
		Function.AvatarSyncPublish = function(userInitiated, explicitClear)
			local AS = System.AvatarSync
			if not AS.enabled then return end
			if userInitiated then
				AS.userActed = true
				AS.forceClear = explicitClear == true
			end
			if not AS.userActed then return end  -- nothing to broadcast yet
			if AS.jobId == "" then
				-- V4.3.168.20: surface Studio/private-server edge case in toggle label
				AS.lastError = "Studio / no JobId"
				AS.lastErrorAt = (tick and tick()) or os.clock()  -- V4.3.349
				return
			end
			if AS.debounceHandle then pcall(task.cancel, AS.debounceHandle) end
			AS.debounceHandle = task.delay(PUBLISH_DEBOUNCE_SEC, function()
				AS.debounceHandle = nil
				if not AS.enabled then return end
				local pd = PlayerData[Player.Name]
				if not pd then
					AS.lastError = "no PlayerData"
					AS.lastErrorAt = (tick and tick()) or os.clock()  -- V4.3.349
					return
				end
				-- V4.3.168.21: publish an EMPTY bundle on unequip instead of silently skipping. (see Changelog for full rationale)
				-- V4.3.170 (revised): "cleared" must reflect NO active state at all - not just
				local hasRegular  = pd.CurrentBundle and pd.CurrentBundle ~= "nil"
				local hasPreset   = pd.CurrentPreset and pd.CurrentPreset ~= ""
				local hasClothBnd = pd.CurrentClothingBundles and #pd.CurrentClothingBundles > 0
				local hasClothes  = pd.CurrentClothes and #pd.CurrentClothes > 0
				local isCleared = not (hasRegular or hasPreset or hasClothBnd or hasClothes)
				local bundleData
				if hasRegular and Bundle[pd.CurrentBundle] then
					bundleData = Bundle[pd.CurrentBundle]
				else
					-- V4.3.172.1: cleared / ClothingBundle-only / Preset-only / individual-cloth-only. (see Changelog for full rationale)
					bundleData = {
						ClearClothing = true,
						Preset = { Tone = "Base" },  -- known recognized field with valid value
					}
				end
				-- V4.3.564: inject LIVE catalog state (catalog clothing / accessories / outfit /
				-- username) into the published Preset so peers render the user's catalog avatar -
				-- not just whatever a saved Bundle baked in. Pre-fix the payload carried only
				-- Bundle[CurrentBundle] + a body-only tweaksPreset, so catalog items equipped via
				-- the catalog browser (which live in pd.Catalog*, not in any bundle) never reached
				-- peers - and because catalog wasn't in the publish HASH, catalog-only changes were
				-- even deduped away (no publish fired at all). The receiver (ApplyBundleToPeerData)
				-- already applies these Preset keys, so this is a publish-side-only fix. We build a
				-- payload-LOCAL copy (never mutate the saved Bundle) and mirror _buildOutfitPreset's
				-- catalog capture (the proven Save-Outfit shape the receiver already round-trips).
				do
					-- V4.5.23: resolve the wearer's NATIVE avatar shirt/pants to concrete catalog asset ids so
					-- the "Roblox Shirt"/"Roblox Pants"/"Roblox Butt Shirt" items actually SYNC to peers. Those
					-- items paint from the LIVE character at apply time (Extra.Shirt = Character:FindFirstChild
					-- OfClass("Shirt"), L21414); pre-fix only the item NAME rode in clothingList, so on a peer -
					-- where RoClothes has stripped the replicated Shirt/Pants - it re-resolved to nothing = naked.
					-- HumanoidDescription.Shirt/.Pants are catalog CLOTHING asset ids (Studio-verified: uid1
					-- Shirt=607785314), which the receiver already renders via HumanoidDescription - the exact
					-- path the "type your username in Catalog" workaround uses. GetAppliedDescription is
					-- synchronous (no web yield), so it's safe inside this publish-debounce worker.
					local _nativeShirt, _nativePants = "", ""
					if type(pd.CurrentClothes) == "table" and (
						   table.find(pd.CurrentClothes, "Roblox Shirt") ~= nil
						or table.find(pd.CurrentClothes, "Roblox Pants") ~= nil
						or table.find(pd.CurrentClothes, "Roblox Butt Shirt") ~= nil) then
						pcall(function()
							local _hum = Player.Character and Player.Character:FindFirstChildOfClass("Humanoid")
							local _hd = _hum and _hum:GetAppliedDescription()
							if _hd then
								if _hd.Shirt and _hd.Shirt ~= 0 then _nativeShirt = tostring(_hd.Shirt) end
								if _hd.Pants and _hd.Pants ~= 0 then _nativePants = tostring(_hd.Pants) end
							end
						end)
					end
					local _hasNative = (_nativeShirt ~= "" or _nativePants ~= "")
					local cc = pd.CatalogClothes
					local hasCat =
						   (pd.CatalogOutfitId and pd.CatalogOutfitId ~= "")
						or (pd.CatalogUsername and pd.CatalogUsername ~= "")
						or (type(cc) == "table" and ((cc.Shirt and cc.Shirt ~= "") or (cc.Pants and cc.Pants ~= "") or (cc.ShirtGraphic and cc.ShirtGraphic ~= "") or (cc.Face and cc.Face ~= "")))
						or (type(pd.CatalogAccessory) == "table" and #pd.CatalogAccessory > 0)
						or (type(pd.CatalogTail) == "table" and #pd.CatalogTail > 0)
						or _hasNative
					do -- live empty slots must override saved catalog choices too
						local _pub, _preset = {}, {}
						for k, v in pairs(bundleData) do _pub[k] = v end
						-- Catalog present ⇒ NOT a cleared/empty avatar. Drop ClearClothing so the
						-- receiver's isEmptyBundle check (L19283) doesn't evict a catalog-only
						-- (e.g. one-accessory) avatar as "empty". ApplyBundleToPeerData clears
						-- CurrentClothes unconditionally anyway, so no stale clothes leak.
						if hasCat then _pub.ClearClothing = nil end
						if type(bundleData.Preset) == "table" then
							for k, v in pairs(bundleData.Preset) do _preset[k] = v end
						end
						if type(cc) == "table" or _hasNative then
							-- V4.5.23: real catalog ids the user set WIN; fall back to the resolved native
							-- shirt/pants only where the user has no explicit catalog clothing in that slot.
							_preset.CatalogClothes = {
								Shirt        = (cc and cc.Shirt and cc.Shirt ~= "" and cc.Shirt) or _nativeShirt or "",
								Pants        = (cc and cc.Pants and cc.Pants ~= "" and cc.Pants) or _nativePants or "",
								ShirtGraphic = (cc and cc.ShirtGraphic) or "",
								Face         = (cc and cc.Face) or "",
							}
						end
						_preset.CatalogOutfitId = pd.CatalogOutfitId or ""
						_preset.CatalogUsername = pd.CatalogUsername or ""
						if type(pd.CatalogAccessory) == "table" then
							local _a = {}
							for _, v in ipairs(pd.CatalogAccessory) do _a[#_a + 1] = v end
							_preset.CatalogAccessory = _a
						end
						if type(pd.CatalogTail) == "table" then
							local _t = {}
							for _, v in ipairs(pd.CatalogTail) do _t[#_t + 1] = v end
							_preset.CatalogTail = _t
						end
						if type(pd.CatalogRemove) == "table" then
							local _r = {}
							for k, v in pairs(pd.CatalogRemove) do _r[k] = v end
							_preset.CatalogRemove = _r
						end
						-- NOTE: deliberately NOT sending CatalogAssetTypes. The peer receive path
						-- (ApplyBundleToPeerData) has no allowlist/handler for it, so it'd be
						-- dropped - pure wasted payload bytes (and we're near the worker's body
						-- cap with rich catalogs). Peers classify accessory types via their own
						-- GetProductInfo lookups, same as before this change. If peer first-render
						-- with many accessories proves slow, prewarming the peer cache from a
						-- synced map is a future optimization (needs a validated receiver handler).
						_pub.Preset = _preset
						bundleData = _pub
					end
				end
				local dehydrated = dehydrate(bundleData)
				-- V4.3.168.1: include per-player tweaks (ClothesRecolor + GizmoOffsets) (see Changelog for full rationale)
				-- V4.3.170: extended tweaks to carry FULL effective state - the active
				local tweaksPreset = {}
				if pd.BreastsType    and pd.BreastsType    ~= 1       then tweaksPreset.BreastsType    = pd.BreastsType    end
				if pd.TorsoType      and pd.TorsoType      ~= 1       then tweaksPreset.TorsoType      = pd.TorsoType      end
				if pd.ArmType        and pd.ArmType        ~= 1       then tweaksPreset.ArmType        = pd.ArmType        end
				if pd.LegsType       and pd.LegsType       ~= 1       then tweaksPreset.LegsType       = pd.LegsType       end
				if pd.ButtType       and pd.ButtType       ~= 1       then tweaksPreset.ButtType       = pd.ButtType       end
				if pd.BreastsScale   and pd.BreastsScale   ~= 1       then tweaksPreset.BreastsScale   = pd.BreastsScale   end
				if pd.ButtsScale     and pd.ButtsScale     ~= 1       then tweaksPreset.ButtsScale     = pd.ButtsScale     end
				if pd.LegsScale      and pd.LegsScale      ~= 1       then tweaksPreset.LegsScale      = pd.LegsScale      end
				if pd.TorsoScale     and pd.TorsoScale     ~= 1       then tweaksPreset.TorsoScale     = pd.TorsoScale     end
				if pd.LeftArmScale   and pd.LeftArmScale   ~= 1       then tweaksPreset.LeftArmScale   = pd.LeftArmScale   end
				if pd.RightArmScale  and pd.RightArmScale  ~= 1       then tweaksPreset.RightArmScale  = pd.RightArmScale  end
				if pd.CockScale      and pd.CockScale      ~= 1       then tweaksPreset.CockScale      = pd.CockScale      end
				if pd.Tone           and pd.Tone           ~= "Base"  then tweaksPreset.Tone           = pd.Tone           end
				tweaksPreset.BodyPartPhysics = pd.BodyPartPhysics == true  -- always propagate; false must reach peers
				-- V4.3.172: HardcoreHP combat-config sync - boolean + format strings only.
				-- Per-frame damage values (SavedTopHP / SavedBottomHP / TopRipped / BottomRipped)
				-- intentionally NOT synced - they update too frequently and the visual rip
				-- propagates via the next state change anyway. Just sync the user's setup.
				if pd.HardcoreHP                                       then tweaksPreset.HardcoreHP    = true              end
				if pd.TopHP          and pd.TopHP          ~= ""      then tweaksPreset.TopHP         = pd.TopHP          end
				if pd.BottomHP       and pd.BottomHP       ~= ""      then tweaksPreset.BottomHP      = pd.BottomHP       end
				if pd.DamageSFX      and pd.DamageSFX      ~= ""      then tweaksPreset.DamageSFX     = pd.DamageSFX      end
				if pd.Volume         and pd.Volume         ~= 1       then tweaksPreset.Volume        = pd.Volume         end
				if pd.TearParticles  == false                          then tweaksPreset.TearParticles = false             end
				if pd.HealParticles  == false                          then tweaksPreset.HealParticles = false             end
				if pd.RealtimeBodyTransparency == false                then tweaksPreset.RealtimeBodyTransparency = false  end
				if pd.Face           == false                          then tweaksPreset.Face          = false             end
				if pd.PhysicsObeyGravity == false                      then tweaksPreset.PhysicsObeyGravity = false        end
				if pd.AccessorySizeLock                                then tweaksPreset.AccessorySizeLock = true          end
				if pd.MeshSizeLock                                     then tweaksPreset.MeshSizeLock  = true              end
				if pd.MeshBasePartInvisible                            then tweaksPreset.MeshBasePartInvisible = true      end
				if pd.BreastsStiffness and pd.BreastsStiffness ~= 10    then tweaksPreset.BreastsStiffness = pd.BreastsStiffness end
				if pd.BreastsDamping   and pd.BreastsDamping   ~= 0.207 then tweaksPreset.BreastsDamping   = pd.BreastsDamping   end
				if pd.ButtsStiffness   and pd.ButtsStiffness   ~= 10    then tweaksPreset.ButtsStiffness   = pd.ButtsStiffness   end
				if pd.ButtsDamping     and pd.ButtsDamping     ~= 0.1   then tweaksPreset.ButtsDamping     = pd.ButtsDamping     end
				if pd.CockStiffness    and pd.CockStiffness    ~= 8     then tweaksPreset.CockStiffness    = pd.CockStiffness    end
				if pd.CockDamping      and pd.CockDamping      ~= 0.207 then tweaksPreset.CockDamping      = pd.CockDamping      end
				if pd.SmartBoneEnabled                                 then tweaksPreset.SmartBoneEnabled = true               end
				-- V4.3.565: previously-omitted body toggles, so these actions carry over to peers
				-- too. All allowlisted in _PEER_ALLOWED_PRESET_KEYS + validated on receive; they
				-- ride presetOverlay (already dehydrate-safe). Default-gated to keep the payload small.
				if pd.BundleBodyColor == false                          then tweaksPreset.BundleBodyColor = false end
				if pd.NippleColorFromBundle == true                     then tweaksPreset.NippleColorFromBundle = true end
				if pd.BreathingEnabled == true                          then tweaksPreset.BreathingEnabled = true end
				if pd.OvertoneEnabled == true                           then tweaksPreset.OvertoneEnabled = true end
				if pd.BreathingAmplitude and pd.BreathingAmplitude ~= 0.03  then tweaksPreset.BreathingAmplitude = pd.BreathingAmplitude end
				if pd.OvertoneAmplitude  and pd.OvertoneAmplitude  ~= 0.015 then tweaksPreset.OvertoneAmplitude  = pd.OvertoneAmplitude  end
				if pd.BodyTransparency   and pd.BodyTransparency   ~= 0     then tweaksPreset.BodyTransparency   = pd.BodyTransparency   end
				-- Correct the legacy global-default comparisons above against the actual
				-- bundle being published. Default/false live values must override a
				-- non-default saved bundle value; a genuine no-op remains omitted.
				local _effectivePreset = type(bundleData.Preset) == "table" and bundleData.Preset or {}
				local _publishDefaults = {
					BreastsType=1, TorsoType=1, ArmType=1, LegsType=1, ButtType=1,
					BreastsScale=1, ButtsScale=1, LegsScale=1, TorsoScale=1, LeftArmScale=1, RightArmScale=1, CockScale=1, Tone="Base",
					BodyPartPhysics=false, HardcoreHP=false, TopHP="", BottomHP="", DamageSFX="", Volume=1,
					TearParticles=true, HealParticles=true, RealtimeBodyTransparency=true, Face=true,
					PhysicsObeyGravity=true, AccessorySizeLock=false, MeshSizeLock=false, MeshBasePartInvisible=false,
					BreastsStiffness=10, BreastsDamping=0.207, ButtsStiffness=10, ButtsDamping=0.1,
					CockStiffness=8, CockDamping=0.207, SmartBoneEnabled=false, BundleBodyColor=true,
					NippleColorFromBundle=false, BreathingEnabled=false, OvertoneEnabled=false,
					BreathingAmplitude=0.03, OvertoneAmplitude=0.015, BodyTransparency=0,
				}
				local function _publishTweak(_key)
					local _base = _effectivePreset[_key]
					if _base == nil then _base = _publishDefaults[_key] end
					if pd[_key] ~= nil and pd[_key] ~= _base then tweaksPreset[_key] = pd[_key]
					else tweaksPreset[_key] = nil end
				end
				for _, _key in ipairs({
					"BreastsType", "TorsoType", "ArmType", "LegsType", "ButtType",
					"BreastsScale", "ButtsScale", "LegsScale", "TorsoScale", "LeftArmScale", "RightArmScale", "CockScale", "Tone",
					"BodyPartPhysics", "HardcoreHP", "TopHP", "BottomHP", "DamageSFX", "Volume",
					"TearParticles", "HealParticles", "RealtimeBodyTransparency", "Face",
					"PhysicsObeyGravity", "AccessorySizeLock", "MeshSizeLock", "MeshBasePartInvisible",
					"BreastsStiffness", "BreastsDamping", "ButtsStiffness", "ButtsDamping",
					"CockStiffness", "CockDamping", "SmartBoneEnabled", "BundleBodyColor",
					"NippleColorFromBundle", "BreathingEnabled", "OvertoneEnabled",
					"BreathingAmplitude", "OvertoneAmplitude", "BodyTransparency",
				}) do _publishTweak(_key) end
				-- A normal body-only/default apply must remain distinguishable from an
				-- explicit Reset clear. The receiver already treats this field as valid.
				tweaksPreset.BodyPartPhysics = pd.BodyPartPhysics == true
				-- Convert CurrentClothes array → "#N"-keyed table so dehydrate emits the
				-- bundle-style integer-key wire format.
				local clothingMap = {}
				for i, name in ipairs(pd.CurrentClothes or {}) do clothingMap[i] = name end
				local tweaks = {
					clothesRecolor = dehydrate(pd.ClothesRecolor or {}),
					gizmoOffsets   = dehydrate(pd.GizmoOffsets or {}),
					gizmoOffset    = dehydrate(pd.GizmoOffset or {}),
					clothingList   = dehydrate(clothingMap),
					clothesHP      = dehydrate(pd.ClothesHP or {}),
					presetOverlay  = dehydrate(tweaksPreset),
					nippleColor    = pd.NippleColor and dehydrate(pd.NippleColor) or nil,
					-- V4.3.171: skin tone overlay - user can manually pick a tone via the
					-- Recolor tab's color picker which writes pd.SkinTone. Without this,
					-- peers see the bundle's default skin tone, not the user's manual edit.
					skinTone       = pd.SkinTone and dehydrate(pd.SkinTone) or nil,
				}
				if AS.forceClear then
					-- Reset is an explicit protocol clear, not an inference from absent
					-- clothes. Keep it sticky so forced heartbeats remain clear.
					dehydrated = dehydrate({ ClearClothing = true, Preset = { Tone = "Base" } })
					tweaks = {}
				end
				-- Hash bundle + tweaks combined so tweak-only changes still trigger a republish.
				local okBundleEnc, bundleEnc = pcall(HS.JSONEncode, HS, dehydrated)
				local okTweakEnc, tweakEnc = pcall(HS.JSONEncode, HS, tweaks)
				if not okBundleEnc or not okTweakEnc then return end
				local hash = _hashBundle(bundleEnc .. "|" .. tweakEnc)
				if hash == AS.lastPublishedHash then return end
				local payload = {
					placeId       = AS.placeId,
					jobId         = AS.jobId,
					userId        = Player.UserId,
					displayName   = Player.DisplayName,
					scriptVersion = VersionInternal,
					updatedAt     = math.floor(os.time() * 1000 + (((tick and tick()) or os.clock()) % 1) * 1000),  -- V4.3.375: tick() guard
					bundle        = dehydrated,
					tweaks        = tweaks,
				}
				local okBody, body = pcall(HS.JSONEncode, HS, payload)
				if not okBody then return end
				local req = _httpReq()
				if not req then
					AS.lastError = "no HTTP API"
					AS.lastErrorAt = (tick and tick()) or os.clock()  -- V4.3.349
					return
				end
				local okReq, res = pcall(req, {Url = PUBLISH_URL, Method = "POST", Headers = {["Content-Type"] = "application/json"}, Body = body})
				if okReq and res and tonumber(res.StatusCode) and tonumber(res.StatusCode) >= 200 and tonumber(res.StatusCode) < 300 then
					AS.lastPublishedHash = hash
					AS.lastError = nil
				else
					-- V4.3.168.5: surface failure in toggle label instead of silent skip.
					-- V4.3.172.1: ALSO capture worker's response-body detail (per V3.18.1 worker
					-- handoff, 400 responses now include `{"error":"...","detail":"..."}`). This
					-- tells us WHICH validator tripped (bad_bundle_shape vs bad_script_version vs
					-- bad_job_id etc.) instead of just bare "publish 400".
					local code = (okReq and res and tonumber(res.StatusCode)) or 0
					local detail = ""
					if okReq and res then
						-- V4.3.423: was `pcall(HS.JSONDecode, HS, tostring(res.Body))` with no
						-- size cap / content-type check. Use the bounded helper.
						local okJson, parsed = _safeDecodeJsonBody(res)
						if okJson then
							detail = " " .. tostring(parsed.error or "") .. (parsed.detail and (" " .. tostring(parsed.detail):sub(1, 50)) or "")
						end
					end
					if code == 0 then
						AS.lastError = "publish network error"
					elseif code == 429 then
						AS.lastError = "publish rate-limited"
					else
						AS.lastError = "publish " .. tostring(code) .. detail
					end
					AS.lastErrorAt = (tick and tick()) or os.clock()  -- V4.3.349
				end
				-- No inline retry - next bundle-apply event will retry naturally.
			end)
		end

		-- V4.3.174: synchronous "I'm leaving - wipe me" publish for clean toggle-OFF. (see Changelog for full rationale)
		local function _publishClearedSync()
			local AS = System.AvatarSync
			if AS.jobId == "" then return end
			local req = _httpReq()
			if not req then return end
			local payload = {
				placeId       = AS.placeId,
				jobId         = AS.jobId,
				userId        = Player.UserId,
				displayName   = Player.DisplayName,
				scriptVersion = VersionInternal,
				updatedAt     = math.floor(os.time() * 1000 + (((tick and tick()) or os.clock()) % 1) * 1000),  -- V4.3.375: tick() guard
				bundle        = { ClearClothing = true, Preset = { Tone = "Base" } },
				tweaks        = {},
			}
			local okBody, body = pcall(HS.JSONEncode, HS, payload)
			if not okBody then return end
			pcall(req, {Url = PUBLISH_URL, Method = "POST", Headers = {["Content-Type"] = "application/json"}, Body = body})
		end

		-- V4.3.173: Receiver rewrite. Drops the parallel `_applyForeignBundle` / (see Changelog for full rationale)
		local function _overlayTweaks(name, tweaks)
			local pd = PlayerData[name]
			if not pd or type(tweaks) ~= "table" then return end
			if type(tweaks.clothesRecolor) == "table" then
				for cloth, colors in pairs(tweaks.clothesRecolor) do
					if type(cloth) ~= "string" or #cloth > 128 then continue end  -- V4.3.569 M-25
					-- V4.3.347: validate `colors` shape - must be table with at least one Color3 slot.
				do local _safe = _sanitizeClothesRecolor(colors); if _safe then pd.ClothesRecolor[cloth] = _safe end end -- V4.3.419: was `pd.ClothesRecolor[cloth] = colors` with permissive sentinel check that let unvalidated peer fields ride along
				end
			end
			-- V4.3.382: bounded sanitizers for peer-supplied data. A malicious peer
			-- could ship `tweaks.gizmoOffsets` with NaN/inf coords, 100k cloth names
			-- in `clothingList`, or `clothesHP` shapes that crash _applyHPClothes.
			-- Pre-fix the only validation was `type == "table"` which permitted
			-- arbitrary content. Sanitize via the helpers below before the writes.
			local function _isFiniteNum(x)
				return type(x) == "number" and x == x and x ~= math.huge and x ~= -math.huge
			end
			if type(tweaks.gizmoOffsets) == "table" then
				-- V4.3.419: was a ~20-line inline sanitizer; extracted to
				-- `_sanitizeGizmoOffsets` near ApplyBundleToPeerData so the bundle path
				-- can reuse the same logic (was previously skipping sanitization).
				pd.GizmoOffsets = _sanitizeGizmoOffsets(tweaks.gizmoOffsets)
				local _relinked = false
				if pd.GizmoTarget and pd.GizmoOffsets[pd.GizmoTarget] then
					pd.GizmoOffset = pd.GizmoOffsets[pd.GizmoTarget]
					_relinked = true
				end
				if not _relinked and type(tweaks.gizmoOffset) == "table" then
					-- V4.3.526 Fix 7: route singular gizmoOffset through _sanitizeGizmoOffsets.
					local _gizSan = _sanitizeGizmoOffsets({_single = tweaks.gizmoOffset})
					if _gizSan and _gizSan._single then pd.GizmoOffset = _gizSan._single end
				end
			elseif type(tweaks.gizmoOffset) == "table" then
				-- V4.3.526 Fix 7: route singular gizmoOffset through sanitizer.
				local _gizSan = _sanitizeGizmoOffsets({_single = tweaks.gizmoOffset})
				if _gizSan and _gizSan._single then pd.GizmoOffset = _gizSan._single end
			end
			if type(tweaks.clothingList) == "table" then
				local newClothing = {}
				local _seen = {}  -- V4.3.382: dedup + cap at 256 entries
				for _, n in pairs(tweaks.clothingList) do
					if type(n) == "string" and #n <= 128 and not _seen[n] and #newClothing < 256 then
						_seen[n] = true
						table.insert(newClothing, n)
					end
				end
				pd.CurrentClothes = newClothing
			end
			if type(tweaks.clothesHP) == "table" then
				-- V4.3.382: per-entry shape validation. Each cloth's HP entry must be
				-- `{HP = "TopHP"|"BottomHP", Inverse = bool}` (the V4.3.362 cycle-format).
				local _safe = {}
				for cloth, entry in pairs(tweaks.clothesHP) do
					if type(cloth) == "string" and #cloth <= 128 and type(entry) == "table" then
						local _hp = entry.HP
						if (_hp == "TopHP" or _hp == "BottomHP") and type(entry.Inverse) == "boolean" then
							_safe[cloth] = {HP = _hp, Inverse = entry.Inverse}
						end
					end
				end
				pd.ClothesHP = _safe
			end
			if type(tweaks.presetOverlay) == "table" then
				-- V4.3.302: file-scope `_PEER_ALLOWED_PRESET_KEYS` allowlist.
				-- V4.3.382: NaN/inf guard on numeric values + per-key range validation.
				-- V4.3.521 Fix 12: route presetOverlay through _validatePresetValue. Pre-fix only
				-- the bundle path (ApplyBundleToPeerData) called the validator; presetOverlay
				-- bypassed it entirely, letting hostile peers ship megabyte strings, NaN/inf,
				-- huge cyclic tables directly into local PD.
				for k, v in pairs(tweaks.presetOverlay) do
					if _PEER_ALLOWED_PRESET_KEYS[k] then
						local _ok = true
						if type(v) == "number" then
							_ok = _isFiniteNum(v)
							-- Range-check the scale/stiffness/damping fields per V4.3.374
							-- checkBundle convention: [0, 10].
							if _ok and (k:find("Scale$") or k:find("Stiffness$") or k:find("Damping$") or k == "Volume") then
								_ok = v >= 0 and v <= 10
							end
						end
						if _ok and _validatePresetValue(k, v) then pd[k] = v end
					end
				end
			end
			-- V4.3.565: harden the Color3 commit. rehydrate restores a real Color3 from the
			-- {__t="C3n"} wire shape (same-version peers); a foreign/legacy payload may carry a
			-- plain {R,G,B} table. Coerce that, and DROP any non-Color3 so it can never be
			-- assigned to a body-color property (a raw table there throws and aborts the WHOLE
			-- peer apply inside the pcall-swallowed CharacterExecute).
			local function _asColor3(v)
				if typeof(v) == "Color3" then return v end
				if type(v) == "table" then
					local r, g, b = v.R or v.r, v.G or v.g, v.B or v.b
					if type(r) == "number" and type(g) == "number" and type(b) == "number" then
						return Color3.new(math.clamp(r, 0, 1), math.clamp(g, 0, 1), math.clamp(b, 0, 1))
					end
				end
			return nil
			end
			if tweaks.nippleColor ~= nil then local _c = _asColor3(tweaks.nippleColor); if _c then pd.NippleColor = _c end end
			if tweaks.skinTone    ~= nil then local _c = _asColor3(tweaks.skinTone);    if _c then pd.SkinTone    = _c end end
		end

		-- Run the same pipeline the Execute button uses, with peer's data loaded into PlayerData.
		local function _runExecuteForPeer(foreign, dataKey, bundleData, tweaks, current)
			-- V4.3.349: liveness re-check + deep-clone peer payload. Pre-fix: (see Changelog for full rationale)
			local _stillLive = function() return foreign and foreign.Parent == PS and (not current or current()) end
			if not _stillLive() then return false, "peer left before apply" end
			local _safeBundle = bundleData
			pcall(function()
				local _enc = HS:JSONEncode(bundleData)
				_safeBundle = HS:JSONDecode(_enc)
			end)
			Bundle[dataKey] = _safeBundle
			Function.PlayerDataAdd(foreign.Name)
			if not _stillLive() then return false, "peer left during PlayerDataAdd" end
			local pd = PlayerData[foreign.Name]
			if not pd then return false, "PlayerData add failed" end
			pd.CurrentBundle           = dataKey
			pd.CurrentPreset           = nil
			pd.CurrentClothingBundles  = {}
			Function.ApplyBundleToPeerData(foreign.Name, _safeBundle)
			if not _stillLive() then return false, "peer left during ApplyBundleToPeerData" end
			_overlayTweaks(foreign.Name, tweaks)
			pd.LastRequestID = (pd.LastRequestID or 0) + 1
			local rid = pd.LastRequestID
			pcall(Function.CharacterReset, foreign.Name)
			if not _stillLive() then return false, "peer left during CharacterReset" end
			local called, ticket = pcall(Function.CharacterExecute, foreign.Character, foreign.Name, nil, rid)
			if not called then return false, ticket end
			if type(ticket) ~= "table" then return false, "missing build completion" end
			local deadline = os.clock() + 30
			while not ticket.done and _stillLive() and pd.LastRequestID == rid and os.clock() < deadline do task.wait(0.05) end
			if not _stillLive() or pd.LastRequestID ~= rid then
				if pd.LastRequestID == rid then pd.LastRequestID = rid + 1 end
				return false, "superseded"
			end
			if not ticket.done then
				pd.LastRequestID = rid + 1 -- cancel the timed-out build before retry
				return false, "build completion timeout"
			end
			return ticket.ok == true, ticket.error
		end

		local function _syncApplyToPeer(userId, bundleData, updatedAt, tweaks)
			local AS = System.AvatarSync
			if not AS.enabled or not _isActiveSession() or userId == Player.UserId then return end
			local foreign = PS:GetPlayerByUserId(userId)
			if not foreign then return end
			local entry = AS.syncedPeers[userId]
			if SelectPlayer == foreign.Name then
				if entry and entry.characterAddedConn then entry.characterAddedConn:Disconnect() end
				AS.syncedPeers[userId] = nil
				return
			end
			if not entry then
				entry = {dataKey = "_peer_" .. foreign.Name, playerName = foreign.Name, generation = 0}
				AS.syncedPeers[userId] = entry
				entry.characterAddedConn = foreign.CharacterAdded:Connect(function()
					if AS.syncedPeers[userId] ~= entry then return end
					entry.generation = entry.generation + 1
					entry.applied, entry.pending, entry.retryAt = false, false, nil
				end)
			end
			if entry.lastUpdatedMs ~= updatedAt then
				entry.generation = entry.generation + 1
				entry.lastUpdatedMs, entry.bundleData, entry.tweaks = updatedAt, bundleData, tweaks
				entry.applied, entry.pending, entry.retryAt = false, false, nil
			end
			if entry.applied or entry.pending or not foreign.Character then return end
			if entry.retryAt and os.clock() < entry.retryAt then return end
			entry.pending = true
			local generation = entry.generation
			local character = foreign.Character
			local function current()
				return AS.enabled and _isActiveSession() and AS.syncedPeers[userId] == entry
					and entry.generation == generation and foreign.Character == character
					and foreign.Parent == PS and SelectPlayer ~= foreign.Name
			end
			task.spawn(function()
				if not current() then return end
				local ran, ok, err = pcall(_runExecuteForPeer, foreign, entry.dataKey, entry.bundleData, entry.tweaks, current)
				if not current() then return end
				entry.pending = false
				entry.applied = ran and ok == true
				if not entry.applied then
					entry.retryAt = os.clock() + 3
					AS.lastError = "apply " .. foreign.Name .. ": " .. tostring(ran and err or ok):sub(1,60)
					AS.lastErrorAt = (tick and tick()) or os.clock()
				end
			end)
		end

		local function _syncRemovePeer(userId, force)
			local AS = System.AvatarSync
			local entry = AS.syncedPeers[userId]
			if not entry then return end
			-- Guard: if the local user has this peer manually selected, don't wipe their session.
			-- Keep the entry AND characterAddedConn alive so respawn-reapply still works.
			if entry.playerName == SelectPlayer and not force then
				return  -- respawn path keeps the entry + conn alive. V4.4.2: `force` (a real PlayerRemoving departure) bypasses this so a departed peer who is the selected target isn't left as a ghost avatar.
			end
			if entry.characterAddedConn then
				pcall(function() entry.characterAddedConn:Disconnect() end)
			end
			-- Bump RID + reset to clean up the proxy via the same pipeline that handles
			-- a manual Reset on a SelectPlayer target.
			if PlayerData[entry.playerName] then
				PlayerData[entry.playerName].LastRequestID = (PlayerData[entry.playerName].LastRequestID or 0) + 1
				pcall(Function.CharacterReset, entry.playerName)
				-- V4.3.302: tear down Maid before drop (else its tasks linger until L3647 sweep).
				if PlayerData[entry.playerName].ExecutionMaid then
					pcall(function() PlayerData[entry.playerName].ExecutionMaid:DoCleaning() end)
				end
				PlayerData[entry.playerName] = nil
			end
			Bundle[entry.dataKey] = nil
			if Method2CharacterFolder then
				local m = Method2CharacterFolder:FindFirstChild(entry.playerName)
				if m then pcall(function() m:Destroy() end) end
			end
			AS.syncedPeers[userId] = nil
		end

		Function.AvatarSyncPoll = function()
			local AS = System.AvatarSync
			if not AS.enabled or AS.jobId == "" then return end
			local function retryPeers()
				for uid, entry in pairs(AS.syncedPeers) do
					if not entry.applied and entry.bundleData then
						_syncApplyToPeer(uid, entry.bundleData, entry.lastUpdatedMs, entry.tweaks)
					end
				end
			end
			-- Recover skipped/locally-owned/failed entries, and tolerate an older Worker.
			if not AS.nextFullPoll or os.clock() >= AS.nextFullPoll then
				AS.pollCursor = nil
				AS.nextFullPoll = os.clock() + 30
			end
			local req = _httpReq()
			if not req then return end
			local url = POLL_URL .. "?placeId=" .. tostring(AS.placeId)
				.. "&jobId=" .. HS:UrlEncode(AS.jobId)
				.. "&self=" .. tostring(Player.UserId)
				.. "&protocol=2"
			if AS.pollCursor then url = url .. "&since=" .. tostring(AS.pollCursor) end
			local okReq, res = pcall(req, {Url = url, Method = "GET"})
			if not AS.enabled or not _isActiveSession() then return end
			if not okReq or not res then
				AS.lastError = "poll network error"
				AS.lastErrorAt = (tick and tick()) or os.clock()  -- V4.3.349
				return
			end
			local code = tonumber(res.StatusCode) or 0
			if code == 304 then AS.lastError = nil; retryPeers(); return end
			if code < 200 or code >= 300 then
				AS.lastError = (code == 429) and "poll rate-limited" or ("poll " .. tostring(code))
				AS.lastErrorAt = (tick and tick()) or os.clock()  -- V4.3.349
				return
			end
			AS.lastError = nil
			-- V4.3.423: was `pcall(HS.JSONDecode, HS, tostring(res.Body or ""))` with no
			-- size cap / content-type check. Use the bounded helper.
			local okJson, parsed = _safeDecodeJsonBody(res)
			if not okJson or not parsed.ok then
				-- V4.3.168.21: surface malformed response so user can distinguish
				-- "worker responding with HTML/error" from "worker not responding at all"
				AS.lastError = "poll: bad response"
				AS.lastErrorAt = (tick and tick()) or os.clock()  -- V4.3.349
				return
			end
			-- V4.3.168.21: remember peers-seen count for the toggle label (separate from
			-- successfully-applied). If server reports N peers but we apply 0, user gets
			-- a diagnostic signal instead of bare "ON (0 peers)".
			AS.lastSeenCount = (type(parsed.entries) == "table") and #parsed.entries or 0
			local present
			if parsed.protocol == 2 and type(parsed.present) == "table" then
				present = {}
				for _, uid in ipairs(parsed.present) do if tonumber(uid) then present[tonumber(uid)] = true end end
				AS.lastSeenCount = #parsed.present
				local removed = {}
				for uid in pairs(AS.syncedPeers) do if not present[uid] then removed[#removed+1] = uid end end
				for _, uid in ipairs(removed) do _syncRemovePeer(uid) end
			end
			if type(parsed.entries) == "table" then
				for _, e in ipairs(parsed.entries) do
					if type(e) == "table" and tonumber(e.userId) and type(e.bundle) == "table" then
						if present and not present[tonumber(e.userId)] then continue end
						local rehydrated = rehydrate(e.bundle)
						-- V4.3.168.22: empty-bundle peer destroys the proxy (rebuild-with-empty
						-- left invisible peer + LocalTransparencyModifier=1 on real body parts).
						-- V4.3.174: prefer explicit ClearClothing flag; field-list check kept
						-- as fallback for malformed / pre-V4.3.172.1 publishers.
						local isEmptyBundle = rehydrated.ClearClothing == true or not (
							rehydrated.Clothing or rehydrated.Accessory or rehydrated.Clothes or
							rehydrated.Preset or rehydrated.MeshEdit or rehydrated.Recolor or
							rehydrated.NippleColor or rehydrated["Body Color"] or rehydrated.HPClothes
						)
						-- V4.3.170 (revised): a publish with empty `bundle` no longer means "user (see Changelog for full rationale)
						local tweaksHaveContent = false
						if type(e.tweaks) == "table" then
							tweaksHaveContent =
								(type(e.tweaks.clothingList)  == "table" and next(e.tweaks.clothingList)  ~= nil) or
								(type(e.tweaks.presetOverlay) == "table" and next(e.tweaks.presetOverlay) ~= nil) or
								(type(e.tweaks.clothesHP)     == "table" and next(e.tweaks.clothesHP)     ~= nil) or
								(type(e.tweaks.clothesRecolor)== "table" and next(e.tweaks.clothesRecolor)~= nil) or
								(e.tweaks.nippleColor ~= nil) or
								(e.tweaks.skinTone ~= nil)
						end
						if isEmptyBundle and not tweaksHaveContent then
							_syncRemovePeer(tonumber(e.userId))
						else
							local tweaks = nil
							if type(e.tweaks) == "table" then
								tweaks = {
									clothesRecolor = type(e.tweaks.clothesRecolor) == "table" and rehydrate(e.tweaks.clothesRecolor) or nil,
									gizmoOffsets   = type(e.tweaks.gizmoOffsets)   == "table" and rehydrate(e.tweaks.gizmoOffsets)   or nil,
									gizmoOffset    = type(e.tweaks.gizmoOffset)    == "table" and rehydrate(e.tweaks.gizmoOffset)    or nil,
									clothingList   = type(e.tweaks.clothingList)   == "table" and rehydrate(e.tweaks.clothingList)   or nil,
									clothesHP      = type(e.tweaks.clothesHP)      == "table" and rehydrate(e.tweaks.clothesHP)      or nil,
									presetOverlay  = type(e.tweaks.presetOverlay)  == "table" and rehydrate(e.tweaks.presetOverlay)  or nil,
									nippleColor    = e.tweaks.nippleColor and rehydrate(e.tweaks.nippleColor) or nil,
									skinTone       = e.tweaks.skinTone and rehydrate(e.tweaks.skinTone) or nil,
								}
							end
							-- V4.3.173: pcall the apply so any silent throw surfaces in the toggle label.
							local _aOk, _aErr = pcall(_syncApplyToPeer, tonumber(e.userId), rehydrated, tonumber(e.updatedAt) or 0, tweaks)
							local seen = AS.syncedPeers[tonumber(e.userId)]
							if seen then seen.lastSeenMs = tonumber(parsed.now) or os.time()*1000 end
							if not _aOk then
								AS.lastError = "applyfn: " .. tostring(_aErr):sub(1, 40)
								AS.lastErrorAt = (tick and tick()) or os.clock()  -- V4.3.349
							end
						end
					end
				end
			end
			if type(parsed.removed) == "table" then
				for _, uid in ipairs(parsed.removed) do
					local _uid = tonumber(uid)
					if _uid and _uid ~= Player.UserId then _syncRemovePeer(_uid) end
				end
			end
			-- Client-side staleness fallback in case server omits `removed`.
			-- V4.3.172.2 fix carried forward: epoch ms via os.time()*1000 (NOT tick()*1000
			-- which is process-seconds - diff would always exceed FOREIGN_STALE_MS).
			local nowMs = tonumber(parsed.now) or (os.time() * 1000)
			local _stale = {}
			for uid, entry in pairs(AS.syncedPeers) do
				if not present and nowMs - (entry.lastSeenMs or nowMs) > FOREIGN_STALE_MS then
					_stale[#_stale+1] = uid
				end
			end
			for _, uid in ipairs(_stale) do _syncRemovePeer(uid) end
			if tonumber(parsed.cursor) then AS.pollCursor = tonumber(parsed.cursor) end
			retryPeers()
		end

		Function.AvatarSyncStart = function()
			local AS = System.AvatarSync
			if AS.pollHandle then return end
			AS.clearToken = (AS.clearToken or 0) + 1 -- cancel any in-flight _publishClearedSync
			-- V4.3.521 Fix 14: getgenv handoff for re-execute cancellation (mirrors V4.3.514 pattern).
			do
				local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
				local _prior = _ok_genv and _genv and _genv._RC_avsync_poll_task or nil
				if _prior then pcall(task.cancel, _prior) end
			end
			AS.pollHandle = task.spawn(function()
				while AS.enabled do
					pcall(Function.AvatarSyncPoll)
					-- V4.3.564: fast 1s cadence for low-latency render; on ANY poll error
					-- (429 from an un-upgraded worker, network, 5xx, bad response) back off so
					-- a flaky/rate-limiting server doesn't get 2× the request pressure - sync
					-- still works, just slower. Match the "poll" prefix so a *publish* error
					-- (which shares AS.lastError, e.g. "publish rate-limited") doesn't wrongly
					-- throttle polling.
					local _le = AS.lastError
					task.wait((_le and string.sub(_le, 1, 4) == "poll") and POLL_INTERVAL_BACKOFF or POLL_INTERVAL_SEC)
				end
				AS.pollHandle = nil
			end)
			-- V4.3.521 Fix 14: stash poll handle on getgenv() for cross-exec cancellation.
			do
				local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
				if _ok_genv and _genv then _genv._RC_avsync_poll_task = AS.pollHandle end
			end
			-- V4.3.168.19: heartbeat re-publish every 60s so peers who stay on the same (see Changelog for full rationale)
			if not AS.heartbeatHandle then
				-- V4.3.521 Fix 14: getgenv handoff for re-execute cancellation.
				do
					local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
					local _prior = _ok_genv and _genv and _genv._RC_avsync_hb_task or nil
					if _prior then pcall(task.cancel, _prior) end
				end
				AS.heartbeatHandle = task.spawn(function()
					while AS.enabled do
						task.wait(30)  -- V4.3.170: 60s → 30s, well under server's 300s TTL
						if AS.enabled then
							AS.lastPublishedHash = nil  -- force publish-fn to hit the server
							pcall(Function.AvatarSyncPublish)
						end
					end
					AS.heartbeatHandle = nil
				end)
				-- V4.3.521 Fix 14: stash heartbeat handle on getgenv() for cross-exec cancellation.
				do
					local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
					if _ok_genv and _genv then _genv._RC_avsync_hb_task = AS.heartbeatHandle end
				end
			end
		end

		-- Clean up peers when a player leaves - avoids 10-minute stale-window via FOREIGN_STALE_MS
		local _playerRemovingConn = PS.PlayerRemoving:Connect(function(player)
			-- V4.5.24 Fix: force-remove regardless of sync state. _syncRemovePeer no-ops when
			-- the uid isn't a synced peer, so the unconditional call is safe and closes the gap
			-- where a lingering entry (e.g. selected-peer leftover from an AvatarSync toggle-off)
			-- survived because the old `if System.AvatarSync.enabled` guard skipped this cleanup.
			_syncRemovePeer(player.UserId, true)  -- V4.4.2: force -- a real departure, so bypass the SelectPlayer keep-alive guard (else a departed selected peer lingers as a ghost avatar)
			-- V4.3.347: prune PlayerData[player.Name] for ordinary leavers - pre-fix this only
			-- happened for AvatarSync peers, so PlayerData grew monotonically across the session
			-- as players joined/left. Each entry carries CurrentClothes/CurrentBundle/GizmoOffset/
			-- ClothesHP/etc. - measurable memory leak on populated/long-lived servers.
			pcall(function()
				local _pd = PlayerData[player.Name]
				if _pd then
					if _pd.ExecutionMaid then pcall(function() _pd.ExecutionMaid:DoCleaning() end) end
					PlayerData[player.Name] = nil
				end
			end)
		end)
		System.GlobalMaid:Give(_playerRemovingConn)

		Function.AvatarSyncStop = function()
			local AS = System.AvatarSync
			-- V4.3.540 Fix 6: reorder Stop so AS.enabled = false and debounceHandle
			-- cancel run BEFORE spawning _publishClearedSync. Pre-fix any pending
			-- task.delay(0.15) from a recent AvatarSyncPublish could fire AFTER the
			-- cleared payload arrived at the server, causing peers to see clear →
			-- stale payload → next clear sequence. With enabled=false set first,
			-- the deferred publish's `if not AS.enabled then return` short-circuit
			-- (L18373-area) fires correctly, and the cancelled debounce can't sneak
			-- a final write past the cleared payload.
			AS.enabled = false
			if AS.debounceHandle then pcall(task.cancel, AS.debounceHandle); AS.debounceHandle = nil end
			-- V4.3.174: if we ever published this session, send a cleared payload so peers
			-- wipe our proxy on their next poll (instead of waiting up to 300 s for worker
			-- TTL expiry). Fires AFTER AS.enabled=false (V4.3.540 reorder) so any in-
			-- flight debounce shortcircuits cleanly first.
			if AS.userActed then
				AS.clearToken = (AS.clearToken or 0) + 1
				local _tok = AS.clearToken
				task.spawn(function()
					if AS.clearToken ~= _tok then return end -- cancelled by rapid toggle-ON
					_publishClearedSync()
				end)
			end
			AS.userActed = false
			if AS.pollHandle then pcall(task.cancel, AS.pollHandle); AS.pollHandle = nil end
			if AS.heartbeatHandle then pcall(task.cancel, AS.heartbeatHandle); AS.heartbeatHandle = nil end
			local _peers = {}
			for uid in pairs(AS.syncedPeers) do _peers[#_peers+1] = uid end
			for _, uid in ipairs(_peers) do _syncRemovePeer(uid, true) end  -- V4.5.24 Fix: force - toggling sync OFF must clear even a manually-selected peer (old no-force call hit the SelectPlayer keep-alive guard at _syncRemovePeer and left the entry + its CharacterAdded conn alive, re-applying stale bundleData on every respawn)
			AS.lastPublishedHash = nil
			AS.pollCursor = nil
			AS.nextFullPoll = nil
		end
	end

	function Function.StringTo(String, Type)
		local Split = string.split(String, ",")

		if Type == "CFrame" then
			-- V4.3.509 Fix 5: nil-safe - any tonumber() returning nil from a malformed
			-- string would throw inside CFrame.new. Return nil so callers can fall back.
			local nums = {}
			for i = 1, 12 do
				nums[i] = tonumber(Split[i])
				if not nums[i] then return nil end
			end
			return CFrame.new(
				nums[1], nums[2], nums[3],
				nums[4], nums[5], nums[6],
				nums[7], nums[8], nums[9],
				nums[10], nums[11], nums[12]
			)
		elseif Type == "RGB" then
			local r, g, b = tonumber(Split[1]), tonumber(Split[2]), tonumber(Split[3])
			if not (r and g and b) then return nil end
			return Color3.fromRGB(r, g, b)
		elseif Type == "Vector3" then
			local x, y, z = tonumber(Split[1]), tonumber(Split[2]), tonumber(Split[3])
			if not (x and y and z) then return nil end
			return Vector3.new(x, y, z)
		end
	end

	-- V4.3.168.8: skip-if-unchanged cache. MeshEditButton is called every GUIUpdate (see Changelog for full rationale)
	local _lastMeshEditName = nil
	function Function.MeshEditButton(Name)
		if not PlayerData[SelectPlayer] then return end
		if Name == _lastMeshEditName then return end
		_lastMeshEditName = Name

		if not GUIObject.PropertyListFrame then return end  -- [V3 MERGE FIX] old-GUI property-list container not built in V3; nil-guard the unguarded :GetChildren below.
		for _, v in ipairs(GUIObject.PropertyListFrame:GetChildren()) do
			if v:IsA(("Frame")) then
				v:Destroy()
			end
		end
		for _, v in pairs(MeshEditConnect) do
			v:Disconnect()
			local idx = table.find(AllConnect, v)
			if idx then table.remove(AllConnect, idx) end
		end

		MeshEditConnect = {}

		local PlayerPartList = PlayerData[SelectPlayer]["PartList"]
		local MeshDetail = PlayerPartList[Name]

		if MeshDetail then
			setmetatable(MeshDetail, MetaClothes)

			if MeshDetail then
				if MeshDetail["Scale"] == "CockScale" then
					local Button = Function.ButtonCreate("CockScale", GUIObject.PropertyListFrame, true, {Color = Color3.fromRGB(93, 93, 93), Text = "CockScale"})
					local Textbox = Button:FindFirstChildOfClass("TextBox")
					-- V4.3.296: nil-guard - SelectPlayer's PD may not exist if this rebuilds
					-- between PlayerData rebuild + repopulate (rare but reachable).
					local _pdInit = PlayerData[SelectPlayer]
					Textbox.Text = tostring((_pdInit and _pdInit.CockScale) or 1)

					local TextboxConnect = Textbox.FocusLost:Connect(function()
						-- V4.3.296: nil-guard the live PD lookup - target player can leave mid-edit.
						local _pd = PlayerData[SelectPlayer]
						if not _pd then return end
						-- V4.3.280: skip nil/non-numeric writes; clamp to bundle-path range [0.1, 10].
						local _n = tonumber(Textbox.Text)
						if _n and _n == _n and math.abs(_n) ~= math.huge then
							_pd.CockScale = math.clamp(_n, 0.1, 10)
						else
							Textbox.Text = tostring(_pd.CockScale or 1)
						end
					end)

					table.insert(MeshEditConnect, TextboxConnect)
					table.insert(AllConnect, TextboxConnect)
				end
				for _, PropertyName in pairs(EditableProperty) do
					local Value = MeshDetail[PropertyName]
					if Value == nil then Value = "" end
					local Button = Function.ButtonCreate(PropertyName, GUIObject.PropertyListFrame, true, {Color = Color3.fromRGB(93, 93, 93), Text = PropertyName})
					local Textbox = Button:FindFirstChildOfClass("TextBox")

					if PropertyName == "Color" then
						local Split = string.split(tostring(Value.Color), ",")

						if tonumber(Split[1]) and tonumber(Split[2]) and tonumber(Split[3]) then
							Textbox.Text = math.round(Split[1]*255)..","..math.round(Split[2]*255)..","..math.round(Split[3]*255)
							Textbox.TextColor3 = Value.Color
							Textbox.TextStrokeTransparency = 0
							Textbox.TextStrokeColor3 = Color3.new(1,1,1)
						else
							Textbox.Text = ""
						end
					else
						Textbox.Text = tostring(Value)
					end

					local TextboxConnect = Textbox.FocusLost:Connect(function()
						-- V4.3.280: every PartList write now sanity-gated. Pre-fix, empty / "abc" / "1,,3"
						-- went straight to PartList - `Function.StringTo("nil,nil,nil","Vector3")` returns
						-- `Vector3.new(nil,nil,nil)` which errors immediately, and `tonumber("")` writes
						-- `nil` which then crashed `Textbox.Text = PlayerData[…]` on next GUI rebuild.
						-- Local input now passes through the same gate as foreign-bundle data (V4.3.279).
						local _pl = PlayerData[SelectPlayer] and PlayerData[SelectPlayer]["PartList"]
						local _entry = _pl and _pl[Name]
						if not _entry then return end

						local function _safeVec3FromStr(s)
							local parts = string.split(s, ",")
							if #parts ~= 3 then return nil end
							local x, y, z = tonumber(parts[1]), tonumber(parts[2]), tonumber(parts[3])
							if not x or not y or not z then return nil end
							if x ~= x or y ~= y or z ~= z then return nil end  -- NaN
							if math.abs(x) == math.huge or math.abs(y) == math.huge or math.abs(z) == math.huge then return nil end
							return Vector3.new(x, y, z)
						end

						if PropertyName == "Size" then
							local _v = _safeVec3FromStr(Textbox.Text)
							if _v then
								local _safe, _ok = Function.SanitizeMeshEditValue("Size", _v)
								if _ok then _entry[PropertyName] = _safe else Textbox.Text = tostring(_entry[PropertyName] or "") end
							else
								Textbox.Text = tostring(_entry[PropertyName] or "")
							end
						elseif PropertyName == "Offset" or PropertyName == "Rotation" then
							local _v = _safeVec3FromStr(Textbox.Text)
							if _v then _entry[PropertyName] = _v
							else Textbox.Text = tostring(_entry[PropertyName] or "") end
						elseif PropertyName == "TextureId" then
							local _safe, _ok = Function.SanitizeMeshEditValue("TextureId", Textbox.Text)
							if _ok then _entry[PropertyName] = _safe
							else Textbox.Text = tostring(_entry[PropertyName] or "") end
						elseif PropertyName == "Color" then
							local RGB = Function.StringTo(Textbox.Text, "RGB")
							if typeof(RGB) == "Color3" and _entry[PropertyName] then
								_entry[PropertyName].Color = RGB
								Textbox.TextColor3 = RGB
							end
						else
							local _n = tonumber(Textbox.Text)
							if _n and _n == _n and math.abs(_n) ~= math.huge then
								_entry[PropertyName] = _n
							else
								Textbox.Text = tostring(_entry[PropertyName] or "")
							end
						end
						-- V4.3.171: trigger re-render so the textbox edit applies immediately.
						if System.hotSwap then System.hotSwap() end
					end)

					table.insert(MeshEditConnect, TextboxConnect)
					table.insert(AllConnect, TextboxConnect)
				end
			end
		end
	end




	function Function.DragUpdate()
		if GUIObject.hardcoreGroup.Visible == true and GUIObject.hardcoreGroup.GroupTransparency < 1 then
			local pos = UIS:GetMouseLocation()

			GUIObject.hardcoreGroup.Position = UDim2.fromOffset(pos.X,pos.Y)
		end
	end

	function Function.FindInvisibleRayParts(ray, blackListSet)
		local targets, filtered = {}, {}
		if blackListSet then table.insert(targets, blackListSet) end
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		while true do
			params.FilterDescendantsInstances = targets
			local hit = workspace:Raycast(ray.Origin, ray.Direction * 999, params)
			local part = hit and hit.Instance
			if not part then break end
			table.insert(targets, part)
			if part.Transparency > 0 then table.insert(filtered, part) end
		end
		return filtered
	end

	function Function.IsCharacter(Model)
		-- M-4 fix: added R15 limb names - was R6-only, so R15-only NPCs without a Head would return falsy
		-- and ClickExecute / character detection would silently fail on them.
		return Model and (
			Model:FindFirstChild("Torso")      or -- R6 torso
			Model:FindFirstChild("UpperTorso") or -- R15 torso
			Model:FindFirstChild("Head")       or -- both rigs
			Model:FindFirstChild("Right Arm")  or -- R6
			Model:FindFirstChild("Left Arm")   or -- R6
			Model:FindFirstChild("Right Leg")  or -- R6
			Model:FindFirstChild("Left Leg")   or -- R6
			Model:FindFirstChild("RightUpperArm") or -- R15
			Model:FindFirstChild("LeftUpperArm")     -- R15
		)
	end



	function Function.FallenPartCheck(Object)
		if Object:IsA("BasePart") then
			return Object.Position.Y < game.Workspace.FallenPartsDestroyHeight
		end
		return false
	end

	function Function.IsParentNil(Object)
		if Object then
			local Target = Object

			while Target and Target.Parent ~= nil and Target ~= game do
				Target = Target.Parent
			end

			if Target ~= game then
				return true
			end
		end
		return false
	end

	function Function.GetMiddleNumber(Numbers)
		table.sort(Numbers, function(a,b)
			return a < b
		end)

		local Count = #Numbers

		if Count % 2 == 0 then
			local middleIndex1 = Count / 2
			local middleIndex2 = middleIndex1 + 1
			local middleNumber = (Numbers[middleIndex1] + Numbers[middleIndex2]) / 2

			return middleNumber
		else
			local middleIndex = math.ceil(Count / 2)
			local middleNumber = Numbers[middleIndex]

			return middleNumber
		end
	end




	local loadDataSuccess, _loadDataErr = pcall(function()
		if RS:IsClient() and not RS:IsStudio() then
			local function toJSON(t)
				for i, v in pairs(t) do
					if typeof(v) == "table" then
						toJSON(v)
					else
						t[i] = Function.convertToJSON(v)
					end
				end
			end
			local function fromJSON(t)
				for i, v in pairs(t) do
					local value,original = Function.convertFromJSON(v)
					t[i] = value
					if typeof(v) == "table" and original then
						fromJSON(v)
					end
				end
			end

			if env.makefolder and env.isfolder and env.readfile and env.writefile and env.delfile and env.listfiles and env.isfile then
				-- V4.3.515 Fix 7: pcall-wrap to match sibling sites.
				if not env.isfolder("RClothesLerp") then
					pcall(env.makefolder, "RClothesLerp")
				end
				if not env.isfolder("RClothesLerp/Bundles") then
					pcall(env.makefolder, "RClothesLerp/Bundles")
				end
				if env.isfile("RClothesLerp/Settings.json") then
					local _okR, _raw = pcall(env.readfile, "RClothesLerp/Settings.json")
					local _okD, settings
					if _okR then _okD, settings = pcall(HS.JSONDecode, HS, _raw) end
					if not _okD or type(settings) ~= "table" then settings = {} end
					-- V4.3.218: snapshot raw autoExecute before convertFromJSON mangles it
					-- (toggle handler writes raw boolean, save handler wraps via convertToJSON
					-- - asymmetric, so unwrap accordingly).
					local _rawAutoExec = settings.autoExecute
					-- V4.3.508: mirror autoExecute snapshot for telemetry keys - convertFromJSON
					-- mangles raw bool/string values; toggle handler writes raw, restore must un-wrap.
					local _rawTelemEnabled = settings.telemEnabled
					local _rawTelemInstallId = settings.telemInstallId
					for i, v in pairs(settings) do
						local _okCv, _cv = pcall(Function.convertFromJSON, v)
						if _okCv then settings[i] = _cv
						else warn("[RoClothes] V4.3.575 convertFromJSON skipped key", tostring(i), "err:", tostring(_cv)) end
					end
					if type(_rawAutoExec) == "boolean" then settings.autoExecute = _rawAutoExec end
					if type(_rawTelemEnabled) == "boolean" then settings.telemEnabled = _rawTelemEnabled end
					if type(_rawTelemInstallId) == "string" then settings.telemInstallId = _rawTelemInstallId end
					loadupBundle = settings.loadupBundle or ""
					loadupExecute = settings.loadupExecute
					loadupClosed = settings.loadupClosed or false
					loadupFPerson = settings.loadupFPerson or 0
					-- V4.3.217: restore AutoExecute from settings (was not persisted before).
					-- V4.3.521 Fix 6: restore-side mirror of Fix 5. AutoExecute is local-install only;
					-- writing to SelectPlayer at restore time would land on whoever was selected when
					-- restore ran (normally Player.Name at init, but fragile if init order changes).
					if settings.autoExecute ~= nil and PlayerData[Player.Name] then
						PlayerData[Player.Name].AutoExecute = settings.autoExecute
					end
					-- V4.3.507: restore telemetry opt-in state. Default OFF if missing -
					-- existing users never get auto-opted-in by a script update.
					-- V4.3.510 Fix 5: normalize to PlayerData[Player.Name]. At restore time
					-- SelectPlayer == Player.Name (init-order coincidence), but the keys are
					-- per-local-install so the correct reference is the local Player. Matches
					-- the saveButton/HUD/lazy-getter pattern.
					if PlayerData[Player.Name] then
						if type(settings.telemEnabled) == "boolean" then
							PlayerData[Player.Name]._telemEnabled = settings.telemEnabled
						end
						if type(settings.telemInstallId) == "string" and #settings.telemInstallId > 0 then
							-- V4.3.508: don't clobber if lazy-getter already populated (race protection).
							if not (type(PlayerData[Player.Name]._telemInstallId) == "string" and #PlayerData[Player.Name]._telemInstallId > 0) then
								PlayerData[Player.Name]._telemInstallId = settings.telemInstallId
							end
							if not (type(_DIAG_INSTALL_ID) == "string" and #_DIAG_INSTALL_ID > 0) then
								_DIAG_INSTALL_ID = settings.telemInstallId  -- populate file-scope for Phase 1 disk logs
							end
						end
					end
					-- V4.3.576: keybinds persist as plain KeyCode name strings ("Insert"). Reconstruct via
					-- Enum.KeyCode[name] (pcall-guarded). Falls back to a real EnumItem for any legacy save;
					-- ignores the old broken {EnumType="de",...} tables (they just restore to nothing -> default).
					local function _kbFromSaved(v, cur)
						if type(v) == "string" then
							local _ok, _e = pcall(function() return Enum.KeyCode[v] end)
							if _ok and typeof(_e) == "EnumItem" then return _e end
						elseif typeof(v) == "EnumItem" then return v end
						return cur
					end
					KEYBIND   = _kbFromSaved(settings.KEYBIND,   KEYBIND)
					hpKEYBIND = _kbFromSaved(settings.hpKEYBIND, hpKEYBIND)
					dpKEYBIND = _kbFromSaved(settings.dpKEYBIND, dpKEYBIND)
					nkKEYBIND = _kbFromSaved(settings.nkKEYBIND, nkKEYBIND)

					loadupBreastsStiffness = settings.loadupBreastsStiffness or 10
					loadupBreastsDamping = settings.loadupBreastsDamping or 0.207
					loadupButtsStiffness = settings.loadupButtsStiffness or 10
					loadupButtsDamping = settings.loadupButtsDamping or 0.1

					-- V4.3.1: SpringConfigs override RE-ENABLED (now safe). (see Changelog for full rationale)
					System.Physics.SpringConfigs.Breasts.Speed   = loadupBreastsStiffness
					System.Physics.SpringConfigs.Breasts.Damper  = loadupBreastsDamping
					System.Physics.SpringConfigs.Buttocks.Speed  = loadupButtsStiffness
					System.Physics.SpringConfigs.Buttocks.Damper = loadupButtsDamping
					if PlayerData[Player.Name] then
						PlayerData[Player.Name].BreastsStiffness = loadupBreastsStiffness
						PlayerData[Player.Name].BreastsDamping   = loadupBreastsDamping
						PlayerData[Player.Name].ButtsStiffness   = loadupButtsStiffness
						PlayerData[Player.Name].ButtsDamping     = loadupButtsDamping
					end
				end
				if env.isfile("RClothesLerp/MobileButtonPlacement.json") then
					local _okR2, _raw2 = pcall(env.readfile, "RClothesLerp/MobileButtonPlacement.json")
					local _okD2, settings
					if _okR2 then _okD2, settings = pcall(HS.JSONDecode, HS, _raw2) end
					if not _okD2 or type(settings) ~= "table" then settings = {} end
					for i, v in pairs(settings) do
						local _okCv, _cv = pcall(Function.convertFromJSON, v)
						if _okCv then settings[i] = _cv
						else warn("[RoClothes] V4.3.575 convertFromJSON skipped key", tostring(i), "err:", tostring(_cv)) end
					end
					task.delay(0,function()
						if settings.HealPos then GUIObject.ImageHeal.Position = settings.HealPos end
						if settings.TearPos then GUIObject.ImageTear.Position = settings.TearPos end
					end)
				end
				-- V4.3.475: one-shot migration for V4.3.473- BundleLoader.json corruption.
				-- The pre-V4.3.474 file-by-file loader unconditionally wrote Personal=true
				-- into the cache for every bundle, reclassifying community bundles imported
				-- with Personal=false as personal. V4.3.474 fixed the write path but couldn't
				-- unstick already-corrupted caches: the quick-load reads stale data, V4.3.474's
				-- conditional `if b.Personal == nil` sees true (not nil) and leaves it. Detect
				-- disagreement by cross-checking BundleLoader.json against per-file source. If
				-- any bundle's Personal flag differs, delete the cache so the quick-load falls
				-- through to the rebuild branch which writes a correct cache from per-file.
				-- After the first migration the rebuild produces a correct cache; on subsequent
				-- boots this check is a no-op (no disagreement detected). Migration cost: one
				-- extra file walk on first V4.3.475 boot per affected user.
				-- V4.3.477: gate the entire migration on env.listfiles being callable.
				-- Pre-fix the `_files = env.listfiles("RClothesLerp/Bundles") or {}` line
				-- would throw "attempt to call a nil value" on executors that expose
				-- isfile/readfile/delfile but not listfiles - propagating out of the
				-- surrounding loadDataSuccess pcall and killing settings load entirely.
				if env.isfile("RClothesLerp/BundleLoader.json") and env.listfiles then
					local _cOk, _cRaw = pcall(env.readfile, "RClothesLerp/BundleLoader.json")
					local _cDOk, _cache = false, nil
					if _cOk then _cDOk, _cache = pcall(HS.JSONDecode, HS, _cRaw) end
					if _cDOk and type(_cache) == "table" then
						local _filesOk, _files = pcall(env.listfiles, "RClothesLerp/Bundles")
						if not _filesOk or type(_files) ~= "table" then _files = {} end
						local _disagree = false
						for _, _path in ipairs(_files) do
							if env.isfile(_path) then
								local _okR, _raw = pcall(env.readfile, _path)
								if _okR then
									local _okD, _b = pcall(HS.JSONDecode, HS, _raw)
									if _okD and type(_b) == "table" then
										local _name = _b.BundleName
										if _name and _cache[_name] then
											-- Normalize nil/missing to true (the default we assign on load) for fair comparison
											local _cP = _cache[_name].Personal; if _cP == nil then _cP = true end
											local _fP = _b.Personal;            if _fP == nil then _fP = true end
											if _cP ~= _fP then _disagree = true; break end
										end
									end
								end
							end
						end
						if _disagree then
							warn("[RoClothes] V4.3.475 migration: BundleLoader.json has stale Personal flags vs per-file source - deleting cache to force clean rebuild.")
							pcall(env.delfile, "RClothesLerp/BundleLoader.json")
						end
					end
				end
				local _bundleLoaderUsed = false
				if env.isfile("RClothesLerp/BundleLoader.json") then
					local _okRBL, _rawBL = pcall(env.readfile, "RClothesLerp/BundleLoader.json")
					local _okDBL, decode
					if _okRBL then _okDBL, decode = pcall(HS.JSONDecode, HS, _rawBL) end
					if type(decode) ~= "table" then
						warn("[RoClothes] BundleLoader.json is corrupt or empty - skipping quick-load.")
					else
						_bundleLoaderUsed = true
						fromJSON(decode)

					local bundleAmount = 0
					for name, bundle in pairs(decode) do
						bundleAmount += 1
						bundle["BundleName"] = nil
						-- V4.3.446: only force Personal=true when the field is missing.
						-- Pre-fix the unconditional assignment reclassified community
						-- bundles cached into BundleLoader.json as personal - wrong tab on
						-- next session.
						if bundle.Personal == nil then bundle.Personal = true end
						Bundle[name] = bundle
					end
					task.spawn(function() -- compile overtime --
						local timeOut = 1000
						local amount = 0
						-- V4.3.503: some executors throw on missing folder. pcall + ipairs.
						local _lfOk, filesFound = pcall(env.listfiles, "RClothesLerp/Bundles")
						if not _lfOk or type(filesFound) ~= "table" then filesFound = {} end
						if #filesFound <= 0 then
							repeat
								task.wait()
								local _lfOk2, _ff = pcall(env.listfiles, "RClothesLerp/Bundles")
								filesFound = (_lfOk2 and type(_ff) == "table") and _ff or {}
								timeOut -= 1
							until timeOut <= 0 or #filesFound > 0
						end
						local tab = {}
						local _anyLoaded = false
						for i, v in ipairs(filesFound) do
							-- V4.3.521 Fix 9: normalize path for executors that return leaf-only / backslash forms.
							local _normp = _normalizeBundlePath(v)
							if _normp then
								local _okRB, _rawB = pcall(env.readfile, _normp)
								if not _okRB then continue end
								local _okDB, b = pcall(HS.JSONDecode, HS, _rawB)
								if not _okDB or type(b) ~= "table" then continue end
								_anyLoaded = true
								-- V4.3.520 Fix 15: skip entries with missing BundleName. Pre-fix, `t[nil] = b`
								-- threw inside the spawn and killed the entire compile silently → one corrupt
								-- bundle file silently broke loading of ALL bundles.
								local storedName = b.BundleName
								if not storedName or type(storedName) ~= "string" or #storedName == 0 then
									continue
								end
								b["BundleName"] = nil

								fromJSON(b)

								-- V4.3.474: respect stored Personal value. Pre-fix `b.Personal = true`
								-- unconditional override reclassified community bundles (saved to disk
								-- with Personal=false from the Submit Community / import paths) as
								-- personal on every load, then wrote them back to BundleLoader.json
								-- with the wrong flag - permanent reclassification across sessions.
								-- V4.3.446 fixed the BundleLoader.json quick-load path (L15353); this
								-- mirrors that fix for the 3 file-by-file load paths (here, L15431,
								-- L15489) which run every session and rewrite BundleLoader.json.
								if b.Personal == nil then b.Personal = true end
								Bundle[storedName] = b
								local asset = {}
								local function transferTable(n,isTable)
									local newTable = {}
									for i, v in pairs(n) do
										if isTable then
											if typeof(v) == "table" then
												newTable[i] = transferTable(v,true)
											else
												newTable[i] = v
											end
										else
											if typeof(v) == "table" then
												asset[i] = transferTable(v,true)
											else
												asset[i] = v
											end
										end
									end
									return newTable
								end
								transferTable(b)
								tab[storedName] = asset
							end
						end

						-- V4.3.526 Fix 3: gate cache write on _anyLoaded, not just #filesFound > 0.
						-- V4.3.521 Fix 9 partially addressed Aki's Solara bundle bug but missed this
						-- branch - if listfiles returns paths none of the normalize fallbacks accept,
						-- tab stays empty and the atomic write wipes the cache.
						if #filesFound > 0 and _anyLoaded then
							toJSON(tab)
							-- V4.3.504: atomic write (see _atomicWriteJSON at file scope).
							_atomicWriteJSON("RClothesLerp/BundleLoader.json", tab)
						elseif #filesFound > 0 and not _anyLoaded then
							-- listfiles returned paths but none could be normalized - DO NOT wipe cache.
							_diagPublicCall("bundle.listfiles_path_unrecognized", { sampleCount = #filesFound })
						-- V4.3.521 Fix 9: only nuke BundleLoader.json if files were found AND none loaded
						-- (i.e. all paths failed normalization → executor path-format mismatch). Pre-fix
						-- the empty-filesFound branch unconditionally deleted the cache, wiping bundles
						-- on every boot for Solara-style executors that return leaf-only names.
						elseif not _anyLoaded and env.isfile("RClothesLerp/BundleLoader.json") and #filesFound == 0 then
							-- V4.3.515 Fix 7: pcall-wrap delfile to match sibling sites.
							-- BundleLoader.json exists but listfiles returned empty - clean up the stale loader.
							pcall(env.delfile, "RClothesLerp/BundleLoader.json")
						end
					end)
					end -- close nil-check guard
				end
				if not _bundleLoaderUsed then
					warn("Quick loader was not detected, using alternative method.")
					-- V4.3.503: pcall guard + ipairs for executor compat.
					local _lfOk, filesFound = pcall(env.listfiles, "RClothesLerp/Bundles")
					if not _lfOk or type(filesFound) ~= "table" then filesFound = {} end
					local t = {}
					local _anyLoaded = false -- V4.3.526 Fix 3: track normalized-and-loaded count
					for i, v in ipairs(filesFound) do
						-- V4.3.521 Fix 9: normalize path for executors that return leaf-only / backslash forms.
						local _normp = _normalizeBundlePath(v)
						if _normp then
							local _okRB, _rawB = pcall(env.readfile, _normp)
								if not _okRB then continue end
								local _okDB, b = pcall(HS.JSONDecode, HS, _rawB)
								if not _okDB or type(b) ~= "table" then continue end
							-- V4.3.520 Fix 15: skip entries with missing BundleName (sibling site).
							local storedName = b.BundleName
							if not storedName or type(storedName) ~= "string" or #storedName == 0 then
								continue
							end
							b["BundleName"] = nil

							fromJSON(b)
							-- V4.3.474: respect stored Personal value (see L15379 fix comment)
							if b.Personal == nil then b.Personal = true end
							Bundle[storedName] = b

							local asset = {}
							local function transferTable(n,isTable)
								local newTable = {}
								for i, v in pairs(n) do
									if isTable then
										if typeof(v) == "table" then
											newTable[i] = transferTable(v,true)
										else
											newTable[i] = v
										end
									else
										if typeof(v) == "table" then
											asset[i] = transferTable(v,true)
										else
											asset[i] = v
										end
									end
								end
								return newTable
							end
							transferTable(b)
							t[storedName] = asset
							_anyLoaded = true -- V4.3.526 Fix 3
						end
					end

					local failed = false
					-- V4.3.526 Fix 3: gate cache write on _anyLoaded to avoid wiping cache when
					-- listfiles returns paths none of the normalize fallbacks accept.
					if #filesFound > 0 and _anyLoaded then
						-- V4.3.503: pcall-wrap encode+write to match peer paths (L16449, L16565 are
						-- already inside spawn pcalls; this alt-method branch runs in the main flow).
						local _wbOk, _wbErr = pcall(function()
							toJSON(t)
							-- V4.3.504: atomic write.
							_atomicWriteJSON("RClothesLerp/BundleLoader.json", t)
						end)
						if not _wbOk then
							warn("[RoClothes] alt-method BundleLoader.json write failed: " .. tostring(_wbErr))
							failed = true
						end
					elseif #filesFound > 0 and not _anyLoaded then
						_diagPublicCall("bundle.listfiles_path_unrecognized", { sampleCount = #filesFound })
						failed = true
					else
						failed = true
						warn("No files were found.")
					end
					task.spawn(function() -- compile overtime --
						local timeOut = 500
						local amount = 0
						-- V4.3.503: pcall guard + ipairs for executor compat.
						local _lfOk, filesFound = pcall(env.listfiles, "RClothesLerp/Bundles")
						if not _lfOk or type(filesFound) ~= "table" then filesFound = {} end
						if #filesFound <= 0 then
							repeat
								task.wait()
								local _lfOk2, _ff = pcall(env.listfiles, "RClothesLerp/Bundles")
								filesFound = (_lfOk2 and type(_ff) == "table") and _ff or {}
								timeOut -= 1
							until timeOut <= 0 or #filesFound > 0
						end
						local t = {}
						local _anyLoaded = false -- V4.3.526 Fix 3
						for i, v in ipairs(filesFound) do
							-- V4.3.521 Fix 9: normalize path for executors that return leaf-only / backslash forms.
							local _normp = _normalizeBundlePath(v)
							if _normp then
								local _okRB, _rawB = pcall(env.readfile, _normp)
								if not _okRB then continue end
								local _okDB, b = pcall(HS.JSONDecode, HS, _rawB)
								if not _okDB or type(b) ~= "table" then continue end
								-- V4.3.520 Fix 15: skip entries with missing BundleName (sibling site).
								local storedName = b.BundleName
								if not storedName or type(storedName) ~= "string" or #storedName == 0 then
									continue
								end
								b["BundleName"] = nil

								fromJSON(b)
								-- V4.3.474: respect stored Personal value (see L15379 fix comment)
								if b.Personal == nil then b.Personal = true end
								Bundle[storedName] = b

								local asset = {}
								local function transferTable(n,isTable)
									local newTable = {}
									for i, v in pairs(n) do
										if isTable then
											if typeof(v) == "table" then
												newTable[i] = transferTable(v,true)
											else
												newTable[i] = v
											end
										else
											if typeof(v) == "table" then
												asset[i] = transferTable(v,true)
											else
												asset[i] = v
											end
										end
									end
									return newTable
								end
								transferTable(b)
								t[storedName] = asset
								_anyLoaded = true -- V4.3.526 Fix 3
							end
						end

						-- V4.3.526 Fix 3: gate cache write on _anyLoaded to prevent overwriting
						-- the cache with {} when listfiles paths fail normalization.
						if #filesFound > 0 and _anyLoaded then
							toJSON(t)
							-- V4.3.504: atomic write.
							_atomicWriteJSON("RClothesLerp/BundleLoader.json", t)
						elseif #filesFound > 0 and not _anyLoaded then
							_diagPublicCall("bundle.listfiles_path_unrecognized", { sampleCount = #filesFound })
						end
					end)
				end
			else
