	for _, v in pairs(PS:GetPlayers()) do
		Function.CharacterConnection(v)
	end

	-- M-1 fix: give PS.PlayerAdded connection to GlobalMaid so it is cleaned up on session end.
	-- Previously the return value was discarded, causing a permanent leaked listener on re-execution
	-- (each re-run stacked another PS.PlayerAdded handler that called CharacterConnection again).
	GlobalMaid:Give(PS.PlayerAdded:Connect(function(v)
		-- V4.3.451: defensive cleanup for rejoin under same username. If the prior
		-- PlayerRemoving handler didn't fully clear PlayerData[v.Name] (e.g.,
		-- pcall-swallowed throw at L13786), or if PlayerAdded fires BEFORE
		-- PlayerRemoving for the leaver (rare engine ordering), the stale entry
		-- would persist and CharacterConnection's idempotent re-init could mask
		-- it. Drain ExecutionMaid + nil out before re-creating.
		local _stale = PlayerData[v.Name]
		if _stale then
			if _stale.ExecutionMaid then pcall(function() _stale.ExecutionMaid:DoCleaning() end) end
			PlayerData[v.Name] = nil
		end
		Function.CharacterConnection(v)
	end))

	local tap = false
	local cd = false

	local hardcoreGUITween
	local repairTween
	local function setUpHPBinds()
		local function HealFunction()
			if cd == false then
				local LP = game:GetService("Players").LocalPlayer
				local data = PlayerData[LP.Name]
				if LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") and data then
					-- V4.3.515 Fix 2: hoist numeric coercion - TopHP/BottomHP are TextBox strings.
					local _top = tonumber(data.TopHP) or 0
					local _bot = tonumber(data.BottomHP) or 0
					-- V4.5.24 Fix: Saved*HP can be nil/string if the heal key fires before CharacterExecute
					-- seeded them (defaults are 0 but peer/partial applies can carry nil). Coerce at entry
					-- so the `nil < number` compares and Saved*HP divides below can never throw.
					-- (DamageFunction got its (x or 0) sibling at V4.3.520/521; HealFunction had none.)
					data["SavedTopHP"] = tonumber(data["SavedTopHP"]) or 0
					data["SavedBottomHP"] = tonumber(data["SavedBottomHP"]) or 0
					if data["HardcoreHP"] == true and (data["TopHP"] ~= "" or data["BottomHP"] ~= "") then
						if data["Healing"] == false then

							GUIObject.hardcoreGroup.Visible = true
							if hardcoreGUITween then pcall(function() hardcoreGUITween:Cancel(); hardcoreGUITween:Destroy() end) end
							hardcoreGUITween = TS:Create(GUIObject.hardcoreGroup,TweenInfo.new(.1,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{GroupTransparency = 0})
							hardcoreGUITween:Play()

							task.delay(0,function()
								Function.DragUpdate()
							end)
							data["Healing"] = true
							cd = true
							tap = true
							task.wait(.3)
							cd = false
							tap = false
							-- V4.3.515 Fix 2: use hoisted _top/_bot numeric values (was raw string compare).
							if data["Healing"] == true and (data["TopHP"] ~= "" and data["SavedTopHP"] < _top
								or data["BottomHP"] ~= "" and data["SavedBottomHP"] < _bot) then
								--local healTime = 0
								local timeAccumulated = 0
								local totalTime = 0
								GUIObject.repairDisplay.Color = ColorSequence.new(
									{ColorSequenceKeypoint.new(0,Color3.new(1,1,1)),
										ColorSequenceKeypoint.new(0.00001,Color3.new(0, 0, 0)),
										ColorSequenceKeypoint.new(1,Color3.new(0, 0, 0))}
								)
								GUIObject.repairBar.Size = UDim2.fromScale(.2,.2)
								GUIObject.repairBar.ImageTransparency = 1
								GUIObject.repairBar.Visible = true
								if repairTween then pcall(function() repairTween:Cancel(); repairTween:Destroy() end) end
								repairTween = TS:Create(GUIObject.repairBar,TweenInfo.new(.3,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),{Size = UDim2.fromScale(.5,.5),ImageTransparency=.2})
								repairTween:Play()
								-- V4.3.517 Fix 3: re-read inside loop. TextBox can mutate mid-heal; the V4.3.515
								-- hoisted _top/_bot would otherwise snapshot the initial cap and miss the edit.
								repeat
									local _topL = tonumber(data.TopHP) or 0
									local _botL = tonumber(data.BottomHP) or 0
									GUIObject.repairBar.Visible = true
									-- V4.3.515 Fix 2: numeric compare against _top/_bot (was string compare).
									if (not tonumber(data["TopHP"]) or data["SavedTopHP"] >= _topL) and
										(not tonumber(data["BottomHP"]) or data["SavedBottomHP"] >= _botL) then
										data["Healing"] = false
									end
									local focus
									local timeRequired = 1  -- V4.3.567 H-2: init=1 (was nil); all branches can skip when both HP fields are cleared -> timeAccumulated/timeRequired divided nil (DamageFunction L20796 already =1)
									-- V4.3.515 Fix 2: numeric divisions guarded via _top/_bot (math.max for div-by-zero safety).
									if data["BottomHP"] ~= "" and (data["TopHP"] == ""
										or data["SavedBottomHP"] <= 0 or data["SavedTopHP"]/math.max(_topL,1) >= data["SavedBottomHP"]/math.max(_botL,1)) then
										focus = "BottomHP"
										local fullTime = math.max(_botL/50,.5)
										if data["SavedBottomHP"] <= 0 then
											timeRequired = fullTime
										else
											timeRequired = math.max(fullTime*.8 + (0 - fullTime*.8) * (data["SavedBottomHP"]/math.max(_botL,1)),.25)
										end
										--timeRequired = math.max((data["BottomHP"]/math.max(data["SavedBottomHP"],1))*0.04,.5)
									elseif data["TopHP"] ~= "" and (data["BottomHP"] == ""
										or data["SavedTopHP"] <= 0 or data["SavedTopHP"]/math.max(_topL,1) < data["SavedBottomHP"]/math.max(_botL,1)) then
										focus = "TopHP"
										local fullTime = math.max(_topL/50,.5)
										if data["SavedTopHP"] <= 0 then
											timeRequired = fullTime
										else
											timeRequired = math.max(fullTime*.8 + (0 - fullTime*.8) * (data["SavedTopHP"]/math.max(_topL,1)),.25)
										end
										--timeRequired = math.max((data["TopHP"]/math.max(data["SavedTopHP"],1))*0.04,.5)
									end
									-- V4.3.515 Fix 2: linked-heal branch using hoisted numerics.
									if data["TopHP"] ~= "" and data["BottomHP"] ~= "" and data["LinkedHeal"] == true then
										focus = "Both"
										local fullTime
										local timeBottom = math.max(_botL/50,.5)
										local timeTop = math.max(_topL/50,.5)
										if timeBottom < timeTop then
											fullTime = timeTop
											if data["SavedTopHP"] <= 0 or data["SavedBottomHP"] <= 0 then
												timeRequired = fullTime
											else
												timeRequired = math.max(fullTime*.8 + (0 - fullTime*.8) * (data["SavedTopHP"]/math.max(_topL,1)),.25)
											end
										else
											fullTime = timeBottom
											if data["SavedTopHP"] <= 0 or data["SavedBottomHP"] <= 0 then
												timeRequired = fullTime
											else
												timeRequired = math.max(fullTime*.8 + (0 - fullTime*.8) * (data["SavedBottomHP"]/math.max(_botL,1)),.25)
											end
										end
									end
									local t = task.wait()
									timeAccumulated += t
									totalTime += t
									GUIObject.repairDisplay.Offset = Vector2.new(timeAccumulated/timeRequired,0)
									if timeAccumulated >= timeRequired then
										timeAccumulated = 0
										-- V4.3.526 Fix 5: assign numeric, not TextBox string. V4.3.515 hoist
										-- intended numeric but the Saved* assignment site was missed;
										-- DamageFunction comparison threw on string-vs-number.
										if focus == "TopHP" then
											data["SavedTopHP"]=_topL
										elseif focus == "BottomHP" then
											data["SavedBottomHP"]=_botL
										elseif focus == "Both" then
											data["SavedTopHP"]=_topL
											data["SavedBottomHP"]=_botL
										end
									end
								until data["Healing"] == false or BREAKER.Parent == nil or PlayerData[LP.Name] ~= data  -- V4.3.567 H-15: break on teardown/re-exec (BREAKER gone) or PD replaced/reset, so a stale loop can't drive the new session repairDisplay
								if GUIObject.repairDisplay.Color == ColorSequence.new(
									{ColorSequenceKeypoint.new(0,Color3.new(1,1,1)),
										ColorSequenceKeypoint.new(0.00001,Color3.new(0, 0, 0)),
										ColorSequenceKeypoint.new(1,Color3.new(0, 0, 0))}
									) then
									if repairTween then pcall(function() repairTween:Cancel(); repairTween:Destroy() end) end
									repairTween = TS:Create(GUIObject.repairBar,TweenInfo.new(.1,Enum.EasingStyle.Sine,Enum.EasingDirection.In),{Size = UDim2.fromScale(.2,.2),ImageTransparency=1})
									repairTween:Play()
								end
							end
						end
					elseif data["HardcoreHP"] == false and (data["TopHP"] ~= "" or data["BottomHP"] ~= "") then
						GUIObject.hardcoreGroup.Visible = true
						if hardcoreGUITween then pcall(function() hardcoreGUITween:Cancel(); hardcoreGUITween:Destroy() end) end
						hardcoreGUITween = TS:Create(GUIObject.hardcoreGroup,TweenInfo.new(.1,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{GroupTransparency = 0})
						hardcoreGUITween:Play()
						data["Healing"] = true
						cd = true
						task.wait(.3)
						cd = false
						data["Healing"] = false
					end
					-- Publish HP clothing state change to synced peers
					if Function.AvatarSyncPublish then Function.AvatarSyncPublish(true) end
				end
			end
		end
		local function DamageFunction()
			if cd == false then
				local LP = game:GetService("Players").LocalPlayer
				local data = PlayerData[LP.Name]
				if LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") and data then
					-- V4.3.515 Fix 2: hoist numeric coercion - TopHP/BottomHP are TextBox strings.
					local _top = tonumber(data.TopHP) or 0
					local _bot = tonumber(data.BottomHP) or 0
					if data["HardcoreHP"] == true and (data["TopHP"] ~= "" or data["BottomHP"] ~= "") then
						if data["Healing"] == false then
							cd = true

							GUIObject.hardcoreGroup.Visible = true
							if hardcoreGUITween then pcall(function() hardcoreGUITween:Cancel(); hardcoreGUITween:Destroy() end) end
							hardcoreGUITween = TS:Create(GUIObject.hardcoreGroup,TweenInfo.new(.1,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{GroupTransparency = 0})
							hardcoreGUITween:Play()

							task.delay(0,function()
								Function.DragUpdate()
							end)
							data["Healing"] = true  -- V4.3.570: dropped a redundant duplicate `cd = true` above this line

							GUIObject.repairDisplay.Color = ColorSequence.new(
								{ColorSequenceKeypoint.new(0,Color3.new(1, 0.3, 0.3)),
									ColorSequenceKeypoint.new(0.00001,Color3.new(0, 0, 0)),
									ColorSequenceKeypoint.new(1,Color3.new(0, 0, 0))}
							)
							GUIObject.repairBar.Size = UDim2.fromScale(.2,.2)
							GUIObject.repairBar.ImageTransparency = 1
							GUIObject.repairBar.Visible = true
							if repairTween then pcall(function() repairTween:Cancel(); repairTween:Destroy() end) end
							repairTween = TS:Create(GUIObject.repairBar,TweenInfo.new(.3,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),{Size = UDim2.fromScale(.5,.5),ImageTransparency=.2})
							repairTween:Play()

							local timeAccumulated = 0
							-- V4.3.517 Fix 3: re-read inside loop. TextBox can mutate mid-damage; the V4.3.515
							-- hoisted _top/_bot would otherwise snapshot the initial cap and miss the edit.
							repeat
								local _topL = tonumber(data.TopHP) or 0
								local _botL = tonumber(data.BottomHP) or 0
								GUIObject.repairBar.Visible = true
								-- V4.3.520 Fix 13: nil-guard SavedTopHP/SavedBottomHP (sibling fix to HealFunction
								-- V4.3.515 Fix 3). Pre-fix, peer-applied PD without local Human init left these
								-- nil and `nil <= 0` threw → caught by outer pcall → silent loop exit.
								if (data["SavedTopHP"] or 0) <= 0 and (data["SavedBottomHP"] or 0) <= 0 then
									data["Healing"] = false
								end
								local focus
								local timeRequired = 1
								-- V4.3.515 Fix 2: guard divisions via _top/_bot.
								-- V4.3.521 Fix 7: V4.3.520 Fix 13 added guards to the exit predicate but the
								-- focus-selection right after still divided unguarded SavedTopHP/SavedBottomHP
								-- - same nil-throw on peer-applied PD without local Human init.
								if data["TopHP"] ~= "" and (data["SavedTopHP"] or 0)/math.max(_topL,1) > 0 then
									focus = "TopHP"
								elseif data["BottomHP"] ~= "" and (data["SavedBottomHP"] or 0)/math.max(_botL,1) > 0 then
									focus = "BottomHP"
								end
								if data["LinkedHeal"] == true then
									focus = "Both"
								end
								local t = task.wait()
								timeAccumulated += t
								GUIObject.repairDisplay.Offset = Vector2.new(timeAccumulated/timeRequired,0)
								if timeAccumulated >= timeRequired then
									timeAccumulated = 0
									if focus == "TopHP" then
										data["SavedTopHP"]=0
									elseif focus == "BottomHP" then
										data["SavedBottomHP"]=0
									elseif focus == "Both" then
										data["SavedTopHP"]=0
										data["SavedBottomHP"]=0
									end
								end
							until data["Healing"] == false or BREAKER.Parent == nil or PlayerData[LP.Name] ~= data  -- V4.3.567 H-15 (DamageFunction sibling)
							if GUIObject.repairDisplay.Color == ColorSequence.new(
								{ColorSequenceKeypoint.new(0,Color3.new(1, 0.3, 0.3)),
									ColorSequenceKeypoint.new(0.00001,Color3.new(0, 0, 0)),
									ColorSequenceKeypoint.new(1,Color3.new(0, 0, 0))}
								) then
								if repairTween then pcall(function() repairTween:Cancel(); repairTween:Destroy() end) end
								repairTween = TS:Create(GUIObject.repairBar,TweenInfo.new(.1,Enum.EasingStyle.Sine,Enum.EasingDirection.In),{Size = UDim2.fromScale(.2,.2),ImageTransparency=1})
								repairTween:Play()
							end
							cd = false
						end
					end
					-- Publish HP clothing state change to synced peers
					if Function.AvatarSyncPublish then Function.AvatarSyncPublish(true) end
				end
			end
		end
		local function CancelHP()
			local LP = game:GetService("Players").LocalPlayer
			local data = PlayerData[LP.Name]
			if LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") and data then
				if data.HardcoreHP == true or (data["TopHP"] ~= "" or data["BottomHP"] ~= "") then
					if data["Healing"] == true then
						data["Healing"] = false
					end
					if GUIObject.hardcoreGroup.GroupTransparency < 1 then
						task.delay(.5,function()
							if tap == false and data["Healing"] == false then
								if hardcoreGUITween then pcall(function() hardcoreGUITween:Cancel(); hardcoreGUITween:Destroy() end) end
								hardcoreGUITween = TS:Create(GUIObject.hardcoreGroup,TweenInfo.new(1,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{GroupTransparency = 1})
								hardcoreGUITween:Play()
							end
						end)
					end
				end
			end
		end

		-- V4.3.572: keybind rebinds now AUTO-PERSIST. Pre-fix, the InputBegan rebind handler
		-- below set the keybind in memory + updated the button text but NEVER wrote Settings.json
		-- - the only persist path was the separate "Save" button, which a user has no reason to
		-- press after changing a hotkey, so every rebind silently evaporated on the next execute
		-- (repeated report: "hotkeys do not get saved at all"). This merge-writes just the 4
		-- keybind keys under the SAME lock + atomic-write the Save button uses, leaving every other
		-- Settings.json key untouched. Stored on System (no new RoClothes local - register-safe).
		System.persistKeybinds = function()
			if not (env and env.writefile and env.isfile and env.readfile and _atomicWriteJSON) then return end
			pcall(function()
				_withSettingsLock(function()
					local merged = {}
					if env.isfile("RClothesLerp/Settings.json") then
						local _okR, _raw = pcall(env.readfile, "RClothesLerp/Settings.json")
						if _okR then
							local _okD, _dec = pcall(HS.JSONDecode, HS, _raw)
							if _okD and type(_dec) == "table" then merged = _dec end
						end
					end
					merged.KEYBIND   = (typeof(KEYBIND) == "EnumItem") and KEYBIND.Name or nil  -- V4.3.576: plain KeyCode name
					merged.hpKEYBIND = (typeof(hpKEYBIND) == "EnumItem") and hpKEYBIND.Name or nil
					merged.dpKEYBIND = (typeof(dpKEYBIND) == "EnumItem") and dpKEYBIND.Name or nil
					merged.nkKEYBIND = (typeof(nkKEYBIND) == "EnumItem") and nkKEYBIND.Name or nil
					_atomicWriteJSON("RClothesLerp/Settings.json", merged)
				end)
			end)
		end

		-- V4.4.2 FIX: the Options "Save" button had no handler, and the four On-Loadup controls updated
		-- their upvalues in-memory only (the setLoadup* comment says persistence is "handled by the Save
		-- button path" -- which never existed). Merge-write just the loadup keys under the SAME lock +
		-- atomic-write persistKeybinds uses, leaving every other Settings.json key intact.
		System.persistLoadup = function()
			if not (env and env.writefile and env.isfile and env.readfile and _atomicWriteJSON) then return false end
			local okAll = false
			pcall(function()
				_withSettingsLock(function()
					local merged = {}
					if env.isfile("RClothesLerp/Settings.json") then
						local _okR, _raw = pcall(env.readfile, "RClothesLerp/Settings.json")
						if _okR then
							local _okD, _dec = pcall(HS.JSONDecode, HS, _raw)
							if _okD and type(_dec) == "table" then merged = _dec end
						end
					end
					merged.loadupClosed  = loadupClosed
					merged.loadupExecute = loadupExecute
					merged.loadupFPerson = loadupFPerson
					merged.loadupBundle  = loadupBundle
					_atomicWriteJSON("RClothesLerp/Settings.json", merged)
					okAll = true
				end)
			end)
			return okAll
		end

		-- V4.4.2 Fix (round 2): persist the telemetry opt-in flag (both true AND false) so an opt-OUT STICKS
		-- across executes. Before this, only the lazy uploader wrote telemEnabled, and only when ENABLED --
		-- so opt-out was memory-only and the next execute reloaded the stale =true (telemetry silently resumed
		-- despite the user opting out). Mirrors persistLoadup/persistKeybinds (same lock + atomic write).
		System.persistTelem = function()
			if not (env and env.writefile and env.isfile and env.readfile and _atomicWriteJSON) then return end
			local pd = PlayerData[Player.Name]
			pcall(function()
				_withSettingsLock(function()
					local merged = {}
					if env.isfile("RClothesLerp/Settings.json") then
						local _okR, _raw = pcall(env.readfile, "RClothesLerp/Settings.json")
						if _okR then
							local _okD, _dec = pcall(HS.JSONDecode, HS, _raw)
							if _okD and type(_dec) == "table" then merged = _dec end
						end
					end
					merged.telemEnabled = (pd and pd._telemEnabled == true) or false
					_atomicWriteJSON("RClothesLerp/Settings.json", merged)
				end)
			end)
		end

