			elseif UIS.KeyboardEnabled and Keycode.KeyCode == nkKEYBIND then
				if PlayerData[SelectPlayer] then
					if PlayerData[SelectPlayer]._nakedMode then
						-- Toggle OFF: clear flag + reset to restore visual state.
						PlayerData[SelectPlayer]._nakedMode = nil
						pcall(Function.CharacterReset, SelectPlayer)
						if System.hotSwap then pcall(System.hotSwap) end
					else
