	setUpHPBinds()

	local collisionList = {}
	local collisionChecks = {}

	-- FP ignore list cache
	local fpCache = {ignoreList={}, dirty=true, lastChar=nil, conn1=nil, conn2=nil, params=RaycastParams.new()}
	fpCache.params.FilterType = Enum.RaycastFilterType.Exclude
