	do
		local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
		local _prior = _ok_genv and _genv and _genv._RC_awhile_task or nil
		if _prior then pcall(task.cancel, _prior) end
	end
	local aWhile
	aWhile = task.spawn(function()
		-- Cached tween handles for FPerson camera offset. One tween per slot, destroyed before
		-- replacement. Prevents TweenService accumulation: TS:Create() leaks if never Destroyed.
		-- Declared inside the spawn closure (not outer scope) to avoid consuming outer registers.
		local fpCamTween = nil
		local fpExitTween = nil
		local fpTi = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		local fpTi2 = TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		-- V4.3.375: hoist per-frame Vector3 allocations. Pre-fix the aWhile
		-- loop allocated 6+ Vector3 userdata per frame in FPerson mode
		-- (Vector3.new(0,1.5,0) x4, Vector3.new(0,0,-1), Vector3.new(.2,.2,.2),
		-- Vector3.new(1,...,1)). All constants now reused below.
		local _V3_HEAD_OFFSET   = Vector3.new(0, 1.5, 0)
		local _V3_FWD_NEG_Z     = Vector3.new(0, 0, -1)
		local _V3_TORSO_OFFSET  = Vector3.new(0.2, 0.2, 0.2)
		while true do
			task.wait()
			local ok, err = pcall(function()
			local lP = PS.LocalPlayer
			if lP and PlayerData[lP.Name] and PlayerData[lP.Name].FPerson then
				PlayerData[lP.Name].updateCooldown = true

				if lP and lP.Character then
					local char = lP.Character
					if char:FindFirstChild("Head") and char:FindFirstChild("HumanoidRootPart") and char:FindFirstChildOfClass("Humanoid") then
						-- V4.3.504: 1s timeout - FindFirstChild guard above can race with
						-- respawn/Destroy, leaving WaitForChild to block this RenderStepped
						-- loop indefinitely. Bail this iteration if either part vanished.
						local hed = char:WaitForChild("Head", 1)
						local rootpart = char:WaitForChild("HumanoidRootPart", 1)
						if not (hed and rootpart) then return end  -- exits the per-iter pcall body; outer `while` reruns next frame
						local human = char:FindFirstChildOfClass("Humanoid")
						local torso = char:FindFirstChild("Torso") or rootpart
						-- V4.3.375: Ray.new userdata removed - Raycast takes (origin, direction)
						-- directly. Pre-fix we built a Ray then immediately read ray.Origin /
						-- ray.Direction on the next line. ~1 Ray alloc/frame eliminated.
						local _rayOrigin = hed.Position
						local _rayDir = hed.CFrame.LookVector * 2

						local currentCamera = workspace.CurrentCamera
						if currentCamera then
							local distance = (currentCamera.Focus.p - currentCamera:GetRenderCFrame().p).magnitude
							local d = (distance<2) and (1.0-(distance-0.5)/1.5) or 0
							if d < 0.5 then
								d = 0
