								end
								-- V4.3.278: cap collisionList at 256 entries (FIFO drop). (see Changelog for full rationale)
								while #collisionList > 256 do
									local oldest = table.remove(collisionList, 1)
									if oldest then
										local conn = collisionChecks[oldest]
										if conn then
											local _ci = table.find(AllConnect, conn)
											if _ci then table.remove(AllConnect, _ci) end
											pcall(function() conn:Disconnect() end)
										end
										collisionChecks[oldest] = nil
									end
								end
								if fpCache.ignoreList then table.clear(fpCache.ignoreList) else fpCache.ignoreList = {} end
								for i, v in pairs(collisionList) do
									table.insert(fpCache.ignoreList, v)
								end
								for i, v in pairs(char:GetDescendants()) do
									if v:IsA("BasePart") then
