									elseif hit.CanCollide == true then
										local idx = table.find(collisionList,hit)
										if idx then table.remove(collisionList,idx) end
										fpCache.dirty = true  -- V4.3.505: rebuild ignore list on remove
										-- Self-remove from AllConnect when part turns collidable (no longer needed)
										local _ci = table.find(AllConnect, collisionChange)
										if _ci then table.remove(AllConnect, _ci) end
