							local _headObjSpace = _rootHeadCF:pointToObjectSpace(hed.CFrame.p)
							local toHead = _headObjSpace
							if PlayerData[lP.Name].HeadTracking == true then
								local offset = hed.CFrame.LookVector
								local Yset = torso.CFrame:ToObjectSpace(hed.CFrame).LookVector --hed.CFrame.LookVector
								local equation = math.max(0,math.pow(-1+10000000,math.min(1,(-Yset.Y)/.98))/9999999)
								local downwardsOffset = 0 + (2 - 0) * Function.Round(equation,3)
								perspective = _rootHeadCF:PointToObjectSpace(hed.CFrame.p+(offset*Vector3.new(1,math.clamp(1-(-Yset.Y/.98),0,1),1))+(torso.CFrame.LookVector*_V3_TORSO_OFFSET*downwardsOffset))-toHead
							else
								perspective = _V3_FWD_NEG_Z
							end
							if hit and d >= .8 then
								if PlayerData[lP.Name].FPsnap == false then
									if fpCamTween then pcall(function() fpCamTween:Cancel(); fpCamTween:Destroy() end) end
									fpCamTween = TS:Create(human,fpTi2,{CameraOffset = _headObjSpace+perspective*(hed.Position - pos).magnitude})
									fpCamTween:Play()
								else
									human.CameraOffset = _headObjSpace+perspective*(hed.Position - pos).magnitude
								end
							elseif d >= .8 then
								if PlayerData[lP.Name].FPsnap == false then
									if fpCamTween then pcall(function() fpCamTween:Cancel(); fpCamTween:Destroy() end) end
									fpCamTween = TS:Create(human,fpTi2,{CameraOffset = _headObjSpace+perspective})
									fpCamTween:Play()
								else
									human.CameraOffset = _headObjSpace+perspective
								end
							else
								if fpExitTween then pcall(function() fpExitTween:Cancel(); fpExitTween:Destroy() end) end
								fpExitTween = TS:Create(human,fpTi,{CameraOffset = _headObjSpace})
								fpExitTween:Play()
							end
						end
					end
				end
			end

			for PlayerName, DataList in pairs(PlayerData) do

				-- V4.3.63: removed dead `for Part, Property in pairs(...Mesh)` wrapper here.
				-- Part/Property were never referenced in the body; the iteration just ran the
				-- entire tear/heal block N times per frame where N = mesh count, multiplying
				-- per-frame work for no benefit. Mesh updates happen in the dedicated loop below.
					-- V4.3.451: single FindFirstChild hoisted. Pre-fix this ran TWICE per
					-- player per frame (60Hz × N players); each call walks Players' child list.
					local p = PS:FindFirstChild(PlayerName)
					if p then
						if p.Character and p.Character.PrimaryPart then
							local chr = p.Character
							local h = chr:FindFirstChildOfClass("Humanoid")
							-- V4.3.449: read DataList.MethodAtBuild instead of live `Method`.
							-- Method dropdown changes shouldn't desync per-frame reads from the
							-- proxy build state. Fallback to live `Method` if MethodAtBuild not set
							-- (first frames before CharacterExecute has run yet).
							local _methodBuilt = (DataList and DataList.MethodAtBuild) or Method
							-- V4.3.451: single FindFirstChild - pre-fix `:FindFirstChild()` ran,
							-- then indexed again with `[PlayerName]`, doubling the lookup. Cache once.
							if _methodBuilt == 2 then
								local _proxy = Method2CharacterFolder:FindFirstChild(PlayerName)
								if _proxy then chr = _proxy end
							end
							local PData = PlayerData[PlayerName]
							-- V4.5.24 Fix: PData can be nil mid-iteration (PlayerRemoving fires during the pairs walk)
							if h and PData and PData.Cooldown == false and PData.Character then
								-- V4.3.256+263: per-frame skip when nothing HP-relevant changed. (see Changelog for full rationale)
								-- V4.3.263 (mobile-perf F1): replaced V4.3.256's `string.format` cache key
								if PData._lastH == h.Health and PData._lastMaxH == h.MaxHealth
									and PData._lastTop == PData.TopHP and PData._lastBot == PData.BottomHP
									and PData._lastSTop == PData.SavedTopHP
									and PData._lastSBot == PData.SavedBottomHP
									and PData._lastHC == PData.HardcoreHP then
									continue
								end
								PData._lastH    = h.Health
								PData._lastMaxH = h.MaxHealth
								PData._lastTop  = PData.TopHP
								PData._lastBot  = PData.BottomHP
								PData._lastSTop = PData.SavedTopHP
								PData._lastSBot = PData.SavedBottomHP
								PData._lastHC   = PData.HardcoreHP
								local function transparent(o,v)
									if v >= 1 and o.Material == Enum.Material.Glass then
										o:AddTag("RCGlassMat")
										o.Material = Enum.Material.Neon
									elseif v < 1 and o.Material == Enum.Material.Neon and o:HasTag("RCGlassMat") then
										o:RemoveTag("RCGlassMat")
										o.Material = Enum.Material.Glass
									end
									o:SetAttribute("MaxTransparencyRC",v)
									o.Transparency = v
								end
								-- Continuous transparency lerp: compute damage fraction for gradient fading.
								-- V4.3.214: percentage-based - TopHP/BottomHP are percent thresholds (0-100),
								-- not raw damage values. Without this, characters with non-100 MaxHealth
								-- (e.g. Juggernaut with 600 HP) tear at the wrong damage.
								-- tonumber guard prevents NaN when TopHP/BottomHP = "0".
								local _topNum = tonumber(PData.TopHP)
								local _botNum = tonumber(PData.BottomHP)
								local _maxHP  = h.MaxHealth
								local _dmgPct = (_maxHP and _maxHP > 0) and ((_maxHP - h.Health) / _maxHP) or 0
								-- V4.3.515 Fix 3: SavedTopHP/SavedBottomHP can be nil prior to first HP write - guard with (... or 0).
								local _topFrac = (_topNum and _topNum > 0) and math.clamp(
									PData.HardcoreHP and (1 - (PData.SavedTopHP or 0) / _topNum)
										or (_dmgPct / (_topNum / 100)), 0, 1) or 0
								local _botFrac = (_botNum and _botNum > 0) and math.clamp(
									PData.HardcoreHP and (1 - (PData.SavedBottomHP or 0) / _botNum)
										or (_dmgPct / (_botNum / 100)), 0, 1) or 0
								-- Shared ClothesHP processor: resolves weld, applies transparency, fires HPFunction.
								-- isStripping=true: damage path (frac increases, Inverse==false gets faded).
								-- isStripping=false: heal path (Inverse==true gets re-shown, Inverse==false restores).
								local function _applyHPClothes(hpType, frac, isStripping)
									-- V4.3.294: cache the equipped-set on PData. Rebuild only when the (see Changelog for full rationale)
									local _cc = PData.CurrentClothes
									if not (PData._equippedSet
										and PData._equippedSetSrc == _cc
										and PData._equippedSetLen == #_cc) then
										local set = {}
										for _, _n in ipairs(_cc) do set[_n] = true end
										PData._equippedSet = set
										PData._equippedSetSrc = _cc
										PData._equippedSetLen = #_cc
									end
									local _equippedSet = PData._equippedSet
									for c, set in pairs(PData.ClothesHP) do
										if not _equippedSet[c] then continue end
										if not Clothes[c] then continue end
										-- V4.3.214: skip clothes with per-cloth Threshold; they're handled by the
										-- per-cloth fade loop further down (continuous fade based on own threshold).
										if type(set.Threshold) == "number" and set.Threshold > 0 then continue end
										local cc = Clothes[c]
										local w = cc.Weld
										if cc.Alternative and cc.Alternative.Condition then
											local _fn = Function[cc.Alternative.Condition]
											local a = false
											if _fn then local _ok, _rv = pcall(_fn, PlayerName); if _ok then a = _rv end end
											if a == true then w = cc.Alternative.Weld end
										elseif cc.Alternative then
											for _, alts in ipairs(cc.Alternative) do  -- V4.3.349: deterministic iteration
												local _fn2 = alts.Condition and Function[alts.Condition]
												local a = false
												if _fn2 then local _ok, _rv = pcall(_fn2, PlayerName); if _ok then a = _rv end end
												if a == true then w = alts["Weld"]; break end
											end
										end
										-- V4.5.24 Fix: cc.Weld (or Alternative.Weld) can be nil for a peer/import
										-- cloth carrying a ClothesHP entry but no weld def - pairs(nil) throws
										-- and aborts the whole per-frame HP body (M-11 sibling at the equip-time
										-- processHPClothes already guards; this per-frame site was missed).
										if type(w) ~= "table" then continue end
										if set["HP"] ~= hpType then continue end
										-- Destroy type: remove item permanently when fully stripped
										if isStripping and set["Type"] == "Destroy" and frac >= 1 then
											local idx = table.find(PData.CurrentClothes, c)
											if idx then
												table.remove(PData.CurrentClothes, idx)
												PData.ClothesHP[c] = nil
												-- V4.3.296: Destroy-type HP removal mutates CurrentClothes (see Changelog for full rationale)
												PData._equippedSetSrc = nil
											if System.hotSwapTarget then
												task.defer(function() System.hotSwapTarget(PlayerName) end)
											elseif System.hotSwap then
												task.defer(System.hotSwap)
											end
											end
										-- Apply or restore based on Inverse flag
										elseif isStripping ~= (set["Inverse"] == true) then
											-- Apply: always fully strip (1) - this is a one-shot trigger, not a continuous lerp
											local applyVal = 1
											for _, v in pairs(w) do
												if PData.CurrentPartList["Clothes"][v] then
													transparent(PData.CurrentPartList["Clothes"][v], applyVal)
												end
											end
											if cc.Unvisible then
												-- V4.3.462: when this "Apply" branch fires we're either (a) ripping non-inverse
												-- cloth or (b) healing inverse cloth; both states REVEAL the underlying Organ
												-- (e.g. breast). Pre-fix used `isStripping and 1 or alpha` which kept the Organ
												-- HIDDEN on the standard "rip non-inverse bra → see breast" path, matching the
												-- user's "breasts disappear when taking damage" report. Original LERP (L17184-17188)
												-- always restores the saved alpha in this branch, never sets transparency=1.
												for _, v in pairs(cc.Unvisible) do
													if PData.CurrentPartList["Organ"][v] then
														local _op = PData.CurrentPartList["Organ"][v]
														transparent(_op, _op:GetAttribute("Alpha") or 0)
													end
												end
											end
											if cc.HPFunction then
												if typeof(cc.HPFunction) == "string" then
													if Function[cc.HPFunction] then pcall(Function[cc.HPFunction], false, chr, PlayerName, c) end
												elseif typeof(cc.HPFunction) == "table" then
													for _, v in pairs(cc.HPFunction) do
														if Function[v] then pcall(Function[v], false, chr, PlayerName, c) end
													end
												end
											end
										else
											-- Restore: stripping+inverse stays, healing+normal restores alpha
											for _, v in pairs(w) do
												if PData.CurrentPartList["Clothes"][v] then
													local t = PData.CurrentPartList["Clothes"][v]:GetAttribute("Alpha") or 0
													transparent(PData.CurrentPartList["Clothes"][v], t)
												end
											end
											if cc.Unvisible then
												for _, v in pairs(cc.Unvisible) do
													if PData.CurrentPartList["Organ"][v] then
														transparent(PData.CurrentPartList["Organ"][v], 1)
													end
												end
											end
											if cc.HPFunction then
												if typeof(cc.HPFunction) == "string" then
													if Function[cc.HPFunction] then pcall(Function[cc.HPFunction], true, chr, PlayerName, c) end
												elseif typeof(cc.HPFunction) == "table" then
													for _, v in pairs(cc.HPFunction) do
														if Function[v] then pcall(Function[v], true, chr, PlayerName, c) end
													end
												end
											end
										end
									end
								end

								-- V4.3.362: AccessoryHP rip/restore - sibling to _applyHPClothes. (see Changelog for full rationale)
								-- V4.3.370: fade animation via TweenService.
								-- V4.3.374: hoisted _TS/TweenInfos/cache/helper to file scope
								local _fadeHandle = _RC_fadeHandle

								local function _applyHPAccessories(hpType, _frac, isStripping)
									-- Per-accessory manual tags (V4.3.362) - explicit user choices.
									if PData.AccessoryHP then
										for accName, set in pairs(PData.AccessoryHP) do
											if type(set) == "table" and set.HP == hpType then
												local acc = chr and chr:FindFirstChild(accName)
												if acc and acc:IsA("Accessory") then
													local handle = acc:FindFirstChild("Handle")
														or acc:FindFirstChildOfClass("MeshPart")
														or acc:FindFirstChildOfClass("Part")
													if handle then
														if isStripping ~= (set.Inverse == true) then
															_fadeHandle(handle, 1)
														else
															_fadeHandle(handle, 0)
														end
													end
												end
											end
										end
									end
									-- V4.3.372: auto-strip walk redesigned per user clarification. Targets (see Changelog for full rationale)
									if PData.AutoStripOnRip == true and PData.CurrentClothes and Clothes then
										local _wantTop = (hpType == "TopHP")
										local _manualHandled = {}
										if PData.ClothesHP then
											for c, set in pairs(PData.ClothesHP) do
												if type(set) == "table" and set.HP then _manualHandled[c] = true end
											end
										end
										local _stripMap = PData.StripOnRipMap or {}
										for _, clothName in ipairs(PData.CurrentClothes) do
											if not _manualHandled[clothName] then
												local cc = Clothes[clothName]
												if cc then
													local _mode = _stripMap[clothName]
													if _mode == nil then
														-- Smart default by ClothType.
														if cc.ClothType == "Shirt" or cc.ClothType == "Pants" then
															_mode = "None"
														else
															_mode = "Both"
														end
													end
													local _matches = _mode == "Both"
														or (_mode == "Top" and _wantTop)
														or (_mode == "Bottom" and not _wantTop)
													if _matches and cc.Weld then
														for _, partName in pairs(cc.Weld) do
															local _mp = PData.CurrentPartList and PData.CurrentPartList["Clothes"]
																and PData.CurrentPartList["Clothes"][partName]
															if _mp then _fadeHandle(_mp, isStripping and 1 or 0) end
														end
													end
												end
											end
										end
									end
								end

								-- top --
								-- V4.3.333: percent-based threshold (re-applied on top of V4.3.332's
								-- cycle-button UI revert). TopHP is a percent (0-100); compare against
								-- (damage taken / MaxHealth) so high-MaxHealth (Juggernaut etc) and
								-- low-MaxHealth characters both trigger at the right damage point.
								if PData.TopHP ~= "" and
									(PData.HardcoreHP == false and h.MaxHealth > 0 and (h.MaxHealth-h.Health) / h.MaxHealth >= (tonumber(PData.TopHP) or 0) / 100 or
										PData.HardcoreHP == true and (PData.SavedTopHP or 0) <= 0
									) then
									if PData.TopRipped == false then
										PData.TopRipped = true

										if UIS.KeyboardEnabled then
											local audio = Instance.new("Sound",chr.PrimaryPart)
											audio.SoundId = Function.GetAsset("rbxasset://RClothesContent/Sound/Tear/tear".. math.random(1,3) ..".mp3")
											audio.Volume = 0.75*PData.Volume
											audio:Play()
											DB:AddItem(audio,3)
										else
											local sounds = {9113827650,9113827551,9113833815}
											local audio = Instance.new("Sound",chr.PrimaryPart)
											audio.SoundId = "rbxassetid://"..  sounds[math.random(1,#sounds)]
											audio.Volume = 0.75*PData.Volume
											audio:Play()
											DB:AddItem(audio,3)
										end

										if PData.TearParticles == true then
											local particle = Instance.new("ParticleEmitter", chr:FindFirstChild("HumanoidRootPart") or chr.PrimaryPart)
											particle.Enabled = false
											particle.Texture = "rbxassetid://386425736"
											particle.Size = NumberSequence.new(
												{
													NumberSequenceKeypoint.new(0,.7,.375),
													NumberSequenceKeypoint.new(1,.4)
												}
											)
											particle.Transparency = NumberSequence.new(
												{
													NumberSequenceKeypoint.new(0,1),
													NumberSequenceKeypoint.new(0.214,0),
													NumberSequenceKeypoint.new(0.545,0),
													NumberSequenceKeypoint.new(1,1)
												}
											)
											particle.Lifetime = NumberRange.new(0.5,1)
											particle.Rotation = NumberRange.new(-360,360)
											particle.RotSpeed = NumberRange.new(-360,360)
											particle.Speed = NumberRange.new(15,20)
											particle.SpreadAngle = Vector2.new(75,75)
											particle.Acceleration = Vector3.new(0,-15,0)
											particle.Drag = 5
											particle:Emit(50)
											DB:AddItem(particle,3)
										end

										_applyHPClothes("TopHP", _topFrac, true)
										_applyHPAccessories("TopHP", _topFrac, true)  -- V4.3.362
									end  -- if TopRipped == false
								elseif PData.TopHP ~= "" and
									(PData.HardcoreHP == false and (h.MaxHealth <= 0 or (h.MaxHealth-h.Health) / h.MaxHealth < (tonumber(PData.TopHP) or 0) / 100) or
										PData.HardcoreHP == true and (PData.SavedTopHP or 0) > 0
									) then
									if PData.TopRipped == true then
										PData.TopRipped = false

										if UIS.KeyboardEnabled then
											local audio = Instance.new("Sound",chr.PrimaryPart)
											audio.SoundId = Function.GetAsset("rbxasset://RClothesContent/Sound/Heal/heal".. math.random(1,4) ..".mp3")
											audio.Volume = 2.5*PData.Volume
											audio:Play()
											DB:AddItem(audio,3)
										else
											local sounds = {9113824422,9119138453,9113384209,9113824860}
											local audio = Instance.new("Sound",chr.PrimaryPart)
											audio.SoundId = "rbxassetid://"..  sounds[math.random(1,#sounds)]
											audio.Volume = 2.5*PData.Volume
											audio:Play()
											DB:AddItem(audio,3)
										end

										if PData.HealParticles == true then
											local particle = Instance.new("ParticleEmitter", chr:FindFirstChild("HumanoidRootPart") or chr.PrimaryPart)
											particle.Enabled = false
											particle.Texture = "rbxassetid://16291625893"
											particle.LightEmission = 1
											particle.ZOffset = 1
											particle.Size = NumberSequence.new(
												{
													NumberSequenceKeypoint.new(0,0),
													NumberSequenceKeypoint.new(1,.5)
												}
											)
											particle.Transparency = NumberSequence.new(
												{
													NumberSequenceKeypoint.new(0,1),
													NumberSequenceKeypoint.new(0.5,0),
													NumberSequenceKeypoint.new(1,1)
												}
											)
											particle.Lifetime = NumberRange.new(0.5,1)
											particle.Rotation = NumberRange.new(-10,10)
											particle.RotSpeed = NumberRange.new(-10,10)
											particle.Speed = NumberRange.new(-1,2)
											particle.Drag = 2
											particle:Emit(math.random(4,8))
											DB:AddItem(particle,3)
										end

										_applyHPClothes("TopHP", _topFrac, false)
										_applyHPAccessories("TopHP", _topFrac, false)  -- V4.3.362
									end  -- if TopRipped == true
								end  -- if/elseif TopHP chain
								-- bottom --
								-- V4.3.333: percent-based threshold (see TopHP block above).
								if PData.BottomHP ~= "" and
									(PData.HardcoreHP == false and h.MaxHealth > 0 and (h.MaxHealth-h.Health) / h.MaxHealth >= (tonumber(PData.BottomHP) or 0) / 100 or
										PData.HardcoreHP == true and (PData.SavedBottomHP or 0) <= 0
									) then
									if PData.BottomRipped == false then
										PData.BottomRipped = true

										if UIS.KeyboardEnabled then
											local audio = Instance.new("Sound",chr.PrimaryPart)
											audio.SoundId = Function.GetAsset("rbxasset://RClothesContent/Sound/Tear/tear".. math.random(1,3) ..".mp3")
											audio.Volume = 0.75*PData.Volume
											audio:Play()
											DB:AddItem(audio,3)
										else
											local sounds = {9113827650,9113827551,9113833815}
											local audio = Instance.new("Sound",chr.PrimaryPart)
											audio.SoundId = "rbxassetid://"..  sounds[math.random(1,#sounds)]
											audio.Volume = 0.75*PData.Volume
											audio:Play()
											DB:AddItem(audio,3)
										end

										if PData.TearParticles == true then
											local particle = Instance.new("ParticleEmitter", chr:FindFirstChild("HumanoidRootPart") or chr.PrimaryPart)
											particle.Enabled = false
											particle.Texture = "rbxassetid://386425736"
											particle.Size = NumberSequence.new(
												{
													NumberSequenceKeypoint.new(0,.7,.375),
													NumberSequenceKeypoint.new(1,.4)
												}
											)
											particle.Transparency = NumberSequence.new(
												{
													NumberSequenceKeypoint.new(0,1),
													NumberSequenceKeypoint.new(0.214,0),
													NumberSequenceKeypoint.new(0.545,0),
													NumberSequenceKeypoint.new(1,1)
												}
											)
											particle.Lifetime = NumberRange.new(0.5,1)
											particle.Rotation = NumberRange.new(-360,360)
											particle.RotSpeed = NumberRange.new(-360,360)
											particle.Speed = NumberRange.new(15,20)
											particle.SpreadAngle = Vector2.new(75,75)
											particle.Acceleration = Vector3.new(0,-15,0)
											particle.Drag = 5
											particle:Emit(50)
											DB:AddItem(particle,3)
										end

										_applyHPClothes("BottomHP", _botFrac, true)
										_applyHPAccessories("BottomHP", _botFrac, true)  -- V4.3.362
									end  -- if BottomRipped == false
								elseif PData.BottomHP ~= "" and
									(PData.HardcoreHP == false and (h.MaxHealth <= 0 or (h.MaxHealth-h.Health) / h.MaxHealth < (tonumber(PData.BottomHP) or 0) / 100) or
										PData.HardcoreHP == true and (PData.SavedBottomHP or 0) > 0
									) then
									if PData.BottomRipped == true then
										PData.BottomRipped = false

										if UIS.KeyboardEnabled then
											local audio = Instance.new("Sound",chr.PrimaryPart)
											audio.SoundId = Function.GetAsset("rbxasset://RClothesContent/Sound/Heal/heal".. math.random(1,4) ..".mp3")
											audio.Volume = 2.5*PData.Volume
											audio:Play()
											DB:AddItem(audio,3)
										else
											local sounds = {9113824422,9119138453,9113384209,9113824860}
											local audio = Instance.new("Sound",chr.PrimaryPart)
											audio.SoundId = "rbxassetid://"..  sounds[math.random(1,#sounds)]
											audio.Volume = 2.5*PData.Volume
											audio:Play()
											DB:AddItem(audio,3)
										end

										if PData.HealParticles == true then
											local particle = Instance.new("ParticleEmitter", chr:FindFirstChild("HumanoidRootPart") or chr.PrimaryPart)
											particle.Enabled = false
											particle.Texture = "rbxassetid://16291625893"
											particle.LightEmission = 1
											particle.ZOffset = 1
											particle.Size = NumberSequence.new(
												{
													NumberSequenceKeypoint.new(0,0),
													NumberSequenceKeypoint.new(1,.5)
												}
											)
											particle.Transparency = NumberSequence.new(
												{
													NumberSequenceKeypoint.new(0,1),
													NumberSequenceKeypoint.new(0.5,0),
													NumberSequenceKeypoint.new(1,1)
												}
											)
											particle.Lifetime = NumberRange.new(0.5,1)
											particle.Rotation = NumberRange.new(-10,10)
											particle.RotSpeed = NumberRange.new(-10,10)
											particle.Speed = NumberRange.new(-1,2)
											particle.Drag = 2
											particle:Emit(math.random(4,8))
											DB:AddItem(particle,3)
										end

										_applyHPClothes("BottomHP", _botFrac, false)
										_applyHPAccessories("BottomHP", _botFrac, false)  -- V4.3.362
									end  -- if BottomRipped == true
								end  -- if/elseif BottomHP chain

								if (PData.SavedPreviousHP-h.Health) > 0 and PData.HardcoreHP == true then
									local _dmgPP = (PData.SavedPreviousHP - h.Health) / ((h.MaxHealth and h.MaxHealth > 0) and h.MaxHealth or 100) * 100  -- V4.5.17: hardcore durability now depletes by PERCENTAGE-POINTS of the char's ACTUAL MaxHealth, not raw HP. "TopHP=100" now tears after losing 100% of real max (300 dmg on a 300-HP char), not a flat 100 -- fixes "tears too easy on >100-HP games". With the 150% slider a >100% pool can't drain from damage alone (you die at 100%), so the clothing survives until death/respawn. (the `or 100` is a respawn-frame div-by-zero guard.)
									PData.SavedTopHP = math.max((PData.SavedTopHP or 0) - _dmgPP, 0)  -- V4.5.24 Fix: nil-guard (peer-synced hardcore can carry nil Saved*HP)
									PData.SavedBottomHP = math.max((PData.SavedBottomHP or 0) - _dmgPP, 0)
									if PData["Healing"] == true then
										PData["Healing"] = false
										GUIObject.repairDisplay.Color = ColorSequence.new(
											{ColorSequenceKeypoint.new(0,Color3.new(1,0,0)),
												ColorSequenceKeypoint.new(0.00001,Color3.new(0, 0, 0)),
												ColorSequenceKeypoint.new(1,Color3.new(0, 0, 0))}
										)
										if repairTween then pcall(function() repairTween:Cancel(); repairTween:Destroy() end) end
										repairTween = TS:Create(GUIObject.repairBar,TweenInfo.new(1,Enum.EasingStyle.Sine,Enum.EasingDirection.In),{ImageTransparency=1})
										repairTween:Play()
									end
								end
								if PData.DamageSFX ~= "" and h.Health < PData.SavedPreviousHP then
									if (PData.SavedPreviousHP-h.Health) >= (tonumber(PData.DamageSFX) or math.huge) then
										if UIS.KeyboardEnabled then
											local audio = Instance.new("Sound",chr.PrimaryPart)
											audio.SoundId = Function.GetAsset("rbxasset://RClothesContent/Sound/Moan/".. math.random(1,8) ..".ogg")
											audio.Volume = 1.5*PData.Volume
											audio:Play()
											DB:AddItem(audio,3)
										else
											local sounds = {4792913155,4792899013,4792904673,4792901644,4792915329,4792884617}
											local audio = Instance.new("Sound",chr.PrimaryPart)
											audio.SoundId = "rbxassetid://".. sounds[math.random(1,#sounds)]
											audio.Volume = 1.5*PData.Volume
											audio:Play()
											DB:AddItem(audio,3)
										end
									end
								end
								PData.SavedPreviousHP = h.Health
								if PData.HardcoreHP == true then
									-- V4.3.214: tonumber() guard. PData.TopHP/BottomHP are strings from
									-- TextBoxes; "0" or non-numeric input would NaN-divide and crash Color3.new.
									if PData.TopHP ~= "" then
										local _t = tonumber(PData.TopHP) or 0
										local _r = (_t > 0) and math.clamp((PData.SavedTopHP or 0)/_t, 0, 1) or 1
										GUIObject.topHPDisplay.Text = math.clamp(math.round(_r*100),0,100).."%"
										GUIObject.topHPDisplay.TextColor3 = Color3.new(1-_r, _r, 0)
									else
										GUIObject.topHPDisplay.Text = ""
									end
									if PData.BottomHP ~= "" then
										local _b = tonumber(PData.BottomHP) or 0
										local _r = (_b > 0) and math.clamp((PData.SavedBottomHP or 0)/_b, 0, 1) or 1
										GUIObject.bottomHPDisplay.Text = math.clamp(math.round(_r*100),0,100).."%"
										GUIObject.bottomHPDisplay.TextColor3 = Color3.new(1-_r, _r, 0)
									else
										GUIObject.bottomHPDisplay.Text = ""
									end
								else
									-- V4.3.333: percent-based display (1 - dmgPct / thresholdPct) so the
									-- HP bar percentage tracks correctly on non-100 MaxHealth characters.
									local _maxHP  = h.MaxHealth
									local _dmgPct = (_maxHP and _maxHP > 0) and ((_maxHP - h.Health) / _maxHP) or 0
									if PData.TopHP ~= "" then
										local _topPct = (tonumber(PData.TopHP) or 0) / 100
										local _r = (_topPct > 0) and (1 - _dmgPct / _topPct) or 1
										GUIObject.topHPDisplay.Text = math.clamp(math.round(_r * 100), 0, 100) .. "%"
										GUIObject.topHPDisplay.TextColor3 = Color3.new(1 - _r, _r, 0)
									else
										GUIObject.topHPDisplay.Text = ""
									end
									if PData.BottomHP ~= "" then
										local _botPct = (tonumber(PData.BottomHP) or 0) / 100
										local _r = (_botPct > 0) and (1 - _dmgPct / _botPct) or 1
										GUIObject.bottomHPDisplay.Text = math.clamp(math.round(_r * 100), 0, 100) .. "%"
										GUIObject.bottomHPDisplay.TextColor3 = Color3.new(1 - _r, _r, 0)
									else
										GUIObject.bottomHPDisplay.Text = ""
									end
								end
							end
						end
					end

					-- V4.3.332: REVERTED V4.3.214 - per-accessory AccessoryHP fade loop and
					-- per-cloth Threshold continuous-fade loop disabled. The cycle-button UI
					-- only writes legacy {HP, Inverse} entries, processed by the
					-- _applyHPClothes one-shot path above. AccessoryHP map and ClothesHP
					-- Threshold field are no longer used.

			end

		end) -- pcall
		if not ok then warn("[RoClothes] aWhile error:", err) end
		end
	end)
	-- V4.3.163 G4: publish handle to System so BREAKER.Destroying (L~1003) can cancel first.
	System.aWhileHandle = aWhile
	-- V4.3.521 Fix 14: stash handle on getgenv() for cross-exec cancellation.
	do
		local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
		if _ok_genv and _genv then _genv._RC_awhile_task = aWhile end
	end

	-- V4.3.48: ensure FP raycast loop is stopped on session teardown (formerly relied on BREAKER.Destroying cascading errors to kill it).
	GlobalMaid:Give(function()
		if aWhile then
			pcall(task.cancel, aWhile)
		end
		-- V4.3.567 H-14: also disconnect the fpCache char-descendant watchers (never maid-tracked -> 2 dead conns leaked per re-execute)
		if fpCache.conn1 then pcall(function() fpCache.conn1:Disconnect() end); fpCache.conn1 = nil end
		if fpCache.conn2 then pcall(function() fpCache.conn2:Disconnect() end); fpCache.conn2 = nil end
	end)

	local highlights = {}
	local currentCamera = workspace.CurrentCamera
	local currentFocus = currentCamera and currentCamera.Focus or CFrame.new()
	local currentCFrame = currentCamera and currentCamera:GetRenderCFrame() or CFrame.new()

	-- V4.3.168.14: dropped the `local camUpdater =` binding since BindToRenderStep
	-- returns nothing (cleanup uses the name-based `RS:UnbindFromRenderStep("CameraUpdate")`
	-- in BREAKER.Destroying). The named local was dead weight at RoClothes scope.
	RS:BindToRenderStep("CameraUpdate", Enum.RenderPriority.Camera.Value, function()
		currentCamera = workspace.CurrentCamera
		-- V4.5.24 Fix: nil camera frame (camera switch/respawn) -> skip this frame instead of
		-- erroring inside the binding (a throw would drop the CameraUpdate binding for the rest
		-- of the session and kill highlight tracking + FP transparency).
		if not currentCamera then return end
		currentFocus = currentCamera.Focus
		currentCFrame = currentCamera:GetRenderCFrame()
	end)

	-- V4.3.265: inlined as anonymous closure to AllConnect (was `local RunConnect = ...`
	-- + adjacent table.insert). Frees 1 RoClothes-scope register slot.
	table.insert(AllConnect, RS.RenderStepped:Connect(function()
		for _, v in pairs(Method2CharacterFolder:GetChildren()) do
			local CharacterValue = v:FindFirstChildOfClass("ObjectValue")

			if CharacterValue and CharacterValue.Value ~= nil and CharacterValue.Value.Parent == nil then
				v:Destroy()
			end
		end

		local lP = PS.LocalPlayer

		-- V4.3.505: hoist _hlSet build out of the per-player loop. `highlights` is a
		-- script-scope list; pre-fix the V4.3.504 set was rebuilt once per player per
		-- frame (4 players × 60fps = 240 throwaway tables/sec). One build per frame now.
		local _hlSet = {}
		for _, _h in ipairs(highlights) do _hlSet[_h] = true end

		for PlayerName, DataList in pairs(PlayerData) do
			local _methodBuilt = (DataList and DataList.MethodAtBuild) or Method  -- V4.3.449: captured method
		local liveCharacter = ((_methodBuilt == 2 or _methodBuilt == 3) and DataList.Character) or nil
			-- V4.3.375: cache the cache. Pre-fix both tables were freshly allocated
			-- every RenderStepped frame per player - at 60fps * 4 players that's
			-- ~480 throwaway tables/sec. Promote onto DataList and table.clear so
			-- the GC stays calm. Cache keys are Instances; clear-on-iter is safe
			-- because the cache is only valid within one frame's pass.
			local meshScaleCache = DataList._meshScaleCache or {}
			local accessoryScaleCache = DataList._accessoryScaleCache or {}
			DataList._meshScaleCache = meshScaleCache
			DataList._accessoryScaleCache = accessoryScaleCache
			table.clear(meshScaleCache)
			table.clear(accessoryScaleCache)

			-- Per-frame scale caches: many clothes share the same torso/limb base.
			-- Reusing the multiplier math cuts repeated head/torso recompute cost on mesh-heavy bundles.
			local function getMeshScaleInfo(Base)
				local cached = meshScaleCache[Base]
				if cached then
					return cached
				end

				local BodySize = BodyPartSize[Base.Name]
				local CalcSize = Base.Size
				local specialHead = false

				if Base.Name == "Head" and Base:IsA("MeshPart") then
					local originalSize = Base:FindFirstChild("OriginalSize")
					if originalSize then
						BodySize = originalSize.Value
					else
						BodySize = BodyPartSize["HeadMeshFix"]
					end
				elseif Base.Name == "Head" and Base:FindFirstChildOfClass("SpecialMesh") then
					local SM:SpecialMesh = Base:FindFirstChildOfClass("SpecialMesh")
					if SM.MeshType == Enum.MeshType.Head then
						specialHead = true
						BodySize = BodyPartSize["HeadScale"]
					else
						local cachedMesh = DataList.CurrentPartList["TrueMeshSize"]
						if cachedMesh and cachedMesh.MeshId == SM.MeshId then
							CalcSize = cachedMesh.Part.Size * SM.Scale
							BodySize = BodyPartSize["HeadMeshFix"]
						else
							Function.RequestHeadMeshSize(DataList, SM.MeshId)
							CalcSize = SM.Scale
							BodySize = BodyPartSize["HeadScale"]
						end
					end
				end

				local XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(CalcSize, BodySize)
				if specialHead then
					local SM:SpecialMesh = Base:FindFirstChildOfClass("SpecialMesh")
					if CalcSize.X > CalcSize.Z then
						CalcSize = Vector3.new(CalcSize.Z, CalcSize.Y, CalcSize.Z)
					end
					if CalcSize.Z > CalcSize.X then
						CalcSize = Vector3.new(CalcSize.X, CalcSize.Y, CalcSize.X)
					end
					XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(CalcSize, BodySize)

					local S = SM.Scale
					if S.X > S.Z then
						S = Vector3.new(S.Z, S.Y, S.Z)
					end
					if S.Z > S.X then
						S = Vector3.new(S.X, S.Y, S.X)
					end
					local XMS, YMS, ZMS = Function.MultiplyCalculate(S, vector3New(1.25, 1.25, 1.25))

					XMultiply = XMultiply * XMS
					YMultiply = YMultiply * YMS
					ZMultiply = ZMultiply * ZMS
				end

				cached = { XMultiply = XMultiply, YMultiply = YMultiply, ZMultiply = ZMultiply }
				meshScaleCache[Base] = cached
				return cached
			end

			local function getAccessoryScaleInfo(Base)
				local cached = accessoryScaleCache[Base]
				if cached then
					return cached
				end

				local CalcSize = Base.Size
				local BodySize = BodyPartSize[Base.Name]
				local specialHead = false

				if not BodySize then
					if Base.Name == "UpperTorso" or Base.Name == "LowerTorso" then
						BodySize = BodyPartSize["Torso"]
					elseif Base.Name == "LeftUpperArm" or Base.Name == "LeftLowerArm" then
						BodySize = BodyPartSize["Left Arm"]
					elseif Base.Name == "RightUpperArm" or Base.Name == "RightLowerArm" then
						BodySize = BodyPartSize["Right Arm"]
					elseif Base.Name == "LeftUpperLeg" or Base.Name == "LeftLowerLeg" then
						BodySize = BodyPartSize["Left Leg"]
					elseif Base.Name == "RightUpperLeg" or Base.Name == "RightLowerLeg" then
						BodySize = BodyPartSize["Right Leg"]
					end
				elseif Base.Name == "Head" and Base:IsA("MeshPart") then
					local originalSize = Base:FindFirstChild("OriginalSize")
					if originalSize then
						BodySize = originalSize.Value
					else
						BodySize = BodyPartSize["HeadMeshFix"]
					end
				elseif Base.Name == "Head" and Base:FindFirstChildOfClass("SpecialMesh") then
					local SM:SpecialMesh = Base:FindFirstChildOfClass("SpecialMesh")
					if SM.MeshType == Enum.MeshType.Head then
						specialHead = true
						BodySize = BodyPartSize["HeadScale"]
					else
						local cachedMeshAcc = DataList.CurrentPartList["TrueMeshSize"]
						if cachedMeshAcc and cachedMeshAcc.MeshId == SM.MeshId then
							local sz = cachedMeshAcc.Part.Size
							local x = 1 - (1.198 / math.max(sz.X, 1.198))
							local y = 1 - (1.202 / math.max(sz.Y, 1.202))
							local z = 1 - (1.198 / math.max(sz.Z, 1.198))
							CalcSize = Vector3.new(SM.Scale.X + x, SM.Scale.Y + y, SM.Scale.Z + z)
							BodySize = BodyPartSize["HeadScale"]
						else
							Function.RequestHeadMeshSize(DataList, SM.MeshId)
							CalcSize = SM.Scale
							BodySize = BodyPartSize["HeadScale"]
						end
					end
				end

				local XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(CalcSize, BodySize)
				if specialHead then
					local SM:SpecialMesh = Base:FindFirstChildOfClass("SpecialMesh")
					if CalcSize.X > CalcSize.Z then
						CalcSize = Vector3.new(CalcSize.Z, CalcSize.Y, CalcSize.Z)
					end
					if CalcSize.Z > CalcSize.X then
						CalcSize = Vector3.new(CalcSize.X, CalcSize.Y, CalcSize.X)
					end
					XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(CalcSize, BodySize)

					local S = SM.Scale
					if S.X > S.Z then
						S = Vector3.new(S.Z, S.Y, S.Z)
					end
					if S.Z > S.X then
						S = Vector3.new(S.X, S.Y, S.X)
					end
					local XMS, YMS, ZMS = Function.MultiplyCalculate(S, vector3New(1.25, 1.25, 1.25))

					XMultiply = XMultiply * XMS
					YMultiply = YMultiply * YMS
					ZMultiply = ZMultiply * ZMS
				end

				cached = { XMultiply = XMultiply, YMultiply = YMultiply, ZMultiply = ZMultiply }
				accessoryScaleCache[Base] = cached
				return cached
			end

			-- V4.3.505: _hlSet hoisted above the per-player loop (single build per frame).
			for Name, Property in pairs(DataList.ConvertedPart) do
				local Part = Property.Part
				local Weld = Property.Weld
				local Base = Property.Base
				local BaseSize = System.R15Size[Base.Name]
				local basePart = DataList.Character and DataList.Character:FindFirstChild(Base.Name)
				local origSize = basePart and basePart:FindFirstChild("OriginalSize")
				if origSize then
					BaseSize = origSize.Value
				end

				if Base:IsA("MeshPart") and Base.MeshId == "http://www.roblox.com/asset/?id=542765884" then
					BaseSize = System.R15Size["UpperTorsoFemale"]
				end

				local XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(Base.Size, BaseSize)

				Part.Color = Base.Color
				Part.Material = Base.Material
				Part.Transparency = Base.Transparency
				Part.LocalTransparencyModifier = 1

				if DataList.MeshSizeLock == false then
					-- V4.3.280: scalar pre-compare so we don't even allocate the Vector3
					-- when sizes are unchanged. Pre-fix's `Vector3.new(...) ; if ~= ...` still
					-- allocated 7,200 Vector3 userdatas/sec on 4-player mobile in steady state.
					-- Now alloc only on actual change.
					local _r6 = System.R6Size[Name]
					local _tx, _ty, _tz = _r6.X * XMultiply, _r6.Y * YMultiply, _r6.Z * ZMultiply
					local _cur = Part.Size
					if _cur.X ~= _tx or _cur.Y ~= _ty or _cur.Z ~= _tz then
						Part.Size = Vector3.new(_tx, _ty, _tz)
					end
					Weld.C0 = CFrame.new(System.WeldCFrame[Name].Position.X * XMultiply, System.WeldCFrame[Name].Position.Y * YMultiply, System.WeldCFrame[Name].Position.Z * ZMultiply) * System.WeldCFrame[Name].Rotation
				end
			end

			-- Highlight replication: run once per player per frame instead of once per mesh part.
			if (((DataList and DataList.MethodAtBuild) or Method) == 2 or ((DataList and DataList.MethodAtBuild) or Method) == 3) and DataList.Character then  -- V4.3.449
				local _hl = DataList.Character:FindFirstChildOfClass("Highlight")
				if _hl and not _hlSet[_hl] then  -- V4.3.504: O(1) hoisted-set lookup (was table.find per part)
					local h:Highlight = _hl
					if not h.Adornee or h.Adornee == h.Parent then
						table.insert(highlights,h)
						_hlSet[h] = true  -- V4.3.504: keep hoisted set coherent within this frame
						local replicate = h:Clone()
						replicate.Parent = Method2CharacterFolder:FindFirstChild(PlayerName) or Method2CharacterFolder
						local changed, destroyingConn
						local closed = false
						local function cleanupHighlight()
							if closed then return end
							closed = true
							for _, connection in ipairs({changed, destroyingConn}) do
								connection:Disconnect()
								local index = table.find(AllConnect, connection)
								if index then table.remove(AllConnect, index) end
							end
							local index = table.find(highlights, h)
							if index then table.remove(highlights, index) end
							_hlSet[h] = nil
							replicate:Destroy()
						end
						changed = h.Changed:Connect(function(c)
							if h.Parent == nil or (h.Parent ~= DataList.Character and (not h.Adornee or h.Adornee ~= DataList.Character)) then
								cleanupHighlight()
								return
							end
							if (not h.Adornee and h.Parent ~= DataList.Character) or (h.Adornee and h.Adornee ~= DataList.Character) then
								replicate.Parent = nil
							else
								if c ~= "Adornee" then replicate[c] = h[c] end
								replicate.Parent = Method2CharacterFolder:FindFirstChild(PlayerName) or Method2CharacterFolder
							end
						end)
						table.insert(AllConnect, changed)
						-- Destroying also covers destruction without a Changed("Parent") event.
						destroyingConn = h.Destroying:Connect(cleanupHighlight)
						table.insert(AllConnect, destroyingConn)
					end
				end
			end

			for Part, Property in pairs(DataList.CurrentPartList.RealtimeUpdateList.Mesh) do
				local Removed = false

				local Base = Property.Base
				if Part.Parent == nil or Function.FallenPartCheck(Part) or not Base then
					if Property.transparencyConn then pcall(function() Property.transparencyConn:Disconnect() end); Property.transparencyConn=nil end  -- V4.4.2 (round 2): disconnect before dropping (was leaked when a proxy part is removed mid-loop while its base survives)
					DataList.CurrentPartList.RealtimeUpdateList.Mesh[Part] = nil
					Removed = true
				end
				if Removed == false and liveCharacter then
					Base = liveCharacter:FindFirstChild(Base.Name)
				end

				if Removed == false then
					local Base = Property.Base
					local CFRAME = Property.CFrame
					local CFRAME1 = Property.CFrame1
					local SIZE = Property.Size
					local Weld = Property.Weld

					if liveCharacter then
						Base = liveCharacter:FindFirstChild(Base.Name)
					end
					if Base and CFRAME and CFRAME1 and SIZE and Weld then
						local scaleInfo = getMeshScaleInfo(Base)
						local XMultiply, YMultiply, ZMultiply = scaleInfo.XMultiply, scaleInfo.YMultiply, scaleInfo.ZMultiply

						local CCFRAME = CFrame.new(CFRAME.Position.X * XMultiply, CFRAME.Position.Y * YMultiply, CFRAME.Position.Z * ZMultiply) * CFRAME.Rotation
						local CCFRAME1 = CFrame.new(CFRAME1.Position.X * XMultiply, CFRAME1.Position.Y * YMultiply, CFRAME1.Position.Z * ZMultiply) * CFRAME1.Rotation

						do
							-- V4.3.134: per-part persistent offsets. Multi-targets share the primary GizmoOffset.
							-- All other parts use GizmoOffsets[Part.Name] (auto-persisted via table reference).
							local _isMulti = DataList.GizmoMultiTargets and DataList.GizmoMultiTargets[Part.Name]
							local go = _isMulti and DataList.GizmoOffset
								or (DataList.GizmoOffsets and DataList.GizmoOffsets[Part.Name])
							if go then
								local _c1Inv = CCFRAME1:Inverse()
								-- V4.3.526 Fix 8: type-check RotCF to defend against unsanitized peer values.
								CCFRAME = CCFRAME * _c1Inv * CFrame.new(go.PosX or 0, go.PosY or 0, go.PosZ or 0) * ((typeof(go.RotCF) == "CFrame" and go.RotCF) or CFrame.new()) * CCFRAME1
							end
						end

						-- V4.3.168.8: compute target Size once (was allocating 2 Vector3s per
						-- part per frame - one for the `~=` compare and a second identical one
						-- for the assignment). Saves ~1 Vector3 alloc per part per frame.
						local _targetSize = Vector3.new(SIZE.X * XMultiply, SIZE.Y * YMultiply, SIZE.Z * ZMultiply)
						if DataList.MeshSizeLock == false and not DataList.CurrentPartList.BodyPartPhysics[Part] then
							if Part.Size ~= _targetSize then
								Part.Size = _targetSize
							end
							if Weld.C0 ~= CCFRAME then
								Weld.C0 = CCFRAME
							end
							if Weld.C1 ~= CCFRAME1 then
								Weld.C1 = CCFRAME1
							end
						elseif DataList.MeshSizeLock == false and DataList.CurrentPartList.BodyPartPhysics[Part] then
							if Part.Size ~= _targetSize then
								Part.Size = _targetSize
							end
							if DataList.CurrentPartList.BodyPartPhysics[Part].CF ~= CCFRAME then
								DataList.CurrentPartList.BodyPartPhysics[Part].CF = CCFRAME
							end
							if DataList.CurrentPartList.BodyPartPhysics[Part].CF1 ~= CCFRAME1 then
								DataList.CurrentPartList.BodyPartPhysics[Part].CF1 = CCFRAME1
							end
						end
					end

					if DataList.RealtimeBodyTransparency == true and not Property.FPOnly then  -- FP FIX: skip the base-Transparency mirror for FP-only breast entries (they carry no geometry; mirroring Torso.Transparency onto them would un-hide a bra-hidden breast + spin up a needless signal conn)
						local actualBase = Property.Base
						if liveCharacter then
							actualBase = liveCharacter:FindFirstChild(Property.Base.Name)
						end
						if actualBase then
							-- Lazy-init signal: connect once per part, reconnect if the base instance
						-- changed (e.g. character respawned - new instance, same name).
							if Property.transparencyConn and Property._connectedBase ~= actualBase then
								Property.transparencyConn:Disconnect()
								Property.transparencyConn = nil
							end
							if not Property.transparencyConn then
								Property.transparencyDirty = true
								Property._connectedBase = actualBase
								Property.transparencyConn = actualBase:GetPropertyChangedSignal("Transparency"):Connect(function()
									Property.transparencyDirty = true
								end)
							end
							if Property.transparencyDirty then
								Property.transparencyDirty = false
								local updated = false
								if actualBase.Transparency ~= DataList.OldTransparency[actualBase] then
									Part.Transparency = math.clamp(actualBase.Transparency,Part:GetAttribute("MaxTransparencyRC") or -math.huge,math.huge)
									updated = true
								end
								if Part.Transparency ~= Part:GetAttribute("MaxTransparencyRC") and
									(Part.Transparency ~= actualBase.Transparency or Part.Transparency == actualBase.Transparency and updated == false and Part:GetAttribute("maxDeterminedRC") == false) then
									Part:SetAttribute("maxDeterminedRC",false)
									Part:SetAttribute("MaxTransparencyRC",Part.Transparency)
								elseif Part.Transparency ~= Part:GetAttribute("MaxTransparencyRC") and
									Part.Transparency == actualBase.Transparency and updated == true then
									Part:SetAttribute("maxDeterminedRC",true)
								end
								Part.Transparency = math.clamp(actualBase.Transparency,Part:GetAttribute("MaxTransparencyRC") or -math.huge,math.huge)
								if Part.Transparency == actualBase.Transparency then
									Part:SetAttribute("maxDeterminedRC",true)
								end
							end
						end
					end
					if PlayerName == lP.Name then
						if DataList.LocalTransparency[Property.Base.Name] == true
							or (System.R15ToR6Name[Property.Base.Name] and DataList.LocalTransparency[System.R15ToR6Name[Property.Base.Name]] == true) then  -- FP FIX: a Type-6 breast's Base is the (R15) UpperTorso; map to the R6 name the body-map toggle writes (mirrors the Accessory loop), else the breast stays faded in first person even with the part toggled SHOWN
							Part.LocalTransparencyModifier = Part.Transparency
						elseif ((DataList and DataList.MethodAtBuild) or Method) == 2 then  -- V4.3.449
							if lP.Character and lP.Character:FindFirstChild("HumanoidRootPart") then
								local chr = lP.Character

								if currentCamera then
									local distance = (currentFocus.p - currentCFrame.p).magnitude
									local transparency = (distance<2) and (1.0-(distance-0.5)/1.5) or 0
									if transparency < 0.5 then
										transparency = 0
									end

									transparency = math.clamp(Function.Round(transparency, 2), 0, 1)
									if transparency >= 0.85 then
										transparency = 1
									end
									if Part.LocalTransparencyModifier ~= transparency then
										if math.abs(Part.LocalTransparencyModifier-transparency) > .4 or Part.LocalTransparencyModifier > .95 then
											Part.LocalTransparencyModifier = transparency
										else
											Part.LocalTransparencyModifier = Part.LocalTransparencyModifier + (transparency - Part.LocalTransparencyModifier) * .2
										end
									end
								end
							end
						end
					end

					if Part.Material == Enum.Material.Glass and Part.Transparency >= 1 then
						Part:AddTag("RCGlassMat")
						Part.Material = Enum.Material.Neon
					elseif Part.Material == Enum.Material.Neon and Part:HasTag("RCGlassMat") and Part.Transparency < 1 then
						Part:RemoveTag("RCGlassMat")
						Part.Material = Enum.Material.Glass
					end
				end
			end

			for Part, Property in pairs(DataList.CurrentPartList.RealtimeUpdateList.Accessory) do
				local Removed = false

				if Part.Parent == nil or Function.IsParentNil(Part) or Function.FallenPartCheck(Part) then
					DataList.CurrentPartList.RealtimeUpdateList.Accessory[Part] = nil

					Removed = true
				end

				if Removed == false then
					local Base = Property.Base
					local Attach = Property.Attachment
					local PAttach = Property.ParentAttachment
					local CF = Property.CFrame
					local Size = Property.Size
					local Scale = Property.Scale
					local SpecialMesh = Property.SpecialMesh
					local Weld = Property.Weld

					local PAttachCFrame = AttachmentCFrame[PAttach.Name] or CFrame.new()  -- BUGFIX (defensive): a stale/renamed attachment name absent from AttachmentCFrame left this nil, then `.Position` threw every frame in this RenderStepped loop. Default to identity.
					local scaleInfo = getAccessoryScaleInfo(Base)
					local XMultiply, YMultiply, ZMultiply = scaleInfo.XMultiply, scaleInfo.YMultiply, scaleInfo.ZMultiply

					if DataList.RealtimeBodyTransparency == true and not _RC_pendingFadeTweens[Part] then
						local alpha = Part:GetAttribute("_RC_HPHidden") and 1
							or math.max(Base.Transparency, Part:GetAttribute("_RC_HPBaseTransparency") or 0)
						if Part.Transparency ~= alpha then Part.Transparency = alpha end
					end
					if PlayerName == lP.Name then
						local isPartHidden = false
						-- Rig-Aware Transparency Check
						if DataList.LocalTransparency[Base.Name] == true then
							isPartHidden = true
						else
							-- V4.3.460: direct R15→R6 lookup. Pre-fix walked 6 RigMap entries
							-- + table.find per entry, per accessory per player per frame.
							local _r6 = System.R15ToR6Name[Base.Name]
							if _r6 and DataList.LocalTransparency[_r6] == true then
								isPartHidden = true
							end
							-- Legacy pair-walk retained as a safety net for any rig name not in
							-- R15ToR6Name (e.g., future Roblox rig additions). When R15ToR6Name
							-- catches a hit, this loop doesn't execute (isPartHidden already true).
							if not isPartHidden then
							for r6Name, r15Parts in pairs(RigMap) do
								if table.find(r15Parts, Base.Name) and DataList.LocalTransparency[r6Name] == true then
									isPartHidden = true
									break
								end
							end
							end  -- V4.3.460: close `if not isPartHidden then` (skips legacy walk when direct lookup already caught it)
						end

						if isPartHidden and DataList.LocalTransparency["Hat"] == true then
							if Part.LocalTransparencyModifier ~= Part.Transparency then
								Part.LocalTransparencyModifier = Part.Transparency
							end
						elseif ((DataList and DataList.MethodAtBuild) or Method) == 2 then  -- V4.3.449
							if lP.Character and lP.Character:FindFirstChild("HumanoidRootPart") then
								local chr = lP.Character

								if currentCamera then
									local distance = (currentFocus.p - currentCFrame.p).magnitude
									local transparency = (distance<2) and (1.0-(distance-0.5)/1.5) or 0
									if transparency < 0.5 then
										transparency = 0
									end

									transparency = math.clamp(Function.Round(transparency, 2), 0, 1)
									if transparency >= 0.85 then
										transparency = 1
									end
									if Part.LocalTransparencyModifier ~= transparency then
										if math.abs(Part.LocalTransparencyModifier-transparency) > .4 or Part.LocalTransparencyModifier > .95 then
											Part.LocalTransparencyModifier = transparency
										else
											Part.LocalTransparencyModifier = Part.LocalTransparencyModifier + (transparency - Part.LocalTransparencyModifier) * .2
										end
									end
								end
							end
						end
					end

					if DataList.AccessorySizeLock == false then
						local targetSize = Vector3.new(Size.X * XMultiply, Size.Y * YMultiply, Size.Z * ZMultiply)
						if Part.Size ~= targetSize then
							Part.Size = targetSize
						end
						if SpecialMesh then
							local targetScale = Vector3.new(Scale.X * XMultiply, Scale.Y * YMultiply, Scale.Z * ZMultiply)
							if SpecialMesh.Scale ~= targetScale then
								SpecialMesh.Scale = targetScale
							end
						end
						if not DataList.CurrentPartList.physicsTails[Part.Parent] then
							local attachCFrame = CFrame.new(CF.Position.X * XMultiply, CF.Position.Y * YMultiply, CF.Position.Z * ZMultiply) * CF.Rotation
							local parentAttachCFrame = CFrame.new(PAttachCFrame.Position.X * XMultiply, PAttachCFrame.Position.Y * YMultiply, PAttachCFrame.Position.Z * ZMultiply) * PAttachCFrame.Rotation
							if Attach.CFrame ~= attachCFrame then
								Attach.CFrame = attachCFrame
							end
							if PAttach.CFrame ~= parentAttachCFrame then
								PAttach.CFrame = parentAttachCFrame
							end
							do
								local _accKey = "acc:" .. Part.Parent.Name
								local _go = DataList.GizmoOffsets and DataList.GizmoOffsets[_accKey]
								local targetC0 = Attach.CFrame
								if _go then
									local _paCFInv = parentAttachCFrame:Inverse()
									_go.baseC0 = Attach.CFrame
									-- V4.3.526 Fix 8: type-check RotCF (see sibling guards).
									targetC0 = Attach.CFrame * _paCFInv * CFrame.new(_go.PosX or 0, _go.PosY or 0, _go.PosZ or 0) * ((typeof(_go.RotCF) == "CFrame" and _go.RotCF) or CFrame.new()) * parentAttachCFrame
								end
								if Weld.C0 ~= targetC0 then
									Weld.C0 = targetC0
								end
							end
							if Weld.C1 ~= parentAttachCFrame then
								Weld.C1 = parentAttachCFrame
							end
						end
					end
				end
			end

			-- Accessory gimbal offset for accessories NOT tracked in RealtimeUpdateList.Accessory.
			-- RealtimeUpdateList.Accessory only contains accessories re-created on the proxy (bundle loaded).
			-- Without a bundle, accessories live on the real character and need this separate writer.
			-- Skips any handle already written by the size loop above to avoid double-writes.
			do
				local accLoop = DataList.CurrentPartList
					and DataList.CurrentPartList.RealtimeUpdateList
					and DataList.CurrentPartList.RealtimeUpdateList.Accessory
				local offsets = DataList.GizmoOffsets
				if offsets then
					local char = Function.ResolveTargetChar(PlayerName)
					if char then
						for key, go in pairs(offsets) do
							if type(key) == "string" and key:sub(1, 4) == "acc:" then
								local acc = char:FindFirstChild(key:sub(5))
								local handle = acc and acc:IsA("Accessory") and acc:FindFirstChild("Handle")
								if handle and (not accLoop or not accLoop[handle]) then
									local weld = handle:FindFirstChildWhichIsA("Weld")
									if weld and weld.Part0 then
										-- V4.3.162 H4 fix: recapture base CFrames when the Weld identity changes
										-- (respawn / bundle re-attach) so stale baseC0/baseC1 don't cause orbit regression.
										if go.baseWeld ~= weld then
											go.baseWeld = weld
											go.baseC0 = weld.C0
											go.baseC1 = weld.C1
										end
										if not go.baseC0 then go.baseC0 = weld.C0 end
										if not go.baseC1 then go.baseC1 = weld.C1 end
										local _c1Inv = go.baseC1:Inverse()
										-- V4.3.526 Fix 8: type-check RotCF (see sibling guards).
										weld.C0 = go.baseC0 * _c1Inv * CFrame.new(go.PosX or 0, go.PosY or 0, go.PosZ or 0) * ((typeof(go.RotCF) == "CFrame" and go.RotCF) or CFrame.new()) * go.baseC1
										weld.C1 = go.baseC1
									end
								end
							end
						end
					end
				end
			end

			for SpecialMesh, Property in pairs(DataList.CurrentPartList.RealtimeUpdateList.SpecialMesh) do
				local Removed = false

				if SpecialMesh.Parent == nil or Function.IsParentNil(SpecialMesh) or Function.FallenPartCheck(SpecialMesh) then
					DataList.CurrentPartList.RealtimeUpdateList.SpecialMesh[SpecialMesh] = nil

					Removed = true
				end

				if Removed == false then
					local Base = Property.Base
					local SIZE = Property.Size

					if (((DataList and DataList.MethodAtBuild) or Method) == 2 or ((DataList and DataList.MethodAtBuild) or Method) == 3) and DataList.Character then  -- V4.3.449
						Base = DataList.Character:FindFirstChild(Base.Name)
					end
					if Base and SIZE and SpecialMesh then
						local BodySize = BodyPartSize[Base.Name]
						local CalcSize = Base.Size
						local specialHead = false
						if Base.Name == "Head" and Base:IsA("MeshPart") then
							if Base:FindFirstChild("OriginalSize") then
								BodySize = Base:FindFirstChild("OriginalSize").Value
							else
								BodySize = BodyPartSize["HeadMeshFix"]
							end
						elseif Base.Name == "Head" and Base:FindFirstChildOfClass("SpecialMesh") then
							local SM:SpecialMesh = Base:FindFirstChildOfClass("SpecialMesh")
							if SM.MeshType == Enum.MeshType.Head then
								specialHead = true
								BodySize = BodyPartSize["HeadScale"]
							else
								CalcSize = SM.Scale
								BodySize = BodyPartSize["HeadScale"]
							end
						end

						local XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(CalcSize, BodySize)
						if specialHead == true then
							local SM:SpecialMesh = Base:FindFirstChildOfClass("SpecialMesh")

							if CalcSize.X > CalcSize.Z then
								CalcSize = Vector3.new(CalcSize.Z,CalcSize.Y,CalcSize.Z)
							end
							if CalcSize.Z > CalcSize.X then
								CalcSize = Vector3.new(CalcSize.X,CalcSize.Y,CalcSize.X)
							end
							XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(CalcSize, BodySize)

							local S = SM.Scale
							if S.X > S.Z then
								S = Vector3.new(S.Z,S.Y,S.Z)
							end
							if S.Z > S.X then
								S = Vector3.new(S.X,S.Y,S.X)
							end
							local XMS, YMS, ZMS = Function.MultiplyCalculate(S, vector3New(1.25,1.25,1.25))

							XMultiply = XMultiply*XMS
							YMultiply = YMultiply*YMS
							ZMultiply = ZMultiply*ZMS
						end

						if DataList.MeshSizeLock == false then
							-- V4.3.168.8: same per-frame dedup as the Mesh-part loop above -
							-- compute target Vector3 once, compare, assign. Saves 1 Vector3
							-- alloc per SpecialMesh per frame.
							local _targetScale = Vector3.new(SIZE.X * XMultiply, SIZE.Y * YMultiply, SIZE.Z * ZMultiply)
							if SpecialMesh.Scale ~= _targetScale then
								SpecialMesh.Scale = _targetScale
							end
						end
					end
				end
			end

			for i, v in pairs(DataList.CurrentPartList.RealtimeUpdateList.Special) do
				local Removed = false

				if v.Parent == nil or Function.IsParentNil(v) then
					-- V4.3.441: Destroy the orphan Attachment + its ParticleEmitter
					-- when its parent dies so the engine actually reclaims it. Pre-fix
					-- the entry was nil'd out of the table but the Attachment lived on
					-- a soon-to-be-reparented MeshPart until the part itself died.
					pcall(function() v:Destroy() end)
					DataList.CurrentPartList.RealtimeUpdateList.Special[i] = nil

					Removed = true
				end

				if Removed == false then
					if v.Name == "cTrail" then
						local origin = v.Parent
						local particle = v:FindFirstChildOfClass("ParticleEmitter")
						if not particle then
							pcall(function() v:Destroy() end)  -- V4.3.441
							DataList.CurrentPartList.RealtimeUpdateList.Special[i] = nil
							continue
						end
						if particle:GetAttribute("Enabled") ~= false then
							-- Exclude owned roots: Roblox filters every descendant, including
							-- accessories added after this list is cached.
							System._cTrailIgnoreCache = System._cTrailIgnoreCache or {}
							local _cache = System._cTrailIgnoreCache
							local _curChar = Player.Character
							local changed = _cache.collisionLen ~= #collisionList
								or _cache.lastChar ~= _curChar or _cache.lastFolder ~= Method2CharacterFolder
								or _cache.dirty or not _cache.list
							if not changed then
								for index, part in ipairs(collisionList) do
									if _cache.list[index] ~= part then changed = true; break end
								end
							end
							if changed then
								local list = _cache.list or {}
								table.clear(list)
								for _, part in ipairs(collisionList) do table.insert(list, part) end
								if _curChar then table.insert(list, _curChar) end
								if Method2CharacterFolder then table.insert(list, Method2CharacterFolder) end
								_cache.list, _cache.collisionLen = list, #collisionList
								_cache.lastChar, _cache.lastFolder = _curChar, Method2CharacterFolder
								_cache.dirty = false
							end
							local ignoreList = _cache.list
							-- V4.3.300: reuse a single RaycastParams across cTrail iterations.
							-- Pre-fix, every cTrail loop iteration allocated a fresh `RaycastParams.new()`
							-- + populated FilterType. Reusing saves the per-frame allocation; only the
							-- (necessarily fresh) ignoreList changes between iterations.
							if not System._cTrailGroundParams then
								local _gp = RaycastParams.new()
								_gp.FilterType = Enum.RaycastFilterType.Exclude
								System._cTrailGroundParams = _gp
							end
							System._cTrailGroundParams.FilterDescendantsInstances = ignoreList
							local _groundResult = workspace:Raycast(origin.Position, Vector3.new(0,-10000,0), System._cTrailGroundParams)
							local instance = _groundResult and _groundResult.Instance
							local hit = _groundResult and _groundResult.Position
							if hit and instance and instance:IsA("BasePart") then
								if instance.CanCollide == false and not collisionChecks[instance] then
									-- V4.3.441: 256-entry FIFO cap on collisionList so cTrail-only
									-- grounded rays don't grow it without bound when FPerson is off.
									-- Pre-fix the FPerson loop's cap at L14563 was the only sink;
									-- with FPerson disabled the list grew per-unique-hit forever.
									if #collisionList >= 256 then
										-- V4.3.504: mirror L17227 FPerson-site cleanup. Pre-fix the FIFO
										-- evict only popped the list entry; the GetPropertyChangedSignal
										-- connection in collisionChecks[oldest] leaked.
										local oldest = table.remove(collisionList, 1)
										if oldest then
											local conn = collisionChecks[oldest]
											if conn then
												local _ci = table.find(AllConnect, conn)
												if _ci then table.remove(AllConnect, _ci) end
												pcall(function() conn:Disconnect() end)
											end
											collisionChecks[oldest] = nil
										end
									end
									table.insert(collisionList,instance)
									_cache.dirty = true  -- V4.3.505: collisionList changed; rebuild ignore list
									-- V4.3.278: mirror the L11904 self-disconnect arm. Without this,
									-- every grounded ray hit on a unique non-collidable part registers
									-- a permanent GetPropertyChangedSignal that leaks until full re-exec.
									local collisionChange; collisionChange = instance:GetPropertyChangedSignal("CanCollide"):Connect(function()
										if instance.CanCollide == false and not table.find(collisionList,instance) then
											table.insert(collisionList,instance)
											_cache.dirty = true  -- V4.3.505: rebuild ignore list on re-insert
										elseif instance.CanCollide == true then
											local idx = table.find(collisionList,instance)
											if idx then table.remove(collisionList,idx) end
											_cache.dirty = true  -- V4.3.505: rebuild ignore list on remove
											local _ci = table.find(AllConnect, collisionChange)
											if _ci then table.remove(AllConnect, _ci) end
											collisionChange:Disconnect()
											collisionChecks[instance] = nil
										end
									end)
									collisionChecks[instance] = collisionChange
									table.insert(AllConnect, collisionChange)
								else
									particle.Enabled = true
									v.WorldCFrame = CFrame.new(hit) --* instance.CFrame.Rotation
								end
							else
								particle.Enabled = false
							end
						else
							particle.Enabled = false
						end
					elseif v.Name == "nCensor" and v:FindFirstChildOfClass("ObjectValue") then
						local origin = v:FindFirstChildOfClass("ObjectValue")
						if origin.Value and origin.Value.Parent ~= nil then
							local tors = origin.Value.Parent
							local LNipple:MeshPart
							local RNipple:MeshPart

							if tors:FindFirstChild("Left Breast") and tors:FindFirstChild("Left Breast"):FindFirstChild("Nipple") then
								LNipple = tors["Left Breast"]["Nipple"]
							end
							if tors:FindFirstChild("Right Breast") and tors:FindFirstChild("Right Breast"):FindFirstChild("Nipple") then
								RNipple = tors["Right Breast"]["Nipple"]
							end
							if tors and LNipple and RNipple and v:FindFirstChildOfClass("Frame") then
								local angle = math.acos(
									math.clamp(
										currentCFrame.LookVector:Dot(tors.CFrame.LookVector),
										-1, 1)
								)

								if angle > math.pi/2.8 and (LNipple.Transparency < 1 or RNipple.Transparency < 1) then
									local corners = {
										RNipple.CFrame * Vector3.new(-.45, -.3, -.3),
										LNipple.CFrame * Vector3.new(-.45, -.3, .3),
										RNipple.CFrame * Vector3.new(-.45, .3, -.3),
										LNipple.CFrame * Vector3.new(-.45, .3, .3),
										RNipple.CFrame * Vector3.new(.45, -.3, -.3),
										LNipple.CFrame * Vector3.new(.45, -.3, .3),
										RNipple.CFrame * Vector3.new(.45, .3, -.3),
										LNipple.CFrame * Vector3.new(.45, .3, .3)
									}

									local minX, minY = math.huge, math.huge
									local maxX, maxY = -math.huge, -math.huge

									-- V4.5.24 Fix: guard the projection against a nil camera (switch/respawn
									-- frame). Pre-fix currentCamera:WorldToScreenPoint threw inside the
									-- RenderStepped callback, permanently dropping the binding for the session.
									local screenBoundingBox
									if currentCamera then
										-- Project to screen space
										for _, corner in ipairs(corners) do
											local screenPos, onScreen = currentCamera:WorldToScreenPoint(corner)
											minX = math.min(minX, screenPos.X)
											minY = math.min(minY, screenPos.Y)
											maxX = math.max(maxX, screenPos.X)
											maxY = math.max(maxY, screenPos.Y)
										end
										-- Screen-aligned bounding box
										screenBoundingBox = {
											x = minX,
											y = minY,
											width = maxX - minX,
											height = maxY - minY
										}
									end

									if screenBoundingBox then
										v.Frame.Position = UDim2.new(0, screenBoundingBox.x, 0, screenBoundingBox.y)
										v.Frame.Size = UDim2.new(0, screenBoundingBox.width, 0, screenBoundingBox.height)
										v.Frame.Visible = true
									else
										v.Frame.Visible = false
									end
								else
									v.Frame.Visible = false
								end
							end
						else
							v:Destroy()
							DataList.CurrentPartList.RealtimeUpdateList.Special[i] = nil
						end
					end
				end
			end

			for Part, Property in pairs(DataList.CurrentPartList.ParentTransparency) do
				local Removed = false

				if Part.Parent == nil or Function.IsParentNil(Part) or Function.FallenPartCheck(Part) then
					DataList.CurrentPartList.ParentTransparency[Part] = nil

					Removed = true
				end

				if Removed == false then
					local T = Property.T

					if T then
						PlayerData[PlayerName].OldTransparency[Part] = Part.Transparency
						if PlayerData[PlayerName].RealtimeBodyTransparency == true then
							Part.LocalTransparencyModifier = T
						else
							if not PlayerData[PlayerName].CurrentPartList.OriginalTransparency[Part] then
								PlayerData[PlayerName].CurrentPartList.OriginalTransparency[Part] = Part.Transparency
							end
							Part.Transparency = T
						end
					end
				end
			end

			for Part, Property in pairs(DataList.CurrentPartList.Link) do
				local Removed = false

				if Part.Parent == nil or Function.IsParentNil(Part) or Function.FallenPartCheck(Part) then
					DataList.CurrentPartList.Link[Part] = nil

					Removed = true
				end

				if Removed == false then
					local T = Property.T.Transparency
					local D = Property.Define or 0
					local _maxTRC = Part:GetAttribute("MaxTransparencyRC")  -- cache: was called 2-3x per part
					if _maxTRC and D < _maxTRC then D = _maxTRC end

					Part.LocalTransparencyModifier = math.clamp(Property.T.LocalTransparencyModifier,D,math.huge)
					Part.Transparency = math.clamp(T,D,math.huge)

					if Property.Color and Property.Color.Color then
						Part.Color = Property.Color.Color
					end
				end
			end

			for Decal, Part in pairs(DataList.CurrentPartList.AreolaDecal) do
				local Removed = false

				if Part.Parent == nil or Function.IsParentNil(Part) or Function.FallenPartCheck(Part) then
					DataList.CurrentPartList.AreolaDecal[Decal] = nil

					Removed = true
				end

				if Removed == false then
					-- V4.3.353: AreolaDecalUVCreate registers a SurfaceAppearance (not a
					-- Decal) into this table; SA has no Transparency / LTM properties, so
					-- skip the writes for it. SA visibility inherits from the parent
					-- MeshPart's Transparency naturally → no visual difference.
					if Decal:IsA("Decal") then
