	function Function.compileOvertime()
		if not (env.listfiles and env.readfile and env.writefile and env.delfile and env.isfile) then
			return
		end
		task.spawn(function()
			-- V4.3.515 Fix 6: pcall like sibling sites at L17745/L17750/L17817 - some executors throw on missing folder.
			local _okLF, filesFound = pcall(env.listfiles, "RClothesLerp/Bundles")
			if not _okLF or type(filesFound) ~= "table" then filesFound = {} end
			local t = {}
			for i, v in pairs(filesFound) do
				if env.isfile(v) then
					local _okRB, _rawB = pcall(env.readfile, v)
								if not _okRB then continue end
								local _okDB, b = pcall(HS.JSONDecode, HS, _rawB)
								if not _okDB or type(b) ~= "table" then continue end
					-- V4.3.520 Fix 15: skip entries with missing BundleName (sibling site).
					local storedName = b.BundleName
					if not storedName or type(storedName) ~= "string" or #storedName == 0 then
						continue
					end
					b["BundleName"] = nil

					local function fromJSON(t)
						for i, v in pairs(t) do
							local value,original = Function.convertFromJSON(v)
							t[i] = value
							if typeof(v) == "table" and original then
								fromJSON(v)
							end
						end
					end
					fromJSON(b)

					t[storedName] = b
				end
			end
			local function toJSON(t)
				for i, v in pairs(t) do
					if typeof(v) == "table" then
						toJSON(v)
					else
						t[i] = Function.convertToJSON(v)
					end
				end
			end
			toJSON(t)
			if #filesFound > 0 then
				-- V4.3.504: atomic write.
				-- V4.3.541 Fix 6: capture return; silent disk-write failure here
				-- meant compileOvertime's rebuild produced no on-disk
				-- BundleLoader.json, so next session's quick-load found stale
				-- (or no) cache and re-walked per-file from scratch. Sibling
				-- class to V4.3.531/533/534 _atomicWriteJSON capture hardening.
				local _ovOk = _atomicWriteJSON("RClothesLerp/BundleLoader.json", t)
				if not _ovOk then
					_diagPublicCall("bundle.compileovertime_write_fail", {})
				end
			else
				-- V4.3.515 Fix 7: pcall-wrap delfile.
				pcall(env.delfile, "RClothesLerp/BundleLoader.json")
			end
		end)
	end


