			-- ----------------------------------------------------------------------------
			-- This function was trapped in the deleted GUI layer (orig handleBundleClick
			-- region, def at orig L26719-26797) and removed during the headless teardown.
			-- The torn-down engine still REFERENCES it in six places, all guarded with
			-- `if Function.ResetBundleSettableFields then pcall(...)`:
			--   * System.doReset            (engine L~8211, Player page Reset button)
			--   * System.applyBundle        (engine L~24393 / L~24418 / L~24425, the three
			--                                handleBundleClick reset branches)
			--   * System.clearBundle        (engine L~24517, the "nil" tile CLEAR path)
			-- Without the real definition those guards silently no-op, so applying or
			-- resetting a bundle left the previous bundle's scalar / body / clothing fields
			-- bleeding into the next selection (the exact cross-bundle-bleed class the
			-- original V4.3.143/280/534 fixes hardened this list against). Re-added here
			-- 1:1 from the original (same field list, same literal defaults, same V4.3.x
			-- rationale comments) so every reference resolves. Defined inside the P6 do...end
			-- block where Function + PlayerData are in scope (= 0 RoClothes registers); the
			-- block runs during RoClothes() setup, before any of the lazy System.* closures
			-- above can fire on a user action, so the guards now find it present.
			-- Resets the per-player bundle-settable fields on PlayerData[name] back to their
			-- defaults. Faithful reproduction of orig L26719-26797.
			function Function.ResetBundleSettableFields(name)
				local pd = PlayerData[name]
				if not pd then return end
				pd.BreastsType              = 1
				pd.TorsoType                = 1
				pd.ArmType                  = 1
				pd.LegsType                 = 1
				pd.ButtType                 = 1
				pd.BreastsScale             = 1
				pd.ButtsScale               = 1
				pd.LegsScale                = 1
				pd.TorsoScale               = 1
				pd.LeftArmScale             = 1
				pd.RightArmScale            = 1
				pd.CockScale                = 1
				pd.BodyPartPhysics          = false
				pd.Tone                     = "Base"
				pd.RealtimeBodyTransparency = true
				pd.Face                     = true
				pd.AccessorySizeLock        = false
				pd.PhysicsObeyGravity       = true
				pd.TopHP                    = ""
				pd.BottomHP                 = ""
				-- V4.3.422: clear ripped flags on bundle reset.
				pd.TopRipped                = false
				pd.BottomRipped             = false
				pd.HardcoreHP               = false
				pd.DamageSFX                = ""
				pd.Volume                   = 1
				pd.NippleColor              = nil
				pd.NippleColorFromBundle    = false
				pd.SmartBoneEnabled         = false
				pd.TearParticles            = true
				pd.HealParticles            = true
				pd.MeshSizeLock             = false
				pd.MeshBasePartInvisible    = false
				pd.BreathingEnabled         = false
				pd.OvertoneEnabled          = false
				pd.BreathingAmplitude       = 0.03
				pd.OvertoneAmplitude        = 0.015
				-- V4.3.280: previously-missing fields (cross-bundle bleed sources).
				pd.CatalogAccessory         = {}
				pd.CatalogTail              = {}
				pd.CatalogRemove            = {}
				pd.CatalogClothes           = {Shirt = "", Pants = "", ShirtGraphic = ""}
				pd.CatalogBundleId          = ""
				pd.HPClothes                = {Shirt = "", Pants = ""}
				pd.BundleBodyColor          = true
				-- V4.3.534 F13: FPerson + BodyTransparency reset (cross-bundle bleed sources
				-- the V4.3.280 fix missed). Both are captured into preset only when ~= default,
				-- so switching from a bundle that captured the non-default to a bundle that
				-- omits it left the prior bundle's non-default value in pd.
				pd.FPerson                  = false
				pd.BodyTransparency         = 0
				-- V4.3.534 F11: FPsnap + HeadTracking reset (sibling fields to FPerson, same
				-- cross-bundle bleed pattern now that they are captured + allowlisted).
				pd.FPsnap                   = false
				pd.HeadTracking             = false
				pd.BreastsStiffness         = 10
				pd.BreastsDamping           = 0.207
				pd.ButtsStiffness           = 10
				pd.ButtsDamping             = 0.1
				pd.CockStiffness            = 8
				pd.CockDamping              = 0.207
				-- V4.3.539 Fix 1: clear ClothesRecolor / ClothesHP / AccessoryHP / StripOnRipMap
				-- so a reset removes orphan rows from the Recolor / HP renderers (they read
				-- pd.ClothesRecolor as ground-truth). Mirrors ApplyBundleToPeerData +
				-- StripAllClothes which already wipe these on their lifecycle.
				pd.ClothesRecolor           = {}
				pd.ClothesHP                = {}
				pd.AccessoryHP              = {}
				pd.StripOnRipMap            = {}
			end

			-- Inline reproduction of the original scrubClothState(cloth) (orig L26218-26237):
			-- clear stale per-cloth ClothesHP / ClothesRecolor / StripOnRipMap so a re-equip or
			-- bundle swap never re-fires a dead inverse-HP entry. cloth==nil => full scrub.
			local function _scrubCloth(pd, cloth)
				if not pd then return end
				if cloth == nil then
					pd.ClothesHP = {}; pd.AccessoryHP = {}; pd.ClothesRecolor = {}; pd.StripOnRipMap = {}
				else
					if pd.ClothesHP then pd.ClothesHP[cloth] = nil end
					if pd.ClothesRecolor then pd.ClothesRecolor[cloth] = nil end
					if pd.StripOnRipMap then pd.StripOnRipMap[cloth] = nil end
				end
			end

			-- Returns a sorted array of {name, hidden, krulHosted, equipped}. The GUI skips
			-- `hidden` entries (orig L4531 / L8959: Breast Clothes SB1/SB2 are exposed via the
			-- BreastsCover cycle, not the Clothes tab) and applies tab/search itself. Sorted by
			-- name to match the original button sort (orig L27422-27424 / L33625).
			System.getClothesList = function()
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				local equipped = {}
				if pd and pd.CurrentClothes then
					for _, n in ipairs(pd.CurrentClothes) do equipped[n] = true end
				end
				local out = {}
				if Clothes then
					for name, def in pairs(Clothes) do
						-- guard the sentinel "nil" key + non-table garbage; mirror the builder's skip set
						if type(name) == "string" and name ~= "nil" and type(def) == "table" then
							out[#out+1] = {
								name = name,
								hidden = def.Hidden == true,
								krulHosted = def.KrulHosted == true,
								equipped = equipped[name] == true,
							}
						end
					end
				end
				table.sort(out, function(a, b) return a.name < b.name end)
				return out
			end

			System.isClothEquipped = function(name)
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				if not (pd and pd.CurrentClothes and name) then return false end
				return table.find(pd.CurrentClothes, name) ~= nil
			end

			-- Clear the shared KrulType pending markers (used when the GUI KrulType modal is
			-- cancelled, so the engine's own popup path -- which reads the same locals at
			-- L23299-23304 -- is not left armed).
			System.clearClothPending = function()
				_pendingKrulCloth = nil; _pendingKrulPlayer = nil
			end

			-- A KrulHosted cloth always asks Shirt/Pants on equip (orig L33604 comment: "Always
			-- ask shirt or pants even if previously chosen -- lets user change type"). Non-Krul
			-- clothes equip directly via toggleCloth. The GUI calls this BEFORE toggling so it
			-- can route an equip-from-unequipped through the KrulType modal instead.
			System.clothNeedsType = function(name)
				return Clothes ~= nil and Clothes[name] ~= nil and Clothes[name].KrulHosted == true
			end

			-- Equip / unequip a (non-KrulHosted) cloth, reproducing the original click handler
			-- 1:1 (orig L4538-4609): toggle membership in pd.CurrentClothes; on equip set up the
			-- recolor flag (Weld part has PartList[w].Recolor), blacklist removal (+scrub), and the
			-- cycle-format default HP; on unequip scrub state. Then re-render recolor (guarded --
			-- the renderer is Phase 7, absent today) and hotSwap (engine reset->execute pipeline).
			-- Returns the new equipped boolean (true=now on) so the GUI can paint the badge.
			System.toggleCloth = function(name)
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				if not (pd and name and Clothes and Clothes[name]) then return nil end
				if not pd.CurrentClothes then pd.CurrentClothes = {} end
				if not pd.ClothesHP then pd.ClothesHP = {} end
				if not pd.ClothesRecolor then pd.ClothesRecolor = {} end
				local nowEquipped
				if not table.find(pd.CurrentClothes, name) then
					-- Equip path (orig L4543-4593)
					table.insert(pd.CurrentClothes, name)
					if Clothes[name].Weld then
						-- flag a recolor row if any welded part is recolourable (orig L4549-4556)
						for _, w in pairs(Clothes[name].Weld) do
							if PartList and PartList[w] and PartList[w].Recolor then
								if not pd.ClothesRecolor[name] then pd.ClothesRecolor[name] = {} end
								break
							end
						end
						-- blacklist removal + scrub (orig L4558-4572)
						if Clothes[name]["Blacklist"] then
							for _, b in pairs(Clothes[name]["Blacklist"]) do
								local idx = table.find(pd.CurrentClothes, b)
								if idx then
									table.remove(pd.CurrentClothes, idx)
									_scrubCloth(pd, b)
								end
							end
							pd._equippedSetSrc = nil  -- orig L4571: force equipped-set cache rebuild
						end
						-- reset then apply default HP in cycle-format (orig L4577-4592)
						pd.ClothesHP[name] = nil
						if Clothes[name]["HP"] then
							local _hp = Clothes[name].HP
							if _hp == 1 then pd.ClothesHP[name] = {HP = "TopHP",    Inverse = false}
							elseif _hp == 2 then pd.ClothesHP[name] = {HP = "BottomHP", Inverse = false}
							elseif _hp == 3 then pd.ClothesHP[name] = {HP = "TopHP",    Inverse = true}
							elseif _hp == 4 then pd.ClothesHP[name] = {HP = "BottomHP", Inverse = true}
							elseif _hp ~= 0 then pd.ClothesHP[name] = {HP = "TopHP",    Inverse = false}
							end
						end
					end
					nowEquipped = true
				else
					-- Unequip path (orig L4595-4603)
					-- V4.5.24 Fix: table.remove inside pairs() over the same array is UB (can skip/
					-- revisit entries). Reverse-ordered numeric loop keeps remove-then-break safe.
					for j = #pd.CurrentClothes, 1, -1 do
						if pd.CurrentClothes[j] == name then
							table.remove(pd.CurrentClothes, j)
							_scrubCloth(pd, name)
							break
						end
					end
					nowEquipped = false
				end
				-- orig tail L4606-4609: renderRecolorList + renderHPList (Phase 7, now wired via the
				-- GUI's registered callbacks; still guarded so the headless engine never nil-calls) +
				-- hotSwap. GUIUpdate is removed -> not called.
				if System.renderRecolorList then pcall(System.renderRecolorList) end
				if System.renderHPList then pcall(System.renderHPList) end
				if hotSwap then hotSwap() end
				return nowEquipped
			end

			-- Resolve a pending KrulHosted cloth's type and equip it (orig Shirt/Pants handlers
			-- L4079-4103 + _krulApplyAndRender L4063-4077). type must be "Shirt" or "Pants".
			-- Remembers the choice in _krulClothTypes, stamps Clothes[name].ClothType, inserts into
			-- CurrentClothes (if not already), then hotSwap (engine reset->execute pipeline).
			System.setClothType = function(name, clothType)
				if not (name and (clothType == "Shirt" or clothType == "Pants")) then return false end
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				if not pd then return false end
				_krulClothTypes[name] = clothType
				if Clothes and Clothes[name] then Clothes[name].ClothType = clothType end
				if not pd.CurrentClothes then pd.CurrentClothes = {} end
				if not table.find(pd.CurrentClothes, name) then
					table.insert(pd.CurrentClothes, name)
				end
				-- clear any stale pending markers shared with the engine's own KrulType popup path
				_pendingKrulCloth = nil; _pendingKrulPlayer = nil
				if System.renderRecolorList then pcall(System.renderRecolorList) end
				if System.renderHPList then pcall(System.renderHPList) end
				if hotSwap then hotSwap() end
				return true
			end

			-- ============================================================================
			-- PHASE 7: RECOLOR + HP + AUTO-STRIP DATA BRIDGE
			-- ----------------------------------------------------------------------------
			-- Read-side helpers return PLAIN data row tables (no Instances); write-side
			-- helpers mutate PD + hotSwap. The file-scope GUI (_buildKrulHubGUI) builds the
			-- actual rows from these and registers its page renderers back onto System (so
			-- the guarded System.renderRecolorList / renderHPList calls above resolve to the
			-- GUI). Every member is a System.X field => 0 RoClothes registers.
			--
			-- Faithfulness map to the ORIGINAL (Ro-Clothes-Krul-V4.3.576.0627.lua):
			--   * recolor row enumeration  -> _buildRecolorRenderer, orig L3786-3934 (equipped
			--       clothes' Weld parts, PartList[part].Recolor slot, dedup, "nil" sentinel,
			--       lazy-prune orphans via the CurrentClothes equipped-set)
			--   * HP cycle state mapping     -> _buildHPRenderer, orig L3944-4049 (0=nil/1=TopHP/
			--       2=BottomHP/3=InverseTop/4=InverseBottom; cloth rows from CurrentClothes,
			--       accessory rows from the live character)
			--   * per-cloth auto-strip        -> _refreshStripConfigDropdown, orig L27559-27665
			--       (StripOnRipMap keyed by clothName; None/Top/Bottom/Both; smart-default by
			--       ClothType; AutoStripOnRip toggle). NOTE: the rip-loop consumer (engine
			--       L20944) is the ONLY consumer of this map -- there is no ApplyStrip call on
			--       this path (that belongs to the Catalog StripCategories path, P9).

			-- RECOLOR -------------------------------------------------------------------
			-- Returns { {cloth=, slot=, current=Color3|nil, default=Color3}, ... } in the same
			-- order the original built rows. Mirrors _buildRecolorRenderer's slot walk + lazy
			-- prune. The "nil" string is written back into pd.ClothesRecolor[cloth][slot] for
			-- unset slots (LOAD-BEARING sentinel, orig L3834) so downstream `~= "nil"` consumers
			-- keep working; `current` is returned as nil for the sentinel so the GUI paints the
			-- part's default colour swatch.
			System.getRecolorRows = function()
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				local out = {}
				if not (pd and pd.ClothesRecolor) then return out end
				local equippedSet = {}
				for _, n in ipairs(pd.CurrentClothes or {}) do equippedSet[n] = true end
				for clothName, slotState in pairs(pd.ClothesRecolor) do
					if not equippedSet[clothName] then
						pd.ClothesRecolor[clothName] = nil  -- orig L3819 lazy prune
					elseif Clothes and Clothes[clothName] and Clothes[clothName].Weld and type(slotState) == "table" then
						local seenSlots = {}
						for _, partName in pairs(Clothes[clothName].Weld) do
							local partMeta = PartList and PartList[partName]
							if partMeta and partMeta.Recolor and not seenSlots[partMeta.Recolor] then
								seenSlots[partMeta.Recolor] = true
								local slot = partMeta.Recolor
								if slotState[slot] == nil then slotState[slot] = "nil" end  -- LOAD-BEARING SENTINEL (orig L3834)
								local currentValue = slotState[slot]
								local defaultColour
								-- partMeta.Color is a Color3Value in the original (partMeta.Color.Color, orig L3836); guard it.
								pcall(function() defaultColour = partMeta.Color and partMeta.Color.Color end)
								out[#out + 1] = {
									cloth = clothName,
									slot = slot,
									current = (typeof(currentValue) == "Color3") and currentValue or nil,
									default = defaultColour or Color3.fromRGB(255, 255, 255),
								}
							end
						end
					end
				end
				return out
			end

			-- Write a chosen Color3 into pd.ClothesRecolor[cloth][slot] then re-apply (orig
			-- swatch Apply L3908-3912). Returns true on success so the GUI can paint the swatch.
			System.setRecolor = function(cloth, slot, colour)
				if not (cloth and slot and typeof(colour) == "Color3") then return false end
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				if not (pd and pd.ClothesRecolor and pd.ClothesRecolor[cloth]) then return false end
				pd.ClothesRecolor[cloth][slot] = colour
				if hotSwap then hotSwap() end
				return true
			end

			-- Reset a slot to the "nil" sentinel (orig reset button L3920) then re-apply.
			System.resetRecolor = function(cloth, slot)
				if not (cloth and slot) then return false end
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				if not (pd and pd.ClothesRecolor and pd.ClothesRecolor[cloth]) then return false end
				pd.ClothesRecolor[cloth][slot] = "nil"  -- LOAD-BEARING SENTINEL
				if hotSwap then hotSwap() end
				return true
			end

			-- HP ------------------------------------------------------------------------
			-- Returns { {label=, state=0..4, accessory=bool}, ... }: cloth rows from
			-- pd.CurrentClothes, then accessory rows from the live character (dedup by name).
			-- Mirrors _buildHPRenderer's enumeration + state read-back (orig L3979-3988). Also
			-- scrubs V4.3.214 threshold-only entries (a set with no .HP field, orig L3974-3977).
			local function _hpStateFromSet(set)
				if type(set) ~= "table" or not set.HP then return 0 end
				if set.HP == "TopHP" then return set.Inverse == true and 3 or 1
				elseif set.HP == "BottomHP" then return set.Inverse == true and 4 or 2 end
				return 0
			end
			System.getHPRows = function()
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				local out = {}
				if not (pd and pd.CurrentClothes) then return out end
				pd.ClothesHP = pd.ClothesHP or {}
				pd.AccessoryHP = pd.AccessoryHP or {}
				-- Cloth rows.
				for _, label in ipairs(pd.CurrentClothes) do
					local cur = pd.ClothesHP[label]
					if cur and not cur.HP then pd.ClothesHP[label] = nil; cur = nil end  -- scrub threshold-only (orig L3974)
					out[#out + 1] = { label = label, state = _hpStateFromSet(cur), accessory = false }
				end
				-- Accessory rows: the live avatar's accessories UNION the script/bundle-applied ones, dedup by name (orig L4031-4047).
				do
					local seen = {}
					local function _addAcc(name)  -- one row per accessory NAME (AccessoryHP is name-keyed; matches the runtime FindFirstChild(name) resolve)
						if type(name) ~= "string" or name == "" or seen[name] then return end
						seen[name] = true
						local cur = pd.AccessoryHP[name]
						if cur and not cur.HP then pd.AccessoryHP[name] = nil; cur = nil end
						out[#out + 1] = { label = name, state = _hpStateFromSet(cur), accessory = true }
					end
					-- (a) accessories the player is CURRENTLY wearing on their real avatar
					local ply = game:GetService("Players"):FindFirstChild(sp)
					local char = ply and ply.Character
					if char then
						for _, child in ipairs(char:GetChildren()) do
							if child:IsA("Accessory") then _addAcc(child.Name) end
						end
					end
					-- (b) V4.5.17 FIX: script/bundle-applied accessories. Under Method 2 (default) a bundle's accessories
					-- are cloned onto the HIDDEN proxy model, not ply.Character, so (a) alone missed them ("HP clothing only
					-- shows accessories worn currently"). CurrentPartList.Accessory is the applied-accessory map (keyed by
					-- the Accessory instance) for BOTH methods; the runtime tear path resolves these on the proxy, so a tag
					-- created here matches at runtime. Skip physics tails (tracked separately; internal suffixed names).
					local cpl = pd.CurrentPartList and pd.CurrentPartList.Accessory
					local tails = pd.CurrentPartList and pd.CurrentPartList.physicsTails
					if cpl then
						for accInst in pairs(cpl) do
							if typeof(accInst) == "Instance" and accInst.Parent and not (tails and tails[accInst]) then _addAcc(accInst.Name) end
						end
					end
				end
				return out
			end

			-- Cycle an item's HP one step (orig change handler L3999-4016) and write the legacy
			-- {HP=,Inverse=} set into pd.ClothesHP (cloth) or pd.AccessoryHP (accessory). Returns
			-- the new state (0..4) so the GUI can relabel without a full re-render.
			System.cycleClothHP = function(label, accessory)
				if not label then return nil end
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				if not pd then return nil end
				local map
				if accessory then
					pd.AccessoryHP = pd.AccessoryHP or {}
					map = pd.AccessoryHP
				else
					pd.ClothesHP = pd.ClothesHP or {}
					-- unequip guard (orig L4026): a cloth label no longer in CurrentClothes => no write
					if pd.CurrentClothes and not table.find(pd.CurrentClothes, label) then return nil end
					map = pd.ClothesHP
				end
				local switch = _hpStateFromSet(map[label])
				switch += 1
				if switch > 4 then switch = 0 end
				if switch == 1 then map[label] = {HP = "TopHP",    Inverse = false}
				elseif switch == 2 then map[label] = {HP = "BottomHP", Inverse = false}
				elseif switch == 3 then map[label] = {HP = "TopHP",    Inverse = true}
				elseif switch == 4 then map[label] = {HP = "BottomHP", Inverse = true}
				else map[label] = nil end
				return switch
			end

			-- AUTO-STRIP (per-cloth, Damage tab) ----------------------------------------
			-- The merged GUI's mock used 8 fixed Hat/Hair/... category rows with None/Top/
			-- Bottom/Both; that conflated the per-cloth Damage StripOnRipMap (this) with the
			-- Catalog StripCategories boolean map (P9). The faithful Damage strip is keyed by
			-- clothName, so these helpers + the GUI render dynamic per-equipped-cloth rows that
			-- mirror _refreshStripConfigDropdown (orig L27572-27665).
			-- Returns { {cloth=, mode="None"|"Top"|"Bottom"|"Both"}, ... } sorted Shirt->Pants->
			-- other (alphabetical within), resolving each cloth's display mode (explicit map ->
			-- else smart-default by ClothType, orig L27631-27635).
			System.getStripRows = function()
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				local out = {}
				if not pd then return out end
				pd.StripOnRipMap = pd.StripOnRipMap or {}
				local equipped = pd.CurrentClothes or {}
				local order = {}
				for _, n in ipairs(equipped) do order[#order + 1] = n end
				table.sort(order, function(a, b)
					local ta = (Clothes and Clothes[a] and Clothes[a].ClothType) or "z"
					local tb = (Clothes and Clothes[b] and Clothes[b].ClothType) or "z"
					if ta == tb then return a:lower() < b:lower() end
					return ta < tb
				end)
				for _, clothName in ipairs(order) do
					local cur = pd.StripOnRipMap[clothName]
					if cur == nil then
						local ct = Clothes and Clothes[clothName] and Clothes[clothName].ClothType
						cur = (ct == "Shirt" or ct == "Pants") and "None" or "Both"
					end
					out[#out + 1] = { cloth = clothName, mode = cur }
				end
				return out
			end

			-- Cycle a cloth's strip mode None->Top->Bottom->Both->None (orig L27658) and write
			-- pd.StripOnRipMap[cloth]. Returns the new mode string. (No ApplyStrip on this path
			-- -- the rip loop at engine L20944 reads the map live; AutoStripOnRip gates it.)
			System.cycleStrip = function(cloth)
				if not cloth then return nil end
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				if not pd then return nil end
				pd.StripOnRipMap = pd.StripOnRipMap or {}
				local now = pd.StripOnRipMap[cloth]
				if now == nil then
					local ct = Clothes and Clothes[cloth] and Clothes[cloth].ClothType
					now = (ct == "Shirt" or ct == "Pants") and "None" or "Both"
				end
				local nxt = ({None = "Top", Top = "Bottom", Bottom = "Both", Both = "None"})[now] or "None"
				pd.StripOnRipMap[cloth] = nxt
				return nxt
			end

			-- AutoStripOnRip enable toggle (orig L27563-27568). Returns the new boolean.
			System.toggleAutoStripOnRip = function()
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				if not pd then return nil end
				pd.AutoStripOnRip = not pd.AutoStripOnRip
				return pd.AutoStripOnRip
			end
			System.getAutoStripOnRip = function()
				local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
				local pd = PlayerData[sp]
				return pd and pd.AutoStripOnRip == true
			end

			-- ============================================================================
			-- PHASE 8: BUNDLES TAB DATA BRIDGE (list + apply + tabs/counts/search +
			--          save/export/import/delete/restore/clear/redownload)
			-- ----------------------------------------------------------------------------
			-- Same model as P6/P7: the file-scope GUI (_buildKrulHubGUI) cannot see the
			-- RoClothes-scope Bundle table, BundleActiveTab, getBundleTab,
			-- env (the curated direct-global env, L7156), _atomicWriteJSON, rehydrate,
			-- MetaClothes, etc., so they are exposed here as System.* methods (0 RoClothes
			-- registers; the small helper locals live inside this do...end). The GUI builds
			-- tiles/rows from these and registers Pages._renderBundles onto System.renderBundles
			-- so a hotSwap (bundle/peer/reset) re-paints the visible list.
			--
			-- Faithfulness map to the ORIGINAL (Ro-Clothes-Krul-V4.3.576.0627.lua):
			--   * list build (loop Bundle)   -> orig L27348-27384 (ButtonCreate per entry)
			--   * sort by name:lower()        -> orig L27419-27421
			--   * tab routing                 -> getBundleTab, orig L8238-8243
			--   * tab counts (skip nil/Bald)  -> GUIUpdate, orig L19888-19893
			--   * active-tab + active flag     -> GUIUpdate, orig L19850-19858 / L19896-19904
			--   * search (plain substring)     -> GUIUpdate, orig L19878-19879
			--   * apply (handleBundleClick)    -> orig L26802-26997 (type route + CharacterReset
			--                                     + state set + LAYERED checkBundle + execute).
			--                                     checkBundle is gone from the torn-down engine; its
			--                                     PURE state-transfer survives as Function.ApplyBundleToPeerData
			--                                     (engine L18344, "mirror of checkBundle's pure logic")
			--                                     which RESETS each call -> PHASE 11: applyBundle layers
			--                                     every active bundle (orig L26916-26932, clicked last),
			--                                     the FIRST via ApplyBundleToPeerData (reset+apply) and the
			--                                     rest via the no-reset _overlayBundle (that function's body
			--                                     minus its reset header), then hotSwap (the engine's
			--                                     debounced CharacterReset->Execute pipeline).
			--                                     PHASE 12: for SELF (SelectPlayer==local),
			--                                     each layered bundle also writes checkBundle's
			--                                     five LOCAL-USER render globals (Method /
			--                                     Position+RotationPhysicsMultiply / included+
			--                                     excludeAccessoryNames, orig L26491-26507) via
			--                                     System._applySelfModuleGlobals; peers skip them.
			--   * delete + DeletedBundles.json -> orig L27142-27295 (delfile personal + blocklist append)
			--   * restore / clear-all          -> Manage Deleted modal, orig L28196-28487
			--   * export clipboard / submit     -> orig L27008-27141 (toBundleFormat + env.copy;
			--                                     POST https://krulhub.dev/roclothes/submit)
			--   * import (parse+validate+disk)  -> orig L29171-29468 (URL/JSON + sandboxed loadstring
			--                                     local paste; _writeImportedBundleToDisk L27844)
			--   * redownload bundles            -> orig delfile RClothesLerp/Bundles/* + re-fetch via
			--                                     the same on-disk loader (orig L20162-20576)
			--
			-- Endpoints / paths used VERBATIM from the engine:
			--   submit  = https://krulhub.dev/roclothes/submit
			--   on-disk = RClothesLerp/Bundles/<name>.json, RClothesLerp/DeletedBundles.json,
			--             RClothesLerp/BundleLoader.json, RClothesLerp/MySubmissions.json
			do
				-- request-fn resolver (the L7156 curated env has file APIs + copy but NOT
				-- http_request; the engine sources the request fn from System.Env -- L5397 /
				-- L7337 / L18615 pattern -- with bare-global fallbacks).
				local function _reqFn()
					return (System.Env and (System.Env.http_request or System.Env.request))
						or http_request or request
						or (syn and syn.request) or (http and http.request)
				end

				-- filename sanitizer -- identical denylist to BOTH original write paths
				-- (orig L27218-27228 / L29324-29334): reject path separators + dot-segments.
				local function _bsanitize(str)
					str = tostring(str or "")
					for _, ch in ipairs({"/", "<", ">", "?", "*", "|", " ", "\\", '"', ":"}) do
						str = string.gsub(str, ch, "_")
					end
					if str == "" or str == "." or str == ".." or str:find("^%.+$") then
						str = "_invalid_" .. tostring(math.random(1, 99999))
					end
					return str
				end

				-- read DeletedBundles.json into a list (orig _md_readDeleted L28196-28207).
				local function _readDeleted()
					if not (env and env.isfile and env.readfile
						and env.isfile("RClothesLerp/DeletedBundles.json")) then
						return {}
					end
					local _okR, _raw = pcall(env.readfile, "RClothesLerp/DeletedBundles.json")
					if not _okR or type(_raw) ~= "string" or #_raw == 0 then return {} end
					local _okD, _list = pcall(HS.JSONDecode, HS, _raw)
					if not _okD or type(_list) ~= "table" then return {} end
					return _list
				end

				-- read MySubmissions.json into a set (orig restore path L28298-28309).
				local function _mySubsSet()
					local set = {}
					if env and env.isfile and env.readfile and env.isfile("RClothesLerp/MySubmissions.json") then
						local _okR, _raw = pcall(env.readfile, "RClothesLerp/MySubmissions.json")
						if _okR and type(_raw) == "string" and #_raw > 0 then
							local _okD, _list = pcall(HS.JSONDecode, HS, _raw)
							if _okD and type(_list) == "table" then
								for _, n in ipairs(_list) do
									if type(n) == "string" then set[n] = true end
								end
							end
						end
					end
					return set
				end

				-- LIST -----------------------------------------------------------------
				-- Sorted, tab-filtered, search-filtered array of bundle descriptors.
				-- tab defaults to the engine's current BundleActiveTab; pass nil to use it.
				-- Mirrors the GUIUpdate visibility filter (orig L19850-19882) + the button
				-- sort (orig L27419-27421). "nil"/"Bald" placeholder entries are skipped
				-- (they are special LayoutOrder rows in the original, not real bundles).
				System.getBundleList = function(tab, search)
					tab = tab or BundleActiveTab
					local needle = string.lower(tostring(search or ""))
					local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
					local pd = PlayerData[sp]
					local out = {}
					if type(Bundle) ~= "table" then return out end
					for name, def in pairs(Bundle) do
						if type(name) == "string" and name ~= "nil" and name ~= "Bald" and type(def) == "table" then
							local vTab = getBundleTab(def)
							local matchSearch = (needle == "") or (string.find(string.lower(name), needle, 1, true) ~= nil)
							if vTab == tab and matchSearch then
								-- active detection (orig L19850-19858)
								local active = false
								if pd then
									if name == pd.CurrentBundle and name ~= "nil" then active = true
									elseif def.IsPreset and pd.CurrentPreset == name then active = true
									elseif def.ClothingBundle and pd.CurrentClothingBundles and table.find(pd.CurrentClothingBundles, name) then active = true end
								end
								out[#out + 1] = {
									name = name,
									tab = vTab,
									active = active,
									isPreset = def.IsPreset == true,
									clothingBundle = def.ClothingBundle == true,
								}
							end
						end
					end
					table.sort(out, function(a, b) return a.name:lower() < b.name:lower() end)
					return out
				end

				-- COUNTS ---------------------------------------------------------------
				-- Per-tab counts (orig L19888-19893: loop Bundle, skip nil/Bald, count by tab).
				System.getBundleCounts = function()
					local counts = { community = 0, mine = 0, clothing = 0, preset = 0 }
					if type(Bundle) == "table" then
						for name, def in pairs(Bundle) do
							if type(name) == "string" and name ~= "nil" and name ~= "Bald" and type(def) == "table" then
								local t = getBundleTab(def)
								counts[t] = (counts[t] or 0) + 1
							end
						end
					end
					return counts
				end

				-- which tab holds the currently active bundle/preset/clothing (orig L19896-19904).
				System.getActiveBundleTab = function()
					local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
					local pd = PlayerData[sp]
					if not pd then return nil end
					if pd.CurrentBundle and pd.CurrentBundle ~= "nil" and Bundle[pd.CurrentBundle] then
						return getBundleTab(Bundle[pd.CurrentBundle])
					elseif pd.CurrentPreset and pd.CurrentPreset ~= "" and Bundle[pd.CurrentPreset] then
						return getBundleTab(Bundle[pd.CurrentPreset])
					elseif pd.CurrentClothingBundles and #pd.CurrentClothingBundles > 0 then
						local last = pd.CurrentClothingBundles[#pd.CurrentClothingBundles]
						if Bundle[last] then return getBundleTab(Bundle[last]) end
					end
					return nil
				end

				-- engine-side tab state (the original kept BundleActiveTab; the GUI seg drives it
				-- so getBundleList(nil,...) and re-renders agree on the active tab).
				System.setBundleTab = function(tab)
					if tab == "community" or tab == "mine" or tab == "clothing" or tab == "preset" then
						BundleActiveTab = tab
					end
					return BundleActiveTab
				end

				-- PHASE 11: NO-RESET OVERLAY (the multi-bundle scalar-layering fix) ------
				-- _overlayBundle(pd, bd) reproduces Function.ApplyBundleToPeerData's BODY 1:1
				-- (engine L18920-19117) but WITHOUT its scalar-reset header (engine L18889-18918).
				-- This is exactly the original checkBundle's role: checkBundle never resets --
				-- the reset is done ONCE externally by handleBundleClick (_resetBundleSettableFields,
				-- orig L26863) and then EACH active bundle is layered additively via checkBundle
				-- (orig L26916-26932, clicked LAST so it wins). The torn-down engine lost the
				-- local checkBundle; ApplyBundleToPeerData is its only mirror but it RESETS every
				-- call, so it can play the FIRST (reset-and-apply) bundle but not the layered
				-- ones. _overlayBundle is the no-reset path for those layered bundles. It writes
				-- ONLY PlayerData (pd) via the same allowlist + validators as ApplyBundleToPeerData
				-- (_PEER_ALLOWED_PRESET_KEYS / _validatePresetValue / _sanitizeClothesRecolor /
				-- _sanitizeGizmoOffsets / Function.StringTo / Function.SanitizeMeshEditValue) -- all
				-- RoClothes-scope locals visible here as upvalues. It deliberately does NOT spawn
				-- catalog buttons / touch GUIObject (those checkBundle side effects were GUI
				-- artifacts dropped throughout this merge; the merged Catalog sidebar rebuilds
				-- from PD). Faithful per the original's PD-only state-transfer.
				-- Assigned as a System.* field (NOT a do-block local) so it costs 0 RoClothes
				-- registers -- the function is already at the 200-local ceiling; a block local
				-- here overflows it. Same 0-register pattern as every other bridge method.
				System._overlayBundle = function(pd, bundleData)
					if not pd or type(bundleData) ~= "table" then return end
					-- Preset scalar fields: copy generically, skipping keys that drive local-only
					-- globals (Method / includedAccessoryNames / etc.) or require UI-side work
					-- (CatalogUsername spawns catalog buttons -- the merged sidebar renders without those).
					if bundleData.Preset then
						for setting, value in pairs(bundleData.Preset) do
							if setting == "PositionPhysicsMultiply"
								or setting == "RotationPhysicsMultiply"
								or setting == "Method"
								or setting == "includedAccessoryNames"
								or setting == "excludeAccessoryNames"
								or setting == "CurrentBundle"
								or setting == "CatalogUsername"
								or setting == "CatalogAccessory"
								or setting == "CatalogTail" then
								-- Skip: these either mutate globals meant for local-user rendering
								-- or require GUI spawning. CatalogAccessory/CatalogTail data IS still
								-- applied (shape-gated) so accessories still load via the
								-- HumanoidDescription pipeline; CatalogUsername is stored for re-fetch.
								-- Mirrors ApplyBundleToPeerData L18925-18955.
								-- PHASE 12: the five render globals (Method / Position+Rotation
								-- PhysicsMultiply / included+excludeAccessoryNames) stay skipped HERE
								-- because they are meaningless for a peer's PlayerData; for SELF they
								-- are layered separately by System._applySelfModuleGlobals (called from
								-- applyBundle's _layer, self-gated), reproducing the original checkBundle.
								if (setting == "CatalogAccessory" or setting == "CatalogTail") and type(value) == "table" then
									pd[setting] = {}
									local _count = 0
									for _, x in pairs(value) do
										_count = _count + 1
										if _count > 100 then break end
										local _n = tonumber(x)
										if _n and _n == _n and math.abs(_n) <= 1e15 then
											table.insert(pd[setting], _n)
										end
									end
								elseif setting == "CatalogUsername" then
									if type(value) == "string" and #value <= 64 and value:match("^[%w_]*$") then
										pd.CatalogUsername = value
									end
								end
							elseif _PEER_ALLOWED_PRESET_KEYS[setting] then
								-- allowlist + shape validator gate (mirrors ApplyBundleToPeerData L18956-18964).
								if _validatePresetValue(setting, value) then
									pd[setting] = value
								end
							end
						end
					end

					-- V4.4.2: tailSettings round-trip (additive merge -- see ApplyBundleToPeerData). Personal
					-- full-save bundles carry Preset.tailSettings; merge it into the live tailSettings.
					if type(bundleData.Preset) == "table" and type(bundleData.Preset.tailSettings) == "table" and type(pd.tailSettings) == "table" then
						-- V4.4.2: type-gate against the existing type (untrusted bundles bypass the validator).
						-- V4.5.24 Fix (CRITICAL): same finite+bounded numeric gate as ApplyBundleToPeerData -
						-- a crafted timeScale here also feeds the uncapped PreRender step loop (client freeze).
						for _tk, _tv in pairs(bundleData.Preset.tailSettings) do
							if type(_tv) == type(pd.tailSettings[_tk]) then
								if type(_tv) == "number" then
									if _tv == _tv and _tv ~= math.huge and _tv ~= -math.huge and math.abs(_tv) <= 1e4 then
										pd.tailSettings[_tk] = _tv
									end
								else
									pd.tailSettings[_tk] = _tv
								end
							end
						end
					end

					-- Clothing: populate CurrentClothes + ClothesHP additively (mirrors
					-- ApplyBundleToPeerData L18969-19007 = checkBundle's Clothing block). This is
					-- the stacking aspect -- later bundles ADD their clothes on top.
					if bundleData.Clothing then
						for _, cname in pairs(bundleData.Clothing) do
							if Clothes[cname] then
								if Clothes[cname].Blacklist then
									for _, b in pairs(Clothes[cname].Blacklist) do
										local idx = table.find(pd.CurrentClothes, b)
										if idx then
											table.remove(pd.CurrentClothes, idx)
											pd.ClothesHP[b] = nil
											pd.ClothesRecolor[b] = nil
										end
									end
									pd._equippedSetSrc = nil
								end
								if not table.find(pd.CurrentClothes, cname) then
									table.insert(pd.CurrentClothes, cname)
								end
								pd.ClothesHP[cname] = nil
								local hp = Clothes[cname].HP
								if hp == 1 then
									pd.ClothesHP[cname] = {HP = "TopHP",    Inverse = false}
								elseif hp == 2 then
									pd.ClothesHP[cname] = {HP = "BottomHP", Inverse = false}
								elseif hp == 3 then
									pd.ClothesHP[cname] = {HP = "TopHP",    Inverse = true}
								elseif hp == 4 then
									pd.ClothesHP[cname] = {HP = "BottomHP", Inverse = true}
								elseif hp and hp ~= 0 then
									pd.ClothesHP[cname] = {HP = "TopHP",    Inverse = false}
								end
							end
						end
					end

					-- Recolor: per-cloth color overrides (mirrors ApplyBundleToPeerData L19009-19016).
					if bundleData.Recolor then
						for cloth, colors in pairs(bundleData.Recolor) do
							if type(cloth) ~= "string" or #cloth > 128 then continue end
							do local _safe = _sanitizeClothesRecolor(colors); if _safe then pd.ClothesRecolor[cloth] = _safe end end
						end
					end

					-- MeshEdit: writes to PartList + CockScale (mirrors ApplyBundleToPeerData L19021-19058).
					if bundleData.MeshEdit then
						for partName, propTbl in pairs(bundleData.MeshEdit) do
							if type(partName) ~= "string" or #partName > 64 or type(propTbl) ~= "table" then continue end
							for propName, propVal in pairs(propTbl) do
								if type(propName) ~= "string" or #propName > 64 then continue end
								if propName == "CockScale" then
									if type(propVal) == "number" and propVal == propVal and math.abs(propVal) ~= math.huge then
										pd.CockScale = math.clamp(propVal, 0.1, 10)
									end
								elseif propName == "Color" then
									if pd.PartList[partName] and pd.PartList[partName][propName] then
										if typeof(propVal) == "Color3" then
											pd.PartList[partName][propName].Color = propVal
										elseif type(propVal) == "table"
											and type(propVal.R) == "number" and type(propVal.G) == "number" and type(propVal.B) == "number"
											and propVal.R == propVal.R and propVal.G == propVal.G and propVal.B == propVal.B then
											local rgb = Function.StringTo(tostring(propVal.R * 255 .. "," .. propVal.G * 255 .. "," .. propVal.B * 255), "RGB")
											if rgb then
												pd.PartList[partName][propName].Color = rgb
											end
										end
									end
								else
									if pd.PartList[partName] then
										local _safe, _ok = Function.SanitizeMeshEditValue(propName, propVal)
										if _ok then pd.PartList[partName][propName] = _safe end
									end
								end
							end
						end
					end

					-- HPClothes (mirrors ApplyBundleToPeerData L19060-19081).
					if bundleData.HPClothes then
						for cname, val in pairs(bundleData.HPClothes) do
							if type(cname) ~= "string" or #cname > 128 then continue end
							if type(val) == "table" then
								if val.HP == "TopHP" or val.HP == "BottomHP" then
									pd.ClothesHP[cname] = {HP = val.HP, Inverse = val.Inverse == true}
								elseif val.Type and (val.Type == "TopHP" or val.Type == "BottomHP") then
									pd.ClothesHP[cname] = {HP = val.Type, Inverse = val.Inverse == true}
								else
									pd.ClothesHP[cname] = {HP = "TopHP", Inverse = val.Inverse == true}
								end
							end
						end
					end

					-- AccessoryHP / GizmoOffsets / GizmoOffset (mirrors ApplyBundleToPeerData L19085-19117).
					if bundleData.AccessoryHP then
						pd.AccessoryHP = pd.AccessoryHP or {}
						for accName, hpType in pairs(bundleData.AccessoryHP) do
							if type(accName) ~= "string" or #accName > 128 then continue end
							if type(hpType) == "table" and (hpType.HP == "TopHP" or hpType.HP == "BottomHP") then
								pd.AccessoryHP[accName] = {HP = hpType.HP, Inverse = hpType.Inverse == true}
							elseif type(hpType) == "number" and hpType > 0 then
								pd.AccessoryHP[accName] = hpType
							end
						end
					end
					if bundleData.GizmoOffsets then
						pd.GizmoOffsets = _sanitizeGizmoOffsets(bundleData.GizmoOffsets)
						if pd.GizmoTarget and pd.GizmoOffsets[pd.GizmoTarget] then
							pd.GizmoOffset = pd.GizmoOffsets[pd.GizmoTarget]
						elseif bundleData.GizmoOffset then
							local _gizSan = _sanitizeGizmoOffsets({_single = bundleData.GizmoOffset})
							if _gizSan and _gizSan._single then pd.GizmoOffset = _gizSan._single end
						end
					elseif bundleData.GizmoOffset then
						local _gizSan = _sanitizeGizmoOffsets({_single = bundleData.GizmoOffset})
						if _gizSan and _gizSan._single then pd.GizmoOffset = _gizSan._single end
					end
				end

				-- PHASE 12: self-only MODULE-GLOBAL writes from a bundle's Preset.
				-- _overlayBundle (and Function.ApplyBundleToPeerData) DELIBERATELY skip the
				-- five LOCAL-USER render globals -- Method / PositionPhysicsMultiply /
				-- RotationPhysicsMultiply / includedAccessoryNames / excludeAccessoryNames --
				-- because for a PEER's PlayerData they are meaningless (they govern how the
				-- LOCAL client renders, not the peer's per-player data); that skip is correct
				-- and must stay for peers. But the original checkBundle (orig L26491-26507)
				-- DOES write them on EVERY bundle apply -- so when SelectPlayer is SELF, a
				-- bundle carrying Preset.Method=3 / custom physics multipliers / accessory
				-- include-exclude lists must update those globals too. This helper reproduces
				-- checkBundle's exact write block 1:1 (the `else` branch of its Preset loop):
				-- direct assign for the three scalars; fresh `{}` + insert-loop for the two
				-- name lists. It is a present-only overlay -- a field ABSENT from this bundle's
				-- Preset is LEFT UNCHANGED (the original never resets these five; they are NOT
				-- in Function.ResetBundleSettableFields, orig L26719-26797 -- only Preset entries
				-- change them). Reassigning the captured upvalues updates the SAME locals the
				-- character build reads (Method via `MethodOverride or Method` at L15174/15857/
				-- 15959/17227; the multipliers via the physics tick; the name lists via
				-- updateIncludedAccessoryNamesValidationSet at L11395) -- the established
				-- keybind/Method bridge pattern (cf. System.setMethod L8510 reassigns the same
				-- L8505 upvalue; the multiplier setters L8474-8475 reassign the file-scope
				-- L2205-2206 upvalues). Assigned as a System.* field (NOT a do-block local) so
				-- it costs 0 RoClothes registers -- the function is at the 200-local ceiling.
				-- The caller (System.applyBundle's _layer) gates this to SELF and runs it once
				-- per layered bundle in the original's order so the clicked bundle wins.
				System._applySelfModuleGlobals = function(bundleData)
					if type(bundleData) ~= "table" or type(bundleData.Preset) ~= "table" then return end
					local p = bundleData.Preset
					-- Iterate exactly as orig checkBundle's `for setting, value in pairs(v.Preset)`
					-- loop, reaching ONLY the five keys its big skip-condition routes to the else
					-- branch (orig L26491-26507). Other Preset keys are PD writes, already done by
					-- ApplyBundleToPeerData / _overlayBundle -- not re-touched here.
					for setting, value in pairs(p) do
						if setting == "PositionPhysicsMultiply" then
							PositionPhysicsMultiply = value
						elseif setting == "RotationPhysicsMultiply" then
							RotationPhysicsMultiply = value
						elseif setting == "Method" then
							Method = value
						elseif setting == "includedAccessoryNames" then
							includedAccessoryNames = {}
							for i, v in pairs(value) do
								table.insert(includedAccessoryNames, v)
							end
						elseif setting == "excludeAccessoryNames" then
							excludeAccessoryNames = {}
							for i, v in pairs(value) do
								table.insert(excludeAccessoryNames, v)
							end
						end
					end
					-- V4.5.19 FIX: the two filter lists above were just reassigned, but the derived
					-- validation set that isTailAccessory reads (L14863) caches behind
					-- includedAccessoryNamesValidationSetNeedsUpdating -- and that flag was set true ONLY at
					-- its declaration (L14866). So a bundle/outfit that restored accessory filters had NO
					-- effect (the stale set was reused for the whole session), silently defeating the
					-- V4.5.18 filter round-trip. Re-dirty the flag so isTailAccessory recomputes lazily.
					includedAccessoryNamesValidationSetNeedsUpdating = true
				end

				-- APPLY ----------------------------------------------------------------
				-- Reproduces handleBundleClick's normal-apply path (orig L26802-26998) for the
				-- merged GUI: validate, toggle-off if re-clicking the active one, else
				-- CharacterReset + reset settable fields + PartList default + set the right
				-- Current* state by type (regular/preset/clothing) + LAYERED apply of every
				-- active bundle (PHASE 11: clicked LAST so it wins; first via the reset-and-apply
				-- ApplyBundleToPeerData, the rest via the no-reset _overlayBundle above) +
				-- hotSwap (the engine's debounced CharacterReset->Execute pipeline) +
				-- AvatarSyncPublish for self. The original's "nil"/Bald CLEAR row is exposed
				-- via clearBundle below (the merged GUI has no nil tile). Returns a small status.
				System._replayBundleLayers = function(sp, pd, clickedName)
					pcall(Function.CharacterReset, sp)
					if Function.ResetBundleSettableFields then pcall(Function.ResetBundleSettableFields, sp) end
					pd.PartList = Function.PartListDefault()
					pd.LastRequestID = (pd.LastRequestID or 0) + 1
					pd.CurrentClothes = {}
					local applied = false
					local function layer(name)
						local bd = name and Bundle[name]
						if type(bd) ~= "table" then return end
						if not applied then
							applied = true
							Function.ApplyBundleToPeerData(sp, bd)
						else
							System._overlayBundle(pd, bd)
						end
						if sp == Player.Name and System._applySelfModuleGlobals then
							System._applySelfModuleGlobals(bd)
						end
					end
					if pd.CurrentBundle ~= "nil" and pd.CurrentBundle ~= clickedName then layer(pd.CurrentBundle) end
					if pd.CurrentPreset ~= clickedName then layer(pd.CurrentPreset) end
					for _, name in ipairs(pd.CurrentClothingBundles or {}) do
						if name ~= clickedName then layer(name) end
					end
					if clickedName then layer(clickedName) end
				end

				System.applyBundle = function(name)
					if type(name) ~= "string" or type(Bundle) ~= "table" then return false end
					local bundleData = Bundle[name]
					if type(bundleData) ~= "table" then return false end
					local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
					local pd = PlayerData[sp]
					if not pd then return false end
					-- NakedMode now PERSISTS across bundle applies (it's a UI toggle, not the original keybind).
					-- The original cleared pd._nakedMode here on every bundle click (orig L26810) - but that
					-- clear ran BEFORE the fresh apply (below) read the flag, so bundle-clothes suppression never
					-- fired via applyBundle, and users had to re-toggle NakedMode for every bundle. Removed: the
					-- flag now stays set (dropping each applied bundle's Shirt/Pants/ShirtGraphic via the equip
					-- pipeline) until the user toggles Naked Mode OFF (setNaked, L~11691) or the N-keybind clears it.
					local isClothingBundle = bundleData.ClothingBundle == true
					local isPreset = bundleData.IsPreset == true
					local isRegular = not isClothingBundle and not isPreset

					-- Toggle-off paths (orig L26817-26859)
					if isRegular and pd.CurrentBundle == name then
						pd.CurrentBundle = "nil"
						pd.CurrentClothes = {}
						_scrubCloth(pd, nil)
						pd.CurrentPreset = nil
						pd.CurrentClothingBundles = {}
						if Function.ResetBundleSettableFields then pcall(Function.ResetBundleSettableFields, sp) end
						if hotSwap then hotSwap() end
						return "toggled_off"
					elseif isClothingBundle and pd.CurrentClothingBundles and table.find(pd.CurrentClothingBundles, name) then
						if bundleData.Clothing then
							for _, clothName in pairs(bundleData.Clothing) do
								local idx = table.find(pd.CurrentClothes, clothName)
								if idx then table.remove(pd.CurrentClothes, idx) end
								_scrubCloth(pd, clothName)
							end
						end
						local _ci = table.find(pd.CurrentClothingBundles, name)
						if _ci then table.remove(pd.CurrentClothingBundles, _ci) end
						System._replayBundleLayers(sp, pd)
						if hotSwap then hotSwap() end
						if sp == Player.Name and Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true) end
						return "toggled_off"
					elseif isPreset and pd.CurrentPreset == name then
						pd.CurrentBundle = "nil"
						pd.CurrentClothes = {}
						pd.CurrentPreset = nil
						pd.CurrentClothingBundles = {}
						_scrubCloth(pd, nil)
						if Function.ResetBundleSettableFields then pcall(Function.ResetBundleSettableFields, sp) end
						if hotSwap then hotSwap() end
						return "toggled_off"
					end

					-- Fresh apply (orig L26861-26932)
					if isRegular then
						pd.CurrentBundle = name
						pd.CurrentPreset = nil
						pd.CurrentClothingBundles = {}
						pd.CurrentClothes = {}
						_scrubCloth(pd, nil)
					elseif isPreset then
						pd.CurrentPreset = name
						pd.CurrentClothingBundles = {}
					elseif isClothingBundle then
						pd.CurrentClothingBundles = pd.CurrentClothingBundles or {}
						if not table.find(pd.CurrentClothingBundles, name) then
							table.insert(pd.CurrentClothingBundles, name)
						end
					end

					-- Reset once, replay survivors, and give the clicked bundle precedence.
					System._replayBundleLayers(sp, pd, name)

					if hotSwap then hotSwap() end
					if sp == Player.Name and Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true) end
					return "applied"
				end

				-- CLEAR (the original "nil" tile path, orig L26873-26896): wipe all bundle state.
				System.clearBundle = function()
					local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
					local pd = PlayerData[sp]
					if not pd then return false end
					pd.CurrentBundle = "nil"
					pd.CurrentClothes = {}
					pd.CurrentPreset = nil
					pd.CurrentClothingBundles = {}
					_scrubCloth(pd, nil)
					if Function.ResetBundleSettableFields then pcall(Function.ResetBundleSettableFields, sp) end
					if hotSwap then hotSwap() end
					return true
				end

				-- DELETE ---------------------------------------------------------------
				-- Mirrors handleBundleClick's delete branch (orig L27142-27295): personal
				-- bundles delfile their on-disk JSON; ALL deletes append to DeletedBundles.json
				-- (the only persistence for community bundles, which re-load from the manifest)
				-- + remove the in-memory entry. Returns true on success.
				System.deleteBundle = function(name)
					if type(name) ~= "string" or type(Bundle) ~= "table" then return false end
					local _bDef = Bundle[name]
					local _isPersonal = _bDef and _bDef.Personal == true
					-- personal-only: delete the per-bundle file (orig L27235-27241)
					if _isPersonal then
						pcall(function()
							if env.delfile and env.isfile and env.isfile("RClothesLerp/Bundles/" .. _bsanitize(name) .. ".json") then
								env.delfile("RClothesLerp/Bundles/" .. _bsanitize(name) .. ".json")
							end
						end)
					end
					-- append to DeletedBundles.json (orig L27251-27283)
					pcall(function()
						if not (env.writefile and env.isfolder and env.makefolder) then return end
						if not env.isfolder("RClothesLerp") then pcall(env.makefolder, "RClothesLerp") end
						local _list = _readDeleted()
						local _alreadyIn = false
						for _, _n in ipairs(_list) do if _n == name then _alreadyIn = true; break end end
						if not _alreadyIn then table.insert(_list, name) end
						local _wrOk = _atomicWriteJSON("RClothesLerp/DeletedBundles.json", _list)
						if not _wrOk then
							warn("[RoClothes] DeletedBundles persist failed for '" .. tostring(name) .. "' -- bundle may reappear on next execute.")
						end
					end)
					-- always: remove from in-memory Bundle (orig L27287)
					Bundle[name] = nil
					return true
				end

				-- DELETED LIST / RESTORE / CLEAR (Manage Deleted modal, orig L28196-28487) --
				System.getDeletedBundles = function()
					local list = _readDeleted()
					local out = {}
					for _, n in ipairs(list) do if type(n) == "string" then out[#out + 1] = n end end
					return out
				end

				-- Restore one name (orig restore handler L28266-28340): drop it from the
				-- blocklist, re-add from the manifest (_RoClothesData.Bundle) with the correct
				-- Personal flag, then hotSwap so the live list refreshes. Returns
				-- true / "manifest_gone" / false.
				System.restoreBundle = function(name)
					if type(name) ~= "string" then return false end
					local _cur = _readDeleted()
					local _new = {}
					for _, n in ipairs(_cur) do if n ~= name then table.insert(_new, n) end end
					local _wrOk = _atomicWriteJSON("RClothesLerp/DeletedBundles.json", _new)
					if not _wrOk then return false end
					if _RoClothesData and _RoClothesData.Bundle and _RoClothesData.Bundle[name] then
						Bundle[name] = _RoClothesData.Bundle[name]
						local _subs = _mySubsSet()
						if type(Bundle[name]) == "table" then
							Bundle[name].Personal = _subs[name] == true
						end
						if hotSwap then hotSwap() end
						return true
					else
						-- manifest entry vanished -> roll back so the user keeps the entry (orig L28321-28335)
						pcall(function()
							local _roll = _readDeleted()
							table.insert(_roll, name)
							_atomicWriteJSON("RClothesLerp/DeletedBundles.json", _roll)
						end)
						return "manifest_gone"
					end
				end

				-- Clear All (orig L28406-28487): wipe the blocklist + re-instate every manifest
				-- bundle not currently present. Returns the restored count.
				System.clearDeletedBundles = function()
					local _wipeOk = _atomicWriteJSON("RClothesLerp/DeletedBundles.json", {})
					if not _wipeOk then return false end
					local restored = 0
					if _RoClothesData and _RoClothesData.Bundle then
						local _subs = _mySubsSet()
						for _bN, _bV in pairs(_RoClothesData.Bundle) do
							if Bundle[_bN] == nil and type(_bV) == "table" then
								Bundle[_bN] = _bV
								if _bV.IsPreset ~= true and _bV.ClothingBundle ~= true then
									_bV.Personal = _subs[_bN] == true
								end
								restored = restored + 1
							end
						end
					end
					if hotSwap then hotSwap() end
					return restored
				end

				-- EXPORT ---------------------------------------------------------------
				-- compact Lua serializer reproduced from the trapped GUI (orig convertTableToString
				-- L25741-25768 + toBundleFormat L25769-25773). Uses the surviving Function.toFormatString
				-- (engine L11365) for leaf Color3/Vector3/CFrame/string values.
				local function _convertTableToString(t, indent)
					indent = indent or 0
					local s = ""
					for i, v in pairs(t) do
						for _ = 1, indent do s = s .. "\t" end
						if typeof(v) == "table" then
							if type(i) == "number" then s = s .. "[" .. tostring(i) .. "] = { \n"
							else s = s .. '["' .. tostring(i) .. '"] = { \n' end
							s = s .. _convertTableToString(v, indent + 1)
							for _ = 1, indent do s = s .. "\t" end
							s = s .. "}, \n"
						else
							if type(i) == "number" then s = s .. Function.toFormatString(v) .. ", \n"
							else s = s .. '["' .. tostring(i) .. '"] = ' .. Function.toFormatString(v) .. ", \n" end
						end
					end
					return s
				end
				local function _toBundleFormat(t, bundleName)
					return "[" .. Function.toFormatString(bundleName) .. "] = { \n"
						.. _convertTableToString(t, 1) .. "},"
				end

				-- patch in non-default live scales (orig _captureLiveScalesToBundle L25778-25798).
				local function _captureLiveScales(bdata)
					local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
					local pd = PlayerData[sp]
					if not pd then return nil end
					local patch = {}
					if pd.BreastsScale and pd.BreastsScale ~= 1 then patch.BreastsScale = pd.BreastsScale end
					if pd.ButtsScale and pd.ButtsScale ~= 1 then patch.ButtsScale = pd.ButtsScale end
					if pd.LegsScale and pd.LegsScale ~= 1 then patch.LegsScale = pd.LegsScale end
					if pd.TorsoScale and pd.TorsoScale ~= 1 then patch.TorsoScale = pd.TorsoScale end
					if pd.LeftArmScale and pd.LeftArmScale ~= 1 then patch.LeftArmScale = pd.LeftArmScale end
					if pd.RightArmScale and pd.RightArmScale ~= 1 then patch.RightArmScale = pd.RightArmScale end
					if pd.CockScale and pd.CockScale ~= 1 then patch.CockScale = pd.CockScale end
					if pd.BreastsType and pd.BreastsType ~= 1 then patch.BreastsType = pd.BreastsType end
					if pd.ButtType and pd.ButtType ~= 1 then patch.ButtType = pd.ButtType end
					if pd.TorsoType and pd.TorsoType ~= 1 then patch.TorsoType = pd.TorsoType end
					if pd.ArmType and pd.ArmType ~= 1 then patch.ArmType = pd.ArmType end
					if pd.LegsType and pd.LegsType ~= 1 then patch.LegsType = pd.LegsType end
					if next(patch) == nil then return nil end
					local out = {}; for k, v in pairs(bdata) do out[k] = v end
					local preset = {}
					if type(bdata.Preset) == "table" then for k, v in pairs(bdata.Preset) do preset[k] = v end end
					for k, v in pairs(patch) do preset[k] = v end
					out.Preset = preset
					return out
				end

				-- Export a bundle by name. mode "clipboard" copies the Lua-literal export string
				-- (orig export_copy L27008-27021); mode "community" POSTs the dehydrated bundle to
				-- the review queue (orig export L27022-27141). Returns a status string for the modal.
				-- Runs synchronously enough for the modal to show the result; the HTTP path is
				-- pcall-guarded. Default target = the currently active bundle if name is omitted.
				System.exportBundle = function(name, mode)
					mode = mode or "clipboard"
					if type(name) ~= "string" or name == "" then
						-- default to the active bundle/preset (the merged GUI exports the selection)
						local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
						local pd = PlayerData[sp]
						if pd then
							if pd.CurrentBundle and pd.CurrentBundle ~= "nil" then name = pd.CurrentBundle
							elseif pd.CurrentPreset and pd.CurrentPreset ~= "" then name = pd.CurrentPreset
							elseif pd.CurrentClothingBundles and #pd.CurrentClothingBundles > 0 then
								name = pd.CurrentClothingBundles[#pd.CurrentClothingBundles]
							end
						end
					end
					if type(name) ~= "string" or type(Bundle) ~= "table" or type(Bundle[name]) ~= "table" then
						return "No bundle selected -- apply one first, then export."
					end
					local bundleData = Bundle[name]
					if mode == "clipboard" then
						local exportString = _toBundleFormat(_captureLiveScales(bundleData) or bundleData, name)
						local copyOk = pcall(function()
							if env.copy then env.copy(exportString) else error("no copy") end
						end)
						if not copyOk then print(exportString) end
						return copyOk and "Copied to clipboard!" or "Printed to console (no clipboard API)"
					elseif mode == "community" then
						local reqFunc = _reqFn()
						if not reqFunc then
							-- fall back to clipboard, matching the original's no-HTTP path (orig L27124-27138)
							local exportString = _toBundleFormat(_captureLiveScales(bundleData) or bundleData, name)
							local copyOk = pcall(function() if env.copy then env.copy(exportString) else error("no copy") end end)
							if not copyOk then print(exportString) end
							return "No HTTP API -- copied to clipboard instead"
						end
						local lp = PS.LocalPlayer
						local payload = {
							name = name,
							bundle = dehydrate(_captureLiveScales(bundleData) or bundleData),
							scriptVersion = VersionInternal,
							manifestVersion = System.ManifestVersion or "unknown",
							submitter = {
								userId = lp and lp.UserId or 0,
								displayName = lp and lp.DisplayName or "Unknown",
							},
						}
						local okEnc, body = pcall(HS.JSONEncode, HS, payload)
						if not okEnc then return "Encode failed" end
						local ok, res = pcall(reqFunc, {
							Url = "https://krulhub.dev/roclothes/submit",
							Method = "POST",
							Headers = { ["Content-Type"] = "application/json" },
							Body = body,
						})
						if ok and res and tonumber(res.StatusCode) and tonumber(res.StatusCode) >= 200 and tonumber(res.StatusCode) < 300 then
							return "Submitted for review!"
						end
						if ok and res and tonumber(res.StatusCode) == 429 then  -- V4.5.19: tonumber, matching the 2xx check one line up
							return "Rate-limited -- try again shortly"
						end
						warn("[RoClothes] Submit non-2xx/transport: " .. tostring(res and (res.StatusCode or res) or res))
						return "Submit failed (see console)"
					end
					return "Unknown export mode"
				end

				-- IMPORT ---------------------------------------------------------------
				-- Reproduces the original import pipeline (orig L29171-29468), trapped in the
				-- deleted GUI: accepts a URL (http... -> GET + JSONDecode + rehydrate) OR a Lua
				-- table literal (size-capped, prefix-gated, sandboxed loadstring with a safelist
				-- env). Validates each bundle (Clothing/Recolor/MeshEdit/HPClothes refs + a
				-- recognized-field gate), skips duplicates, and stages survivors into
				-- System._pendingImports for the Save Bundle modal to finalize (Private = disk;
				-- Community = disk + submit). Returns a status table:
				--   { ok=bool, status=string, pending=int }
				-- so the GUI can show the message and open the Save Bundle modal when pending>0.
				System._pendingImports = System._pendingImports or {}
				System.importBundle = function(text)
					if type(text) ~= "string" or text == "" then
						return { ok = false, status = "Paste a bundle table or a URL.", pending = 0 }
					end
					-- reset pending queue each paste (orig L29242)
					System._pendingImports = {}
					local fromURL, urlOutput = false, nil
					if text:sub(1, 4) == "http" then
						local reqFunc = _reqFn()
						if not reqFunc then
							return { ok = false, status = "http_request not supported on this executor", pending = 0 }
						end
						local ok, res = pcall(reqFunc, { Url = text, Method = "GET" })
						if not (ok and res and tonumber(res.StatusCode) == 200) then
							return { ok = false, status = ok and ("HTTP error: " .. tostring(res and res.StatusCode)) or "URL fetch failed", pending = 0 }
						end
						if type(res.Body) ~= "string" or #res.Body > 524288 then
							return { ok = false, status = "Response too large (max 512 KB)", pending = 0 }
						end
						local decodeOk, decoded = pcall(function() return HS:JSONDecode(res.Body) end)
						if not (decodeOk and type(decoded) == "table") then
							return { ok = false, status = "URL response is not valid JSON", pending = 0 }
						end
						pcall(function() decoded = rehydrate(decoded) end)
						fromURL, urlOutput = true, decoded
					end

					local success, output
					if fromURL then
						success, output = true, urlOutput
					else
						if #text > 262144 then
							return { ok = false, status = "Paste too large or empty (max 256 KB)", pending = 0 }
						end
						-- prefilter: must look like a table literal (orig L29260)
						if not (text:match("^%s*{") or text:match("^%s*return%s+{")
							or text:match("^%s*local%s+import%s*=%s*{") or text:match("^%s*%[")
							or text:match("^%s*[%w_]+%s*=%s*{")) then
							return { ok = false, status = "Paste must be a bundle table literal (starts with '{' or 'return {')", pending = 0 }
						end
						-- V4.5.24 Fix: getgenv() can return nil/false on some executors - `getgenv().loadstring`
						-- indexed nil BEFORE reaching the `if not _ls` fallback, throwing into the GUI caller.
						-- Resolve the sandbox loader safely.
						local _ls
						local _gok, _g = pcall(function() return getgenv and getgenv() end)
						_ls = (_gok and type(_g) == "table" and _g.loadstring) or loadstring
						if not _ls then return { ok = false, status = "loadstring unavailable on this executor", pending = 0 } end
						-- safelist sandbox env (orig L29269-29282)
						local _sandbox = {
							Color3 = Color3, Vector3 = Vector3, Vector2 = Vector2,
							CFrame = CFrame, UDim = UDim, UDim2 = UDim2,
							Enum = Enum, BrickColor = BrickColor,
							NumberRange = NumberRange, NumberSequence = NumberSequence,
							ColorSequence = ColorSequence,
							NumberSequenceKeypoint = NumberSequenceKeypoint,
							ColorSequenceKeypoint = ColorSequenceKeypoint,
							Rect = Rect, Region3 = Region3,
							tonumber = tonumber, tostring = tostring,
							pairs = pairs, ipairs = ipairs, next = next,
							type = type, typeof = typeof, select = select,
							math = math, string = string, table = table,
						}
						success, output = pcall(function()
							local _chunk, _err = _ls(text)
							if not _chunk then error(_err or "loadstring failed") end
							local _sfOk = pcall(setfenv, _chunk, _sandbox)
							if not _sfOk then error("setfenv failed -- refusing to run unsandboxed chunk") end
							return _chunk()
						end)
						if not success then
							-- second try: wrap as a record (orig L29297-29306)
							local reFormat = "local import = {" .. text .. "} return import"
							success, output = pcall(function()
								local _chunk, _err = _ls(reFormat)
								if not _chunk then error(_err or "loadstring failed") end
								local _sfOk = pcall(setfenv, _chunk, _sandbox)
								if not _sfOk then error("setfenv failed -- refusing to run unsandboxed chunk") end
								return _chunk()
							end)
						end
					end

					if not success then
						return { ok = false, status = tostring(output), pending = 0 }
					end
					if type(output) ~= "table" then
						return { ok = false, status = "Not a bundle. Paste a Lua bundle table.", pending = 0 }
					end
					local _hasAny = false
					for _ in pairs(output) do _hasAny = true; break end
					if not _hasAny then
						return { ok = false, status = "Empty input -- no bundles found in pasted text.", pending = 0 }
					end

					-- per-bundle validation (orig L29338-29434). Reads Clothes / MetaClothes /
					-- _RoClothesData.PartListDefault -- all in scope here.
					local allBundlesSuccess = true
					local s2 = pcall(function()
						for name, input in pairs(output) do
							if type(input) ~= "table" then
								allBundlesSuccess = false; warn("Bundle '" .. tostring(name) .. "' is not a table -- skipped."); continue
							end
							local invalidBundle = false
							local function bWarn(reason) invalidBundle = true; warn(reason) end
							if input["Clothing"] then
								for _, v in pairs(input["Clothing"]) do
									if not (Clothes and Clothes[v]) then bWarn(name .. ": Could not find " .. tostring(v) .. " as Clothing.") end
								end
							end
							if input["Recolor"] then
								for i, v in pairs(input["Recolor"]) do
									if Clothes and Clothes[i] then
										for cType in pairs(v) do
											if cType ~= "Primary" and cType ~= "Secondary" and cType ~= "Tertiary" then
												bWarn(name .. ": " .. tostring(cType) .. " is not a valid color type.")
											end
										end
									else
										bWarn(name .. ": Recolor could not find " .. tostring(i) .. " as Clothing.")
									end
								end
							end
							if input["MeshEdit"] then
								for i, v in pairs(input["MeshEdit"]) do
									if _RoClothesData and _RoClothesData.PartListDefault and _RoClothesData.PartListDefault[i] then
										for property in pairs(v) do
											if not (MetaClothes and MetaClothes.__index and MetaClothes.__index[property]) then
												bWarn(name .. ": " .. tostring(property) .. " is not a valid property.")
											end
										end
									else
										bWarn(name .. ": MeshEdit does not register " .. tostring(i) .. " as a valid part.")
									end
								end
							end
							if input["HPClothes"] then
								for i, v in pairs(input["HPClothes"]) do
									if Clothes and Clothes[i] then
										for property in pairs(v) do
											if property ~= "HP" and property ~= "Inverse"
												and property ~= "Threshold" and property ~= "Type" then
												bWarn(name .. ": " .. tostring(property) .. " isn't registered. Use HP/Threshold/Inverse/Type only.")
											end
										end
									else
										bWarn(name .. ": HPClothes could not find " .. tostring(i) .. " as Clothing.")
									end
								end
							end
							-- recognized-field gate (orig L29408-29415)
							if not input["Clothing"] and not input["Recolor"] and not input["MeshEdit"]
								and not input["HPClothes"] and not input["Preset"]
								and not input["AccessoryHP"] and not input["GizmoOffsets"]
								and not input["Body Color"] and not input["NippleColor"]
								and not input["SkinTone"] and not input["TClothes"]
								and not input["Accessory"] and not input["Clothes"] then
								bWarn(name .. ": no recognized bundle fields -- not a valid RoClothes bundle.")
							end
							if invalidBundle then
								allBundlesSuccess = false
								warn(" Bundle " .. tostring(name) .. " has been aborted! ")
								continue
							end
							if Bundle[name] then
								allBundlesSuccess = false
								warn("Bundle '" .. tostring(name) .. "' already exists -- skipped. Delete it first to re-import.")
								continue
							end
							input.Personal = true
							table.insert(System._pendingImports, { name = name, input = input })
						end
					end)
					if not s2 then
						return { ok = false, status = "Import failed (see console)", pending = 0 }
					end
					local pendingN = #System._pendingImports
					if pendingN > 0 then
						return {
							ok = true,
							status = allBundlesSuccess and "Bundle(s) parsed -- choose where to save"
								or "Some errors found. Choose where to save the rest",
							pending = pendingN,
						}
					elseif allBundlesSuccess then
						return { ok = true, status = "Nothing new to import (all duplicates?)", pending = 0 }
					else
						return { ok = false, status = "Errors found. Check Developer Console.", pending = 0 }
					end
				end

				-- finalize an imported bundle to disk (orig _writeImportedBundleToDisk L27844-27898):
				-- deep-copy, convertToJSON each leaf, stamp BundleName, atomic-write, un-blocklist.
				local function _writeImportedToDisk(name, input)
					if not (env and env.writefile) then return false end
					local t = {}
					local function transfer(n, isNested)
						local newT = {}
						for i, v in pairs(n) do
							if isNested then
								if typeof(v) == "table" then newT[i] = transfer(v, true) else newT[i] = v end
							else
								if typeof(v) == "table" then t[i] = transfer(v, true) else t[i] = v end
							end
						end
						return newT
					end
					transfer(input)
					local function convert(inp)
						for i, v in pairs(inp) do
							if typeof(v) == "table" then convert(v)
							else inp[i] = Function.convertToJSON(v) end
						end
					end
					convert(t)
					t["BundleName"] = name
					local _safe = _bsanitize(name)
					local _wrOk = _atomicWriteJSON("RClothesLerp/Bundles/" .. _safe .. ".json", t)
					if not _wrOk then return false end
					-- un-blocklist if re-saving a previously-deleted name (orig L27880-27894)
					pcall(function()
						local _list = _readDeleted()
						if #_list == 0 then return end
						local _filtered, _removed = {}, false
						for _, _n in ipairs(_list) do
							if _n ~= name then table.insert(_filtered, _n) else _removed = true end
						end
						if _removed then _atomicWriteJSON("RClothesLerp/DeletedBundles.json", _filtered) end
					end)
					return _wrOk
				end

				-- register an imported bundle in-memory (orig _finalizeImport L27939-27980, minus
				-- the GUI button build -- the merged GUI re-renders tiles from Bundle on demand).
				local function _registerImport(name, input)
					Bundle[name] = input
				end

				-- submit an imported bundle to the community queue (orig _submitImportedBundleToCommunity
				-- L27901-27934).
				local function _submitImported(name, input)
					local reqFunc = _reqFn()
					if not reqFunc then return false end
					local lp = PS.LocalPlayer
					local payload = {
						name = name,
						bundle = dehydrate(input),
						scriptVersion = VersionInternal,
						manifestVersion = System.ManifestVersion or "unknown",
						submitter = { userId = lp and lp.UserId or 0, displayName = lp and lp.DisplayName or "Unknown" },
					}
					local okEnc, body = pcall(HS.JSONEncode, HS, payload)
					if not okEnc then return false end
					local ok, res = pcall(reqFunc, {
						Url = "https://krulhub.dev/roclothes/submit", Method = "POST",
						Headers = { ["Content-Type"] = "application/json" }, Body = body,
					})
					return ok and res and tonumber(res.StatusCode) and tonumber(res.StatusCode) >= 200 and tonumber(res.StatusCode) < 300 or false
				end

				-- Save Bundle modal "Save Private" (orig L28024-28040): write each pending bundle to
				-- disk + register it. Returns a status string. Clears the queue.
				System.finalizeImportPrivate = function()
					local pending = System._pendingImports or {}
					local n = 0
					local failed = {}
					for _, p in ipairs(pending) do
						_registerImport(p.name, p.input)
						if _writeImportedToDisk(p.name, p.input) then
							n = n + 1
						else
							table.insert(failed, p)
						end
					end
					if Function.compileOvertime then pcall(Function.compileOvertime) end
					System._pendingImports = failed
					if hotSwap then hotSwap() end
					if #failed > 0 then
						return "Saved " .. n .. " private; " .. #failed .. " memory-only: disk write FAILED. Retry Save Private."
					end
					return n > 0 and ("Saved " .. n .. " private!") or "Nothing to save"
				end

				-- Save Bundle modal "Submit Community" (orig L28041-28113): save locally first,
				-- then submit; append accepted names to MySubmissions.json. Returns a status string.
				System.finalizeImportCommunity = function()
					local pending = System._pendingImports or {}
					local remaining = {}
					local ok, fail, diskFail, indexFail = 0, 0, 0, 0
					for _, p in ipairs(pending) do
						_registerImport(p.name, p.input)
						local diskOK = _writeImportedToDisk(p.name, p.input)
						if not diskOK then diskFail = diskFail + 1 end
						local _submit = {}
						for k, vv in pairs(p.input) do _submit[k] = vv end
						_submit.Personal = false
						if p.communitySubmitted or _submitImported(p.name, _submit) then
							p.communitySubmitted = true
							ok = ok + 1
							-- append to MySubmissions.json (orig L28076-28099)
							local indexOK, indexSaved = pcall(function()
								if not (env and env.writefile) then return false end
								local _list = {}
								if env.isfile and env.readfile and env.isfile("RClothesLerp/MySubmissions.json") then
									local _okR, _raw = pcall(env.readfile, "RClothesLerp/MySubmissions.json")
									if _okR and type(_raw) == "string" and #_raw > 0 then
										local _okD, _dec = pcall(HS.JSONDecode, HS, _raw)
										if _okD and type(_dec) == "table" then _list = _dec end
									end
								end
								local _seen = false
								for _, _n in ipairs(_list) do if _n == p.name then _seen = true; break end end
								if not _seen then
									table.insert(_list, p.name)
									return _atomicWriteJSON("RClothesLerp/MySubmissions.json", _list)
								end
								return true
							end)
							p.communityIndexed = indexOK and indexSaved == true
							if not p.communityIndexed then indexFail = indexFail + 1 end
						else
							fail = fail + 1
						end
						if not diskOK or not p.communitySubmitted or not p.communityIndexed then table.insert(remaining, p) end
					end
					System._pendingImports = remaining
					if Function.compileOvertime then pcall(Function.compileOvertime) end
					if hotSwap then hotSwap() end
					if diskFail > 0 then
						return "Submitted " .. ok .. ", " .. fail .. " submission failed; " .. diskFail .. " memory-only: disk write FAILED. Retry Submit Community."
					end
					if indexFail > 0 then
						return "Submitted " .. ok .. ", " .. fail .. " submission failed; " .. indexFail .. " submission index write FAILED. Retry Submit Community."
					end
					if fail == 0 then return "Submitted " .. ok .. " for review!" end
					return "Submitted " .. ok .. ", " .. fail .. " failed (see console)"
				end

				-- Save Bundle modal "Cancel" (orig L28114-28122): discard everything.
				System.cancelImport = function()
					System._pendingImports = {}
					return "Import cancelled"
				end

				-- REDOWNLOAD -----------------------------------------------------------
				-- Re-fetch personal bundles from disk: delete the BundleLoader.json cache + each
				-- on-disk per-bundle file is the original's "redownload" of LOCAL bundles. Since
				-- local bundles ARE the on-disk JSONs, a faithful "redownload" here = drop the
				-- cache so the on-disk loader (orig L20162-20576) rebuilds from RClothesLerp/Bundles
				-- on the next execute, AND re-instate manifest bundles (Clear-style) so the user's
				-- community list refreshes from _RoClothesData.Bundle live. Returns a status string.
				-- NOTE: full asset/mesh redownload is the separate Options "Redownload All Content"
				-- (System.doRedownload, P4); this is the BUNDLE-list refresh only.
				System.redownloadBundles = function()
					-- drop the quick-load cache so disk is re-read next session (orig L20426 / L27709 style)
					pcall(function()
						if env.delfile and env.isfile and env.isfile("RClothesLerp/BundleLoader.json") then
							env.delfile("RClothesLerp/BundleLoader.json")
						end
					end)
					-- re-instate any manifest bundles missing from the live table (so a stale in-memory
					-- delete/edit doesn't hide community bundles after a refresh)
					local restored = 0
					if _RoClothesData and _RoClothesData.Bundle and type(Bundle) == "table" then
						local _subs = _mySubsSet()
						local _deletedSet = {}
						for _, n in ipairs(_readDeleted()) do _deletedSet[n] = true end
						for _bN, _bV in pairs(_RoClothesData.Bundle) do
							if Bundle[_bN] == nil and type(_bV) == "table" and not _deletedSet[_bN] then
								Bundle[_bN] = _bV
								if _bV.IsPreset ~= true and _bV.ClothingBundle ~= true then
									_bV.Personal = _subs[_bN] == true
								end
								restored = restored + 1
							end
						end
					end
					return "Bundle list refreshed (" .. restored .. " re-added). Restart to re-read disk."
				end

				-- ====================================================================
				-- PHASE 9: CATALOG BROWSER DATA BRIDGE (dynamic grid + filters +
				--          pagination + equip + strip-categories + equipped sidebar +
				--          Save Outfit). The By-ID 6 fields are already wired (P4b).
				-- --------------------------------------------------------------------
				-- Same model as P6/P7/P8: the file-scope GUI (_buildKrulHubGUI) cannot
				-- see PlayerData / SelectPlayer / Function.Catalog* / hotSwap / env / HS /
				-- Bundle / the P8 _writeImportedToDisk + _registerImport helpers, so the
				-- catalog data layer is exposed here as System.* methods (0 RoClothes
				-- registers; this block lives inside the P8 inner do...end so it reuses
				-- _writeImportedToDisk / _registerImport / _reqFn directly for saveOutfit).
				-- The GUI builds a grid/sidebar from these and registers Pages._renderCatalog
				-- / Pages._renderEquipped onto System.renderCatalog so a hotSwap re-paints.
				--
				-- Faithfulness map to the ORIGINAL (Ro-Clothes-Krul-V4.3.576.0627.lua):
				--   * category list (_CB_CATS)   -> orig L24423-24445 (cat/sub/ats verbatim)
				--   * page fetch (_CB_loadPage)   -> orig L25181-25256 wraps Function.CatalogFetchPage
				--                                    (orig L16265; sig (category,subcategory,assetTypes,
				--                                    keyword,cursor,limit,filters)); async detail fill
				--                                    via Function.CatalogFetchAssetDetails (orig L16360)
				--   * apply routing (_cb_applyTap)-> orig L24868-25102 -- assetType route via
				--                                    Function.CatalogIsAccessoryAssetType (orig L16409):
				--                                    Bundle=>CatalogOutfitId, 11=>Shirt, 12=>Pants,
				--                                    2=>ShirtGraphic, accessory=>CatalogAccessory[];
				--                                    same-item tap UNEQUIPS (orig L24889-24960); then hotSwap.
				--                                    GUI-list manipulation (GUIObject.Catalog_3 / the
				--                                    per-player removal buttons / OutfitIdTextbox) is GONE
				--                                    with the old GUI -- the merged GUI's Equipped sidebar
				--                                    rebuilds from PD instead, so only the PD mutations
				--                                    are reproduced here (rule: reproduce PD/file logic
				--                                    inline, not dead GUI-instance code).
				--   * equipped detection          -> _cb_isEquipped, orig L24543-24565
				--   * equipped sidebar data       -> _cb_renderEquippedPanel collect loop, orig L24659-24677
				--   * equipped remove per slot     -> orig L24798-24841 (OutfitId/Shirt/Pants/ShirtGraphic/Accessory)
				--   * strip categories (8 bool)    -> orig L25439-25458 toggle pd.StripCategories[cat]
				--                                    + Function.ApplyStripToLiveCharacter (orig L14181 here)
				--   * Save Outfit capture+commit   -> _buildOutfitPreset (orig L28557-28803, reproduced
				--                                    inline -- trapped in the deleted GUI, touches only PD +
				--                                    Function.* survivors) + _commitOutfitSave (orig L28876-28937;
				--                                    register + disk via the P8 _registerImport/_writeImportedToDisk)
				--                                    + _publishOutfitToWebsite (orig L28827; POST
				--                                    https://krulhub.dev/bundles/publish)
				--
				-- Endpoints / paths used VERBATIM from the engine:
				--   publish = https://krulhub.dev/bundles/publish
				--   thumbs  = rbxthumb://type=Asset|Outfit&id=<id>&w=150&h=150
				do
					-- CATEGORIES verbatim from orig _CB_CATS (L24423-24445): numeric IDs from
					-- /v1/categories + /v1/subcategories (verified live 2026-05-08).
					local _CB_CATS = {
						{label = "All",                 cat = 1,  sub = nil, ats = nil},
						-- V4.4.x: all accessory subcategories (Hats/Face/Neck/Shoulder/Front/Back/Waist)
						-- condensed into ONE chip. sub=nil + the full accessory AssetType list -> both the
						-- native (AssetTypes-driven) and worker (Category=11 + AssetTypes=...) paths return
						-- every accessory type in one browse.
						{label = "Accessories",         cat = 11, sub = nil, ats = {8, 42, 43, 44, 45, 46, 47}},
						{label = "Hair",                cat = 18, sub = 20, ats = {41}},
						{label = "Classic Faces",       cat = 18, sub = 10, ats = {18}},
						{label = "Classic Shirts",      cat = 3,  sub = 56, ats = {11}},
						{label = "Classic Pants",       cat = 3,  sub = 57, ats = {12}},
						{label = "Classic T-Shirts",    cat = 3,  sub = 55, ats = {2}},
					}
					-- Return a fresh copy each call so the GUI can hold it without aliasing the
					-- bridge's table. (label/cat/sub/ats per row; ats is itself copied.)
					System.getCatalogCats = function()
						local out = {}
						for i, c in ipairs(_CB_CATS) do
							local _ats
							if c.ats then _ats = {} for _, a in ipairs(c.ats) do table.insert(_ats, a) end end
							out[i] = {label = c.label, cat = c.cat, sub = c.sub, ats = _ats}
						end
						return out
					end

					-- Page fetch. Thin wrapper over Function.CatalogFetchPage (orig L16265) with
					-- the EXACT original signature/argument order (orig _CB_loadPage L25186-25191):
					--   CatalogFetchPage(category, subcategory, assetTypes, keyword, cursor, limit, filters)
					-- cat = {cat=,sub=,ats=} descriptor (a row from getCatalogCats); filters =
					-- {freeOnly=,minPrice=,maxPrice=,creator=}. The CALLER (GUI) owns the task.spawn +
					-- in-flight gate + cursor stack -- this is a synchronous (yielding) data call that
					-- never blocks the engine. Returns items[], nextCursor, errMsg (CatalogFetchPage's
					-- own contract; native path returns a per-page "NEXT<n>" sentinel cursor, while
					-- worker cursors are internally tagged so their opaque values cannot be mistaken
					-- for native sentinels. The bridge unwraps before building the HTTP request.
					System.catalogLoadPage = function(cat, keyword, cursor, filters)
						cat = cat or _CB_CATS[1]
						if not (Function and Function.CatalogFetchPage) then return nil, nil, "no CatalogFetchPage" end
						local ok, items, nxt, err = pcall(Function.CatalogFetchPage,
							cat.cat, cat.sub, cat.ats, keyword or "", cursor or "", 30, filters)
						if not ok then return nil, nil, tostring(items) end
						return items, nxt, err
					end

					-- Per-asset detail fetch (orig L16360). Returns {name, price, assetType} or nil.
					-- Used by the GUI to async-fill cells whose name/price/type the page response
					-- did not include. Yields; the caller spawns it.
					System.catalogItemDetails = function(id)
						if not (Function and Function.CatalogFetchAssetDetails) then return nil end
						local ok, d = pcall(Function.CatalogFetchAssetDetails, id)
						if not ok then return nil end
						return d
					end

					-- Equipped-state detection (orig _cb_isEquipped L24543-24565). True when the item
					-- is currently applied via one of pd's catalog fields. Routes by assetType through
					-- Function.CatalogIsAccessoryAssetType (orig L16409). pd defaults to the active player.
					local function _catIsEquipped(item, pd)
						pd = pd or PlayerData[(System.getSelectPlayer and System.getSelectPlayer()) or Player.Name]
						if not pd or not item or not item.id then return false end
						if item.itemType == "Bundle" then
							local bundleIdentity = (pd.CatalogBundleId and pd.CatalogBundleId ~= "") and pd.CatalogBundleId or pd.CatalogOutfitId
							return tostring(bundleIdentity or "") == tostring(item.id)
						end
						local atyp = item.assetType
						local idNum = tonumber(item.id)
						if not idNum then return false end
						if atyp == 11 then
							return tonumber(pd.CatalogClothes and pd.CatalogClothes.Shirt) == idNum
						elseif atyp == 12 then
							return tonumber(pd.CatalogClothes and pd.CatalogClothes.Pants) == idNum
						elseif atyp == 2 then
							return tonumber(pd.CatalogClothes and pd.CatalogClothes.ShirtGraphic) == idNum
						elseif atyp == 18 then
							return tonumber(pd.CatalogClothes and pd.CatalogClothes.Face) == idNum
						elseif Function.CatalogIsAccessoryAssetType and Function.CatalogIsAccessoryAssetType(atyp) then
							if not pd.CatalogAccessory then return false end
							for _, v in ipairs(pd.CatalogAccessory) do
								if tonumber(v) == idNum then return true end
							end
						end
						return false
					end
					System.catalogIsEquipped = function(item)
						return _catIsEquipped(item, nil)
					end

					-- recently-equipped history push (orig _cb_pushHistory L24853-24866): cap 20, dedup by id.
					local function _catPushHistory(pd, item)
						if not (pd and item and item.id) then return end
						pd.CatalogHistory = pd.CatalogHistory or {}
						for i = #pd.CatalogHistory, 1, -1 do
							if pd.CatalogHistory[i] and pd.CatalogHistory[i].id == item.id then
								table.remove(pd.CatalogHistory, i)
							end
						end
						table.insert(pd.CatalogHistory, 1, {
							id = item.id, name = item.name, assetType = item.assetType,
							itemType = item.itemType, priceInRobux = item.priceInRobux,
						})
						while #pd.CatalogHistory > 20 do table.remove(pd.CatalogHistory) end
					end

					-- Apply a tapped catalog item (orig _cb_applyTap L24868-25102). Routes through
					-- PlayerData[sp] + the hotSwap pipeline (NO parallel apply system). Same-item tap
					-- UNEQUIPS. The original also poked the now-deleted GUIObject.Catalog_3 list /
					-- OutfitIdTextbox / per-player removal buttons -- those are gone with the old GUI;
					-- the merged Equipped sidebar rebuilds from PD on the GUI's re-render, so only the
					-- PD mutations + hotSwap are reproduced here. Returns "equipped"/"unequipped"/false.
					System.catalogApplyItem = function(item)
						if type(item) ~= "table" then return false end
						local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
						local pd = PlayerData[sp]
						if not pd then return false end
						-- Pre-details guard (orig L24873-24880): sync-fetch assetType for a non-Bundle item.
						if item.itemType ~= "Bundle" and type(item.assetType) ~= "number" then
							local ok, d = pcall(Function.CatalogFetchAssetDetails, item.id)
							if ok and d then
								if d.name then item.name = d.name end
								if d.price then item.priceInRobux = d.price end
								if d.assetType then item.assetType = d.assetType end
							end
						end
						-- pre-warm the asset-type cache so the apply pipeline skips the MPS timeout (orig L24886-24888).
		if item.itemType ~= "Bundle" and type(item.assetType) == "number" and Function._catalogAssetTypeCache then
			Function._catalogTypeCachePut(item.id, item.assetType)
		end
						-- helper: keep "Roblox Shirt"/"Roblox Pants" toggles in CurrentClothes (orig _ensureCloth L25036).
						local function _ensureCloth(name)
							pd.CurrentClothes = pd.CurrentClothes or {}
							if not table.find(pd.CurrentClothes, name) then table.insert(pd.CurrentClothes, name) end
						end
						local function _removeFromCurrent(name)
							if pd.CurrentClothes then
								local _idx = table.find(pd.CurrentClothes, name)
								if _idx then table.remove(pd.CurrentClothes, _idx) end
							end
						end
						-- UNEQUIP path (orig L24889-24960): same-item tap clears its slot.
						if _catIsEquipped(item, pd) then
							if item.itemType == "Bundle" then
								pd.CatalogOutfitId = ""
								pd.CatalogBundleId = ""
								pd.CatalogRemove = {}
								_removeFromCurrent("Roblox Shirt")
								_removeFromCurrent("Roblox Pants")
							else
								local atyp = item.assetType
								if atyp == 11 then
									if pd.CatalogClothes then pd.CatalogClothes.Shirt = "" end
									_removeFromCurrent("Roblox Shirt")
								elseif atyp == 12 then
									if pd.CatalogClothes then pd.CatalogClothes.Pants = "" end
									_removeFromCurrent("Roblox Pants")
								elseif atyp == 2 then
									if pd.CatalogClothes then pd.CatalogClothes.ShirtGraphic = "" end
									_removeFromCurrent("Roblox Shirt")
								elseif atyp == 18 then
									if pd.CatalogClothes then pd.CatalogClothes.Face = "" end
								elseif Function.CatalogIsAccessoryAssetType and Function.CatalogIsAccessoryAssetType(atyp) then
									local idNum = tonumber(item.id)
									if pd.CatalogAccessory and idNum then
										for i, v in ipairs(pd.CatalogAccessory) do
											if tonumber(v) == idNum then table.remove(pd.CatalogAccessory, i); break end
										end
									end
								end
							end
							if hotSwap then hotSwap() end
							return "unequipped"
						end
						-- EQUIP path.
						if item.itemType == "Bundle" then
							local bundleId = tonumber(item.id)
							if not bundleId then return false end
							local okDetails, details = pcall(function()
								return game:GetService("AssetService"):GetBundleDetailsAsync(bundleId)
							end)
							if not okDetails or type(details) ~= "table" or type(details.Items) ~= "table" then
								warn("[RoClothes] catalog bundle details failed: " .. tostring(details))
								return false
							end
							local outfitId
							for _, bundleItem in ipairs(details.Items) do
								local itemType = bundleItem and bundleItem.Type
								local typeName = (typeof(itemType) == "EnumItem" and itemType.Name) or tostring(itemType or "")
								if typeName == "UserOutfit" or typeName:match("%.UserOutfit$") then
									outfitId = tonumber(bundleItem.Id)
									break
								end
							end
							if PlayerData[sp] ~= pd or ((System.getSelectPlayer and System.getSelectPlayer()) or Player.Name) ~= sp then return false end
							if not outfitId or outfitId <= 0 then
								warn("[RoClothes] catalog bundle contains no UserOutfit: " .. tostring(bundleId))
								return false
							end
							_ensureCloth("Roblox Shirt")
							_ensureCloth("Roblox Pants")
							pd.CatalogBundleId = tostring(bundleId)
							pd.CatalogOutfitId = tostring(outfitId)
							pd.CatalogRemove = {}
						else
							local atyp = item.assetType
							if atyp == 11 then
								pd.CatalogClothes = pd.CatalogClothes or {}
								pd.CatalogClothes.Shirt = tostring(item.id)
								_ensureCloth("Roblox Shirt")
							elseif atyp == 12 then
								pd.CatalogClothes = pd.CatalogClothes or {}
								pd.CatalogClothes.Pants = tostring(item.id)
								_ensureCloth("Roblox Pants")
							elseif atyp == 2 then
								pd.CatalogClothes = pd.CatalogClothes or {}
								pd.CatalogClothes.ShirtGraphic = tostring(item.id)
								_ensureCloth("Roblox Shirt")
							elseif atyp == 18 then
								local id = tonumber(item.id)
								if not id or id <= 0 or id >= 2^53 or id ~= math.floor(id) then return false end
								pd.CatalogClothes = pd.CatalogClothes or {}
								pd.CatalogClothes.Face = tostring(id)
							elseif Function.CatalogIsAccessoryAssetType and Function.CatalogIsAccessoryAssetType(atyp) then
								pd.CatalogAccessory = pd.CatalogAccessory or {}
								local idNum = tonumber(item.id)
								local dup = false
								for _, existing in ipairs(pd.CatalogAccessory) do
									if tonumber(existing) == idNum then dup = true; break end
								end
								if not dup and idNum then table.insert(pd.CatalogAccessory, idNum) end
							else
								warn("[RoClothes] catalog tap: unmapped assetType " .. tostring(atyp))
								return false
							end
						end
						_catPushHistory(pd, item)
						if hotSwap then hotSwap() end
						return "equipped"
					end

					-- Equipped-sidebar data (orig _cb_renderEquippedPanel collect loop L24659-24677).
					-- Returns an array of {id, kind, slot} for every equipped catalog item.
					--   kind: "Bundle"/"Shirt"/"Pants"/"TShirt"/"Accessory"
					--   slot: "OutfitId"/"Shirt"/"Pants"/"ShirtGraphic"/"Accessory"
					-- The GUI resolves names via catalogItemDetails (cache-first) and filters client-side.
					System.getCatalogEquipped = function()
						local pd = PlayerData[(System.getSelectPlayer and System.getSelectPlayer()) or Player.Name]
						local out = {}
						if not pd then return out end
						if pd.CatalogOutfitId and pd.CatalogOutfitId ~= "" then
							local bundleIdentity = (pd.CatalogBundleId and pd.CatalogBundleId ~= "") and pd.CatalogBundleId or pd.CatalogOutfitId
							local n = tonumber(bundleIdentity)
							if n then table.insert(out, {id = n, kind = "Bundle", slot = "OutfitId"}) end
						end
						if pd.CatalogClothes then
							local s = tonumber(pd.CatalogClothes.Shirt)
							if s and s > 0 then table.insert(out, {id = s, kind = "Shirt", slot = "Shirt"}) end
							local p = tonumber(pd.CatalogClothes.Pants)
							if p and p > 0 then table.insert(out, {id = p, kind = "Pants", slot = "Pants"}) end
							local t = tonumber(pd.CatalogClothes.ShirtGraphic)
							if t and t > 0 then table.insert(out, {id = t, kind = "TShirt", slot = "ShirtGraphic"}) end
							local f = tonumber(pd.CatalogClothes.Face)
							if f and f > 0 then table.insert(out, {id = f, kind = "Face", slot = "Face"}) end
						end
						if pd.CatalogAccessory then
							for _, v in ipairs(pd.CatalogAccessory) do
								local n = tonumber(v)
								if n then table.insert(out, {id = n, kind = "Accessory", slot = "Accessory"}) end
							end
						end
						return out
					end

					-- Remove one equipped catalog item by slot+id (orig X-button handler L24798-24841),
					-- then hotSwap. slot is one of OutfitId/Shirt/Pants/ShirtGraphic/Accessory.
					System.catalogRemoveEquipped = function(id, slot)
						local pd = PlayerData[(System.getSelectPlayer and System.getSelectPlayer()) or Player.Name]
						if not pd then return false end
						local idNum = tonumber(id)
						if slot == "OutfitId" then
							pd.CatalogOutfitId = ""
							pd.CatalogBundleId = ""
							pd.CatalogRemove = {}
						elseif slot == "Shirt" then
							if pd.CatalogClothes then pd.CatalogClothes.Shirt = "" end
						elseif slot == "Pants" then
							if pd.CatalogClothes then pd.CatalogClothes.Pants = "" end
						elseif slot == "ShirtGraphic" then
							if pd.CatalogClothes then pd.CatalogClothes.ShirtGraphic = "" end
						elseif slot == "Face" then
							if pd.CatalogClothes then pd.CatalogClothes.Face = "" end
						elseif slot == "Accessory" then
							if pd.CatalogAccessory and idNum then
								for i, v in ipairs(pd.CatalogAccessory) do
									if tonumber(v) == idNum then table.remove(pd.CatalogAccessory, i); break end
								end
							end
						end
						if hotSwap then hotSwap() end
						return true
					end

					-- STRIP DEFAULT AVATAR (the 8-category boolean map; this is the P7-deferred
					-- catalog strip, orig L25439-25458). Toggle pd.StripCategories[cat] then live-update
					-- via Function.ApplyStripToLiveCharacter (NOT CharacterReset -- orig L25448-25453).
					-- getCatalogStrip returns the current bool map so the GUI paints active buttons red.
					System.getCatalogStrip = function()
						local pd = PlayerData[(System.getSelectPlayer and System.getSelectPlayer()) or Player.Name]
						local out = {}
						if pd and pd.StripCategories then
							for _, cat in ipairs({"Hat","Hair","Face","Neck","Shoulder","Front","Back","Waist"}) do
								out[cat] = pd.StripCategories[cat] and true or false
							end
						end
						return out
					end
					System.catalogStripToggle = function(cat)
						local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
						local pd = PlayerData[sp]
						if not pd then return false end
						pd.StripCategories = pd.StripCategories or {}
						-- orig L25446: `not value or nil` -> set true, or clear back to nil when toggling off.
						pd.StripCategories[cat] = (not pd.StripCategories[cat]) or nil
						if Function.ApplyStripToLiveCharacter then pcall(Function.ApplyStripToLiveCharacter, sp) end
						return pd.StripCategories[cat] and true or false
					end

					-- SAVE OUTFIT --------------------------------------------------------
					-- Inline reproduction of the original _buildOutfitPreset (orig L28557-28803) --
					-- it was trapped in the deleted GUI and touches only PD + Function.* survivors,
					-- so the rules permit reproducing it inline. Captures the full preset payload
					-- (catalog fields, body types/scales, tone, HP, recolor, gizmo, physics, FPerson,
					-- mesh edits, etc.) so a saved/published outfit round-trips losslessly.
					local function _shallowClone(t) local _o = {}; for k, v in pairs(t) do _o[k] = v end; return _o end
					local function _depth2Clone(t) local _o = {}; for k, v in pairs(t) do _o[k] = (type(v) == "table") and _shallowClone(v) or v end; return _o end
					local function _dehydratePreset(t)
						if type(t) ~= "table" then return Function.convertToJSON(t) end
						local _o = {}
						for k, v in pairs(t) do
							if type(v) == "table" then _o[k] = _dehydratePreset(v)
							else _o[k] = Function.convertToJSON(v) end
						end
						return _o
					end
					local function _propsEqual(a, b)
						if type(a) ~= type(b) then return false end
						local _ta, _tb = typeof(a), typeof(b)
						if _ta ~= _tb then return false end
						if _ta == "Color3" or _ta == "Vector3" or _ta == "CFrame" or _ta == "UDim2" or _ta == "UDim" then
							return a == b
						end
						if type(a) == "table" then
							for k, v in pairs(a) do if not _propsEqual(v, b[k]) then return false end end
							for k in pairs(b) do if a[k] == nil then return false end end
							return true
						end
						return a == b
					end
					local function _buildOutfitPreset(pd, stripCats)
						if not pd then return {} end
						local preset = {
							CatalogClothes = {
								Shirt        = pd.CatalogClothes and pd.CatalogClothes.Shirt or "",
								Pants        = pd.CatalogClothes and pd.CatalogClothes.Pants or "",
								ShirtGraphic = pd.CatalogClothes and pd.CatalogClothes.ShirtGraphic or "",
								Face         = pd.CatalogClothes and pd.CatalogClothes.Face or "",
							},
							CatalogAccessory = {},
							CatalogTail      = {},
							CatalogOutfitId  = pd.CatalogOutfitId or "",
							BodyPartPhysics  = pd.BodyPartPhysics == true,
						}
						if pd.CatalogAccessory then for _, v in ipairs(pd.CatalogAccessory) do table.insert(preset.CatalogAccessory, v) end end
						if pd.CatalogTail      then for _, v in ipairs(pd.CatalogTail)      do table.insert(preset.CatalogTail,      v) end end
						preset.CatalogAssetTypes = {}
						if Function._catalogAssetTypeCache then
							local function _capture(id)
								if not id then return end
								local _key = tonumber(id) or id
								local _t = Function._catalogAssetTypeCache[_key]
								if _t then preset.CatalogAssetTypes[tostring(id)] = _t end
							end
							if pd.CatalogAccessory then for _, v in ipairs(pd.CatalogAccessory) do _capture(v) end end
							if pd.CatalogTail      then for _, v in ipairs(pd.CatalogTail)      do _capture(v) end end
						end
						if pd.BreastsType    and pd.BreastsType    ~= 1       then preset.BreastsType    = pd.BreastsType    end
						if pd.ClothesHP and next(pd.ClothesHP) then preset.ClothesHP = _depth2Clone(pd.ClothesHP) end
						if pd.ClothesRecolor and next(pd.ClothesRecolor) then preset.ClothesRecolor = _dehydratePreset(pd.ClothesRecolor) end
						if pd.AccessoryHP and next(pd.AccessoryHP) then preset.AccessoryHP = _depth2Clone(pd.AccessoryHP) end
						if pd.GizmoOffsets and next(pd.GizmoOffsets) then preset.GizmoOffsets = _dehydratePreset(pd.GizmoOffsets) end
						if pd.GizmoOffset and next(pd.GizmoOffset) then preset.GizmoOffset = _dehydratePreset(pd.GizmoOffset) end
						if pd.GizmoPresets and next(pd.GizmoPresets) then preset.GizmoPresets = _dehydratePreset(pd.GizmoPresets) end
						if pd.TorsoType      and pd.TorsoType      ~= 1       then preset.TorsoType      = pd.TorsoType      end
						if pd.ArmType        and pd.ArmType        ~= 1       then preset.ArmType        = pd.ArmType        end
						if pd.LegsType       and pd.LegsType       ~= 1       then preset.LegsType       = pd.LegsType       end
						if pd.ButtType       and pd.ButtType       ~= 1       then preset.ButtType       = pd.ButtType       end
						if pd.BreastsScale   and pd.BreastsScale   ~= 1       then preset.BreastsScale   = pd.BreastsScale   end
						if pd.ButtsScale     and pd.ButtsScale     ~= 1       then preset.ButtsScale     = pd.ButtsScale     end
						if pd.LegsScale      and pd.LegsScale      ~= 1       then preset.LegsScale      = pd.LegsScale      end
						if pd.TorsoScale     and pd.TorsoScale     ~= 1       then preset.TorsoScale     = pd.TorsoScale     end
						if pd.LeftArmScale   and pd.LeftArmScale   ~= 1       then preset.LeftArmScale   = pd.LeftArmScale   end
						if pd.RightArmScale  and pd.RightArmScale  ~= 1       then preset.RightArmScale  = pd.RightArmScale  end
						if pd.CockScale      and pd.CockScale      ~= 1       then preset.CockScale      = pd.CockScale      end
						if pd.Tone           and pd.Tone           ~= "Base"  then preset.Tone           = pd.Tone           end
						if pd.HardcoreHP                                       then preset.HardcoreHP    = true              end
						if pd.TopHP          and pd.TopHP          ~= ""      then preset.TopHP         = pd.TopHP          end
						if pd.BottomHP       and pd.BottomHP       ~= ""      then preset.BottomHP      = pd.BottomHP       end
						if pd.DamageSFX      and pd.DamageSFX      ~= ""      then preset.DamageSFX     = pd.DamageSFX      end
						if pd.Volume         and pd.Volume         ~= 1       then preset.Volume        = pd.Volume         end
						if pd.TearParticles  == false                          then preset.TearParticles = false             end
						if pd.HealParticles  == false                          then preset.HealParticles = false             end
						if pd.RealtimeBodyTransparency == false                then preset.RealtimeBodyTransparency = false  end
						if pd.Face           == false                          then preset.Face          = false             end
						if pd.PhysicsObeyGravity == false                      then preset.PhysicsObeyGravity = false        end
						if pd.AccessorySizeLock                                then preset.AccessorySizeLock = true          end
						if pd.MeshSizeLock                                     then preset.MeshSizeLock  = true              end
						if pd.MeshBasePartInvisible                            then preset.MeshBasePartInvisible = true      end
						if pd.BreastsStiffness and pd.BreastsStiffness ~= 10    then preset.BreastsStiffness = pd.BreastsStiffness end
						if pd.BreastsDamping   and pd.BreastsDamping   ~= 0.207 then preset.BreastsDamping   = pd.BreastsDamping   end
						if pd.ButtsStiffness   and pd.ButtsStiffness   ~= 10    then preset.ButtsStiffness   = pd.ButtsStiffness   end
						if pd.ButtsDamping     and pd.ButtsDamping     ~= 0.1   then preset.ButtsDamping     = pd.ButtsDamping     end
						if pd.CockStiffness    and pd.CockStiffness    ~= 8     then preset.CockStiffness    = pd.CockStiffness    end
						if pd.CockDamping      and pd.CockDamping      ~= 0.207 then preset.CockDamping      = pd.CockDamping      end
						if pd.SmartBoneEnabled                                  then preset.SmartBoneEnabled = true                end
						if stripCats then preset.StripCategories = stripCats end
						if pd.NippleColor                                       then preset.NippleColor   = pd.NippleColor  end
						if pd.SkinTone                                          then preset.SkinTone      = pd.SkinTone     end
						if pd.AutoStripOnRip == true                            then preset.AutoStripOnRip = true                  end
						if pd.StripOnRipMap                                     then preset.StripOnRipMap = pd.StripOnRipMap       end
						if pd.NippleColorFromBundle == true                     then preset.NippleColorFromBundle = true            end
						if pd.BundleBodyColor       == false                    then preset.BundleBodyColor       = false           end
						if pd.BreathingEnabled      == true                     then preset.BreathingEnabled      = true            end
						if pd.OvertoneEnabled       == true                     then preset.OvertoneEnabled       = true            end
						if pd.BreathingAmplitude    and pd.BreathingAmplitude   ~= 0.03  then preset.BreathingAmplitude = pd.BreathingAmplitude end
						if pd.OvertoneAmplitude     and pd.OvertoneAmplitude    ~= 0.015 then preset.OvertoneAmplitude  = pd.OvertoneAmplitude  end
						if pd.BodyTransparency      and pd.BodyTransparency     ~= 0     then preset.BodyTransparency   = pd.BodyTransparency   end
						if pd.FPerson               == true                     then preset.FPerson               = true            end
						if pd.FPsnap                == true                     then preset.FPsnap                = true            end
						if pd.HeadTracking          == true                     then preset.HeadTracking          = true            end
						if pd.HPClothes and type(pd.HPClothes) == "table"
							and ((pd.HPClothes.Shirt and pd.HPClothes.Shirt ~= "") or (pd.HPClothes.Pants and pd.HPClothes.Pants ~= "")) then
							preset.HPClothesTemplates = {
								Shirt = (type(pd.HPClothes.Shirt) == "string" or type(pd.HPClothes.Shirt) == "number") and pd.HPClothes.Shirt or "",
								Pants = (type(pd.HPClothes.Pants) == "string" or type(pd.HPClothes.Pants) == "number") and pd.HPClothes.Pants or "",
							}
						end
						if PositionPhysicsMultiply ~= nil and PositionPhysicsMultiply ~= 1 then preset.PositionPhysicsMultiply = PositionPhysicsMultiply end
						if RotationPhysicsMultiply ~= nil and RotationPhysicsMultiply ~= 4 then preset.RotationPhysicsMultiply = RotationPhysicsMultiply end
						-- V4.5.18: capture the self-apply module globals so a PERSONAL save round-trips them.
						-- _applySelfModuleGlobals (L28607-28618) RESTORES Method / includedAccessoryNames /
						-- excludeAccessoryNames from a bundle's Preset, but _buildOutfitPreset never CAPTURED
						-- them -- only PositionPhysicsMultiply/RotationPhysicsMultiply (the two above) of the
						-- five module globals were saved. So a saved outfit lost its accessory show/hide filters
						-- and attach Method on reload -> accessories came back wrong/missing ("incomplete /
						-- flawed avatar" community report). Community bundles already carry these; personal saves
						-- did not. Guards mirror the existing "capture only if non-default" pattern (Method
						-- default = 2, filters default = empty) so plain outfits stay clean.
						if Method ~= nil and Method ~= 2 then preset.Method = Method end
						if type(includedAccessoryNames) == "table" and #includedAccessoryNames > 0 then
							preset.includedAccessoryNames = {}
							for _, _an in ipairs(includedAccessoryNames) do table.insert(preset.includedAccessoryNames, _an) end
						end
						if type(excludeAccessoryNames) == "table" and #excludeAccessoryNames > 0 then
							preset.excludeAccessoryNames = {}
							for _, _an in ipairs(excludeAccessoryNames) do table.insert(preset.excludeAccessoryNames, _an) end
						end
						if pd.CatalogUsername       and pd.CatalogUsername      ~= "" then preset.CatalogUsername = pd.CatalogUsername end
						if pd.CatalogRemove and #pd.CatalogRemove > 0 then
							preset.CatalogRemove = {}
							for _, v in ipairs(pd.CatalogRemove) do table.insert(preset.CatalogRemove, v) end
						end
						if pd.CatalogHistory and #pd.CatalogHistory > 0 then preset.CatalogHistory = _shallowClone(pd.CatalogHistory) end
						if pd.LocalTransparency and next(pd.LocalTransparency) then preset.LocalTransparency = _shallowClone(pd.LocalTransparency) end
						if pd.PartList then
							local _defaultPL = Function.PartListDefault and Function.PartListDefault() or {}
							preset.MeshEdit = {}
							local _hasEdit = false
							for partName, partEntry in pairs(pd.PartList) do
								if type(partEntry) == "table" then
									local _d = _defaultPL[partName]
									local _diff = false
									if type(_d) ~= "table" then
										_diff = true
									else
										for k, v in pairs(partEntry) do
											if not _propsEqual(v, _d[k]) then _diff = true; break end
										end
									end
									if _diff then preset.MeshEdit[partName] = _depth2Clone(partEntry); _hasEdit = true end
								end
							end
							if not _hasEdit then preset.MeshEdit = nil end
						end
						-- V4.4.2: capture tailSettings (custom tail physics) so it round-trips -- it was NEITHER
						-- captured NOR restored before. Exclude the runtime isTailCurrentlyEnabled.
						if type(pd.tailSettings) == "table" then
							preset.tailSettings = {}
							for _tk, _tv in pairs(pd.tailSettings) do if _tk ~= "isTailCurrentlyEnabled" then preset.tailSettings[_tk] = _tv end end
						end
						return preset
					end

					-- Gather up to 8 catalog asset IDs for the website preview thumbnails (orig
					-- _collectThumbnailIds L28808-28824). Order: shirt, pants, graphic, accessories, tail.
					local function _collectThumbnailIds(pd)
						local out, seen = {}, {}
						local function _push(id)
							if #out >= 8 then return end
							local s = tostring(id or ""):match("^%d+$")
							if not s or seen[s] then return end
							seen[s] = true; table.insert(out, s)
						end
						if pd.CatalogClothes then
							_push(pd.CatalogClothes.Shirt); _push(pd.CatalogClothes.Pants); _push(pd.CatalogClothes.ShirtGraphic); _push(pd.CatalogClothes.Face)
						end
						if pd.CatalogAccessory then for _, v in ipairs(pd.CatalogAccessory) do _push(v) end end
						if pd.CatalogTail      then for _, v in ipairs(pd.CatalogTail)      do _push(v) end end
						return out
					end

					-- POST the preset to the website (orig _publishOutfitToWebsite L28827-28868).
					-- Endpoint VERBATIM: https://krulhub.dev/bundles/publish. Returns ok, code, detail.
					local function _publishOutfit(name, preset, thumbnailIds, author)
						local body = {
							name          = name,
							author        = author,
							scriptVersion = VersionInternal,
							preset        = dehydrate(preset),
							thumbnailIds  = thumbnailIds or {},
						}
						local okEnc, encoded = pcall(HS.JSONEncode, HS, body)
						if not okEnc then return false, 0, "encode failed" end
						if #encoded > 60 * 1024 then
							return false, 413, "preset too large (" .. tostring(math.floor(#encoded / 1024)) .. " KB > 60 KB)"
						end
						local req = _reqFn()
						if not req then return false, 0, "no http_request API on this executor" end
						local okReq, res = pcall(req, {
							Url = "https://krulhub.dev/bundles/publish", Method = "POST",
							Headers = {["Content-Type"] = "application/json"}, Body = encoded,
						})
						if not okReq then return false, 0, tostring(res) end
						local code = tonumber(res and res.StatusCode) or 0
						local detail, bundleId = "", nil
						if res and res.Body then
							local okJson, parsed = pcall(HS.JSONDecode, HS, tostring(res.Body))
							if okJson and type(parsed) == "table" then
								if parsed.bundleId then bundleId = tostring(parsed.bundleId) end
								if parsed.error then detail = tostring(parsed.error) end
								if parsed.detail then detail = detail .. " " .. tostring(parsed.detail):sub(1, 60) end
							end
						end
						if code >= 200 and code < 300 then return true, code, "Submitted - pending moderation. id=" .. (bundleId or "?") end
						if code == 0 then return false, 0, "network error" end
						return false, code, detail ~= "" and detail or ("HTTP " .. tostring(code))
					end

					-- Build the bundleData {Preset, Personal, Clothing} from live PD (orig _commitOutfitSave
					-- body L28889-28922): preset + Personal=true + Clothing array (CurrentClothes minus the
					-- "nil" sentinel). Shared by both save paths.
					local function _buildOutfitBundle(pd)
						local preset = _buildOutfitPreset(pd, pd.StripCategories)
						local bundleData = {Preset = preset, Personal = true}
						-- V4.4.2 FIX: MeshEdit is captured nested under preset.MeshEdit, but BOTH apply paths read
						-- mesh edits only from TOP-LEVEL bundleData.MeshEdit -> per-part Size/CFrame/TextureId/Color
						-- overrides were LOST on reload. Lift it (community bundles already carry it top-level).
						if preset.MeshEdit then bundleData.MeshEdit = preset.MeshEdit end
						if pd.CurrentClothes and #pd.CurrentClothes > 0 then
							bundleData.Clothing = {}
							for _, _cname in ipairs(pd.CurrentClothes) do
								if type(_cname) == "string" and _cname ~= "nil" then
									table.insert(bundleData.Clothing, _cname)
								end
							end
						end
						return bundleData
					end

					-- Save Outfit (orig _commitOutfitSave L28876-28937 + the Private/Public button
					-- handlers L28941-29013). Captures the live PD into a bundle, registers it + writes
					-- it to disk (reusing the P8 _registerImport / _writeImportedToDisk), and -- when
					-- public==true -- also publishes it to the website. Name is sanitized for collision
					-- (suffix _2,_3,... like the original). Returns finalName, statusMsg.
					-- This is a YIELDING call (publish does HTTP); the GUI runs it in task.spawn.
					System.saveOutfit = function(name, public)
						local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
						local pd = PlayerData[sp]
						if not pd then return nil, "no pending outfit" end
						name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
						if name == "" then return nil, "name required" end
						if #name > 64 then name = name:sub(1, 64) end
						-- collision-safe name (orig L28883-28888)
						local finalName, suffix = name, 1
						while Bundle[finalName] do
							suffix = suffix + 1
							finalName = name .. "_" .. tostring(suffix)
							if suffix > 99 then return nil, "too many same-name bundles" end
						end
						local bundleData = _buildOutfitBundle(pd)
						_registerImport(finalName, bundleData)
						local _diskOk = _writeImportedToDisk(finalName, bundleData)
						if Function.compileOvertime then pcall(Function.compileOvertime) end
						if hotSwap then hotSwap() end
						if _diskOk == false then
							return finalName, "Saved (memory) but disk write FAILED for '" .. finalName .. "'"
						end
						if not public then
							return finalName, "Saved private as '" .. finalName .. "'"
						end
						-- publish path (orig L28983-29006)
						local preset = bundleData.Preset
						local thumbs = _collectThumbnailIds(pd)
						local lp = PS.LocalPlayer
						local _author = ((lp and lp.Name) or "Unknown"):sub(1, 48)
						local ok, code, detail = _publishOutfit(finalName, preset, thumbs, _author)
						if ok then return finalName, "Published! " .. tostring(detail or "") end
						if code == 426 then return finalName, "Saved private; publish blocked: script outdated." end
						if code == 429 then return finalName, "Saved private; rate-limited (5/hour). Try later." end
						if code == 413 then return finalName, "Saved private; " .. tostring(detail) end
						if code == 409 then return finalName, "Saved private; duplicate of a recent submission." end
						if code == 503 then return finalName, "Saved private; moderation queue full." end
						return finalName, "Saved private; publish failed: " .. tostring(detail or code)
					end
				end
			end
		end



	function Function.RunInitialization()
		-- V4.3.254: prefix sweep `rc_*` (matches BREAKER pattern). Catches orphan tags
		-- from prior crashed sessions whose RCTag hash no live RCTag references.
		do
			local _CS = game:GetService("CollectionService")
			local _allTags = _CS.GetAllTags and _CS:GetAllTags() or nil
			if _allTags then
				for _, _tag in ipairs(_allTags) do
					if type(_tag) == "string" and _tag:sub(1, 3) == "rc_" then
						for _, v in ipairs(_CS:GetTagged(_tag)) do
							pcall(function() v:Destroy() end)
						end
					end
				end
			else
				for _, v in ipairs(_CS:GetTagged(System.RCTag)) do
					pcall(function() v:Destroy() end)
				end
			end
		end

		-- V4.3.492: SUPPRESSED the GUI build's loading splash + "loading" TextLabel.
		-- The global `_RC_Brand` overlay owns the loading UX for the entire boot
		-- pipeline, so this site no longer needs to show its own UI. We still
		-- need the IsLoaded wait so GUI elements that consume the load image
		-- don't render uninitialized - but we do it INVISIBLY (no Enabled flip,
		-- no TextLabel pop-in). Pre-fix the user saw the "loading" text pop up
		-- briefly here, ruining the aesthetic.
		local loadui = _sharedLoadui or Instance.new("ScreenGui", game:GetService("CoreGui"))
		_sharedLoadui = nil
		loadui.Enabled = false  -- stay invisible; brand owns the loading UX
		local load = loadui:FindFirstChildOfClass("ImageLabel")
		if not load then
			load = Instance.new("ImageLabel", loadui)
			local okLoad, loadAsset = pcall(System.getcustomasset, "RClothesContent/loadv9.png")
			load.Image = okLoad and loadAsset or ""
			load.Size = UDim2.new(1,0,1,0)
			load.Transparency = 1
			load.ImageTransparency = .999
		end
		local okLoad = load.Image ~= ""
		local debounce_load = 0
		repeat
			task.wait(.1)
			debounce_load += 1
		until debounce_load >= 10 or load.IsLoaded == true or not okLoad
		
		if okLoad and load.IsLoaded == false then  -- V4.3.570 UX: only warn when the load image WAS found but did not finish; skip the misleading warn when the file is simply absent (okLoad=false)
			warn("[RoClothes] Assets are not fully loaded yet. GUI may appear incomplete until files are found.")
		end

		-- V4.3.258: VNS preload re-enabled. The original V4.3.217 disable was because (see Changelog for full rationale)
		System._sbPreloadHandle = task.spawn(function()
			pcall(Function.LoadSmartBoneApi)
			System._sbPreloadHandle = nil
		end)

		do
			if loadupFPerson > 0 then
				PlayerData[Player.Name].FPerson = true
				if loadupFPerson == 3 or loadupFPerson == 4 then
					PlayerData[Player.Name].FPsnap = true
				end
				if loadupFPerson == 5 or loadupFPerson == 6 then
					PlayerData[Player.Name].HeadTracking = true  -- BUGFIX: modes 5/6 are the head-tracking tier; `false` is the default (ResetBundleSettableFields), so the tier was a no-op. Enable it.
				end
				if loadupFPerson == 1 or loadupFPerson == 3 or loadupFPerson == 5 then
					PlayerData[Player.Name].LocalTransparency = {
						["Head"] = false,
						["Right Arm"] = true,
						["Left Arm"] = true,
						["Torso"] = true,
						["Right Leg"] = true,
						["Left Leg"] = true,
						["Hat"] = true
					}
				end
			end
			if loadupClosed == false then
				GUIObject.Screen.Enabled = true
			end
			if loadupExecute == true and Player.Character then
				local InitialID = PlayerData[Player.Name].LastRequestID
				Function.CharacterExecute(Player.Character, Player.Name, nil, InitialID)
				-- V4.3.168: announce loaded bundle to in-server peers (no-op if Avatar Sync is OFF).
				-- V4.3.174: passes `true` because Loadup Bundle is a user-configured action
				-- (the user explicitly set Loadup Bundle = X in settings to auto-apply on script
				-- load); broadcasting it to peers is the intended behavior.
				Function.AvatarSyncPublish(true)
			end
			loadui:Destroy()

			-- V4.3.189: KrulHosted clothing - ensure cache folder, then async-download
			-- any PNG files listed in the krulhub.dev manifest and register them in Clothes.
			local CLOTHING_DIR = "RClothesContent/KrulClothing"
			if env.isfolder and env.makefolder and not env.isfolder(CLOTHING_DIR) then
				pcall(env.makefolder, CLOTHING_DIR)
			end

			-- V4.3.441: cooperative-stop flag so BREAKER's cancel signal aborts the
			-- per-filename HTTP loop. task.cancel can't preempt a yielded HttpGet;
			-- pre-fix the loop kept writing into the global Clothes table after
			-- BREAKER fired, polluting the next exec's dedup set.
			System._krulManifestStop = true  -- V4.3.567 H-8: signal any still-yielded PRIOR manifest task to stop BEFORE cancelling it (task.cancel cannot preempt a yielded HttpGet)
			-- V4.3.521 Fix 14: getgenv handoff for re-execute cancellation (mirrors V4.3.514 pattern).
			do
				local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
				local _prior = _ok_genv and _genv and _genv._RC_krul_manifest_task or nil
				if _prior then pcall(task.cancel, _prior) end
			end
			System._krulManifestTask = task.spawn(function()
				System._krulManifestStop = false  -- V4.3.567 H-8: clear for THIS task, now that the prior one was signalled + cancelled
				local CLOTHING_BASE = "https://krulhub.dev/roclothes/clothing/"
				-- V4.3.349: simple 3-attempt exponential-backoff retry on transient HTTP
				-- failure. Pre-fix one blip aborted the whole manifest fetch silently
				-- (no warn) → user re-execute required. Retries: 0 / 1.5s / 4.5s.
				local ok, body = false, nil
				for attempt = 1, 3 do
					ok, body = pcall(game.HttpGet, game, CLOTHING_BASE .. "manifest.json")
					if ok and type(body) == "string" and #body > 0 then break end
					task.wait(1.5 * attempt)
				end
				if not ok or type(body) ~= "string" then return end
				local okD, manifest = pcall(game:GetService("HttpService").JSONDecode,
					game:GetService("HttpService"), body)
				if not okD or type(manifest) ~= "table" then return end

				for _, filename in ipairs(manifest) do
					if System._krulManifestStop then return end  -- V4.3.441: BREAKER signalled
					if type(filename) ~= "string" then continue end -- malformed manifest entry
					-- V4.3.520 Fix 9: segment-by-segment path-traversal guard for CDN manifest
					-- entries (mirrors V4.3.502 install-path guard). Pre-fix only checked type;
					-- a CDN compromise could ship filenames with .. or absolute paths and write
					-- outside CLOTHING_DIR.
					-- V4.3.521 Fix 3: V4.3.520 Fix 9 missed backslash + UNC. Reject any path with
					-- backslash (Windows separator that bypasses the / segmenter), leading // (UNC),
					-- or trailing whitespace/dot (NTFS namespace tricks).
					if filename:find("\\") or filename:sub(1,2) == "//"
					   or filename:match("[ %.]$") or filename:find("\0") then
						_diagPublicCall("manifest.bad_path", { f = filename, reason = "fs_traversal" })
						continue
					end
					local _badSeg = false
					for _seg in filename:gmatch("[^/]+") do
						if _seg == ".." or _seg == "." or _seg:find("[\\:]") or _seg:sub(2,2) == ":" then
							_badSeg = true; break
						end
					end
					if _badSeg or filename:sub(1,1) == "/" or filename:sub(1,1) == "\\" then
						_diagPublicCall("manifest.bad_path", { f = filename })
						continue
					end
					local localPath = CLOTHING_DIR .. "/" .. filename
					if env.isfile and not env.isfile(localPath) then
						local okH, data = pcall(game.HttpGet, game, CLOTHING_BASE .. filename)
						if okH and type(data) == "string" and #data > 100 and data:sub(1,4) == "\x89PNG" then
							if env.writefile then pcall(env.writefile, localPath, data) end
						end
					end
					local clothName = filename:match("^(.-)%.png$") or filename
					-- Only register if the file is confirmed on disk (or at least downloadable)
					local _fileReady = env.isfile and env.isfile(localPath)
					if Clothes and not Clothes[clothName] and _fileReady then
						local isShirt = clothName:lower():find("shirt") ~= nil
						local isPants = clothName:lower():find("pant") ~= nil
						if isShirt or isPants then
							Clothes[clothName] = setmetatable({
								ClothType = isShirt and "Shirt" or "Pants",
								LocalPath = localPath,
								KrulHosted = true,
							}, MetaClothes)
							if GUIObject and GUIObject.ClothesButtonFrame then
								local btn = Function.ButtonCreate(clothName, GUIObject.ClothesButtonFrame)
								if btn and btn:FindFirstChildOfClass("TextButton") then
									btn:SetAttribute("KrulHosted", true)
									local conn = btn:FindFirstChildOfClass("TextButton").MouseButton1Click:Connect(function()
										if not PlayerData[SelectPlayer] then return end
										if table.find(PlayerData[SelectPlayer].CurrentClothes, clothName) then
											-- Already on - remove directly
											local idx = table.find(PlayerData[SelectPlayer].CurrentClothes, clothName)
											if idx then table.remove(PlayerData[SelectPlayer].CurrentClothes, idx) end
											if System.hotSwap then System.hotSwap() end
										else
											-- Always ask shirt or pants (even if previously chosen - lets user change type)
											if _pendingKrulCloth then return end
											_pendingKrulCloth = clothName
											_pendingKrulPlayer = SelectPlayer
											if GUIObject.KrulTypePopup then
												GUIObject.KrulTypePopupLabel.Text = clothName
												GUIObject.KrulTypePopup.Visible = true
											end
										end
									end)
									System.GlobalMaid:Give(conn)
									table.insert(System.ClothesButtons, btn)
								end
							end
						else
							warn("[RoClothes] KrulHosted: filename '" .. filename .. "' does not contain 'shirt' or 'pant' - skipped")
						end
					end
				end

				-- Sort once after all buttons inserted (not per-item)
				table.sort(System.ClothesButtons, function(a,b) return a.Name < b.Name end)
				for i, v in ipairs(System.ClothesButtons) do v.LayoutOrder = i end
			end)
			-- V4.3.521 Fix 14: stash krul-manifest handle on getgenv() for cross-exec cancellation.
			do
				local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
				if _ok_genv and _genv then _genv._RC_krul_manifest_task = System._krulManifestTask end
			end
		end
	end

	-- V4.3.262 fix part 3/3: bail out before mounting the GUI if a newer execute
	-- has taken over the singleton slot. Without this, rapid double-execute → 2 GUIs.
	-- BREAKER folder is destroyed by the newer session's kill loop, but its
	-- .Destroying handler may not have fired yet (deferred signal) - this check is
	-- the synchronous guard that ensures only one GUI ever mounts.
	if not _isActiveSession() then
		pcall(function() if BREAKER then BREAKER:Destroy() end end)
		return
	end

	Function.RunInitialization()


	-- Monitor for external shutdown signal (via Singleton pattern or manual deletion)
	-- Cleanup loop removed: Now handled by BREAKER.Destroying signal
end -- close inner block
end -- close RoClothes

if RS:IsStudio() then
	RoClothes(PS.LocalPlayer)
else
	if RS:IsClient() then
		if not PS.LocalPlayer then
			PS.PlayerAdded:Wait()
		end
		RoClothes(PS.LocalPlayer)
	elseif RS:IsServer() then
		-- Server-side execution is not supported; RoClothes is client-only
		-- PS:WaitForChild("lerp()") was a stale placeholder that hangs forever
	end
end
return nil
